COPLAS_PIEZA(7, [["frenk_t4-n9737",8,"Voy a poner una casa\nmás allá de los infiernos,\npara las suegras malvadas\nque no quieren a sus yernos.",166,2,-1,182,"Las suegras",0,4,"eo",634,0,-1,0,219,219,"9737","",0,"","","",1,0,0,[],""],["frenk_t4-n9738",8,"Cabezas de calabazas,\ncuerpecitos de escorpión,\npara maltratar al yerno\nno tienen comparación.",166,2,-1,182,"Las suegras",0,4,"o",31,0,-1,0,219,219,"9738","",0,"","","",1,0,0,[],""],["frenk_t4-n9739",8,"Tu suegra me gusta tanto,\nque le voy a regalar\nun rosario de diamantes\npa que se ponga a rezar.",166,2,-1,182,"El rosario de mi suegra",0,4,"a",21,0,-1,0,219,219,"9739","",0,"","","",1,0,0,[],""],["frenk_t4-n9740",8,"Juana, Juana, Juana,\npréndete la vela,\nmira a ver quién anda\npor la carretera:\n¿no será la vaca?,\n¿no será mi suegra?",166,2,-1,182,"La cuera",9,6,"ea",-1,0,-1,0,219,219,"9740","",0,"","","",2,0,0,[],""],["frenk_t4-n9741",8,"Si a tu suegra caes mal,\nno dejes que te acapare:\naflójale un pasa-mare,\ny después un juela-real.",185,2,13,182,"Estrofa suelta",11,4,"a",1,0,-1,0,219,219,"9741","",0,"","","",1,0,0,[],""],["frenk_t4-n9742",8,"Si queres que tu suegra\nse ponga vieja,\nráscale la barriga\ncon una teja.",166,2,-1,182,"La bamba",6,4,"ea",165,0,-1,0,219,219,"9742","",0,"","","",1,0,0,[],""],["frenk_t4-n9743",8,"Si tienes sueño o esplín,\nun beso de mujer te alegra,\npero si el beso es de suegra,\n¡prefiere el Paricutín!",185,2,13,182,"Estrofa suelta",11,4,"i",211,0,-1,0,220,220,"9743","",0,"","","",1,0,0,[],""],["frenk_t4-n9744",8,"Si tu suegra es muy tunante\ny te hace amarga la vida,\nendúlzale el chocolate\ncon polvo de raticida.",168,2,11,182,"La Sanmarqueña; Estrofa suelta",0,4,"ia",37,0,-1,0,220,220,"9744","",0,"","","",1,0,0,[],""],["frenk_t4-n9745",8,"¡Gran barata, quemazón,\nventa de todas las suegras:\nuna peseta las negras,\ny las güeras un tostón!",166,2,-1,182,"Estrofa suelta",11,4,"o",31,0,-1,0,220,220,"9745","",0,"","","",1,0,0,[],""],["frenk_t4-n9746",8,"—¿Qué es aquello que relumbra\nen la punta de aquel cerro?\n—Es la suegra del calero,\nque le están quitando el cuero.",178,2,10,182,"El calero",0,4,"eo",38,0,-1,0,220,220,"9746","",0,"","","",8,0,0,[],""],["frenk_t4-n9747",8,"Yo quisiera que las suegras\nse volvieran lagartijas,\npa matarlas a pedradas\ny quedarme con sus hijas.",169,2,8,182,"La Sanmarqueña; El chinaco; Estrofa suelta",0,4,"ia",635,0,-1,0,220,220,"9747","",0,"","","",1,0,0,[],""],["frenk_t4-n9748a",8,"La suegra que yo me encuentre\nla voy a hacer mi violín;\nsus tripas serán las cuerdas,\nsu pescuezo el diapasón,\nsus dientes serán clavijas\ny su hija mi inspiración.",175,2,6,182,"Estrofa suelta",9,6,"o",31,0,-1,0,220,220,"9748a","",0,"","","",1,0,0,[],""],["frenk_t4-n9750",8,"¡Ay, qué suegras tan ingratas,\nque le hacen a uno desaires!\n¡Ay, qué paredes tan altas!,\n¡cómo no las tumba el aire!",166,2,-1,182,"El indio",0,4,"ae",-1,0,-1,0,221,221,"9750","",0,"","","",1,0,0,[],""],["frenk_t4-n9751",8,"A nuestras suegras les gustan\nlas linternas amarillas;\nsi nos ven con otras viejas,\npues nos rompen las costillas.",166,2,-1,182,"Linternas y lintemitas",0,4,"ia",294,0,-1,0,221,221,"9751","",0,"","","",1,0,0,[],""],["frenk_t4-n9753",8,"Mejor que les dieran yerba\n—para acabar con la raza—,\nde estos caballos de pita;\n¡suegritas de mala traza!",166,2,-1,182,"Las suegras",0,4,"aa",307,0,-1,0,221,221,"9753","",0,"","","",1,0,0,[],""],["frenk_t4-n9754",8,"—Viene mi suegra,\nahora chulapearemos.\n—Deja que venga,\naquí la capotearemos.",191,2,1,182,"El torito",3,4,"eo",127,0,-1,0,221,221,"9754","",0,"","","",1,0,0,[],""],["frenk_t4-n9755",8,"¡Ay, Señor San Sebastián!,\nperdona mi atrevimiento:\nmi suegra me había cansado,\ny le pegué en un momento.",170,2,7,182,"Las suegras",0,4,"eo",94,0,-1,0,221,221,"9755","",0,"","","",2,0,0,[],""],["frenk_t4-n9756",8,"¡Ah, qué suegra tan maldita!,\nno me podía ni ver;\nvieja, cabeza de pita,\n¡qué paliza le di ayer!",170,2,7,182,"Las suegras",1,4,"e",20,0,-1,0,221,221,"9756","",0,"","","",1,0,0,[],""],["frenk_t4-n9757",8,"Mi suegra me dio un gallito\npa que lo enseñe a cantar;\nyo le di mi periquito,\npa que lo enseñara a hablar.",166,2,-1,182,"El rosario de mi suegra",1,4,"a",21,0,-1,0,221,221,"9757","",0,"","","",1,0,0,[],""],["frenk_t4-n9758",8,"Mi suegra, que tiene ochenta,\ntodavía piensa en la boda;\nme dice que va a la moda\ny se peina a la francesa..",166,2,-1,182,"El rosario de mi suegra’T",5,4,"ea",-1,0,-1,0,221,221,"9758","",0,"","","",1,0,0,[],""],["frenk_t4-n9759",8,"¡Si vieran cuando se pone\nel sombrero pa lucirse!\nParece una guacamaya\nforrada con el chemisse.",166,2,-1,182,"El rosario de mi suegra",0,4,"ie",-1,0,-1,0,221,221,"9759","",0,"","","",1,0,0,[],""],["frenk_t4-n9760",8,"Un gallo es un buen cantante,\nel perico un hablador:\ndice que de noche ronca\nmi suegra con un señor.",166,2,-1,182,"El rosario de mi suegra",0,4,"o",72,0,-1,0,222,222,"9760","",0,"","","",1,0,0,[],""],["frenk_t4-n9761",8,"En las márgenes del río\nvide un torito bramar;\nmi suegra apesta a zorrillo,\npor no quererse bañar.",166,2,-1,182,"El torito",0,4,"a",21,0,-1,0,222,222,"9761","",0,"","","",1,0,0,[],""],["frenk_t4-n9762",8,"En los cerros nacen tunas,\nen los bajos chilicayotes,\nen la siembra de mi suegra\nnacieron los zopilotes.",166,2,-1,182,"Al pasar por tu ventana",0,4,"oe",565,0,-1,0,222,222,"9762","",0,"","","",1,0,0,[],""],["frenk_t4-n9763",8,"De Acapulco sacaron\nuna ballena podrida,\ny de la boca sacaron\na mi suegra empedernida.",166,2,-1,182,"La Sanmarqueña",1,4,"ia",37,0,-1,0,222,222,"9763","",0,"","","",1,0,0,[],""],["frenk_t4-n9764",8,"Estando en la mar remando,\nse cayó al agua mi suegra;\npor eso los tiburones\ntienen la sangre tan negra.",166,2,-1,182,"La Sanmarqueña",0,4,"ea",382,0,-1,0,222,222,"9764","",0,"","","",1,0,0,[],""],["frenk_t4-n9765",8,"Hay dos clases de bombas:\nla rusa y la americana,\npero es peor la de mi suegra\nestando de madrugada.",185,2,13,182,"Estrofa suelta",0,4,"aa",-1,0,-1,0,222,222,"9765","",0,"","","",1,0,0,[],""],["frenk_t4-n9766",8,"Mi suegra es una viejita,\npero carga mucha facha;\nvieja, cabeza de pita,\n¡boquita de cucaracha!",166,2,-1,182,"Las suegras",1,4,"aa",556,0,-1,0,222,222,"9766","",0,"","","",1,0,0,[],""],["frenk_t4-n9767",8,"¡Ah, qué horrorosa es mi suegra!\ntiene su cara de rata,\ny con su cuerpo redondo,\nque parece garrapata.",166,2,-1,182,"Las suegras",0,4,"aa",74,0,-1,0,222,222,"9767","",0,"","","",1,0,0,[],""],["frenk_t4-n9769",8,"Mi suegra a mí no me quiere,\ndice que soy pica-pica;\npues sin cuidado me tiene:\nlo que me importa es la chica;\nde ver tanto que me quiere,\nhasta mi suegra se pica.",167,2,2,182,"El pica-pica",9,6,"ia",174,0,-1,0,222,222,"9769","",0,"","","",1,0,0,[],""],["frenk_t4-n9770",8,"Mi suegra no me mastica,\naunque soy hombre decente,\nvámonos a la perica:\nsi la encuentro de repente,\nle voy a echar pica-pica,\npara que se ría la gente.",167,2,2,182,"El pica-pica",9,6,"ee",15,0,-1,0,223,223,"9770","",0,"","","",1,0,0,[],""],["frenk_t4-n9771",8,"Aburrido de aguantar,\nde sufrir y padecer,\nmi suegra voy a vender:\n¿quién me la quiere comprar?",166,2,-1,182,"Estrofa suelta",11,4,"a",21,0,-1,0,223,223,"9771","",0,"","","",1,0,0,[],""],["frenk_t4-n9772",8,"Yo disputo de mi suegra,\nporque así se lo merece;\nseñores, ya está tan vieja,\nque de un hervor no se cuece.",166,2,-1,182,"Las suegras",0,4,"ee",64,0,-1,0,223,223,"9772","",0,"","","",1,0,0,[],""],["frenk_t4-n9773",8,"La vieja de mi suegra\nme dio unos cuadros,\ncada vez que reñimos\nlos descolgamos.\nDe esta manera\ntoda la noche andamos\ncon la escalera.",173,2,17,182,"Estrofa suelta",4,7,"ea",44,0,-1,0,223,223,"9773","",0,"","","",7,0,0,[],""],["frenk_t4-n9774",8,"Ya la vieja de mi suegra\nno más quiere regañar:\nde a tiro la corta verde,\nno la deja madurar.",186,2,27,182,"Estrofa suelta",0,4,"a",21,0,-1,0,223,223,"9774","",0,"","","",1,0,0,[],""],["frenk_t4-n9775",8,"Glorioso San Sebastián,\nmírame cuán afligido,\nque mi suegra barbaján\ndice que soy mantenido.",166,2,-1,182,"Estrofa suelta",1,4,"io",101,0,-1,0,223,223,"9775","",0,"","","",9,0,0,[],""],["frenk_t4-n9776",8,"O me marcho pa la guerra,\no me casan a la fuerza;\nentre la guerra o mi suegra,\nyo me quedo con la guerra:\na la mano del metate\nprefiero la balacera.",166,2,-1,182,"La leva",9,6,"ea",-1,0,-1,0,223,223,"9776","",0,"","","",1,0,0,[],""],["frenk_t4-n9777",8,"Ariles y más ariles,\nariles del alma negra;\nyo me salí de mi casa,\nporque me corrió mi suegra.",171,2,4,182,"El Balajú",0,4,"ea",382,0,-1,0,223,223,"9777","",0,"","","",24,0,0,[],""],["frenk_t4-n9778",8,"Contradicción jocosa\nde una suegra sin razón:\nque quiere quitar a su hija,\nporque no duerme en colchón.",166,2,-1,182,"Estrofa suelta, Las suegras",0,4,"o",31,0,-1,0,223,223,"9778","",0,"","","",1,0,0,[],""],["frenk_t4-n9779",8,"Porque no le quiero a su hija\nni la quiero mantener,\nesa dientes de clavija\nnunca me ha podido ver.",166,2,-1,182,"Las suegras’*",1,4,"e",20,0,-1,0,224,224,"9779","",0,"","","",1,0,0,[],""],["frenk_t4-n9781",8,"Dicen que a todas las suegras\nlas van a echar a la mar,\ny la vieja de mi suegra\nestá aprendiendo a nadar.",168,2,11,182,"La Sanmarqueña",0,4,"a",21,0,-1,0,224,224,"9781","",0,"","","",2,0,0,[],""],["frenk_t4-n9782",8,"El águila en el nopal\nse siente muy orgullosa;\nsi se muriera mi suegra,\n¡ay, qué vida tan dichosa!",166,2,-1,182,"ay, qué vida tan dichosa! [Las chivarras",0,4,"oa",63,0,-1,0,224,224,"9782","",0,"","","",1,0,0,[],""],["frenk_t4-n9784a",8,"¡Ay, Señor San Sebastián!,\nte suplico humildemente:\na la vieja de mi suegra\nyo la pateé de repente.",166,2,-1,182,"Las suegras",0,4,"ee",15,0,-1,0,224,224,"9784a","",0,"","","",2,0,0,[],""],["frenk_t4-n9786",8,"Me voy a vestir de luto,\nde una enagua colorada,\nporque se ha muerto mi suegra,\nesa vieja condenada.",166,2,-1,182,"Arriba, caballo bayo",0,4,"aa",49,0,-1,0,224,224,"9786","",0,"","","",1,0,0,[],""],["frenk_t4-n9787",8,"Con los huesos de mi suegra\nvoy a hacer una escalera,\npara bajar a su tumba\ny escupir su calavera.",167,2,2,182,"Estrofa suelta, El novillo despuntado’’, La Sanmarqueña",0,4,"ea",44,0,-1,0,225,225,"9787","",0,"","","",2,0,0,[],""],["frenk_t4-n9788",8,"Cuando se muera mi suegra,\nque la entierren de perfil,\npor si se quiere salir,\nque se vaya hasta el Brasil.",168,2,11,182,"La Sanmarqueña,' Estrofa suelta",0,4,"i",-1,0,-1,0,225,225,"9788","",0,"","","",7,0,0,[],""],["frenk_t4-n9789a",8,"Cuando se muera mi suegra,\nque la entierren boca abajo,\npor si se quiere salir,\nque se vaya más pa abajo.",168,2,11,182,"La Sanmarqueña; El Balajú; Estrofa suelta",0,4,"ao",-1,0,-1,0,225,225,"9789a","",0,"","","",7,0,0,[],""],["frenk_t4-n9789b",8,"Cuando se muera mi suegra\nle he de tirar un abrazo;\nsi la llevan a enterrar,\nque la entierren boca abajo,\npor si se quiera salir,\nque se vaya más abajo.",167,2,2,182,"El caballito",9,6,"ao",-1,0,-1,0,225,225,"9789b","",0,"","","",7,0,0,[],""],["frenk_t4-n9790",8,"Por debajo de la arena\ncorre el agua, y no la vemos;\nanda a buscarte un muchacho\npara el viejo que queremos.",166,2,-1,183,"Estrofa suelta",0,4,"eo",127,0,-1,0,226,226,"9790","",0,"","","",6,0,0,[],""],["frenk_t4-n9792",8,"¿Qué es aquello que relumbra\ndebajo de aquella mesa?\nPolicarpio Sandoval,\nque parece una princesa.",178,2,10,183,"El güerito",0,4,"ea",201,0,-1,0,226,226,"9792","",0,"","","",8,0,0,[],""],["frenk_t4-n9793",8,"Para una composición\nrecuerda lo que dijiste;\nquizá y no tengas razón,\na Isidoro prometiste;\npareces un maricón,\nporque tú aquí no veniste.",171,2,4,183,"El siquisirí",9,6,"ie",153,0,-1,0,226,226,"9793","",0,"","","",1,0,0,[],""],["frenk_t4-n9794",8,"El chofer de este camión\nes un as del volante,\npero tiene un defecto:\nque le gusta su ayudante.",184,2,14,183,"Estrofa suelta",0,4,"ae",47,0,-1,0,226,226,"9794","",0,"","","",2,0,0,[],""],["frenk_t4-n9795",8,"El chofer de este camión,\nése es un gran manejador,\npero tiene una gran dificultad:\nque le gusta el cobrador.",176,2,3,183,"La Sanmarqueña",3,4,"o",72,0,-1,0,226,226,"9795","",0,"","","",2,0,0,[],""],["frenk_t4-n9796",8,"De aquellos que están allá\nno me parece ninguno:\nuno ya está muy viejo\ny el otro es cuarenta y uno.",169,2,8,183,"Estrofa suelta, La Sanmarqueña",3,4,"uo",230,0,-1,0,226,226,"9796","",0,"","","",1,0,0,[],""],["frenk_t4-n9797",8,"Uno, dos, tres, cuatro, cinco,\ncinco, cuatro, tres, dos, uno,\ncinco por ocho cuarenta,\ncon usted cuarenta y uno.",168,2,11,183,"La Sanmarqueña",0,4,"uo",-1,0,-1,0,227,227,"9797","",0,"","","",3,0,0,[],""],["frenk_t4-n9798",8,"Pues los putos de hoy en día\nya se visten muy sencillo,\nporque quieren que les metan\nla verga por el fundillo.",193,2,31,183,"El pato",0,4,"io",228,0,-1,0,227,227,"9798","",0,"","","",1,0,0,[],""],["frenk_t4-n9799",8,"En la punta de aquel cerro\ntengo una barra de acero;\nen el tronco me echan pedos\ny la punta me la cagan.",169,2,8,183,"Estrofa suelta",5,4,"aa",-1,0,-1,0,227,227,"9799","",0,"","","",21,0,0,[],""],["frenk_t4-n9800",8,"Ese pedo que me echaste\nno fue ofensa que me hiciste,\nfue un ramillete de flores\nque a mi verga le pusiste.",169,2,8,183,"Estrofa suelta",0,4,"ie",153,0,-1,0,227,227,"9800","",0,"","","",1,0,0,[],""],["frenk_t4-n9801",8,"Entre Melón y Melambas\nmataron un pajarito;\nMelón se comió las plumas,\nMelambas el pajarito.",166,2,-1,183,"Estrofa suelta",0,4,"io",-1,0,-1,0,227,227,"9801","",0,"","","",4,0,0,[],""],["frenk_t4-n9802",8,"Entre Melón y Melambas\nmataron una venada;\nMelón le tiene las patas,\nMelambas, la pelada.",174,2,9,183,"Estrofa suelta",0,4,"aa",-1,0,-1,0,227,227,"9802","",0,"","","",4,0,0,[],""],["frenk_t4-n9803",8,"Entre Melón y Melambas\nmataron un policía;\nMelón se llevó el uniforme\ny Melambas la macana.",174,2,9,183,"Estrofa suelta",5,4,"aa",-1,0,-1,0,227,227,"9803","",0,"","","",4,0,0,[],""],["frenk_t4-n9804",8,"Entre Melón y Melambas\nformaron un tren carguero;\nMelón era el maquinista,\nMelambas, el garrotero.",174,2,9,183,"Estrofa suelta",0,4,"eo",38,0,-1,0,227,227,"9804","",0,"","","",4,0,0,[],""],["frenk_t4-n9806",8,"En la punta de aquel cerro\nhay una estaca clavada,\npara meterla en tu culo\ny sacarte la cagada.",174,2,9,183,"Estrofa suelta",0,4,"aa",49,0,-1,0,227,227,"9806","",0,"","","",21,0,0,[],""],["frenk_t4-n9807",8,"Tate quieto, pingorongo,\nno te dé pena por eso;\nestáte como te pongo:\nchupando el tuétano al güeso.",189,2,5,183,"Estrofa suelta",1,4,"eo",48,0,-1,0,227,227,"9807","",0,"","","",1,0,0,[],""],["frenk_t4-n9809",8,"Ni a los coches ni al....\nni al volar, por ser tan duro;\nyo a nada le pongo tacho,\nporque llegando al oscuro,\nsea de hembra o sea de macho,\nyo lo que quiero es el culo.",171,2,4,183,"El siquisirí",9,6,"uo",-1,0,-1,0,228,228,"9809","",0,"","","",1,0,0,[],""],["frenk_t4-n9810",8,"Suplicamos al ratero,\namante del mal vivir,\nno se le vaya a ocurrir\nclavarse este monedero.\nFíjense bien, el dinero,\nes de níquel y de cobre,\ny no sacará de pobre\na ningún ratero malo;\ntoda la caja es de palo:\n¡le rogamos no maniobre!",173,2,17,184,"Estrofa suelta",18,10,"oe",410,0,-1,0,229,229,"9810","",0,"","","",1,0,0,[],""],["frenk_t4-n9811",8,"Pasaron las noches,\npasaron los días,\npasaron los coches\ny los tranvías.",168,2,11,184,"Estrofa suelta",6,4,"ia",214,0,-1,0,229,229,"9811","",0,"","","",1,0,0,[],""],["frenk_t4-n9812",8,"El sol sale de día,\nla luna sale de noche,\ncuatro ruedas tiene un coche:\n¡cuánta melancolía!",185,2,13,184,"Estrofa suelta",11,4,"ia",0,0,-1,0,229,229,"9812","",0,"","","",1,0,0,[],""],["frenk_t4-n9813",8,"Árboles de la alameda,\nque en la punta tienen flores,\nno les pusieron colores,\nporque se acabaron en la tlapalería.",168,2,11,184,"El cateto",3,4,"ia",-1,0,-1,0,229,229,"9813","",0,"","","",5,0,0,[],""],["frenk_t4-n9814",8,"Sin tener barranca honda,\nme dice un compañerito:\n“No seas tú como el perrito,\nque al sentarse, así se monta”.",166,2,-1,184,"Por lo alto doy cincuenta",5,4,"oa",-1,0,-1,0,229,229,"9814","",0,"","","",1,0,0,[],""],["frenk_t4-n9815",8,"Áhi viene un cojo\npor la banqueta,\nsacando sones\ncon la muleta.",187,2,12,184,"El cojo",6,4,"ea",200,0,-1,0,229,229,"9815","",0,"","","",1,0,0,[],""],["frenk_t4-n9816",8,"Entré a la huerta y corté\nun limón reverdeciendo,\nentre los gajos hallé\nun gachupín escribiendo.",192,2,22,184,"Zapateado",1,4,"eo",52,0,-1,0,229,229,"9816","",0,"","","",2,0,0,[],""],["frenk_t4-n9817a",8,"Un ciego estaba escribiendo\nlo que el mudo le decía;\nel sordo lo estaba oyendo\npara cantarlo otro día.",175,2,6,184,"Estrofa suelta",1,4,"ia",0,0,-1,0,229,229,"9817a","",0,"","","",3,0,0,[],""],["frenk_t4-n9818",8,"Era capitán de un barco\nde las Naciones Unidas,\nla mar tenía por encanto\nde aquellas aguas teñidas,\ntenía un avión en su barco\ncon dos mil paracaídas.",175,2,6,184,"La Petenera",9,6,"ia",279,0,-1,0,230,230,"9818","",0,"","","",1,0,0,[],""],["frenk_t4-n9819",8,"En el pueblo no sé dónde\ncelebran no sé qué santo,\nle ofrecen no sé qué cosa,\ny pagan no sé qué tanto.",166,2,-1,184,"Estrofa suelta",0,4,"ao",30,0,-1,0,230,230,"9819","",0,"","","",1,0,0,[],""],["frenk_t4-n9820",8,"En el cerrito\nde los otates\nbrincan y saltan\nlos cacahuates.",168,2,11,184,"Estrofa suelta",6,4,"ae",283,0,-1,0,230,230,"9820","",0,"","","",1,0,0,[],""],["frenk_t4-n9822",8,"Ja, ja, ja,\nQué risa que a mí me da,\nporque, porque, porque\nen el mundo hay variedad.",166,2,-1,184,"Cielito lindo",3,4,"a",-1,0,-1,0,230,230,"9822","",0,"","","",1,0,0,[],""],["frenk_t4-n9823",8,"Parece que no,\nparece que sí,\nparece que pega,\npero no pegó.",170,2,7,184,"El aguajacado",5,4,"o",2,0,-1,0,230,230,"9823","",0,"","","",1,0,0,[],""],["frenk_t4-n9824",8,"¡Que búscalo allí!,\n¡que cógelo allá!,\n¡que búscalo acá!,\n¡que búscalo aquí!",171,2,4,184,"Mi marido fue a La Habana",11,4,"i",23,0,-1,0,230,230,"9824","",0,"","","",1,0,0,[],""],["frenk_t4-n9825",8,"Mi vecina de allí en frente\nse llamaba Doña Clara,\ny si no se hubiera muerto,\ntodavía así se llamara.",166,2,-1,184,"El pastelero; La vecina de allí enfrente; Las ventanas; Estrofa suelta",0,4,"aa",57,0,-1,0,230,230,"9825","",0,"","","",1,0,0,[],""],["frenk_t4-n9826",8,"El diablo se fue a tomar,\ny le dieron pulque curado;\nde tan sabroso que estaba,\nque hasta se quedó tirado.",175,2,6,184,"Estrofa suelta",0,4,"ao",14,0,-1,0,231,231,"9826","",0,"","","",1,0,0,[],""],["frenk_t4-n9827",8,"El diablo se fue a pasear,\ny le dieron chocolate;\nde tan caliente que estaba,\nque hasta se quemó el gaznate.",175,2,6,184,"Estrofa suelta",0,4,"ae",384,0,-1,0,231,231,"9827","",0,"","","",1,0,0,[],""],["frenk_t4-n9828",8,"El diablo perdió un cdntavo\nla noche de San Miguel,\ny era el único dinero\nque tenía para perder.",168,2,11,184,"Los padres de San Francisco",0,4,"e",-1,0,-1,0,231,231,"9828","",0,"","","",1,0,0,[],""],["frenk_t4-n9829",8,"Áhi viene el diablo mayor\ncon sus veinticinco hermanos,\ny dice que se va a llevar\na todos los marihuanos.",166,2,-1,184,"La marihuana",0,4,"ao",318,0,-1,0,231,231,"9829","",0,"","","",1,0,0,[],""],["frenk_t4-n9830",8,"Marihuana tuvo un hijito,\ny le pusieron San Expedito;\ncomo era abogado de los de Santa Anna,\npor esa sazón de la marihuana.",168,2,11,184,"La marihuana",3,4,"aa",-1,0,-1,0,231,231,"9830","",0,"","","",1,0,0,[],""],["frenk_t4-n9832",8,"Marihuana, ya no puedo\nni levantar la cabeza,\ncon los ojos retecolorados\ny la boca reseca, reseca.",168,2,11,184,"La marihuana; Estrofa suelta",3,4,"ea",-1,0,-1,0,231,231,"9832","",0,"","","",1,0,0,[],""],["frenk_t4-n9833",8,"Cuando estés en el infierno,\ntodito lleno de llamas,\nallí te dirán los diablos:\n“Áhi va la india, ¿qué no le hablas?”",166,2,-1,184,"El viaje al infierne",0,4,"aa",-1,0,-1,0,231,231,"9833","",0,"","","",1,0,0,[],""],["frenk_t4-n9834",8,"La manzana se pasea\nde la sala al comedor:\n“No me maten con cuchillo,\nmátenme con tenedor”.",168,2,11,184,"Estrofa suelta",0,4,"o",72,0,-1,0,231,231,"9834","",0,"","","",1,0,0,[],""],["frenk_t4-n9835",8,"¡Ay!, qué bonito es volar\na las once de la noche,\nsubirse y dejarse caer\nen los tirantes de un coche;\nque hasta quisiera llorar (¡ay, mamá!).",171,2,4,184,"La bruja",7,5,"a",21,0,-1,0,232,232,"9835","",0,"","","",3,0,0,[],""],["frenk_t4-n9836",8,"Una currita me dijo\nque le hiciera yo un favor:\nque le acomodara un hijo\nde escribano en Peñaflor;\no si no, que fuera fraile,\ny después gobernador.",166,2,-1,184,"El pájaro carpintero",9,6,"o",72,0,-1,0,232,232,"9836","",0,"","","",1,0,0,[],""],["frenk_t4-n9837",8,"Los besos del estudiante (Llorona)\nson como el terrón de azúcar:\nla muchacha que los prueba (Llorona)\nhasta los dedos se chupa.",168,2,11,184,"La Llorona; La Sanmarqueña; Estrofa suelta",3,4,"ua",-1,0,-1,0,232,232,"9837","",0,"","","",1,0,0,[],""],["frenk_t4-n9838",8,"No te cases con un chino,\nni con un japonés;\nmejor cásate con un muchacho\nde la secundaria 66.",168,2,11,184,"Estrofa suelta",3,4,"aa",-1,0,-1,0,232,232,"9838","",0,"","","",1,0,0,[],""],["frenk_t4-n9839",8,"Para pasar año\nse necesita\nhacerle la barba\na la señorita.\nY arriba y arriba\nya viene el año\ny de año pasaré.",166,2,-1,184,"Estrofa suelta",4,7,"e",-1,0,-1,0,232,232,"9839","",0,"","","",1,0,0,[],""],["frenk_t4-n9841",8,"Trabajar, ¡qué horror!,\nestudiar, ¡un poco peor!\nPara no ir a la escuela,\nun poquito de viruela;\neso es lo mejor\nque me hubiera dado hoy.",184,2,14,184,"Estrofa suelta",9,6,"o",-1,0,-1,0,232,232,"9841","",0,"","","",1,0,0,[],""],["frenk_t4-n9842",8,"Tus ojos son dos luceros\nque brillan con esplendor,\nse parecen a los ceros\nque te pone el profesor.",168,2,11,184,"Estrofa suelta",1,4,"o",72,0,-1,0,232,232,"9842","",0,"","","",5,0,0,[],""],["frenk_t4-n9843",8,"Soñé que la nieve ardía,\nsoñé que el sol helaba,\ny por soñar imposibles,\nsoñé que tú no estudiabas.",168,2,11,184,"Estrofa suelta",0,4,"aa",-1,0,-1,0,233,233,"9843","",0,"","","",1,0,0,[],""],["frenk_t4-n9844",8,"Cuando vayas por la calle\ny te encuentres una lata,\nacuérdate de los dulces\nque le debes a doña Cata.",174,2,9,184,"Estrofa suelta",0,4,"aa",74,0,-1,0,233,233,"9844","",0,"","","",5,0,0,[],""],["frenk_t4-n9845",8,"Tanto juegas tú en tu casa,\ntanto juegas tú frontón,\npero yo no me quedo abajo,\ny ahí te va mi jonrón.",168,2,11,184,"Estrofa suelta",0,4,"o",31,0,-1,0,233,233,"9845","",0,"","","",1,0,0,[],""],["frenk_t4-n9846",8,"No te sientes en el banco,\nporque el banco tiene cera;\nyo no siento la pegada,\nsino la despegadera.",177,2,18,184,"El tejón",0,4,"ea",44,0,-1,0,233,233,"9846","",0,"","","",1,0,0,[],""],["frenk_t4-n9847",8,"¡Ay, señora!, su periquito\nme dijo: “Vieja pelona”,\ny corrí frente a un espejo\ny me vi que estoy muy mona.",166,2,-1,184,"El perico",0,4,"oa",7,0,-1,0,233,233,"9847","",0,"","","",1,0,0,[],""],["frenk_t4-n9848",8,"Ahora, si quieren saber\nel secreto de mi suerte,\ntienen que agarrarse fuerte,\nno se vayan a caer.",166,2,-1,184,"Yo agarro parejo",11,4,"e",20,0,-1,0,233,233,"9848","",0,"","","",1,0,0,[],""],["frenk_t4-n9849",8,"Amigos, les contaré\nlo que a mí me sucedió:\nestando mi tía gordita,\nquería que pariera yo.",177,2,18,184,"El ausente",0,4,"o",2,0,-1,0,233,233,"9849","",0,"","","",3,0,0,[],""],["frenk_t4-n9850",8,"Me llevaron prisionero,\nya me iban a fusilar;\nme quitaron mi sombrero,\nme empezaron a pelar;\nme dijo ese peluquero:\n“Tú vas a ser general”.",167,2,2,184,"El querreque",9,6,"a",-1,0,-1,0,233,233,"9850","",0,"","","",1,0,0,[],""],["frenk_t4-n9851",8,"Toda la noche me estuve\ndebajo de las estrellas,\nellas, diciéndome chismes,\ny yo, creyéndome de ellas.",170,2,7,184,"La Malagueña curreña",0,4,"ea",89,0,-1,0,233,233,"9851","",0,"","","",2,0,0,[],""],["frenk_t4-n9852",8,"En la puerta de mi casa\nestá una mata de romero;\ncuando me acuesto en mi cama\nsolo me cae el dinero.",169,2,8,184,"Estrofa suelta",0,4,"eo",38,0,-1,0,233,233,"9852","",0,"","","",24,0,0,[],""],["frenk_t4-n9853",8,"Tres letras en un papel\nme miraban, se reían;\ncomo no las supe leer,\nno supe lo que decían,\n¡cómo no me enseñaría\ncuando estaba de aprender!",166,2,-1,184,"El bejuquito",9,6,"e",20,0,-1,0,234,234,"9853","",0,"","","",1,0,0,[],""],["frenk_t4-n9854",8,"Me subí por ’l alto pino,\ndi vuelta por el ciprés,\ny al abrir la media hoja,\nse me fueron los dos pies.",187,2,12,184,"El cascabel",0,4,"e",218,0,-1,0,234,234,"9854","",0,"","","",1,0,0,[],""],["frenk_t4-n9855",8,"Me subí en un palo\nalto y delgado,\ny no me pude bajar,\ny allí me quedé colgado.",174,2,9,184,"Estrofa suelta",0,4,"ao",14,0,-1,0,234,234,"9855","",0,"","","",1,0,0,[],""],["frenk_t4-n9856",8,"Me subí en un caballo\ny me fui muy a la carrera;\nde tan ligero que iba,\nme caí en la pradera.",174,2,9,184,"Estrofa suelta",0,4,"ea",44,0,-1,0,234,234,"9856","",0,"","","",1,0,0,[],""],["frenk_t4-n9857",8,"Tengo una casa\nmuy bien arreglada,\ncon cuatro sillas\ny una olla quebrada.",174,2,9,184,"Estrofa suelta",3,4,"aa",49,0,-1,0,234,234,"9857","",0,"","","",1,0,0,[],""],["frenk_t4-n9858",8,"Cuando salí de mi tierra\nde nadie me despedí,\nsólo de una perra flaca\nque estaba junto de mí.",189,2,5,184,"Estrofa suelta, Las chaparreras",0,4,"i",23,0,-1,0,234,234,"9858","",0,"","","",9,0,0,[],""],["frenk_t4-n9859",8,"Ya llegué,\nya me vienen a llevar,\nsobre las olas del mar,\ncuatro diablos a bañar.",176,2,3,184,"El veinte",3,4,"a",21,0,-1,0,234,234,"9859","",0,"","","",1,0,0,[],""],["frenk_t4-n9860",8,"Arrímate, Pepa,\ny arrímate, Juana,\nque áhi anda la bruja\ndebajo la cama.",166,2,-1,184,"Estrofa suelta",0,4,"aa",-1,0,-1,0,234,234,"9860","",0,"","","",1,0,0,[],""],["frenk_t4-n9861",8,"Y esto es tan verdad\ncomo ver un borrico volar\npor los elementos.\n—Churripampli de mis pensamientos,\n¿dónde te hallaré?\n—En la esquina, tomando café.",171,2,4,184,"Churripampli se casa",9,6,"e",77,0,-1,0,234,234,"9861","",0,"","","",1,0,0,[],""],["frenk_t4-n9862",8,"De un seso de un zancudo\nsacaré una pomada;\nya verán cómo la curo\nsin que le cueste nada.",187,2,12,184,"Estrofa suelta",0,4,"aa",49,0,-1,0,234,234,"9862","",0,"","","",1,0,0,[],""],["frenk_t4-n9864",8,"Está un pobre moribundo\nen el pueblo de Juchitán;\na bien morir le ayudaban\ncon la sílaba bam y bam.",169,2,8,184,"Estrofa suelta",0,4,"a",-1,0,-1,0,235,235,"9864","",0,"","","",1,0,0,[],""],["frenk_t4-n9865",8,"El muchacho se cayó\npor andar cortando limas;\ndel porrazo que se dio,\nse espantaron las gallinas.",187,2,12,184,"El muchacho",0,4,"ia",-1,0,-1,0,235,235,"9865","",0,"","","",3,0,0,[],""],["frenk_t4-n9866",8,"El muchacho se cayó\npor andar cortando flores;\ndel porrazo que llevó,\nse espantó María Dolores.",187,2,12,184,"El muchacho",1,4,"oe",5,0,-1,0,235,235,"9866","",0,"","","",3,0,0,[],""],["frenk_t4-n9867",8,"El muchacho se cayó\nen la puerta de la escuela;\ndel porrazo que llevó,\nse espantó María Manuela.",187,2,12,184,"El muchacho",1,4,"ea",167,0,-1,0,235,235,"9867","",0,"","","",3,0,0,[],""],["frenk_t4-n9868",8,"Padeciendo de un fuerte accidente\ny un dolor que siempre me da,\nla otra tarde encontré al cirujano,\ny me dijo me fuera a bañar.",166,2,-1,184,"Los baños",3,4,"a",-1,0,-1,0,235,235,"9868","",0,"","","",1,0,0,[],""],["frenk_t4-n9869",8,"—¿Sabes la tos?\n—Yo no la sé.\n—¿Quieres oírla?,\nla toseré:\n“ejé, ejé, ejé, ejé”.",166,2,-1,184,"La tos",7,5,"e",77,0,-1,0,235,235,"9869","",0,"","","",1,0,0,[],""],["frenk_t4-n9870",8,"La sama es un accidente\nque depende del humor,\nque si se la rascan, es malo\ny si no se la rascan, es peor.",171,2,4,184,"La sama",3,4,"o",72,0,-1,0,235,235,"9870","",0,"","","",1,0,0,[],""],["frenk_t4-n9871",8,"Samícula emperadora,\nmadre de la sebadilla,\ndéjame rascarme un poco,\nque me llega a la rodilla.",171,2,4,184,"La sama",0,4,"ia",162,0,-1,0,235,235,"9871","",0,"","","",2,0,0,[],""],["frenk_t4-n9872",8,"Samícula emperadora,\nmadre de la comezón,\ndéjame rascar un poco,\nque me sabe a requesón.",171,2,4,184,"La sama",0,4,"o",31,0,-1,0,235,235,"9872","",0,"","","",2,0,0,[],""],["frenk_t4-n9873",8,"En una ventana bájica\nestaba una señorítica,\ncomponiéndose los chínicoi\nretorciéndose todítica.",166,2,-1,184,"El tagarno",0,4,"ia",636,0,-1,0,236,236,"9873","",0,"","","",1,0,0,[],""],["frenk_t4-n9874",8,"Por lo que sítiqui,\npor lo que nótico,\nque más de poético\ntengo de lótico.",178,2,10,184,"El tagarno",6,4,"oo",637,0,-1,0,236,236,"9874","",0,"","","",2,0,0,[],""],["frenk_t4-n9875a",8,"Por lo que sítico,\npor lo que nótico,\npor lo que el poético\nme preguntótico.",166,2,-1,184,"El tagamo’T",6,4,"oo",637,0,-1,0,236,236,"9875a","",0,"","","",1,0,0,[],""],["frenk_t4-n9876",8,"Está enfermo Don Ventura,\ny el cura de la parroquia\nle afirmaba que lo cura:\n¿que lo cura?, ¡qué locura!",166,2,-1,184,"Estrofa suelta",5,4,"ua",17,0,-1,0,236,236,"9876","",0,"","","",1,0,0,[],""],["frenk_t4-n9877",8,"Escucha doña Nicasia,\nescucha todito el día,\nescucha toda la noche\ny cucha al amanecer.",178,2,10,184,"El güerito",5,4,"e",-1,0,-1,0,236,236,"9877","",0,"","","",1,0,0,[],""],["frenk_t4-n9878",8,"Un diablo cayó al infierno,\ny otro diablo lo sacó,\ny dijeron los diablitos:\n“¿Cómo diablos se cayó?”",171,2,4,184,"Estrofa suelta",0,4,"o",2,0,-1,0,236,236,"9878","",0,"","","",1,0,0,[],""],["frenk_t4-n9879",8,"Un perdido muy perdido\nque de perdido se pierde,\nsi se pierde, ¿qué se pierde,\nsi se pierde lo perdido?",166,2,-1,184,"El pastelero^",11,4,"io",-1,0,-1,0,236,236,"9879","",0,"","","",1,0,0,[],""],["frenk_t4-n9880a",8,"Han dicho que he dicho un dicho,\ntal dicho no he dicho yo;\nbien estuviera el dicho,\nsi lo hubiera dicho yo.",168,2,11,184,"Estrofa suelta",1,4,"o",-1,0,-1,0,236,236,"9880a","",0,"","","",2,0,0,[],""],["frenk_t4-n9881",8,"Yo traigo un medio dolor,\nque me trae de medio a medio\nquisiera un medio doctor,\nque me dé un medio remedio\nen medio de este dolor.",175,2,6,184,"El querreque",7,5,"o",72,0,-1,0,237,237,"9881","",0,"","","",1,0,0,[],""],["frenk_t4-n9883",8,"Quiero mandar un tamal\ny debo de ver a quién,\nporque me he puesto a pensar\nque, aunque lo mande por bien,\nno está bien, porque está mal.",189,2,5,184,"Estrofa suelta",7,5,"a",-1,0,-1,0,237,237,"9883","",0,"","","",1,0,0,[],""],["frenk_t4-n9884",8,"Ola que viene,\nola que va,\n¡hola, muchacho!,\n¿cómo te va?",168,2,11,184,"Estrofa suelta",6,4,"a",-1,0,-1,0,237,237,"9884","",0,"","","",1,0,0,[],""],["frenk_t4-n9885",8,"Las pelotas, las pelotas,\nlas pelotas de carey\nson igual en la Indochina,\nel Japón y el Japagüéy.",174,2,9,184,"Estrofa suelta",0,4,"e",133,0,-1,0,237,237,"9885","",0,"","","",1,0,0,[],""],["frenk_t4-n9886",8,"Cuando mi abuela murió\nme dejó bien heredada:\nuna quiebra de magueyes\ny una yegüita ensillada;\nla quiebra se me acabó,\nsólo el homito me queda.",176,2,3,184,"Estrofa suelta",9,6,"ea",-1,0,-1,0,237,237,"9886","",0,"","","",1,0,0,[],""],["frenk_t4-n9887",8,"Un estudiante a su novia\naritmética enseñaba,\ny al cabo de nueve meses\nla novia multiplicaba.",168,2,11,184,"La Sanmarqueña",0,4,"aa",28,0,-1,0,237,237,"9887","",0,"","","",1,0,0,[],""],["frenk_t4-n9888",8,"Cuando la india me iba a ver\nllevaba su chiquihuite;\nde todas yerbas llevaba,\nmenos papaloquelite,\nporque eso no le gustaba.",171,2,4,184,"La indita",7,5,"aa",28,0,-1,0,237,237,"9888","",0,"","","",1,0,0,[],""],["frenk_t4-n9889",8,"Cuando a Alvarado me fui\na pasarme una semana,\nluego que de allí volví\nya me faltaba una hermana;\nen vez de ganar, perdí:\nbien me lo decía mi mama.",171,2,4,184,"El siquisirí; La morena",9,6,"aa",-1,0,-1,0,237,237,"9889","",0,"","","",1,0,0,[],""],["frenk_t4-n9890a",8,"Si tienes hijas bonitas\nde costumbres disolutas\neres pobre porque quieres:\npon una casa de modas.",185,2,13,184,"Estrofa suelta, La Sanmarqueña",5,4,"oa",-1,0,-1,0,237,237,"9890a","",0,"","","",1,0,0,[],""],["frenk_t4-n9891",8,"Si te riegan la maceta\nantes de nacer el sol,\n¡ay, qué matas tan floridas!\n¡y ay, qué matas de frijol!",166,2,-1,184,"‘‘Chula la mañana",0,4,"o",24,0,-1,0,238,238,"9891","",0,"","","",1,0,0,[],""],["frenk_t4-n9892",8,"Al general cartuchero,\npara celebrar su triunfo,\nle regalaron un fo-\nnógrafo de primera.",185,2,13,184,"Estrofa suelta",5,4,"ea",-1,0,-1,0,238,238,"9892","",0,"","","",1,0,0,[],""],["frenk_t4-n9893",8,"Antenoche fui a tu casa\ny me lastimé un dedo,\ny del esfuerzo que hice,\n¡pum!, que se me sale una lágrima.",166,2,-1,184,"Las bombas viejas",5,4,"aa",-1,0,-1,0,238,238,"9893","",0,"","","",8,0,0,[],""],["frenk_t4-n9894",8,"En el puerto de Tampico\nme asaltaron los ladrones,\ny del susto que me dieron,\nse me cayó una chancla.",168,2,11,184,"El cateto",5,4,"aa",-1,0,-1,0,238,238,"9894","",0,"","","",4,0,0,[],""],["frenk_t4-n9895",8,"—Úrsula, ¿qué estás haciendo?\n—Remendando mis enaguas,\nporque si no las remiendo,\nentonces se me ven las trenzas.",169,2,8,184,"Ürsula’T",5,4,"ea",-1,0,-1,0,238,238,"9895","",0,"","","",2,0,0,[],""],["frenk_t4-n9896",8,"Un niño iba corriendo,\ny al pasar una calzada\nun coche lo atropelló,\ny se lo llevó la Cruz Roja.",168,2,11,184,"Estrofa suelta, Las bombas viejas",5,4,"oa",-1,0,-1,0,238,238,"9896","",0,"","","",1,0,0,[],""],["frenk_t4-n9898",8,"¡Quién tuviera el venturón\ncomo lo tuvo el cabrito,\nque se murió de chiquito\npor no llegar a grande!",185,2,13,184,"Estrofa suelta",5,4,"ae",-1,0,-1,0,239,239,"9898","",0,"","","",1,0,0,[],""],["frenk_t4-n9899",8,"Un chivo pegó un reparo\ny en el aire se detuvo;\nhay chivos que tienen madre,\npero éste ni madre tuvo.",168,2,11,184,"La Sanmarqueña; Estrofa suelta",0,4,"uo",638,0,-1,0,239,239,"9899","",0,"","","",2,0,0,[],""],["frenk_t4-n9900",8,"Una mañana en las dunas\nno tenía qué cobijarme;\nsubí al cerro y comí tunas;\nya tuve con qué taparme.",166,2,-1,184,"Estrofa suelta",1,4,"ae",35,0,-1,0,239,239,"9900","",0,"","","",1,0,0,[],""],["frenk_t4-n9901",8,"Yo soy el cólera morbus,\nmi marido es el torzón,\nmis hijos son los calambres,\nmi suegra, la evacuación.",166,2,-1,184,"Estrofa suelta",0,4,"o",31,0,-1,0,239,239,"9901","",0,"","","",1,0,0,[],""],["frenk_t4-n9902",8,"En la punta de aquel cerro\nestá un zorrillo;\nyo que le aviento el lazo,\ny él que me pica el fundillo.",187,2,12,184,"Estrofa suelta",3,4,"io",228,0,-1,0,239,239,"9902","",0,"","","",21,0,0,[],""],["frenk_t4-n9903",8,"Yo no soy apóstol,\nni soy nada;\nno más acabo de cenar,\ny me largo a la tiznada.",166,2,-1,184,"Estrofa suelta",3,4,"aa",49,0,-1,0,239,239,"9903","",0,"","","",1,0,0,[],""],["frenk_t4-n9904",8,"Cuentan de un sabio que un día\ntan caliente se encontraba,\nque por el culo le daba,\na una hija que tenía.\n“¿Habrá otro, entre sí decía,\nmás puto y cabrón que yo?”\nY cuando el rostro volvió\nhalló la respuesta, viendo\nque su hijo iba cogiendo\na la madre que lo parió.",168,2,11,184,"Estrofa suelta",18,10,"o",2,0,-1,0,239,239,"9904","",0,"","","",1,0,0,[],""],["frenk_t4-n9905",8,"Las mujeres que portan\nbastante ropa,\nparecen bergantines\ncon viento en popa.",166,2,-1,184,"Estrofa suelta",6,4,"oa",608,0,-1,0,240,240,"9905","",0,"","","",1,0,0,[],""],["frenk_t4-n9906",8,"Don Ferruco es un catrín\nque viste de sobretodo,\ny al dar la vuelta a la esquina,\nse fue de hocico en el lodo.",166,2,-1,184,"Estrofa suelta",0,4,"oo",261,0,-1,0,240,240,"9906","",0,"","","",1,0,0,[],""],["frenk_t4-n9907",8,"Úrsula se fue a lavar,\na lavar a la corriente;\ngasta litros de jabón,\ny la ropa, como siempre.",169,2,8,184,"Úrsula",0,4,"ee",-1,0,-1,0,240,240,"9907","",0,"","","",1,0,0,[],""],["frenk_t4-n9908",8,"Gallos y gallinas\nse pusieron a pelear;\nasí estabas con tu hermana\ncuando te fui a visitar.",168,2,11,184,"Estrofa suelta",0,4,"a",21,0,-1,0,240,240,"9908","",0,"","","",1,0,0,[],""],["frenk_t4-n9909",8,"¡Qué bonitos son los negros!,\nparecen plátano asado\ncuando se ponen camisa,\nrevocado en la ceniza.",171,2,4,184,"Los negritos",5,4,"ia",420,0,-1,0,240,240,"9909","",0,"","","",1,0,0,[],""],["frenk_t4-n9910",8,"Me puse a bañar a un negro,\na ver si se componía;\nentre más lo enjabonaba,\nmás negro se ponía.",174,2,9,184,"Estrofa suelta",0,4,"ia",0,0,-1,0,240,240,"9910","",0,"","","",1,0,0,[],""],["frenk_t4-n9911",8,"Los negritos de Jamapa\ncuando se van a bañar\nhacen la agua “japa, japa”.\n¿Cómo hacen los negros\npara trabajar?\nComen tortilla\ncon carne y sal.",166,2,-1,184,"Estrofa suelta",4,7,"a",-1,0,-1,0,240,240,"9911","",0,"","","",1,0,0,[],""],["frenk_t4-n9912",8,"Los indios no son cristianos\nni tienen la fe completa;\nsi no, váyanle a las manos,\ny el pelo como escobeta\ny la barba como gusano.",171,2,4,184,"La indita’T",7,5,"ao",-1,0,-1,0,240,240,"9912","",0,"","","",1,0,0,[],""],["frenk_t4-n9913",8,"¡Anda, indita ladina,\ncolor de manzana seca!\nSe la da por gachupina\ny siendo de la Mixteca.",171,2,4,184,"La indita",1,4,"ea",594,0,-1,0,240,240,"9913","",0,"","","",1,0,0,[],""],["frenk_t4-n9914",8,"El amor del estudiante\nes como el palo de arroz:\nno tiene para comprar cigarros,\ny ya quiere tener de a dos.",174,2,9,184,"Estrofa suelta",3,4,"o",87,0,-1,0,240,240,"9914","",0,"","","",2,0,0,[],""],["frenk_t4-n9915",8,"Toma esta canastita\nde chicharrones.\n¡Quién te lo manda ser burro!,\n¿por qué no comes?",178,2,10,184,"Las canastitas",6,4,"oe",-1,0,-1,0,241,241,"9915","",0,"","","",2,0,0,[],""],["frenk_t4-n9916",8,"Toma esta canastita\nde chiles verdes.\n¡Quién te lo manda ser burro!,\n¿por qué no muerdes?",178,2,10,184,"Las canastitas",6,4,"ee",369,0,-1,0,241,241,"9916","",0,"","","",2,0,0,[],""],["frenk_t4-n9917",8,"En la esquina de provincia\nmataron a un jorobado,\ny en la joroba tenía\ndoce cargas de pescado.",166,2,-1,184,"El jorobante; Estrofa suelta",0,4,"ao",14,0,-1,0,241,241,"9917","",0,"","","",1,0,0,[],""],["frenk_t4-n9918",8,"En el río de los naranjos\nmataron a un jorobante,\ny en la joroba tenía\ndiez arrobas de picante.\nJorobita, tipitante,\nque pareces elefante.",166,2,-1,184,"El jorobante",9,6,"ae",47,0,-1,0,241,241,"9918","",0,"","","",1,0,0,[],""],["frenk_t4-n9919",8,"Para entrar en Valencia (cielito lindo)\ntuvo una hermana\nuna valencianita (cielito lindo)\ncara de rana.",171,2,4,184,"Cielito lindo",3,4,"aa",4,0,-1,0,241,241,"9919","",0,"","","",1,0,0,[],""],["frenk_t4-n9920",8,"El Cerro de la Campana\nse está muriendo de risa\nal ver a los de la Prepa\ncomiendo en caballeriza.",174,2,9,184,"Estrofa suelta",0,4,"ia",420,0,-1,0,241,241,"9920","",0,"","","",1,0,0,[],""],["frenk_t4-n9921",8,"Las torres de Catedral\nse están muriendo de risa\nde ver a los estudiantes\ncon corbata y sin camisa.",184,2,14,184,"Estrofa suelta, La Sanmarqueña",0,4,"ia",68,0,-1,0,241,241,"9921","",0,"","","",1,0,0,[],""],["frenk_t4-n9922",8,"Cuando vayas a cagar\nno te limpies con papel,\nporque el papel tiene letras,\ny el culo no eat»» leer.",169,2,8,184,"Estrofa suelta",0,4,"e",-1,0,-1,0,241,241,"9922","",0,"","","",1,0,0,[],""],["frenk_t4-n9924",8,"En la punta de aquel cerro\nestaba una cubeta llena de cubala;\n¿quién quieres que te quiera,\nsi tu culo tiene caca?",187,2,12,184,"Estrofa suelta",3,4,"aa",-1,0,-1,0,242,242,"9924","",0,"","","",21,0,0,[],""],["frenk_t4-n9925",8,"Este joven que está ahí\nlo espantaron los ladrones,\ny del susto que llevó,\nse ensució los pantalones.",187,2,12,184,"Estrofa suelta",0,4,"oe",34,0,-1,0,242,242,"9925","",0,"","","",1,0,0,[],""],["frenk_t4-n9926",8,"¿Qué es aquello que relumbra\ndebajo de aquella cama?\nEl bacín de doña Juana,\nque está que se derrama.",178,2,10,184,"Estrofa suelta",0,4,"aa",-1,0,-1,0,242,242,"9926","",0,"","","",8,0,0,[],""],["frenk_t4-n9927",8,"Margaritas y Llanas,\nmucho cuidado:\nya viene la bruja\na curar almorranas.",182,2,21,184,"Estrofa suelta",3,4,"aa",263,0,-1,0,242,242,"9927","",0,"","","",1,0,0,[],""],["frenk_t4-n9929",8,"Vamos a jugar\nal mono de alambre,\ny el que no lo baile\nle dará un calambre.",166,2,-1,184,"Estrofa suelta",0,4,"ae",-1,0,-1,0,242,242,"9929","",0,"","","",1,0,0,[],""],["frenk_t4-n9930",8,"Como dijo la guacamaya\nal pájaro azul turquí:\n“Vámonos a la chingada,\n¿qué estamos haciendo aquí?”",168,2,11,184,"Estrofa suelta",0,4,"i",23,0,-1,0,242,242,"9930","",0,"","","",1,0,0,[],""],["frenk_t4-n9931",8,"Esta campana no toca,\nporque no tiene badajo;\npasen a tomar su copa,\ny váyanse a su trabajo.",176,2,3,184,"Estrofa suelta",0,4,"ao",168,0,-1,0,242,242,"9931","",0,"","","",1,0,0,[],""],["frenk_t4-n9932",8,"Escaleras para arriba\ny escaleras para abajo;\nunos se van para arriba\ny otros se van para abajo.",166,2,-1,184,"La Sanmarqueña; La carretera",1,4,"ao",-1,0,-1,0,242,242,"9932","",0,"","","",1,0,0,[],""],["frenk_t4-n9933",8,"Asco les tengo a los pesos\ny también a los tostones;\npero más asco les tengo\na una pila de cartones.",166,2,-1,184,"La chinita; La carretera",0,4,"oe",34,0,-1,0,242,242,"9933","",0,"","","",2,0,0,[],""],["frenk_t4-n9934",8,"Que cuando se baña\nla vista se me empaña,\nporque miro de lejos\nno más puros cangrejos.",166,2,-1,184,"El palmero",5,4,"eo",149,0,-1,0,243,243,"9934","",0,"","","",1,0,0,[],""],["frenk_t4-n9935",8,"La escalera se te quiebre\ny caigas de arriba abajo,\nenrollando tu tortilla\ny pelando tu tasajo.",169,2,8,184,"Estrofa suelta",0,4,"ao",168,0,-1,0,243,243,"9935","",0,"","","",1,0,0,[],""],["frenk_t4-n9936",8,"Estaba el güero sentado,\nsentado en una banqueta,\nescupiéndose la mano\npara hacerse una puñeta.",174,2,9,184,"Estrofa suelta",0,4,"ea",200,0,-1,0,243,243,"9936","",0,"","","",1,0,0,[],""],["frenk_t4-n9937",8,"La cucha le dijo al cuche:\n—Vamos a comer cagada.\nLa cucha le contestó:\n—Si es de crudo una chingada.",168,2,11,184,"La Sanmarqueña",0,4,"aa",49,0,-1,0,243,243,"9937","",0,"","","",1,0,0,[],""],["frenk_t4-n9938",8,"La cucaracha pinta\nle dijo a la colorada:\n“Si no le van a la Universidad,\nque se vayan a la chingada”.",174,2,9,184,"Estrofa suelta",3,4,"aa",49,0,-1,0,243,243,"9938","",0,"","","",1,0,0,[],""],["frenk_t4-n9939",8,"En un mar de agua salada\nun tejo de oro perdí,\ny nadie podía dar con el tejo,\ny yo con el tejo di.",171,2,4,184,"Estrofa suelta",3,4,"i",23,0,-1,0,243,243,"9939","",0,"","","",1,0,0,[],""],["frenk_t4-n9940",8,"¡Ay, padrotes desgraciados,\ncómo se levantan tarde\ny no tienen compasión\nde su rechingada madre!",175,2,6,184,"El pato’T",0,4,"ae",-1,0,-1,0,243,243,"9940","",0,"","","",1,0,0,[],""],["frenk_t4-n9941",8,"¡Ay, chivas achivarradas,\nhijas del borrego padre!\nYa chingaron a las putas,\nahora chinguen a su madre.",169,2,8,184,"Estrofa suelta",0,4,"ae",166,0,-1,0,243,243,"9941","",0,"","","",1,0,0,[],""],["frenk_t4-n9942",8,"Y en una mesa te puse\nun platón con berenjenas;\nno te lo digo de veras,\ncomo modo de arguenenas.",166,2,-1,184,"El Chúmbale",0,4,"ea",-1,0,-1,0,244,244,"9942","",0,"","","",1,0,0,[],""],["frenk_t4-n9943",8,"En una mesa te puse\nun plato con cuatro elotes;\nno te lo digo de veras,\nno más pa que te alborotes.",169,2,8,184,"Estrofa suelta, El Chúmbale; María, María; Negra del alma; La Sanmarqueña; Soy virgencita; El valiente",0,4,"oe",565,0,-1,0,244,244,"9943","",0,"","","",7,0,0,[],""],["frenk_t4-n9944",8,"Si quieres la vaca,\nvéalo en la vaca;\nvende una vaca\ny cómprate la navaja.",169,2,8,184,"Estrofa suelta",3,4,"aa",-1,0,-1,0,244,244,"9944","",0,"","","",1,0,0,[],""],["frenk_t4-n9946",8,"Me gusta sacar el barco\ncuando le dan borroneado;\nme acuerdo de mi perrito,\nfuchi, que ni vacunado.",166,2,-1,184,"La Sanmarqueña",0,4,"ao",14,0,-1,0,244,244,"9946","",0,"","","",1,0,0,[],""],["frenk_t4-n9947",8,"Anoche estuve soñando\nque le di un beso a la luna,\ny me quedé saboreando,\ncomo aquel que come tuna,\nla boca coloradeando.",171,2,4,184,"El buscapiés",7,5,"ao",33,0,-1,0,244,244,"9947","",0,"","","",1,0,0,[],""],["frenk_t4-n9948",8,"Un saludo a los frijoles,\nmemorias a las tortillas,\nrecuerdos a los totoles\ny un besito a las ardillas.",166,2,-1,184,"Las -—?¡anitas",1,4,"ia",294,0,-1,0,244,244,"9948","",0,"","","",1,0,0,[],""],["frenk_t4-n9949",8,"Te mandan a saludar\nlos tamales en mi panza,\nlo mismo mi paladar:\nquiere echarte a la balanza.",166,2,-1,184,"Las mañanitas",1,4,"aa",163,0,-1,0,245,245,"9949","",0,"","","",1,0,0,[],""],["frenk_t4-n9950",8,"Mi estómago quiere verte,\nmi espinazo quiere queso,\nmi gañote, refrenderte\ny mis huaraches, un beso.",166,2,-1,184,"Las mañanitas",1,4,"eo",48,0,-1,0,245,245,"9950","",0,"","","",1,0,0,[],""],["frenk_t4-n9951",8,"En la punta de aquel cerro\ntengo un nopal sembrado;\ndéjalo que se madure,\ny comeremos chicharrón.",168,2,11,184,"El cateto",5,4,"o",-1,0,-1,0,245,245,"9951","",0,"","","",21,0,0,[],""],["frenk_t4-n9952",8,"El corazón, viejo maula,\nde la barranca al potrero,\nse me escapó de la jaula\nbajo el ala del sombrero.",170,2,7,184,"Camino de Chilpancingo",1,4,"eo",38,0,-1,0,245,245,"9952","",0,"","","",1,0,0,[],""],["frenk_t4-n9953",8,"No es chicle lo que yo masco,\nsino el dolor insepulto;\nla luna nacida en Taxco\nes sirena de Acapulco.",170,2,7,184,"Camino de Chilpancingo",0,4,"uo",-1,0,-1,0,245,245,"9953","",0,"","","",1,0,0,[],""],["frenk_t4-n9954",8,"Del cerro de las cotorras\nvenía bajando un pastor,\nchupándose su cigarro\ny echando chispas de amor.",169,2,8,184,"Estrofa suelta",0,4,"o",72,0,-1,0,245,245,"9954","",0,"","","",1,0,0,[],""],["frenk_t4-n9955",8,"De una muchacha bonita\nsale un muchacho jetón,\ny el macho reparador\nno necesita cuarteta.",177,2,18,184,"El ausente",5,4,"ea",-1,0,-1,0,245,245,"9955","",0,"","","",1,0,0,[],""],["frenk_t4-n9956",8,"Dijo a su novio Teresa:\n“Te odiaré, si al fin compruebo\nque no me hablas con franqueza;\ngallina que bebe huevo\nnunca su rama endereza”.",185,2,13,184,"Estrofa suelta",7,5,"ea",108,0,-1,0,245,245,"9956","",0,"","","",1,0,0,[],""],["frenk_t4-n9957",8,"Arrímate a la azotea,\ny al rato te correspondo;\ny el gato que se le apea,\npobrecito ratoncito..",176,2,3,184,"El ratón",5,4,"io",-1,0,-1,0,245,245,"9957","",0,"","","",1,0,0,[],""],["frenk_t4-n9959",8,"Árboles de la alameda,\nque en la punta tienen flores,\n¿cuándo tendré una peseta\npa comprar cajeta de Celaya?.",168,2,11,184,"El cateto",3,4,"aa",-1,0,-1,0,246,246,"9959","",0,"","","",5,0,0,[],""],["frenk_t4-n9960",8,"La bola rueda para abajo,\nsi no le pone la calza;\ncomo no me gusta el freno,\ntodavía me traen de falsa.",169,2,8,184,"Estrofa suelta",3,4,"aa",639,0,-1,0,246,246,"9960","",0,"","","",1,0,0,[],""],["frenk_t4-n9961",8,"Una zorra en un portal\nle dice a Diéguez:\n¿“Quién le cortaría las hojas (mi vida)?\n¡Ay!, no me niegues”.",176,2,3,184,"El tamarindo",3,4,"ee",640,0,-1,0,246,246,"9961","",0,"","","",1,0,0,[],""],["frenk_t4-n9962",8,"Una vez vide un tejón\ncon un zorrillo peleando;\ny le contestó el león,\nun caballo rucio y pando\ny un potro recién capón,\nque un ciego andaba amansando.",171,2,4,184,"Estrofa suelta",9,6,"ao",33,0,-1,0,246,246,"9962","",0,"","","",1,0,0,[],""],["frenk_t4-ap001-01",8,"—Ticuz, ticuz, ticuz,\nseñora, traigo un ticuz;\n¿quién me lo quiere comprar?\nSe lo vendo, se lo vendo,\naunque sea por un real.",166,2,-1,185,"EL TICUZ",7,5,"a",-1,0,-1,0,250,250,"Ap. 1","",0,"","","",1,0,0,[],""],["frenk_t4-ap001-02",8,"—Quién sabe qué le diré,\nno se lo puedo comprar:\nmi marido es muy celoso,\nno se nos vaya a enojar.",166,2,-1,185,"EL TICUZ",0,4,"a",21,0,-1,0,250,250,"Ap. 1","",0,"","","",1,0,0,[],""],["frenk_t4-ap001-03",8,"—Vale más, vale más, entonces,\nvuelva al puerto de Veracruz,\nsu marido es muy celoso,\nme vuelvo con mi ticuz.",166,2,-1,185,"EL TICUZ",0,4,"u",109,0,-1,0,250,250,"Ap. 1","",0,"","","",1,0,0,[],""],["frenk_t4-ap002-01",8,"—Prometo ser buen marido,\npues tengo mundo y dinero;\ncrea usted que yo la venero,\npues para amarla he nacido,",166,2,-1,185,"UN VIEJO CON UNA NIÑA PARA HACER UN CASAMIENTO",11,4,"io",101,0,-1,0,250,250,"Ap. 2","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap002-02",8,"Ay, será usted muy molesto,\ncosijoso e imprudente,\ny a todo le hará usted el gesto,\nmortificando a la gente,\ny quizá injustamente...",166,2,-1,185,"UN VIEJO CON UNA NIÑA PARA HACER UN CASAMIENTO",7,5,"ee",15,0,-1,0,250,250,"Ap. 2","",0,"","","",1,0,0,[],""],["frenk_t4-ap002-03",8,"Que la maltrate por celo,\n¡ah!, no lo permita el cielo,\npues tal vida he aborrecido,\nquite usted ese desconsuelo,\nprometo ser buen marido.",166,2,-1,185,"UN VIEJO CON UNA NIÑA PARA HACER UN CASAMIENTO",7,5,"io",101,0,-1,0,250,250,"Ap. 2","",0,"","","",1,0,0,[],""],["frenk_t4-ap002-04",8,"¿No padece usted del pecho,\ntos flemática, señor,\ny se recoge en su lecho\na la metida del sel?\nPorque le diré, mi amor...",166,2,-1,185,"UN VIEJO CON UNA NIÑA PARA HACER UN CASAMIENTO",7,5,"o",72,0,-1,0,250,250,"Ap. 2","",0,"","","",1,0,0,[],""],["frenk_t4-ap002-05",8,"Calle, mi bien, yo sospecho\nque usted es algo asquerosa,\npero le diré primero\nque haré en usted limpia esposa,\npues tengo mundo y dinero.",166,2,-1,185,"UN VIEJO CON UNA NIÑA PARA HACER UN CASAMIENTO",7,5,"eo",38,0,-1,0,250,250,"Ap. 2","",0,"","","",1,0,0,[],""],["frenk_t4-ap002-06",8,"Yo contaré, si es así,\ncriados, coche, buen vestido,\ntertulia y buena comida,\ny dinero para mí;\npero me firma usted aquí.",166,2,-1,185,"UN VIEJO CON UNA NIÑA PARA HACER UN CASAMIENTO",7,5,"i",23,0,-1,0,250,250,"Ap. 2","",0,"","","",1,0,0,[],""],["frenk_t4-ap002-07",8,"Que le daré hasta mi vida,\nque la adoro y que la quiero,\nseré su esposo primero\nsi me da gusto, querida;\ncrea usted que yo la venero.",166,2,-1,185,"UN VIEJO CON UNA NIÑA PARA HACER UN CASAMIENTO",7,5,"eo",38,0,-1,0,250,250,"Ap. 2","",0,"","","",1,0,0,[],""],["frenk_t4-ap002-10",8,"O lo adivina, o lo fue\npor su audacia apercibido,\ny siempre las he tenido;\npero las tolera usted,\npues para amarla he nacido.",166,2,-1,185,"UN VIEJO CON UNA NIÑA PARA HACER UN CASAMIENTO",7,5,"io",101,0,-1,0,251,251,"Ap. 2","",0,"","","",1,0,0,[],""],["frenk_t4-ap003-01",8,"—Mariquita de mi vida,\nte están pidiendo, prenda querida,\ntú sabes lo que respondes;\n—Sí, mamá, yo me caso con este hombre.",166,2,-1,185,"MARIQUITA DE MI VIDA",3,4,"oe",-1,0,-1,0,251,251,"Ap. 3","",0,"","","",1,0,0,[],""],["frenk_t4-ap003-02",8,"—Hija de mi vida,\nyo un consejo te he de dar,\nporque este hombre'es muy flojo;\n—Sí, mamá, ya le contesté que es flojo.",166,2,-1,185,"MARIQUITA DE MI VIDA",3,4,"oo",-1,0,-1,0,251,251,"Ap. 3","",0,"","","",7,0,0,[],""],["frenk_t4-ap003-03",8,"—Hija de mi vida,\nyo un consejo te he de dar,\nporque este hombre no tiene ni sombrero;\n—Sí, mamá, es un hombre muy sincero.",166,2,-1,185,"MARIQUITA DE MI VIDA",3,4,"eo",38,0,-1,0,251,251,"Ap. 3","",0,"","","",7,0,0,[],""],["frenk_t4-ap003-04",8,"—Hija de mi vida,\nyo un consejo te he de dar,\nese hombre no tiene ni camisa;\n—Sí, mamá, pero a mí me simpatiza.",166,2,-1,185,"MARIQUITA DE MI VIDA",3,4,"ia",420,0,-1,0,251,251,"Ap. 3","",0,"","","",7,0,0,[],""],["frenk_t4-ap003-05",8,"—Hija de mi vida,\nyo un consejo te he de dar,\nese hombre no tiene ni calzones;\n—Sí, mamá, ya le compré sus pantalones.",166,2,-1,185,"MARIQUITA DE MI VIDA",3,4,"oe",34,0,-1,0,251,251,"Ap. 3","",0,"","","",7,0,0,[],""],["frenk_t4-ap003-06",8,"—Hija de mi vida,\nyo un consejo te he de dar,\nporque ese hombre es jugador;\n—Sí, mamá, pero fue mi primer amor.",166,2,-1,185,"MARIQUITA DE MI VIDA",3,4,"o",72,0,-1,0,251,251,"Ap. 3","",0,"","","",7,0,0,[],""],["frenk_t4-ap003-07",8,"—Hija de mi vida,\nyo un consejo te he de dar,\nporque ese hombre es tan invuelto;\n—Sí, mamá, ya le compré su instrumento.",166,2,-1,185,"MARIQUITA DE MI VIDA",3,4,"eo",-1,0,-1,0,251,251,"Ap. 3","",0,"","","",7,0,0,[],""],["frenk_t4-ap003-08",8,"—Hija de mi vida,\nyo un consejo te he de dar,\npuesto que van a mantearlo;\n—Sí, mamá, déjeme usted que me lleve el diablo.",166,2,-1,185,"MARIQUITA DE MI VIDA",3,4,"ao",-1,0,-1,0,251,251,"Ap. 3","",0,"","","",7,0,0,[],""],["frenk_t4-ap004-01",8,"Hasta cuándo, presumida,\ndejaré de andar penando;\nno más me das esperanzas,\npero no me dices cuándo.",166,2,-1,185,"COMO EL PALO BLANCO",0,4,"ao",33,0,-1,0,251,251,"Ap. 4","",0,"","","",2,0,0,[],""],["frenk_t4-ap004-02",8,"Si es que yo te di esperanzas,\npa qué me andas molestando;\nno por mucho que madrugues\nte amanece más temprano.",166,2,-1,185,"COMO EL PALO BLANCO",0,4,"ao",-1,0,-1,0,251,251,"Ap. 4","",0,"","","",1,0,0,[],""],["frenk_t4-ap004-03",8,"Dime si es que no me quieres\npa no andarme desvelando,\nque mi amor no es gota de agua\npa que se ande serenando.",166,2,-1,185,"COMO EL PALO BLANCO",0,4,"ao",33,0,-1,0,251,251,"Ap. 4","",0,"","","",2,0,0,[],""],["frenk_t4-ap004-04",8,"Si es que te andas desvelando,\na mí no me andes culpando;\neso pones de pretexto\npara andarte parrandeando.",166,2,-1,185,"COMO EL PALO BLANCO",0,4,"ao",33,0,-1,0,251,251,"Ap. 4","",0,"","","",1,0,0,[],""],["frenk_t4-ap004-05",8,"Ya te conocí muy bien,\neres como el palo blanco:\nnunca en la vida florece,\nno más ocupando el campo,",166,2,-1,185,"COMO EL PALO BLANCO",0,4,"ao",-1,0,-1,0,251,251,"Ap. 4","",0,"","","",2,0,0,[],""],["frenk_t4-ap004-06",8,"Si soy como el palo blanco,\n¿para qué lo andas contando?\nNo te vayas a quedar\ncomo campana sonando.",166,2,-1,185,"COMO EL PALO BLANCO",0,4,"ao",33,0,-1,0,251,251,"Ap. 4","",0,"","","",1,0,0,[],""],["frenk_t4-ap004-07",8,"Si porque eres muy bonita,\ncrees que te he de andar rogando;\nsi tu brazos me desprecian,\notros me están esperando.",166,2,-1,185,"COMO EL PALO BLANCO",0,4,"ao",33,0,-1,0,251,251,"Ap. 4","",0,"","","",2,0,0,[],""],["frenk_t4-ap004-08",8,"Si te esperan otros brazos,\nno creas que voy a llorar,\npues estás equivocado;\nya tengo otro en tu lugar.",166,2,-1,185,"COMO EL PALO BLANCO",0,4,"a",21,0,-1,0,251,251,"Ap. 4","",0,"","","",1,0,0,[],""],["frenk_t4-ap005-01",8,"Ya llegó el guapo del barrio,\nviene repartiendo plata;\nla pobreza la he dejado\ncolgada en una alcayata.",166,2,-1,185,"EL GUAPO",0,4,"aa",74,0,-1,0,252,252,"Ap. 5","",0,"","","",1,0,0,[],""],["frenk_t4-ap005-02",8,"Dices que eres guapo y rico,\n¿no será que te ha hecho daño\nel eclipse y el menguante,\no las heladas de este año?",166,2,-1,185,"EL GUAPO",0,4,"ao",40,0,-1,0,252,252,"Ap. 5","",0,"","","",1,0,0,[],""],["frenk_t4-ap005-03",8,"Por fuerita me maldices\ny por dentro me apapachas;\npor mi amor y por mis besos\nandas que te deshilachas.",166,2,-1,185,"EL GUAPO",0,4,"aa",589,0,-1,0,252,252,"Ap. 5","",0,"","","",1,0,0,[],""],["frenk_t4-ap005-04",8,"No te azotes, rabo verde,\nni te embarres tanta crema;\nme andas haciendo la rueda\nporque quieres cosa buena.",166,2,-1,185,"EL GUAPO",0,4,"ea",-1,0,-1,0,252,252,"Ap. 5","",0,"","","",1,0,0,[],""],["frenk_t4-ap005-05",8,"De cualquier modo que le hagas,\nconmigo sales perdiendo;\nhasta se te cae la baba\ny el dedo te estás lambiendo.",166,2,-1,185,"EL GUAPO",0,4,"eo",52,0,-1,0,252,252,"Ap. 5","",0,"","","",1,0,0,[],""],["frenk_t4-ap005-06",8,"Ya estás viejo pa esta polla,\nse oyen roncos tus bramidos;\naunque te mueras de rabia,\nno eres de mis escogidos.",166,2,-1,185,"EL GUAPO",0,4,"io",255,0,-1,0,252,252,"Ap. 5","",0,"","","",1,0,0,[],""],["frenk_t4-ap006-01",8,"Ya me canso de rogarte,\npero tú ni me haces caso;\nyo con ansias de ser tuyo,\ntú negándome tus brazos.",166,2,-1,185,"LA CHACHARERA",0,4,"ao",-1,0,-1,0,252,252,"Ap. 6","",0,"","","",1,0,0,[],""],["frenk_t4-ap006-02",8,"Cómo quieres que te quiera\nsi eres vago y bien borracho,\nte hacen falta pantalones\npara ser un hombre macho.",166,2,-1,185,"LA CHACHARERA",0,4,"ao",310,0,-1,0,252,252,"Ap. 6","",0,"","","",16,0,0,[],""],["frenk_t4-ap006-03",8,"Eso sí que me calienta,\nchacharera de Tepito,\nte vives transando gente\nen tu mugre puestecito.",166,2,-1,185,"LA CHACHARERA",0,4,"io",119,0,-1,0,252,252,"Ap. 6","",0,"","","",1,0,0,[],""],["frenk_t4-ap006-04",8,"Yo seré una chacharera,\npero no me muero de hambre;\ntú ya eres puro pellejo,\nborrachito miserable.",166,2,-1,185,"LA CHACHARERA",0,4,"ae",-1,0,-1,0,252,252,"Ap. 6","",0,"","","",1,0,0,[],""],["frenk_t4-ap006-05",8,"Para ti seré borracho,\npero a mí me sobran hembras;\nme verás en otros brazos\nnada'más para que aprendas.",166,2,-1,185,"LA CHACHARERA",0,4,"ea",-1,0,-1,0,252,252,"Ap. 6","",0,"","","",1,0,0,[],""],["frenk_t4-ap006-06",8,"Vive, vive como quieras,\neso y más, me importa poco,\nno te falta naditita\npara convertirte en loco.",166,2,-1,185,"LA CHACHARERA",0,4,"oo",152,0,-1,0,252,252,"Ap. 6","",0,"","","",1,0,0,[],""],["frenk_t4-ap007-01",8,"Tú te fijas porque me emborracho,\nporque paso mi vida tomando;\ntú también te pascas con los hombres,\nno dirás que yo te ando celando.",166,2,-1,185,"EL DESCALZO",3,4,"ao",33,0,-1,0,252,252,"Ap. 7","",0,"","","",1,0,0,[],""],["frenk_t4-ap007-03",8,"Cuando salgo a la calle, y te encuentro,\nte saludo y ni me hablas siquiera,\npresumiendo porque eres bonita,\nporque todos te dan tu madera.",166,2,-1,185,"EL DESCALZO",3,4,"ea",44,0,-1,0,252,252,"Ap. 7","",0,"","","",1,0,0,[],""],["frenk_t4-ap007-04",8,"Cuando salgo a la calle me encuentras,\nme saludas y no te hago caso;\nque en los años que tengo de vida,\nnunca he visto otro bato tan gacho.",166,2,-1,185,"EL DESCALZO",3,4,"ao",-1,0,-1,0,252,252,"Ap. 7","",0,"","","",1,0,0,[],""],["frenk_t4-ap007-05",8,"Yo quisiera ser hombre de bienes\ny tener un montón de dinero\npa quitarte ese bato que tienes\ny mandarlo descalzo a Laredo.",166,2,-1,185,"EL DESCALZO",3,4,"eo",-1,0,-1,0,253,253,"Ap. 7","",0,"","","",1,0,0,[],""],["frenk_t4-ap007-06",8,"Tú quisieras mandar pa Laredo\nal que gasta todos mis tostones;\npara cuando lo mires descalzo\nes que tú ya no traes ni calzones.",166,2,-1,185,"EL DESCALZO",3,4,"oe",34,0,-1,0,253,253,"Ap. 7","",0,"","","",1,0,0,[],""],["frenk_t4-ap007-07",8,"Por áhi dicen que tú todo sabes,\npor áhi dicen que todo compones,\nque tu casa parece un juzgado\ndonde entran y salen los hombres.",166,2,-1,185,"EL DESCALZO",3,4,"oe",-1,0,-1,0,253,253,"Ap. 7","",0,"","","",1,0,0,[],""],["frenk_t4-ap007-08",8,"Ese hombre que tengo y que quiero,\nno te pide ni una gota de aire;\na los perros les dan su comida\nen la boca para que no ladren.",166,2,-1,185,"EL DESCALZO",3,4,"ae",-1,0,-1,0,253,253,"Ap. 7","",0,"","","",1,0,0,[],""],["frenk_t4-ap008-01",8,"¿Qué te pasa, Nicolasa?,\nte has hecho muy presumida;\n¿te acuerdas que allá en tu casa\nno querías ni ver pa arriba?",166,2,-1,185,"LA NICOLASA",0,4,"ia",-1,0,-1,0,253,253,"Ap. 8","",0,"","","",1,0,0,[],""],["frenk_t4-ap008-02",8,"Si yo ando muy arreglada,\nmi dinero me ha costado,\npero tú andas de parada\ncon la ropa que te han dado.",166,2,-1,185,"LA NICOLASA",1,4,"ao",14,0,-1,0,253,253,"Ap. 8","",0,"","","",1,0,0,[],""],["frenk_t4-ap008-03",8,"Te miras rete vaciada\ncontoneando la cadera;\n¿te acuerdas cuando cuidabas\nlas chivas en la ladera?",166,2,-1,185,"LA NICOLASA",0,4,"ea",44,0,-1,0,253,253,"Ap. 8","",0,"","","",1,0,0,[],""],["frenk_t4-ap008-04",8,"Las chivas que yo cuidaba\nme las regaló mi madre;\nlas vacas que tú ordeñabas\nse las robaba tu padre.",166,2,-1,185,"LA NICOLASA",0,4,"ae",166,0,-1,0,253,253,"Ap. 8","",0,"","","",1,0,0,[],""],["frenk_t4-ap008-05",8,"Dices que ya no me quieres\nporque tengo poca lana;\nsi en verdad no me prefieres,\nrecomiéndame a tu hermana.",166,2,-1,185,"LA NICOLASA",1,4,"aa",4,0,-1,0,253,253,"Ap. 8","",0,"","","",21,0,0,[],""],["frenk_t4-ap008-06",8,"¡Qué poca vergüenza tienes,\nholgazán y descarado!,\nni tú solo te mantienes\ny quieres ser mi cuñado.",166,2,-1,185,"LA NICOLASA",1,4,"ao",14,0,-1,0,253,253,"Ap. 8","",0,"","","",1,0,0,[],""],["frenk_t4-ap009-01",8,"Hoy me sales presumiendo\ncon falditas de catrina,\ny pa que te vea la gente\nvas y vienes a la esquina;\nse ve que donde trabajas\nte aflojan buena propina.",166,2,-1,185,"LA CATRINA POBRE",9,6,"ia",11,0,-1,0,253,253,"Ap. 9","",0,"","","",1,0,0,[],""],["frenk_t4-ap009-02",8,"Esas faldas que tú dices\nque compré con mis propinas,\nme las ha comprado un hombre\nque pagó con plata fina,\nese sí es hombre de trabajo\ny no vicioso de cantina.",166,2,-1,185,"LA CATRINA POBRE",9,6,"ia",11,0,-1,0,253,253,"Ap. 9","",0,"","","",1,0,0,[],""],["frenk_t4-ap009-03",8,"Soy vicioso de cantina\nporque me sobra el dinero,\náhi te van tres de a cincuenta,\npágale algo al abonero;\nsi en verdad tienes un hombre,\ndile que no sea droguero.",166,2,-1,185,"LA CATRINA POBRE",9,6,"eo",38,0,-1,0,253,253,"Ap. 9","",0,"","","",1,0,0,[],""],["frenk_t4-ap009-04",8,"Yo no sé por qué hoy me sales\ncon dinero y pantalones;\nsi eres indio de huaraches\nque te asustan los camiones;\nguárdate tus tres centavos\npa que cures tus ardores.",166,2,-1,185,"LA CATRINA POBRE",9,6,"oe",-1,0,-1,0,253,253,"Ap. 9","",0,"","","",1,0,0,[],""],["frenk_t4-ap009-05",8,"Ya estarás, catrina pobre,\nya me diste mil cortones;\ntú en la calle presumiendo\ny en tu casa sin frijoles;\nde comer te ofrezco un plato\npor si todavía no comes.",166,2,-1,185,"LA CATRINA POBRE",9,6,"oe",-1,0,-1,0,253,253,"Ap. 9","",0,"","","",1,0,0,[],""],["frenk_t4-ap009-06",8,"Indio prieto y calzonudo,\nya el alcohol te tiene loco;\nya quisieras tostaditas\npara reponerte un poco,\npero no tienes pa carne,\nni para chiles tampoco.",166,2,-1,185,"LA CATRINA POBRE",9,6,"oo",152,0,-1,0,253,253,"Ap. 9","",0,"","","",1,0,0,[],""],["frenk_t4-ap010-01",8,"Qué milagro, paisanita,\nya tenía ganas de verte;\ndesde que chambeas de gata\ndices que cambió tu suerte,\nentreteniendo a los niños\npara poder mantenerte.",166,2,-1,185,"LA BRUJA DE RANCHO",9,6,"ee",134,0,-1,0,254,254,"Ap. 10","",0,"","","",1,0,0,[],""],["frenk_t4-ap010-02",8,"Dices que eres mi paisano,\npero yo ni te conozco;\nsi yo trabajo de gata,\neso te importa muy poco;\nes más, ya te recordé,\nte decían “El burro cojo”.",166,2,-1,185,"LA BRUJA DE RANCHO",9,6,"oo",-1,0,-1,0,254,254,"Ap. 10","",0,"","","",1,0,0,[],""],["frenk_t4-ap010-03",8,"Paisana, bruja orgullosa,\n¿no que no me conocías?;\nya ni rastro de las chapas\nque antes tan lindas tenías;\nusas pintura a montones,\npareces perfumería.",166,2,-1,185,"LA BRUJA DE RANCHO",9,6,"ia",-1,0,-1,0,254,254,"Ap. 10","",0,"","","",1,0,0,[],""],["frenk_t4-ap010-04",8,"Si me pinto y me perfumo,\nno te importa, es cosa mía,\nlos compro con mi dinero\ny a mí nadie me los fía;\npues tú apestas a zorrillo,\nya ni hables, calcomanía.",166,2,-1,185,"LA BRUJA DE RANCHO",9,6,"ia",0,0,-1,0,254,254,"Ap. 10","",0,"","","",1,0,0,[],""],["frenk_t4-ap010-05",8,"Tú, todo lo que te pones,\nlo robaste a la patrona;\ny de los niños que cuidas,\nuno es nuestro hijo, paloma;\n¿te acuerdas cuando me amabas\ny que andabas de rogona?",166,2,-1,185,"LA BRUJA DE RANCHO",9,6,"oa",-1,0,-1,0,254,254,"Ap. 10","",0,"","","",1,0,0,[],""],["frenk_t4-ap010-06",8,"Ya no me levantes falsos,\nya deja de molestar;\nse me agotó la paciencia,\ncaro lo vas a pagar,\nrebuznarás como burro\nporque te voy a embrujar.",166,2,-1,185,"LA BRUJA DE RANCHO",9,6,"a",21,0,-1,0,254,254,"Ap. 10","",0,"","","",1,0,0,[],""],["frenk_t4-ap011-01",8,"Tú te alegras de ser tan bonita\ny te burlas de los corazones,\ny pareces una maquinita\narrastrando un montón de furgones.",166,2,-1,185,"LA MAQUINITA VACILADORA",3,4,"oe",34,0,-1,0,254,254,"Ap. 11","",0,"","","",1,0,0,[],""],["frenk_t4-ap011-02",8,"Yo te miro pasear orgullosa\nporque todos te ofrecen dinero;\nte pusistes el nombre de Rosa\ny te llamas Cristina Romero.",166,2,-1,185,"LA MAQUINITA VACILADORA",3,4,"eo",38,0,-1,0,254,254,"Ap. 11","",0,"","","",1,0,0,[],""],["frenk_t4-ap011-03",8,"Yo hace tiempo conozco a tus padres,\ny hasta tuve de novio a tu hermano;\ny contigo no quise aventarme\nporque entonces estabas tomado.",166,2,-1,185,"LA MAQUINITA VACILADORA",3,4,"ao",-1,0,-1,0,254,254,"Ap. 11","",0,"","","",1,0,0,[],""],["frenk_t4-ap011-05",8,"Yo no soy quien el sueño te quita,\nporque siempre al mirarme te escondes;\ntú te vives de día muy santita\ny de noche jalando a los hombres.",166,2,-1,185,"LA MAQUINITA VACILADORA",3,4,"oe",-1,0,-1,0,254,254,"Ap. 11","",0,"","","",1,0,0,[],""],["frenk_t4-ap011-06",8,"Tú dirás que tu vida es tu vida,\nmaquinita que vas tan volada;\ncon la carga que llevas encima\nte he de ver, con el tiempo, chocada.",166,2,-1,185,"LA MAQUINITA VACILADORA",3,4,"aa",49,0,-1,0,254,254,"Ap. 11","",0,"","","",1,0,0,[],""],["frenk_t4-ap011-07",8,"Tú me dices que soy maquinita\nporque sabes que ya no te quiero;\ncomo ya tengo mi maquinista\nno me sirves ni pa garrotero.",166,2,-1,185,"LA MAQUINITA VACILADORA",3,4,"eo",38,0,-1,0,254,254,"Ap. 11","",0,"","","",1,0,0,[],""],["frenk_t4-ap011-08",8,"Como tú andas borracho y volado,\nmuy atrás de mi vida quedaste;\nel furgón que se queda atrasado\nya no vuelve en mi vida a engancharse.",166,2,-1,185,"LA MAQUINITA VACILADORA",3,4,"ae",-1,0,-1,0,254,254,"Ap. 11","",0,"","","",1,0,0,[],""],["frenk_t4-ap012-01",8,"Ahora sí, vieja escalera,\nya subí tus escalones;\npuede subir el que quiera\na gozar de tus amores.",166,2,-1,185,"LA VIEJA ESCALERA",0,4,"oe",-1,0,-1,0,255,255,"Ap. 12","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap012-02",8,"Dices que soy escalera\ny que por ella subiste;\neso es lo que tú deseabas\ny nunca lo conseguistes.",166,2,-1,185,"LA VIEJA ESCALERA",0,4,"ie",-1,0,-1,0,255,255,"Ap. 12","",0,"","","",2,0,0,[],""],["frenk_t4-ap012-03",8,"Si porque te vengo a ver\ncrees que te vengo a rogar,\nno más vine a conocer\nal que ocupa mi lugar.",166,2,-1,185,"LA VIEJA ESCALERA",1,4,"a",21,0,-1,0,255,255,"Ap. 12","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap012-04",8,"Te voy a dar un retrato\ndel que ocupa tu lugar;\nacuérdate que es tu padre,\nlo tienes que respetar.",166,2,-1,185,"LA VIEJA ESCALERA",0,4,"a",21,0,-1,0,255,255,"Ap. 12","",0,"","","",2,0,0,[],""],["frenk_t4-ap012-05",8,"Si en antes yo te rogaba\nera porque te quería,\npero quedaste borrada\nde mi lista, vida mía.",166,2,-1,185,"LA VIEJA ESCALERA",0,4,"ia",0,0,-1,0,255,255,"Ap. 12","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap012-06",8,"Siempre vienes a rogarme\ncuando me vienes a ver,\na ver si tengo dinero\npa poderte mantener,",166,2,-1,185,"LA VIEJA ESCALERA",0,4,"e",20,0,-1,0,255,255,"Ap. 12","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap012-07",8,"Voy a comprarte un gallito\nde esos que ya cantan tarde,\npara enseñar al maldito\na ser hombre y no cobarde,",166,2,-1,185,"LA VIEJA ESCALERA",1,4,"ae",344,0,-1,0,255,255,"Ap. 12","",0,"","","",2,0,0,[],""],["frenk_t4-ap012-08",8,"El gallito que me compres\nme lo compras a mi gusto,\npa cuando me veas con él\nque no te mueras del susto.",166,2,-1,185,"LA VIEJA ESCALERA",0,4,"uo",497,0,-1,0,255,255,"Ap. 12","",0,"","","",1,0,0,[],""],["frenk_t4-ap014-01",8,"¡Qué bonita chaparrita,\nse me hace que me la llevo;\naquí traigo veinte pesos,\ny a ninguno se los debo;\na agarrarla yo me atrevo,\npues al fin traigo con qué;\n¿qué dices, chatita mía,\nno gustas ir al café,\nal teatro, a la nevería?,\nyo todo te pagaré.",166,2,-1,185,"QUÉ BONITA CHAPARRITA",18,10,"e",77,0,-1,0,256,256,"Ap. 14","",0,"","","",5,0,0,[],""],["frenk_t4-ap014-02",8,"Borracho tan atrevido,\nmajadero inconsecuente,\nlargúese de aquí, le digo,\nque apesta mucho a aguardiente;\nyo soy novia de un decente,\ny usted está muy pelado;\nno tiene para cobija,\npero anda de enamorado.\nVoy a llamar al gendarme,\nsi no se va de mi lado.",166,2,-1,185,"QUÉ BONITA CHAPARRITA",18,10,"ao",14,0,-1,0,256,256,"Ap. 14","",0,"","","",2,0,0,[],""],["frenk_t4-ap014-03",8,"Ya me ve que estoy pelado,\npero a ninguno le pido\ny no crea que son mentiras,\nno más escuche el sonido:\nmás dinero que un bandido\ntraigo para disparar,\ny todito ha de ser suyo,\nno más déjese agarrar,\nque se le acabe el orgullo\ny nos vamos a pasear.",166,2,-1,185,"QUÉ BONITA CHAPARRITA",18,10,"a",21,0,-1,0,256,256,"Ap. 14","",0,"","","",1,0,0,[],""],["frenk_t4-ap014-04",8,"Borracho tan atrevido,\npues no le digo que no,\nque se largue de mi lado,\no está sordo o no lo oyó.",166,2,-1,185,"QUÉ BONITA CHAPARRITA",0,4,"o",2,0,-1,0,256,256,"Ap. 14","",0,"","","",2,0,0,[],""],["frenk_t4-ap014-05",8,"Que hasta me avergüenzo yo\nque me venga usted siguiendo,\nporque sus garras de hilachas\nde piojos vienen hirviendo,\ny así es que yo ya le dije:\nprontito váyase yendo.",166,2,-1,185,"QUÉ BONITA CHAPARRITA",9,6,"eo",52,0,-1,0,256,256,"Ap. 14","",0,"","","",1,0,0,[],""],["frenk_t4-ap014-06",8,"Mire, linda morenita,\npues yo no la he de olvidar,\nsi me corresponde a mí,\n¡horita voy a estrenar 1;\ndéjeme ir a rasurar,\nque no soy mal parecido;\nllévese estos cinco pesos\npor lo que la he entretenido;\nme voy con el sentimiento\nde no ser correspondido.",166,2,-1,185,"QUÉ BONITA CHAPARRITA",18,10,"io",101,0,-1,0,256,256,"Ap. 14","",0,"","","",1,0,0,[],""],["frenk_t4-ap014-07",8,"Mire, le daré un consejo,\ndéjelos para su copa\no mejor cómprese ropa,\ncachirul y un barboquejo;\ndespués mírese al espejo;\nle diré dónde hay barata,\nsi gusta, lo llevaré,\nno diga que soy ingrata,\nni crea que por interési\nporque le miré su plata.",166,2,-1,185,"QUÉ BONITA CHAPARRITA",18,10,"aa",74,0,-1,0,256,256,"Ap. 14","",0,"","","",1,0,0,[],""],["frenk_t4-ap014-08",8,"Pues se tomaron del guante\ny se fueron al cajón,\nse tomaron sus taquitos\ny dieron su resbalón.\nCuando salieron de allí\ncon tan grande papalina,\nque los tuvo que llevar\nel gendarme de la esquina,\ny amanecieron muy crudos\ndentro de una bartolina.",166,2,-1,185,"QUÉ BONITA CHAPARRITA",18,10,"ia",11,0,-1,0,256,256,"Ap. 14","",0,"","","",1,0,0,[],""],["frenk_t4-ap015-01",8,"Gran escándalo y alarma\nhay en este matrimonio,\nel hombre de rigor se arma\ny la mujer, del demonio,\nporque llora, chilla y brama\ncomo los del manicomio.",166,2,-1,185,"CORRIDO DE CASADOS",9,6,"oo",-1,0,-1,0,257,257,"Ap. 15","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap015-02",8,"Ya me tienes aburrido,\nmujer sucia y asquerosa;\nno digas que eres mi esposa,\nni que yo fui tu marido;\nte sepulto en el olvido,\nbien me lo puedes creer;\nya mi esposa no has de ser,\npor más pucheros que hagas;\neres cual las chintatlahuas\npor tu infame proceder.",166,2,-1,185,"CORRIDO DE CASADOS",18,10,"e",20,0,-1,0,257,257,"Ap. 15","",0,"","","",1,0,0,[],""],["frenk_t4-ap015-03",8,"Pues si tal cosa me dices,\n¿yo qué te podré decir,\ncuando no puedo sufrir\nlo mucho que me maldices?\nTú eres de los infelices\nque buscan mujer de gorra;\nya puedes irte a la porra,\nyo para nada te quiero;\ncon la mano en el trasero\nve a buscar otra cotorra.",166,2,-1,185,"CORRIDO DE CASADOS",18,10,"oa",461,0,-1,0,257,257,"Ap. 15","",0,"","","",1,0,0,[],""],["frenk_t4-ap016-01",8,"Estaba sentado un payo\nen las trancas de un corral,\ny el mayordomo le dice:\n—No estés triste, Nicolás.",166,2,-1,185,"EL PAYO",0,4,"a",-1,0,-1,0,257,257,"Ap. 16","",0,"","","",1,0,0,[],""],["frenk_t4-ap016-02",8,"—Si quieres que no esté triste,\nlo que pida me has de dar.\nY el mayordomo le dice:\n—Ve pidiendo, Nicolás.",166,2,-1,185,"EL PAYO",0,4,"a",-1,0,-1,0,257,257,"Ap. 16","",0,"","","",2,0,0,[],""],["frenk_t4-ap016-03",8,"—Necesito treinta pesos,\nuna cuera y un gabán.\nY el mayordomo le dice:\n—No hay dinero, Nicolás.",166,2,-1,185,"EL PAYO",0,4,"a",-1,0,-1,0,257,257,"Ap. 16","",0,"","","",1,0,0,[],""],["frenk_t4-ap016-04",8,"—Necesito treinta reales\npara poderme casar.\nY el mayordomo le dice:\n—Ni un real tengo, Nicolás.",166,2,-1,185,"EL PAYO",0,4,"a",-1,0,-1,0,257,257,"Ap. 16","",0,"","","",1,0,0,[],""],["frenk_t4-ap016-05",8,"—Necesito de mi china\npara poderme casar.\nY el mayordomo le dice:\n—Tiene dueño, Nicolás.",166,2,-1,185,"EL PAYO",0,4,"a",-1,0,-1,0,257,257,"Ap. 16","",0,"","","",1,0,0,[],""],["frenk_t4-ap016-06",8,"El payo, desesperado,\nun cuchillo fue a sacar.\nY el mayordomo le dice:\n—Date fuerte, Nicolás.",166,2,-1,185,"EL PAYO",0,4,"a",-1,0,-1,0,257,257,"Ap. 16","",0,"","","",2,0,0,[],""],["frenk_t4-ap016-07",8,"El payo, desesperado,\na un barranco se iba a echar.\nY el mayordomo le dice:\n—De cabeza, Nicolás.",166,2,-1,185,"EL PAYO",0,4,"a",-1,0,-1,0,257,257,"Ap. 16","",0,"","","",2,0,0,[],""],["frenk_t4-ap017-01",8,"Mi hijo se casó,\nya tiene mujer;\nmañana veremos\nlo que sabe hacer.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"e",20,0,-1,0,258,258,"Ap. 17","",0,"","","",1,0,0,[],""],["frenk_t4-ap017-02",8,"Levántate, mi alma,\ncomo es de costumbre:\nlavar tu brasero\ny poner la lumbre.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"ue",181,0,-1,0,258,258,"Ap. 17","",0,"","","",1,0,0,[],""],["frenk_t4-ap017-03",8,"Yo no me casé\npara trabajar,\nsi en mi casa tengo\ncriados que mandar.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"a",21,0,-1,0,258,258,"Ap. 17","",0,"","","",1,0,0,[],""],["frenk_t4-ap017-04",8,"¡Demonio de nueral,\n¿pues qué sabe hacer?\nCoja usted la escoba,\npóngase a barrer.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"e",20,0,-1,0,258,258,"Ap. 17","",0,"","","",1,0,0,[],""],["frenk_t4-ap017-05",8,"¡Demonio de viejal,\n¿por qué me regaña?\nEl diablo se pare en\nsus sucias marañas.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"aa",-1,0,-1,0,258,258,"Ap. 17","",0,"","","",1,0,0,[],""],["frenk_t4-ap017-06",8,"¡Demonio de nuera!,\n¿pues qué sabe hacer?\nCoja usted la aguja,\npóngase a coser.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"e",20,0,-1,0,258,258,"Ap. 17","",0,"","","",1,0,0,[],""],["frenk_t4-ap017-07",8,"¡Demonio de vieja!,\n¿por qué me maldice?\nEl diablo se pare en\nsus sucias narices.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"ie",-1,0,-1,0,258,258,"Ap. 17","",0,"","","",1,0,0,[],""],["frenk_t4-ap017-08",8,"Yo quise a mi nuera,\nla quise y la adoro,\npor verla sentada en\nlas llaves de un toro.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"oo",85,0,-1,0,258,258,"Ap. 17","",0,"","","",1,0,0,[],""],["frenk_t4-ap017-09",8,"Yo quise a mi suegra,\nla quise y la quiero,\npor verla sentada\nen un hormiguero.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"eo",38,0,-1,0,258,258,"Ap. 17","",0,"","","",1,0,0,[],""],["frenk_t4-ap017-10",8,"¡Ay, ay, ay, ay, ay!,\nque me haces llorar\ncon los malos ratos\nque me haces pasar.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"a",21,0,-1,0,258,258,"Ap. 17","",0,"","","",6,0,0,[],""],["frenk_t4-ap017-11",8,"¡Ay, ay, ay, ay, ay!,\nque me hacen llorar\nlas ingratitudes\nque me hacen pasar.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"a",21,0,-1,0,258,258,"Ap. 17","",0,"","","",6,0,0,[],""],["frenk_t4-ap017-12",8,"¡Ay, hijo de mi alma,\nmira a tu mujer!,\nllévala al infierno,\nno la puedo ver.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"e",20,0,-1,0,258,258,"Ap. 17","",0,"","","",1,0,0,[],""],["frenk_t4-ap017-13",8,"¡Ay, madre del alma,\ncállese por Dios!,\nque yo ya me canso\nde oír a las dos.",168,2,11,185,"LA SUEGRA Y LA NUERA I",0,4,"o",-1,0,-1,0,258,258,"Ap. 17","",0,"","","",1,0,0,[],""],["frenk_t4-ap018-02",8,"Tengo de hacer una casa\nmás allá de los infiernos,\npara meter a las suegras\nque se pelean con los yernos.",166,2,-1,185,"SUEGROS, PADRASTROS, CUÑADOS",0,4,"eo",634,0,-1,0,258,258,"Ap. 18","",0,"","","",1,0,0,[],""],["frenk_t4-ap018-04",8,"Dime, yerno sin razón,\n¿cuándo intentas trabajar?\nA mi hija me has de entregar\nporque no duerme en colchón.",166,2,-1,185,"SUEGROS, PADRASTROS, CUÑADOS",11,4,"o",31,0,-1,0,259,259,"Ap. 18","",0,"","","",1,0,0,[],""],["frenk_t4-ap018-05",8,"Dime, yerno, ¿por qué a mi hija\nla tienes abandonada?,\nmuy mugrienta y desgarrada\nestá porque eres sortija:\nmuy cierta, segura y fija\nestoy de tal sinrazón,\npues ni leña ni carbón\nle das tú por su consuelo;\nmi hija durmiendo en el suelo\nporque otra duerma en colchón.",166,2,-1,185,"SUEGROS, PADRASTROS, CUÑADOS",18,10,"o",31,0,-1,0,259,259,"Ap. 18","",0,"","","",1,0,0,[],""],["frenk_t4-ap018-06",8,"No se meta en lo excusado\nni en cosa que no le importa;\nsi su argumento no corta\nyo le quito lo arrastrado;\nya bastante me ha injuriado\ny me está descreditando,\nmucho, mucho ha andado hablando\ncon las viejas donde quiera,\ny el de ser chirinolera\ndejará de serlo... ¡Cuándo!",166,2,-1,185,"SUEGROS, PADRASTROS, CUÑADOS",18,10,"ao",33,0,-1,0,259,259,"Ap. 18","",0,"","","",1,0,0,[],""],["frenk_t4-ap018-07",8,"Usted me está provocando,\ncanalla de chicharrita;\ny de ser linda alhajita\ndejará de serlo... ¡Cuándo!",166,2,-1,185,"SUEGROS, PADRASTROS, CUÑADOS",11,4,"ao",33,0,-1,0,259,259,"Ap. 18","",0,"","","",1,0,0,[],""],["frenk_t4-ap018-08",8,"Yo no soy chirinolera;\na mi hija me has de entregar\ny al grillete has de ir a dar\nsin tener ninguna espera;\nhombre, atiende y considera,\nque mi hija tiene un torzón\nde hambre y mal de corazón\nsin tomar su chocolate;\nmi hija duerme en un petate\nporque otra duerma en colchón.",166,2,-1,185,"SUEGROS, PADRASTROS, CUÑADOS",18,10,"o",31,0,-1,0,259,259,"Ap. 18","",0,"","","",1,0,0,[],""],["frenk_t4-ap018-09",8,"Se dará mayor soflama\nde aquesta vieja embustera;\n¿no atiende ni considera\nque ultraja mi honor y fama?\nYo le tengo buena cama,\na mi esposa estoy amando,\ny mi suegra perturbando,\na mi estado lo destroza,\ny lombriz escandalosa\ndejará de serlo... ¡Cuándo!",166,2,-1,185,"SUEGROS, PADRASTROS, CUÑADOS",18,10,"ao",33,0,-1,0,259,259,"Ap. 18","",0,"","","",1,0,0,[],""],["frenk_t4-ap018-10",8,"Ya mi hija me ha dicho así:\nque la pretende otro amante\nporque tú eres inconstante,\nbastante se queja a mí:\ncuando yo te la ofrecí\ny te hice tal donación\nte tanteé buen corazón;\npero tú eres muy celoso\ny mi hija está sin rebozo\nporque otra duerma en colchón.",166,2,-1,185,"SUEGROS, PADRASTROS, CUÑADOS",18,10,"o",31,0,-1,0,259,259,"Ap. 18","",0,"","","",1,0,0,[],""],["frenk_t4-ap018-11",8,"Con razón me la ha pedido\npara salir a pasearse;\nya usted empieza a declararse\ny yo soy muy entendido;\npero ya no estoy engreído,\nsegún lo que estoy mirando,\nmis manzanas me están dando;\nusted es la más causante,\nvieja huesos de gigante\ndejará de serlo... ¡Cuándo!",166,2,-1,185,"SUEGROS, PADRASTROS, CUÑADOS",18,10,"ao",33,0,-1,0,259,259,"Ap. 18","",0,"","","",1,0,0,[],""],["frenk_t4-ap018-12",8,"A la cuerda hás de ir a dar\na padecer sin consuelo,\nporque no nos das dinero\ny de mí te has de acordar;\nbien te puedes amolar,\ncara de chango capón,\npanza de buen barrigón,\nmugriento más que un velero;\nmi hija vive en un chiquero\nporque otra duerma en colchón.",166,2,-1,185,"SUEGROS, PADRASTROS, CUÑADOS",18,10,"o",31,0,-1,0,259,259,"Ap. 18","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-01",8,"—Bienvenido, alvaradeño,\na esta bella Tlacotalpan,\na la que le llaman todos\nla perla del Papaloapan.",166,2,-1,185,"PUGNA JAROCHA",0,4,"aa",-1,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-02",8,"—No empiecen a presumir,\npues pa qué me han invitado;\nno he venido a discutir\nla paz que tanto han deseado.",166,2,-1,185,"PUGNA JAROCHA",1,4,"ao",14,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-03",8,"—Yo no creo sea presumir\nel que ustedes reconozcan\nque donde acaban de venir\nes la tierra más hermosa.",166,2,-1,185,"PUGNA JAROCHA",3,4,"oa",-1,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-04",8,"—Es un pueblo pasadero\nde esos que por ahí hay muchos;\npero en cambio mi Alvarado\nes cuna de los jarochos.",166,2,-1,185,"PUGNA JAROCHA",5,4,"oo",-1,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-05",8,"—¿De qué tierra tú me hablas?,\nserá para tus arenales;\ncuánto darían por tener\nnuestros antiguos portales.",166,2,-1,185,"PUGNA JAROCHA",0,4,"ae",26,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-06",8,"—¿Para esto me invitastes,\npara empezarme a picar?,\ngracias a que hay mucha gente\nno te puedo contestar.",166,2,-1,185,"PUGNA JAROCHA",0,4,"a",21,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-07",8,"—No me extrañaría nada\nque empezaras a insultar,\npues no en balde tienes fama\nde ser rey del mal hablar.",166,2,-1,185,"PUGNA JAROCHA",0,4,"a",21,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-09",8,"En nombre del cielo\nos pido posada,\npues no puede andar\nmi esposa amada.",166,2,-1,185,"PUGNA JAROCHA",6,4,"aa",49,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-10",8,"Aquí no es mesón,\nsigan adelante;\nyo no debo abrir,\nno sea algún tunante.",166,2,-1,185,"PUGNA JAROCHA",0,4,"ae",47,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-11",8,"—Pa qué más que la verdad:\nsoy un poco mal hablado,\npero eso es muy natural,\nyo no soy afeminado.",166,2,-1,185,"PUGNA JAROCHA",0,4,"ao",14,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-12",8,"—No me pongo la casaca,\npues a mí eso no me queda;\npregúntaselo a tu hermana,\nque a ella ya le di la prueba.",166,2,-1,185,"PUGNA JAROCHA",0,4,"ea",-1,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-13",8,"—Le preguntaré a mi hermana\nla verdad que hay en tus coplas;\ncasi te aseguro que\ntú en amor ya no soplas.",166,2,-1,185,"PUGNA JAROCHA",0,4,"oa",641,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-14",8,"—¿Para qué tanto lío,\nsi los dos somos hermanos?,\nvivimos el mismo río\ny somos veracruzanos.",166,2,-1,185,"PUGNA JAROCHA",1,4,"ao",318,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-15",8,"—Unamos nuestros patrones\nen un solo gran santuario;\na tu patrón, San Cristóbal,\ny a mi Virgen del Rosario.",166,2,-1,185,"PUGNA JAROCHA",0,4,"ao",25,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-16",8,"—Ahora sí que están unidos\nAlvarado y Tlacotalpan,\nno obstante estar divididos\npor el río Papaloapan.",166,2,-1,185,"PUGNA JAROCHA",0,4,"aa",-1,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-17",8,"No seas inhumano,\ntennos caridad,\nque el Dios de los Cielos\nte lo premiará.",166,2,-1,185,"PUGNA JAROCHA",0,4,"a",-1,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-18",8,"Ya se pueden ir\ny no molestar,\nporque si me enfado\nos voy a apalear.",166,2,-1,185,"PUGNA JAROCHA",0,4,"a",21,0,-1,0,260,260,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-19",8,"Venimos rendidos\ndesde Nazareth;\nyo soy carpintero\nde nombre José.",166,2,-1,185,"PUGNA JAROCHA",0,4,"e",-1,0,-1,0,261,261,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-20",8,"No me importa el nombre,\n¡déjenme dormir!,\npues que ya les digo\nque no hemos de abrir.",166,2,-1,185,"PUGNA JAROCHA",0,4,"i",157,0,-1,0,261,261,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-21",8,"Posada te pide,\namado casero,\npor sólo una noche\nla Reina del Cielo.",166,2,-1,185,"PUGNA JAROCHA",0,4,"eo",-1,0,-1,0,261,261,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-22",8,"Pues si es una reina\nquien lo solicita,\n¿cómo es que de noche\nanda tan solita?",166,2,-1,185,"PUGNA JAROCHA",0,4,"ia",50,0,-1,0,261,261,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-23",8,"Mi esposa es María,\nes Reina del Cielo\ny madre va a ser\ndel Divino Verbo.",166,2,-1,185,"PUGNA JAROCHA",0,4,"eo",-1,0,-1,0,261,261,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-24",8,"¿Eres tú José?\n¿Tu esposa es María?\nEntren, peregrinos,\nno los conocía.",166,2,-1,185,"PUGNA JAROCHA",0,4,"ia",0,0,-1,0,261,261,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-25",8,"Dios pague, señores,\nvuestra caridad,\ny así os colme el cielo\nde felicidad.",166,2,-1,185,"PUGNA JAROCHA",0,4,"a",16,0,-1,0,261,261,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-26",8,"Dichosa la casa\nque abriga este día\na la Virgen pura,\nla hermosa María.",166,2,-1,185,"PUGNA JAROCHA",0,4,"ia",0,0,-1,0,261,261,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-27",8,"Entren, Santos Peregrinos,\nreciban este rincón,\nno de esta pobre morada,\nsino de mi corazón.",166,2,-1,185,"PUGNA JAROCHA",0,4,"o",31,0,-1,0,261,261,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-28",8,"Esta noche es de alegría,\nde gusto y de regocijo,\nporque hospedamos aquí\na la madre de Dios hijo.",166,2,-1,185,"PUGNA JAROCHA",0,4,"io",122,0,-1,0,261,261,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap019-29",8,"José y María: Mil gracias os damos,\nque en esta ocasión\nposada nos disteis\ncon leal corazón.",166,2,-1,185,"PUGNA JAROCHA",3,4,"o",31,0,-1,0,261,261,"Ap. 19","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-01",8,"Muy buenas noches,\naldeanos dichosos;\nposadas les piden\nestos dos esposos.",171,2,4,185,"CANTOS DE POSADAS",3,4,"oo",186,0,-1,0,261,261,"Ap. 21","",0,"","","",2,0,0,[],""],["frenk_t4-ap021-02",8,"¿Quién viene a esta hora\nel sueño a turbar?,\nváyanse de aquí\npara otro lugar.",171,2,4,185,"CANTOS DE POSADAS",6,4,"a",21,0,-1,0,261,261,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-03",8,"Por piedad, señores,\nno seáis inhumanos;\nya las fieras rugen\ny no andan humanos.",171,2,4,185,"CANTOS DE POSADAS",0,4,"ao",318,0,-1,0,261,261,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-04",8,"Adelante está\nuna pastoría,\nallí dan posada\nde noche y de día.",171,2,4,185,"CANTOS DE POSADAS",0,4,"ia",0,0,-1,0,261,261,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-05",8,"Ni yo ni mi esposa\npodemos andar,\npor eso en tu choza\npedimos lugar.",171,2,4,185,"CANTOS DE POSADAS",1,4,"a",21,0,-1,0,261,261,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-06",8,"¿Qué destino traen\npor estos caminos?,\npues esta no es hora\nde andar peregrinos.",171,2,4,185,"CANTOS DE POSADAS",0,4,"io",206,0,-1,0,261,261,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-07",8,"Por cumplir [d]el César\nun gran mandamiento,\nvamos a Belén\ncon gran sufrimiento.",171,2,4,185,"CANTOS DE POSADAS",0,4,"eo",94,0,-1,0,261,261,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-08",8,"Decimos sus nombres\nsi queréis entrar,\npues hay malos hombre)\npor este lugar.",171,2,4,185,"CANTOS DE POSADAS",0,4,"a",21,0,-1,0,261,261,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-09",8,"Soy noble varón,\ncarpintero honrado,\nmi esposa es María,\nJosé yo me llamo.",171,2,4,185,"CANTOS DE POSADAS",0,4,"ao",-1,0,-1,0,262,262,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-10",8,"José, iSanto cielo!\ncon su esposa amada;\nentrad sin recelo,\nque aquí hay fiel posada.",171,2,4,185,"CANTOS DE POSADAS",1,4,"aa",49,0,-1,0,262,262,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-11",8,"Si estáis satisfechos,\ndéjanos entrar\na un rincón cualquiera\npara descansar.",171,2,4,185,"CANTOS DE POSADAS",0,4,"a",21,0,-1,0,262,262,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-12",8,"Que se abran las puertas\ncon mucha alegría\npara dar posada\na José y María.",171,2,4,185,"CANTOS DE POSADAS",0,4,"ia",0,0,-1,0,262,262,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-13",8,"Cariño tan tierno,\npiedad tan notoria\npremiará el Eterno\ncon su eterna gloria.",171,2,4,185,"CANTOS DE POSADAS",1,4,"oa",126,0,-1,0,262,262,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-14",8,"Entrad, peregrinos,\nentrad y gozad\nde esta franca y noble\nhospitalidad.",171,2,4,185,"CANTOS DE POSADAS",0,4,"a",16,0,-1,0,262,262,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-15",8,"Pasad la escogida,\nla niña dichosa,\nque el alma le albergue\ny humilde le adora.",171,2,4,185,"CANTOS DE POSADAS",0,4,"oa",-1,0,-1,0,262,262,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap021-16",8,"Quisiera en su obsequio\nhacer mil festines,\ny el coro entonarle\nde los querubines.",171,2,4,185,"CANTOS DE POSADAS",0,4,"ie",272,0,-1,0,262,262,"Ap. 21","",0,"","","",1,0,0,[],""],["frenk_t4-ap022-02",8,"—Anda que te anda;\nvine a un establo\ny allí, en el pesebre,\ncontemplé un milagro.",168,2,11,185,"PASTORCITA",6,4,"ao",-1,0,-1,0,262,262,"Ap. 22","",0,"","","",1,0,0,[],""],["frenk_t4-ap022-04",8,"—Vi que allí dormía\nun hermoso niño;\nera dulce y bello\neste pequeñito.",168,2,11,185,"PASTORCITA",0,4,"io",-1,0,-1,0,262,262,"Ap. 22","",0,"","","",1,0,0,[],""],["frenk_t4-ap022-06",8,"—Vi que linda madre\ntierna lo cargaba\ny, con voz muy tierna,\nquedo le cantaba.",168,2,11,185,"PASTORCITA",0,4,"aa",28,0,-1,0,262,262,"Ap. 22","",0,"","","",1,0,0,[],""],["frenk_t4-ap022-08",8,"Vi que un hombre fuerte\ny de negra barba\nal niñito hermoso\nprotegiendo estaba.",168,2,11,185,"PASTORCITA",0,4,"aa",-1,0,-1,0,262,262,"Ap. 22","",0,"","","",1,0,0,[],""],["frenk_t4-ap022-10",8,"—Ese pequeñito\nes el prometido;\nese pequeñito\nes Jesús el Cristo.",168,2,11,185,"PASTORCITA",0,4,"io",-1,0,-1,0,262,262,"Ap. 22","",0,"","","",1,0,0,[],""],["frenk_t4-ap022-12",8,"—Devoción sincera,\ntodo mi cariño,\ndevoción sincera\nyo le llevo al niño.",168,2,11,185,"PASTORCITA",1,4,"io",176,0,-1,0,262,262,"Ap. 22","",0,"","","",1,0,0,[],""],["frenk_t4-ap023-01",8,"—Yo te ofrezco, manso Niño,\nun ramo fresco y florido;\nlas flores que te he ofrecido\ndel jardín de mi alma son.",171,2,4,185,"YO TE OFREZCO, MANSO NIÑO",5,4,"o",-1,0,-1,0,262,262,"Ap. 23","",0,"","","",1,0,0,[],""],["frenk_t4-ap023-02",8,"—Yo estos pañalitos\nte vengo a dejar,\nque están bien hechecitos\nde lino y cambrai.",171,2,4,185,"YO TE OFREZCO, MANSO NIÑO",5,4,"aa",-1,0,-1,0,262,262,"Ap. 23","",0,"","","",1,0,0,[],""],["frenk_t4-ap024-01",8,"El sol y la luna\nesconden la cara\nde ver que María\nno hallaba posada.",166,2,-1,185,"CANCIÓN DE NOCHEBUENA",0,4,"aa",-1,0,-1,0,263,263,"Ap. 24","",0,"","","",1,0,0,[],""],["frenk_t4-ap024-03",8,"Despierta José\nmuy afligidito\nde ver que no tiene\nni un pañalito.",166,2,-1,185,"CANCIÓN DE NOCHEBUENA",6,4,"io",119,0,-1,0,263,263,"Ap. 24","",0,"","","",2,0,0,[],""],["frenk_t4-ap024-04",8,"Le dice María:\n—No te aflijas, José,\nen mi pobre toca\nyo lo envolveré.",166,2,-1,185,"CANCIÓN DE NOCHEBUENA",0,4,"e",77,0,-1,0,263,263,"Ap. 24","",0,"","","",2,0,0,[],""],["frenk_t4-ap025-02",8,"Compadre, usted me dispensa\npor esta gran humildad;\na ustedes les doy las gracias,\ny al niño felicidad.",170,2,7,185,"BAUTIZO",0,4,"a",16,0,-1,0,263,263,"Ap. 25","",0,"","","",1,0,0,[],""],["frenk_t4-ap025-03",8,"—Compadre, yo lo recibo\ncon el aprecio más fino;\nque Dios extienda sus manos,\njy que vivan los padrinos!",170,2,7,185,"BAUTIZO",0,4,"io",-1,0,-1,0,263,263,"Ap. 25","",0,"","","",1,0,0,[],""],["frenk_t4-ap027-01",8,"Décimas de un arrancado\nque por su mucha pobreza,\nla suerte con tal vileza\ncruelmente lo ha maltratado.",177,2,18,185,"SIEMPRE EL POBRE DESMERECE",11,4,"ao",14,0,-1,0,264,264,"Ap. 27","",0,"","","",2,0,0,[],""],["frenk_t4-ap027-02",8,"El rico en palacios vive\ny el pobre en los campos crece;\ny en medio de las ciudades\nsiempre el pobre desmerece.",177,2,18,185,"SIEMPRE EL POBRE DESMERECE",0,4,"ee",64,0,-1,0,264,264,"Ap. 27","",0,"","","",1,0,0,[],""],["frenk_t4-ap027-03",8,"El rico desde la cuna\ntiene pulido latón,\ny el pobre en su mal cajón,\ncon una manta importuna,\ndelicadeza ninguna;\nsiempre el pobre desmerece.",177,2,18,185,"SIEMPRE EL POBRE DESMERECE",9,6,"ee",-1,0,-1,0,264,264,"Ap. 27","",0,"","","",2,0,0,[],""],["frenk_t4-ap027-04",8,"Está el niño pobretón\ntirado en cualquier rincón\no en el suelo, si se ofrece,\nporque en cualquier ocasión,\nsiempre el pobre desmerece.",177,2,18,185,"SIEMPRE EL POBRE DESMERECE",7,5,"ee",64,0,-1,0,264,264,"Ap. 27","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap027-05",8,"Llega a salirle el bozo,\nque es la edad de las pasiones,\ny sólo quien tiene doblones\nes fino, amable y buen mozo;\ny aunque el pobre sea juicioso,\nsiempre el pobre desmerece.",177,2,18,185,"SIEMPRE EL POBRE DESMERECE",9,6,"ee",-1,0,-1,0,264,264,"Ap. 27","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap027-06",8,"Y aun de buenos procederes,\nlo desprecian las mujeres\ny de ellas todo apetece,\nporque en cualquier ocasión,\nsiempre el pobre desmerece.",177,2,18,185,"SIEMPRE EL POBRE DESMERECE",7,5,"ee",64,0,-1,0,264,264,"Ap. 27","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap027-07",8,"Se ofrece hacer la vela;\nel rico siempre pasea,\npero el pobre ni se menea\nporque si sale la lleva;\nvuelvo pues a repetir:\nsiempre el pobre desmerece,",177,2,18,185,"SIEMPRE EL POBRE DESMERECE",9,6,"ee",-1,0,-1,0,264,264,"Ap. 27","",0,"","","",2,0,0,[],""],["frenk_t4-ap027-08",8,"No hay comisión que se atreva\na molestar a un decente,\npero al pobre prontamente\nen las filas aparece,\nporque en cualquier ocasión,\nsiempre el pobre desmerece.",177,2,18,185,"SIEMPRE EL POBRE DESMERECE",9,6,"ee",64,0,-1,0,264,264,"Ap. 27","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap028-01",8,"Cuando el pobre está más arruinado\nni los de su casa lo pueden ver:\nes pelado, es borracho, es plebeyo,\ntrabaja al rendir y no sabe cumplir.\n¡Ah, qué mancha tan negra es la pobreza!",172,2,23,185,"LA POBREZA",7,5,"ea",-1,0,-1,0,264,264,"Ap. 28","",0,"","","",2,0,0,[],""],["frenk_t4-ap028-02",8,"Cuando un rico amanece tomado,\ntodita la gente con gusto: “¡El señor!”\nPara el rico no hay cárcel, no hay pena;\ncometió un delito, sale con honor.\n¡Ah, qué mancha tan negra es la pobreza!",172,2,23,185,"LA POBREZA",7,5,"ea",-1,0,-1,0,264,264,"Ap. 28","",0,"","","",2,0,0,[],""],["frenk_t4-ap028-03",8,"Cuando el rico las trata de amores,\nunas a las otras: “Me habló este señor”.\nLe contestan con orgullo ufano:\n“Oiga, don Fulano, es suyo mi amor\".\n¡Ah, qué mancha tan negra es la pobreza!",172,2,23,185,"LA POBREZA",7,5,"ea",-1,0,-1,0,264,264,"Ap. 28","",0,"","","",1,0,0,[],""],["frenk_t4-ap028-04",8,"Cuando el pobre las trata de amores:\n“Pelado, plebeyo, es infiel a su amor.”\nPara el rico no hay cárcel, no hay pena;\ncometió una falta, sale con honor.\n¡Ah, qué mancha tan negra es la pobreza!",172,2,23,185,"LA POBREZA",7,5,"ea",-1,0,-1,0,264,264,"Ap. 28","",0,"","","",1,0,0,[],""],["frenk_t4-ap029-01",8,"Te compré tu peine de oro\ny tu escobeta de plata\npara que te peines, china,\nesos rizos que me matan.",173,2,17,186,"EL PEINE",0,4,"aa",-1,0,-1,0,265,265,"Ap. 29","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap029-02",8,"A que yo te peino, china,\ndebajo de los laureles;\nal amanecer el día,\njay, qué rebonita eres!",173,2,17,186,"EL PEINE",0,4,"ee",-1,0,-1,0,265,265,"Ap. 29","",0,"","","",2,0,0,[],""],["frenk_t4-ap029-03",8,"Aquí yo te peino, china,\ndebajo de los limones;\nal amanecer el día,\njay, qué rebuena te pones!",173,2,17,186,"EL PEINE",0,4,"oe",34,0,-1,0,265,265,"Ap. 29","",0,"","","",1,0,0,[],""],["frenk_t4-ap030-01",8,"Mira lo que te traje\nde Panamá:\nuna peineta de oro\npa tu mamá.",176,2,3,186,"LA PEINETA",6,4,"a",9,0,-1,0,265,265,"Ap. 30","",0,"frenk_t1","","",8,0,0,[],""],["frenk_t4-ap030-03",8,"Mira lo que te traje\nde más adentro:\nuna peineta de oro,\ny a tu contento,",176,2,3,186,"LA PEINETA",6,4,"eo",-1,0,-1,0,265,265,"Ap. 30","",0,"","","",8,0,0,[],""],["frenk_t4-ap030-05",8,"Mira lo que te traje\nde Manzanillo:\nuna peineta de oro,\ncon un anillo.",176,2,3,186,"LA PEINETA",6,4,"io",228,0,-1,0,265,265,"Ap. 30","",0,"frenk_t1","","",8,0,0,[],""],["frenk_t4-ap031-01",8,"¡Ay, morená,\nmorená, la de allá arriba!,\nesta noche me la llevo,\naunque me cueste la vida.",176,2,3,186,"LA MORENITA I",3,4,"ia",-1,0,-1,0,265,265,"Ap. 31","",0,"","","",4,0,0,[],""],["frenk_t4-ap031-02",8,"¡Ay, morená,\nmorená, la de allá abajo!,\nesta noche me la llevo,\naunque me cueste trabajo.",176,2,3,186,"LA MORENITA I",3,4,"ao",168,0,-1,0,265,265,"Ap. 31","",0,"","","",4,0,0,[],""],["frenk_t4-ap032-01",8,"Bonitas conchitas\ncolor colorado;\nyo dejé a mis padres\npor enamorado.",178,2,10,186,"LAS CONCHITAS I",0,4,"ao",14,0,-1,0,266,266,"Ap. 32","",0,"frenk_t1","","",12,0,0,[],""],["frenk_t4-ap032-02",8,"Bonitas conchitas\ncolor amarillo;\nyo dejé a mis padres\npor irme contigo.",178,2,10,186,"LAS CONCHITAS I",0,4,"io",-1,0,-1,0,266,266,"Ap. 32","",0,"frenk_t1","","",12,0,0,[],""],["frenk_t4-ap032-03",8,"Bonitas conchitas\ncolor carmesí;\nyo dejé a mis padres\npor seguirte a ti.",178,2,10,186,"LAS CONCHITAS I",0,4,"i",23,0,-1,0,266,266,"Ap. 32","",0,"","","",12,0,0,[],""],["frenk_t4-ap032-05",8,"Bonitas conchitas\ncolor de estandarte;\nbonita muchacha\nes Clotilde Quirarte.",178,2,10,186,"LAS CONCHITAS I",0,4,"ae",8,0,-1,0,266,266,"Ap. 32","",0,"frenk_t1","","",12,0,0,[],""],["frenk_t4-ap032-06",8,"Bonitas conchitas\ncolor de azafrán;\nbonita muchacha\nes Conchita Durán.",178,2,10,186,"LAS CONCHITAS I",0,4,"a",147,0,-1,0,266,266,"Ap. 32","",0,"frenk_t1","","",12,0,0,[],""],["frenk_t4-ap033-01",8,"Este cuamecate, mi alma,\nque tiendo en la mañanita\npara que tienda sus trapos,\n¡alma mía de mi Juanita!",166,2,-1,186,"EL CUAMECATE",0,4,"ia",50,0,-1,0,266,266,"Ap. 33","",0,"frenk_t2","","",8,0,0,[],""],["frenk_t4-ap033-02",8,"Este cuamecate, mi alma,\nque tiendo de todo el día,\npara que tienda sus trapos\nla dueña del alma mía.",166,2,-1,186,"EL CUAMECATE",0,4,"ia",0,0,-1,0,266,266,"Ap. 33","",0,"frenk_t2","","",8,0,0,[],""],["frenk_t4-ap033-03",8,"Este cuamecate, mi alma,\nque pongo yo a la oración,\npara que tienda sus trapos\nTaima mía de Concepción.",166,2,-1,186,"EL CUAMECATE",0,4,"o",31,0,-1,0,266,266,"Ap. 33","",0,"","","",8,0,0,[],""],["frenk_t4-ap033-04",8,"Este cuamecate, mi alma,\nque tiendo toda la tarde,\n¡qué bonito se enredaba\ncon mi querida comadre!",166,2,-1,186,"EL CUAMECATE",0,4,"ae",-1,0,-1,0,266,266,"Ap. 33","",0,"frenk_t2","","",8,0,0,[],""],["frenk_t4-ap034-01",8,"Cupido me dijo a mí\nque no me malbaratara,\nque primero andara el mundo\ny después que me casara,",171,2,4,186,"EL CUPIDO",0,4,"aa",57,0,-1,0,266,266,"Ap. 34","",0,"frenk_t2","","",3,0,0,[],""],["frenk_t4-ap034-02",8,"¡Ay!, Cupido, Cupido, Cupido;\n¡ay!, Cupido, Cupido traidor;\n¡ay, me muero, me muero, Cupido!,\n¡ay!, me muero por darte mi amor.",171,2,4,186,"EL CUPIDO",3,4,"o",72,0,-1,0,266,266,"Ap. 34","",0,"","","",9,0,0,[],""],["frenk_t4-ap034-03",8,"Dicen que Cupido es muerto,\nque lo mató una mujer;\nsi Cupido fuera muerto\nya me mandarían prender.",171,2,4,186,"EL CUPIDO",1,4,"e",20,0,-1,0,266,266,"Ap. 34","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap034-04",8,"¡Ay!, Cupido, Cupido, Cupido;\n¡ay!, Cupido, Cupido tirano;\n¡ay, me muero, me muero, Cupido!,\n¡ay!, me muero por darte la mano.",171,2,4,186,"EL CUPIDO",3,4,"ao",81,0,-1,0,267,267,"Ap. 34","",0,"","","",9,0,0,[],""],["frenk_t4-ap034-05",8,"¡Ay!, Cupido, Cupido, Cupido;\n¡ay!, Cupido, Cupido chiquito;\n¡ay, me muero, me muero, Cupido!,\n¡ay!, me muero por darte un besito.",171,2,4,186,"EL CUPIDO",3,4,"io",-1,0,-1,0,267,267,"Ap. 34","",0,"","","",9,0,0,[],""],["frenk_t4-ap034-06",8,"Cupido me dio su espada\npara entrar en su aposento,\ny me dijo el camarada:\n“No procure usté el intento,\nno se puede, que es casada”.",171,2,4,186,"EL CUPIDO",7,5,"aa",49,0,-1,0,267,267,"Ap. 34","",0,"","","",2,0,0,[],""],["frenk_t4-ap034-07",8,"¡Ay!, Cupido, Cupido, Cupido;\n¡ay!, Cupido, Cupido grandote;\n¡ay, me muero, me muero, Cupido!,\n¡ay!, me muero por darte un besote.",171,2,4,186,"EL CUPIDO",3,4,"oe",292,0,-1,0,267,267,"Ap. 34","",0,"frenk_t1","","",9,0,0,[],""],["frenk_t4-ap035-01",8,"Aquí me siento a cantar\nencima de este rasero;\na ver si puedo lograr\nla mujer del cabretero.",182,2,21,186,"AQUÍ ME SIENTO A CANTAR",1,4,"eo",38,0,-1,0,267,267,"Ap. 35","",0,"frenk_t1","","",10,0,0,[],""],["frenk_t4-ap035-02",8,"Aquí me siento a cantar\nencima de este cuartillo:\na ver si puedo lograr\nla mujer de “Ligerillo”.",182,2,21,186,"AQUÍ ME SIENTO A CANTAR",1,4,"io",228,0,-1,0,267,267,"Ap. 35","",0,"frenk_t1","","",10,0,0,[],""],["frenk_t4-ap035-03",8,"Aquí me siento a cantar\ncon ternura y con aplomo:\na ver si puedo lograr\nla mujer del mayordomo.",182,2,21,186,"AQUÍ ME SIENTO A CANTAR",1,4,"oo",349,0,-1,0,267,267,"Ap. 35","",0,"frenk_t1","","",10,0,0,[],""],["frenk_t4-ap035-04",8,"Aquí me siento a cantar\nencima de este gran ramo;\ny éstas son las donas\nde mi señor amo.",182,2,21,186,"AQUÍ ME SIENTO A CANTAR",0,4,"ao",100,0,-1,0,267,267,"Ap. 35","",0,"frenk_t3","","",10,0,0,[],""],["frenk_t4-ap035-05",8,"Mi coletito de cuero,\nmangas, puños de sayal,\ny éstas son las galas\nde mi caporal.",182,2,21,186,"AQUÍ ME SIENTO A CANTAR",0,4,"a",1,0,-1,0,267,267,"Ap. 35","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap036-01",8,"Yo soy un gavilancillo\nque ando por aquí volando;\nla polla que no me llevo,\nla dejo cacaraqueando,",173,2,17,186,"EL GAVILANCILLO",0,4,"ao",33,0,-1,0,267,267,"Ap. 36","",0,"frenk_t1","","",12,0,0,[],""],["frenk_t4-ap036-02",8,"Yo soy un gavilancillo\nque me la vengo a llevar;\navísele a su marido,\nque me la venga a quitar.",173,2,17,186,"EL GAVILANCILLO",0,4,"a",21,0,-1,0,267,267,"Ap. 36","",0,"","","",12,0,0,[],""],["frenk_t4-ap036-03",8,"Yo soy un gavilancillo\nque ando por aquí volando;\nno me asustan pichoncitos,\nque palomas ando buscando.",173,2,17,186,"EL GAVILANCILLO",0,4,"ao",33,0,-1,0,267,267,"Ap. 36","",0,"","","",12,0,0,[],""],["frenk_t4-ap036-04",8,"Yo soy un gavilancillo\nque ando por altos y bajos;\nal lado de mi chinita\nando pasando trabajos.",173,2,17,186,"EL GAVILANCILLO",0,4,"ao",286,0,-1,0,267,267,"Ap. 36","",0,"","","",12,0,0,[],""],["frenk_t4-ap036-05",8,"Yo soy un gavilancillo\nque ando por entre las peñas;\na ver si puedo agarrar\nel amor de una trigueña.",173,2,17,186,"EL GAVILANCILLO",0,4,"ea",-1,0,-1,0,267,267,"Ap. 36","",0,"frenk_t1","","",12,0,0,[],""],["frenk_t4-ap036-06",8,"Yo soy un gavilancillo\nque ando por la nopalera;\na ver si puedo agarrar\nuna güilota habanera.",173,2,17,186,"EL GAVILANCILLO",0,4,"ea",44,0,-1,0,267,267,"Ap. 36","",0,"","","",12,0,0,[],""],["frenk_t4-ap036-07",8,"Yo soy un gavilancillo\nque ando por aquí, en el río;\ncobíjame con tus alas\nque ya me muero de frío.",173,2,17,186,"EL GAVILANCILLO",0,4,"io",3,0,-1,0,267,267,"Ap. 36","",0,"frenk_t1","","",12,0,0,[],""],["frenk_t4-ap037-01",8,"Señora, su periquito\nme gusta por colorado;\nahí verá si me lo vende\no me lo da regalado.",166,2,-1,186,"EL PERICO",0,4,"ao",14,0,-1,0,268,268,"Ap. 37","",0,"frenk_t2","","",8,0,0,[],""],["frenk_t4-ap037-02",8,"Señora, su periquito\nme gusta por amarillo;\nahí verá si me lo da\ndelante de su marido.",166,2,-1,186,"EL PERICO",0,4,"io",-1,0,-1,0,268,268,"Ap. 37","",0,"frenk_t2","","",8,0,0,[],""],["frenk_t4-ap037-03",8,"Señora, su periquito\nme quiere llevar al río,\ny yo le digo que no\nporque me muero de frío.",166,2,-1,186,"EL PERICO",0,4,"io",3,0,-1,0,268,268,"Ap. 37","",0,"","","",8,0,0,[],""],["frenk_t4-ap037-04",8,"Señora, su periquito\nme quiere llevar al mar,\ny yo le digo que no\nporque yo no sé nadar.",166,2,-1,186,"EL PERICO",0,4,"a",21,0,-1,0,268,268,"Ap. 37","",0,"","","",8,0,0,[],""],["frenk_t4-ap038-01",8,"Becerrero, becerrero\nde la hacienda de Tequila:\nle dirás a la ranchera\nque me guarde mantequilla.",166,2,-1,186,"EL TORO I",0,4,"ia",-1,0,-1,0,268,268,"Ap. 38","",0,"frenk_t1","","",7,0,0,[],""],["frenk_t4-ap038-02",8,"Becerrero, becerrero\nde la hacienda del Ranchito:\nle dirás a la ranchera\nsi tiene queso chiquito.",166,2,-1,186,"EL TORO I",0,4,"io",119,0,-1,0,268,268,"Ap. 38","",0,"frenk_t1","","",7,0,0,[],""],["frenk_t4-ap038-03",8,"Becerrero, becerrero\nde la hacienda El Cabezón:\nle dirás a la ranchera\nque si tiene requesón,",166,2,-1,186,"EL TORO I",0,4,"o",31,0,-1,0,268,268,"Ap. 38","",0,"frenk_t1","","",7,0,0,[],""],["frenk_t4-ap039-01",8,"Cuando me vine de Tuxpan,\nsobre las olas venía\ny el estrépito del agua\nme recordaba a María.",176,2,3,186,"MARÍA, MARÍA I",0,4,"ia",0,0,-1,0,268,268,"Ap. 39","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap039-03",8,"Ya se cayó el arbolito\ndonde yo me entretenía,\ndonde pasé buenas horas\nplaticando con María.",176,2,3,186,"MARÍA, MARÍA I",0,4,"ia",0,0,-1,0,268,268,"Ap. 39","",0,"","","",3,0,0,[],""],["frenk_t4-ap039-05",8,"Dicen que me han de matar\npor el amor de María;\n¡mentirai, no me hacen nada,\nson pollos de mala cría.",176,2,3,186,"MARÍA, MARÍA I",0,4,"ia",0,0,-1,0,268,268,"Ap. 39","",0,"","","",19,0,0,[],""],["frenk_t4-ap039-07",8,"Dicen que me han de quitar\nel camino para el pozo;\n¡mentiral, no me hacen nada,\ncon mi cuchillo filoso.",176,2,3,186,"MARÍA, MARÍA I",0,4,"oo",160,0,-1,0,268,268,"Ap. 39","",0,"","","",12,0,0,[],""],["frenk_t4-ap039-09",8,"Dicen que me han de matar\na orillas del camposanto;\n¡mentiral, no me hacen nada,\nque estoy curado de espanto.",176,2,3,186,"MARÍA, MARÍA I",0,4,"ao",30,0,-1,0,268,268,"Ap. 39","",0,"","","",19,0,0,[],""],["frenk_t4-ap039-11",8,"Dicen que me han de quitar\nel camino de tu huerto;\nno más me andan asustando\ncon el petate del muerto.",176,2,3,186,"MARÍA, MARÍA I",0,4,"eo",88,0,-1,0,268,268,"Ap. 39","",0,"frenk_t1","","",12,0,0,[],""],["frenk_t4-ap039-13",8,"Dicen que me han de matar\ncon una daga bonita;\nlas heridas que me den,\nme las cura Mariquita.",176,2,3,186,"MARÍA, MARÍA I",0,4,"ia",50,0,-1,0,269,269,"Ap. 39","",0,"frenk_t2","","",19,0,0,[],""],["frenk_t4-ap039-15",8,"Dicen que me han de matar\na aquello del medio día;\ny aquí se acaba cantando\nel “Corrido de María”.",176,2,3,186,"MARÍA, MARÍA I",3,4,"ia",0,0,-1,0,269,269,"Ap. 39","",0,"","","",19,0,0,[],""],["frenk_t4-ap040-01",8,"Qué bonitas campanitas\nse repican en Tepic;\nellas se repican solas\nacordándose de ti.",173,2,17,186,"LAS CAMPANITAS",0,4,"i",-1,0,-1,0,269,269,"Ap. 40","",0,"","","",6,0,0,[],""],["frenk_t4-ap040-02",8,"Triste, triste\nmi corazón estaría\npor una joven que yo amo\nque se llama Rosalía.",173,2,17,186,"LAS CAMPANITAS",3,4,"ia",0,0,-1,0,269,269,"Ap. 40","",0,"frenk_t1","","",3,0,0,[],""],["frenk_t4-ap040-03",8,"Triste, triste\nmi corazón estará\npor una joven que yo amo\nque se llama Soledad.",173,2,17,186,"LAS CAMPANITAS",3,4,"a",-1,0,-1,0,269,269,"Ap. 40","",0,"","","",3,0,0,[],""],["frenk_t4-ap040-04",8,"Qué bonitas campanitas,\n¿cuándo se repicarán?\nCada que me acuerdo de ellas,\nganas de llorar me dan.",173,2,17,186,"LAS CAMPANITAS",0,4,"a",147,0,-1,0,269,269,"Ap. 40","",0,"","","",6,0,0,[],""],["frenk_t4-ap040-06",8,"Qué bonitas campanitas\nlas que toca el compañero;\nel consuelo que me queda;\nque yo las toqué primero.",173,2,17,186,"LAS CAMPANITAS",0,4,"eo",38,0,-1,0,269,269,"Ap. 40","",0,"","","",6,0,0,[],""],["frenk_t4-ap041-01",8,"Mi marido se fue a viaje\ny me trajo un molcajete;\ny de gusto que lo trajo,\nya lo saca, ya lo mete.",166,2,-1,186,"MI MARIDO SE FUE A VIAJE",0,4,"ee",285,0,-1,0,269,269,"Ap. 41","",0,"","","",6,0,0,[],""],["frenk_t4-ap041-03",8,"Mi marido se fue a viaje\ny me trajo una batea;\ny del gusto que la trajo,\nya se sube, ya se apea.",166,2,-1,186,"MI MARIDO SE FUE A VIAJE",0,4,"ea",54,0,-1,0,269,269,"Ap. 41","",0,"frenk_t2","","",6,0,0,[],""],["frenk_t4-ap042-01",8,"Mi comadre está bailando,\n¡qué bonito las dispara!;\nsi no fuera mi comadre,\notro gallo nos cantara.",176,2,3,186,"MI COMADRE",0,4,"aa",57,0,-1,0,269,269,"Ap. 42","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap042-02",8,"Mi comadre está enojada,\nno sé cuál será su intento;\n¿será porque mi compadre\nno pasaba para adentro?",176,2,3,186,"MI COMADRE",0,4,"eo",-1,0,-1,0,269,269,"Ap. 42","",0,"","","",6,0,0,[],""],["frenk_t4-ap042-03",8,"Mi comadre está enojada,\nyo no sé por qué sería;\nla hallaron con mi compadre\nhaciéndole una avería.",176,2,3,186,"MI COMADRE",0,4,"ia",0,0,-1,0,270,270,"Ap. 42","",0,"","","",6,0,0,[],""],["frenk_t4-ap042-04",8,"Mi comadre está enojada,\nyo no sé por qué será;\nla hallaron con mi compadre\nhaciéndole una maldad.",176,2,3,186,"MI COMADRE",0,4,"a",-1,0,-1,0,270,270,"Ap. 42","",0,"frenk_t2","","",6,0,0,[],""],["frenk_t4-ap042-05",8,"Mi comadre está muy gorda,\nyo no sé por qué será;\n¿será por los alimentos\nque mi compadre le da?",176,2,3,186,"MI COMADRE",0,4,"a",9,0,-1,0,270,270,"Ap. 42","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap042-06",8,"Mi compadre se murió,\nel diablo se lo llevó,\ny allá le estará pagando\nlas patadas que le dio.",176,2,3,186,"MI COMADRE",0,4,"o",2,0,-1,0,270,270,"Ap. 42","",0,"","","",1,0,0,[],""],["frenk_t4-ap043-01",8,"Una niña se embarcó\nen los vapores de guerra;\nel contramaestre le dice:\n“¡Cuidado con la candela!”",171,2,4,186,"LA CANDELA",0,4,"ea",-1,0,-1,0,270,270,"Ap. 43","",0,"frenk_t2","","",6,0,0,[],""],["frenk_t4-ap043-02",8,"A mí no me quema, mamá,\na mí no me quema, papá,\na mí no me quema nada,\nni la candela, ni el aguarrás,\nni la candela que está apagá.",171,2,4,186,"LA CANDELA",7,5,"a",-1,0,-1,0,270,270,"Ap. 43","",0,"","","",2,0,0,[],""],["frenk_t4-ap043-03",8,"Una niña se embarcó\nen el vapor de Colón;\nel contramaestre le dice:\n“¡Cuidado con el fogón!”",171,2,4,186,"LA CANDELA",0,4,"o",31,0,-1,0,270,270,"Ap. 43","",0,"frenk_t2","","",6,0,0,[],""],["frenk_t4-ap043-05",8,"Una niña se embarcó\nen los vapores de Venus;\nel contramaestre le dice:\n“¡Sólo a Jesucristo temo!”",171,2,4,186,"LA CANDELA",5,4,"eo",-1,0,-1,0,270,270,"Ap. 43","",0,"frenk_t2","","",6,0,0,[],""],["frenk_t4-ap044-01",8,"Cuatro palomitas blancas\nparadas en un romero,\nunas a las otras dicen:\n“No hay amor como el primero.”",178,2,10,186,"CUATRO PALOMITAS BLANCAS",0,4,"eo",38,0,-1,0,270,270,"Ap. 44","",0,"frenk_t2","","",5,0,0,[],""],["frenk_t4-ap045-01",8,"Una guacamaya pinta\nle dijo a una verde, verde:\n“¡Ay!, qué ojitos de señora,\nparece que ya se duerme.”",166,2,-1,186,"LA GUACAMAYA",0,4,"ee",-1,0,-1,0,270,270,"Ap. 45","",0,"frenk_t1","","",8,0,0,[],""],["frenk_t4-ap045-02",8,"Una guacamaya pinta\nle dijo a una colorada:\n“Vámonos para la costa,\na pasar la temporada.”",166,2,-1,186,"LA GUACAMAYA",0,4,"aa",49,0,-1,0,270,270,"Ap. 45","",0,"","","",8,0,0,[],""],["frenk_t4-ap045-03",8,"Una guacamaya pinta\nle dijo a una azul turquí:\n“Si al cabo me has de querer,\n¿por qué no dices que sí?”",166,2,-1,186,"LA GUACAMAYA",0,4,"i",23,0,-1,0,270,270,"Ap. 45","",0,"frenk_t1","","",8,0,0,[],""],["frenk_t4-ap046-01",8,"Andaba la chachalaca\npor las orillas del río:\nandaba de enamorada\ncon el pájaro tildío.",168,2,11,186,"LA CHACHALACA",0,4,"io",3,0,-1,0,271,271,"Ap. 46","",0,"frenk_t3","","",10,0,0,[],""],["frenk_t4-ap046-02",8,"Andaba la chachalaca\npor las orillas del monte:\nandaba de enamorada\ncon el pájaro cenzontle.",168,2,11,186,"LA CHACHALACA",0,4,"oe",-1,0,-1,0,271,271,"Ap. 46","",0,"","","",10,0,0,[],""],["frenk_t4-ap046-03",8,"Andaba la chachalaca\npor las orillas del cerro:\nandaba de enamorada\ncon el pájaro jilguero.",168,2,11,186,"LA CHACHALACA",0,4,"eo",-1,0,-1,0,271,271,"Ap. 46","",0,"frenk_t3","","",10,0,0,[],""],["frenk_t4-ap046-04",8,"Andaba la chachalaca\npor las orillas del llano:\nandaba de enamorada\ncon el pájaro paisano.",168,2,11,186,"LA CHACHALACA",0,4,"ao",81,0,-1,0,271,271,"Ap. 46","",0,"frenk_t3","","",10,0,0,[],""],["frenk_t4-ap048-01",8,"Estaba la tuza, estaba\nsentadita en un rincón,\ny el picaro del tucillo\nhaciéndose el dormilón,",166,2,-1,186,"LA TUZA",0,4,"o",31,0,-1,0,271,271,"Ap. 48","",0,"frenk_t3","","",9,0,0,[],""],["frenk_t4-ap048-02",8,"Tan, tan, que la puerta toca,\ntan, tan, que la van a abrir;\ntan, tan, ¿si será la tuza,\ntuza que viene a dormir?",166,2,-1,186,"LA TUZA",0,4,"i",157,0,-1,0,271,271,"Ap. 48","",0,"","","",1,0,0,[],""],["frenk_t4-ap048-03",8,"Estaba la tuza, estaba\nparadita en una esquina,\ny el picaro del tucillo\nadentro de la cantina.",166,2,-1,186,"LA TUZA",0,4,"ia",11,0,-1,0,271,271,"Ap. 48","",0,"frenk_t3","","",9,0,0,[],""],["frenk_t4-ap048-05",8,"Estaba la tuza, estaba\nsentada en el canapé,\ny el picaro del tucillo\ndiciéndole no sé qué.",166,2,-1,186,"LA TUZA",0,4,"e",77,0,-1,0,271,271,"Ap. 48","",0,"frenk_t3","","",9,0,0,[],""],["frenk_t4-ap048-07",8,"Estaba la tuza, estaba\ndormida en su blanco lecho,\ny el picaro del tucillo\ndándose golpes de pecho.",166,2,-1,186,"LA TUZA",0,4,"eo",60,0,-1,0,272,272,"Ap. 48","",0,"","","",9,0,0,[],""],["frenk_t4-ap049-01",8,"—Tecolotito, ¿de dónde vienes?\n—Vengo de la manzanía;\ntoditas vienen bajando,\nmás atrás viene la mía.",166,2,-1,186,"EL TECOLOTITO",3,4,"ia",0,0,-1,0,272,272,"Ap. 49","",0,"frenk_t3","","",4,0,0,[],""],["frenk_t4-ap049-02",8,"—Tecolotito, ¿de dónde vienes?\n—Vengo del número uno,\nesperando mi tecolota,\nque me traiga el desayuno.",166,2,-1,186,"EL TECOLOTITO",3,4,"uo",230,0,-1,0,272,272,"Ap. 49","",0,"frenk_t3","","",4,0,0,[],""],["frenk_t4-ap049-03",8,"—Tecolote, ¿qué haces ahí,\nparado en ese palmar?\n—Esperando mi tecolota,\nque me traiga de cenar,",166,2,-1,186,"EL TECOLOTITO",0,4,"a",21,0,-1,0,272,272,"Ap. 49","",0,"frenk_t3","","",6,0,0,[],""],["frenk_t4-ap049-04",8,"—Tecolote, ¿qué haces ahí,\nparado en ese granado?\n—Esperando mi tecolota,\nque con otro se ha fugado.",166,2,-1,186,"EL TECOLOTITO",0,4,"ao",14,0,-1,0,272,272,"Ap. 49","",0,"frenk_t3","","",6,0,0,[],""],["frenk_t4-ap051-01",8,"Y este torito que traigo\nno es pinto ni es colorado,\ny es un torito barato,\nde los cuernos recortado.",171,2,4,186,"EL",0,4,"ao",-1,0,-1,0,272,272,"Ap. 51","",0,"","","",1,0,0,[],""],["frenk_t4-ap051-02",8,"¡Átalo, átalo, átalo,\nque se te fue!;\nya me lo habían toreado,\ny nunca te olvidaré.",171,2,4,186,"EL",3,4,"e",77,0,-1,0,272,272,"Ap. 51","",0,"","","",3,0,0,[],""],["frenk_t4-ap051-03",8,"—Cuervito, cuervito,\n¿qué haces en el río?\n—Pasando trabajos\ny muerto de frío.",171,2,4,186,"EL",0,4,"io",3,0,-1,0,272,272,"Ap. 51","",0,"frenk_t3","","",7,0,0,[],""],["frenk_t4-ap051-04",8,"—Hazme mi choco, choco,\nhazme mi chocolate,\ny corre la caldereta\ny bate que bate.",171,2,4,186,"EL",0,4,"ae",384,0,-1,0,272,272,"Ap. 51","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap051-06",8,"¡Átalo, átalo, átalo,\nque se te iba!;\néste ya me lo habían toreado,\nsi no, yo te bajo de arriba.",171,2,4,186,"EL",3,4,"ia",140,0,-1,0,272,272,"Ap. 51","",0,"frenk_t3","","",3,0,0,[],""],["frenk_t4-ap051-07",8,"Este torito que traigo,\nlo traigo desde Campeche;\ny lo vengo manteniendo\ncon pura sopa de leche.",171,2,4,186,"EL",0,4,"ee",180,0,-1,0,272,272,"Ap. 51","",0,"frenk_t3","","",10,0,0,[],""],["frenk_t4-ap051-08",8,"¡Lázalo, lázalo, lázalo,\nque se te va!;\néchame los brazos, mi alma,\nsi me tienes voluntad.",171,2,4,186,"EL",3,4,"a",-1,0,-1,0,273,273,"Ap. 51","",0,"frenk_t1","","",3,0,0,[],""],["frenk_t4-ap051-09",8,"¡Lázalo, lázalo, lázalo,\nque se te fue!;\néchame los brazos, mi alma,\nsi me tienes buena fe.",171,2,4,186,"EL",3,4,"e",77,0,-1,0,273,273,"Ap. 51","",0,"","","",3,0,0,[],""],["frenk_t4-ap051-10",8,"Este torito que traigo,\nlo traigo desde Jalapa,\ny lo vengo manteniendo\ncon pura salsa borracha.",171,2,4,186,"EL",0,4,"aa",-1,0,-1,0,273,273,"Ap. 51","",0,"","","",10,0,0,[],""],["frenk_t4-ap051-11",8,"¡Lázalo, lázalo, lázalo,\nque se te fue!;\néchame los brazos, mi alma,\nque nunca te olvidaré.",171,2,4,186,"EL",3,4,"e",77,0,-1,0,273,273,"Ap. 51","",0,"","","",3,0,0,[],""],["frenk_t4-ap052-01",8,"Le dirás a la vaquilla\nque no se ande ladereando;\nun becerro trae a pie\ny otro que se le anda ahijando.",173,2,17,186,"LA VAQUILLA",3,4,"ao",33,0,-1,0,273,273,"Ap. 52","",0,"","","",8,0,0,[],""],["frenk_t4-ap052-02",8,"Le dirás a la vaquilla\nque se baje para el plan,\nporque se le muere de hambre\nel becerro gavilán.",173,2,17,186,"LA VAQUILLA",0,4,"a",147,0,-1,0,273,273,"Ap. 52","",0,"frenk_t3","","",8,0,0,[],""],["frenk_t4-ap052-03",8,"Le dirás a la vaquilla\nque se baje del mogote,\nporque se le muere de hambre\nel becerro capirote.",173,2,17,186,"LA VAQUILLA",0,4,"oe",292,0,-1,0,273,273,"Ap. 52","",0,"frenk_t3","","",8,0,0,[],""],["frenk_t4-ap053-01",8,"Si la gallina quisiera\nhacer un trato conmigo,\nella pusiera los huevos\ny yo me echara en el nido.",175,2,6,186,"LA GALLINA",0,4,"io",-1,0,-1,0,273,273,"Ap. 53","",0,"","","",1,0,0,[],""],["frenk_t4-ap053-02",8,"Voy a casar mi pollita\ncon un gallo de la bola,\npara que nazcan los pollos\ncon un copete en la cola.",175,2,6,186,"LA GALLINA",0,4,"oa",321,0,-1,0,273,273,"Ap. 53","",0,"frenk_t3","","",5,0,0,[],""],["frenk_t4-ap053-04",8,"¿Qué pajarillo es aquél\nque canta en aquella lima?,\nanda, dile que no cante,\nque a mi corazón lastima.",175,2,6,186,"LA GALLINA",0,4,"ia",302,0,-1,0,273,273,"Ap. 53","",0,"","","",8,0,0,[],""],["frenk_t4-ap053-05",8,"Voy a casar mi pollita\ncon un gallo de Durango,\npara que nazcan los pollos\ntemplados para el fandango.",175,2,6,186,"LA GALLINA",0,4,"ao",596,0,-1,0,273,273,"Ap. 53","",0,"frenk_t3","","",5,0,0,[],""],["frenk_t4-ap053-06",8,"Voy a casar mi pollita\ncon un gallo copetón,\npara que nazcan los pollos\ncon chaqueta y pantalón.",175,2,6,186,"LA GALLINA",0,4,"o",31,0,-1,0,273,273,"Ap. 53","",0,"","","",5,0,0,[],""],["frenk_t4-ap053-07",8,"¿Qué pajarillo es aquél\nque viene por la garita?\nFs el “Pajarillo alegre”\nque bailaba Margarita.",175,2,6,186,"LA GALLINA",0,4,"ia",50,0,-1,0,273,273,"Ap. 53","",0,"","","",8,0,0,[],""],["frenk_t4-ap053-08",8,"¿Qué paj arillo es aquél\nque se ha venido volando?,\nno lo puedo conocer\nsobre la tierra andando.",175,2,6,186,"LA GALLINA",0,4,"ao",33,0,-1,0,274,274,"Ap. 53","",0,"","","",2,0,0,[],""],["frenk_t4-ap053-09",8,"¿Qué paj arillo es aquél\nque canta en aquella higuera?,\nanda, dile que no cante,\nque espere a que yo me muera.",175,2,6,186,"LA GALLINA",0,4,"ea",44,0,-1,0,274,274,"Ap. 53","",0,"","","",2,0,0,[],""],["frenk_t4-ap055-01",8,"Ay, la pobre de la tuza\nya no comerá más caña,\nporque se la llevan presa\nlos soldados para España.",171,2,4,186,"LA TUZA",0,4,"aa",213,0,-1,0,274,274,"Ap. 55","",0,"","","",2,0,0,[],""],["frenk_t4-ap055-02",8,"Tan, tan, tan,\nque toca la puerta;\ntilín, tilín.\nque la voy a abrir,\nno sea que será la tuza,\ntuza que viene a dormir.",171,2,4,186,"LA TUZA",9,6,"i",157,0,-1,0,274,274,"Ap. 55","",0,"","","",2,0,0,[],""],["frenk_t4-ap055-03",8,"Tan, tan, tan,\nque será la tuza;\ntilín, tilín,\nque no tengo llave;\ntan, tan, tan,\nque será la tuza,\ntuza que viene del baile.",171,2,4,186,"LA TUZA",4,7,"ae",-1,0,-1,0,274,274,"Ap. 55","",0,"","","",2,0,0,[],""],["frenk_t4-ap055-04",8,"A la pobre de la tuza\nle dio mal de corazón,\nporque vido su retrato\npintado en un cartelón.",171,2,4,186,"LA TUZA",0,4,"o",31,0,-1,0,274,274,"Ap. 55","",0,"","","",4,0,0,[],""],["frenk_t4-ap055-06",8,"Ay, la pobre de la tuza\nya no comerá camote,\nporque se la llevan presa\nlos soldados pa Perote.",171,2,4,186,"LA TUZA",0,4,"oe",292,0,-1,0,274,274,"Ap. 55","",0,"","","",2,0,0,[],""],["frenk_t4-ap056-01",8,"Viborita, viborita,\nviborita mahuaquite:\n¿cómo no me picas hora\nque vengo de Chalahuite?",167,2,2,186,"LA VIBORITA I",0,4,"ie",315,0,-1,0,274,274,"Ap. 56","",0,"frenk_t3","","",8,0,0,[],""],["frenk_t4-ap056-02",8,"Viborita, viborita,\nviborita de colores;\nsáquenle la vueltecita\ny al estilo Pisaflores.",167,2,2,186,"LA VIBORITA I",1,4,"oe",5,0,-1,0,274,274,"Ap. 56","",0,"frenk_t3","","",8,0,0,[],""],["frenk_t4-ap056-03",8,"Viborita, viborita,\nviborita coralilla;\n¿cómo no me picas hora\nque vengo de Jilitilla?",167,2,2,186,"LA VIBORITA I",0,4,"ia",162,0,-1,0,274,274,"Ap. 56","",0,"","","",8,0,0,[],""],["frenk_t4-ap056-04",8,"Viborita, viborita,\nviborita, viborón.\n¿como no me picas hora\nque vengo de La Misión?",167,2,2,186,"LA VIBORITA I",0,4,"o",31,0,-1,0,274,274,"Ap. 56","",0,"frenk_t3","","",8,0,0,[],""],["frenk_t4-ap057-01",8,"La culebra me picó\nmuy cerquita del tobillo;\nno me pudieron curar\nporque era de coralillo,",171,2,4,186,"LA CULEBRA I",0,4,"io",228,0,-1,0,275,275,"Ap. 57","",0,"frenk_t3","","",6,0,0,[],""],["frenk_t4-ap057-02",8,"La culebra me picó\nmuy cerquita del pescuezo;\nno me pudieron curar\nporque era de rabo hueso.",171,2,4,186,"LA CULEBRA I",0,4,"eo",48,0,-1,0,275,275,"Ap. 57","",0,"frenk_t3","","",6,0,0,[],""],["frenk_t4-ap057-03",8,"La culebra me picó\nmuy cerquita de la corva;\nno me pudieron curar\nporque era víbora sorda.",171,2,4,186,"LA CULEBRA I",0,4,"oa",-1,0,-1,0,275,275,"Ap. 57","",0,"frenk_t3","","",6,0,0,[],""],["frenk_t4-ap058-01",8,"Cuando el pescador empieza\na dar golpes en el río,\nsalen las indias diciendo:\n“Todos los juiles son míos.”",171,2,4,186,"LOS JUILES",0,4,"io",-1,0,-1,0,275,275,"Ap. 58","",0,"frenk_t3","","",8,0,0,[],""],["frenk_t4-ap058-03",8,"Cuando el pescador empieza\na dar golpes en el bote,\nsalen las indias diciendo:\n“Juiles, robalo y jolote”.",171,2,4,186,"LOS JUILES",0,4,"oe",292,0,-1,0,275,275,"Ap. 58","",0,"frenk_t3","","",8,0,0,[],""],["frenk_t4-ap058-05",8,"Cuando el pescador empieza\na dar golpes en el banco,\nsalen las indias diciendo:\n“Juiles y robalo blanco.”",171,2,4,186,"LOS JUILES",0,4,"ao",303,0,-1,0,275,275,"Ap. 58","",0,"frenk_t3","","",8,0,0,[],""],["frenk_t4-ap059-01",8,"El carretero se va,\nya se va para Sayula;\nel carretero no va\nporque le falta una mula.",173,2,17,186,"EL CARRETERO",1,4,"ua",547,0,-1,0,275,275,"Ap. 59","",0,"frenk_t3","","",11,0,0,[],""],["frenk_t4-ap059-02",8,"Señor carretero,\nle vengo a avisar\nque sus animales\nse me iban a ahogar,\nunos en la playa,\notros en el mar.",173,2,17,186,"EL CARRETERO",9,6,"a",21,0,-1,0,275,275,"Ap. 59","",0,"","","",3,0,0,[],""],["frenk_t4-ap059-03",8,"El carretero se va,\nya se va para la Unión;\nel carretero no va\nporque le falta el camión.",173,2,17,186,"EL CARRETERO",1,4,"o",31,0,-1,0,275,275,"Ap. 59","",0,"frenk_t3","","",11,0,0,[],""],["frenk_t4-ap059-05",8,"El carretero se va,\nya se va para el Potrero;\nel carretero no va\nporque le falta dinero.",173,2,17,186,"EL CARRETERO",1,4,"eo",38,0,-1,0,276,276,"Ap. 59","",0,"frenk_t3","","",11,0,0,[],""],["frenk_t4-ap060-01",8,"Yo conocí un carpintero\nque se llamaba Manuel,\nque empalmaba un tinajero\ndel cogollo de un laurel;\n¡ese sí era carpintero!",171,2,4,186,"EL PÁJARO CARPINTERO",7,5,"eo",38,0,-1,0,276,276,"Ap. 60","",0,"","","",13,0,0,[],""],["frenk_t4-ap060-02",8,"Yo conocí un carpintero\nque se llamaba Pablo,\nque empalmaba un tinajero\ny antes que naciera el palo;\n¡y ese sí era carpintero!,\nyo le conocí la mano.",171,2,4,186,"EL PÁJARO CARPINTERO",9,6,"ao",-1,0,-1,0,276,276,"Ap. 60","",0,"","","",13,0,0,[],""],["frenk_t4-ap060-03",8,"Yo conocí un carpintero\nque vivía en un campamento,\nque empalmaba un tinajero\ndel aire, de puro viento;\n¡ese sí era carpintero!,\ny hombre de mucho talento.",171,2,4,186,"EL PÁJARO CARPINTERO",9,6,"eo",-1,0,-1,0,276,276,"Ap. 60","",0,"frenk_t3","","",13,0,0,[],""],["frenk_t4-ap060-04",8,"Siempre vive apasionado\nel pájaro carpintero,\ny le contesta el jilguero:\n“Hombre, vive con cuidado;\nsiendo yo carbonero,\nuna mujer me ha tiznado.”",171,2,4,186,"EL PÁJARO CARPINTERO",9,6,"ao",14,0,-1,0,276,276,"Ap. 60","",0,"","","",1,0,0,[],""],["frenk_t4-ap060-05",8,"Yo conocí un carpintero\nque se llamaba Felipe,\nque formaba un tinajero\ndel cogollo de un quelite;\n¡ese sí era carpintero!,\nde lo bueno, que le quiten.",171,2,4,186,"EL PÁJARO CARPINTERO",9,6,"ie",-1,0,-1,0,276,276,"Ap. 60","",0,"","","",13,0,0,[],""],["frenk_t4-ap061-02",8,"Campanita de oro\ncon cordón de lazo,\narrea al caporal\npara ese pedazo.",187,2,12,186,"DANZA DE LOS TOREADORES",0,4,"ao",43,0,-1,0,276,276,"Ap. 61","",0,"","","",5,0,0,[],""],["frenk_t4-ap061-03",8,"Campanita de oro\ncon cordón de cuero,\narrea al caporal\npara ese potrero",187,2,12,186,"DANZA DE LOS TOREADORES",0,4,"eo",38,0,-1,0,276,276,"Ap. 61","",0,"","","",5,0,0,[],""],["frenk_t4-ap061-04",8,"Manga de gamuza,\ncalzón de sayal;\nrecoge la zaraza\npor la calle real.",187,2,12,186,"DANZA DE LOS TOREADORES",0,4,"a",1,0,-1,0,276,276,"Ap. 61","",0,"","","",1,0,0,[],""],["frenk_t4-ap061-05",8,"Campanita de oro\ncon cordón de seda,\narrea al caporal\ny a los que se quedan.",187,2,12,186,"DANZA DE LOS TOREADORES",0,4,"ea",-1,0,-1,0,276,276,"Ap. 61","",0,"","","",5,0,0,[],""],["frenk_t4-ap061-06",8,"Repique en San Francisco,\nresponde catedral;\nqué linda viene viajando\nla Santísima Trinidad.",187,2,12,186,"DANZA DE LOS TOREADORES",0,4,"a",-1,0,-1,0,276,276,"Ap. 61","",0,"","","",2,0,0,[],""],["frenk_t4-ap061-07",8,"Campanita de oro,\npájaros de abril,\ncántenle a mi toro\nque ya se va a morir.",187,2,12,186,"DANZA DE LOS TOREADORES",0,4,"i",-1,0,-1,0,276,276,"Ap. 61","",0,"","","",5,0,0,[],""],["frenk_t4-ap062-01",8,"Estaba la Lloroncita\nplaticándole a David:\nque para pasar trabajos,\nlo mismo es allá que aquí.",171,2,4,186,"LA LLORONCITA",0,4,"i",-1,0,-1,0,277,277,"Ap. 62","",0,"frenk_t3","","",10,0,0,[],""],["frenk_t4-ap062-02",8,"¡Ay de mí, Llorona!,\nmi bien, déjame llorar,\nque sólo llorando puede\nmi corazón descansar.",171,2,4,186,"LA LLORONCITA",0,4,"a",21,0,-1,0,277,277,"Ap. 62","",0,"","","",35,0,0,[],""],["frenk_t4-ap062-03",8,"¡Ay de mí, Llorona!,\nque llore y que ría;\nes la causa de mi llanto,\ny esa es toda mi alegría.",171,2,4,186,"LA LLORONCITA",0,4,"ia",0,0,-1,0,277,277,"Ap. 62","",0,"","","",35,0,0,[],""],["frenk_t4-ap062-04",8,"Estaba la Lloroncita\nplaticándole a Tomás:\nque para pasar trabajos,\nlo mismo es allá que acá.",171,2,4,186,"LA LLORONCITA",0,4,"a",-1,0,-1,0,277,277,"Ap. 62","",0,"","","",10,0,0,[],""],["frenk_t4-ap062-06",8,"Estaba la Lloroncita\nplaticándole a un ranchero:\nque para pasar trabajos,\nlo mismo es el plan que el cerro.",171,2,4,186,"LA LLORONCITA",0,4,"eo",-1,0,-1,0,277,277,"Ap. 62","",0,"","","",10,0,0,[],""],["frenk_t4-ap063-01",8,"Camino real de Colima,\ndicen que yo no lo sé;\ncómo no lo he de saber\nsi en el camino me crié.",173,2,17,186,"CAMINO REAL DE COLIMA",0,4,"e",-1,0,-1,0,277,277,"Ap. 63","",0,"frenk_t3","","",7,0,0,[],""],["frenk_t4-ap063-02",8,"Camino real de Colima,\ntiene mil altos y bajos;\nen compañía de mi chata\nando pasando trabajos,",173,2,17,186,"CAMINO REAL DE COLIMA",0,4,"ao",286,0,-1,0,277,277,"Ap. 63","",0,"","","",7,0,0,[],""],["frenk_t4-ap063-03",8,"Camino real de Colima,\nno me quisiera acordar\nlos trabajos que pasé\nen ese camino real.",173,2,17,186,"CAMINO REAL DE COLIMA",0,4,"a",-1,0,-1,0,277,277,"Ap. 63","",0,"","","",7,0,0,[],""],["frenk_t4-ap065-01",8,"Ay, qué bonitos\nson “Los enanos”\ncuando lo bailan\nlos mexicanos.",171,2,4,186,"LOS ENANOS",6,4,"ao",318,0,-1,0,278,278,"Ap. 65","",0,"","","",6,0,0,[],""],["frenk_t4-ap065-02",8,"Son, son,\nson los enanos\nchiquitititos\ny veteranos.",171,2,4,186,"LOS ENANOS",3,4,"ao",318,0,-1,0,278,278,"Ap. 65","",0,"","","",0,0,0,[],""],["frenk_t4-ap065-03",8,"Ay, qué bonitos\nson “Los enanos”\ncuando lo bailan\nveracruzanos.",171,2,4,186,"LOS ENANOS",6,4,"ao",318,0,-1,0,278,278,"Ap. 65","",0,"","","",6,0,0,[],""],["frenk_t4-ap065-04",8,"Son, son,\nson los enanos\nchiquitititos\nveracruzanos.",171,2,4,186,"LOS ENANOS",3,4,"ao",318,0,-1,0,278,278,"Ap. 65","",0,"","","",0,0,0,[],""],["frenk_t4-ap065-05",8,"Ay, qué bonitos\nson “Los enanos\"\ncuando lo bailan\nprimos hermanos.",171,2,4,186,"LOS ENANOS",6,4,"ao",318,0,-1,0,278,278,"Ap. 65","",0,"","","",6,0,0,[],""],["frenk_t4-ap065-06",8,"Son, son,\nson los enanos\ncortos de pies,\nlargos de manos.",171,2,4,186,"LOS ENANOS",3,4,"ao",318,0,-1,0,278,278,"Ap. 65","",0,"","","",0,0,0,[],""],["frenk_t4-ap065-07",8,"Los enanitos\nya se enojaron\nporque a la enana\nla pellizcaron.",171,2,4,186,"LOS ENANOS",6,4,"ao",41,0,-1,0,278,278,"Ap. 65","",0,"","","",10,0,0,[],""],["frenk_t4-ap065-09",8,"Ay, qué bonitos\nlos enanitos\ncuando los bailan\nagachaditos.",171,2,4,186,"LOS ENANOS",6,4,"io",254,0,-1,0,278,278,"Ap. 65","",0,"frenk_t3","","",6,0,0,[],""],["frenk_t4-ap065-11",8,"Los enanitos\nvienen del río\npidiendo capa,\nque tienen frío.",171,2,4,186,"LOS ENANOS",6,4,"io",3,0,-1,0,278,278,"Ap. 65","",0,"","","",10,0,0,[],""],["frenk_t4-ap065-13",8,"Los enanitos\nya se enojaron\nporque a su enana\nse la robaron.",171,2,4,186,"LOS ENANOS",6,4,"ao",41,0,-1,0,278,278,"Ap. 65","",0,"","","",10,0,0,[],""],["frenk_t4-ap065-15",8,"Los enanitos\nquieren zapatos;\nque se los compren\nen Catemaco.",171,2,4,186,"LOS ENANOS",6,4,"ao",-1,0,-1,0,278,278,"Ap. 65","",0,"","","",10,0,0,[],""],["frenk_t4-ap065-17",8,"Los enanitos\nquieren camisa;\nque se la compren\ncon longaniza.",171,2,4,186,"LOS ENANOS",6,4,"ia",420,0,-1,0,278,278,"Ap. 65","",0,"","","",10,0,0,[],""],["frenk_t4-ap065-19",8,"Los enanitos\nya quieren ropa;\nque se la compren\nen Europa.",171,2,4,186,"LOS ENANOS",6,4,"oa",608,0,-1,0,278,278,"Ap. 65","",0,"","","",10,0,0,[],""],["frenk_t4-ap065-21",8,"Los enanitos\nquieren calzones;\nque se los compren\ncon chicharrones.",171,2,4,186,"LOS ENANOS",6,4,"oe",-1,0,-1,0,278,278,"Ap. 65","",0,"","","",10,0,0,[],""],["frenk_t4-ap065-23",8,"Los enanitos\nquieren calzones\nporque de atrás\nson cachetones.",171,2,4,186,"LOS ENANOS",6,4,"oe",34,0,-1,0,278,278,"Ap. 65","",0,"","","",10,0,0,[],""],["frenk_t4-ap065-25",8,"Los enanitos\nde Nacajuca\nson chiquititos\ncomo una yuca.",171,2,4,186,"LOS ENANOS",6,4,"ua",607,0,-1,0,278,278,"Ap. 65","",0,"","","",10,0,0,[],""],["frenk_t4-ap065-27",8,"Los enanitos\nquieren sombrero;\nque se los compren\nlos compañeros.",171,2,4,186,"LOS ENANOS",6,4,"eo",-1,0,-1,0,279,279,"Ap. 65","",0,"","","",10,0,0,[],""],["frenk_t4-ap066-01",8,"Anda, Juanito,\ncabeza de araña,\nanda y reparte\npedazos de caña.",166,2,-1,186,"CANTOS DE POSADAS",6,4,"aa",213,0,-1,0,279,279,"Ap. 66","",0,"frenk_t3","","",3,0,0,[],""],["frenk_t4-ap066-02",8,"Anda, Lupita,\nno te dilates\ncon la canasta\nde los cacahuates,",166,2,-1,186,"CANTOS DE POSADAS",6,4,"ae",283,0,-1,0,279,279,"Ap. 66","",0,"","","",1,0,0,[],""],["frenk_t4-ap066-03",8,"Anda, Juanito,\nsal del rincón\ncon la canasta\nde la colación.",166,2,-1,186,"CANTOS DE POSADAS",6,4,"o",31,0,-1,0,279,279,"Ap. 66","",0,"","","",3,0,0,[],""],["frenk_t4-ap069-02",8,"Estaban las tres pelonas\nsentadas en un balcón,\ny una a la otra se decían:\n“iQue viva Alvaro Obregón!”",179,2,26,186,"LAS TRES PELONAS",0,4,"o",31,0,-1,0,280,280,"Ap. 69","",0,"","","",8,0,0,[],""],["frenk_t4-ap070-01",8,"Quien te puso Petenera\nseguro no estaba en sí,\nque tú te habías de llamar\n“la Maldición para mí”.",171,2,4,186,"LA PETENERA",0,4,"i",23,0,-1,0,280,280,"Ap. 70","",0,"frenk_t2","","",3,0,0,[],""],["frenk_t4-ap070-02",8,"“La Petenera”, señores,\nno hay quien la sepa cantar,\nsólo los marineritos\nque navegan por el mar.",171,2,4,186,"LA PETENERA",0,4,"a",21,0,-1,0,280,280,"Ap. 70","",0,"","","",1,0,0,[],""],["frenk_t4-ap070-03",8,"—Petenera, Petenera,\ndame de tu palo un ramo.\n-¿Quién te ha dicho, picarona,\nque Petenera me llamo?",171,2,4,186,"LA PETENERA",0,4,"ao",100,0,-1,0,280,280,"Ap. 70","",0,"","","",2,0,0,[],""],["frenk_t4-ap070-04",8,"Quien te puso Petenera\nno te supo poner nombre;\nque tú te habías de llamar\n“la Perdición de los hombres”.",171,2,4,186,"LA PETENERA",0,4,"oe",-1,0,-1,0,280,280,"Ap. 70","",0,"","","",3,0,0,[],""],["frenk_t4-ap070-05",8,"¡Ay!, Sola, Soledad,\nSoledad, llévame a ver\na la casa de mi madre,\nque era todo mi querer,\ny después de haberla visto\nnos volveremos a ver.",171,2,4,186,"LA PETENERA",9,6,"e",20,0,-1,0,280,280,"Ap. 70","",0,"","","",1,0,0,[],""],["frenk_t4-ap072-01",8,"San Señor de Chalma,\nno venimos un año\nporque lo mojiere\nestábanlo borracho.",166,2,-1,186,"CANCIÓN AL SEÑOR DE CHALMA",0,4,"ao",-1,0,-1,0,281,281,"Ap. 72","",0,"","","",4,0,0,[],""],["frenk_t4-ap072-02",8,"San Señor de Chalma,\nno venimos un año\nporque lo mojiere\nno tenía enagua blanca.",166,2,-1,186,"CANCIÓN AL SEÑOR DE CHALMA",5,4,"aa",-1,0,-1,0,281,281,"Ap. 72","",0,"","","",4,0,0,[],""],["frenk_t4-ap072-03",8,"San Señor de Chalma,\ndánolos tu reino,\nya que en esta vida\ntamos tan pelados.",166,2,-1,186,"CANCIÓN AL SEÑOR DE CHALMA",5,4,"ao",-1,0,-1,0,281,281,"Ap. 72","",0,"","","",4,0,0,[],""],["frenk_t4-ap072-04",8,"San Señor de Chalma,\nque venga la agüita\npa que la semilla\nnos lo dé el frotito.",166,2,-1,186,"CANCIÓN AL SEÑOR DE CHALMA",5,4,"io",-1,0,-1,0,281,281,"Ap. 72","",0,"","","",4,0,0,[],""],["frenk_t4-ap073-01",8,"Huapanguero, huapanguero,\nhuapanguero, huapanguerito:\nsi quieres tener mi amistad,\ncántame este huapanguito.",171,2,4,186,"HUAPANGUERO, HUAPANGUERITO",0,4,"io",119,0,-1,0,281,281,"Ap. 73","",0,"","","",1,0,0,[],""],["frenk_t4-ap073-02",8,"Fandanguero, fandanguero,\nfandanguero, fandanguerito:\nsi quieres tener mi cariño,\nbáilame este fandanguito.",171,2,4,186,"HUAPANGUERO, HUAPANGUERITO",0,4,"io",-1,0,-1,0,281,281,"Ap. 73","",0,"","","",2,0,0,[],""],["frenk_t4-ap073-03",8,"Huapanguero, huapanguerito,\nhuapanguero, ¡ay!, qué bonito;\nhuapanguero, ¡ay!, ya merito\nse acaba mi huapanguito.",171,2,4,186,"HUAPANGUERO, HUAPANGUERITO",0,4,"io",119,0,-1,0,281,281,"Ap. 73","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap073-04",8,"Doña Clara, doña Clara,\ndoña Clara, doña Clarita:\nsi quieres que yo te prefiera,\ndame un beso en la boquita.",171,2,4,186,"HUAPANGUERO, HUAPANGUERITO",0,4,"ia",50,0,-1,0,281,281,"Ap. 73","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap073-05",8,"No te alejes, no te alejes,\nno te alejes, doña Clarita,\nque van a empezar a bailar\neste son huapanguerito.",171,2,4,186,"HUAPANGUERO, HUAPANGUERITO",5,4,"io",-1,0,-1,0,281,281,"Ap. 73","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap073-06",8,"Campirana, campirana,\ncampirana, campiranita:\neres flor que por la mañana\nhueles a poma-rosita.",171,2,4,186,"HUAPANGUERO, HUAPANGUERITO",1,4,"ia",50,0,-1,0,281,281,"Ap. 73","",0,"","","",2,0,0,[],""],["frenk_t4-ap073-07",8,"Mi huapango se acabó,\nse acabó mi huapanguerito,\npero pronto ha de regresar\ncon su son tan sabrosito.",171,2,4,186,"HUAPANGUERO, HUAPANGUERITO",0,4,"io",119,0,-1,0,281,281,"Ap. 73","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap074-01",8,"Rema, guarecita, rema,\nrema para San Miguel;\nya se reventó la reata,\n¿con qué otra la lazaré?",166,2,-1,186,"LA GUARECITA I",0,4,"e",-1,0,-1,0,281,281,"Ap. 74","",0,"frenk_t2","","",8,0,0,[],""],["frenk_t4-ap074-03",8,"Rema, guarecita, rema\ny rema como te enseño;\na nadie le abras la puerta,\nsólo a mí, que soy tu dueño.",166,2,-1,186,"LA GUARECITA I",0,4,"eo",138,0,-1,0,281,281,"Ap. 74","",0,"frenk_t1","","",8,0,0,[],""],["frenk_t4-ap074-04",8,"Rema, guarecita, rema,\nrema para San Miguel;\nque unos tumban el panal\ny otros se comen la miel.",166,2,-1,186,"LA GUARECITA I",0,4,"e",32,0,-1,0,281,281,"Ap. 74","",0,"","","",8,0,0,[],""],["frenk_t4-ap074-05",8,"Rema, guarecita, rema\ny rema como es costumbre;\nyo soy como los rancheros:\nllegando y haciendo lumbre.",166,2,-1,186,"LA GUARECITA I",0,4,"ue",181,0,-1,0,281,281,"Ap. 74","",0,"","","",8,0,0,[],""],["frenk_t4-ap074-06",8,"Rema, guarecita, rema\ny rema y vamos remando;\nno todos han de saber\nque nos estamos amando.",166,2,-1,186,"LA GUARECITA I",0,4,"ao",33,0,-1,0,281,281,"Ap. 74","",0,"","","",8,0,0,[],""],["frenk_t4-ap075-01",8,"La niña que a mí me quiera\nha de ser al gusto mío;\nha de salir a la puerta\ncuando yo le haga:\n“FÍO, fío, fío, fío, fío.”",168,2,11,186,"EL AMOR Y EL DESAFÍO",7,5,"io",3,0,-1,0,282,282,"Ap. 75","",0,"","","",2,0,0,[],""],["frenk_t4-ap075-02",8,"A la noche voy a verte,\nexpuesto al agua y al frío;\ndime si estarás despierta\npara cuando yo te haga:\n“FÍO, fío, fío, fío, fío.”",168,2,11,186,"EL AMOR Y EL DESAFÍO",7,5,"io",3,0,-1,0,282,282,"Ap. 75","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap075-03",8,"Ya no paso por tu casa\npor el respeto a tu tío;\nallí me quedo en la esquina\ny me quedo haciéndole:\n“Fío, fío, fío, fío, fío.”",168,2,11,186,"EL AMOR Y EL DESAFÍO",7,5,"io",3,0,-1,0,282,282,"Ap. 75","",0,"","","",2,0,0,[],""],["frenk_t4-ap075-04",8,"Antenoche vi a tu padre\ny me citó a desafío;\nel tonto se fue adelante\ny yo haciéndole:\n“Fío, fío, fío, fío, fío.”",168,2,11,186,"EL AMOR Y EL DESAFÍO",7,5,"io",3,0,-1,0,282,282,"Ap. 75","",0,"","","",1,0,0,[],""],["frenk_t4-ap075-05",8,"Aquí se acaban los versos\ndel amor y el desafío;\nla niña se fue con otro\ny yo me quedé chiflando:\n“FÍO, fío, fío, fío, fío.”",168,2,11,186,"EL AMOR Y EL DESAFÍO",7,5,"io",3,0,-1,0,282,282,"Ap. 75","",0,"","","",3,0,0,[],""],["frenk_t4-ap076-01",8,"Se confunde el pensamiento\ncuando miro tu figura;\nme quedo súpito, atento,\nal contemplar tu ternura,\ntu boquita y tu talento.",166,2,-1,186,"SE CONFUNDE EL PENSAMIENTO",7,5,"eo",94,0,-1,0,282,282,"Ap. 76","",0,"","","",1,0,0,[],""],["frenk_t4-ap076-02",8,"Tu boquita y tu talento\nme tienen loco, mujer;\ncuando te miro, yo siento\ninexplicable placer,\nterminando el sufrimiento.",166,2,-1,186,"SE CONFUNDE EL PENSAMIENTO",7,5,"eo",94,0,-1,0,282,282,"Ap. 76","",0,"","","",1,0,0,[],""],["frenk_t4-ap076-03",8,"Terminando el sufrimiento\nque tengo al no contemplarte,\ncuando te miro, yo siento\ngran deseo de coronarte\ncon astros del firmamento.",166,2,-1,186,"SE CONFUNDE EL PENSAMIENTO",7,5,"eo",94,0,-1,0,282,282,"Ap. 76","",0,"","","",1,0,0,[],""],["frenk_t4-ap076-04",8,"Con astros del firmamento\nquisiera adornar tu frente;\nasí viviría contento\nporque te amo tiernamente,\ndueña de mi pensamiento.",166,2,-1,186,"SE CONFUNDE EL PENSAMIENTO",7,5,"eo",94,0,-1,0,282,282,"Ap. 76","",0,"","","",1,0,0,[],""],["frenk_t4-ap077-01",8,"Marcando con el compás\ncon que he de pasar mi vida,\nalgún día recordarás,\nfalsa, malagradecida,\nque el malhaya lo darás\ncuando te encuentres perdida.",175,2,6,186,"EL TACONCITO II",9,6,"ia",37,0,-1,0,282,282,"Ap. 77","",0,"","","",2,0,0,[],""],["frenk_t4-ap077-02",8,"Cuando te encuentres perdida\npor tu falso proceder,\nirás muy arrepentida\nqueriendo retroceder;\nes imposible, mi vida,\nque vuelvas a mi poder.",175,2,6,186,"EL TACONCITO II",9,6,"e",20,0,-1,0,282,282,"Ap. 77","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap077-03",8,"Que vuelvas a mi poder,\ndirás: “¿Con qué corazón\nhe de volver a querer?”,\nrecordando tu traición;\neres muy falsa mujer,\nno quiero tu estimación.",175,2,6,186,"EL TACONCITO II",9,6,"o",31,0,-1,0,283,283,"Ap. 77","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap077-04",8,"No quiero tu estimación\npor tu mal procedimiento;\neres de mala intención,\ntienes muy mal pensamiento;\nheriste mi corazón,\nlo dejas en sufrimiento.",175,2,6,186,"EL TACONCITO II",9,6,"eo",94,0,-1,0,283,283,"Ap. 77","",0,"","","",2,0,0,[],""],["frenk_t4-ap078-01",8,"Con aquellas mancuernillas\na los dos los mancornaron\ncuando el velo les echaron\nen aquellas barandillas.",175,2,6,186,"LOS DESPOSORIOS",11,4,"ia",294,0,-1,0,283,283,"Ap. 78","",0,"","","",1,0,0,[],""],["frenk_t4-ap078-02",8,"Fue meritorio y glorioso,\ngloriosa fue la apariencia,\napariencia de obediencia,\nobediencia de la esposa;\nla esposa quedó gustosa,\ngustosa dio maravillas,\nmaravillas de rodillas,\nde rodillas recibió;\nsu estado hoy lo aseguró\ncon aquellas mancuernillas.",175,2,6,186,"LOS DESPOSORIOS",18,10,"ia",294,0,-1,0,283,283,"Ap. 78","",0,"","","",1,0,0,[],""],["frenk_t4-ap078-03",8,"El padre tomó de manos,\nde manos a ambos dos;\nambos dos fueron con Dios,\ncon Dios, por todos cristianos,\ncristianos los dos humanos;\nhumanos dos se casaron,\nse casaron y quedaron,\nquedaron para servirse,\npara servirse y unirse;\na los dos los mancornaron.",175,2,6,186,"LOS DESPOSORIOS",18,10,"ao",41,0,-1,0,283,283,"Ap. 78","",0,"","","",1,0,0,[],""],["frenk_t4-ap078-04",8,"La Virgen María bajó,\nbajó a ver el desposorio;\nel desposorio notorio,\nnotorio el día que se vio;\nse vio el estado y quedó,\nquedó en lo que lo tomaron,\ntomaron luz y velaron,\nvelaron con alegría;\nbajó la Virgen María\ncuando el velo les echaron.",175,2,6,186,"LOS DESPOSORIOS",18,10,"ao",41,0,-1,0,283,283,"Ap. 78","",0,"","","",1,0,0,[],""],["frenk_t4-ap078-05",8,"El Dios todopoderoso,\npoderoso siempre ha sido,\nha sido quien los ha unido,\nunido en día tan dichoso;\ndichoso quedó el esposo,\nel esposo a quien te humillas,\nte humillas, y de rodillas,\nde rodillas en el suelo;\nel padre les puso el velo\nen aquellas barandillas.",175,2,6,186,"LOS DESPOSORIOS",18,10,"ia",294,0,-1,0,283,283,"Ap. 78","",0,"","","",1,0,0,[],""],["frenk_t4-ap080-01",8,"Rosita de olivo,\nblanca flor de azahar,\nme das un besito\ncuando haya lugar.",166,2,-1,186,"ROSITA DE OLIVO",0,4,"a",21,0,-1,0,284,284,"Ap. 80","",0,"","","",1,0,0,[],""],["frenk_t4-ap080-02",8,"Cuando haya lugar\nme mandas decir;\nyo soy hombrecito\ny te puedo cumplir.",166,2,-1,186,"ROSITA DE OLIVO",0,4,"i",157,0,-1,0,284,284,"Ap. 80","",0,"","","",1,0,0,[],""],["frenk_t4-ap080-03",8,"Me salgo a la esquina\npa verla pasar,\npa ver si se duele\nde verme llorar.",166,2,-1,186,"ROSITA DE OLIVO",0,4,"a",21,0,-1,0,284,284,"Ap. 80","",0,"","","",1,0,0,[],""],["frenk_t4-ap080-04",8,"De verme llorar\nella se dolió;\ndespués me pregunta\npor quién lloro yo.",166,2,-1,186,"ROSITA DE OLIVO",0,4,"o",2,0,-1,0,284,284,"Ap. 80","",0,"","","",1,0,0,[],""],["frenk_t4-ap080-05",8,"Y yo le contesto\ncon grande dolor:\n“No lloro por nadie,\nsólo por tu amor”.",166,2,-1,186,"ROSITA DE OLIVO",0,4,"o",72,0,-1,0,284,284,"Ap. 80","",0,"","","",1,0,0,[],""],["frenk_t4-ap080-06",8,"Sólo por tu amor\nme voy a morir;\nte mando una carta\ny te mando decir.",166,2,-1,186,"ROSITA DE OLIVO",0,4,"i",157,0,-1,0,284,284,"Ap. 80","",0,"","","",1,0,0,[],""],["frenk_t4-ap081-01",8,"Licencia pedimos,\nfamilia decente,\nsi los he ofendido,\ndispense a mi gente.",171,2,4,186,"NARANJAS Y LIMAS",0,4,"ee",15,0,-1,0,284,284,"Ap. 81","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap081-02",8,"Ya se fue este año,\nya vino otro nuevo;\nadiós Manuelito’\nal año nos vemos.",171,2,4,186,"NARANJAS Y LIMAS",6,4,"eo",-1,0,-1,0,284,284,"Ap. 81","",0,"","","",1,0,0,[],""],["frenk_t4-ap081-03",8,"Dispense a mi gente\nque llegó a su casa;\nsi son religiosas,\noigan lo que pasa.",171,2,4,186,"NARANJAS Y LIMAS",0,4,"aa",123,0,-1,0,284,284,"Ap. 81","",0,"","","",1,0,0,[],""],["frenk_t4-ap081-05",8,"Que nació el Mesías\ncual era esperado,\ny el profeta Elias\nya lo había anunciado.",171,2,4,186,"NARANJAS Y LIMAS",0,4,"ao",14,0,-1,0,284,284,"Ap. 81","",0,"","","",1,0,0,[],""],["frenk_t4-ap081-07",8,"Que nació en Belén\nel Dios verdadero,\ny a verlo también\nlos magos vinieron.",171,2,4,186,"NARANJAS Y LIMAS",0,4,"eo",-1,0,-1,0,284,284,"Ap. 81","",0,"","","",1,0,0,[],""],["frenk_t4-ap081-08",8,"Los magos vinieron\nde lejanas tierras\n....................\nhabía dos estrellas.",171,2,4,186,"NARANJAS Y LIMAS",3,4,"ea",-1,0,-1,0,284,284,"Ap. 81","",0,"","","",1,0,0,[],""],["frenk_t4-ap081-10",8,"Había dos estrellas\nque es lo que alumbraba,\ncon su luz tan bella\ndonde el niño estaba.",171,2,4,186,"NARANJAS Y LIMAS",0,4,"aa",28,0,-1,0,284,284,"Ap. 81","",0,"","","",1,0,0,[],""],["frenk_t4-ap081-11",8,"Donde el niño estaba\ncantan los pastores,\npor quien preguntaba\nel tirano Herodes.",171,2,4,186,"NARANJAS Y LIMAS",0,4,"oe",-1,0,-1,0,284,284,"Ap. 81","",0,"","","",1,0,0,[],""],["frenk_t4-ap082-01",8,"En noche lóbrega, galante incógnito\nlas calles céntricas atravesó,\ny bajo clásica ventana dórica\ntendió su cítara y así cantó:",166,2,-1,187,"VIRGEN PURÍSIMA",3,4,"o",2,0,-1,0,285,285,"Ap. 82","",0,"","","",1,0,0,[],""],["frenk_t4-ap082-02",8,"“Virgen purísima, de faz angélica,\nque en blancas sábanas durmiendo estás;\ndespierta y óyeme: entre mis cánticos,\nsuspiros prófugos escucharás.”",166,2,-1,187,"VIRGEN PURÍSIMA",3,4,"a",51,0,-1,0,285,285,"Ap. 82","",0,"","","",1,0,0,[],""],["frenk_t4-ap082-03",8,"La bella sílfide, que oyó mis cánticos,\nentre sus sábanas se rebujó\ny dijo: “¡Cáscaras! y a este murciélago,\ny a este romántico no le abro yo.",166,2,-1,187,"VIRGEN PURÍSIMA",3,4,"o",2,0,-1,0,285,285,"Ap. 82","",0,"","","",1,0,0,[],""],["frenk_t4-ap083-01",8,"Y he llegado con júbilo inábido\nal dintel de tu morada espléndida;\nsólo quiero de ti el beneplácito\npara darte mi razón espléndida.",166,2,-1,187,"HE LLEGADO CON JÚBILO INÁBIDO",3,4,"ea",-1,0,-1,0,285,285,"Ap. 83","",0,"","","",1,0,0,[],""],["frenk_t4-ap083-02",8,"Es muy cierto que soy un inábido\nque ante el vulgo yo no tengo mérito,\npero te ruego, con lágrimas triágicas\nque me des tu amor puro y cándido.",166,2,-1,187,"HE LLEGADO CON JÚBILO INÁBIDO",3,4,"ao",-1,0,-1,0,285,285,"Ap. 83","",0,"","","",1,0,0,[],""],["frenk_t4-ap083-03",8,"Siempre busco un lugar estratégico\npara hablarte de un dialecto gráfico,\nporque tú eres el ángel doméstico\nque te debo rendir, aunque mínimo.",166,2,-1,187,"HE LLEGADO CON JÚBILO INÁBIDO",3,4,"io",-1,0,-1,0,285,285,"Ap. 83","",0,"","","",1,0,0,[],""],["frenk_t4-ap083-04",8,"Ya me voy, jovencita, perdóname;\nya no quiero llegar a esa prórroga,\nsólo he venido, a través de mis cánticos,\npara darte mi adiós por vez última.",166,2,-1,187,"HE LLEGADO CON JÚBILO INÁBIDO",3,4,"ua",-1,0,-1,0,285,285,"Ap. 83","",0,"","","",1,0,0,[],""],["frenk_t4-ap084-01",8,"Me quisiera comer un panecillo\ncon azúcar y canela, muy caliente;\nme quisiera arrancar hasta los dientes,\ntan sólo por tu amor.",176,2,3,187,"LA MARIANA O EL FISICO",3,4,"o",-1,0,-1,0,285,285,"Ap. 84","",0,"","","",1,0,0,[],""],["frenk_t4-ap084-02",8,"Por ti, bella Mariana,\npor ti lo puedo todo;\nal mundo entero, si me mandas,\nte lo pongo de otro modo.",176,2,3,187,"LA MARIANA O EL FISICO",0,4,"oo",261,0,-1,0,285,285,"Ap. 84","",0,"","","",2,0,0,[],""],["frenk_t4-ap084-04",8,"Volaré del uno al otro polo\nimitando los globos aerostáticos,\nhasta encontrar la piedra filosófica,\ncuadrada o triangular.",176,2,3,187,"LA MARIANA O EL FISICO",3,4,"a",-1,0,-1,0,285,285,"Ap. 84","",0,"","","",1,0,0,[],""],["frenk_t4-ap084-07",8,"Porque soy físico, retórico, poético,\nastrónomo, filósofo y político;\nsin duda soy el hombre más científico\nque en el mundo pudo haber.",176,2,3,187,"LA MARIANA O EL FISICO",3,4,"e",-1,0,-1,0,286,286,"Ap. 84","",0,"","","",1,0,0,[],""],["frenk_t4-ap084-08",8,"Por ti, bella Mariana,\na quien debo amar;\nsi la mar se me viniera con sus olas,\nyo la mandaría secar.",176,2,3,187,"LA MARIANA O EL FISICO",3,4,"a",21,0,-1,0,286,286,"Ap. 84","",0,"","","",2,0,0,[],""],["frenk_t4-ap084-11",8,"Haré que los pecados capitales\nsean obra meritoria para el cielo;\nharé que los demonios del infierno\nse salgan a confesar.",176,2,3,187,"LA MARIANA O EL FISICO",3,4,"a",-1,0,-1,0,286,286,"Ap. 84","",0,"","","",1,0,0,[],""],["frenk_t4-ap084-14",8,"Bajaré al fondo del infierno,\nsacaré a los diablos de la cola;\na cada uno le daré yo su pistola\npara ver si saben pelear.",176,2,3,187,"LA MARIANA O EL FISICO",3,4,"a",-1,0,-1,0,286,286,"Ap. 84","",0,"","","",1,0,0,[],""],["frenk_t4-ap085-01",8,"Despierta, hermoso lucero,\nsi acaso dormida estás,\nvuélvete a quedar dormida,\ncon ésta y no digo más.",168,2,11,188,"DESPIERTA, HERMOSO LUCERO. . .",0,4,"a",51,0,-1,0,287,287,"Ap. 85","",0,"","","",2,0,0,[],""],["frenk_t4-ap085-02",8,"He venido a festejar\na vuestra deidad amorosa,\nescucha, ninfa preciosa,\nque ahora voy a empezar:\nvísperas te vengo a dar,\nlos días te los dan enero\nen compañía de febrero;\nvengo a darte el parabién,\npara que me escuches bien,\ndespierta, hermoso lucero.",168,2,11,188,"DESPIERTA, HERMOSO LUCERO. . .",18,10,"eo",38,0,-1,0,287,287,"Ap. 85","",0,"","","",1,0,0,[],""],["frenk_t4-ap085-03",8,"Marzo te ofrece rendido\nel que vivas años mil,\nlo mismo responde abril,\nporque siempre te ha querido;\nmayo quiere, agradecido,\nel que vivas mucho más\ncon gusto, sosiego y paz;\njunio dice: cosa cierta,\nque tú no estarás despierta,\nsi acaso dormida estás.",168,2,11,188,"DESPIERTA, HERMOSO LUCERO. . .",18,10,"a",51,0,-1,0,287,287,"Ap. 85","",0,"","","",1,0,0,[],""],["frenk_t4-ap085-04",8,"Julio te ofrece mil bienes;\nagosto, dos mil placeres\npor el tiempo que vivieres;\nen septiembre todo tienes,\ndesde octubre te previenes,\ny prestándote Dios vida,\nsi tú eres entendida,\nnoviembre es mi desempeño;\nsi no tienes mucho sueño,\nvuélvete a quedar dormida.",168,2,11,188,"DESPIERTA, HERMOSO LUCERO. . .",18,10,"ia",37,0,-1,0,287,287,"Ap. 85","",0,"","","",1,0,0,[],""],["frenk_t4-ap085-05",8,"En fin, diciembre te dice\ncon muchísima lealtad,\nque goces felicidad,\nesto es porque se autorice\ny (Fulano de Tal dice)\ncon amor fino y sagaz:\n—Quédate con Dios y en paz,\ncon muchísima alegría;\nhasta mañana, alma mía.\nCon ésta y no digo más.",168,2,11,188,"DESPIERTA, HERMOSO LUCERO. . .",18,10,"a",51,0,-1,0,287,287,"Ap. 85","",0,"","","",1,0,0,[],""],["frenk_t4-ap086-01",8,"El encanto de mis ojos,\nla gracia de mis tormentos,\nmi alma, por ti he quebrantado\nde Dios, los Diez Mandamientos.",173,2,17,188,"LOS DIEZ MANDAMIENTOS",0,4,"eo",234,0,-1,0,287,287,"Ap. 86","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap086-02",8,"El primero: amar a Dios.\nYo no lo amo como debo\npor estar pensando en ti,\nhermosísimo lucero.",173,2,17,188,"LOS DIEZ MANDAMIENTOS",0,4,"eo",-1,0,-1,0,287,287,"Ap. 86","",0,"","","",2,0,0,[],""],["frenk_t4-ap086-03",8,"Sólo en tu amor considero\ny hago dos mil arrojos;\ninnumerables sonrojos\nhe tenido yo por ti,\nporque tú eres para mí\nel encanto de mis ojos.",173,2,17,188,"LOS DIEZ MANDAMIENTOS",9,6,"oo",99,0,-1,0,288,288,"Ap. 86","",0,"","","",1,0,0,[],""],["frenk_t4-ap086-04",8,"El segundo es no jurar.\nYo mil veces he jurado\nel no comer ni beber\nhasta no verme a tu lado.\nY di si no he quebrantado\nestos Santos Mandamientos,\ny también los Sacramentos\nhe quebrantado por ti,\nporque tú eres para mí\nla gracia de mis tormentos.",173,2,17,188,"LOS DIEZ MANDAMIENTOS",18,10,"eo",234,0,-1,0,288,288,"Ap. 86","",0,"","","",2,0,0,[],""],["frenk_t4-ap086-06",8,"Una naranja me dieron\ny no me la dieron dada;\ncinco me dieron con ella\ny diez para que guardara.",173,2,17,188,"LOS DIEZ MANDAMIENTOS",0,4,"aa",-1,0,-1,0,288,288,"Ap. 86","",0,"","","",2,0,0,[],""],["frenk_t4-ap086-07",8,"El tercero, que es la misa,\nno la oigo con devoción\npor estar pensando en ti,\ndueña de mi corazón.\nDi si no es gran sinrazón\nque hasta de Dios me he olvidado,\nsabiendo que es gran pecado\nno amar a nuestros creadores,\nque hasta en mis oraciones,\nmi alma, por ti he quebrantado.",173,2,17,188,"LOS DIEZ MANDAMIENTOS",18,10,"ao",14,0,-1,0,288,288,"Ap. 86","",0,"","","",2,0,0,[],""],["frenk_t4-ap086-08",8,"El cuarto: que yo el respeto\na mis padres les perdí,\nsólo por amarte a ti\nen público y en secreto.\nTú viste que hubo de mí\nsemejantes argumentos.\n¡Qué de chismes, qué de cuentos!\nque yo a mis padres largué,\ny ahí fue onde quebranté\nde Dios, los Diez Mandamientos.",173,2,17,188,"LOS DIEZ MANDAMIENTOS",18,10,"eo",234,0,-1,0,288,288,"Ap. 86","",0,"","","",1,0,0,[],""],["frenk_t4-ap087-02",8,"El segundo es no jurar;\nyo mil veces he jurado\nel no comer ni beber\nhasta no estar a tu lado.",190,2,20,188,"LOS MANDAMIENTOS",0,4,"ao",14,0,-1,0,288,288,"Ap. 87","",0,"","","",2,0,0,[],""],["frenk_t4-ap087-03",8,"El tercero es que la misa\nno la oigo con devoción,\nporque tengo puesto en ti\nalma, vida y corazón.",190,2,20,188,"LOS MANDAMIENTOS",0,4,"o",31,0,-1,0,288,288,"Ap. 87","",0,"","","",1,0,0,[],""],["frenk_t4-ap087-04",8,"El cuarto es que honre a mis padres;\nla obediencia les perdí,\nen público y en secreto,\npor estar pensando en ti.",190,2,20,188,"LOS MANDAMIENTOS",0,4,"i",23,0,-1,0,288,288,"Ap. 87","",0,"","","",1,0,0,[],""],["frenk_t4-ap087-05",8,"El quinto, que es no matar,\nese no lo he quebrantado,\n(pero) alevoso he de matar\nal que encontrare a tu lado.",190,2,20,188,"LOS MANDAMIENTOS",1,4,"ao",14,0,-1,0,288,288,"Ap. 87","",0,"","","",2,0,0,[],""],["frenk_t4-ap087-06",8,"De ese sexto mandamiento\nyo me debo de acusar,\nporque con el pensamiento\nhe llegado hasta pecar.",190,2,20,188,"LOS MANDAMIENTOS",1,4,"a",21,0,-1,0,288,288,"Ap. 87","",0,"","","",1,0,0,[],""],["frenk_t4-ap087-07",8,"¡El séptimo, no hurtarás!\nEse sí que he quebrantado,\nporque pretendí robarte,\ncorazón apasionado.",190,2,20,188,"LOS MANDAMIENTOS",0,4,"ao",14,0,-1,0,288,288,"Ap. 87","",0,"","","",3,0,0,[],""],["frenk_t4-ap087-08",8,"El octavo es: no levante\nnunca falso testimonio.\nDe ése sí no hay quien me acuse,\n¡pues me acusará el demonio!",190,2,20,188,"LOS MANDAMIENTOS",0,4,"oo",169,0,-1,0,288,288,"Ap. 87","",0,"","","",1,0,0,[],""],["frenk_t4-ap087-09",8,"El noveno es no desear\nla mujer de otro marido.\nPero yo siempre he deseado,\nvida mía, estar contigo.",190,2,20,188,"LOS MANDAMIENTOS",0,4,"io",-1,0,-1,0,288,288,"Ap. 87","",0,"","","",1,0,0,[],""],["frenk_t4-ap087-10",8,"El décimo, no desear\nlas cosas que son ajenas:\nquerida, de que te miro\nse acrecientan más mis penas.",190,2,20,188,"LOS MANDAMIENTOS",0,4,"ea",62,0,-1,0,288,288,"Ap. 87","",0,"","","",2,0,0,[],""],["frenk_t4-ap087-11",8,"Y son los diez Mandamientos\nlos que se encierran en dos:\nen quererte y adorarte\ny en vivir juntos los dos.",190,2,20,188,"LOS MANDAMIENTOS",0,4,"o",-1,0,-1,0,288,288,"Ap. 87","",0,"","","",1,0,0,[],""],["frenk_t4-ap088-01",8,"El primero: amar a Dios.\nNo lo aman de corazón.\nÉstas son las poblanitas\nde nuestra heroica nación.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",0,4,"o",31,0,-1,0,289,289,"Ap. 88","",0,"","","",2,0,0,[],""],["frenk_t4-ap088-02",8,"El segundo: no jurar.\nY lo hacen cada ratito,\npues no origina otra cosa\nel malvado aguardientito.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",0,4,"io",119,0,-1,0,289,289,"Ap. 88","",0,"","","",2,0,0,[],""],["frenk_t4-ap088-03",8,"El tercero es que las fiestas\nno saben santificar,\npues en ese día ayunan\nno más por irse a embriagar.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",0,4,"a",21,0,-1,0,289,289,"Ap. 88","",0,"","","",1,0,0,[],""],["frenk_t4-ap088-04",8,"honrar a sus padres.\nNo lo hacen con perfección,\npues lo principal les falta,\nque es la buena educación.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",0,4,"o",31,0,-1,0,289,289,"Ap. 88","",0,"","","",1,0,0,[],""],["frenk_t4-ap088-05",8,"No matarás, dice el quinto.\nPero esto es muy poca cosa;\nlo que matan las arañas\nes del prójimo las bolsas.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",0,4,"oa",-1,0,-1,0,289,289,"Ap. 88","",0,"","","",1,0,0,[],""],["frenk_t4-ap088-06",8,"Y del sexto, ya lo vemos,\nque siempre andan las arañas\npor los portales buscando,\nesto lo hacen con más ganas.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",0,4,"aa",-1,0,-1,0,289,289,"Ap. 88","",0,"","","",1,0,0,[],""],["frenk_t4-ap088-07",8,"El séptimo; no hurtarás.\nEsto lo hacen con empeño,\npues no hacen las mexicanas\nmás que cogerse lo ajeno.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",0,4,"eo",-1,0,-1,0,289,289,"Ap. 88","",0,"","","",3,0,0,[],""],["frenk_t4-ap088-08",8,"Octavo: no levantar\nningún falso testimonio.\nEsto hacen las tapatías,\ntentadas por el demonio.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",0,4,"oo",169,0,-1,0,289,289,"Ap. 88","",0,"","","",1,0,0,[],""],["frenk_t4-ap088-09",8,"El noveno: no desear\nninguna mujer ajena.\nEsto sí que no han de hacer,\neso fuera una tontera.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",0,4,"ea",-1,0,-1,0,289,289,"Ap. 88","",0,"","","",1,0,0,[],""],["frenk_t4-ap088-10",8,"El décimo, no desear\nlo que otro tiene. Por eso\nuna a la otra se pelea\no se agarran del pescuezo.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",0,4,"eo",345,0,-1,0,289,289,"Ap. 88","",0,"","","",2,0,0,[],""],["frenk_t4-ap088-11",8,"Aquestos Diez Mandamientos\nen dos deben encerrarse:\nen vivir con precaución,\ny de la araña no fiarse.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",0,4,"ae",250,0,-1,0,289,289,"Ap. 88","",0,"","","",1,0,0,[],""],["frenk_t4-ap088-12",8,"Estos son Los Mandamientos\nque acostumbran las arañas,\npor sus malos pensamientos\ny también sus malas mañas.",166,2,-1,188,"LOS MANDAMIENTOS QUE REZAN LAS POBLANAS, TAPATÍAS Y MEXICANAS",1,4,"aa",42,0,-1,0,289,289,"Ap. 88","",0,"","","",1,0,0,[],""],["frenk_t4-ap089-01",8,"Estar ausente es morir\npara quien sabe querer;\nmejor no deseo vivir\nsi ya nunca te he de ver.",171,2,4,188,"LAS HORAS",1,4,"e",20,0,-1,0,289,289,"Ap. 89","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap089-02",8,"De día y de noche cautivo\nlas horas paso contando,\nsólo en ti vivo pensando\ny sólo por ti deliro.\nA la una es un suspiro\npara empezar a sufrir,\na las dos vuelvo a seguir,\na las tres no hallo consuelo;\npor un tormento y desvelo\nestar ausente es morir.",171,2,4,188,"LAS HORAS",18,10,"i",157,0,-1,0,289,289,"Ap. 89","",0,"","","",1,0,0,[],""],["frenk_t4-ap089-03",8,"A las cuatro hago mi suerte,\nvas a recordar mi amor;\na las cinco es el dolor,\ncasi me lleva a la muerte;\na las seis desearía verte\ny como no puede ser,\npor distante el proceder\ndobla y redobla sus penas;\nahí se expresa esta cadena\npara quien sabe querer.",171,2,4,188,"LAS HORAS",18,10,"e",20,0,-1,0,289,289,"Ap. 89","",0,"","","",1,0,0,[],""],["frenk_t4-ap089-04",8,"A las siete mi atención\nya me hace pasar enojos,\nentonces vierten mis ojos\nlágrimas del corazón;\na las ocho mi ascensión\nque nos ampara al morir,\na las nueve resistir\nno puedo tanta amargura,\ny si esta pena me dura\nmejor no deseo vivir.",171,2,4,188,"LAS HORAS",18,10,"i",157,0,-1,0,290,290,"Ap. 89","",0,"","","",1,0,0,[],""],["frenk_t4-ap089-05",8,"Vuelvo a seguir a las diez\na tenerte más presente\ny en mi memoria tenerte\nquién sabe si de una vez;\na las once ya no es\ntodo como había de ser,\na las doce el padecer\naumenta más mi pereza;\ndeseo morir de tristeza\nsi ya nunca te he de ver.",171,2,4,188,"LAS HORAS",18,10,"e",20,0,-1,0,290,290,"Ap. 89","",0,"","","",1,0,0,[],""],["frenk_t4-ap090-01",8,"Adiós mis cuarenta cartas\nde mi baraja querida,\npor ti perdí mi dinero\ny a mi negra consentida.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",0,4,"ia",37,0,-1,0,290,290,"Ap. 90","",0,"","","",1,0,0,[],""],["frenk_t4-ap090-02",8,"Adiós, baraja querida,\nceniza te has de volver;\naunque me cuesta la vida\nno le ruego a esa mujer.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",1,4,"e",20,0,-1,0,290,290,"Ap. 90","",0,"","","",1,0,0,[],""],["frenk_t4-ap090-03",8,"También la baraja siente\ncuando le sacan el as;\ncómo no he de sentir yo (mi vida),\nsi me dejas y te vas.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",3,4,"a",51,0,-1,0,290,290,"Ap. 90","",0,"","","",10,0,0,[],""],["frenk_t4-ap090-04",8,"También la baraja siente\ncuando le sacan el dos,\ncómo no he de sentir yo (mi vida),\nsi no me dijiste adiós.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",3,4,"o",-1,0,-1,0,290,290,"Ap. 90","",0,"","","",10,0,0,[],""],["frenk_t4-ap090-05",8,"También la baraja siente\ncuando le sacan el tres;\ncómo no he de sentir yo (mi vida),\nsi me andas haciendo res.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",3,4,"e",218,0,-1,0,290,290,"Ap. 90","",0,"","","",10,0,0,[],""],["frenk_t4-ap090-06",8,"También la baraja sienté\ncuando le sacan el cuatro;\ncómo no he de sentir yo (mi vida),\nsi por ti me desbarato.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",3,4,"ao",-1,0,-1,0,290,290,"Ap. 90","",0,"","","",10,0,0,[],""],["frenk_t4-ap090-07",8,"También la baraja siente\ncuando le sacan el cinco;\ncómo no he de sentir yo (mi vida),\nde celos estoy que brinco.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",3,4,"io",559,0,-1,0,290,290,"Ap. 90","",0,"","","",10,0,0,[],""],["frenk_t4-ap090-08",8,"También la baraja siente\ncuando le sacan el seis;\ncómo no he de sentir yo (mi vida),\nsi hoy te paseas con Andrés.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",3,4,"e",-1,0,-1,0,290,290,"Ap. 90","",0,"","","",10,0,0,[],""],["frenk_t4-ap090-09",8,"También la baraja siente\ncuando le sacan el siete;\ncómo no he de sentir yo (mi vida),\nsi me hiciste... rehilete.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",3,4,"ee",285,0,-1,0,290,290,"Ap. 90","",0,"","","",10,0,0,[],""],["frenk_t4-ap090-10",8,"También la baraja siente\ncuando le sacan la sota;\ncómo no he de sentir yo (mi vida),\nsi me traes como pelota.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",3,4,"oa",432,0,-1,0,290,290,"Ap. 90","",0,"","","",10,0,0,[],""],["frenk_t4-ap090-11",8,"También la baraja siente\ncuando le sacan el caballo;\ncómo no he de sentir yo (mi vida),\néchame pronto tu gallo.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",3,4,"ao",102,0,-1,0,290,290,"Ap. 90","",0,"","","",10,0,0,[],""],["frenk_t4-ap090-12",8,"También la baraja siente\ncuando le sacan el rey;\ncómo no he de sentir yo (mi vida),\nsi al fin tú me hiciste buey.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",3,4,"e",133,0,-1,0,290,290,"Ap. 90","",0,"","","",10,0,0,[],""],["frenk_t4-ap090-13",8,"Aquí se acaba el corrido\nde “Adiós mis cuarenta cartas”;\nya no me creo de los naipes,\nni de las mujeres baratas.",166,2,-1,188,"ADIÓS MIS CUARENTA CARTAS",0,4,"aa",-1,0,-1,0,290,290,"Ap. 90","",0,"","","",2,0,0,[],""],["frenk_t4-ap091-01",8,"Si un sargento te trata de amores,\ndile al momento, dile que no,\nporque un sargento, en mi opinión,\nes lo más sucio y más indecente de un batallón.",166,2,-1,188,"EL SARGENTO",3,4,"o",31,0,-1,0,291,291,"Ap. 91","",0,"","","",1,0,0,[],""],["frenk_t4-ap091-03",8,"Se va el vapor,\nme voy con él;\nse va mi amor,\nme voy también.",166,2,-1,188,"EL SARGENTO",6,4,"e",-1,0,-1,0,291,291,"Ap. 91","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap091-04",8,"Si un teniente se dirige a ti,\ndile al momento, dile que sí,\nporque un teniente, es de aguardar,\nque pronto ascienda a capitán.",166,2,-1,188,"EL SARGENTO",3,4,"a",-1,0,-1,0,291,291,"Ap. 91","",0,"","","",1,0,0,[],""],["frenk_t4-ap091-05",8,"Si un capitán se dirige a ti,\ndile al momento, dile que sí,\nporque un capitán, si él es constante,\npronto asciende a comandante.",166,2,-1,188,"EL SARGENTO",3,4,"ae",47,0,-1,0,291,291,"Ap. 91","",0,"","","",1,0,0,[],""],["frenk_t4-ap091-06",8,"Si un comandante se dirige a ti,\ndile al momento, dile que sí,\nporque un comandante, es de atener,\nque pronto ascienda a coronel.",166,2,-1,188,"EL SARGENTO",3,4,"e",-1,0,-1,0,291,291,"Ap. 91","",0,"","","",1,0,0,[],""],["frenk_t4-ap091-07",8,"Si un coronel se dirige a ti,\ndile al momento, dile que sí,\nporque un coronel, si sabe pelear,\n¡qué pronto asciende a general!",166,2,-1,188,"EL SARGENTO",3,4,"a",-1,0,-1,0,291,291,"Ap. 91","",0,"","","",1,0,0,[],""],["frenk_t4-ap091-08",8,"Si un general se dirige a ti,\ndile al momento, dile que sí,\nporque un general, si él es valiente,\n¡qué pronto asciende a presidente!",166,2,-1,188,"EL SARGENTO",3,4,"ee",15,0,-1,0,291,291,"Ap. 91","",0,"","","",1,0,0,[],""],["frenk_t4-ap091-09",8,"Si un presidente se dirige a ti,\ndile al momento, dile que sí,\nporque un presidente, si tiene valor,\n¡qué pronto asciende a emperador!",166,2,-1,188,"EL SARGENTO",3,4,"o",72,0,-1,0,291,291,"Ap. 91","",0,"","","",1,0,0,[],""],["frenk_t4-ap091-10",8,"El hombre sin dinero\nno vale nada en la vida;\nla mujer que es consentida\nvive siempre en su agujero.",166,2,-1,188,"EL SARGENTO",11,4,"eo",38,0,-1,0,291,291,"Ap. 91","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap091-11",8,"Si un sargento te trata de amor,\ndile al momento, dile que no,\nporque un sargento, en mi opinión,\nes lo más sucio del batallón.",166,2,-1,188,"EL SARGENTO",3,4,"o",31,0,-1,0,291,291,"Ap. 91","",0,"","","",1,0,0,[],""],["frenk_t4-ap092-01",8,"Ya me estoy poniendo pardo\ncomo el animal tejón;\nya me está tentando el diablo,\nya me dio un arrempujón.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",0,4,"o",31,0,-1,0,291,291,"Ap. 92","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap092-02",8,"A Veracruz\nte he de llevar,\nporque es paseo (caramba)\nparticular.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",6,4,"a",21,0,-1,0,291,291,"Ap. 92","",0,"","","",1,0,0,[],""],["frenk_t4-ap092-03",8,"No te creas de un maquinista,\naunque te diga grandota,\nporque te da de comer\npuros hilos de la estopa.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",0,4,"oa",-1,0,-1,0,291,291,"Ap. 92","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap092-04",8,"No te creas de un zapatero\nporque lo veas con dinero,\nporque te da de comer\npuros pedazos de cuero.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",0,4,"eo",38,0,-1,0,291,291,"Ap. 92","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap092-05",8,"No te creas de un arrierito,\naunque lo veas con corbata,\nporque te dará de comer\npuros pedazos de reata.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",0,4,"aa",74,0,-1,0,291,291,"Ap. 92","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap092-06",8,"Un zapatero fue a misa,\nv no teniendo qué rezar\na los santos les decía:\n“Zapatos que remendar”.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",0,4,"a",21,0,-1,0,291,291,"Ap. 92","",0,"","","",2,0,0,[],""],["frenk_t4-ap092-07",8,"No te creas de un carpintero,\naunque lo veas de catrín,\nporque te dará de comer\nvinitas y hasta aserrín.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",0,4,"i",211,0,-1,0,292,292,"Ap. 92","",0,"","","",2,0,0,[],""],["frenk_t4-ap092-08",8,"No te creas de un soldadito,\naunque te hable en la cocina,\nporque te dará de comer\npuritita carabina.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",0,4,"ia",11,0,-1,0,292,292,"Ap. 92","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap092-09",8,"No te creas de un carnicero,\naunque te dé muchos besos,\nporque te dará de comer\nun montonote de huesos.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",0,4,"eo",529,0,-1,0,292,292,"Ap. 92","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap092-10",8,"No te creas de un peluquero,\nporque luego, anda con celos,\ny te dará de comer\nuna baraña de pelos.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",0,4,"eo",192,0,-1,0,292,292,"Ap. 92","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap092-11",8,"No te creas de un gendarmito,\naunque lo veas muy bonito,\nporque unos dan de comer\npistola, garrote y pito.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",0,4,"io",119,0,-1,0,292,292,"Ap. 92","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap092-12",8,"Ya con ésta me despido\nen las cumbres de un encino;\naquí se acaba el corrido\nde los versos del destino.",166,2,-1,188,"CORRIDO DE LOS DESTINOS",1,4,"io",-1,0,-1,0,292,292,"Ap. 92","",0,"frenk_t3","","",71,0,0,[],""],["frenk_t4-ap093-01",8,"Éstas eran cinco hermanas\ny las cinco se casaron:\ntuvieron buenos maridos,\npero no las ayudaron.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"ao",41,0,-1,0,292,292,"Ap. 93","",0,"","","",1,0,0,[],""],["frenk_t4-ap093-02",8,"La primera se casó\ncon un cocinero suizo,\ny todas las noches estaba\npelándole el chile\npa hacerle el chorizo.",175,2,6,188,"LAS CINCO HERMANAS",7,5,"io",95,0,-1,0,292,292,"Ap. 93","",0,"","","",1,0,0,[],""],["frenk_t4-ap093-03",8,"La segunda se casó\ncon un vendedor de leña,\ny todas las noches estaba\nsacando mecates\npara irse a la leña.",175,2,6,188,"LAS CINCO HERMANAS",7,5,"ea",-1,0,-1,0,292,292,"Ap. 93","",0,"","","",1,0,0,[],""],["frenk_t4-ap093-04",8,"La tercera se casó\ncon un maestro carpintero,\ny todas las noches estaba\nmetiendo la broca\ny haciendo agujero.",175,2,6,188,"LAS CINCO HERMANAS",7,5,"eo",38,0,-1,0,292,292,"Ap. 93","",0,"","","",1,0,0,[],""],["frenk_t4-ap093-05",8,"Y la cuarta se casó\ncon un capitán villista,\ny todas las noches estaba\npelándole el sable\ny pasando revista.",175,2,6,188,"LAS CINCO HERMANAS",7,5,"ia",352,0,-1,0,292,292,"Ap. 93","",0,"","","",1,0,0,[],""],["frenk_t4-ap093-06",8,"Y la quinta se casó\ncon un maestro carbonero,\ny todas las noches estaba\npelándole el chile\ny haciendo agujero.",175,2,6,188,"LAS CINCO HERMANAS",7,5,"eo",38,0,-1,0,292,292,"Ap. 93","",0,"","","",1,0,0,[],""],["frenk_t4-ap093-09",8,"A las dos de la mañana\nsalen paseando una iguana;\ntiraron un Santo Cristo\npor agarrar una iguana.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"aa",-1,0,-1,0,292,292,"Ap. 93","",0,"","","",7,0,0,[],""],["frenk_t4-ap093-10",8,"Las muchachas de San Pedro\nson altas y cotorronas;\nde que bajan al riyito\nparecen yeguas pelonas.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"oa",549,0,-1,0,292,292,"Ap. 93","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap093-11",8,"Las muchachas de Nacozari\nson altas y delgaditas;\npero son más pedigüeñas\nque las ánimas benditas.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"ia",258,0,-1,0,292,292,"Ap. 93","",0,"","","",1,0,0,[],""],["frenk_t4-ap093-12",8,"Las muchachas nacoreñas\nse visten de azul y verde;\nde las ocho en adelante,\nla que no pellizca, muerde.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"ee",154,0,-1,0,292,292,"Ap. 93","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap093-13",8,"Las muchachas de Tepache\ncompraron una romana\npara pesarse las piernas\ntres veces a la semana.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"aa",4,0,-1,0,293,293,"Ap. 93","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap093-14",8,"Las muchachas de Batuco\nviven en puros jacales;\nde que bajan a la plaza\nparecen las principales.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"ae",26,0,-1,0,293,293,"Ap. 93","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap093-15",8,"Las muchachas matapeñas\nson bastante retobadas;\nse quitan la atarria a golpes\ny el tapojo a manotadas.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"aa",282,0,-1,0,293,293,"Ap. 93","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap093-16",8,"En el Pueblo Viejo de Ures,\nlas muchachas sandungueras\nparecen chicharras viejas\npor feas y mitoteras.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"ea",-1,0,-1,0,293,293,"Ap. 93","",0,"","","",2,0,0,[],""],["frenk_t4-ap093-17",8,"Las muchachas alamenses\nya no saben ni qué hacer;\npiden a Dios que haya un hombre\nque bien las sepa querer.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"e",20,0,-1,0,293,293,"Ap. 93","",0,"","","",2,0,0,[],""],["frenk_t4-ap093-18",8,"Las muchachas de Magdalena\nson bastante perezosas:\ncuando las llame el trabajo\nse vuelven lobas furiosas.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"oa",61,0,-1,0,293,293,"Ap. 93","",0,"","","",2,0,0,[],""],["frenk_t4-ap093-19",8,"Las muchachas de Hermosillo\nson como el atole frío:\nla cabeza enlistonada\ny el estómago vacío,",175,2,6,188,"LAS CINCO HERMANAS",0,4,"io",3,0,-1,0,293,293,"Ap. 93","",0,"frenk_t3","","",3,0,0,[],""],["frenk_t4-ap093-20",8,"Las chicas de Navojoa\npasan la vida en la plaza,\nmirando por todas partes\npor ver si un marido pasa.",175,2,6,188,"LAS CINCO HERMANAS",0,4,"aa",123,0,-1,0,293,293,"Ap. 93","",0,"","","",1,0,0,[],""],["frenk_t4-ap095-01",8,"Blanca flor de amapolita,\ncuánto te he de agradecer:\nsi nuevos amores tienes,\nlos debes aborrecer.",176,2,3,188,"EL TILANGUERO",0,4,"e",20,0,-1,0,293,293,"Ap. 95","",0,"","","",2,0,0,[],""],["frenk_t4-ap095-02",8,"Dices que ya no me quieres\npor consejos que te han dado;\nanda, busca quien te quiera,\nya no quiero amor forzado,",176,2,3,188,"EL TILANGUERO",0,4,"ao",14,0,-1,0,293,293,"Ap. 95","",0,"","","",21,0,0,[],""],["frenk_t4-ap095-03",8,"Dices que ya no me quieres\nporque no traigo huaraches;\ntú tampoco traes naguas,\nmás que dos puritos parches.",176,2,3,188,"EL TILANGUERO",0,4,"ae",-1,0,-1,0,293,293,"Ap. 95","",0,"","","",21,0,0,[],""],["frenk_t4-ap095-04",8,"Dices que ya no me quieres\nporque no traigo sombrero;\ntú tampoco traes fondo,\nmás que el puro tilanguero.",176,2,3,188,"EL TILANGUERO",0,4,"eo",38,0,-1,0,293,293,"Ap. 95","",0,"frenk_t2","","",21,0,0,[],""],["frenk_t4-ap095-05",8,"Dices que ya no me quieres\nporque no traigo camisa;\ntú tampoco echas gordas,\ntodo está eso de mestiza.",176,2,3,188,"EL TILANGUERO",0,4,"ia",420,0,-1,0,293,293,"Ap. 95","",0,"frenk_t2","","",21,0,0,[],""],["frenk_t4-ap095-06",8,"Dices que ya no me quieres\nporque ya estoy muy tordillo;\nyo tampoco no te quiero\nporque hueles a zorrillo.",176,2,3,188,"EL TILANGUERO",0,4,"io",228,0,-1,0,293,293,"Ap. 95","",0,"","","",21,0,0,[],""],["frenk_t4-ap095-07",8,"Ya con ésta me despido,\nésa es la misma cosita:\nsi nuevos amores tienes,\ndame un beso en tu boquita.",176,2,3,188,"EL TILANGUERO",0,4,"ia",50,0,-1,0,293,293,"Ap. 95","",0,"","","",71,0,0,[],""],["frenk_t4-ap096-01",8,"Esta sí es arca de Noé,\nrodeada de figuritas,\ndonde se ven colocados\nseñores y señoritas.",166,2,-1,188,"EL ARCA DE NOÉ",0,4,"ia",258,0,-1,0,293,293,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-02",8,"Señores, el arca de Noé\ntiene diversas cositas,\ncanarios y palomitas,\ncomo ahora lo explicaré.",166,2,-1,188,"EL ARCA DE NOÉ",3,4,"e",77,0,-1,0,293,293,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-03",8,"Águilas son las Joaquinas,\nlechuzas son las Antonias\ny grullas las Macedonias,\npanteras las Agustinas,\nlas Petras vacas ladinas,\nlas Natalias mariposas,\ny calandrias las Pomposas\na quienes yo admiraré;\nardillas serán las Rosas;\nésta sí es la arca de Noé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,294,294,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-04",8,"Las Loretos son gallinas,\njirafas las Anastasias,\naguilillas las Tomasas,\ncotorras son las Paulinas,\nchicharras las Ernestinas,\nculebras serán las Blasas\ny las Lucitas torcazas,\ncon ellas me recrearé;\nguajolotas las Eufrasias;\nésta sí es el arca de Noé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,294,294,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-05",8,"Las Altagracias canarias,\ny las Elisas gorrionas,\nsaltapared las Ramonas,\ncampamochas las Macanas,\nánsares son las Leocadias,\nmantequillas las Teodoras,\ncacatúas serán las Floras,\npor quienes yo moriré;\ngolondrinas son las Lolas;\nésta sí es el arca de Noé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,294,294,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-06",8,"Urracas serán las Juanas,\nchuparrosas las Lucías,\nguacamayas las Marías,\nlas Petronilas iguanas,\ny las Victorias son ranas,\ngallaretas las Chabelas,\ncucarachas las Manuelas,\nde las Lupes ¿qué diré?,\néstas serán sanguijuelas;\nésta sí es el arca de Nçé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,294,294,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-07",8,"Culebras las Jesuses,\nyeguas son las Josefinas,\ntortugas las Enedinas,\ny madreselvas las Cruces,\npalomas las Catalinas,\ncodornices son las Luisas,\nlagartijas las Narcisas,\ncon quienes las brillaré;\ncarpas serán las Dionisias;\nésta sí es el arca de Noé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,294,294,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-08",8,"Cigüeñas son las Maclovias,\narañas las Enriquetas,\ny garzas las Antonietas,\nballenas son las Cenobias,\nvíboras las Modestas,\ncebras son las Rosalías,\ny jirafas las Sofías\npor quienes yo sufriré;\nfocas las Estefanías;\nésta sí es el arca de Noé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,294,294,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-09",8,"Gallos serán los Crescendos\ny los Eduardos faisanes,\nlos Clementes gavilanes,\ntecolotes los Florencios;\npapagayos son los Juanes,\nlos Rafaeles magalones,\nlobos serán los Zenones,\ny burrito un Bernabé,\ncoyotes los Pantaleones;\nésta sí es el arca de Noé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,294,294,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-10",8,"Los Vicentes camaleones,\ngatos son los Anastasios,\nelefantes los Nicasios,\nlos Pedros son tiburones,\ntepocates los Eufrasios,\nlos Lucios son alacranes,\njicotes los Sebastianes,\nde quienes me cuidaré,\nostiones son los Fabianes;\nésta sí es el arca de Noé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,294,294,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-11",8,"Grillos son los Zeferinos\ny sapos los Margaritos,\npescados los Agapitos,\narmadillos los Rufinos,\nlos Ubaldos son cochinos,\nbúfalos son los Leobardos\ny changos son los Leonardos,\nconejo será un José,\ncuyos los Estanislaos;\nésta sí es la arca de Noé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,294,294,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-12",8,"Alicantes los Fermines,\ncorucos son los Franciscos,\nlos Eladios basiliscos,\ntutubises los Joaquines,\ny leones los Federicos,\nmadrugadores los Guillermos,\ncaracoles los Anselmos,\ncamarón un Salomé,\nleopardos los Filomenos;\nésta sí es la arca de Noé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,294,294,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-13",8,"Los Pablos serán bisontes,\ny borregos los Matías,\ntordos son los Malaquías,\nlos Claudios rinocerontes\ny los Julios son cenzontles,\nlos Constantinos lagartos,\ntejones son los Donatos,\ntigre un Bartolomé,\ncocuyos los Honoratos;\nésta sí es la arca de Noé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,295,295,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap096-14",8,"Los Aurelios cocodrilos,\ntlacuaches serán los Cletos,\njenízaros los Anicetos,\nchapulines los Cirilos,\npalomos los Anacletos,\npavos serán los Manueles,\npericos los Isabeles,\na quienes yo venderé,\ny patos son los Migueles;\nésta sí es la arca de Noé.",166,2,-1,188,"EL ARCA DE NOÉ",18,10,"e",77,0,-1,0,295,295,"Ap. 96","",0,"","","",1,0,0,[],""],["frenk_t4-ap097-01",8,"Yo ser casada no quiero,\nsola me he de mantener;\nque el hombre más verdadero\ny de mejor parecer\nno pasa de un embustero.",166,2,-1,188,"DEFECTOS DE LOS HOMBRES SACADOS POR LAS MUJERES",7,5,"eo",38,0,-1,0,295,295,"Ap. 97","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap097-02",8,"Los Antonios son malcriados;\nborrachos, los Cayetanos,\ninsolentes, los Ciprianos,\ny los Bernardos, osados;\nlos Pedros son desconfiados,\nlos Felipes muy groseros;\npataratos, los Severos,\ny valientes los Ramones;\npor todas estas razones\nyo ser casada no quiero.",166,2,-1,188,"DEFECTOS DE LOS HOMBRES SACADOS POR LAS MUJERES",18,10,"eo",-1,0,-1,0,295,295,"Ap. 97","",0,"","","",1,0,0,[],""],["frenk_t4-ap097-03",8,"Los Marcos son habladores;\ncoqueros los Bonifacios;\ngroseros los Atanasios,\ny los Luises jugadores;\nlos Benitos son traidores,\nlos Justos quieren tener\ndos damas que mantener,\nmuy bien golpeadas y en cueros;\nno quiero a esos caballeros,\nsola me he de mantener.",166,2,-1,188,"DEFECTOS DE LOS HOMBRES SACADOS POR LAS MUJERES",18,10,"e",-1,0,-1,0,295,295,"Ap. 97","",0,"","","",1,0,0,[],""],["frenk_t4-ap097-04",8,"Los Mauricios son salados,\nlos Manueles, altaneros;\nlos Patricios, embusteros;\ny los Dionisios, porfiados;\nlos Félix, enamorados;\nlos Anselmos, muy barberos;\nlos Pablos tratan primero\nde engañar y no cumplir;\nde leño podrá servir\nel hombre más verdadero.",166,2,-1,188,"DEFECTOS DE LOS HOMBRES SACADOS POR LAS MUJERES",18,10,"eo",38,0,-1,0,295,295,"Ap. 97","",0,"","","",1,0,0,[],""],["frenk_t4-ap097-05",8,"Los Franciscos son celosos,\nlos Remigios, charlatanes;\nzonzos y bobos los Juanes,\ny los Diegos, revoltosos;\nlos Joaquines son melosos\nlo mismo que una mujer;\nyo a ninguno puedo ver;\nlos Roques son muy fatales,\nque aparentan ser formales\ny de mejor parecer.",166,2,-1,188,"DEFECTOS DE LOS HOMBRES SACADOS POR LAS MUJERES",18,10,"e",20,0,-1,0,295,295,"Ap. 97","",0,"","","",1,0,0,[],""],["frenk_t4-ap097-06",8,"Los Lorenzos son inmundos,\ndesdeñosos, los Macarios,\nflojos, los Apolinarios,\nlos Migueles, vagabundos;\nlos Mateos son iracundos,\nlos Santiagos, noveleros,\nlos Carlos son callejeros,\ntodo se les va en pasear;\nde todos, el más formal,\nno pasa de un embustero.",166,2,-1,188,"DEFECTOS DE LOS HOMBRES SACADOS POR LAS MUJERES",18,10,"eo",-1,0,-1,0,295,295,"Ap. 97","",0,"","","",1,0,0,[],""],["frenk_t4-ap098-01",8,"Traigo muy bellas mujeres,\nmuy pronto se han de acabar,\npara salir pronto de ellas\nhoy las pienso rematar.",166,2,-1,188,"GRAN BARATA DE MUJERES",0,4,"a",21,0,-1,0,296,296,"Ap. 98","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap098-02",8,"Pues sacaremos primero\nal remate a las Juanitas,\nque por su mucho salero\ndeben ser preferiditas;\nestas bellas señoritas,\ncon su modito de andar,\nsin compasión a los hombres\nhasta los hacen sudar;\npor eso yo les pregunto:\n¿Quién las quiere rematar?",166,2,-1,188,"GRAN BARATA DE MUJERES",18,10,"a",21,0,-1,0,296,296,"Ap. 98","",0,"","","",1,0,0,[],""],["frenk_t4-ap098-03",8,"Después las bellas Rositas\npondremos en el remate,\npues de verlas tan preciosas\nno habrá quien me las maltrate;\nson buenas, finas y limpias,\nnadie lo podrá negar,\nserán muy buenas esposas,\nmuy amantes a su hogar;\nvamos a ver, muchachones,\n¿Quién las quiere rematar?",166,2,-1,188,"GRAN BARATA DE MUJERES",18,10,"a",21,0,-1,0,296,296,"Ap. 98","",0,"","","",1,0,0,[],""],["frenk_t4-ap098-04",8,"A las Vicentas llegó\nsu turno en esta ocasión,\néstas sí deben quererlas\ncon todo su corazón,\nson muy limpias y hacendosas\ny en todas han de observar\nque andan muy limpias y aseadas,\nno les gusta descansar;\nde los flojos de hoy en día,\n¿Quién las quiere rematar?",166,2,-1,188,"GRAN BARATA DE MUJERES",18,10,"a",21,0,-1,0,296,296,"Ap. 98","",0,"","","",1,0,0,[],""],["frenk_t4-ap098-05",8,"A las Jesusitas lindas\nla ocasión se les llegó,\n¿quién será el que no las quiera\ntanto cual las amo yo?\nSon amantes, cariñosas,\ny constantes en amor,\nson limpias y cuidadosas\ncual yo no puedo explicar;\ncon que así, mis valedores,\n¿Quién las quiere rematar?",166,2,-1,188,"GRAN BARATA DE MUJERES",18,10,"a",21,0,-1,0,296,296,"Ap. 98","",0,"","","",1,0,0,[],""],["frenk_t4-ap098-06",8,"Las Agustinas aquí\ndeben de comparecer,\nno quisiera hablar de ellas,\nque el color han de perder,\nson puercas y atolondradas,\nnada más saben charlar,\nquieren cochero y lacayo\ny dar gusto al paladar;\ncon que de los hacendados,\n¿Quién las quiere rematar?",166,2,-1,188,"GRAN BARATA DE MUJERES",18,10,"a",21,0,-1,0,296,296,"Ap. 98","",0,"","","",1,0,0,[],""],["frenk_t4-ap098-07",8,"Rematar pienso baratas\na las Dolores por flojas,\nles gusta mucho el paseo\ny todas las más son locas;\ncon que, respóndanme pronto\nel que las quiera comprar;\nno les gusta estar en casa,\nno más en la calle andar;\nde los que quieran baratas,\n¿Quién las quiere rematar?",166,2,-1,188,"GRAN BARATA DE MUJERES",18,10,"a",21,0,-1,0,296,296,"Ap. 98","",0,"","","",1,0,0,[],""],["frenk_t4-ap098-08",8,"Vámonos con las Refugios;\nno te engaño, comprador,\nsi te crees de sus patrañas,\nte harán perder el color;\nson vanas y presuntuosas,\nno les gusta trabajar,\nson flojas y presumidas,\nno saben ni remendar,\ncon que a ver, enamorados,\n¿Quién las quiere rematar?",166,2,-1,188,"GRAN BARATA DE MUJERES",18,10,"a",21,0,-1,0,296,296,"Ap. 98","",0,"","","",1,0,0,[],""],["frenk_t4-ap098-09",8,"Ya sé que iban escapando\nlas vanidosas Marinas,\nno se crean, amigos, de ellas,\npues siempre hablan de cocinas;\ndicen que saben coser,\nse pintan para planchar\ny llegada la ocasión\nahí se empiezan a arrugar;\ncon que así de los guajillos,\n¿Quién las quiere rematar?",166,2,-1,188,"GRAN BARATA DE MUJERES",18,10,"a",21,0,-1,0,296,296,"Ap. 98","",0,"","","",1,0,0,[],""],["frenk_t4-ap098-10",8,"A las Antonias devotas\n¿no hay quien las quiera comprar?\nLas verán siempre en la iglesia,\npero es por no trabajar;\nsiempre piensan en el cielo\no vienen de comulgar,\ny si no está el chocolate\ncomienzan a regañar;\ncon que aquí de los devotos,\n¿Quién las quiere rematar?",166,2,-1,188,"GRAN BARATA DE MUJERES",18,10,"a",21,0,-1,0,297,297,"Ap. 98","",0,"","","",1,0,0,[],""],["frenk_t4-ap098-11",8,"A las Sabinas dejé\npara el último lugar,\nporque éstas con mucho aprecio\nlas debo de rematar:\nejemplo son de mujeres,\nsaben coser y guisar,\ncon lo que gana el marido\nse saben acomodar;\ncon que, amigos artesanos,\n¿Quién las quiere rematar?",166,2,-1,188,"GRAN BARATA DE MUJERES",18,10,"a",21,0,-1,0,297,297,"Ap. 98","",0,"","","",1,0,0,[],""],["frenk_t4-ap099-01",8,"Treinta días que tiene el mes\nhe de estar acompañado,\nestarán siempre a mi lado\nPachita, Julia y Inés.",175,2,6,188,"EL MUJERIEGO",11,4,"e",218,0,-1,0,297,297,"Ap. 99","",0,"","","",1,0,0,[],""],["frenk_t4-ap099-02",8,"El día primero saldré\na pasear con Anastasia,\nel día dos con Altagracia\ny el día tres con Salomé,\nel día cuatro Bernabé\nme mostrará su interés,\nel cinco y el seis después\nde estar con Guadalupita,\nestaré con Jesusita\ntreinta días que tiene el mes.",175,2,6,188,"EL MUJERIEGO",18,10,"e",218,0,-1,0,297,297,"Ap. 99","",0,"","","",1,0,0,[],""],["frenk_t4-ap099-03",8,"El día siete con Juanita,\nel día ocho con Urbana,\nel nueve con Sebastiana\ny el día diez con Elenita,\nel once con Josefina,\nel doce estaré casado,\nel día trece entusiasmado,\nel catorce con Victoria\ny el día quince con Gregorià\nhe de estar acompañado.",175,2,6,188,"EL MUJERIEGO",18,10,"ao",14,0,-1,0,297,297,"Ap. 99","",0,"","","",1,0,0,[],""],["frenk_t4-ap099-04",8,"El dieciocho con Macrina,\nel diecisiete con Lola,\nel dieciocho con Bartola\ny el diecinueve Agripina;\nel día veinte, Catalina\nme tendrá regocijado,\nel veintiuno me ha gustado\npor complacer a Nestora,\nel veintidós con Aurora\nestará siempre a mi lado.",175,2,6,188,"EL MUJERIEGO",18,10,"ao",14,0,-1,0,297,297,"Ap. 99","",0,"","","",1,0,0,[],""],["frenk_t4-ap099-05",8,"El veintitrés Timotea,\nel veinticuatro con Rosa,\nel veinticinco Pomposa\ny el veintiséis con Andrea,\nel veintisiete, Irinea\nme amará con honradez,\nel día ventiocho, otra vez,\nme ha de acariciar Vicenta,\nel veintinueve y el treinta\nPachita, Julia y Inés.",175,2,6,188,"EL MUJERIEGO",18,10,"e",218,0,-1,0,297,297,"Ap. 99","",0,"","","",1,0,0,[],""],["frenk_t4-ap100-01",8,"Soy el muchacho engreído,\ndueño de las tres garitas,\ndespreciado de las feas,\nquerido de las bonitas.",171,2,4,188,"SOY EL MUCHACHO ENGREÍDO",0,4,"ia",258,0,-1,0,298,298,"Ap. 100","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap100-02",8,"Mucho me quiso Ernestina\nporque con ella me he criado,\ncon una Dionisia he estado,\njugando con Ceferina;\n¡Cómo fui a dar con Lucina...!\nCon ella me he entretenido;\nLuz me tiene sin sentido\nporque se ha mostrado fina;\npero al lado de Joaquina\nsoy el muchacho engreído.",171,2,4,188,"SOY EL MUCHACHO ENGREÍDO",18,10,"io",101,0,-1,0,298,298,"Ap. 100","",0,"","","",1,0,0,[],""],["frenk_t4-ap100-03",8,"Manuela es mi idolatría,\ntodo mi querer, Ramona;\npero donde está Simona...\npues ella es la vida mía;\nyo quiero mucho a Lucía,\na Alonsa y a Gertruditas,\nporque son presumiditas;\nno hay otra como Asunción,\nporque me dicen que soy\ndueño de las tres garitas.",171,2,4,188,"SOY EL MUCHACHO ENGREÍDO",18,10,"ia",258,0,-1,0,298,298,"Ap. 100","",0,"","","",1,0,0,[],""],["frenk_t4-ap100-04",8,"Guadalupe es mi tesoro,\nmi buen querer es Antonia,\nyo me muero por Gorgonia,\ntambién por Timotea lloro;\na Petra guardo el decoro\nporque la quiero de veras,\nMarcela, con sus flojeras,\ntodo me suele pasar\ny a la fuerza me hace estar\ndespreciado de las feas.",171,2,4,188,"SOY EL MUCHACHO ENGREÍDO",18,10,"ea",-1,0,-1,0,298,298,"Ap. 100","",0,"","","",1,0,0,[],""],["frenk_t4-ap100-05",8,"En fin, yo por Andresita\nhe de olvidar a Leonarda,\ny aunque se enoje Ricarda\nme he de ir con Agapita,\nporque las quiero a toditas\naunque se enoje Luisita,\nSevera y también Chuchita,\nCarmen, Rosita y María,\nporque me dicen que soy\nquerido de las bonitas.",171,2,4,188,"SOY EL MUCHACHO ENGREÍDO",18,10,"ia",-1,0,-1,0,298,298,"Ap. 100","",0,"","","",1,0,0,[],""],["frenk_t4-ap101-02",8,"—Hija de tía Dorotea,\n¡cuánto me gusta!,\npero más me gusta Justa\nla de tía Chepa.",176,2,3,188,"LAS MUCHACHAS",3,4,"ea",-1,0,-1,0,298,298,"Ap. 101","",0,"","","",1,0,0,[],""],["frenk_t4-ap101-03",8,"—Lástima que no me quepa\nduda de Blasa.\n—Yo prefiero a Nicolasa\ncon Jesusita",176,2,3,188,"LAS MUCHACHAS",6,4,"ia",-1,0,-1,0,298,298,"Ap. 101","",0,"","","",1,0,0,[],""],["frenk_t4-ap101-04",8,"—Esta duda no la quita\nni tía Mercedes.\n—Solamente que te quedes\nen la Parota,",176,2,3,188,"LAS MUCHACHAS",6,4,"oa",-1,0,-1,0,298,298,"Ap. 101","",0,"","","",1,0,0,[],""],["frenk_t4-ap101-05",8,"—A mí me gusta Carlota\ncon sus humores.\n—Yo preferiría a Dolores\no a Celestina.",176,2,3,188,"LAS MUCHACHAS",3,4,"ia",-1,0,-1,0,298,298,"Ap. 101","",0,"","","",1,0,0,[],""],["frenk_t4-ap101-06",8,"—Si se me pandea la esquina,\nprefiero a Lupe.\n—Sólo que ya no la ocupe\ndon Pantaleón.",176,2,3,188,"LAS MUCHACHAS",3,4,"o",-1,0,-1,0,298,298,"Ap. 101","",0,"","","",1,0,0,[],""],["frenk_t4-ap101-07",8,"—Si viniera Concepción\ncon su linda trenza.\n—Yo sólo con mi Lorenza\nvoy de paseo.",176,2,3,188,"LAS MUCHACHAS",6,4,"eo",-1,0,-1,0,298,298,"Ap. 101","",0,"","","",1,0,0,[],""],["frenk_t4-ap101-08",8,"—No te quedes con deseo,\nllévate a Carmen.\n—Sus hermano? que te la armen\ncon sus pendencias.",176,2,3,188,"LAS MUCHACHAS",6,4,"ea",-1,0,-1,0,298,298,"Ap. 101","",0,"","","",1,0,0,[],""],["frenk_t4-ap101-09",8,"—Entre ellas viene Clemencia,\nla de tía Paca.\n—Esa ya nadie la aplaca\nni con espuelas.",176,2,3,188,"LAS MUCHACHAS",6,4,"ea",-1,0,-1,0,299,299,"Ap. 101","",0,"","","",1,0,0,[],""],["frenk_t4-ap101-10",8,"—Luisa viene con Estela\ny con Catalina.\n—Ya se me clavó la espina\ncon sus amores.",176,2,3,188,"LAS MUCHACHAS",6,4,"oe",-1,0,-1,0,299,299,"Ap. 101","",0,"","","",1,0,0,[],""],["frenk_t4-ap101-11",8,"—¿La coronarías de flores\nen el huizache?\n—Estrenando mi huarache,\nDios me acompañe.",176,2,3,188,"LAS MUCHACHAS",3,4,"ae",-1,0,-1,0,299,299,"Ap. 101","",0,"","","",1,0,0,[],""],["frenk_t4-ap101-12",8,"La prefiero con sus cuñas,\naunque me engañe,\nque se recorte las uñas\npara que a mí no me arañe.",176,2,3,188,"LAS MUCHACHAS",3,4,"ae",582,0,-1,0,299,299,"Ap. 101","",0,"","","",1,0,0,[],""],["frenk_t4-ap102-01",8,"Oye, Rosita, dile a Ricarda,\na Marianita y a Soledad,\nqué cosa delira, qué cosa ha pensado,\nporque Panchita, dice, se va.",169,2,8,188,"ROSITA",3,4,"a",-1,0,-1,0,299,299,"Ap. 102","",0,"","","",1,0,0,[],""],["frenk_t4-ap102-02",8,"Juana y Elvira son amistades,\ntambién Florita y Natividad;\nsi Guadalupe ya no me quiere,\nesa Panchita sí me querrá.",169,2,8,188,"ROSITA",3,4,"a",-1,0,-1,0,299,299,"Ap. 102","",0,"","","",1,0,0,[],""],["frenk_t4-ap102-03",8,"Por eso Petra ya no me quiere\nni corresponde mi relación,\nporque Josefa le habrá avisado\nque yo trataba con Asunción.",169,2,8,188,"ROSITA",3,4,"o",31,0,-1,0,299,299,"Ap. 102","",0,"","","",1,0,0,[],""],["frenk_t4-ap102-04",8,"María y Librada ya se enojaron\nporque Adelaida les platicó\nque a Josefina tenía abrazada;\nllegó Rosita y la regañó.",169,2,8,188,"ROSITA",3,4,"o",2,0,-1,0,299,299,"Ap. 102","",0,"","","",1,0,0,[],""],["frenk_t4-ap102-05",8,"Rosalía me estaba mirando,\nEsperanza se lo avisó;\ncuando Teresa también lo supo,\ncon Manuelita también peleó.",169,2,8,188,"ROSITA",3,4,"o",2,0,-1,0,299,299,"Ap. 102","",0,"","","",1,0,0,[],""],["frenk_t4-ap102-06",8,"Sara y Gregoria hicieron junta\npara agarrar a este gavilán,\nporque en el pico llevaba flores\ny en las alitas todo el refrán.",169,2,8,188,"ROSITA",3,4,"a",147,0,-1,0,299,299,"Ap. 102","",0,"","","",1,0,0,[],""],["frenk_t4-ap102-07",8,"Voy a pasearme por esos prados\ncon Caritina y con Isabel,\nantes que vengan Lola y Elvira,\nporque hasta loco me han de volver.",169,2,8,188,"ROSITA",3,4,"e",-1,0,-1,0,299,299,"Ap. 102","",0,"","","",1,0,0,[],""],["frenk_t4-ap102-08",8,"A mí me gusta un amor constante,\npero que sea de su voluntad:\nque no me salga como Panchita,\nque me dice que ya se va y ya se fue.",169,2,8,188,"ROSITA",3,4,"e",-1,0,-1,0,299,299,"Ap. 102","",0,"","","",1,0,0,[],""],["frenk_t4-ap103-01",8,"Vamos, niña, conmigo a los mares\ny verás las embarcaciones,\ny verás muchos animales\nde variados, distintos colores.",175,2,6,188,"VAMOS, NIÑA, CONMIGO A LOS MARES",3,4,"oe",-1,0,-1,0,299,299,"Ap. 103","",0,"","","",1,0,0,[],""],["frenk_t4-ap103-12",8,"Mira, niña, si conmigo te vas,\nte prometo llevarte embarcada\na tomar el jugo de granada;\nlos aviones volando verás,\nmuchas cosas las conocerás\npara que nadie te venga a contar\ntodo lo que yo te voy a enseñar.",175,2,6,188,"VAMOS, NIÑA, CONMIGO A LOS MARES",4,7,"a",21,0,-1,0,300,300,"Ap. 103","",0,"","","",1,0,0,[],""],["frenk_t4-ap104-01",8,"Te daré, como me des\nde tu bella boca el sí,\nlas alfombras de Turquía\ny el oro del Potosí.",171,2,4,188,"TE DARÉ, COMO ME DES",0,4,"i",23,0,-1,0,300,300,"Ap. 104","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap104-02",8,"En un coche pasearás\ncon abundante opulencia\ny con crecida asistencia\nla África gobernarás.\nTres palacios mandarás\ny te verás como juez;\nse rendirán a tus pies\ndoce mil turcos famosos,\ntodos vestidos lujosos\nte daré, como me des.",171,2,4,188,"TE DARÉ, COMO ME DES",18,10,"e",218,0,-1,0,300,300,"Ap. 104","",0,"","","",1,0,0,[],""],["frenk_t4-ap104-03",8,"Mandarás toda la tropa\nde americanos flecheros\ny con cariños severos\nse te rendirá la Europa.\nVestirás pulida ropa\nde tela de carmesí;\ntodo lo que conseguí\nen las Indias sometidas\nte daré cuando me digas\nde tu bella boca el sí.",171,2,4,188,"TE DARÉ, COMO ME DES",18,10,"i",23,0,-1,0,300,300,"Ap. 104","",0,"","","",1,0,0,[],""],["frenk_t4-ap104-04",8,"De las potencias del Asia\ntendrás el acatamiento;\nte ofrecerán rendimiento\nlos Doce Pares de Francia.\nNo digas que es arrogancia\nlo que te digo, alma mía,\nmandarás de noche y día\nla Alejandría y la Inglaterra,\ny pisarás en la tierra\nlas alfombras de Turquía.",171,2,4,188,"TE DARÉ, COMO ME DES",18,10,"ia",0,0,-1,0,300,300,"Ap. 104","",0,"","","",1,0,0,[],""],["frenk_t4-ap104-05",8,"Y de la China afamada\ntendrás tesoros y alivios,\nde diamantes y de anillos\nte verás bien adornada,\ny de flores coronada,\nde brillantes y rubí,\ncomo me digas que sí;\ngobernarás claramente\nlas estrellas del Oriente\ny el oro del Potosí.",171,2,4,188,"TE DARÉ, COMO ME DES",18,10,"i",23,0,-1,0,300,300,"Ap. 104","",0,"","","",1,0,0,[],""],["frenk_t4-ap105-01",8,"Sólo Dios, sólo la muerte\nde tu amor me apartarán,\nporque vivos no podrán\nprivar mi amor de quererte.",171,2,4,188,"SÓLO DIOS, SÓLO LA MUERTE",11,4,"ee",134,0,-1,0,301,301,"Ap. 105","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap105-02",8,"Jovencita, bien has visto\nque te amo con gran lealtad,\nque no me lo ha de evitar\nni Pedro, Juan, ni Francisco,\ny si el Papa y el Obispo\nmandan que de ti me ausente,\nresponderé evidente\nque no te puedo olvidar,\nque de ti me ha de apartar\nsólo Dios, sólo la muerte.",171,2,4,188,"SÓLO DIOS, SÓLO LA MUERTE",18,10,"ee",-1,0,-1,0,301,301,"Ap. 105","",0,"","","",1,0,0,[],""],["frenk_t4-ap105-03",8,"Ni Sansón por ser tan fuerte,\nni el Rey Carlos sin segundo,\nni los más sabios del mundo,\nni las naciones de Oriente,\nni Fierabrás con su gente,\nni Oliveros, ni Roldán,\nni el almirante Balán,\nte aseguro, vida mía,\nque ni Francia ni Turquía\nde tu amor me apartarán.",171,2,4,188,"SÓLO DIOS, SÓLO LA MUERTE",18,10,"a",147,0,-1,0,301,301,"Ap. 105","",0,"","","",1,0,0,[],""],["frenk_t4-ap105-04",8,"Ni el guerrero Zabulón,\nni el rey David con su agravio,\nni Salomón con ser sabio\nme ha de quitar la intención;\nte amo con mucha pasión\ny te digo la verdad,\nque no me la ha de evitar\nni una sospecha ni un celo,\nsolamente Dios del cielo,\nporque vivos no podrán.",171,2,4,188,"SÓLO DIOS, SÓLO LA MUERTE",18,10,"a",-1,0,-1,0,301,301,"Ap. 105","",0,"","","",1,0,0,[],""],["frenk_t4-ap105-05",8,"Ni los clarines ufanos\ncon sus resonantes ecos,\nque son realmente completos,\nni los leones africanos,\nni los árabes tiranos\npor ser nación tan valiente,\nni la espada de la muerte,\nni hombres vivos ni difuntos,\nhan de poder todos juntos\nprivar mi amor de quererte.",171,2,4,188,"SÓLO DIOS, SÓLO LA MUERTE",18,10,"ee",134,0,-1,0,301,301,"Ap. 105","",0,"","","",1,0,0,[],""],["frenk_t4-ap106-01",8,"Ya se llegó mi partida,\nya me voy a retirar,\nadiós, mi alma, adiós, mi vida,\nadiós, perlita del mar.",171,2,4,188,"YA SE LLEGÓ MI PARTIDA",1,4,"a",21,0,-1,0,301,301,"Ap. 106","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap106-02",8,"Lloren las flores del tiempo,\nlloren los peces del mar,\nlloren, lloren sin cesar\ntodas las flores de aumento.\n¡Oh astros del firmamento,\néchenme la despedida,\nllora, mi bien de mi vida,\nque llorar es tu destino,\nmírame presto en camino,\nya se llegó mi partida.",171,2,4,188,"YA SE LLEGÓ MI PARTIDA",18,10,"ia",37,0,-1,0,301,301,"Ap. 106","",0,"","","",1,0,0,[],""],["frenk_t4-ap106-03",8,"Ya se aleja, prenda amada,\nel dueño de tu albedrío,\nno llores, regalo mío,\nni quedes desconsolada;\n¡qué suerte tan desdichada,\nque no te puedo llevar!\nTú eres todo mi pesar,\n¡válgame Dios!, ¡qué dolencia!\npor una gran imprudencia\nyo me voy a retirar.",171,2,4,188,"YA SE LLEGÓ MI PARTIDA",18,10,"a",21,0,-1,0,301,301,"Ap. 106","",0,"","","",1,0,0,[],""],["frenk_t4-ap106-04",8,"Adiós, te digo llorando\ncon mi corazón herido,\ny a Dios, llorando, le pido\nque tú no vivas penando,\nyo siempre te estaré amando\nmientras Dios me preste vida;\nesto dejo en despedida,\nestrellita reluciente,\nadiós, arco del oriente,\nadiós, mi alma, adiós, mi vida.",171,2,4,188,"YA SE LLEGÓ MI PARTIDA",18,10,"ia",37,0,-1,0,302,302,"Ap. 106","",0,"","","",1,0,0,[],""],["frenk_t4-ap106-05",8,"Adiós, jardín oloroso,\nadiós, fragante azucena,\nme voy a otra tierra ajena;\nadiós, clavel primoroso,\nadiós, rancho desdeñoso,\nadiós, ramito de azahar,\nadiós, palma, adiós, cristal\ndonde tuve mis amores,\nadiós, flores de las flores,\nadiós, perlita del mar.",171,2,4,188,"YA SE LLEGÓ MI PARTIDA",18,10,"a",-1,0,-1,0,302,302,"Ap. 106","",0,"","","",1,0,0,[],""],["frenk_t4-ap107-01",8,"No creas que te perjudico,\ningrata, aunque tuyo fui,\nya que te encontraste un rico\nno lo desprecies por mí.",171,2,4,188,"NO CREAS QUE TE PERJUDICO",1,4,"i",23,0,-1,0,302,302,"Ap. 107","",0,"","","",1,0,0,[],""],["frenk_t4-ap107-02",8,"Sé que te vas a casar\ncon un hombre millonario,\nlo aprecio, aunque es mi contrario,\nmucho gusto me ha de dar.\nComo me supiste amar,\nque lo quieras te replico\ny también te comunico,\nel mundo y todos lo ven,\nyo siempre te busco un bien,\nno creas que te perjudico.",171,2,4,188,"NO CREAS QUE TE PERJUDICO",18,10,"io",141,0,-1,0,302,302,"Ap. 107","",0,"","","",3,0,0,[],""],["frenk_t4-ap107-03",8,"Si te ama pa compañera,\ny a idolatrarte se empeña,\námalo y serás la dueña\nde la República entera.\nHasta la gente extranjera\ntendrá que venir aquí,\nyo, sólo por verte a ti\nasí que ya estés casada,\nno creas que yo diga nada,\ningrata, aunque tuyo fui.",171,2,4,188,"NO CREAS QUE TE PERJUDICO",18,10,"i",23,0,-1,0,302,302,"Ap. 107","",0,"","","",1,0,0,[],""],["frenk_t4-ap107-04",8,"En una casa adornada\nvivirán juntos los dos,\nno de zacate de arroz\ncomo la mía está techada.\nEn un trono colocada\nestarás con tu abanico,\ny para que no haya pico\ntendrás mozas, molenderas;\ncásate, tonta, ¿qué esperas?,\nya que te encontraste un rico.",171,2,4,188,"NO CREAS QUE TE PERJUDICO",18,10,"io",141,0,-1,0,302,302,"Ap. 107","",0,"","","",1,0,0,[],""],["frenk_t4-ap107-05",8,"El día de tu casamiento\nte traerán una corona\nel Santo Papa de Roma\ny todo su acompañamiento.\nCon varios vidrios de aumento,\nperlas, diamantes, rubís,\ntodos te traerán a ti\nde las diez hasta las once;\nno cambies oro por bronce\nni lo desprecies por mí.",171,2,4,188,"NO CREAS QUE TE PERJUDICO",18,10,"i",23,0,-1,0,302,302,"Ap. 107","",0,"","","",1,0,0,[],""],["frenk_t4-ap108-01",8,"Por ser hoy día de tu santo,\ncon prósperas alegrías\na tus puertas vengo a dar\nvísperas, noches y días.",168,2,11,188,"JUSTICIAS O SEAN MAÑANITAS PARA ONOMÁSTICO",0,4,"ia",214,0,-1,0,302,302,"Ap. 108","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap108-03",8,"San Jerónimo el clarín\nte toque con dulce voz,\nen honra y gloria de Dios,\ndías te dé San Agustín,\ny el glorioso Serafín\nhoy te otorgue, sin quebranto,\nla gloria que posee el Santo;\nnunca jamás tengas pena,\ncante alegre la sirena\npor ser hoy día de tu santo.",168,2,11,188,"JUSTICIAS O SEAN MAÑANITAS PARA ONOMÁSTICO",18,10,"ao",-1,0,-1,0,303,303,"Ap. 108","",0,"","","",1,0,0,[],""],["frenk_t4-ap108-05",8,"Que también San Juan Bautista,\ncon regocijo y esmero,\nde cuelga te dé un cordero\npresentándolo a tu vista;\nSan Lucas Evangelista\nhoy te venga a visitar;\nlos ángeles a cantar\ncon muy crecida alegría,\nentonen melifluo canto\npor ser hoy día de tu Santo.",168,2,11,188,"JUSTICIAS O SEAN MAÑANITAS PARA ONOMÁSTICO",18,10,"ao",30,0,-1,0,303,303,"Ap. 108","",0,"","","",1,0,0,[],""],["frenk_t4-ap108-07",8,"Santo Tomás te dará\nborla y capelo al presente,\nlas alas, un San Vicente;\nla custodia, Santa Clara;\nte dé un Patriarca la vara\ncon todas sus jerarquías,\nel Paraíso, San Elias,\ny también las Tres Marías;\nte dé gracias y virtudes\nSeñora Santa Gertrudis.",168,2,11,188,"JUSTICIAS O SEAN MAÑANITAS PARA ONOMÁSTICO",18,10,"ui",-1,0,-1,0,303,303,"Ap. 108","",0,"","","",1,0,0,[],""],["frenk_t4-ap108-10",8,"Oiga usted, doña Antoñita,\nperdone las faltas mías,\nsi a sus puertas vine a dar\nvísperas, noches y días.",168,2,11,188,"JUSTICIAS O SEAN MAÑANITAS PARA ONOMÁSTICO",0,4,"ia",214,0,-1,0,303,303,"Ap. 108","",0,"","","",1,0,0,[],""],["frenk_t4-ap108-12",8,"Oiga usted, doña Cholita,\nla culpa no tengo en nada,\nque aquí, doña Mariquita\nme mandó que le cantara.",168,2,11,188,"JUSTICIAS O SEAN MAÑANITAS PARA ONOMÁSTICO",0,4,"aa",-1,0,-1,0,303,303,"Ap. 108","",0,"","","",1,0,0,[],""],["frenk_t4-ap109-01",8,"Quisiera darte los días\ncon muy soberano anhelo\ny ser vicario de Cristo\npara despacharte al cielo.",166,2,-1,188,"DÉCIMAS DE DAR LOS DÍAS",0,4,"eo",10,0,-1,0,303,303,"Ap. 109","",0,"","","",1,0,0,[],""],["frenk_t4-ap109-02",8,"Quisiera del río Jordán\ntraerte el agua de la gracia\ny con graciosa eficacia\nel corazón de San Juan,\nla vida de San Guzmán\ny el alma de San Elias,\nSan Simón y San Matías,\npues en mi afecto veloz\nhoy en el nombre de Dios\nquisiera darte los días.",166,2,-1,188,"DÉCIMAS DE DAR LOS DÍAS",18,10,"ia",214,0,-1,0,303,303,"Ap. 109","",0,"","","",1,0,0,[],""],["frenk_t4-ap109-03",8,"Que te dé San Agustín\nde San Joaquín la victoria\ny de San Fermín la gloria\nen nombre de San Crispin,\ntambién de San Valentín,\nSan Enrique y San Marcelo,\na San Justo con anhelo\npor ser serafín llegado,\nque te libre de pecado\ncon muy soberano anhelo.",166,2,-1,188,"DÉCIMAS DE DAR LOS DÍAS",18,10,"eo",-1,0,-1,0,303,303,"Ap. 109","",0,"","","",1,0,0,[],""],["frenk_t4-ap109-04",8,"Quisiera que San Miguel\ny San Gabriel con consuelo\nte llevaran para el cielo,\nel arcángel San Rafael\ncon San Vicente Ferrer\nte bendiga un Santo Cristo,\nque te haga bueno San Sixto,\nasí lo desea mi ley,\nhoy quisiera ser un rey\no ser vicario de Cristo.",166,2,-1,188,"DÉCIMAS DE DAR LOS DÍAS",18,10,"io",-1,0,-1,0,304,304,"Ap. 109","",0,"","","",1,0,0,[],""],["frenk_t4-ap109-05",8,"En fin, la Virgen María\nte alcance mucha virtud,\nte preste vida y salud\ny que en todo sea tu guía;\ny también Santa Lucía\nde sus ojos te dé el velo\npara que andes sin recelo\ny con afecto veloz\nque fueras a ver a Dios\npara despacharte al cielo.",166,2,-1,188,"DÉCIMAS DE DAR LOS DÍAS",18,10,"eo",10,0,-1,0,304,304,"Ap. 109","",0,"","","",1,0,0,[],""],["frenk_t4-ap110-01",8,"Las muchachas casaderas\nque ya se dan al demonio\ninvocan a San Antonio\npidiendo las marrulleras:\n¡Matrimonio, matrimonio!",166,2,-1,188,"SÚPLICAS A SAN ANTONIO",7,5,"oo",169,0,-1,0,304,304,"Ap. 110","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap110-03",8,"¡Ay, Santito milagroso!,\npor tu hábito te suplico\nque me des marido rico,\njoven, gallardo y buen mozo.\nNo lo quiero pretencioso,\nni menos calaverón;\nme ha de amar de corazón\nsolito y sin compañía,\nsiempre alegre noche y día,\nhe de ser su adoración.",166,2,-1,188,"SÚPLICAS A SAN ANTONIO",18,10,"o",31,0,-1,0,304,304,"Ap. 110","",0,"","","",1,0,0,[],""],["frenk_t4-ap110-05",8,"¡San Antonio, Santo mío!,\nescucha mi petición:\ndame esposo, te lo pido\ncon todo mi corazón.\nMírame con compasión,\n¡oh San Antonio admirable!\nY dame un marido amable\ny de una edad competente;\nni joven impertinente,\nni viejo chocho intratable.",166,2,-1,188,"SÚPLICAS A SAN ANTONIO",18,10,"ae",322,0,-1,0,304,304,"Ap. 110","",0,"","","",1,0,0,[],""],["frenk_t4-ap110-07",8,"¡Ay, San Antonio!, ¿qué haré\nsi tú me niegas tu ayuda?\nSin duda me quedaré\ncomo marchita lechuga.\nYa mi juventud se fuga\ny por lo mismo te pido\nque me des un buen marido\nque me quiera y me mantenga,\nque con nadie se entretenga\ny me ame siempre rendido.",166,2,-1,188,"SÚPLICAS A SAN ANTONIO",18,10,"io",101,0,-1,0,304,304,"Ap. 110","",0,"","","",1,0,0,[],""],["frenk_t4-ap110-09",8,"San Antonio, San Antonio,\n¿por qué me has abandonado?\nMira que ya estoy pasando\nla línea del matrimonio;\nme está llevando el demonio\nen burro flaco y roñoso;\nyo lo que quiero es esposo\nsin que me importe un comino\nque parezca pergamino,\ncon tal que sea cariñoso.",166,2,-1,188,"SÚPLICAS A SAN ANTONIO",18,10,"oo",160,0,-1,0,304,304,"Ap. 110","",0,"","","",1,0,0,[],""],["frenk_t4-ap111-02",8,"No sé dónde han inventado\ntantas modas diferentes\nen las mujeres decentes\nque hay en “El Mundo Ilustrado”.\nVarias clases de peinado\nson los que se están usando;\npero ahorita está privando\nel famoso resplandor;\nlas rancheras, con honor,\na la moda están entrando.",171,2,4,188,"A LA MODA VAN ENTRANDO",18,10,"ao",33,0,-1,0,305,305,"Ap. 111","",0,"","","",1,0,0,[],""],["frenk_t4-ap111-03",8,"Muy decentes y adornadas\nvan a pasear las rancheras,\ndonde hay bailes y carreras\náhi van las desfiguradas;\ntodas ellas empolvadas\nquién sabe si hasta con cal,\ncon la baba del nopal\nllevan el pelo asentado,\ny acostumbran el peinado\ntoditas en general.",171,2,4,188,"A LA MODA VAN ENTRANDO",18,10,"a",1,0,-1,0,305,305,"Ap. 111","",0,"","","",1,0,0,[],""],["frenk_t4-ap111-04",8,"Pretenden aparentar\nde un modo decente y rico,\na cual más con su abanico\nni viento se saben dar;\npero no quieren hablar\nporque ven que andan cuadrando;\ncomo ven que andan lujando,\npara ellas es un placer,\ny aunque no sepan coser,\n¡cómo andan aparentando!",171,2,4,188,"A LA MODA VAN ENTRANDO",18,10,"ao",33,0,-1,0,305,305,"Ap. 111","",0,"","","",1,0,0,[],""],["frenk_t4-ap111-05",8,"En fin, muchachas bonitas,\nno se vayan a enojar,\nque de todas he de hablar,\nmenos de ustedes, chatitas;\nustedes, bien peinaditas,\ncon su traje de percal\nmuy decente, es natural;\nyo hablo de esas escurridas\nque como anden añadidas,\n¡qué importa que se vean mal!",171,2,4,188,"A LA MODA VAN ENTRANDO",18,10,"a",1,0,-1,0,305,305,"Ap. 111","",0,"","","",1,0,0,[],""],["frenk_t4-ap112-01",8,"Amigos, yo me casé\ncon una mujer de Tula;\nyo por yegua la compré,\ny me fue saliendo mula.",179,2,26,188,"AMIGOS, YO ME CASÉ",1,4,"ua",547,0,-1,0,305,305,"Ap. 112","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap112-02",8,"Reciban esta lección,\nno los engañe el demonio,\ntodos los que al matrimonio\nles tire la inclinación.\nYo causé mi perdición,\ncuando la novia busqué,\nde medio a medio la erré;\nlo mejor sería matarme,\nya no vale encocorarme,\namigos, yo me casé.",179,2,26,188,"AMIGOS, YO ME CASÉ",18,10,"e",77,0,-1,0,305,305,"Ap. 112","",0,"","","",1,0,0,[],""],["frenk_t4-ap112-03",8,"Mi mujer el codo sube,\ncome como un tiburón,\ny duerme más que un lirón,\ny bebe más que una nube;\nsube y baja, baja y sube\npor la calle, la muy tuna,\nni apenas lo disimula,\naunque me mire enojado;\nahora vivo condenado\ncon una mujer de Tula.",179,2,26,188,"AMIGOS, YO ME CASÉ",18,10,"ua",547,0,-1,0,305,305,"Ap. 112","",0,"","","",1,0,0,[],""],["frenk_t4-ap112-04",8,"Jamás recoge un petate,\nni un jarrita, ni una aguja,\ny pretende, la muy bruja,\nhacerme un buen chocolate.\nQuiere llenarme el tompiate,\npero yo me vengaré,\ndía y noche la cuidaré\ncon cierta cautela y maña;\nahora se me vuelve araña,\nyo por yegua la compré.",179,2,26,188,"AMIGOS, YO ME CASÉ",18,10,"e",77,0,-1,0,306,306,"Ap. 112","",0,"","","",1,0,0,[],""],["frenk_t4-ap112-05",8,"La mayor parte del día\nse pasa en fiesta y en risa,\nyo he de coser su camisa\ny he de remendar la mía.\nLe dice alguien: “Vida mía”,\ny muy pronto capitula,\nsin reconocer que es gula\nel usar la carne ajena;\nyo la tomé por muy buena\ny me fue saliendo muía.",179,2,26,188,"AMIGOS, YO ME CASÉ",18,10,"ia",0,0,-1,0,306,306,"Ap. 112","",0,"","","",1,0,0,[],""],["frenk_t4-ap114-01",8,"Todos marchamos para el panteón,\na donde marchan los que se mueren.\nUnos queremos, otros no quieren\ndejar del mundo la diversión.",175,2,6,188,"DANZA DE LA MUERTE",3,4,"o",31,0,-1,0,306,306,"Ap. 114","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-01",8,"Adiós, mis señores amos,\nya me voy al triste olvido;\nadiós, mi casa querida,\nen donde estuve tendido.",166,2,-1,188,"DESPEDIMENTO",0,4,"io",101,0,-1,0,307,307,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-02",8,"Hijos míos, ya no quisiera\nescuchar su triste llanto,\nporque voy al camposanto\na que me cubra la tierra.",166,2,-1,188,"DESPEDIMENTO",5,4,"ea",-1,0,-1,0,307,307,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-03",8,"Quédate, esposa, con Dios,\nya me voy a separar:\nnos veremos ambos dos\nen el Santo Tribunal.",166,2,-1,188,"DESPEDIMENTO",0,4,"a",-1,0,-1,0,307,307,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-04",8,"De todos mis parientes\nme despido en general;\ndispensen hoy mis molestias\nde venirme a acompañar.",166,2,-1,188,"DESPEDIMENTO",0,4,"a",-1,0,-1,0,307,307,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-05",8,"Adiós, compañeros queridos\nque me van a sepultar;\nal sepulcro del olvido\ndonde hemos de ir a parar.",166,2,-1,188,"DESPEDIMENTO",0,4,"a",21,0,-1,0,307,307,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-06",8,"Adiós, mundo delicioso\ndonde quise yo triunfar;\nya llegó el día riguroso\nde empezar a compurgar.",166,2,-1,188,"DESPEDIMENTO",1,4,"a",21,0,-1,0,307,307,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-07",8,"Adiós, mi acompañamiento,\nque me has estado velando;\nya se llegó la hora y tiempo\nde que me vayan sacando.",166,2,-1,188,"DESPEDIMENTO",0,4,"ao",33,0,-1,0,307,307,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-08",8,"Adiós, el triste solar\ndonde fue mi habitación;\na mis parientes les pido:\nno me vayan a olvidar.",166,2,-1,188,"DESPEDIMENTO",5,4,"a",21,0,-1,0,307,307,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-09",8,"Adiós, padre de mi vida,\nmadre de mi corazón;\nllegó mi triste partida\npara la helada mansión.",166,2,-1,188,"DESPEDIMENTO",1,4,"o",31,0,-1,0,307,307,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-10",8,"Adiós, hijos de mi vida,\nhijas de todo mi amor;\nya me voy al camposanto\npor mandato del Señor.",166,2,-1,188,"DESPEDIMENTO",0,4,"o",72,0,-1,0,307,307,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-11",8,"Adiós, hermanas y hermanos,\n¡válgame la Virgen pura!\nA convertirme en gusanos\nme voy a la sepultura.",166,2,-1,188,"DESPEDIMENTO",1,4,"ua",17,0,-1,0,307,307,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-12",8,"Adiós, mis queridos suegros\ny vecinos de este lugar,\npor amor de Dios les pido\nque me vengan a cargar.",166,2,-1,188,"DESPEDIMENTO",0,4,"a",21,0,-1,0,308,308,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-13",8,"Adiós, astros y luceros,\nluna, sol y firmamento,\nadiós, arena y viento\nque fueron mis compañeros.",166,2,-1,188,"DESPEDIMENTO",11,4,"eo",-1,0,-1,0,308,308,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-14",8,"Espero que San Gregorio\nde allí me ha de sacar;\nde aquel Santo Purgatorio\npara poderme salvar.",166,2,-1,188,"DESPEDIMENTO",1,4,"a",21,0,-1,0,308,308,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-15",8,"No te acuestes en pecado\nporque es cierto y evidente:\npuedes morir de repente\ny amanecer condenado.",166,2,-1,188,"DESPEDIMENTO",11,4,"ao",14,0,-1,0,308,308,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-16",8,"De este mundo has de sacar,\naunque el dinero te sobre,\nsólo una mortaja pobre\npara llevarte a enterrar.",166,2,-1,188,"DESPEDIMENTO",11,4,"a",21,0,-1,0,308,308,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap115-17",8,"Alabemos, hermanitos,\na Jesús, María y José,\nen los cielos y en la tierra\ny en todo lugar, amén.",166,2,-1,188,"DESPEDIMENTO",3,4,"e",-1,0,-1,0,308,308,"Ap. 115","",0,"","","",1,0,0,[],""],["frenk_t4-ap116-01",8,"Me despido tristemente\nde la casa donde estoy;\ny adiós y adiós,\ny adiós, porque ya me voy.",177,2,18,188,"LOS PARABIENES",0,4,"o",-1,0,-1,0,308,308,"Ap. 116","",0,"","","",1,0,0,[],""],["frenk_t4-ap116-02",8,"Adiós, mi padre y mi madre,\nadiós también mis hermanos;\ny adiós y adiós,\nla tierra me está llamando.",177,2,18,188,"LOS PARABIENES",0,4,"ao",-1,0,-1,0,308,308,"Ap. 116","",0,"","","",4,0,0,[],""],["frenk_t4-ap116-03",8,"Adiós, mi madre querida,\ntú siempre sigue llorando;\ny adiós y adiós,\nla tierra me está llamando.",177,2,18,188,"LOS PARABIENES",0,4,"ao",33,0,-1,0,308,308,"Ap. 116","",0,"","","",5,0,0,[],""],["frenk_t4-ap116-04",8,"No llores, madre querida,\nque Dios te dio esta victoria;\ny adiós y adiós;\ndéjame ganar mi gloria.",177,2,18,188,"LOS PARABIENES",0,4,"oa",126,0,-1,0,308,308,"Ap. 116","",0,"","","",3,0,0,[],""],["frenk_t4-ap116-05",8,"Adiós, mi madre querida,\nque Dios me dio esta victoria;\ny adiós y adiós;\ndéjame gozar mi gloria.",177,2,18,188,"LOS PARABIENES",0,4,"oa",126,0,-1,0,308,308,"Ap. 116","",0,"","","",5,0,0,[],""],["frenk_t4-ap116-06",8,"Adiós, mi padre y mi madre,\nadiós también mis padrinos;\ny adiós y adiós,\nvoy a tomar mi camino.",177,2,18,188,"LOS PARABIENES",0,4,"io",-1,0,-1,0,308,308,"Ap. 116","",0,"","","",4,0,0,[],""],["frenk_t4-ap116-07",8,"Adiós, mi madre querida,\nyo ya voy en el camino;\ny adiós y adiós,\nmi madrina y mi padrino.",177,2,18,188,"LOS PARABIENES",0,4,"io",199,0,-1,0,308,308,"Ap. 116","",0,"","","",5,0,0,[],""],["frenk_t4-ap116-08",8,"Los acentos de mi casa\nrevelan la ingratitud;\ny adiós y adiós,\npadres, y buena salud.",177,2,18,188,"LOS PARABIENES",0,4,"u",278,0,-1,0,308,308,"Ap. 116","",0,"","","",1,0,0,[],""],["frenk_t4-ap116-09",8,"No llores, madre querida,\nmadre de toda la rama;\nya se va tu hijo querido,\nnacido de tus entrañas.",177,2,18,188,"LOS PARABIENES",0,4,"aa",-1,0,-1,0,308,308,"Ap. 116","",0,"","","",3,0,0,[],""],["frenk_t4-ap116-10",8,"No llores, madre querida,\nfuente de toda la rama;\ny adiós y adiós,\ncon mi corona y mi palma.\nSe fue una prenda querida\nnacida de tus entrañas.",177,2,18,188,"LOS PARABIENES",9,6,"aa",-1,0,-1,0,308,308,"Ap. 116","",0,"","","",3,0,0,[],""],["frenk_t4-ap117-02",8,"¡Ay!, pues éste ¿qué pensaría?,\n¿que me los hacían de un violín?\n¡Ay!, pues yo soy uil probe al fin,\nla mal obra que me hacía;\nfue grande su picardía,\n¡ay!, al punto tuve razón:\nque le agarre una comezón;\n¡ay!, que se destripe a arañones,\nque le den fuertes torzones\nal que se hurtó mi timón.",176,2,3,188,"EL TIMÓN",18,10,"o",31,0,-1,0,309,309,"Ap. 117","",0,"","","",1,0,0,[],""],["frenk_t4-ap117-03",8,"¡Ay!, lo despacharon con brillo\na beber agua salada;\n¡ay!, que lo arroje una manada\ny un coce le dé un potrillo,\nlos ojos le mee un zorrillo;\n¡ay!, pa cuando vaya desesperado\nno vaya a ver otro arado;\n¡ay!, por un mal de corazón,\nque hasta el infierno no pare\nel que se hurtó mi timón.",176,2,3,188,"EL TIMÓN",18,10,"o",31,0,-1,0,309,309,"Ap. 117","",0,"","","",1,0,0,[],""],["frenk_t4-ap117-04",8,"¡Ay!, le demando mis atrasos\npara su mayor gobierno;\n¡ay!, que pase por el infierno\ny que le den fuertes diablazos,\ntambién unos pisonazos;\n¡ay!, ha de llevar mi timón\nsirviéndole de bordón;\n¡ay!, el diablillo más chiquillo\nque lo arrastre del jondillo\nal que se hurtó mi timón.",176,2,3,188,"EL TIMÓN",18,10,"o",31,0,-1,0,309,309,"Ap. 117","",0,"","","",1,0,0,[],""],["frenk_t4-ap117-05",8,"¡Ay!, despedida no les doy\nporque a mí no me conviene,\n¡ay!, porque esta vida y en la otra\nlo que uno granjea, eso tiene.",176,2,3,188,"EL TIMÓN",3,4,"ee",70,0,-1,0,309,309,"Ap. 117","",0,"","","",3,0,0,[],""],["frenk_t4-ap118-01",8,"¡Ay!, el dientito de este anciano,\n¡ay!, cuánto dinero me ha dado;\n¡ay!, le saqué enclavijaduras\ny al arpa de Atilano,\nhecha de mi propia mano.",176,2,3,188,"EL DIENTITO DE CABADA",7,5,"ao",81,0,-1,0,309,309,"Ap. 118","",0,"","","",1,0,0,[],""],["frenk_t4-ap118-02",8,"¡Ay!, guitarras enhuesadas\ncon sus huecos y boqueadas,\n¡ay!, varias cositas al fin;\nclavijas le eché a un violín\nde ese diente de Cabada.",176,2,3,188,"EL DIENTITO DE CABADA",7,5,"aa",-1,0,-1,0,309,309,"Ap. 118","",0,"","","",1,0,0,[],""],["frenk_t4-ap118-03",8,"¡Ay!, don Apolonio Mendoza,\ncomo acordaba el suplente,\n¡ay!, le ha regalado ¿abadas\nun dineral en un diente,\npero fino solamente.",176,2,3,188,"EL DIENTITO DE CABADA",7,5,"ee",15,0,-1,0,309,309,"Ap. 118","",0,"","","",1,0,0,[],""],["frenk_t4-ap118-04",8,"¡Ay! tres onzas tengo sacadas;\naquí las tengo sumadas,\n¡ay!, con la pluma y el tintero;\nme ha dado mucho dinero\nel dientito de este anciano;",176,2,3,188,"EL DIENTITO DE CABADA",7,5,"ao",-1,0,-1,0,309,309,"Ap. 118","",0,"","","",1,0,0,[],""],["frenk_t4-ap118-05",8,"¡Ay!, del dientito de este anciano,\nde los mejores raigones,\n¡ay!, luego me senté y forjé\nunos doce piscalones\npara toditos mis peones.",176,2,3,188,"EL DIENTITO DE CABADA",7,5,"oe",34,0,-1,0,309,309,"Ap. 118","",0,"","","",1,0,0,[],""],["frenk_t4-ap118-06",8,"¡Ay!, una cosecha mentada,\nva la tenía preparada,\nlay!, que otro día la iba a empezar;\nsaqué un tarro pa ordeñar\nde este diente de Cabada.",176,2,3,188,"EL DIENTITO DE CABADA",7,5,"aa",49,0,-1,0,310,310,"Ap. 118","",0,"","","",1,0,0,[],""],["frenk_t4-ap118-07",8,"¡Ay!, por fin siempre me ha dado\nvarias obritas buenas;\n¡ay!, cuatro cachas de machete,\ntambién unas seis barrenas,\ntres partidores apenas.",176,2,3,188,"EL DIENTITO DE CABADA",7,5,"ea",62,0,-1,0,310,310,"Ap. 118","",0,"","","",1,0,0,[],""],["frenk_t4-ap118-08",8,"¡Ay!, peinetas muy regaladas\npara uso de mis chorreadas,\n¡ay!, para que se aten al pelo;\nbadajo le eché a un cencerro\nde ese diente de Cabada.",176,2,3,188,"EL DIENTITO DE CABADA",7,5,"aa",-1,0,-1,0,310,310,"Ap. 118","",0,"","","",1,0,0,[],""],["frenk_t4-ap118-09",8,"¡Ay! despedida no les doy\nporque a mí no me conviene,\n¡ay! que en esta vida y en la otra\nlo que uno granjea, eso tiene.",176,2,3,188,"EL DIENTITO DE CABADA",3,4,"ee",70,0,-1,0,310,310,"Ap. 118","",0,"","","",3,0,0,[],""],["frenk_t4-ap119-01",8,"Esas tierras del rincón\nlas sembré con un buey pando;\ny se reventó el barzón,\ny siempre la yunta andando.",166,2,-1,188,"EL BARZÓN",1,4,"ao",33,0,-1,0,310,310,"Ap. 119","",0,"","","",1,0,0,[],""],["frenk_t4-ap119-09",8,"Cuando yo la fui a pizcar,\nel máiz estaba bien dado,\nel máiz estaba muy basto;\nse me desaró el canasto,\ncompuse bien mi montón,\nse me quebró el pizcador,\ny se me zafó el cotón;\nel máiz estaba podrido,\ny se quebró el pizcador\ny siempre seguí pizcando.",166,2,-1,188,"EL BARZÓN",18,10,"ao",-1,0,-1,0,311,311,"Ap. 119","",0,"","","",1,0,0,[],""],["frenk_t4-ap120-01",8,"Mandé hacer un pantalón,\nchaleco, corbata y blusa,\ny también un chaquetón\nde la purita gamuza.",187,2,12,188,"RELACIÓN DE UN CHARRO",1,4,"ua",599,0,-1,0,312,312,"Ap. 120","",0,"","","",1,0,0,[],""],["frenk_t4-ap120-02",8,"Tengo mis botas vaqueras,\nmis espuelas, mis polainas,\nreata, cuarta y chaparreras;\nbrillantes pantaloneras\npara pasear el cantón.",187,2,12,188,"RELACIÓN DE UN CHARRO",7,5,"o",-1,0,-1,0,312,312,"Ap. 120","",0,"","","",1,0,0,[],""],["frenk_t4-ap120-03",8,"Aunque vean que no trabajo,\npero tengo, para todo el año,\nen engorda un caballo\npara estrenar ese traje.",187,2,12,188,"RELACIÓN DE UN CHARRO",3,4,"ae",-1,0,-1,0,312,312,"Ap. 120","",0,"","","",1,0,0,[],""],["frenk_t4-ap120-04",8,"Para que vean que no soy guaje\ny mi pecho no se excusa;\nencargué una capiruza\nde la nación extranjera,\nde terciopelo y seda.",187,2,12,188,"RELACIÓN DE UN CHARRO",7,5,"ea",-1,0,-1,0,313,313,"Ap. 120","",0,"","","",1,0,0,[],""],["frenk_t4-ap120-05",8,"Tengo mis buenas espuelas,\nmanga de hule y chivarreras\nde una onza en cada botón;\nde charro estoy arreglado.",187,2,12,188,"RELACIÓN DE UN CHARRO",5,4,"ao",-1,0,-1,0,313,313,"Ap. 120","",0,"","","",1,0,0,[],""],["frenk_t4-ap120-06",8,"Tengo para mi calzado\nbotines muy elegantes;\npara mis manos unos guantes,\ny un sombrero galoneado,\nde hilo de oro bordado.",187,2,12,188,"RELACIÓN DE UN CHARRO",7,5,"ao",14,0,-1,0,313,313,"Ap. 120","",0,"","","",1,0,0,[],""],["frenk_t4-ap120-07",8,"Aunque no soy de balcón\nme gusta la compostura;\nde oro la botonadura\nmandé hacer de un pantalón.",187,2,12,188,"RELACIÓN DE UN CHARRO",11,4,"o",31,0,-1,0,313,313,"Ap. 120","",0,"","","",1,0,0,[],""],["frenk_t4-ap120-08",8,"Como único millonario\ncompré un potro a Salomón:\ndiez cuartas, siete colores,\npara pasear mis amores;\nme cuesta el cuaco un millón.",187,2,12,188,"RELACIÓN DE UN CHARRO",7,5,"o",31,0,-1,0,313,313,"Ap. 120","",0,"","","",1,0,0,[],""],["frenk_t4-ap120-09",8,"Para salir a pasear\ntengo plata que gastar;\nlo digo y lo verifico\ny les doy satisfacción.",187,2,12,188,"RELACIÓN DE UN CHARRO",5,4,"o",-1,0,-1,0,313,313,"Ap. 120","",0,"","","",1,0,0,[],""],["frenk_t4-ap121-01",8,"Yo tenía un borrego gordo\ny no lo quería vender;\ny un amigo ya me daba\nquinientos pesos por él.",181,2,15,188,"PURAS LANAS",0,4,"e",-1,0,-1,0,313,313,"Ap. 121","",0,"","","",1,0,0,[],""],["frenk_t4-ap121-02",8,"Los cuernos se los quité;\nhice peinetas muy finas,\ny a peso me las pagaban\ntodititas las catrinas.",181,2,15,188,"PURAS LANAS",0,4,"ia",243,0,-1,0,313,313,"Ap. 121","",0,"","","",1,0,0,[],""],["frenk_t4-ap121-03",8,"La lana se la quité\ny me fui para Dolores;\nsaqué doscientas cobijas\ny quinientos cobertores.",181,2,15,188,"PURAS LANAS",0,4,"oe",5,0,-1,0,313,313,"Ap. 121","",0,"","","",1,0,0,[],""],["frenk_t4-ap121-04",8,"Las patas no las guisé;\nlas dejé para escabeche,\ny un amigo las cambió\npor ocho jarras de leche.",181,2,15,188,"PURAS LANAS",0,4,"ee",180,0,-1,0,313,313,"Ap. 121","",0,"","","",1,0,0,[],""],["frenk_t4-ap121-05",8,"El menudo lo guisé\ny me fui pa Guanajuato;\nallá lo estuve vendiendo\na quince pesos el plato.",181,2,15,188,"PURAS LANAS",0,4,"ao",19,0,-1,0,313,313,"Ap. 121","",0,"","","",1,0,0,[],""],["frenk_t4-ap121-06",8,"La cola era tan grande\ncomo todos lo verán:\nque la pusieron de puente\nen Barranca de Beltrán.",181,2,15,188,"PURAS LANAS",0,4,"a",147,0,-1,0,313,313,"Ap. 121","",0,"","","",1,0,0,[],""],["frenk_t4-ap121-07",8,"Pudiera seguir contando\nlo que saqué a mi borrega,\npero temo que me digan:\n“¡Ya no pega, ya no pega!”",181,2,15,188,"PURAS LANAS",0,4,"ea",257,0,-1,0,313,313,"Ap. 121","",0,"","","",1,0,0,[],""],["frenk_t4-ap121-08",8,"Con ésta ya me despido\npor el cerro Palanganas;\naquí se acaban cantando\nlos versos de “puras lanas”.",181,2,15,188,"PURAS LANAS",0,4,"aa",263,0,-1,0,313,313,"Ap. 121","",0,"","","",2,0,0,[],""],["frenk_t4-ap122-01",8,"Yo tenía una puerca pinta\nque un amigo me vendió;\ntan amigo me salió\nque en dos reales me la dio.",194,2,29,188,"LA PUERQUITA PINTA",0,4,"o",2,0,-1,0,313,313,"Ap. 122","",0,"","","",1,0,0,[],""],["frenk_t4-ap122-03",8,"Las pestañas de mi puerca\nparecían unas balcarrias;\ndesde lejos se le veían:\nparecían agujas de arria.",194,2,29,188,"LA PUERQUITA PINTA",0,4,"aa",-1,0,-1,0,313,313,"Ap. 122","",0,"","","",1,0,0,[],""],["frenk_t4-ap122-05",8,"Los ojitos de mi puerca\nya se le estaban secando\ndesde lejos se le veían\ncomo la luna llorando.",194,2,29,188,"LA PUERQUITA PINTA",0,4,"ao",33,0,-1,0,314,314,"Ap. 122","",0,"","","",1,0,0,[],""],["frenk_t4-ap122-07",8,"L’espinazo de mi puerca\nse lo di a la vida mía;\nde tan sabroso que estaba\nhasta los huesos lambía.",194,2,29,188,"LA PUERQUITA PINTA",0,4,"ia",0,0,-1,0,314,314,"Ap. 122","",0,"","","",1,0,0,[],""],["frenk_t4-ap122-09",8,"Del cuerito de mi puerca\nhice muchos chicharrones;\nlos comieron mis paisanos\nreventando por tragones.",194,2,29,188,"LA PUERQUITA PINTA",0,4,"oe",34,0,-1,0,314,314,"Ap. 122","",0,"","","",1,0,0,[],""],["frenk_t4-ap122-11",8,"El rabito de mi puerca\nera todo un movimiento;\ny dispénsenme, señores,\nque si no la echo, reviento.",194,2,29,188,"LA PUERQUITA PINTA",0,4,"eo",94,0,-1,0,314,314,"Ap. 122","",0,"","","",1,0,0,[],""],["frenk_t4-ap122-13",8,"La manteca de mi puerca\nla vendí para un bailecito,\ny a dos pesos kilo\nla pagó ’ñor Pascualito.",194,2,29,188,"LA PUERQUITA PINTA",0,4,"io",-1,0,-1,0,314,314,"Ap. 122","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-01",8,"Tengan cuidado, señores,\nlo que les voy a contar:\nlos versitos de “La pulga”\nse los voy a figurar.",182,2,21,188,"DE LA PULGA",0,4,"a",21,0,-1,0,314,314,"Ap. 123","",0,"","","",2,0,0,[],""],["frenk_t4-ap123-02",8,"Era una pulga tan grande\ny ligera para andar,\nque cansó tres mil caballos\npara poderla alcanzar.",182,2,21,188,"DE LA PULGA",0,4,"a",21,0,-1,0,314,314,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-03",8,"Y cuando ya la alcanzaron\nfue cuando se dominó:\nreventó cien calabrotes,\notros de acero trozó.",182,2,21,188,"DE LA PULGA",0,4,"o",2,0,-1,0,314,314,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-04",8,"Para poderla tumbar,\n¡ah!, qué trabajos tan peores,\nque no la podían tumbar\nmás de doscientos vapores.",182,2,21,188,"DE LA PULGA",1,4,"oe",5,0,-1,0,314,314,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-05",8,"Y cuando ya la tumbaron\ndespués de harto batallar,\nquebró trescientos cuchillos\npara poderla matar.",182,2,21,188,"DE LA PULGA",0,4,"a",21,0,-1,0,314,314,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-06",8,"¡Ay!, cuando abrieron la pulga,\n¡ay, ay, qué animal tan grande!;\nle sacaron cien barriles\nde muy gorda y buena sangre.",182,2,21,188,"DE LA PULGA",0,4,"ae",-1,0,-1,0,314,314,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-07",8,"Ahí los lomos de la pulga\ntrozados y en pedazones;\npara poderlos llevar,\npoco fueron diez furgones.",182,2,21,188,"DE LA PULGA",0,4,"oe",34,0,-1,0,314,314,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-08",8,"El corazón de la pulga\nlo ha comprado un general\npara ración de sus tropas;\ntreinta días tuvo que dar.",182,2,21,188,"DE LA PULGA",0,4,"a",-1,0,-1,0,314,314,"Ap. 123","",0,"","","",2,0,0,[],""],["frenk_t4-ap123-09",8,"De la pulga salió aceite\ny no son exageradas:\nla cantidad que salió\nfueron tres mil toneladas.",182,2,21,188,"DE LA PULGA",0,4,"aa",282,0,-1,0,314,314,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-10",8,"Del gurguñate tan grande\nancho y de buen agujero,\nlo llevaron a una mina\nque sirviera de caldero.",182,2,21,188,"DE LA PULGA",0,4,"eo",38,0,-1,0,314,314,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-11",8,"Áhi, cuando abrieron la pulga,\ncuando ya la destazaron,\nestaban duros los huesos;\nmás de mil hachas quebraron.",182,2,21,188,"DE LA PULGA",0,4,"ao",41,0,-1,0,314,314,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-12",8,"Áhi, cuando frieron la carne,\nle sacaron buena ley;\nse repartió en tres Estados:\nSan Luis, León y Monterrey.",182,2,21,188,"DE LA PULGA",0,4,"e",133,0,-1,0,314,314,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-13",8,"El cuero estaba muy grande,\nera muy bonito cuero;\nen alfombra convertido,\nalfombró un palacio entero.",182,2,21,188,"DE LA PULGA",0,4,"eo",38,0,-1,0,315,315,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-14",8,"La cabeza no era grande,\ncon qué compararla no hallo;\nle cupo la infantería\ny doscientos de a caballo.",182,2,21,188,"DE LA PULGA",0,4,"ao",102,0,-1,0,315,315,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-15",8,"Las pezuñas de la pulga,\ny esto no es ningún alarde,\nsirvieron como casinos\ny salones para baile.",182,2,21,188,"DE LA PULGA",0,4,"ae",-1,0,-1,0,315,315,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-16",8,"¡Ay!, los huesos de la pulga\nocasionaron un lío:\npudieron utilizarlos\nde mástiles de un navio.",182,2,21,188,"DE LA PULGA",0,4,"io",-1,0,-1,0,315,315,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-17",8,"Las tripas largas y gordas\nlas han venido a comprar\npara ponerlas de cable\nen la línea federal.",182,2,21,188,"DE LA PULGA",0,4,"a",-1,0,-1,0,315,315,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-18",8,"En fin, esta era una pulga\nnacida, creo, en el Japón;\nde un brinco, ochocientas leguas\nabarcaba de un jalón.",182,2,21,188,"DE LA PULGA",0,4,"o",31,0,-1,0,315,315,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-19",8,"Sirvió de buque de guerra,\npa navegar en el mar;\nle cabían trescientos mil\nsoldados para pelear.",182,2,21,188,"DE LA PULGA",0,4,"a",21,0,-1,0,315,315,"Ap. 123","",0,"","","",1,0,0,[],""],["frenk_t4-ap123-20",8,"Ya con ésta me despido,\n“La pulga” les he cantado;\nsi no me lo quieren creer,\nni me las echo de lado.",182,2,21,188,"DE LA PULGA",0,4,"ao",14,0,-1,0,315,315,"Ap. 123","",0,"","","",71,0,0,[],""],["frenk_t4-ap124-01",8,"Yo vide a un triste zancudo\nuna torre fabricando;\ncon su azadón en la mano\nestaba desquelitando.",166,2,-1,188,"YO VIDE UN TRISTE ZANCUDO",0,4,"ao",-1,0,-1,0,315,315,"Ap. 124","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap124-02",8,"Vide un mayate escribiendo\nen una boda, una noche,\nvi cantar a un cuitlacoche\ncon las alitas bullendo;\nvide una liebre moliendo\nen un cuarto muy oscuro;\ntambién, guisando menudo\nuna rana en su cazuela;\ncantando con su vihuela\nyo vide a un triste zancudo.",166,2,-1,188,"YO VIDE UN TRISTE ZANCUDO",18,10,"uo",191,0,-1,0,315,315,"Ap. 124","",0,"","","",1,0,0,[],""],["frenk_t4-ap124-03",8,"También vide en una plaza\nestar peleando dos machos;\ny unos ratones borrachos\nestar haciendo una casa;\noí cantar una torcaza\ny una pulga estar lavando,\ny a una tortuga bordando;\ntanta vergüenza le cupo\nel ver a un triste gorupo\nuna torre fabricando.",166,2,-1,188,"YO VIDE UN TRISTE ZANCUDO",18,10,"ao",33,0,-1,0,315,315,"Ap. 124","",0,"","","",1,0,0,[],""],["frenk_t4-ap124-04",8,"También vide en una estancia\nde caporal un zorrillo\ncorriendo tras un novillo,\ny se le quebró la lanza;\na sus vaqueros alcanza\ny dice: “Miren, hermanos,\nremuden en dos gusanos\ny tráiganme mi rejón,\nque me ha cansado un tejón\ncon su azadón en la mano.”",166,2,-1,188,"YO VIDE UN TRISTE ZANCUDO",18,10,"ao",-1,0,-1,0,315,315,"Ap. 124","",0,"","","",1,0,0,[],""],["frenk_t4-ap124-05",8,"Vide a un par de guajolotes\ntambién corriendo parejas;\nde pastor de unas ovejas\nvide venir un coyote;\nde vecino a un tecolote,\nlos dos se paran cantando;\nvide a un chapulín marchando\ncon su gorro en la cabeza\ny un conejo en una mesa\nestaba desquelitando.",166,2,-1,188,"YO VIDE UN TRISTE ZANCUDO",18,10,"ao",33,0,-1,0,315,315,"Ap. 124","",0,"","","",1,0,0,[],""],["frenk_t4-ap125-01",8,"Amigos, les contaré\nlo que son los animales:\nyo vide tejer guacales\ncon las costuras de hilacho.",166,2,-1,188,"A LOS ANIMALES",5,4,"ao",-1,0,-1,0,316,316,"Ap. 125","",0,"","","",3,0,0,[],""],["frenk_t4-ap125-02",8,"Cuatro palomas rascuachas\nme pelaban tantos dientes,\ntan blancos y relucientes\nque parecían de marfil.",166,2,-1,188,"A LOS ANIMALES",5,4,"i",-1,0,-1,0,316,316,"Ap. 125","",0,"","","",1,0,0,[],""],["frenk_t4-ap125-03",8,"Les conté seiscientos mil,\naparte de los colmillos;\nlos pericos amarillos\nregañando al comején.",166,2,-1,188,"A LOS ANIMALES",5,4,"e",-1,0,-1,0,316,316,"Ap. 125","",0,"","","",1,0,0,[],""],["frenk_t4-ap125-04",8,"El zancudo y el jején\nse agarraron a guantadas;\nlas avispas coloradas\nregañando a los coyotes.",166,2,-1,188,"A LOS ANIMALES",5,4,"oe",-1,0,-1,0,316,316,"Ap. 125","",0,"","","",1,0,0,[],""],["frenk_t4-ap125-05",8,"Yo vide cocer camotes\na una pobre cucaracha;\ntambién vide agarrar su hacha\nal perro, sin dilación.",166,2,-1,188,"A LOS ANIMALES",5,4,"o",-1,0,-1,0,316,316,"Ap. 125","",0,"","","",1,0,0,[],""],["frenk_t4-ap125-06",8,"También vide al arvejón\napadrinando un mayate;\ntoditos con su sarape\npor las calles correteando.",166,2,-1,188,"A LOS ANIMALES",5,4,"ao",-1,0,-1,0,316,316,"Ap. 125","",0,"","","",1,0,0,[],""],["frenk_t4-ap125-07",8,"Vide una lechuza vieja\nencima de una ladera;\nvide un conejo con cuera\nremendando sus costales.",166,2,-1,188,"A LOS ANIMALES",5,4,"ae",-1,0,-1,0,316,316,"Ap. 125","",0,"","","",1,0,0,[],""],["frenk_t4-ap125-08",8,"Vide un lagartijo arando,\nunciendo dos jabalíes;\nvide un sapo con botines\npara montar a caballo.",166,2,-1,188,"A LOS ANIMALES",5,4,"ao",-1,0,-1,0,316,316,"Ap. 125","",0,"","","",1,0,0,[],""],["frenk_t4-ap125-09",8,"Ya no les explico más,\npues ya vienen los rurales;\ny aquí se acaban cantando\nlos versos de los animales.",166,2,-1,188,"A LOS ANIMALES",3,4,"ae",26,0,-1,0,316,316,"Ap. 125","",0,"","","",1,0,0,[],""],["frenk_t4-ap126-01",8,"Cuando me traían mis padres\nbien vestidito, con mis dos mudas;\nhora me parezco a Judas\npor lo harapiento.\nComo gato de convento\npor los rincones,\nremendando mis calzones\ncon pita floja;\ny esta vieja tan loca\nque me ha salido.",177,2,18,188,"EL SOLTERITO",18,10,"io",-1,0,-1,0,316,316,"Ap. 126","",0,"","","",1,0,0,[],""],["frenk_t4-ap126-02",8,"Me voy para Guanajuato\na comprar cueros;\ny pongo una cría de puercos,\nde esos pelones\npa chicharrones.",177,2,18,188,"EL SOLTERITO",7,5,"oe",34,0,-1,0,316,316,"Ap. 126","",0,"","","",1,0,0,[],""],["frenk_t4-ap127-01",8,"Me dio un perro una mordida,\nun burro me dio una coz;\nmi mujer se fue con otro;\nsea por el amor de Dios.",168,2,11,188,"ME DIO UN PERRO UNA MORDIDA",0,4,"o",87,0,-1,0,317,317,"Ap. 127","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap127-02",8,"Un toro pinto bramaba\nporque no tenía camisa,\ny un gallo que lo miraba\nya reventaba de risa;\nuna ardilla decía misa,\nle ayudaba un guajolote;\ny a un chapulín muy grandote\nle echaban una medida;\npor estar mirando yo esto\nme dio un perro una mordida.",168,2,11,188,"ME DIO UN PERRO UNA MORDIDA",18,10,"ia",37,0,-1,0,317,317,"Ap. 127","",0,"","","",1,0,0,[],""],["frenk_t4-ap127-03",8,"Un elefante peleaba\npor amor de una pollita;\ny una garrapata dice:\n—Mírame, yo soy bonita.\n—El amor nunca me incita,\nle respondió un zopilote;\nentró luego un guajolote\ny hablándoles a los dos\nmuy quejumbroso les dice:\n—Un burro me dio una coz.",168,2,11,188,"ME DIO UN PERRO UNA MORDIDA",18,10,"o",280,0,-1,0,317,317,"Ap. 127","",0,"","","",1,0,0,[],""],["frenk_t4-ap127-04",8,"Una ardilla picarona\nse enamoró de un pichón;\n'in lobo pone atención\ny le dice a un armadillo:\n—Si otro caballo no ensillo,\nme andaré como tortuga.\n—¿Qué quieres?, dice una oruga\nyo te prestaré mi potro;\ny un sapo triste decía:\n—Mi mujer se fue con otro.",168,2,11,188,"ME DIO UN PERRO UNA MORDIDA",18,10,"oo",275,0,-1,0,317,317,"Ap. 127","",0,"","","",1,0,0,[],""],["frenk_t4-ap127-05",8,"Un gato muy enojado\nregañaba inconsecuente,\ny un pato le respondió:\n—Con amor nada se siente.\n—Yo voy a ser presidente,\nle responde un escorpión;\nreza luego una oración\nla rata y le da la tos;\ny un cuervo le dice: —Niña,\nsea por el amor de Dios.",168,2,11,188,"ME DIO UN PERRO UNA MORDIDA",18,10,"o",87,0,-1,0,317,317,"Ap. 127","",0,"","","",1,0,0,[],""],["frenk_t4-ap127-06",8,"—¡Sea por el amor de Dios!,\nun perro prieto decía.\n—Si me caso, dice un pollo,\nserá por la sacristía.\n—No tengo madre ni tía,\nun mono le respondió,\ny una chicharra cantó\nel son de una seguidilla,\ny un perico dice al punto:\n—A mí ninguno me pilla.",168,2,11,188,"ME DIO UN PERRO UNA MORDIDA",18,10,"ia",162,0,-1,0,317,317,"Ap. 127","",0,"","","",2,0,0,[],""],["frenk_t4-ap127-07",8,"—Un burro me dio una coz,\ndecía cierta golondrina,\ny un macho cabrío le dice:\n—Quién te manda ser catrina.\n—Quiero que sea mi madrina,\ndice un oso a una culebra;\ny por novia el ajolote\nquiere pedir a la zebra;\n“por delgada, canta el mosco,\nsiempre se revienta la hebra”.",168,2,11,188,"ME DIO UN PERRO UNA MORDIDA",18,10,"ea",642,0,-1,0,317,317,"Ap. 127","",0,"","","",1,0,0,[],""],["frenk_t4-ap127-08",8,"—Mi mujer se fue con otro,\ncontestaba un alacrán,\nsi no la encuentro yo me hago\nun cura o buen sacristán.\n—Amigo, no tenga afán,\nle dice una guacamaya,\nyo también me encuentro triste,\nporque no tengo pitaya;\ndéjese de sentimientos\ny a mi jaula luego vaya.",168,2,11,188,"ME DIO UN PERRO UNA MORDIDA",18,10,"aa",404,0,-1,0,317,317,"Ap. 127","",0,"","","",1,0,0,[],""],["frenk_t4-ap127-09",8,"—¡Sea por el amor de Dios!,\nexclama un quebrantahuesos,\ny un gavilán riendo dice:\n—Como máiz, yo tengo pesos.\n—Dame mi pico, mis besos,\nuna tórtola decía\na un orangután que entonces\ntocaba la chirimía;\ny de toda esta monserga\nuna pipila reía.",168,2,11,188,"ME DIO UN PERRO UNA MORDIDA",18,10,"ia",0,0,-1,0,317,317,"Ap. 127","",0,"","","",2,0,0,[],""],["frenk_t4-ap130-01",8,"Todos ’tan en el estrado,\nlos novios en la pandilla,\ncuando llegó la aguililla\nechándoselas de lado:\n“Donde quiera me he paseado,\nyo no he sido escandalosa”;\nle dijo a la mariposa:\n“Vámonos a andar al monte”,\ny le respondió el cenzontle:\n“Hoy se casa un cuitlacoche.”",178,2,10,188,"CASAMIENTO DEL CUITLACOCHE",18,10,"oe",-1,0,-1,0,322,322,"Ap. 130","",0,"","","",1,0,0,[],""],["frenk_t4-ap130-02",8,"El tordo toca la flauta,\nel gavilán el clarión;\nel del bajo era el gurrión,\nla tortuga toca el arpa,\nla terrona qué bien canta,\nborracha toda la noche;\ny una calandria en un coche,\nmas como era la madrina,\nle dijo a la golondrina:\n\"Hoy se casa un cuitlacoche.”",178,2,10,188,"CASAMIENTO DEL CUITLACOCHE",18,10,"oe",337,0,-1,0,322,322,"Ap. 130","",0,"","","",1,0,0,[],""],["frenk_t4-ap130-03",8,"Un cuyo andaba bailando\ncon la botija colgada,\nla garza, muy afamada,\nella comenzó el mitote;\nle responde el tecolote:\n“Toque, maestro, cualquier cosa”;\nle dijo la chuparrosa:\n“No de oquis, por mi dinero,\nva a bailar un carpintero\ncon una urraca famosa.",178,2,10,188,"CASAMIENTO DEL CUITLACOCHE",18,10,"oa",63,0,-1,0,322,322,"Ap. 130","",0,"","","",1,0,0,[],""],["frenk_t4-ap130-04",8,"Y, ándele, señora, y ándele,\ny ándele pa los corrales,\nque ahí vienen los toros mochos,\ny atrás vienen los puntales\na comerse los condoches\nque vienen en los costales.”",178,2,10,188,"CASAMIENTO DEL CUITLACOCHE",9,6,"ae",26,0,-1,0,322,322,"Ap. 130","",0,"","","",1,0,0,[],""],["frenk_t4-ap130-05",8,"“Coyotito, ¿de dónde vienes?”\n“Señor, vengo de la mar;\nallí me iban a matar:\nveinte puñaladas traigo\nde la corva al carcañal,\ny así viene mi caballo\ndesde el cincho hasta el pretal.",178,2,10,188,"CASAMIENTO DEL CUITLACOCHE",4,7,"a",1,0,-1,0,322,322,"Ap. 130","",0,"","","",1,0,0,[],""],["frenk_t4-ap131-01",8,"Y un pájaro colorado\nse casó con una urraca;\nbajaron todas las aves\ny de día están saca y saca.",166,2,-1,188,"CORRIDO DEL PÁJARO COLORADO",3,4,"aa",457,0,-1,0,322,322,"Ap. 131","",0,"","","",1,0,0,[],""],["frenk_t4-ap131-02",8,"Bajaron todas las aves,\ny dos verdes guacamayas;\nbajaron todas las aves\na ver la novia peinada.",166,2,-1,188,"CORRIDO DEL PÁJARO COLORADO",0,4,"aa",-1,0,-1,0,322,322,"Ap. 131","",0,"","","",2,0,0,[],""],["frenk_t4-ap131-03",8,"El cura fue un tecolote;\nsacristán: quebrantahueso,\nrespondió el tapacaminos:\n“Haremos la mano en eso.’",166,2,-1,188,"CORRIDO DEL PÁJARO COLORADO",0,4,"eo",48,0,-1,0,322,322,"Ap. 131","",0,"","","",1,0,0,[],""],["frenk_t4-ap131-04",8,"Respondió ya el zopilote:\n“De la carne no hay cuidado,\nme voy para las barrancas,\ny les traeré yo un caballo.”",166,2,-1,188,"CORRIDO DEL PÁJARO COLORADO",0,4,"ao",-1,0,-1,0,322,322,"Ap. 131","",0,"","","",1,0,0,[],""],["frenk_t4-ap131-05",8,"Respondió ya el cacalote:\n“Del máiz no tengan cuidado:\nsi se descuida el milpero,\ntoda la milpa les traigo.”",166,2,-1,188,"CORRIDO DEL PÁJARO COLORADO",0,4,"ao",-1,0,-1,0,322,322,"Ap. 131","",0,"","","",1,0,0,[],""],["frenk_t4-ap131-06",8,"El aura vieja decía:\n“¿En qué, pues, nos acomedimos?,\npues vamos a hacer tortillas\npa que coman los padrinos.”",166,2,-1,188,"CORRIDO DEL PÁJARO COLORADO",0,4,"io",-1,0,-1,0,323,323,"Ap. 131","",0,"","","",1,0,0,[],""],["frenk_t4-ap131-07",8,"El águila, por más beata,\náhi les traiba de presente,\ny áhi les traiba de presente\ny en el pico una culebra.",166,2,-1,188,"CORRIDO DEL PÁJARO COLORADO",3,4,"ea",-1,0,-1,0,323,323,"Ap. 131","",0,"","","",1,0,0,[],""],["frenk_t4-ap131-08",8,"Bajaron todas las aves,\ny entraron, pues, al disimulo;\noí las nuevas músicas\nde mil trescientos zancudos.",166,2,-1,188,"CORRIDO DEL PÁJARO COLORADO",3,4,"uo",-1,0,-1,0,323,323,"Ap. 131","",0,"","","",2,0,0,[],""],["frenk_t4-ap131-10",8,"Respondió el tapacaminos:\n“Eso sí que no lo creo;\nde noche los acompaño,\nporque yo de día no veo.”",166,2,-1,188,"CORRIDO DEL PÁJARO COLORADO",0,4,"eo",66,0,-1,0,323,323,"Ap. 131","",0,"","","",1,0,0,[],""],["frenk_t4-ap131-11",8,"Pues con ésta me despido,\nya me voy pa el otro lado,\nya cantamos el corrido\ndel pájaro colorado.",166,2,-1,188,"CORRIDO DEL PÁJARO COLORADO",1,4,"ao",14,0,-1,0,323,323,"Ap. 131","",0,"","","",2,0,0,[],""],["frenk_t4-ap132-01",8,"Mandó que echaran prisiones,\ny entre dos o tres ratones\nllevan al pobre animal\na punta de arrempujones.",173,2,17,188,"EL LEÓN EN SU TRIBUNAL",0,4,"oe",34,0,-1,0,323,323,"Ap. 132","",0,"","","",1,0,0,[],""],["frenk_t4-ap132-02",8,"No se espanten ni se asombren,\ny en esto diga su nombre;\nvaya pronto a la capilla,\nen esto dijo un ardilla:\n“Yo vide llorar a un hombre.”",173,2,17,188,"EL LEÓN EN SU TRIBUNAL",7,5,"oe",220,0,-1,0,323,323,"Ap. 132","",0,"","","",1,0,0,[],""],["frenk_t4-ap132-03",8,"Había muchos reptiles\npresos y embartolinados;\nhabía sapos engrillados,\ngallinas y guajolotes.",173,2,17,188,"EL LEÓN EN SU TRIBUNAL",5,4,"oe",-1,0,-1,0,323,323,"Ap. 132","",0,"","","",1,0,0,[],""],["frenk_t4-ap132-04",8,"Había liebres y coyotes,\ntigres y zorrillos;\nentre ellos, dos armadillos,\nun galgo y un talcoyote.",173,2,17,188,"EL LEÓN EN SU TRIBUNAL",5,4,"oe",-1,0,-1,0,323,323,"Ap. 132","",0,"","","",1,0,0,[],""],["frenk_t4-ap132-05",8,"Y un miserable ajolote\ncon unos pesados grillos;\nel cuervo era el intendente\ny el alcaide un escorpión;\nel gato de presidente.",173,2,17,188,"EL LEÓN EN SU TRIBUNAL",7,5,"ee",15,0,-1,0,323,323,"Ap. 132","",0,"","","",1,0,0,[],""],["frenk_t4-ap132-06",8,"Que está ahí sin placer,\nviendo a un hombre padecer\nansias, congojas y penas,\ncon unas gruesas cadenas\nque no las podía mover.",173,2,17,188,"EL LEÓN EN SU TRIBUNAL",7,5,"e",20,0,-1,0,323,323,"Ap. 132","",0,"","","",1,0,0,[],""],["frenk_t4-ap133-01",8,"Todititas las personas:\n¿me querrán hacer favor\nde prestarme su atención\npara que escuchen los versos\nde la zorra y el tejón?",166,2,-1,188,"VERSOS DE LA ZORRA Y EL TEJÓN",7,5,"o",31,0,-1,0,323,323,"Ap. 133","",0,"","","",1,0,0,[],""],["frenk_t4-ap134-01",8,"Iba llegando un coyote\na la gran ciudad de León,\ncuando llegó un zopilote\nque andaba de comisión",166,2,-1,188,"CORRIDO VACILADOR",1,4,"o",31,0,-1,0,325,325,"Ap. 134","",0,"","","",2,0,0,[],""],["frenk_t4-ap134-02",8,"Y le dijo en la calzada:\n“Oiga, amigo, ¿a dónde va\ncon esa mujer casada?,\nahora me la pagará.”",166,2,-1,188,"CORRIDO VACILADOR",1,4,"a",9,0,-1,0,325,325,"Ap. 134","",0,"","","",1,0,0,[],""],["frenk_t4-ap134-03",8,"Se lo llevó con el juez\na dar vuelta en una esquina;\nera éste un gato montés\nque estaba en una cocina.\nUna pobre golondrina\nal saber, pues, lo sucedido,\nse fue volando del nido\nderecho para la plaza,\nen busca de una torcaza\nporque no tenía marido.",166,2,-1,188,"CORRIDO VACILADOR",18,10,"io",101,0,-1,0,325,325,"Ap. 134","",0,"","","",1,0,0,[],""],["frenk_t4-ap134-04",8,"De la ciudad del borlote,\nese mismo día, en la tarde,\ntambién llegó un tecolote;\nal descurrir una calle,\nla zorra hizo un ensaye\npara hablar con el coyote;\ncuando a caballo y al trote\nllegó, al momento, un tejón,\ny las hizo mazacote\na las muchachas de León.",166,2,-1,188,"CORRIDO VACILADOR",18,10,"o",31,0,-1,0,325,325,"Ap. 134","",0,"","","",1,0,0,[],""],["frenk_t4-ap134-05",8,"Descalzo y con un huarache,\nllegaron apareaditos\nuna ardilla y un tlacuache;\nllegaron con sus hijitos.\nDe verlos tan peladitos\ntodas las gentes reían,\npues al ver que en ese día\nse fueron para el Parián,\na comerse una sandía;\nel zancudo alacrán",166,2,-1,188,"CORRIDO VACILADOR",18,10,"a",147,0,-1,0,325,325,"Ap. 134","",0,"","","",1,0,0,[],""],["frenk_t4-ap135-01",8,"Ahi anda el pajarerito,\nbuscando por plan y cerros\ncenzontles muy cantadores,\nmulatitos y jilgueros.",166,2,-1,188,"EL PAJARERITO",0,4,"eo",-1,0,-1,0,325,325,"Ap. 135","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap135-02",8,"Los cenzontles, con sus cantos,\nalegran los corazones;\nencerrados en sus jaulas\ncantan sus dulces canciones.",166,2,-1,188,"EL PAJARERITO",0,4,"oe",34,0,-1,0,325,325,"Ap. 135","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap135-03",8,"El mulato, en la barranca,\ncanta con todo esmero;\npero cuando menos piensa\nse lo pesca el pajarero,",166,2,-1,188,"EL PAJARERITO",0,4,"eo",38,0,-1,0,325,325,"Ap. 135","",0,"","","",2,0,0,[],""],["frenk_t4-ap135-04",8,"El jilguero es muy ladino,\nvibra su canto en la sierra;\ncomiendo capulincitos,\ncanta mejor en su tierra,",166,2,-1,188,"EL PAJARERITO",0,4,"ea",80,0,-1,0,325,325,"Ap. 135","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap136-01",8,"Áhi les va la cucaracha\nque acaba, pues, de llegar;\nespántenla con la hilacha,\nno se la dejen pegar.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"a",21,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-02",8,"La cucaracha, la cucaracha,\nse fue al Norte a caminar,\na traer máiz y remolacha\npara su hambre dominar.",166,2,-1,188,"LA CUCARACHA VIAJERA",3,4,"a",21,0,-1,0,326,326,"Ap. 136","",0,"","","",7,0,0,[],""],["frenk_t4-ap136-03",8,"Y solita, en los caminos\nnada encuentra que comer,\ny ni aguardientes ni vinos;\npero ni agua que beber.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"e",20,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-04",8,"En la población de Tula\nla agarraron prisionera,\nporque se robó una muía\nde una compañía minera.",166,2,-1,188,"LA CUCARACHA VIAJERA",0,4,"ea",44,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-05",8,"La cucaracha, la cucaracha\nya no quiere caminar;\ny como si fuera muchacha,\nle dan ganas de orinar.",166,2,-1,188,"LA CUCARACHA VIAJERA",3,4,"a",21,0,-1,0,326,326,"Ap. 136","",0,"","","",7,0,0,[],""],["frenk_t4-ap136-06",8,"Y queriendo y no queriendo\nsale de esa población;\npues al rato va sintiendo\nmorirse de insolación.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"o",31,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-07",8,"Se encuentra con un soldado\nque guarnecen las calzadas,\ny se quedan admirados\nde ver sus patas hinchadas.",166,2,-1,188,"LA CUCARACHA VIAJERA",0,4,"aa",282,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-08",8,"“¿Dónde vas, cucarachita?”\nle preguntan los sargentos;\ny la pobre muchachita\nles sale con muchos cuentos..",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"eo",234,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-09",8,"La cucaracha, manises\nya se encuentra arrepentida;\ntiene hinchadas las narices\ny su boca está partida.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"ia",37,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-10",8,"Llega hasta San Juan del Río\nsin haber comido nada\ny casi muerta de frío,\nsolita y abandonada.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"aa",49,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-11",8,"La cucaracha, muchachos,\nde caminar se ha fastidiado,\nporque sus humildes hilachos\nun arriero le ha incendiado.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"ao",-1,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-12",8,"A Querétaro va entrando,\npero pasar no la dejan;\ntodos se encuentran llorando\nporque del hambre se quejan.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"ea",643,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-13",8,"La cucaracha, viejecitos,\nquiere el Norte conocer;\ny aunque sea con migajitas\nse tiene que mantener.",166,2,-1,188,"LA CUCARACHA VIAJERA",3,4,"e",20,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-14",8,"Con la panza bien vacía\ntoma el camino de Celaya;\ny llegando a Santa Lucía\ncon un amigo se halla.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"aa",249,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-15",8,"Este amigo era panadero\nde apellido Calderón,\nquien aquí fue su aparcero\nporque es reata y muy entrón.",166,2,-1,188,"LA CUCARACHA VIAJERA",3,4,"o",31,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-16",8,"La cucaracha, aparceros,\nle da gusto ver al parcia,\ny le baila “Los lanceros”\ncon mucho salero y gracia.",166,2,-1,188,"LA CUCARACHA VIAJERA",0,4,"aa",-1,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-17",8,"Y su amiguito Manzano\na la cucaracha enamora,\ny al puerto veracruzano\nla lleva como señora.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"oa",107,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-18",8,"Mas la cucaracha insiste\nen llegar hasta Chihuahua;\ny muy temprano se viste,\ndejándolo echando agua.",166,2,-1,188,"LA CUCARACHA VIAJERA",0,4,"aa",-1,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-19",8,"La cucaracha, babosos,\nya se hizo de centavos:\npues les robó los rebozos\na las viejas de los cabos.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"ao",644,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-20",8,"Muy cerca de Zacatecas\nse introdujo en un ranchito,\ndonde engulló carnes secas\ny buena ración de chito.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"io",119,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-21",8,"La cucaracha, viejitas,\nviene colorada y gorda,\npor comer hartas tortillas\nse ha quedado medio sorda.",166,2,-1,188,"LA CUCARACHA VIAJERA",0,4,"oa",645,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-22",8,"Se les hace agua la boca\na los que la ven comiendo;\npero la cucaracha está loca,\nnada más se va sonriendo.",166,2,-1,188,"LA CUCARACHA VIAJERA",3,4,"eo",52,0,-1,0,326,326,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-23",8,"La cucaracha, valecitos,\npuede muy bien caminar;\ncomienza a hacer versitos\npa tener para cenar.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"a",21,0,-1,0,327,327,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-24",8,"A la ciudad zacatecana\nentra la cucaracha hermosa,\nvestida a la mexicana,\ncon su guitarra famosa.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"oa",63,0,-1,0,327,327,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-25",8,"La cucaracha, paisanos,\nnos invita de de veras,\na los buenos mexicanos,\na recorrer esas tierras.",166,2,-1,188,"LA CUCARACHA VIAJERA",0,4,"ea",-1,0,-1,0,327,327,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-26",8,"Con su rebozo de bolita\ny sus botas amarillas;\nse alza también la colita,\nque se ven sus pantorrillas.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"ia",-1,0,-1,0,327,327,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-27",8,"La cucaracha, jamonas,\nde viajar tiene entusiasmo,\ny con muchísimo sarcasmo\nse pega dos buenas monas.",166,2,-1,188,"LA CUCARACHA VIAJERA",11,4,"oa",549,0,-1,0,327,327,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-28",8,"De Torreón el rumbo agarra,\nsiguiendo por Ciudad Juárez,\npara allá, con su guitarra,\nacordarse de sus lares.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"ae",164,0,-1,0,327,327,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-29",8,"Chulear a los militares\ny hacerlos como basura,\ncon sus bonitos cantares\ny su asombrosa hermosura.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"ua",17,0,-1,0,327,327,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap136-30",8,"La cucaracha, su cruz\nse comienza a hacer pesada,\nya se va pa Veracruz;\ncambiaremos de tonada.",166,2,-1,188,"LA CUCARACHA VIAJERA",1,4,"aa",49,0,-1,0,327,327,"Ap. 136","",0,"","","",1,0,0,[],""],["frenk_t4-ap137-02",8,"Al rayar el sol su luz,\nen una fragata hermosa,\nyo vide la Veracruz\nque es tierra muy prodigiosa;\nvide a la Puebla famosa,\ny a México con esmero,\nle di vuelta al mundo entero\ny muchos prodigios vi,\ny cuando salí de aquí\nvide a Lima y Puerto Bello.",171,2,4,188,"VIDE LIMA Y PUERTO BELLO",18,10,"eo",-1,0,-1,0,327,327,"Ap. 137","",0,"","","",1,0,0,[],""],["frenk_t4-ap137-03",8,"Me pasé para otras tierras,\nestuve en Mongolia y China,\ny no he visto tierra fina\ncomo las de Cartagena,\ndonde sin ninguna pena\ncon gusto me divertí,\ny más adelante fui\na donde me vide yo\ny lo que más me gustó:\nPanamá y el Guayaquil.",171,2,4,188,"VIDE LIMA Y PUERTO BELLO",18,10,"i",-1,0,-1,0,327,327,"Ap. 137","",0,"","","",1,0,0,[],""],["frenk_t4-ap137-04",8,"Para Campeche enfilé,\nfui a Mérida una ocasión,\nle di vuelta a Nuevo León\ny a Panzacola llegué.\nA Santo Domingo entré,\ndonde a mi Dios le suplico\nque de glorias me haga rico\ny sustente en su poder,\nporque he venido de ver\nBuenos Aires y Alguarico.",171,2,4,188,"VIDE LIMA Y PUERTO BELLO",18,10,"io",141,0,-1,0,327,327,"Ap. 137","",0,"","","",1,0,0,[],""],["frenk_t4-ap137-05",8,"Para seguir mi campaña\nestuve en Andalucía,\nde ahí me fui para Hungría\ny navegué hasta Bretaña,\ndonde con traza y con maña\nbastante gusto me di\ny más adelante fui:\nDinamarca visité,\ny lo que más disfruté\nfue la Corte de Madrid.",171,2,4,188,"VIDE LIMA Y PUERTO BELLO",18,10,"i",-1,0,-1,0,327,327,"Ap. 137","",0,"","","",1,0,0,[],""],["frenk_t4-ap139-01",8,"En mi caballo melado,\nrucio, retinto, mohíno,\novero, prieto, sabino,\nrosillo, alazán, tostado,\nme ensayé a echar un volteado;\ny es tan ligero este guapo\nque yendo para Apizaco\ndi una vuelta por Escala\ny en medio de Guatemala,\nme puse a adorar a Baco.",166,2,-1,188,"ZAPATEADO DE JUAN PERDIDO",18,10,"ao",423,0,-1,0,328,328,"Ap. 139","",0,"","","",1,0,0,[],""],["frenk_t4-ap139-02",8,"Me salí para Cuitzeo,\nGuadalajara y Jalapa;\nalmorcé en Mostato y Lapa\ny marché para Angangueo;\nde Tula, para un buen pegue,\nllegué a Saltillo rendido,\ny en Tampico entretenido\ncon el naipe y sus amores;\nahí le hice los honores\na Birjain y al rey Cupido.",166,2,-1,188,"ZAPATEADO DE JUAN PERDIDO",18,10,"io",101,0,-1,0,328,328,"Ap. 139","",0,"","","",1,0,0,[],""],["frenk_t4-ap139-03",8,"Salí para Tetepango,\natravesando a Pachuca;\npegué un brinco hasta Ixmiluca\ny pronto estuve en Tenango,\ny no paré hasta Molango,\ndonde llegué cansado;\npara San Luis del..........\ncaminé como deseaba;\nal verme entrar a Orizaba\ndicen que estoy endiosado.",166,2,-1,188,"ZAPATEADO DE JUAN PERDIDO",18,10,"ao",14,0,-1,0,329,329,"Ap. 139","",0,"","","",1,0,0,[],""],["frenk_t4-ap139-04",8,"Tan ligero como un rayo\ntodas esas partes anduve;\nhasta en Veracruz estuve\nmontado en mi buen caballo;\nahora no sé dónde me hallo:\nen la cárcel detenido\nen la................. nací\ndonde me he llegado a ver,\n¡cuándo me verán volver!,\nme llaman Juan Perdido.",166,2,-1,188,"ZAPATEADO DE JUAN PERDIDO",18,10,"io",101,0,-1,0,329,329,"Ap. 139","",0,"","","",1,0,0,[],""],["frenk_t4-ap139-05",8,"Lunes, salí de Chihuahua;\nmartes, llegué a Real de Minas\ny crucé por La Marina;\nmiércoles muy de mañana,\npues de por ver a mi hermana,\npasé por Guadalajara;\nviernes, entré a Tlaxcala;\nsábado, llegué hasta Usingo\ny al otro día, domingo,\noí misa en Guatemala.",166,2,-1,188,"ZAPATEADO DE JUAN PERDIDO",18,10,"aa",330,0,-1,0,329,329,"Ap. 139","",0,"","","",1,0,0,[],""],["frenk_t4-ap139-06",8,"De Mérida, la famosa,\nsalí a las once del día\ny llegué.....................\na las tres, por Villahermosa;\ndel Ave María, graciosa,\nme cambié para Acayucan;\nel alba lo oí en Toluca;\nel sol me salió en San Blas,\ny por no caminar más,\nme desayuné en Pachuca.",166,2,-1,188,"ZAPATEADO DE JUAN PERDIDO",18,10,"ua",607,0,-1,0,329,329,"Ap. 139","",0,"","","",1,0,0,[],""],["frenk_t4-ap139-07",8,"Almorcé en Mostato y Plan,\ny antes de quitar la mesa,\ncomiendo con ligereza,\npasé por Tesichoacán;\nluego llegué a Tehuacán,\ny por vida de mi abuela",166,2,-1,188,"ZAPATEADO DE JUAN PERDIDO",9,6,"ea",-1,0,-1,0,329,329,"Ap. 139","",0,"","","",1,0,0,[],""],["frenk_t4-ap139-08",8,"..................\npasé por Sasichimula;\nprendí la yesca en Aculia,\nel cigarro encendí en Puebla.",166,2,-1,188,"ZAPATEADO DE JUAN PERDIDO",3,4,"ea",-1,0,-1,0,329,329,"Ap. 139","",0,"","","",0,0,0,[],""],["frenk_t4-ap139-09",8,"Salí fumando con aire\npara divertirme un rato,\ny crucé por Guanajuato\nhaciendo el sol su desaire;\nluego llegué a Buenos Aires,\ncrucé por Copacabana;\ncuando llegué a la Lusiana,\niba el cigarro encendido,\npor el humo percibido\nboté la vieja en La Habana.",166,2,-1,188,"ZAPATEADO DE JUAN PERDIDO",18,10,"aa",4,0,-1,0,329,329,"Ap. 139","",0,"","","",1,0,0,[],""],["frenk_t4-ap141-02",8,"Esa Huasteca\nquién sabe lo que tendrá;\nel que una vez la conoce\nregresa y se queda allá.",166,2,-1,188,"LAS TRES HUASTECAS",3,4,"a",9,0,-1,0,330,330,"Ap. 141","",0,"","","",1,0,0,[],""],["frenk_t4-ap141-03",8,"Huasteca linda,\n¿cómo te voy a olvidar?,\nsi nací con tu querencia,\nsi nací con tu cantar.",166,2,-1,188,"LAS TRES HUASTECAS",3,4,"a",21,0,-1,0,330,330,"Ap. 141","",0,"","","",2,0,0,[],""],["frenk_t4-ap141-04",8,"La Huasteca potosina\ntiene flores de a montón;\ntierra llena de neblina\ny laderas de ilusión.",166,2,-1,188,"LAS TRES HUASTECAS",1,4,"o",31,0,-1,0,331,331,"Ap. 141","",0,"","","",2,0,0,[],""],["frenk_t4-ap141-05",8,"En la Huasteca hidalguense\nno se alquila el corazón,\ny aunque diga: usted dispense,\nno amanece en su colchón.",166,2,-1,188,"LAS TRES HUASTECAS",1,4,"o",31,0,-1,0,331,331,"Ap. 141","",0,"","","",2,0,0,[],""],["frenk_t4-ap142-01",8,"El veinte de octubre,\n¡oh!, con chinita de mis amores,\nnos iremos a pasear\na San Juan Teposcolula.",169,2,8,188,"LA FERIA DE TLAXIACO",3,4,"ua",-1,0,-1,0,331,331,"Ap. 142","",0,"","","",1,0,0,[],""],["frenk_t4-ap142-03",8,"Ese pueblo San Martín,\nya verás de sus bajadas\nque tenemos que pasar;\nBoca del Perro, sí, también.",169,2,8,188,"LA FERIA DE TLAXIACO",5,4,"e",-1,0,-1,0,331,331,"Ap. 142","",0,"","","",1,0,0,[],""],["frenk_t4-ap142-04",8,"Madre mía de la Asunción,\nte pedimos por piedad\nnos concedas a llegar\npa poderte visitar.",169,2,8,188,"LA FERIA DE TLAXIACO",0,4,"a",21,0,-1,0,331,331,"Ap. 142","",0,"","","",1,0,0,[],""],["frenk_t4-ap142-05",8,"La hacienda de la Concepción\nSanta Cruz y Tullaltillo, (?)\nChancatango (?) y San Bartolo,\nMadalenos y Comán (?).",169,2,8,188,"LA FERIA DE TLAXIACO",5,4,"a",-1,0,-1,0,331,331,"Ap. 142","",0,"","","",1,0,0,[],""],["frenk_t4-ap142-06",8,"Ese pueblo de Tlaxiaco\nque tenemos que pasar,\na la Virgen de Juquila,\npara poder ya llegar.",169,2,8,188,"LA FERIA DE TLAXIACO",0,4,"a",21,0,-1,0,331,331,"Ap. 142","",0,"","","",1,0,0,[],""],["frenk_t4-ap142-07",8,"Esa carretera que se vido\ny es la Villa de Checahuaxtla;\nnos llegamos al pueblo\ndel Distrito de Putla.",169,2,8,188,"LA FERIA DE TLAXIACO",3,4,"ua",-1,0,-1,0,331,331,"Ap. 142","",0,"","","",1,0,0,[],""],["frenk_t4-ap143-01",8,"Camino de Guanajuato,\nno vale nada la vida,\nla vida no vale nada.\nComienza siempre llorando\ny así llorando se acaba;\npor eso es que en este mundo\nla vida no vale nada.",168,2,11,188,"CAMINO DE GUANAJUATO",4,7,"aa",-1,0,-1,0,331,331,"Ap. 143","",0,"","","",1,0,0,[],""],["frenk_t4-ap143-02",8,"Bonito es León, Guanajuato,\nsus ferias con sus jugadas;\nahí se apuesta la vida\ny se respeta al que gana;\nahí en León, Guanajuato,\nla vida no vale nada.",168,2,11,188,"CAMINO DE GUANAJUATO",9,6,"aa",-1,0,-1,0,331,331,"Ap. 143","",0,"","","",1,0,0,[],""],["frenk_t4-ap143-03",8,"Camino de Santa Rosa\nque pasas por tanto pueblo;\nno pases por Salamanca,\nque ahí me hiere el recuerdo;\nvete rodeando vereda,\nno pases, porque me muero.",168,2,11,188,"CAMINO DE GUANAJUATO",9,6,"eo",-1,0,-1,0,332,332,"Ap. 143","",0,"","","",2,0,0,[],""],["frenk_t4-ap143-04",8,"El Cristo de la Montaña\ndel cerro del Cubilete;\nahí no más tras lomita\nse ve Dolores Hidalgo;\nyo ahí me quedo, paisano:\nahí es mi pueblo adorado.",168,2,11,188,"CAMINO DE GUANAJUATO",9,6,"ao",-1,0,-1,0,332,332,"Ap. 143","",0,"","","",1,0,0,[],""],["frenk_t4-ap144-01",8,"Yo traigo de Guanajuato\nsu gusto y sus tradiciones,\ny busco el amor ingrato\nque rompe mil corazones;\nlo bueno es pasar el rato\nentre tequila y canciones.",166,2,-1,188,"MI GLORIOSO GUANAJUATO",9,6,"oe",34,0,-1,0,332,332,"Ap. 144","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap144-02",8,"Dime ¿por qué es tanto el brete\nsi en mi tierra todo tienes?\nUn Cristo en el Cubilete\ncon un laurel en sus sienes,\ny el glorioso Negrete,\na José Alfredo Jiménez.",166,2,-1,188,"MI GLORIOSO GUANAJUATO",9,6,"ee",-1,0,-1,0,332,332,"Ap. 144","",0,"","","",1,0,0,[],""],["frenk_t4-ap144-03",8,"San Luis tiene su bravura,\nQuerécuaro, hembras bonitas;\nen mi Celaya, dulzura,\ny en Moroleón, sus camitas;\nen Irapuato, hermosura\ny al héroe de Granaditas.",166,2,-1,188,"MI GLORIOSO GUANAJUATO",9,6,"ia",258,0,-1,0,332,332,"Ap. 144","",0,"","","",1,0,0,[],""],["frenk_t4-ap144-04",8,"Petróleo en mi Salamanca,\nguayabas en Salvatierra,\nlas uvas en Tierra Blanca,\nDolores tiene su sierra;\nes de Silao mi potranca\ny es Abasólo mi tierra.",166,2,-1,188,"MI GLORIOSO GUANAJUATO",9,6,"ea",80,0,-1,0,332,332,"Ap. 144","",0,"","","",1,0,0,[],""],["frenk_t4-ap144-05",8,"Yuriria tiene su lago,\nAcámbaro su violencia;\nen Cortázar hay un trago\ny aquí en Santiago, Tendencia; (?)\nen mero Pénjamo, Hidalgo,\npadre de la Independencia.",166,2,-1,188,"MI GLORIOSO GUANAJUATO",9,6,"ea",46,0,-1,0,332,332,"Ap. 144","",0,"","","",1,0,0,[],""],["frenk_t4-ap144-06",8,"Mi despedida es con calma\ny en Romita estoy al rato;\nmi San Miguel me reclama,\nSan Francisco y Uriangato,\ny grito con toda mi alma:\nique viva León, Guanajuatol",166,2,-1,188,"MI GLORIOSO GUANAJUATO",9,6,"o",-1,0,-1,0,332,332,"Ap. 144","",0,"","","",1,0,0,[],""],["frenk_t4-ap145-01",8,"Voy a cantar con empeño\ny lo hago sin condición:\nsoy de esas tierras que sueño\ny que son mi pretensión.",167,2,2,188,"ALMA HIDALGUENSE",1,4,"o",31,0,-1,0,332,332,"Ap. 145","",0,"","","",1,0,0,[],""],["frenk_t4-ap145-02",8,"Donde estrechando la diestra,\nla amistad se da a montón;\nel corazón no se presta,\neso dice la razón.",167,2,2,188,"ALMA HIDALGUENSE",0,4,"o",31,0,-1,0,332,332,"Ap. 145","",0,"","","",1,0,0,[],""],["frenk_t4-ap145-03",8,"Con gusto te canto a ti,\nflorida tierra de Hidalgo,\ntierra donde yo nací\ny en el corazón te traigo,\n¡cómo olvidarme de ti!",167,2,2,188,"ALMA HIDALGUENSE",7,5,"i",23,0,-1,0,332,332,"Ap. 145","",0,"","","",1,0,0,[],""],["frenk_t4-ap145-04",8,"Pachuca, entre sus montañas,\nguarda vario su caudal;\nson portento sus entrañas\npor su rico mineral.",167,2,2,188,"ALMA HIDALGUENSE",1,4,"a",1,0,-1,0,332,332,"Ap. 145","",0,"","","",1,0,0,[],""],["frenk_t4-ap145-05",8,"Tulancingo tiene fama\npor sus mujeres hermosas,\npues del valle es la sultana,\nvergel de fragantes rosas.",167,2,2,188,"ALMA HIDALGUENSE",0,4,"oa",61,0,-1,0,332,332,"Ap. 145","",0,"","","",1,0,0,[],""],["frenk_t4-ap145-07",8,"Zochatipan y Atlapexco,\nHuejutla y Orizatlán,\nla cuna del son huasteco;\nahí se baila “El caimán”.",167,2,2,188,"ALMA HIDALGUENSE",0,4,"a",147,0,-1,0,332,332,"Ap. 145","",0,"","","",1,0,0,[],""],["frenk_t4-ap145-08",8,"Huasteca, siempre risueña\ncantas el son del “Llorar”,\n“La rosa” o “La malagueña”\npa versos improvisar.",167,2,2,188,"ALMA HIDALGUENSE",1,4,"a",21,0,-1,0,333,333,"Ap. 145","",0,"","","",1,0,0,[],""],["frenk_t4-ap146-01",8,"Yo soy del mero Chihuahua,\ndel mineral de Parral;\nescuchen este corrido\nque alegre vengo a cantar.",166,2,-1,188,"EL CORRIDO DE CHIHUAHUA",0,4,"a",-1,0,-1,0,333,333,"Ap. 146","",0,"","","",1,0,0,[],""],["frenk_t4-ap146-03",8,"Eres, mi tierra norteña,\nindia vestida de sol,\nbrava como el león herido,\ndulce como una canción.",166,2,-1,188,"EL CORRIDO DE CHIHUAHUA",0,4,"o",-1,0,-1,0,333,333,"Ap. 146","",0,"","","",1,0,0,[],""],["frenk_t4-ap146-05",8,"Lindas las noches de luna\nalegradas con su luz,\nque por allá por la Junta\nme paseaba con mi amor.",166,2,-1,188,"EL CORRIDO DE CHIHUAHUA",5,4,"o",-1,0,-1,0,333,333,"Ap. 146","",0,"","","",1,0,0,[],""],["frenk_t4-ap146-07",8,"Las fiestas de Santa Rita\ndel noble y viejo Real,\nque tienen sabor añejo\nde alegría tradicional.",166,2,-1,188,"EL CORRIDO DE CHIHUAHUA",0,4,"a",1,0,-1,0,333,333,"Ap. 146","",0,"","","",1,0,0,[],""],["frenk_t4-ap146-09",8,"La cascada Basaseáchic\nes como lluvia de plata,\ndonde me iba por las tardes\na pasearme con mi chata.",166,2,-1,188,"EL CORRIDO DE CHIHUAHUA",0,4,"aa",74,0,-1,0,333,333,"Ap. 146","",0,"","","",1,0,0,[],""],["frenk_t4-ap146-11",8,"Para valientes mi tierra,\npara manzanas El Valle;\nasaderos, Villa Ahumada\ny de la sierra, la carne.",166,2,-1,188,"EL CORRIDO DE CHIHUAHUA",0,4,"ae",-1,0,-1,0,333,333,"Ap. 146","",0,"","","",1,0,0,[],""],["frenk_t4-ap146-13",8,"Esas liebres orejonas\ny los pinos de Majalca,\ny el gran ganado llamado\ncara blanca de Chihuahua.",166,2,-1,188,"EL CORRIDO DE CHIHUAHUA",0,4,"aa",-1,0,-1,0,333,333,"Ap. 146","",0,"","","",1,0,0,[],""],["frenk_t4-ap146-15",8,"Ya me voy, ya me despido,\nno se les vaya a olvidar:\npa gente buena, Chihuahua,\nque es valiente, noble y leal.",166,2,-1,188,"EL CORRIDO DE CHIHUAHUA",3,4,"a",-1,0,-1,0,333,333,"Ap. 146","",0,"","","",9,0,0,[],""],["frenk_t4-ap147-01",8,"Ese lucido Oaxaca de Juárez,\nquién por sus calles alegre paseara,\nentonando por todito el valle,\nsu palacio y cuatro portales.",166,2,-1,188,"CORRIDO DE OAXACA DE JUÁREZ",3,4,"ae",-1,0,-1,0,333,333,"Ap. 147","",0,"","","",1,0,0,[],""],["frenk_t4-ap147-02",8,"Vengan, vengan todos mis amigos;\nbajen, bajen toditas las aves\na entonar este nuevo corrido\nde este lucido Oaxaca de Juárez.",166,2,-1,188,"CORRIDO DE OAXACA DE JUÁREZ",3,4,"ae",-1,0,-1,0,333,333,"Ap. 147","",0,"","","",1,0,0,[],""],["frenk_t4-ap147-03",8,"También tiene sus fuentes de agua\nque causan mucha admiración;\nen la Alameda hay un jardín de flores\ny la estatua del General León.",166,2,-1,188,"CORRIDO DE OAXACA DE JUÁREZ",3,4,"o",31,0,-1,0,333,333,"Ap. 147","",0,"","","",1,0,0,[],""],["frenk_t4-ap147-04",8,"Vengan, vengan toditos a ver\nesos templos lucidos que tiene,\nadornados de oro, es la verdad,\nes el templo de Santo Domingo,\ny también el de la Soledad.",166,2,-1,188,"CORRIDO DE OAXACA DE JUÁREZ",7,5,"a",16,0,-1,0,333,333,"Ap. 147","",0,"","","",1,0,0,[],""],["frenk_t4-ap147-05",8,"Esa plaza de Santa María\nque le nombran el Marquesado,\ndonde corren bonitos tranvías\npara la plaza del mercado.",166,2,-1,188,"CORRIDO DE OAXACA DE JUÁREZ",3,4,"ao",14,0,-1,0,334,334,"Ap. 147","",0,"","","",1,0,0,[],""],["frenk_t4-ap147-06",8,"En esos paseos de Netzahualcóyotl\nhay jaulas de varios animales\ny pescados de varios colores\ny la estatua de Benito Juárez.",166,2,-1,188,"CORRIDO DE OAXACA DE JUÁREZ",3,4,"ae",-1,0,-1,0,334,334,"Ap. 147","",0,"","","",1,0,0,[],""],["frenk_t4-ap147-07",8,"En fin, con ésta yo ya me despido\nde toditas mis amistades;\nya cantamos el nuevo corrido\nde ese lucido Oaxaca de Juárez.",166,2,-1,188,"CORRIDO DE OAXACA DE JUÁREZ",3,4,"ae",-1,0,-1,0,334,334,"Ap. 147","",0,"","","",1,0,0,[],""],["frenk_t4-ap147-08",8,"Vengan, vengan dos mil pajarillos,\nbajen, bajen toditas las aves\na cantar este nuevo corrido\ndel lucido Oaxaca de Juárez.",166,2,-1,188,"CORRIDO DE OAXACA DE JUÁREZ",3,4,"ae",-1,0,-1,0,334,334,"Ap. 147","",0,"","","",1,0,0,[],""],["frenk_t4-ap148-01",8,"Pongan cuidado, buenos amigos,\nlo que les canto y les cantaré:\nvoy a decirles lo que yo siento\npara mi pueblo, Jamiltepec.",169,2,8,188,"CORRIDO DE JAMILTEPEC",3,4,"e",-1,0,-1,0,334,334,"Ap. 148","",0,"","","",1,0,0,[],""],["frenk_t4-ap148-02",8,"Si es que me alejo, buenos amigos,\ntengan presente que si me voy,\nllevo grabada mi tierra linda,\npueblo querido donde nací.",169,2,8,188,"CORRIDO DE JAMILTEPEC",3,4,"i",-1,0,-1,0,334,334,"Ap. 148","",0,"","","",1,0,0,[],""],["frenk_t4-ap148-05",8,"Ahora vamos ya con sus calles,\ny no se enfaden, sigo a cantar;\nvamos al centro y al frente vemos\nese palacio municipal.",169,2,8,188,"CORRIDO DE JAMILTEPEC",3,4,"a",-1,0,-1,0,334,334,"Ap. 148","",0,"","","",1,0,0,[],""],["frenk_t4-ap148-06",8,"Frente al palacio tiene su kiosco\ncon sus banquitos alrededor,\ndonde se pasan noches de luna\na dar vueltas junto a su amor.",169,2,8,188,"CORRIDO DE JAMILTEPEC",3,4,"o",72,0,-1,0,334,334,"Ap. 148","",0,"","","",1,0,0,[],""],["frenk_t4-ap148-07",8,"Su barrio chico y su barrio grande,\nese Noyuco y ese Ñuto,\nquieren saber quién hizo el corrido,\nen el último barrio, allí vivo yo.",169,2,8,188,"CORRIDO DE JAMILTEPEC",3,4,"o",-1,0,-1,0,334,334,"Ap. 148","",0,"","","",1,0,0,[],""],["frenk_t4-ap150-01",8,"Pinotepa Nacional,\neres un lindo vergel;\naquí me enseñé yo a amar\ny aquí nació mi querer.",166,2,-1,188,"CHILENA DE PINOTEPA NACIONAL",3,4,"e",-1,0,-1,0,335,335,"Ap. 150","",0,"","","",2,0,0,[],""],["frenk_t4-ap150-02",8,"Muy bonito panorama\nde mi tierra verá, usted;\nviniendo de Tlacamama,\nsubiendo a Jicaltepec.",166,2,-1,188,"CHILENA DE PINOTEPA NACIONAL",0,4,"e",-1,0,-1,0,335,335,"Ap. 150","",0,"","","",1,0,0,[],""],["frenk_t4-ap150-03",8,"Ay, ay, ay, y vengo yo\na cantar aunque no sepa;\nque siga y que siga el gusto,\ny que viva Pinotepa.",166,2,-1,188,"CHILENA DE PINOTEPA NACIONAL",1,4,"ea",309,0,-1,0,335,335,"Ap. 150","",0,"","","",1,0,0,[],""],["frenk_t4-ap150-04",8,"Sus mujeres son hermosas\ncomo era la Magdalena;\nparece un ramo de rosas,\nde claveles y azucenas.",166,2,-1,188,"CHILENA DE PINOTEPA NACIONAL",0,4,"ea",-1,0,-1,0,335,335,"Ap. 150","",0,"","","",1,0,0,[],""],["frenk_t4-ap150-05",8,"Morenas, pero bonitas,\nlindas sin comparación;\ntambién hay unas güeritas\nque roban el corazón.",166,2,-1,188,"CHILENA DE PINOTEPA NACIONAL",1,4,"o",31,0,-1,0,335,335,"Ap. 150","",0,"","","",1,0,0,[],""],["frenk_t4-ap150-07",8,"Por esta calle derecha,\ncalle real de mis amores,\npor aquí sigue la brecha\nhasta el barrio de las Flores.",166,2,-1,188,"CHILENA DE PINOTEPA NACIONAL",1,4,"oe",5,0,-1,0,335,335,"Ap. 150","",0,"","","",8,0,0,[],""],["frenk_t4-ap150-08",8,"Me gusta mucho esa flor\npa llevármela a mi casa;\npor el arroyo me voy\ny hasta llegar a Ñusaca.",166,2,-1,188,"CHILENA DE PINOTEPA NACIONAL",0,4,"aa",-1,0,-1,0,335,335,"Ap. 150","",0,"","","",1,0,0,[],""],["frenk_t4-ap150-09",8,"Sus muchachos son entrones\npara darse con cualquiera,\nnunca han sido unos dragones,\nson de muy buena madera.",166,2,-1,188,"CHILENA DE PINOTEPA NACIONAL",1,4,"ea",44,0,-1,0,335,335,"Ap. 150","",0,"","","",1,0,0,[],""],["frenk_t4-ap150-10",8,"Tenemos varias mejoras,\nrecuerdo de un presidente:\nnueva escuela hay ahora\ny también sus varias fuentes.",166,2,-1,188,"CHILENA DE PINOTEPA NACIONAL",0,4,"ee",-1,0,-1,0,335,335,"Ap. 150","",0,"","","",1,0,0,[],""],["frenk_t4-ap150-12",8,"Desde mi jardín florido\nme gusta más la violeta;\nde la costa me despido\ny de mi tierra, Pinotepa.",166,2,-1,188,"CHILENA DE PINOTEPA NACIONAL",0,4,"ea",-1,0,-1,0,335,335,"Ap. 150","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-01",8,"Paraíso de Michoacán,\n¿por qué eres tan engreidor?\n¿Será por las guaricitas\nque tienes alrededor?",176,2,3,188,"CORRIDO DE URUAPAN",3,4,"o",72,0,-1,0,336,336,"Ap. 152","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-02",8,"Amigo, vamos a Uruapan\ny verás qué bonito es;\nde la Quinta para abajo\nallí está el mundo al revés.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"e",218,0,-1,0,336,336,"Ap. 152","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-03",8,"Esa entrada de la Quinta,\nel pasar por allí es preciso,\na ir donde nace el agua\nde ese río de Cupatitzio.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"io",-1,0,-1,0,336,336,"Ap. 152","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-04",8,"Ese barrio de Santiago\nse ve bonito en la altura;\nallí todas las muchachas\nson buenas pa la pintura.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"ua",17,0,-1,0,336,336,"Ap. 152","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-05",8,"Ese barrio de San Pedro\nes chiquito y muy bonito;\ndonde siembran la verdura\nmuy buena pa el picadillo.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"io",-1,0,-1,0,336,336,"Ap. 152","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap152-06",8,"Ese barrio de San Juan,\ndonde subsiste el panteón;\nallí hay bóvedas y losas\nque hasta duele el corazón.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"o",31,0,-1,0,336,336,"Ap. 152","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-07",8,"Por esa calle del Ebia,\nyendo pa la Trinidad,\nen ese barrio mentado\nno se encuentra falsedad.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"a",16,0,-1,0,336,336,"Ap. 152","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-08",8,"En el puente Cupatitzio\ntrabajan los arrestados;\nlos fabriqueños a un lado\njugando albures cortados.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"ao",-1,0,-1,0,336,336,"Ap. 152","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-09",8,"Vamos, pues, a dar la vuelta,\nal barrio de la Magdalena;\nvamos con gusto y contento\nque allá vive mi morena.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"ea",59,0,-1,0,336,336,"Ap. 152","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-10",8,"El barrio de San Francisco,\nbarrio de la polvareda;\nen la esquina de Leonardo\nse encuentra la borrachera.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"ea",-1,0,-1,0,336,336,"Ap. 152","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-11",8,"Ese barrio San Miguel,\npasando por la Canoa Alta,\nen ese barrio lucido\nno más dinero nos falta.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"aa",442,0,-1,0,336,336,"Ap. 152","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-12",8,"Barrio de San Juan quemado,\nbarrio de las pulquerías;\ncuando suben los de la hebra\nno les van a pedir frías.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"ia",214,0,-1,0,336,336,"Ap. 152","",0,"","","",1,0,0,[],""],["frenk_t4-ap152-13",8,"Ya con ésta me despido,\nno sé si les gustarán;\naquí se acaban cantando\nlos versos de Michoacán.",176,2,3,188,"CORRIDO DE URUAPAN",0,4,"a",147,0,-1,0,336,336,"Ap. 152","",0,"","","",71,0,0,[],""],["frenk_t4-ap153-01",8,"Pueblo de Santiago del Río,\nnunca te puedo olvidar;\ndonde hay muchachas bonitas\ny limas, pues, sin contar.",169,2,8,188,"SANTIAGO DEL RIO",0,4,"a",21,0,-1,0,336,336,"Ap. 153","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap153-02",8,"Tienes tu calle derecha\ndonde ando todos los días;\ntienes un buen mercadito\nllamado “Porfirio Díaz”.",169,2,8,188,"SANTIAGO DEL RIO",0,4,"ia",476,0,-1,0,336,336,"Ap. 153","",0,"","","",2,0,0,[],""],["frenk_t4-ap153-03",8,"Tienes tu calle derecha,\nrevestida de casarinas,\ndonde canta el ruiseñor\ny trinan las golondrinas.",169,2,8,188,"SANTIAGO DEL RIO",0,4,"ia",243,0,-1,0,337,337,"Ap. 153","",0,"","","",2,0,0,[],""],["frenk_t4-ap153-04",8,"Tienes tu famoso río,\nrevestido de arboleda,\ndonde canta el ruiseñor\ny trinan las primaveras.",169,2,8,188,"SANTIAGO DEL RIO",0,4,"ea",-1,0,-1,0,337,337,"Ap. 153","",0,"","","",1,0,0,[],""],["frenk_t4-ap153-05",8,"Tienes tus grandes reguíos\ny tus grandes cequias de agua;\ntus hombres trabajadores\nque a nadien le piden nada.",169,2,8,188,"SANTIAGO DEL RIO",0,4,"aa",-1,0,-1,0,337,337,"Ap. 153","",0,"","","",1,0,0,[],""],["frenk_t4-ap153-06",8,"Pues con ésta me despido\nde las aguas de las fuentes;\ndonde se matan como hombres\ny adonde nacen valientes.",169,2,8,188,"SANTIAGO DEL RIO",0,4,"ee",252,0,-1,0,337,337,"Ap. 153","",0,"","","",2,0,0,[],""],["frenk_t4-ap153-07",8,"Estos versitos que canto,\nlos digo sin ningún desvío;\ny si quieren conocerme:\nsoy de Santiago del Río.",169,2,8,188,"SANTIAGO DEL RIO",0,4,"io",3,0,-1,0,337,337,"Ap. 153","",0,"","","",1,0,0,[],""],["frenk_t4-ap154-01",8,"Nacido y criado en Canelas,\nduranguense hasta las cachas;\npueblo donde nacen hombres\ny muy bonitas muchachas.",166,2,-1,188,"A CANELAS",0,4,"aa",589,0,-1,0,337,337,"Ap. 154","",0,"","","",1,0,0,[],""],["frenk_t4-ap154-02",8,"Qué bonito es mi Canelas:\nde cerros está rodeado,\ny con jardines de flores\nmi Dios lo tiene sembrado,",166,2,-1,188,"A CANELAS",0,4,"ao",14,0,-1,0,337,337,"Ap. 154","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap154-03",8,"Al Oriente, la ladera,\nal Poniente está el Sillón,\ny en las cumbres de este cerro\nestá la Cruz del Perdón.",166,2,-1,188,"A CANELAS",0,4,"o",31,0,-1,0,337,337,"Ap. 154","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap154-04",8,"Cómo quiero yo a Canelas\ncon toda su ranchería;\nallá se brinda amistad\nsin lucir la valentía.",166,2,-1,188,"A CANELAS",0,4,"ia",0,0,-1,0,337,337,"Ap. 154","",0,"","","",2,0,0,[],""],["frenk_t4-ap154-05",8,"Qué bonitas sus campanas\ncuando se oyen repicar,\nllamando a todos los fieles,\na que vayan a rezar.",166,2,-1,188,"A CANELAS",0,4,"a",21,0,-1,0,337,337,"Ap. 154","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap154-06",8,"Y bajan unas rancheras\nque hasta queman con los ojos,\nluciendo sus lindas trenzas\ny sus chulos labios rojos.",166,2,-1,188,"A CANELAS",0,4,"oo",99,0,-1,0,337,337,"Ap. 154","",0,"","","",1,0,0,[],""],["frenk_t4-ap154-07",8,"Qué bonitas sus mujeres\nde colores naturales;\nbañándose al aire libre\ncon agua de manantiales.",166,2,-1,188,"A CANELAS",0,4,"ae",26,0,-1,0,337,337,"Ap. 154","",0,"","","",1,0,0,[],""],["frenk_t4-ap154-08",8,"¿Cuándo volveré a mi tierra,\na mi Canelas querido?,\nque en un rincón de la sierra\nallá se encuentra escondido.",166,2,-1,188,"A CANELAS",1,4,"io",101,0,-1,0,337,337,"Ap. 154","",0,"","","",1,0,0,[],""],["frenk_t4-ap154-09",8,"Adiós, Canelas, Durango,\nya me despido de ti:\nte juro que no te olvido,\npueblo donde yo nací,",166,2,-1,188,"A CANELAS",0,4,"i",23,0,-1,0,337,337,"Ap. 154","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap154-10",8,"Estos versos los compuse\nen Culiacán, Sinaloa;\nsi en algo puedo servirles:\nyo soy Victorio Gamboa.",166,2,-1,188,"A CANELAS",0,4,"oa",614,0,-1,0,337,337,"Ap. 154","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap155-01",8,"Yo no soy de esta ciudad,\npero vivo agradecido\nporque aquí la autoridad\nnunca me ha desconocido\ny reina la libertad.",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",7,5,"a",16,0,-1,0,337,337,"Ap. 155","",0,"","","",1,0,0,[],""],["frenk_t4-ap155-02",8,"Aquí cualquier hombre vale,\nde toda categoría;\nvale el gringo, vale el chale;\naquí no hay hipocresía.\n¡Qué viva Tamazunchale!",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",7,5,"ae",202,0,-1,0,337,337,"Ap. 155","",0,"","","",2,0,0,[],""],["frenk_t4-ap155-03",8,"Feliz vive el aguador,\nestaquista, carpintero,\nlo mismo que el labrador,\nel albañil, el leñero,\ntodo el que es trabajador.",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",7,5,"o",72,0,-1,0,338,338,"Ap. 155","",0,"","","",1,0,0,[],""],["frenk_t4-ap155-04",8,"Cuando suena la oración,\nfrente al cine, es una gloria:\nel violín y guitarrón\ndan el toque de victoria\nen alegre tendajón.",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",7,5,"o",31,0,-1,0,338,338,"Ap. 155","",0,"","","",1,0,0,[],""],["frenk_t4-ap155-05",8,"En el puesto de Juan Rojas\nreina siempre la alegría,\nallí no existen congojas;\ncon un topo de vainilla\nse escuchan lindas estrofas.",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",7,5,"oa",-1,0,-1,0,338,338,"Ap. 155","",0,"","","",1,0,0,[],""],["frenk_t4-ap155-06",8,"Al compás del guitarrón\nse oyen los sones huastecos;\ntambién se oye la canción\nde Pedro y Goyo, con ecos\nque alegran al corazón.",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",7,5,"o",31,0,-1,0,338,338,"Ap. 155","",0,"","","",1,0,0,[],""],["frenk_t4-ap155-07",8,"También es gran distracción\ncuando se acerca a cantar\nalgún cuate muy cañón;\ntodo es risa y vacilón\nal toque de la oración.",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",7,5,"o",31,0,-1,0,338,338,"Ap. 155","",0,"","","",1,0,0,[],""],["frenk_t4-ap155-08",8,"Adiós, Corral de Barranco,\ncon tus jardines de flores;\nDios sabe quién volverá\na gozar de tus favores.",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",0,4,"oe",5,0,-1,0,338,338,"Ap. 155","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap155-09",8,"Adiós, noble nopalera\ndel cordón del colorín;\nhoy me despido por fin,\npues se llegó mi carrera;\nadiós, pelona ladera\ndonde me recreaba tanto;\nadiós, Sonora, mi encanto,\ncon su mesita graciosa;\nadiós, tierra venturosa,\nadiós, Corral de Barranco.",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",18,10,"ao",-1,0,-1,0,338,338,"Ap. 155","",0,"","","",1,0,0,[],""],["frenk_t4-ap155-10",8,"Cueva del tigre dichosa,\ndonde habitó un ermitaño,\nruega a Dios que al siguiente año\nvuelva a verte tan hermosa;\nmi separación forzosa\nme llena de sinsabores;\nsi el destino y sus rigores\nme impiden volver a verte,\nsiempre te tendré presente\nccn tus jardines de flores.",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",18,10,"oe",5,0,-1,0,338,338,"Ap. 155","",0,"","","",1,0,0,[],""],["frenk_t4-ap155-11",8,"Adiós, charco de agua pura\ndonde tanto me bañé\ny donde alegre pasé\nlargas horas de ventura;\nno desoigas mi amargura\nni el adiós del que se va;\nque a ti no te olvidará\nquien vivió aquí tan contento;\npero dice el pensamiento:\nDios sabe quién volverá.",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",18,10,"a",9,0,-1,0,338,338,"Ap. 155","",0,"","","",1,0,0,[],""],["frenk_t4-ap155-12",8,"Del Arroyo de las Astas\nsuspirando me despido,\nque es tanto lo que he sufrido\nque ya las fuerzas me faltan;\nadiós también la Mesa Alta\ncon sus aves de colores,\nadiós, pájaros cantores,\nadiós, hermoso ciprés,\nruego a Dios vuelva otra vez\na gozar de tus favores.",178,2,10,188,"UN FORASTERO EN TAMAZUNCHALE",18,10,"oe",5,0,-1,0,338,338,"Ap. 155","",0,"","","",1,0,0,[],""],["frenk_t4-ap157-02",8,"Adiós, plaza del mercado\ndonde se ve tanto chito;\nadiós tantísimo indito\nque a tu templo han regresado;\nadiós te digo postrado\na tus plantas eminentes;\nadiós, pues, ya que existentes\nnos tienes en hora ufana,\nmadre mía, Guadalupana,\nadiós, dicen los vivientes.",166,2,-1,188,"AMOROSO DESPEDIMENTO A LA GUADALUPANA",18,10,"ee",252,0,-1,0,338,339,"Ap. 157","",0,"","","",1,0,0,[],""],["frenk_t4-ap157-03",8,"Adiós, fuente principal\ny también los arbolitos,\nlos que están tan regaditos\ncon tus aguas de cristal;\nadiós, adiós, barandal\ndel cementerio que allana\na María Guadalupana;\nadiós, tirando un suspiro,\nadiós, pues ya me retiro\nen esta hora tan cercana.",166,2,-1,188,"AMOROSO DESPEDIMENTO A LA GUADALUPANA",18,10,"aa",4,0,-1,0,339,339,"Ap. 157","",0,"","","",1,0,0,[],""],["frenk_t4-ap157-06",8,"Yo soy de San Luis Potosí,\nes mi barrio San Miguelito,\ndel centro de México soy;\nsoy, por Dios, corazón solito.",166,2,-1,188,"AMOROSO DESPEDIMENTO A LA GUADALUPANA",0,4,"io",119,0,-1,0,339,339,"Ap. 157","",0,"","","",2,0,0,[],""],["frenk_t4-ap157-07",8,"Yo soy de San Luis Potosí;\nel nopal dibujó, enterito,\ndonde el águila paró,\ny su estampa dibujó\nen el lienzo tricolor.",166,2,-1,188,"AMOROSO DESPEDIMENTO A LA GUADALUPANA",7,5,"o",-1,0,-1,0,339,339,"Ap. 157","",0,"","","",2,0,0,[],""],["frenk_t4-ap157-09",8,"En fin, de las torrecitas\nme despido con anhelo;\nadiós digo sin consuelo\na toditas las monjitas;\nadiós a las tortillitas\nque las veo tan eminentes,\nadiós digo a los vivientes;\nadiós, pues, en general:\nadiós, santa Catedral,\nadiós te dicen las gentes.",166,2,-1,188,"AMOROSO DESPEDIMENTO A LA GUADALUPANA",18,10,"ee",252,0,-1,0,339,339,"Ap. 157","",0,"","","",1,0,0,[],""],["frenk_t4-ap157-10",8,"A su feria de San Marcos,\nvoy contento año con año;\nbuen amigo es Guanajuato,\ncolonial y gran soldado.",166,2,-1,188,"AMOROSO DESPEDIMENTO A LA GUADALUPANA",0,4,"ao",-1,0,-1,0,339,339,"Ap. 157","",0,"","","",1,0,0,[],""],["frenk_t4-ap157-11",8,"Vecino de Tamaulipas,\nde Coahuila y Zacatecas;\ncomo Hidalgo y Veracruz,\nSan Luis tiene sus Huastecas.",166,2,-1,188,"AMOROSO DESPEDIMENTO A LA GUADALUPANA",3,4,"ea",647,0,-1,0,339,339,"Ap. 157","",0,"","","",1,0,0,[],""],["frenk_t4-ap159-01",8,"Bonita la capital\ndel estado potosino;\nsi Dios le cedió el destino,\nno puede haber otra igual.",175,2,6,188,"SAN LUIS",11,4,"a",1,0,-1,0,339,339,"Ap. 159","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-01",8,"Imagen santa, morena,\nporque llegué y conocí;\na la hora de mi muerte\nten, Jesús, piedad de mí.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",0,4,"i",23,0,-1,0,340,340,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-02",8,"La una de un pecador\nes llegar en pleno día,\ndarle gracias al Señor\ny estar en su compañía.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",1,4,"ia",0,0,-1,0,340,340,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-03",8,"A las dos, en el Calvario,\npidiéndote protección:\nalza tu bendita mano\ny dame tu bendición.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",0,4,"o",31,0,-1,0,340,340,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-04",8,"A las tres entré a la ermita\ny me postré en oración,\ncon lágrimas en los ojos\nbuscando mi salvación.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",0,4,"o",31,0,-1,0,340,340,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-05",8,"A las cuatro contemplaba\na Jesús oscurecido\nque me ha venido cuidando\nen el mundo tan temido.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",0,4,"io",101,0,-1,0,340,340,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-06",8,"A las cinco me sentía\nmuy contento y muy a gusto,\nporque estaba yo en el templo\nde mi Jesús amoroso.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",5,4,"oo",-1,0,-1,0,340,340,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-07",8,"A las seis pedí perdón\na todita la hermandad\nen aquella Santa Casa,\nsalón de la eternidad.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",0,4,"a",16,0,-1,0,340,340,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-08",8,"A las siete, con dolor,\nme arrimé a un confesionario\na llorar allí mis culpas,\nen aquel bello santuario.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",0,4,"ao",25,0,-1,0,340,340,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-09",8,"A las ocho, con esmero\nme acerqué al confesionario;\nen esa hora me entregaba\na mi Jesús Nazareno.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",5,4,"eo",-1,0,-1,0,340,340,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-10",8,"A las nueve, en gran conflicto,\nde su pasión contemplaba;\ny medité muy contrito\nlo que esta oración guardaba.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",0,4,"aa",28,0,-1,0,340,340,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-11",8,"A las diez fui a comulgar\ncon mucho gusto y contento,\nde ver que había recibido\nel divino Sacramento.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",0,4,"eo",94,0,-1,0,341,341,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-12",8,"A las once me postré\na hacer mi despedimiento\ny vi a mi dulce Jesús\nmuy afable y muy contento.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",0,4,"eo",94,0,-1,0,341,341,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-13",8,"A las doce, con amor\nse humilló mi corazón:\nPadre, Jesús de mi vida,\ndadme vuestra bendición.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",0,4,"o",31,0,-1,0,341,341,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap160-14",8,"Adiós, de Tila el Santuario,\nadiós, la imagen hermosa;\nadiós, santo campanario,\nte digo adiós yo y mi esposa.",183,2,19,188,"ALABANZA AL SEÑOR DE TILA",1,4,"oa",63,0,-1,0,341,341,"Ap. 160","",0,"","","",1,0,0,[],""],["frenk_t4-ap162-01",8,"Pequé, mi Jesús, pequé;\nyo a mi vicio doy de baja,\npensando así en la baraja\ntu pasión contemplaré.",166,2,-1,188,"NUEVA RELACIÓN RELATIVA A LAS CUARENTA CARTAS DE LA BARAJA",11,4,"e",77,0,-1,0,342,342,"Ap. 162","",0,"","","",1,0,0,[],""],["frenk_t4-ap162-02",8,"Yo por ellas considero\nun solo Dios en lo criado;\nbuen Jesús, mi padre amado,\ndulce bien por quien yo muero;\nde todos eres el primero,\nsupuesto que sois increado;\naunque esta carta he jugado,\nhe apostado sin refleja;\n¡oh, Dios!, es justa tu queja\nporque en el naipe he pecado.",166,2,-1,188,"NUEVA RELACIÓN RELATIVA A LAS CUARENTA CARTAS DE LA BARAJA",18,10,"ao",14,0,-1,0,342,342,"Ap. 162","",0,"","","",1,0,0,[],""],["frenk_t4-ap162-03",8,"Dos varones te bajaron\nde la cruz, mi amado Dios;\ny a mí, por jugar al dos,\ncuanto tuve me ganaron;\ntu cuerpo lo sepultaron\ncon reverencja y afán,\nde luto María y San Juan,\ncon amargos sufrimientos\ncausaron tristes lamentos,\npor lo que en el tres verán.",166,2,-1,188,"NUEVA RELACIÓN RELATIVA A LAS CUARENTA CARTAS DE LA BARAJA",18,10,"a",147,0,-1,0,342,342,"Ap. 162","",0,"","","",1,0,0,[],""],["frenk_t4-ap162-04",8,"Dos clavos te traspasaron\nesas sacrosantas manos,\nal rigor de los tiranos\ncuando te sacrificaron;\ncon otro clavo clavaron\ntus sacratísimos pies;\nsalvamos fue tu interés,\nun texto lo ha referido,\ny aquí queda discutido\nlo que significa el tres.",166,2,-1,188,"NUEVA RELACIÓN RELATIVA A LAS CUARENTA CARTAS DE LA BARAJA",18,10,"e",218,0,-1,0,342,342,"Ap. 162","",0,"","","",1,0,0,[],""],["frenk_t4-ap162-05",8,"Cuatro Evangelios, mi Dios;\nel cuatro aquí significa,\nsegún San Juan testifica\ncuando de ti oyó la voz;\ntomó la pluma veloz\npara escribir los tratados,\n¡qué argumentos tan sagrados!,\naquí nos dan a entender\nla hermosura y el poder\ndel mismo Dios humanado.",166,2,-1,188,"NUEVA RELACIÓN RELATIVA A LAS CUARENTA CARTAS DE LA BARAJA",18,10,"ao",-1,0,-1,0,342,342,"Ap. 162","",0,"","","",1,0,0,[],""],["frenk_t4-ap162-06",8,"La cruel mujer es la sota,\nsegún la escritura explica;\na todo hombre perjudica\ny aun en el naipe lo azota;\nEva tomó su derrota\ncon un engañoso afán,\ny en todo imitó a Birján\nen lo cruel y en lo profana,\npues dio a comer la manzana\nal inocente de Adán.",166,2,-1,188,"NUEVA RELACIÓN RELATIVA A LAS CUARENTA CARTAS DE LA BARAJA",18,10,"a",147,0,-1,0,342,342,"Ap. 162","",0,"","","",1,0,0,[],""],["frenk_t4-ap162-07",8,"Un bruto, a San Juan de Dios,\nuna coz le dio atrevido,\ny yo a Dios tengo ofendido\ncon delito tan atroz;\npequé, Señor, contra vos,\nperdón pido al confesar\ny pretendo declarar\nechándome solo el fallo;\nporque apostando al caballo\ntodo se me fue en pensar.",166,2,-1,188,"NUEVA RELACIÓN RELATIVA A LAS CUARENTA CARTAS DE LA BARAJA",18,10,"a",21,0,-1,0,342,342,"Ap. 162","",0,"","","",1,0,0,[],""],["frenk_t4-ap163-02",8,"Cecilita, Cecilita,\npasó una garza morena;\ndebajo de tu rebozo\nme pasé la Nochebuena.",187,2,12,188,"CECILIA",0,4,"ea",59,0,-1,0,342,342,"Ap. 163","",0,"","","",1,0,0,[],""],["frenk_t4-ap164-01",8,"Alabárnoste, ¡oh sagrada\nsangre de mi redentor!,\npues por ella quedó libre\nde culpas el pecador.",167,2,2,188,"ALABADO DE LA PRECIOSA SANGRE",0,4,"o",72,0,-1,0,343,343,"Ap. 164","",0,"","","",1,0,0,[],""],["frenk_t4-ap164-05",8,"¡Oh, remedio universali\n¡Oh, sangre de mi Jesús!,\nlíbranos de todo mal,\npues te vertiste en la cruz.",167,2,2,188,"ALABADO DE LA PRECIOSA SANGRE",0,4,"u",109,0,-1,0,343,343,"Ap. 164","",0,"","","",1,0,0,[],""],["frenk_t4-ap165-02",8,"Es del Padre Eterno pira,\nes de su trono columna,\nes inmaculada y pura,\ny es espejo en quien se mira;\nes manantial que respira\nsu santidad: ¡qué alegríal;\nes el sol y es luz del día,\nes la torre de David\npues dijo el Señor así:\nésta que ves es María.",166,2,-1,188,"LOA DE LA PURÍSIMA",18,10,"ia",0,0,-1,0,344,344,"Ap. 165","",0,"","","",1,0,0,[],""],["frenk_t4-ap165-03",8,"Es de la gracia el maná,\nes fijo reclinatorio,\nes divino consistorio\nde la augusta Trinidad;\nes madre de la verdad,\nes en todo Virgen bella;\nfue a gusto del Padre, en ella\nque el Verbo había de encamar,\ny así llegó a formar:\nclara luz, divina estrella.",166,2,-1,188,"LOA DE LA PURÍSIMA",18,10,"ea",6,0,-1,0,344,344,"Ap. 165","",0,"","","",1,0,0,[],""],["frenk_t4-ap165-04",8,"Es Madre, es Hija, es Esposa,\nde tres personas iguales,\nen divinidad cabales,\ny en trina ciencia una sola.\nDel Padre Hija poderosa,\nes de Hijo Madre bella,\nes Esposa y es doncella\ndel Espíritu, es verdad\ny, aseguro, realidad:\nSi el que la hizo nació de ella.",166,2,-1,188,"LOA DE LA PURÍSIMA",18,10,"ea",6,0,-1,0,344,344,"Ap. 165","",0,"","","",1,0,0,[],""],["frenk_t4-ap165-05",8,"De la más realizada ciencia\nla hizo Dios tan poderosa,\ncándida azucena hermosa\nde la más alta eminencia;\nes de tan sacra excelencia,\nde toda la jerarquía,\nla escogió con alegría\nhaciéndola sin igual,\nsabia y maestra general:\ncontempla qué tal la haría.",166,2,-1,188,"LOA DE LA PURÍSIMA",18,10,"ia",0,0,-1,0,344,344,"Ap. 165","",0,"","","",1,0,0,[],""],["frenk_t4-ap165-07",8,"Ya te lo dijo el glosista,\nSacra divina Señora;\nmi frotita se ha quedado\ny voy a venderla agora...",166,2,-1,188,"LOA DE LA PURÍSIMA",0,4,"oa",107,0,-1,0,344,344,"Ap. 165","",0,"","","",1,0,0,[],""],["frenk_t4-ap166-02",8,"Estando necesitado,\nSoledad, Virgen bendita,\nme diste una canastita\nde aquel pan sacramentado;\nmil gracias he tributado\na su reliquia sin par,\nrecordando que en el mar\nandas por la embarcación;\nes preciso publicar\ntu milagro en la ocasión.",166,2,-1,188,"MILAGRO QUE HIZO LA SANTÍSIMA VIRGEN DE LA SOLEDAD",18,10,"o",31,0,-1,0,344,344,"Ap. 166","",0,"","","",1,0,0,[],""],["frenk_t4-ap166-03",8,"Con razón el preso clama\na ti, divina Señora,\ny el enfermo siempre implora\ny a cada instante te llama.\nEl pajarito en la rama\ncanta alegre en su retiro,\nserá por ti, según miro,\npuesto llenas de piedad;\nyo también per ti suspiro,\nVirgen de la Soledad.",166,2,-1,188,"MILAGRO QUE HIZO LA SANTÍSIMA VIRGEN DE LA SOLEDAD",18,10,"a",16,0,-1,0,344,344,"Ap. 166","",0,"","","",1,0,0,[],""],["frenk_t4-ap166-04",8,"De aquel preso emparedado\nque la justicia olvidó,\ntu majestad lo sacó\nestando en vida enterrado.\nEra en todo consolado\na cada instante y momento;\nno le faltó su alimento:\ndía con día se lo llevabas;\nen aquel triste aposento\nmil maravillas obrabas.",166,2,-1,188,"MILAGRO QUE HIZO LA SANTÍSIMA VIRGEN DE LA SOLEDAD",18,10,"aa",204,0,-1,0,345,345,"Ap. 166","",0,"","","",1,0,0,[],""],["frenk_t4-ap166-05",8,"Si era de día dabas luz;\nde noche, hermosa candela.\nSoledad de Santa Cruz,\ncuidadosa centinela;\ntodo pobre se consuela\nentrando a tu templo hermoso;\nel enfermo, aunque quejoso,\nllega y sana de su mal.\nEres remedio amoroso\nde toda la capital.",166,2,-1,188,"MILAGRO QUE HIZO LA SANTÍSIMA VIRGEN DE LA SOLEDAD",18,10,"a",1,0,-1,0,345,345,"Ap. 166","",0,"","","",1,0,0,[],""],["frenk_t4-ap166-06",8,"En la Sierra, pereciendo,\nmi familia se afligía;\npero en ese mismo día\ntres tortas fui recibiendo;\nte fuiste tú apareciendo\nenlutada y muy paciente,\nresplandeciendo tu frente;\nfue cosa de admiración;\npues el milagro patente\nlo tengo en el corazón.",166,2,-1,188,"MILAGRO QUE HIZO LA SANTÍSIMA VIRGEN DE LA SOLEDAD",18,10,"o",31,0,-1,0,345,345,"Ap. 166","",0,"","","",1,0,0,[],""],["frenk_t4-ap166-07",8,"Mas que el reo sea tan causante\ny lo lleven al suplicio,\nlo indulta tu beneficio\ny en todo andas vigilante.\nQuién como tú ¡Madre amante!,\nque hablas al defensor,\na todos haces favor\ny les das la libertad;\neres Madre del Creador\npues tenéis de mí piedad.",166,2,-1,188,"MILAGRO QUE HIZO LA SANTÍSIMA VIRGEN DE LA SOLEDAD",18,10,"a",16,0,-1,0,345,345,"Ap. 166","",0,"","","",1,0,0,[],""],["frenk_t4-ap166-08",8,"A la viuda o la casada\npor tu mano la libertas;\ntus maravillas son ciertas\ny en todo eres abogada;\npues estando encapillada\ndoña María Salomé,\ncon grande misterio y fe\na tu majestad clamó;\ndel suplicio se salvó,\nesto patente se ve.",166,2,-1,188,"MILAGRO QUE HIZO LA SANTÍSIMA VIRGEN DE LA SOLEDAD",18,10,"e",77,0,-1,0,345,345,"Ap. 166","",0,"","","",1,0,0,[],""],["frenk_t4-ap166-09",8,"En fin, Madre poderosa,\nMadre Virgen sin igual,\ndanos un buen temporal,\nazucena misteriosa;\ndel paraíso eres rosa\ny del campo bendición,\nquítanos esta aflición,\nno te olvides, Madre mía;\nhaz que llueva en este día\npor toda nuestra nación.",166,2,-1,188,"MILAGRO QUE HIZO LA SANTÍSIMA VIRGEN DE LA SOLEDAD",18,10,"o",31,0,-1,0,345,345,"Ap. 166","",0,"","","",1,0,0,[],""],["frenk_t4-ap167-01",8,"Con gran consuelo en el alma\nvenimos hoy a tu templo,\ndando con esto un ejemplo\nde la fe que no se acaba;\npues todo el mundo te alaba\ncomo digna Soberana,\ncantando con voz ufana:\n“¡Viva la Reina del Cielo,\nque es todo nuestro consuelo,\nla Virgen Guadalupana!”",166,2,-1,188,"SALUTACIÓN A MARÍA SANTÍSIMA DE GUADALUPE",18,10,"aa",4,0,-1,0,345,345,"Ap. 167","",0,"","","",1,0,0,[],""],["frenk_t4-ap167-02",8,"Al emprender nuestro viaje\nlo hicimos con devoción,\ntrayendo en el corazón\nesa tu sagrada imagen;\ncon un sublime lenguaje\nentramos a saludarte,\ny gozosos a adorarte\nllegamos los peregrinos,\na ver tus ojos divinos\npara más y más amarte.",166,2,-1,188,"SALUTACIÓN A MARÍA SANTÍSIMA DE GUADALUPE",18,10,"ae",8,0,-1,0,345,345,"Ap. 167","",0,"","","",1,0,0,[],""],["frenk_t4-ap167-03",8,"Llegamos a la Estación\nsin novedad, sin cuidado;\nvamos al templo sagrado\ncon gran fe y veneración;\nsumisos, con devoción,\nlleguémonos a la Villa\na adorar la maravilla\nque linda se apareció,\ny que todo el mundo vio\nentre rosas de Castilla.",166,2,-1,188,"SALUTACIÓN A MARÍA SANTÍSIMA DE GUADALUPE",18,10,"ia",162,0,-1,0,346,346,"Ap. 167","",0,"","","",2,0,0,[],""],["frenk_t4-ap167-04",8,"Ya llegamos al Santuario,\nde gozo el alma se tupe,\n¡Oh, Virgen de Guadalupe,\nel gozo es extraordinario!\nTu sagrado escapulario\nllevaremos en el pecho\ncomo insignia de derecho\nque tú nos has concedido,\npor eso, ¡Oh, Madre!, te pido\nque nos sirva de provecho.",166,2,-1,188,"SALUTACIÓN A MARÍA SANTÍSIMA DE GUADALUPE",18,10,"eo",60,0,-1,0,346,346,"Ap. 167","",0,"","","",1,0,0,[],""],["frenk_t4-ap167-05",8,"Los peregrinos siguientes\nte hacen gran salutación\ncon santa fe y devoción\ny con hechos muy patentes;\nque tú los tengas presentes\nte ruegan los de Celaya,\ntambién los de Calimaya,\nlos de Coahuila y Sonora\nte rogamos, Gran Señora,\nnos auxilies en la Raya.",166,2,-1,188,"SALUTACIÓN A MARÍA SANTÍSIMA DE GUADALUPE",18,10,"aa",404,0,-1,0,346,346,"Ap. 167","",0,"","","",1,0,0,[],""],["frenk_t4-ap167-06",8,"Todo San Luis Potosí,\nHuetamo y Maravatío,\nSanta Fe, San Juan del Río,\ntodos adoran en ti;\npor eso con frenesí\ny con ánimos fervientes\nvienen los de Aguascalientes,\nTemazcalcingo y Otumba;\nlos de Ameca y los de Ozumba\na postrarse reverentes.",166,2,-1,188,"SALUTACIÓN A MARÍA SANTÍSIMA DE GUADALUPE",18,10,"ee",252,0,-1,0,346,346,"Ap. 167","",0,"","","",1,0,0,[],""],["frenk_t4-ap167-07",8,"De mil pueblos y montañas,\nde islas, peñascos y ríos,\ny de los mares bravios,\ny de las pobres cabañas,\ny de otras partes extrañas\nvenimos con precisión\nen gran peregrinación\na solemnizar, María,\nen tan memorable día\ntu hermosa coronación.",166,2,-1,188,"SALUTACIÓN A MARÍA SANTÍSIMA DE GUADALUPE",18,10,"o",31,0,-1,0,346,346,"Ap. 167","",0,"","","",1,0,0,[],""],["frenk_t4-ap167-08",8,"No hay una parte del mundo\nque no venga a contemplar\nprodigio tan singular\ny de saber tan profundo;\nes la fe del moribundo,\nla fe de todo viviente,\nla luz de todo creyente,\nel faro del caminante\ny el amparo del amante\nque nos dio el Omnipotente.",166,2,-1,188,"SALUTACIÓN A MARÍA SANTÍSIMA DE GUADALUPE",18,10,"ee",15,0,-1,0,346,346,"Ap. 167","",0,"","","",1,0,0,[],""],["frenk_t4-ap168-01",8,"El pueblo de Nochistlán\ny toda jurisdicción,\npostrándose de rodillas\nte pide tu bendición.",178,2,10,188,"DESPEDIDAS A LA VIRGEN",0,4,"o",31,0,-1,0,346,346,"Ap. 168","",0,"","","",1,0,0,[],""],["frenk_t4-ap168-02",8,"Adiós, adiós, Madre nuestra,\nMadre sin comparación;\nnos vamos de tu presencia,\néchanos tu bendición.",178,2,10,188,"DESPEDIDAS A LA VIRGEN",0,4,"o",31,0,-1,0,346,346,"Ap. 168","",0,"","","",1,0,0,[],""],["frenk_t4-ap168-03",8,"De San Luis y Zacatecas,\nde Teocaltiche y Villita,\nnos vamos de tu santuario;\nadiós, blanca palomita.",178,2,10,188,"DESPEDIDAS A LA VIRGEN",3,4,"ia",50,0,-1,0,346,346,"Ap. 168","",0,"","","",1,0,0,[],""],["frenk_t4-ap168-04",8,"Adiós, bello relicario,\nMadre del Verbo divino;\ntu santo nombre nos sea\nla defensa del camino.",178,2,10,188,"DESPEDIDAS A LA VIRGEN",0,4,"io",199,0,-1,0,346,346,"Ap. 168","",0,"","","",1,0,0,[],""],["frenk_t4-ap168-05",8,"De Apozol y Juchipila\ny toda su cercanía,\nte piden tu bendición;\nadiós, adiós, Madre mía.",178,2,10,188,"DESPEDIDAS A LA VIRGEN",0,4,"ia",0,0,-1,0,346,346,"Ap. 168","",0,"","","",1,0,0,[],""],["frenk_t4-ap168-06",8,"También de Mezticacán,\nAcacico y Yahualica;\néchales tu bendición\ncon tu sagrada manita.",178,2,10,188,"DESPEDIDAS A LA VIRGEN",0,4,"ia",-1,0,-1,0,346,346,"Ap. 168","",0,"","","",1,0,0,[],""],["frenk_t4-ap168-07",8,"De Apulco y Chimaliquín,\nde Tapias y de Oxtotán,\nviendo en ti sus beneficios\nlas gracias, Madre, te dan.",178,2,10,188,"DESPEDIDAS A LA VIRGEN",3,4,"a",147,0,-1,0,347,347,"Ap. 168","",0,"","","",1,0,0,[],""],["frenk_t4-ap168-08",8,"También de Huejotitlán\ny todos los de Acatita,\nte dicen “adiós, adiós,\nadiós, blanca palomita”.",178,2,10,188,"DESPEDIDAS A LA VIRGEN",0,4,"ia",50,0,-1,0,347,347,"Ap. 168","",0,"","","",1,0,0,[],""],["frenk_t4-ap169-01",8,"Vengamos, almas contritas,\ncon amor y gozo pleno,\na cantarle mañanitas\na Jesús el Nazareno.",183,2,19,188,"ORACIÓN AL SEÑOR DE ACAPETAHUA",1,4,"eo",76,0,-1,0,347,347,"Ap. 169","",0,"","","",1,0,0,[],""],["frenk_t4-ap169-02",8,"Por sus hermosos cabellos,\nsus ojitos claros de agua,\ntraemos marimba y versos\nal Señor de Acapetahua.",183,2,19,188,"ORACIÓN AL SEÑOR DE ACAPETAHUA",0,4,"aa",-1,0,-1,0,347,347,"Ap. 169","",0,"","","",1,0,0,[],""],["frenk_t4-ap169-03",8,"Presidentes y jerarcas\nson insectos a tu lado;\nlos luceros son su trono\ny luz del cielo estrellado.",183,2,19,188,"ORACIÓN AL SEÑOR DE ACAPETAHUA",0,4,"ao",14,0,-1,0,347,347,"Ap. 169","",0,"","","",1,0,0,[],""],["frenk_t4-ap169-04",8,"A la casa de oración\ntodos vamos a llegar,\ncon grande veneración\nnos hincamos a rezar.",183,2,19,188,"ORACIÓN AL SEÑOR DE ACAPETAHUA",1,4,"a",21,0,-1,0,347,347,"Ap. 169","",0,"","","",1,0,0,[],""],["frenk_t4-ap169-05",8,"Toda la costa venera\na este Señor milagroso;\nChiapas se te rinde entera\npor tu poder tan famoso.",183,2,19,188,"ORACIÓN AL SEÑOR DE ACAPETAHUA",1,4,"oo",160,0,-1,0,347,347,"Ap. 169","",0,"","","",1,0,0,[],""],["frenk_t4-ap169-06",8,"Para que con regocijo\nen la celestial mansión\nte encuentres eternamente,\nte entonamos la canción.",183,2,19,188,"ORACIÓN AL SEÑOR DE ACAPETAHUA",0,4,"o",31,0,-1,0,347,347,"Ap. 169","",0,"","","",1,0,0,[],""],["frenk_t4-ap169-07",8,"Adiós, Señor, dulce encanto,\nde todo pueblo adorado,\nde San Cristóbal al Salto,\nde Bochil a Maldonado.",183,2,19,188,"ORACIÓN AL SEÑOR DE ACAPETAHUA",0,4,"ao",-1,0,-1,0,347,347,"Ap. 169","",0,"","","",1,0,0,[],""],["frenk_t4-ap169-08",8,"De Chiapa hasta Soyaló,\ndesde Ayutla a Tecpatán,\nvienen los de Bachajón\ny después de Comitán.",183,2,19,188,"ORACIÓN AL SEÑOR DE ACAPETAHUA",0,4,"a",147,0,-1,0,347,347,"Ap. 169","",0,"","","",1,0,0,[],""],["frenk_t4-ap169-09",8,"De Larrainzar y Chamula,\nde Tila y Chicomuselo,\nya vengan a pie o en muía,\na todos les das consuelo.",183,2,19,188,"ORACIÓN AL SEÑOR DE ACAPETAHUA",0,4,"eo",10,0,-1,0,347,347,"Ap. 169","",0,"","","",1,0,0,[],""],["frenk_t4-ap169-10",8,"Ya todito amaneció,\ncantaron las avecitas;\nadiós, Cristo sacrosanto,\nte trajimos mañanitas.",183,2,19,188,"ORACIÓN AL SEÑOR DE ACAPETAHUA",0,4,"ia",258,0,-1,0,347,347,"Ap. 169","",0,"","","",1,0,0,[],""],["frenk_t4-ap170-01",8,"Los de la Hacienda de Treinta\nde Ixcapixtla, llorando\npor ti se van suspirando,\npues ya el indito se ausenta;\nde Buenavista y su Venta\nse despiden en reunión.\nAdiós, hasta otra ocasión,\nya se van los de Zumpango;\néchanos la bendición,\nMadre mía de Tlaltenango.",166,2,-1,188,"DESPEDIMENTO A MARÍA SANTÍSIMA DE TLALTENANGO",18,10,"ao",596,0,-1,0,347,347,"Ap. 170","",0,"","","",1,0,0,[],""],["frenk_t4-ap170-02",8,"Adiós, dalia matizada,\nya se van los de Morelos,\nde Guanacato ya vemos\nse retiran, Madre amada;\nya te quedas colocada,\ngüerita del alma mía;\nadiós, clara luz del día,\nse van los de Huauchinango;\nrecibe el último adiós,\nMadre mía de Tlaltenango.",166,2,-1,188,"DESPEDIMENTO A MARÍA SANTÍSIMA DE TLALTENANGO",18,10,"ao",596,0,-1,0,347,347,"Ap. 170","",0,"","","",1,0,0,[],""],["frenk_t4-ap170-04",8,"En fin, adiós, Madrecita,\ntus hijos los mexicanos,\nel adiós todos te damos\ncomo linda azucenita;\nadiós, bella amapolita\ndel paraíso celestial;\nadiós, vuestro trono real\nde la Virgen Soberana,\nlíbranos de todo mal;\nadiós, rosita temprana.",166,2,-1,188,"DESPEDIMENTO A MARÍA SANTÍSIMA DE TLALTENANGO",18,10,"aa",4,0,-1,0,348,348,"Ap. 170","",0,"","","",1,0,0,[],""],["frenk_t4-ap171-01",8,"Ya te lo vas, Madre mía,\nya te lo vas, mi consuelo;\nadiós, sagrada María,\nnos veremos en el cielo.",178,2,10,188,"DESPEDIDA A LA VIRGEN",1,4,"eo",10,0,-1,0,348,348,"Ap. 171","",0,"","","",2,0,0,[],""],["frenk_t4-ap171-02",8,"Señora mía del Rosario,\ntú eres nostra protectora;\na tus pies tienes postrada\na nostra alma pecadora.",178,2,10,188,"DESPEDIDA A LA VIRGEN",0,4,"oa",107,0,-1,0,348,348,"Ap. 171","",0,"","","",1,0,0,[],""],["frenk_t4-ap171-03",8,"Te lo vas de Nochistlán\ndesparramándonos flores;\nel corazón nos alumbra\ncon rayos y resplandores.",178,2,10,188,"DESPEDIDA A LA VIRGEN",0,4,"oe",5,0,-1,0,348,348,"Ap. 171","",0,"","","",1,0,0,[],""],["frenk_t4-ap171-04",8,"Te lo vas a tu santuario,\ncon humildad, Virgen Santa;\npostrados nos dispidimos,\neres arca de la 'lianza.",178,2,10,188,"DESPEDIDA A LA VIRGEN",0,4,"aa",-1,0,-1,0,348,348,"Ap. 171","",0,"","","",1,0,0,[],""],["frenk_t4-ap171-05",8,"Todas las aves del viento\nvengan a hacer compañía,\nya se va nostro consuelo\nque nos ampara y nos guía.",178,2,10,188,"DESPEDIDA A LA VIRGEN",3,4,"ia",0,0,-1,0,348,348,"Ap. 171","",0,"","","",1,0,0,[],""],["frenk_t4-ap171-06",8,"¡Ay!, vámonos dispidiendo\nde nostra gran protectora;\nsabe Dios si la miraremos\na nostra Reina y Señora.",178,2,10,188,"DESPEDIDA A LA VIRGEN",0,4,"oa",107,0,-1,0,348,348,"Ap. 171","",0,"","","",1,0,0,[],""],["frenk_t4-ap171-07",8,"Adiós, campanitas tristes,\nya se va nostro consuelo;\nya se va la Virgen Santa,\nya se va nostro remedio.",178,2,10,188,"DESPEDIDA A LA VIRGEN",0,4,"eo",-1,0,-1,0,348,348,"Ap. 171","",0,"","","",1,0,0,[],""],["frenk_t4-ap171-08",8,"Adiós, arca de David,\nestrella de la mañana,\ncon tus manitas sagradas\nrecibe tú nostras almas.",178,2,10,188,"DESPEDIDA A LA VIRGEN",0,4,"aa",-1,0,-1,0,348,348,"Ap. 171","",0,"","","",1,0,0,[],""],["frenk_t4-ap171-09",8,"Adiós, adiós, Madre mía,\nhoy te pidimos perdón;\ntú nos has di acompañar\nen cualquier tribulación.",178,2,10,188,"DESPEDIDA A LA VIRGEN",0,4,"o",31,0,-1,0,348,348,"Ap. 171","",0,"","","",2,0,0,[],""],["frenk_t4-ap171-10",8,"Ya te lo vas, Madre mía,\nte lo vas de Nochistlán;\nal primer rancho que llegas\nes el de Don Juan Durán.",178,2,10,188,"DESPEDIDA A LA VIRGEN",0,4,"a",147,0,-1,0,348,348,"Ap. 171","",0,"","","",2,0,0,[],""],["frenk_t4-ap172-01",8,"Adiós, te dice a porfía,\nPadre de consolación;\nse llegó ya el triste día\nde ser mi separación.",166,2,-1,188,"DESPEDIMENTO AL SEÑOR DEL HOSPITAL DE LA VILLA DE SALAMANCA",1,4,"o",31,0,-1,0,348,348,"Ap. 172","",0,"","","",1,0,0,[],""],["frenk_t4-ap172-02",8,"Adiós, Señor sin igual,\nte dicen los mexicanos,\ntambién los zacatee anos,\nde San Luis y del Parral;\nya vamos a caminar,\nde ser mi separación.",166,2,-1,188,"DESPEDIMENTO AL SEÑOR DEL HOSPITAL DE LA VILLA DE SALAMANCA",9,6,"o",-1,0,-1,0,348,348,"Ap. 172","",0,"","","",1,0,0,[],""],["frenk_t4-ap172-03",8,"échanos tu bendición,\ntambién los de Nuevo León\ndicen todos por igual;\nvendrán hasta otra ocasión,\nPadre mío del Hospital.",166,2,-1,188,"DESPEDIMENTO AL SEÑOR DEL HOSPITAL DE LA VILLA DE SALAMANCA",7,5,"a",1,0,-1,0,348,348,"Ap. 172","",0,"","","",1,0,0,[],""],["frenk_t4-ap172-04",8,"Lindo de mi corazón,\nmi trigueñito sagrado;\nadiós, dice aletargado\ntoda la ciudad de León;\nva a ser su separación,\nte dicen los de Durango,\nde Cadereyta y Camargo,\nte dicen con devoción:\n“No te olvides de nosotros,\nPadre de consolación.”",166,2,-1,188,"DESPEDIMENTO AL SEÑOR DEL HOSPITAL DE LA VILLA DE SALAMANCA",18,10,"o",31,0,-1,0,349,349,"Ap. 172","",0,"","","",1,0,0,[],""],["frenk_t4-ap172-05",8,"Adiós, flor de mejor vara,\ndicen los de Aguascalientes;\nde Guanajuato obedientes,\ntambién de Guadalajara;\ncada quien a su morada,\ntodos piden en lo actual,\nPadre fuerte y sin igual,\ny tú has de ser nuestro guía\nen nuestras penas sombrías,\nPadre mío del Hospital.",166,2,-1,188,"DESPEDIMENTO AL SEÑOR DEL HOSPITAL DE LA VILLA DE SALAMANCA",18,10,"a",1,0,-1,0,349,349,"Ap. 172","",0,"","","",1,0,0,[],""],["frenk_t4-ap172-06",8,"Venid, ángeles de gloria,\nvenid desde el alto cielo,\nte dice Silao Victoria\nel adiós con desconsuelo;\neres todo nuestro anhelo\nque el martes ya celebramos;\ncon tu protección contamos\ndicen los de Zapotlán,\na ti nos encomendamos,\nPadre mío del Hospital.",166,2,-1,188,"DESPEDIMENTO AL SEÑOR DEL HOSPITAL DE LA VILLA DE SALAMANCA",18,10,"a",-1,0,-1,0,349,349,"Ap. 172","",0,"","","",1,0,0,[],""],["frenk_t4-ap172-07",8,"Adiós, la cruz elevada,\nte dicen gentes sencillas;\nadiós, estrella que brillas,\ndicen de Rosa Morada;\ntambién los de Matehuala\nse despiden de tu vista;\ndicen los de la Villita\nque se van a caminar;\nadiós, hasta otra ocasión,\nPadre mío del Hospital.",166,2,-1,188,"DESPEDIMENTO AL SEÑOR DEL HOSPITAL DE LA VILLA DE SALAMANCA",18,10,"a",-1,0,-1,0,349,349,"Ap. 172","",0,"","","",1,0,0,[],""],["frenk_t4-ap172-08",8,"Adiós, auxilio sin par,\nadiós, todo mi reposo,\nadiós, atril primoroso,\nadiós, templo singular;\nadiós, dicen sin cesar\ncantando dos mil primores;\nlos del pueblo de Dolores\nse despiden ya de vos;\ndicen los de Miraflores:\n“Adiós, Padrecito, adiós”.",166,2,-1,188,"DESPEDIMENTO AL SEÑOR DEL HOSPITAL DE LA VILLA DE SALAMANCA",18,10,"o",87,0,-1,0,349,349,"Ap. 172","",0,"","","",1,0,0,[],""],["frenk_t4-ap172-09",8,"Tus reliquias llevo aquí,\ntu rosario y tu estampita,\ny también tus medallitas\npara acordarme de ti;\nadiós, pues, que ya te vi,\nte llevo en mi corazón.\n¿Volveré en otra ocasión,\nmuro firme y sin mancilla?,\nhasta el año venidero,\nsi Dios nos presta la vida.",166,2,-1,188,"DESPEDIMENTO AL SEÑOR DEL HOSPITAL DE LA VILLA DE SALAMANCA",18,10,"ia",-1,0,-1,0,349,349,"Ap. 172","",0,"","","",1,0,0,[],""],["frenk_t4-ap172-11",8,"En fin, mi manso Cordero,\ntú nos has de acompañar,\ny que podamos llegar\na gozarte allá en el cielo;\nporque eres nuestro consuelo,\ny en ti la esperanza habita;\ntodo viviente te grita:\nte pedimos en cada hora,\nnos des una buena muerte\npara mirarte en la gloria.",166,2,-1,188,"DESPEDIMENTO AL SEÑOR DEL HOSPITAL DE LA VILLA DE SALAMANCA",18,10,"oa",-1,0,-1,0,349,349,"Ap. 172","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-01",8,"Adiós, Señor de mi vida,\nadiós, mi prenda querida,\nadiós, cura venturoso,\nadiós, función tan lucida.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"ia",37,0,-1,0,349,349,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-02",8,"Adiós, Señor de los cielos,\nay, momento, triste alarde,\nprenda, la más estimada\nde la más dichosa madre.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"ae",-1,0,-1,0,349,349,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-03",8,"Ya me despido llorando,\nadiós hasta el venidero;\nadiós, mi prenda querida\nque estás en este madero.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"eo",38,0,-1,0,349,349,"Ap. 173","",0,"","","",2,0,0,[],""],["frenk_t4-ap173-04",8,"Adiós, santo romerío,\nadiós, cirio consagrado,\nadiós, mi padre amoroso,\nde todos seas alabado.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"ao",14,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-05",8,"Adiós templo, adiós altar,\nadiós, veleta encumbrada,\nadiós, campanita, adiós;\nadiós, coro, adiós portal.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",5,4,"a",-1,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-06",8,"Adiós, pila consagrada,\nadiós, santo bautisterio;\nadiós, tu colateral,\nadiós, adiós, cementerio.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"eo",398,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-07",8,"Tu bendición esperamos\nde tus manos consagradas,\nSanto Cristo aparecido,\nya estoy preso en mi jomada",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"aa",-1,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-08",8,"Adiós, Padrecito y Madre,\nya vi tu rostro de nuevo;\nel visitante se va\na volver de donde vino.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",5,4,"io",-1,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-09",8,"Ya se van tus visitantes\nde pueblos, ranchos y villas,\ndiciéndote: “Adiós, Señor,\nya vimos tus maravillas.”",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"ia",294,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-10",8,"Ya se van tus peregrinos;\nadiós, mi Padre querido,\nse van de tu compañía\ncon el corazón herido.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"io",101,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-11",8,"Se van de buena salud\nde Topia y de Culiacán,\nde Durango y de Santiago,\ndel puerto de Mazatlán.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"a",147,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-12",8,"Ya se van del Cerro Gordo,\nde la Sarca y del Cordero,\ndándote mil parabienes,\nPadre y Jesús de los cielos.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"eo",-1,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-13",8,"Adiós, rosa de Castilla,\nlos de Mapimí dirán;\ntambién los de La Laguna\nde tu presencia se van.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"a",147,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-14",8,"Todos los de tierra adentro\nse despiden por iguales,\nde Chihuahua y Canutillo\ny Santa Cruz de Rosales.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"ae",26,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap173-15",8,"Ya llegó el triste momento\nde ir a emprender su partida;\nadiós, Señor de mi vida,\nadiós, prenda de mi vida.",166,2,-1,188,"DESPEDIDA AL SEÑOR DE MAPIMÍ",0,4,"ia",-1,0,-1,0,350,350,"Ap. 173","",0,"","","",1,0,0,[],""],["frenk_t4-ap174-01",8,"San Caralampio nos llama\nel día del juicio final,\ny da la primer llamada\nantes de que llegue el mal.",166,2,-1,188,"ORACIÓN A SAN CARALAMPIO",0,4,"a",1,0,-1,0,350,350,"Ap. 174","",0,"","","",1,0,0,[],""],["frenk_t4-ap174-02",8,"Los mandamientos son diez,\nmás los siete sacramentos;\nmilagrosas son las tres\npersonas, dos testamentos.",166,2,-1,188,"ORACIÓN A SAN CARALAMPIO",1,4,"eo",234,0,-1,0,350,350,"Ap. 174","",0,"","","",1,0,0,[],""],["frenk_t4-ap174-03",8,"Sólo hay un juicio final\ny una doctrina cristiana,\nsólo una sombra del mal\nque se retira a la diana.",166,2,-1,188,"ORACIÓN A SAN CARALAMPIO",1,4,"aa",4,0,-1,0,350,350,"Ap. 174","",0,"","","",1,0,0,[],""],["frenk_t4-ap174-04",8,"San Caralampio nos dice:\n“Yo les voy a recordar\nque un solo Dios, en el cielo,\nes lo que se debe amar.”",166,2,-1,188,"ORACIÓN A SAN CARALAMPIO",0,4,"a",21,0,-1,0,350,350,"Ap. 174","",0,"","","",1,0,0,[],""],["frenk_t4-ap174-05",8,"Los artículos de fe\nhoy los van a preguntar;\nel día del juicio ha llegado,\nya se oye el clarín sonar.",166,2,-1,188,"ORACIÓN A SAN CARALAMPIO",0,4,"a",21,0,-1,0,350,350,"Ap. 174","",0,"","","",1,0,0,[],""],["frenk_t4-ap174-06",8,"Santísimo Caralampio,\ndanos riqueza y placer,\nahuyenta los malos ratos\ny al soltero da mujer.",166,2,-1,188,"ORACIÓN A SAN CARALAMPIO",0,4,"e",20,0,-1,0,350,350,"Ap. 174","",0,"","","",2,0,0,[],""],["frenk_t4-ap174-07",8,"A la soltera, consorte,\nal pobre, bienes y abrigo;\nal rico, buena memoria\npara que ayude al amigo.",166,2,-1,188,"ORACIÓN A SAN CARALAMPIO",0,4,"io",106,0,-1,0,350,350,"Ap. 174","",0,"","","",1,0,0,[],""],["frenk_t4-ap174-08",8,"Santísimo Caralampio,\ncuida mi casa y la ajena,\ndel rayo libra mi espalda\ny alivia al alma de pena.",166,2,-1,188,"ORACIÓN A SAN CARALAMPIO",0,4,"ea",59,0,-1,0,351,351,"Ap. 174","",0,"","","",2,0,0,[],""],["frenk_t4-ap174-09",8,"San Caralampio, Señor,\nCristo y Virgen del Perdón,\npor el huerto del dolor\ndadme ya la bendición.",166,2,-1,188,"ORACIÓN A SAN CARALAMPIO",1,4,"o",-1,0,-1,0,351,351,"Ap. 174","",0,"","","",1,0,0,[],""],["frenk_t4-ap176-01",8,"San Agustín Victorioso,\nsintiendo cerca su fin,\nmandó llamar a los santos\ncon su amigo San Joaquín.",170,2,7,188,"TESTAMENTO DE SAN AGUSTIN VICTORIOSO",3,4,"i",211,0,-1,0,351,351,"Ap. 176","",0,"","","",9,0,0,[],""],["frenk_t4-ap176-02",8,"Rodeado de sus vaqueros\ny sus fieles caporales,\nno dejaba de pensar\nen todos sus animales.",170,2,7,188,"TESTAMENTO DE SAN AGUSTIN VICTORIOSO",0,4,"ae",26,0,-1,0,351,351,"Ap. 176","",0,"","","",1,0,0,[],""],["frenk_t4-ap176-03",8,"“¡Cómo tardan mis amigos!,\nse decía San Agustín;\nsi así tardara la muerte,\nhoy le pintaba un violín.”",170,2,7,188,"TESTAMENTO DE SAN AGUSTIN VICTORIOSO",0,4,"i",211,0,-1,0,351,351,"Ap. 176","",0,"","","",1,0,0,[],""],["frenk_t4-ap176-04",8,"San Vicente fue el primero\nde los santos en llegar;\nluego llegó San Francisco,\ndespués vino San Gaspar.",170,2,7,188,"TESTAMENTO DE SAN AGUSTIN VICTORIOSO",0,4,"a",21,0,-1,0,351,351,"Ap. 176","",0,"","","",1,0,0,[],""],["frenk_t4-ap176-05",8,"San Jorge llegó corriendo,\nseguido de San Gabriel;\nSan Gregorio y San Ignacio\nllegaron con San Manuel.",170,2,7,188,"TESTAMENTO DE SAN AGUSTIN VICTORIOSO",0,4,"e",32,0,-1,0,351,351,"Ap. 176","",0,"","","",1,0,0,[],""],["frenk_t4-ap176-06",8,"San Nicolás y Santiago,\na poco fueron llegando;\ntras ellos llegó San Pedro\nque los venía coleando.",170,2,7,188,"TESTAMENTO DE SAN AGUSTIN VICTORIOSO",0,4,"ao",33,0,-1,0,351,351,"Ap. 176","",0,"","","",1,0,0,[],""],["frenk_t4-ap176-10",8,"será la primera parte,\nla segunda se reparte\nentre parientes y hermanos;\npagado fue el escribano,\ndelante de los testigos,\ncon mis sentidos cabales;\nhago aquí partes iguales\ncon mucha precaución;\npara todos mis amigos,\nes la última donación.",170,2,7,188,"TESTAMENTO DE SAN AGUSTIN VICTORIOSO",18,10,"o",31,0,-1,0,352,352,"Ap. 176","",0,"","","",1,0,0,[],""],["frenk_t4-ap176-11",8,"El mundo estará contento,\npues a todos por igual,\nsin distinción de cabeza,\nles repartí el capital.”",170,2,7,188,"TESTAMENTO DE SAN AGUSTIN VICTORIOSO",0,4,"a",1,0,-1,0,352,352,"Ap. 176","",0,"","","",1,0,0,[],""],["frenk_t4-ap176-12",8,"¡Adiós, lindas jovencitas,\naquí termino, por fin;\ndénle un traguito a su amigo\nque cantó el San Agustín!",170,2,7,188,"TESTAMENTO DE SAN AGUSTIN VICTORIOSO",0,4,"i",211,0,-1,0,352,352,"Ap. 176","",0,"","","",1,0,0,[],""],["frenk_t4-ap177-01",8,"San Ignacio de Loyola,\nSan Vicente de Ferrel\nfueron a torear un toro\nal rancho de San Miguel.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"e",32,0,-1,0,352,352,"Ap. 177","",0,"","","",2,0,0,[],""],["frenk_t4-ap177-02",8,"San Pedro no estaba allí,\nél andaba remudando;\npedacitos le hizo el fuste\nuna burra reparando.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"ao",33,0,-1,0,352,352,"Ap. 177","",0,"","","",1,0,0,[],""],["frenk_t4-ap177-03",8,"Luego salió San Felipe\ncon gusto y de buena gana:\n“Échenmelo contra el lienzo,\nle tiraré una mangana”.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"aa",4,0,-1,0,352,352,"Ap. 177","",0,"","","",1,0,0,[],""],["frenk_t4-ap177-04",8,"Luego salió San Fernando\nen una yegua tuzada;\npedazos de calzonera\npor el viento le volaban.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"aa",-1,0,-1,0,352,352,"Ap. 177","",0,"","","",1,0,0,[],""],["frenk_t4-ap177-05",8,"Luego salió San Antonio\nen su caballito arisco,\ncon sus espuelotas grandes\nque le prestó San Francisco.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"io",649,0,-1,0,352,352,"Ap. 177","",0,"","","",1,0,0,[],""],["frenk_t4-ap177-06",8,"Luego salió San Martín\nen un prieto salpicado:\nque él iba a torear el toro,\nque tenía valor sobrado.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"ao",14,0,-1,0,352,352,"Ap. 177","",0,"","","",1,0,0,[],""],["frenk_t4-ap177-07",8,"Luego se le dejó caer\nSan Gaspar y San Simón:\nhombre que ha sido partero\nno puede ser toreador.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"o",-1,0,-1,0,352,352,"Ap. 177","",0,"","","",1,0,0,[],""],["frenk_t4-ap177-08",8,"También el Señor Santiago,\nhombre de bastante honor.\nAquí se acaba el corrido\nde los santos de valor.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"o",72,0,-1,0,352,352,"Ap. 177","",0,"","","",1,0,0,[],""],["frenk_t4-ap177-11",8,"San Agustín Victorioso\nnunca se puso camisa;\nla primera que se puso,\nla cambió por longaniza.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"ia",420,0,-1,0,352,352,"Ap. 177","",0,"","","",9,0,0,[],""],["frenk_t4-ap177-12",8,"San Agustín Victorioso\nnunca se puso calzones;\nlos primeros que se puso,\nlos cambió por chicharrones.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"oe",34,0,-1,0,352,352,"Ap. 177","",0,"","","",9,0,0,[],""],["frenk_t4-ap177-13",8,"San Agustín Victorioso\nnunca se puso sombrero;\nel primero que se puso,\nfue una cachucha de cuero.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"eo",38,0,-1,0,353,353,"Ap. 177","",0,"","","",9,0,0,[],""],["frenk_t4-ap177-14",8,"San Agustín Victorioso\nnunca se puso guaraches;\nlos primeros que se puso,\nse los regaló a unos guaches.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"ae",526,0,-1,0,353,353,"Ap. 177","",0,"","","",9,0,0,[],""],["frenk_t4-ap177-15",8,"San Agustín Victorioso,\ndueño de una cofradía,\ncuatro ranchos y tres huertas\npor propiedades tenía.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"ia",0,0,-1,0,353,353,"Ap. 177","",0,"","","",9,0,0,[],""],["frenk_t4-ap177-16",8,"San Agustín Victorioso,\ncon toda su vaquerada,\nal rancho de San Miguel\nse fueron de madrugada.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"aa",49,0,-1,0,353,353,"Ap. 177","",0,"","","",9,0,0,[],""],["frenk_t4-ap177-17",8,"Uno de los cuatro ranchos\nque San Agustín tenía,\nsobre las grandes llanuras\ndel Cerro del Agua Fría.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"ia",0,0,-1,0,353,353,"Ap. 177","",0,"","","",1,0,0,[],""],["frenk_t4-ap177-18",8,"San Agustín Victorioso\nfue un jinete sin rival:\nmontaba potros y toros,\nsin estribos ni pretal.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"a",1,0,-1,0,353,353,"Ap. 177","",0,"","","",9,0,0,[],""],["frenk_t4-ap177-19",8,"San Ignacio de Loyola,\ncon una cuerda lucida,\nmontando un caballo grullo\nllevaba a la recogida.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"ia",37,0,-1,0,353,353,"Ap. 177","",0,"","","",2,0,0,[],""],["frenk_t4-ap177-20",8,"—Caballo grullo, ni tuyo,\nle dice San Agustín.\n—Caballo moro ni de oro,\nesto dijo San Joaquín.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",3,4,"i",211,0,-1,0,353,353,"Ap. 177","",0,"","","",1,0,0,[],""],["frenk_t4-ap177-21",8,"—Aunque es grullo mi caballo,\nno deja de hacer buen lomo;\nlas palabras que me dicen,\ncomo de quien son las tomo.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"oo",349,0,-1,0,353,353,"Ap. 177","",0,"","","",1,0,0,[],""],["frenk_t4-ap177-22",8,"Todos los santos se rieron\na mandíbula batiente;\nal oír a San Ignacio\nse carcajeó hasta la gente.",166,2,-1,188,"CORRIDO DE LOS SANTOS DE VALOR",0,4,"ee",15,0,-1,0,353,353,"Ap. 177","",0,"","","",1,0,0,[],""],["frenk_t4-ap179-01",8,"Para que no se te olviden\nlos días de cada mes,\naprenderás de memoria\neste cómputo que ves.",166,2,-1,188,"LOS MESES",0,4,"e",218,0,-1,0,353,353,"Ap. 179","",0,"","","",1,0,0,[],""],["frenk_t4-ap179-02",8,"Treinta sólo traen abril,\njunio, septiembre y noviembre;\nfebrero, en común, veintiocho,\ny en bisiesto, veintinueve.",166,2,-1,188,"LOS MESES",0,4,"ee",-1,0,-1,0,353,353,"Ap. 179","",0,"","","",1,0,0,[],""],["frenk_t4-ap179-03",8,"Los siete meses restantes\ntodos tienen treinta y uno;\nsea o no bisiesto el año,\nno hay diferencia en ninguno.",166,2,-1,188,"LOS MESES",0,4,"uo",230,0,-1,0,353,353,"Ap. 179","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-01",8,"En la feria de Morelos\nencontré a la vida mía,\ny me dijo con anhelo:\n“Llévame a la lotería,\nahí no más la están corriendo,\nregalo del alma mía.”",166,2,-1,188,"LA LOTERÍA",9,6,"ia",0,0,-1,0,353,353,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-02",8,"¡Ya se va la lotería,\nalerta los que están presentes!\nEsto me dijo Lucía:\n“Ya tenía deseos de verte,\nllévame a la lotería,\nllévame a rifar mi suerte.”",166,2,-1,188,"LA LOTERÍA",9,6,"ee",134,0,-1,0,353,353,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-03",8,"Dama triste y afligida,\nel corazón traspasado;\nla pifia de a tres cuartillas,\nel pavo real mexicano,\nla chalupita remando,\nel corazón colorado.",166,2,-1,188,"LA LOTERÍA",9,6,"ao",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-04",8,"Una sandía rebanada,\nel toro bravo de Ateneo,\nel que lo tiene lo carga;\nel indito flachiquero,\nla bandera nacional,\nel pastelero vendiendo.",166,2,-1,188,"LA LOTERÍA",9,6,"eo",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-05",8,"El periquito hablador,\nel soldado está de guardia,\nal pie de un verde limón,\nla rana verde del agua,\nya viene saliendo el sol,\nlucero de la mañana.",166,2,-1,188,"LA LOTERÍA",9,6,"aa",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-06",8,"Señora, mire a su perro,\ntambor o caja de guerra,\nen la tierra de los ciegos,\nel que espera desespera,\nel compás de un carpintero,\nlos anteojos de una suegra.",166,2,-1,188,"LA LOTERÍA",9,6,"ea",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-07",8,"Pájaro que alegre cantas,\nel catrín se anda paseando,\nla iguana allá en la barranca,\nun pino alto y elevado,\nel árbol de la confianza,\n¿qué paredón se habrá cáido?",166,2,-1,188,"LA LOTERÍA",9,6,"ao",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-08",8,"La escalera de un sereno,\nel león con ser animal...,\nel que carga el mundo entero,\nal pie de un verde nopal,\nel negrito es habanero,\nel caballito alazán.",166,2,-1,188,"LA LOTERÍA",9,6,"a",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-09",8,"Con las que repican, doblan,\nlas torres de San Icuipa,\nel guajolote en la fonda,\nla granada es cordelina,\nuna maceta de flores,\nuna rosa de Castilla.",166,2,-1,188,"LA LOTERÍA",9,6,"ia",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-11",8,"¿A dónde chilla el marrano?,\nojalá se quiebre el arpa,\nla mano de un escribano,\nla que adoran en Zacualpa,\nel aguador mexicano,\npor el cuatro caen las ratas.",166,2,-1,188,"LA LOTERÍA",9,6,"aa",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-12",8,"Mis tijeras ya no cortan,\ndonde lloran está el muerto,\nel navio va a toda vela,\nlas jaras de un indio meco,\nuna naranja madura,\nel ratón se acaba el queso.",166,2,-1,188,"LA LOTERÍA",9,6,"eo",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-13",8,"El capitán de Celaya,\nel valiente bachilaco,\nun meloncito en la playa,\nla muerte siriquicuando,\nla calavera de Adán,\nel alacrán de Durango.",166,2,-1,188,"LA LOTERÍA",9,6,"ao",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-14",8,"El venadito en la breña,\nno te hago caso, rogona,\nel que se duerme no cena,\nla sirena encantadora,\nel borracho y su botella,\nla bota rechinadora.",166,2,-1,188,"LA LOTERÍA",9,6,"oa",107,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-15",8,"Viene saliendo la luna,\nel peine de las señoras,\nel patito en la laguna,\nel diablo en el panteón llora,\nel gallito en el palenque,\nel reloj dando las horas.",166,2,-1,188,"LA LOTERÍA",9,6,"oa",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap180-16",8,"Mas, en fin, ya me despido;\nadiós, prenda de mi vida,\nadiós, amor consentido,\nya se acerca mi partida\ny por eso me despido\nde esta lotería lucida.",166,2,-1,188,"LA LOTERÍA",9,6,"ia",37,0,-1,0,354,354,"Ap. 180","",0,"","","",2,0,0,[],""],["frenk_t4-ap180-17",8,"¡Ya salió la lotería,\nsalió con el veinticuatro!\nesto me dijo Lucía;\n“Ya para pasar el rato,\nme saqué una lotería\nde a tres pesos menos cuatro.”",166,2,-1,188,"LA LOTERÍA",9,6,"ao",-1,0,-1,0,354,354,"Ap. 180","",0,"","","",1,0,0,[],""],["frenk_t4-ap182-01",8,"Corté la flor de la tuna,\ninjertada con liante;\nsin ofender a ninguna,\nquiero que me diga usted:\n¿Cuántos días tiene la luna?",166,2,-1,188,"CORTÉ LA FLOR DE LA TUNA",7,5,"ua",56,0,-1,0,355,355,"Ap. 182","",0,"","","",2,0,0,[],""],["frenk_t4-ap182-02",8,"La luna es el astro rey\nque ilumina el firmamento,\ny que parece un portento\nlo invariable de su ley;\nhace crecer al maguey,\nal plátano y la aceituna,\ny si mengua, una por una,\nlas ves menguar a fe mía;\ntan sólo por ver si olía,\ncorté la flor de la tuna.",166,2,-1,188,"CORTÉ LA FLOR DE LA TUNA",18,10,"ua",56,0,-1,0,355,355,"Ap. 182","",0,"","","",1,0,0,[],""],["frenk_t4-ap182-03",8,"La luna tiene que ver\ncon el mar y con los peces,\ny hasta la planta florece\ndespués que la hace crecer;\nhace menstruar la mujer,\ny así como usté la ve,\nel mundo entero yo sé\nque se rige por la luna.\nCorté la flor de la tuna\ninjertada con llanté.",166,2,-1,188,"CORTÉ LA FLOR DE LA TUNA",18,10,"e",77,0,-1,0,355,355,"Ap. 182","",0,"","","",1,0,0,[],""],["frenk_t4-ap182-04",8,"La luna, de enero a enero,\ncasi siempre la verás\nque la sigue, por detrás,\nun refulgente lucero;\nese es su fiel compañero\ny pregunto: ¿Por fortuna,\nexiste mujer alguna\nque no la haga cabalgar?\nYo lo quiero averiguar\nsin ofender a ninguna.",166,2,-1,188,"CORTÉ LA FLOR DE LA TUNA",18,10,"ua",56,0,-1,0,356,356,"Ap. 182","",0,"","","",1,0,0,[],""],["frenk_t4-ap182-05",8,"El que a preguntar se atreve:\ncuántos días tiene la luna,\nle diré que por fortuna\nsólo tiene veintinueve,\ny como sola se mueve,\nse oculta y nadie la ve;",166,2,-1,188,"CORTÉ LA FLOR DE LA TUNA",9,6,"e",-1,0,-1,0,356,356,"Ap. 182","",0,"","","",1,0,0,[],""],["frenk_t4-ap182-06",8,"y un astrónomo da fe\nque la luna es habitada\n¿cómo la ve, camarada?,\nquiero que me diga usté.",166,2,-1,188,"CORTÉ LA FLOR DE LA TUNA",11,4,"e",77,0,-1,0,356,356,"Ap. 182","",0,"","","",1,0,0,[],""],["frenk_t4-ap182-08",8,"En fin, la luna verás\ntodos los meses del año,\na veces causando daño\ny haciendo bien por demás;\ntodo marcha a su compás\nsin diferencia ninguna:\nla tierra, el mar, la laguna,\nla flor, el ave y la noria,\ntodos saben de memoria\ncuántos días tiene la luna.",166,2,-1,188,"CORTÉ LA FLOR DE LA TUNA",18,10,"ua",56,0,-1,0,356,356,"Ap. 182","",0,"","","",1,0,0,[],""],["frenk_t4-ap183-01",8,"Señores, me había dormido,\nla ausencia me dispertó.\n¡Ave María!, ¡gavilanes!\nYa el águila real llegó.",168,2,11,188,"SEÑORES, ME HABÍA DORMIDO",0,4,"o",2,0,-1,0,356,356,"Ap. 183","",0,"","","",1,0,0,[],""],["frenk_t4-ap183-02",8,"Hoy sólo vengo a saber\nquién es aquí el cantador,\nel poeta o compositor\nque se me quiera oponer;\npienso no le ha de valer,\nsi cantar bien ha sabido,\ny si no es desentendido\nhoy pregunto con anhelo:\n¿Cuánto hay de la tierra al cielo?\nSeñores, me había dormido.",168,2,11,188,"SEÑORES, ME HABÍA DORMIDO",18,10,"io",101,0,-1,0,356,356,"Ap. 183","",0,"","","",1,0,0,[],""],["frenk_t4-ap183-03",8,"Esto me has de contestar,\ncomo te voy preguntando,\nsi quieres seguir versando:\n¿Cuántos peces tiene el mar?\nSi me llegas a explicar\nquedaré gustoso yo;\nme dirás: ¿Dónde paró\nCristo después de haber muerto?,\ny ]por su costado abierto!,\nla ausencia me dispertó.",168,2,11,188,"SEÑORES, ME HABÍA DORMIDO",18,10,"o",2,0,-1,0,356,356,"Ap. 183","",0,"","","",1,0,0,[],""],["frenk_t4-ap183-04",8,"Pienso que me ando engañando:\n¿qué colores tiene el día?,\nsi quieres seguir versando,\n¿qué dice la Teología\nde la luz del claro día?\nNo se anime a los caimanes,\nanímese a los galanes\nde las guapas y las criollas;\nno tengan miedo a las pollas,\n¡Ave María!, ¡gavilanes!",168,2,11,188,"SEÑORES, ME HABÍA DORMIDO",18,10,"ae",444,0,-1,0,356,356,"Ap. 183","",0,"","","",1,0,0,[],""],["frenk_t4-ap183-05",8,"¿Dónde el bálsamo quedara\ncon que ungieron al Señor?\nEsto deseo saber yo:\nsi en la tierra o en el agua.\n¿Qué contiene aquella vara\nque a San José floreció?\nLa respuesta espero yo\ncon siete cielos contando;\náguila que andas volando,\nya el águila real llegó.",168,2,11,188,"SEÑORES, ME HABÍA DORMIDO",18,10,"o",2,0,-1,0,356,356,"Ap. 183","",0,"","","",1,0,0,[],""],["frenk_t4-ap185-01",8,"Es muy preciso advertir\npara ponerse en estado:\nnecesita el que es casado\nhasta cama en que dormir.",171,2,4,188,"PARA PONERSE EN ESTADO",11,4,"i",157,0,-1,0,357,357,"Ap. 185","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap186-01",8,"Ahi vienen los colorados\nde la sierra de Amarillas;\néchame tus brazos, mi alma,\ncon esas venas azules.",166,2,-1,188,"LOS COLORADOS",5,4,"ue",-1,0,-1,0,358,358,"Ap. 186","",0,"","","",1,0,0,[],""],["frenk_t4-ap186-02",8,"Salieron los colorados,\nsalieron de uno en uno,\ny su chata les decía:\n“Los que se van... pero uno.”",166,2,-1,188,"LOS COLORADOS",0,4,"uo",-1,0,-1,0,358,358,"Ap. 186","",0,"","","",4,0,0,[],""],["frenk_t4-ap186-03",8,"Salieron los colorados,\nsalieron de dos en dos,\ny su chata les decía:\n“¿Por qué no dicen adiós?”",166,2,-1,188,"LOS COLORADOS",0,4,"o",87,0,-1,0,358,358,"Ap. 186","",0,"","","",4,0,0,[],""],["frenk_t4-ap186-04",8,"Salieron los colorados,\nsalieron de tres en tres,\ny su chata les decía:\n“Vamos matando un francés.”",166,2,-1,188,"LOS COLORADOS",0,4,"e",218,0,-1,0,358,358,"Ap. 186","",0,"","","",4,0,0,[],""],["frenk_t4-ap186-05",8,"Salieron los colorados,\nsalieron de cuatro en cuatro\ny su chata les decía:\n“¿Qué me traen de Guanajuato?”",166,2,-1,188,"LOS COLORADOS",0,4,"ao",-1,0,-1,0,358,358,"Ap. 186","",0,"","","",4,0,0,[],""],["frenk_t4-ap186-06",8,"No quiero paz,\nno quiero unión;\nlo que quiero son balazos.\n¡Viva la revolución!",166,2,-1,188,"LOS COLORADOS",3,4,"o",31,0,-1,0,358,358,"Ap. 186","",0,"","","",2,0,0,[],""],["frenk_t4-ap187-01",8,"Lo que digo de hoy en día,\nlo que digo lo sostengo:\n¡yo no vengo a ver si puedo,\nsino porque puedo vengo!",166,2,-1,188,"YO NO VENGO A VER SI PUEDO",0,4,"eo",-1,0,-1,0,358,358,"Ap. 187","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap187-02",8,"Dicen que yo soy pelado,\ny no sirvo pa el gobierno;\n¡yo no vengo a ver si puedo,\nsino porque puedo vengo!\nsino porque puedo vengo!",166,2,-1,188,"YO NO VENGO A VER SI PUEDO",7,5,"eo",-1,0,-1,0,358,358,"Ap. 187","",0,"","","",1,0,0,[],""],["frenk_t4-ap187-03",8,"Lo que les va a suceder\na los ricos, les prevengo:\n¡yo no vengo a ver si puedo,\nsino porque puedo vengo!",166,2,-1,188,"YO NO VENGO A VER SI PUEDO",0,4,"eo",-1,0,-1,0,358,358,"Ap. 187","",0,"","","",1,0,0,[],""],["frenk_t4-ap187-04",8,"Dicen que ellos se mantienen,\ny yo soy quien los mantengo;\n¡yo no vengo a ver si puedo,\nsino porque puedo vengo!",166,2,-1,188,"YO NO VENGO A VER SI PUEDO",0,4,"eo",-1,0,-1,0,359,359,"Ap. 187","",0,"","","",1,0,0,[],""],["frenk_t4-ap187-06",8,"¡Ay!, padrecitos y monjas\nque se mantienen del pueblo:\n¡yo no vengo a ver si puedo,\nsino porque puedo vengo!",166,2,-1,188,"YO NO VENGO A VER SI PUEDO",0,4,"eo",-1,0,-1,0,359,359,"Ap. 187","",0,"","","",1,0,0,[],""],["frenk_t4-ap188-01",8,"Ya el mundo se va a acabar\ncomo está pronosticado;\nno hay que olvidar al cuidado,\nsino con cuidado estar.",166,2,-1,188,"EL FIN DEL MUNDO",11,4,"a",21,0,-1,0,359,359,"Ap. 188","",0,"","","",2,0,0,[],""],["frenk_t4-ap188-02",8,"El próximo mes entrante,\njunio de cincuenta y siete,\nserá el día en que se complete\ndel mundo el fin de una vez.\nHay autores, más de diez,\nastrónomos a la par\nque han venido a asegurar\ncon grande sabiduría,\nque ya se nos llegó el día,\nya el mundo se va a acabar.",166,2,-1,188,"EL FIN DEL MUNDO",18,10,"a",21,0,-1,0,359,359,"Ap. 188","",0,"","","",1,0,0,[],""],["frenk_t4-ap188-03",8,"Un cometa, formidable\ncomo una serpiente fiera,\nha de chocar con la tierra\ncon su cola interminable;\na ese choque saludable\nserá el globo desquiciado,\ny en el sol será aplastado\ncomo masa de buñuelos,\nesparcido por los cielos\ncomo está pronosticado.",166,2,-1,188,"EL FIN DEL MUNDO",18,10,"ao",14,0,-1,0,359,359,"Ap. 188","",0,"","","",1,0,0,[],""],["frenk_t4-ap188-04",8,"Cada hombre caminará\ncomo bala de cañón,\ny en la espaciosa mansión\nal fin se desgastará;\nni su polvo se verá,\nporque en el aire embarrado,\nen él mismo se ha quedado;\nfatal desgracia por cierto,\nlector, estáte despierto;\nno hay que olvidar al cuidado.",166,2,-1,188,"EL FIN DEL MUNDO",18,10,"ao",14,0,-1,0,359,359,"Ap. 188","",0,"","","",1,0,0,[],""],["frenk_t4-ap188-05",8,"No hay que guardar ya dinero\ncon avaricia formal,\nsi al cabo se va a acabar\neste mundo lisonjero;\nni trabajar con esmero,\nni beber, ni enamorar,\nni perder tiempo en charlar\nen los cafés como loco,\nni beber pulque tampoco,\nsino con cuidado estar.",166,2,-1,188,"EL FIN DEL MUNDO",18,10,"a",21,0,-1,0,359,359,"Ap. 188","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-01",8,"¡Oh, qué toro tan puntal,\na toditos ha arrastrado!;\nparece perro del mal,\nsegún nos ha revolcado.",166,2,-1,188,"EL TORITO DEL COMERCIO",1,4,"ao",14,0,-1,0,359,359,"Ap. 189","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap189-03",8,"A todos, en general,\neste toro ha revolcado,\nninguno se le ha escapado,\na toditos por igual;\neste es un toro puntal\nque anda en toda la nación,\na todos, sin dilación,\nnos ha causado algún mal\ny dicen en pelotón:\n“¡Ay, qué toro tan puntal!’’",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"a",1,0,-1,0,360,360,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-04",8,"Al rico, al pobre y aldeano,\narrieros y comerciantes;\nel capital más constante\nse lo ha llevado entre mano;\nhoy todito ciudadano\nya ninguno se ha parado,\naunque sea el más afamado,\nporque a toditos embiste;\njah, que lamento tan triste:\na toditos ha arrastrado!",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"ao",14,0,-1,0,360,360,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-05",8,"En Guanajuato jay, Jesús!,\na toditos los mineros\nya los ha dejado en cueros,\ndel Mineral de la Luz;\nni con ponerle la cruz\na semejante animal;\nen Angangueo por igual,\nTlalpujahua, Real del Oro;\nanda muy bravo ese toro,\nparece perro del mal.",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"a",1,0,-1,0,360,360,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-06",8,"México, la gran ciudad,\ntodos los días, diariamente,\nse sale bastante gente\npor tan gran necesidad;\nhay mucha calamidad,\ntodo el comercio atrasado;\nel arte más afamado\nse lamenta diariamente,\nmuy asustada la gente,\nsegún los ha revolcado.",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"ao",14,0,-1,0,360,360,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-07",8,"A todos los minerales\nlos ha revolcado el toro;\nya ni la plata, ni el oro,\nni quien saque los metales;\npronto acabarán los reales\nasegún io que se espera;\npor Nuevo León, la Frontera,\nSan Miguel y los Dolores,\nno se oyen más que clamores:\nSeñores ¡ah, que arranquera!",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"ea",44,0,-1,0,360,360,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-08",8,"En la hermosa capital,\npueblos, villas y ciudades,\nse ven mil calamidades\ncon ese toro del mal;\nni modo de echarle un pial,\nporque es muy bravo y ligero;\nanda todo el reino entero,\ndeja espantada a la gente,\ny dice todo viviente:\n¡Ah, qué escasez de dinero!",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"eo",38,0,-1,0,360,360,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-09",8,"En Querétaro, aflicción,\npor Salamanca y Celaya;\nen el Valle, gran batalla\ny en los pueblos del Rincón;\nen esta villa de León,\nIrapuato, Salvatierra,\nla gente se desespera;\npor Monterrey y Saltillo\ntodito es un baratillo\nen la República entera.",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"ea",44,0,-1,0,360,360,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-10",8,"Por San Luis del Potosí,\nla hermosa Guadalajara,\nel toro a toditos para,\nlos de San Blas y Tepic;\nen el Real de Mapimí\nle tienen mucho recelo;\npor Durango dejó el pelo,\nen Oaxaca gran porción,\ndice hoy toda la nación:\n“Ya no tenemos consuelo.”",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"eo",10,0,-1,0,360,360,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-11",8,"Puebla, Córdoba y Huamantla,\nen Orizaba y Tepeaca,\nTacubaya, Tlalnepantla,\nSan Juan del Río y Huichapan,\nrancho ni hacienda se escapan;\nen el Real de Cardonal,\nIxmiquilpan, el Mezquital,\npor caminos y potreros,\ntumba muchos carreteros.\n¡Ah, qué toro tan puntal!",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"a",1,0,-1,0,360,360,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-12",8,"Embiste a los reboceros,\ntiendas y carnicerías,\nobradores, pulquerías,\nfábrica de cigarros;\ntoditos los zapateros\ncon las hormas se han tirado;\nlos canteros ha asustado,\nsastres y talabarteros,\nalbañiles, carpinteros,\na toditos ha arrastrado.",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"ao",14,0,-1,0,360,360,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-13",8,"A las pobres comideras\ny a las que venden verdura;\nentró con grande travesura\ncon toditas las fruteras;\nrevolcó a las cigarreras\ny a las que venden tortillas,\nya les salen amarillas;\nya no tienen nixtamal\ny dicen las pobrecitas:\n“Parece perro del mal.”",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"a",1,0,-1,0,361,361,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-14",8,"Ya nos deja sin camisa,\nnos quitó hasta los calzones,\nchaqueta ni pantalones,\nno podemos ir a misa;\na la pobre María Luisa\nel rebozo le ha rasgado,\ntoda la ha despilfarrado;\n¡quién lo pudiera agarrar!\nNos habíamos de vengar\nasegún nos ha arrastrado.",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"ao",14,0,-1,0,361,361,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-15",8,"Las hijas de Tía Quiteria,\ny también las del borlote,\ntoditas andan al trote\nporque están en la miseria,\ny nos dice Desideria,\nque viene de la frontera:\n“Yo morir ya me quisiera,\nporque andando en la misión\nhe oído en conversación:\nSeñores, ¡ah, qué arranquera!”",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"ea",44,0,-1,0,361,361,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-16",8,"En Morelia y Zimapán,\nZacatecas y Toluca,\nel Real del Monte y Pachuca,\nHuauchinango, Ozumatlán,\nCuemavaca, Apatzingán,\nel Estado de Guerrero\nanda el toro muy grosero,\nno los deja ni dormir\ny comienzan a decir:\n¡Cuánta escasez de dinero!",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"eo",38,0,-1,0,361,361,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-17",8,"Si todos los minerales\ntrabajara la nación,\ncesaría la apuración\nsacando muchos metales;\ntendrían pesos y reales,\nse acabaría la arranquera;\nal toro su mal le diera,\ntodos con gusto y contento,\nse nos quitaría el tormento\nen la República entera.",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"ea",44,0,-1,0,361,361,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap189-18",8,"No más a los extranjeros\nno les ha llegado el toro;\nrecogen la plata y oro\ny lo embarcan, muy ligeros,\nen buques de pasajeros,\ncon mucha seguridad;\ny hablándoles con verdad\nson los del mero comercio,\ny todos, en realidad,\nya no tenemos consuelo.",166,2,-1,188,"EL TORITO DEL COMERCIO",18,10,"eo",-1,0,-1,0,361,361,"Ap. 189","",0,"","","",1,0,0,[],""],["frenk_t4-ap190-01",8,"Señores, áhi va la bola,\nquién sabe a quién tumbará;\na que ninguna le da,\ncomo dijo tía Canchóla:\nhasta el martes se sabrá,",166,2,-1,188,"SEÑORES, AHI VA LA BOLA",7,5,"a",9,0,-1,0,361,361,"Ap. 190","",0,"","","",2,0,0,[],""],["frenk_t4-ap190-02",8,"Comenzaremos a hablar\nde todos los comerciantes:\nse acabó la papa de antes,\nya nadie le puede dar,\nni el que sabe trabajar,\nni el que día por día, enamora,\nhoy gime como cotorra\ny canta como chicharra;\n¡ah, qué suerte tan chaparra,\nque nadie le da a la bola!",166,2,-1,188,"SEÑORES, AHI VA LA BOLA",18,10,"oa",-1,0,-1,0,361,361,"Ap. 190","",0,"","","",1,0,0,[],""],["frenk_t4-ap190-03",8,"Un arriero muy tunante\ny un loquito misionero\ndesean, como el comerciante,\ntener hoy mucho dinero;\nya no vale ser arriero\nni andar con la tandariola,\ndice muy bien tía Canchola:\nque aunque uno sepa tirar,\nhoy sí se puede apostar\nque nadie le da a la bola.",166,2,-1,188,"SEÑORES, AHI VA LA BOLA",18,10,"oa",321,0,-1,0,361,361,"Ap. 190","",0,"","","",1,0,0,[],""],["frenk_t4-ap190-04",8,"Toditos los arrancados\nsueñan hoy con la arranquera,\nque los pesos bien sellados\ntuvieran de cabecera,\nhasta una carrera diera\nel flojo y el que enamora\ny los que cargan pistola\nya no saben ni tirar;\naunque sepan apuntar,\nninguno le da a la bola.",166,2,-1,188,"SEÑORES, AHI VA LA BOLA",18,10,"oa",321,0,-1,0,362,362,"Ap. 190","",0,"","","",1,0,0,[],""],["frenk_t4-ap190-05",8,"Todito el mundo se queja\nde la maldita arranquera;\nse queja una tortillera\nque salió su masa neja\npero que siempre la deja\npara teñirla con mora,\ncomo es una mujer sola\nno la pudo tortillar,\nvolvió a poner nixtamal\ny nunca le dio a la bola.",166,2,-1,188,"SEÑORES, AHI VA LA BOLA",18,10,"oa",321,0,-1,0,362,362,"Ap. 190","",0,"","","",1,0,0,[],""],["frenk_t4-ap190-06",8,"Puros quejidos se oirán\nen todita la pandilla,\nno vale ser gavilán\nni perico ni aguililla,\nsólo el oro es el que brilla\ny la plata como aurora,\nni los rebozos de bola\nrifarán para adelante,\nni vale ser estudiante;\nninguno le da a la bola.",166,2,-1,188,"SEÑORES, AHI VA LA BOLA",18,10,"oa",-1,0,-1,0,362,362,"Ap. 190","",0,"","","",1,0,0,[],""],["frenk_t4-ap190-07",8,"No vale ser artesano,\nlas artes están llorando\ny la ciencia suspirando;\nnadie les tiende la mano.\nAunque el pueblo es soberano,\nnada vale sin mamola\ncomo la casa que sola,\nsin quien la cuide, se cae,\nloco el hambre al pueblo trae\ny nadie le da a la bola.",166,2,-1,188,"SEÑORES, AHI VA LA BOLA",18,10,"oa",321,0,-1,0,362,362,"Ap. 190","",0,"","","",1,0,0,[],""],["frenk_t4-ap190-08",8,"Se queja Pancha y Ciriaca\ny tía Lola y tía Joaquina,\ndesde que no buscan plata,\nninguna come gallina.\nLo mismo tía Marcelina\nde que se acuerda hasta llora,\nquedó viuda, pobre, sola,\ny como quedó viejita,\nnadie le ofrece platita\ny nunca le da a la bola.",166,2,-1,188,"SEÑORES, AHI VA LA BOLA",18,10,"oa",321,0,-1,0,362,362,"Ap. 190","",0,"","","",1,0,0,[],""],["frenk_t4-ap193-01",8,"Sacaron a vender una escopeta\nsin cañón, sin culata y sin baqueta;\nla compró el padre Filiberto\npara matar los ratones del convento.",168,2,11,188,"LA ALMONEDA",3,4,"eo",-1,0,-1,0,364,364,"Ap. 193","",0,"","","",2,0,0,[],""],["frenk_t4-ap193-02",8,"Sacaron a vender luego una silla\nsin patas, sin respaldo y sin rejilla;\nla compró el padre Filiberto\npara sentar a las monjas del convento.",168,2,11,188,"LA ALMONEDA",3,4,"eo",-1,0,-1,0,364,364,"Ap. 193","",0,"","","",1,0,0,[],""],["frenk_t4-ap193-03",8,"Sacaron a vender una sardina\nsin carne, sin cola y sin espinas;\nla compró el padre Filiberto\npara los días de vigilia en el convento.",168,2,11,188,"LA ALMONEDA",3,4,"eo",-1,0,-1,0,364,364,"Ap. 193","",0,"","","",1,0,0,[],""],["frenk_t4-ap193-04",8,"Sacaron a vender unos calzones\nsin tela, sin pretina y sin botones;\nlos compró el padre Filiberto\npara los días de verano en el convento.",168,2,11,188,"LA ALMONEDA",3,4,"eo",-1,0,-1,0,364,364,"Ap. 193","",0,"","","",1,0,0,[],""],["frenk_t4-ap194-01",8,"Apunte usted, señor escribano,\nla pluma en la mano y apunte usted\nun testamento que voy a hacer\nde lo que dejo a mi mujer:",178,2,10,188,"EL TESTAMENTO",3,4,"e",20,0,-1,0,364,364,"Ap. 194","",0,"","","",1,0,0,[],""],["frenk_t4-ap195-01",8,"Me gusta que sea chiquita\nla reina de mi querer;\npara mí una chaparrita\nes mi tipo de querer.",166,2,-1,189,"LAS CHAPARRITAS",1,4,"e",-1,0,-1,0,365,365,"Ap. 195","",0,"","","",1,0,0,[],""],["frenk_t4-ap195-02",8,"Me gusta su figurita,\npero todo a proporción\ny toda que sea chiquita,\nmenos de su corazón.",166,2,-1,189,"LAS CHAPARRITAS",1,4,"o",31,0,-1,0,365,365,"Ap. 195","",0,"","","",1,0,0,[],""],["frenk_t4-ap195-03",8,"Nada le hace la estatura\npa poderla enamorar,\nchaparrita cuerpo de uva,\npues yo me puedo agachar.",166,2,-1,189,"LAS CHAPARRITAS",0,4,"a",21,0,-1,0,365,365,"Ap. 195","",0,"","","",1,0,0,[],""],["frenk_t4-ap195-04",8,"Que quepa en una maleta,\nsi la tengo que esconder,\ny si la crisis aprieta,\nfácil se ha de mantener.",166,2,-1,189,"LAS CHAPARRITAS",1,4,"e",20,0,-1,0,365,365,"Ap. 195","",0,"","","",1,0,0,[],""],["frenk_t4-ap195-05",8,"Además, si es chaparrita,\npara siempre me durará;\npues la yegua que es chiquita\npotrita siempre será.",166,2,-1,189,"LAS CHAPARRITAS",1,4,"a",9,0,-1,0,365,365,"Ap. 195","",0,"","","",1,0,0,[],""],["frenk_t4-ap195-07",8,"Las chaparras se me antojan\npor fácil de manejar;\ny si acaso se me enoja,\nno me alcanzaría a pegar.",166,2,-1,189,"LAS CHAPARRITAS",0,4,"a",21,0,-1,0,365,365,"Ap. 195","",0,"","","",1,0,0,[],""],["frenk_t4-ap195-08",8,"El perfume que se estima\npoquito se ha de poner,\nel chile para que pique,\nchiquitín tiene que ser.",166,2,-1,189,"LAS CHAPARRITAS",0,4,"e",20,0,-1,0,365,365,"Ap. 195","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap196-01",8,"Lo más bello es la mujer\nen nuestro querido suelo,\ny la que llega a tener\namor, sentimiento y celo,\ntodo debe merecer.",175,2,6,189,"LO MÁS BELLO ES LA MUJER",7,5,"e",20,0,-1,0,365,365,"Ap. 196","",0,"","","",1,0,0,[],""],["frenk_t4-ap196-02",8,"En nuestro querido suelo\nes el ser más preferido,\na la mujer bajo el cielo,\nporque ni el oro esculpido\nse quiere con tanto anhelo.",175,2,6,189,"LO MÁS BELLO ES LA MUJER",7,5,"eo",10,0,-1,0,365,365,"Ap. 196","",0,"","","",1,0,0,[],""],["frenk_t4-ap196-03",8,"Y la que llega a tener\namor, sentimiento y celo,\nes muy valiosa mujer;\nse ama como al casto cielo,\nsiendo digna de un laurel.",175,2,6,189,"LO MÁS BELLO ES LA MUJER",7,5,"e",-1,0,-1,0,365,365,"Ap. 196","",0,"","","",1,0,0,[],""],["frenk_t4-ap196-04",8,"Amor, sentimiento y celo\ndebe tener la mujer,\npara amarse con anhelo,\nporque si no, entra la hiel\nque nos trae el desconsuelo.",175,2,6,189,"LO MÁS BELLO ES LA MUJER",7,5,"eo",10,0,-1,0,366,366,"Ap. 196","",0,"","","",1,0,0,[],""],["frenk_t4-ap196-05",8,"Todo debe merecer\nla de sentimiento y celo;\ncuando es firme la mujer,\nel hogar es un consuelo,\nes un eterno placer.",175,2,6,189,"LO MÁS BELLO ES LA MUJER",7,5,"e",20,0,-1,0,366,366,"Ap. 196","",0,"","","",1,0,0,[],""],["frenk_t4-ap197-01",8,"Cuida bien de tu pureza,\nesa joya de valor,\ny a nadie des esa flor,\nmira que es una riqueza.",171,2,4,189,"CUIDA BIEN DE TU PUREZA",11,4,"ea",108,0,-1,0,366,366,"Ap. 197","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap197-02",8,"Te aconsejo humildemente\nque seas honesta y honrada,\npara que seas respetada\ny bien vista de la gente.\nYa que Dios Omnipotente\nte ha dotado de belleza,\nde hermosura y de nobleza,\nde delicias y virtudes,\nasí, con exactitudes,\ncuida bien de tu pureza.",171,2,4,189,"CUIDA BIEN DE TU PUREZA",18,10,"ea",108,0,-1,0,366,366,"Ap. 197","",0,"","","",1,0,0,[],""],["frenk_t4-ap197-03",8,"Te pidieron tal objeto\ntus amantes con halagos,\ncausándote mil estragos\nsi revelas el secreto;\nmira que hay mucho indiscreto\nen el mundo engañador,\nte ruego, hazlo por favor,\nno te dejes engañar,\ny a nadie debes de dar\nesa joya de valor.",171,2,4,189,"CUIDA BIEN DE TU PUREZA",18,10,"o",72,0,-1,0,366,366,"Ap. 197","",0,"","","",1,0,0,[],""],["frenk_t4-ap197-04",8,"¿Ves una flor deshojada,\nque nada llega a valer?,\nasimismo es la mujer,\ndejando de ser honrada.\nEs de todos despreciada\ncuando pierde lo mejor:\nla pureza y el color,\nno pensando en un segundo,\nmira bien lo que es el mundo,\ny a nadie des esa flor.",171,2,4,189,"CUIDA BIEN DE TU PUREZA",18,10,"o",72,0,-1,0,366,366,"Ap. 197","",0,"","","",1,0,0,[],""],["frenk_t4-ap197-05",8,"En fin, te digo, alma mía,\nque el honor es un tesoro,\nvale más que todo el oro,\ntestigo es la luz del día;\nsi mi consejo te guía\nconservarás tu pureza,\nporque la delicadeza\nengrandece la hermosura,\ncuida esa rosa tan pura,\nmira que es una riqueza.",171,2,4,189,"CUIDA BIEN DE TU PUREZA",18,10,"ea",108,0,-1,0,366,366,"Ap. 197","",0,"","","",1,0,0,[],""],["frenk_t4-ap198-01",8,"Casarse es tomar buen rumbo\ncon una mujer honrada,\nporque es una ley sagrada\ndesde que Dios hizo el mundo.",171,2,4,189,"CASARSE ES TOMAR BUEN RUMBO",5,4,"uo",-1,0,-1,0,366,366,"Ap. 198","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap198-02",8,"El casa; se es natural\ny no influye ni avergüenza,\nporque el hombre que lo piensa\nnadie se lo toma a mal.\nEs un mérito especial\nhasta para que haya el mundo,\ny en esto no me confundo\nporque dice el sacerdote\nque para que Dios nos dote,\ncasarse es tomar buen rumbo.",171,2,4,189,"CASARSE ES TOMAR BUEN RUMBO",18,10,"uo",-1,0,-1,0,366,366,"Ap. 198","",0,"","","",1,0,0,[],""],["frenk_t4-ap198-03",8,"El hombre que piensa bien\ny se quiere hacer valer,\ndebe de tener mujer,\njuicio y recato también;\npor la honra y el sostén\nhasta la vida es prestada,\nes cosa que al mundo agrada,\nmérito del porvenir,\nno hay más placer que vivir\ncon una mujer honrada.",171,2,4,189,"CASARSE ES TOMAR BUEN RUMBO",18,10,"aa",49,0,-1,0,367,367,"Ap. 198","",0,"","","",1,0,0,[],""],["frenk_t4-ap198-04",8,"El casarse es un deber\nnatural y tan preciso,\nque al hacer el compromiso\nse debe de sostener;\nla razón nos da a entender\nque a la edad determinada,\ndebe de ser desposada\nla mujer con el varón\ny vivir en buena unión,\nporque es una ley sagrada.",171,2,4,189,"CASARSE ES TOMAR BUEN RUMBO",18,10,"aa",49,0,-1,0,367,367,"Ap. 198","",0,"","","",1,0,0,[],""],["frenk_t4-ap198-06",8,"En fin, esto manda Dios\ny claro en la cuenta sale,\nque una persona no vale\nlo que pueden valer dos,\ny lo digo en alta voz,\ny en la razón me confundo,\nque es lo primero y segundo,\ny también es reglamento,\ny es un Santo Mandamiento\ndesde que Dios hizo el mundo.",171,2,4,189,"CASARSE ES TOMAR BUEN RUMBO",18,10,"uo",179,0,-1,0,367,367,"Ap. 198","",0,"","","",1,0,0,[],""],["frenk_t4-ap201-01",8,"Escucha, joven hermosa,\ndueña de mis alegrías,\nte pretendo para esposa\npa vivir años y días.",171,2,4,189,"ESCUCHA, JOVEN HERMOSA",1,4,"ia",214,0,-1,0,369,369,"Ap. 201","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap201-02",8,"Te trato de casamiento\ny ya mi amor te ofrecí,\nsi tú me quieres a mí\nse me cumplirá mi intento.\nAl pie de un verde pimiento\ndonde mi amor se reposa,\nuna mañana frondosa\nvide la aurora brillante\ny oí la voz de tu amante:\nEscucha, joven hermosa.",171,2,4,189,"ESCUCHA, JOVEN HERMOSA",18,10,"oa",63,0,-1,0,369,369,"Ap. 201","",0,"","","",1,0,0,[],""],["frenk_t4-ap201-03",8,"No te puedo comparar\nadónde llego a quererte,\ny el día que dejo de verte\ntodo se me va en llorar;\nconsuelo no puedo hallar\nnoches, semanas y días;\ntodas las cuestiones mías\nse reducen a pasión,\njoven de mi corazón,\ndueña de mis alegrías.",171,2,4,189,"ESCUCHA, JOVEN HERMOSA",18,10,"ia",214,0,-1,0,369,369,"Ap. 201","",0,"","","",1,0,0,[],""],["frenk_t4-ap201-04",8,"Cuando mi mano recibas\ny me tengas a tu lado,\nme tendrás a tu mandado\nalma, corazón y vida;\noye, joven de mi vida,\nmi corazón se destroza,\nsiendo tú la más hermosa\nentre todas las mujeres,\nsi tú de veras me quieres,\nte pretendo para esposa.",171,2,4,189,"ESCUCHA, JOVEN HERMOSA",18,10,"oa",63,0,-1,0,369,369,"Ap. 201","",0,"","","",1,0,0,[],""],["frenk_t4-ap201-05",8,"En fin, le pido a mi Dios\nque me conceda mi intento,\nque te dé convencimiento\npara juntamos los dos;\nen mi pena tan atroz\npara mí no hay alegría,\nhe de seguir mi porfía,\nporque a mí nada me pasa,\nte he de llevar a mi casa\na vivir noches y días.",171,2,4,189,"ESCUCHA, JOVEN HERMOSA",18,10,"ia",-1,0,-1,0,369,369,"Ap. 201","",0,"","","",1,0,0,[],""],["frenk_t4-ap202-01",8,"Si es que usted me quiere a mí,\ncontésteme este papel\nque con mi mano escribí,\npara que se imponga de él.",171,2,4,189,"SI ES QUE USTED ME QUIERE",1,4,"e",32,0,-1,0,369,369,"Ap. 202","",0,"","","",1,0,0,[],""],["frenk_t4-ap202-02",8,"Le suplico que se fije\nen estos cuantos renglones:\nno son letras, son borrones\nque este joven le dirige\nporque el corazón me exige\nsaber el no o el sí,\nen mis letras que escribí,\ncon las cuales yo le digo:\nA amarle hoy me obligo\nsi es que usted me quiere a mí.",171,2,4,189,"SI ES QUE USTED ME QUIERE",18,10,"i",23,0,-1,0,369,369,"Ap. 202","",0,"","","",1,0,0,[],""],["frenk_t4-ap202-03",8,"Perdóneme por ahora\nque tuve el atrevimiento\nde declararle mi intento:\nque mi corazón la adora.\nNo estoy tranquilo una hora,\npensando en su bello ser;\ny si por otro placer\nde mí no hace usté intención,\njoven, por su educación,\ncontésteme este papel.",171,2,4,189,"SI ES QUE USTED ME QUIERE",18,10,"e",-1,0,-1,0,369,369,"Ap. 202","",0,"","","",1,0,0,[],""],["frenk_t4-ap202-04",8,"Señorita, bien comprendo\nque no merezco su amor,\npor pobre o por mi color\nconsidero que la ofendo;\npero yo qué culpa tengo\nal quererla tanto así,\nsi desde el día en que la vi\nen usted vivo pensando.\nEsta décima le mando\nque con mi mano escribí.",171,2,4,189,"SI ES QUE USTED ME QUIERE",18,10,"i",23,0,-1,0,369,369,"Ap. 202","",0,"","","",2,0,0,[],""],["frenk_t4-ap202-05",8,"Oiga usté, encamada rosa,\nsólo me puse a escribir\npara poderle decir:\npretendo que sea mi esposa.\nConteste, joven hermosa,\nsi me ha de corresponder,\ny así que acabe de leer\nlo que le suplico a usted,\ny por eso lo mandé\npara que se imponga de él.",171,2,4,189,"SI ES QUE USTED ME QUIERE",18,10,"e",-1,0,-1,0,370,370,"Ap. 202","",0,"","","",1,0,0,[],""],["frenk_t4-ap203-01",8,"Pretendo que seas mi esposa\npor medio del Sacramento,\ny con padrinos honrados\nnos dirijamos al templo.",166,2,-1,189,"PRETENDO QUE SEAS MI ESPOSA",0,4,"eo",-1,0,-1,0,370,370,"Ap. 203","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap203-02",8,"Luego que tus ojos vi,\nal punto me apasioné,\ntoda mi alma te entregué\ny el corazón te rendí.\nResponde, mi bien, que sí\na mi pretensión dichosa,\nsea la muerte venturosa\nsi el cielo lo determina,\npues eres modesta y fina,\npretendo que seas mi esposa.",166,2,-1,189,"PRETENDO QUE SEAS MI ESPOSA",18,10,"oa",63,0,-1,0,370,370,"Ap. 203","",0,"","","",1,0,0,[],""],["frenk_t4-ap203-03",8,"Libre de ásperos abrojos\na Dios pretendo servir,\ny espero hemos de vivir\nsin lágrimas en los ojos.\nLejos amargos enojos\nresolverás con contento,\npara gozar en aumento\ndichas sin comparación,\ny la paz y salvación\npor medio del Sacramento.",166,2,-1,189,"PRETENDO QUE SEAS MI ESPOSA",18,10,"eo",94,0,-1,0,370,370,"Ap. 203","",0,"","","",1,0,0,[],""],["frenk_t4-ap203-04",8,"Sola tú eres la escogida\npara esposa y compañera,\nde mi amor la tesonera,\nsin que nadie me lo impida.\nDale a mi intento acogida\ny seremos presentados,\nen seguida amonestados\npara podemos casar,\nllegaremos al altar,\ny con padrinos honrados.",166,2,-1,189,"PRETENDO QUE SEAS MI ESPOSA",18,10,"ao",18,0,-1,0,370,370,"Ap. 203","",0,"","","",1,0,0,[],""],["frenk_t4-ap203-05",8,"Oirás antes de las bodas\ngorjear pájaros jilgueros,\ntambién sonoros salterios,\narpas y flautas de modas.\nLlegarán las niñas todas,\nsegún ahora me contemplo,\nllenas de virtud y ejemplo,\ncon gozo y con alegría,\npara que en compañía\nnos dirijamos al templo.",166,2,-1,189,"PRETENDO QUE SEAS MI ESPOSA",18,10,"eo",376,0,-1,0,370,370,"Ap. 203","",0,"","","",1,0,0,[],""],["frenk_t4-ap204-01",8,"Ahi te mando estos versitos,\nprocúralos aprender,\npara que me los enseñes\nel día que te venga a ver.",166,2,-1,189,"NUEVAS DÉCIMAS DE UNA CARTA DE PRETENSIÓN",0,4,"e",20,0,-1,0,370,370,"Ap. 204","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap204-02",8,"Lejos de ti, prenda amada,\ndeterminé en este día\nescribirte, vida mía,\nesta carta será rara,\ndonde mi amor se declara\npensando al ver tus ojitos;\nno digas que son poquitos\nlos cariños de mi esmero;\npara que veas que te quiero,\náhi te mando estos versitos.",166,2,-1,189,"NUEVAS DÉCIMAS DE UNA CARTA DE PRETENSIÓN",18,10,"io",254,0,-1,0,370,370,"Ap. 204","",0,"","","",1,0,0,[],""],["frenk_t4-ap204-03",8,"Quisiera personalmente\nel llevártelos yo a ti;\npero no puedo ¡ay de mí!,\nel rigor me tiene ausente;\npero si eres permanente,\ndía con día los has de leer,\nno los vayas a perder\ny te muestres inconstante,\nmira que son de tu amante,\nprocúralos aprender.",166,2,-1,189,"NUEVAS DÉCIMAS DE UNA CARTA DE PRETENSIÓN",18,10,"e",20,0,-1,0,371,371,"Ap. 204","",0,"","","",1,0,0,[],""],["frenk_t4-ap204-04",8,"Si Dios me presta la vida\ny son finos tus amores,\nte mandaré otros mejores,\ndulce prenda de mi vida;\npero si eres advertida\ny en aprenderlos te empeñes,\npueda ser que hasta los sueñes,\nesto es si no te acobardas;\napréndelos y los guardas\npara que me los enseñes.",166,2,-1,189,"NUEVAS DÉCIMAS DE UNA CARTA DE PRETENSIÓN",18,10,"ee",650,0,-1,0,371,371,"Ap. 204","",0,"","","",3,0,0,[],""],["frenk_t4-ap204-06",8,"No te pido otro favor\nporque otro será imposible,\nsólo éste, por ser posible,\ny no te daré dolor;\ndime, no será mejor\nmemorias de mí tener;\npero si me has de querer\ncon arreglo, cielo amado,\ntu amor será bien pagado\nel día que te venga a ver.",166,2,-1,189,"NUEVAS DÉCIMAS DE UNA CARTA DE PRETENSIÓN",18,10,"e",20,0,-1,0,371,371,"Ap. 204","",0,"","","",1,0,0,[],""],["frenk_t4-ap205-01",8,"Cómpreme este corazón,\nse lo doy de conveniencia,\nque sabe lo que es dolor\ny está hecho a tener paciencia.",166,2,-1,189,"DE PRIMERA PRETENSIÓN",0,4,"ea",46,0,-1,0,371,371,"Ap. 205","",0,"frenk_t2","","",3,0,0,[],""],["frenk_t4-ap205-02",8,"Se juega, se fía o se empeña,\nyo de cualquier modo trato,\ny a usted se lo doy barato,\nsi usted quiere ser su dueña;\noiga, que le hablo, trigueña,\nescúcheme mi razón,\nprésteme usted su atención,\nque la honra es de quien la da;\nóigame y después se irá,\n¡Cómpreme este corazón!",166,2,-1,189,"DE PRIMERA PRETENSIÓN",18,10,"o",31,0,-1,0,371,371,"Ap. 205","",0,"","","",1,0,0,[],""],["frenk_t4-ap205-03",8,"Si tratamos, señorita,\nde esa su persona noble,\npor ser corazón de un pobre\nlo doy en cualquier cosita,\ny si su amor solicita,\nrespóndame con violencia,\nhable, no tenga vergüenza,\nni piense usted que la engaño;\npor ser corazón extraño,\nse lo doy de conveniencia.",166,2,-1,189,"DE PRIMERA PRETENSIÓN",18,10,"ea",-1,0,-1,0,371,371,"Ap. 205","",0,"","","",1,0,0,[],""],["frenk_t4-ap205-05",8,"Querer una no es ninguna,\nquerer dos es necedad,\nquerer unas cuatro o cinco\nes gracia y habilidad.",166,2,-1,189,"DE PRIMERA PRETENSIÓN",0,4,"a",16,0,-1,0,371,371,"Ap. 205","",0,"frenk_t2","","",7,0,0,[],""],["frenk_t4-ap205-06",8,"Yo no vine a regatear,\nyo lo que quiero es vender;\nyo con usted he de tratar\ny se ha de quedar con él;\nsi no lo ha de menester\nporque tenga otro mejor,\nes un manso corazón,\nno piense se le ha de ir,\nque él mismo le ha de decir\nque sabe lo que es dolor.",166,2,-1,189,"DE PRIMERA PRETENSIÓN",18,10,"o",-1,0,-1,0,371,371,"Ap. 205","",0,"","","",1,0,0,[],""],["frenk_t4-ap205-07",8,"Usted nada me ha ofrecido,\naunque sea una sinrazón;\npensará usted en su interior\nque es corazón mal habido;\nusted no me ha conocido\nni de mí tenga experiencia;\nyo le daré conociencia\nporque no soy de la tierra,\nque si no, yo le dijera\nque está hecho a tener paciencia.",166,2,-1,189,"DE PRIMERA PRETENSIÓN",18,10,"ea",-1,0,-1,0,371,371,"Ap. 205","",0,"","","",1,0,0,[],""],["frenk_t4-ap206-01",8,"Yo por Loreto me muero,\ny tras de Loreto me ando,\ny aunque no le hablo, la quiero,\nmas que ella me quiera — ¡cuándo!",166,2,-1,189,"YO POR LORETO ME MUERO",1,4,"ao",33,0,-1,0,372,372,"Ap. 206","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap206-02",8,"Todo el día la veo pasar\npor enfrente de mi casa,\ntodos me dicen que pasa\nal baño para lavar;\nyo la quisiera ayudar,\npor no parecer grosero,\nmas el hablarle es primero,\ny no me sé resolver;\nen verdad, no sé qué hacer,\nyo por Loreto me muero.",166,2,-1,189,"YO POR LORETO ME MUERO",18,10,"eo",38,0,-1,0,372,372,"Ap. 206","",0,"","","",1,0,0,[],""],["frenk_t4-ap206-03",8,"Cuando a mí venir la veo\ncon su carita de rosa,\nme pasa no sé qué cosa,\nme estremezco, me mareo,\ny luego con su meneo,\ncon su mirar dulce, blando,\nva mi pecho palpitando\ncon tal precipitación\nque tomo respiración\ny tras de Loreto me ando.",166,2,-1,189,"YO POR LORETO ME MUERO",18,10,"ao",33,0,-1,0,372,372,"Ap. 206","",0,"","","",1,0,0,[],""],["frenk_t4-ap206-04",8,"Es en extremo hechicera,\ntodo me seduce de ella,\ntan fresca la veo y tan bella\ncual la flor de la pradera;\nflexible es cual la palmera,\nsu andar suave, aunque ligero;\nen su rostro placentero\nla felicidad rebosa,\nmi alma con mirarla, goza\ny aunque no le hablo, la quiero.",166,2,-1,189,"YO POR LORETO ME MUERO",18,10,"eo",38,0,-1,0,372,372,"Ap. 206","",0,"","","",1,0,0,[],""],["frenk_t4-ap206-05",8,"Si ella comprender pudiera\nlo que por ella he sufrido,\nsu corazón conmovido\na mi amor correspondiera;\nmas esto es una quimera,\nestoy despierto soñando\ny por ella suspirando;\nveré mi vida pasar:\nyo mucho la sabré amar,\nmas que ella me quiera — ¿cuándo?",166,2,-1,189,"YO POR LORETO ME MUERO",18,10,"ao",33,0,-1,0,372,372,"Ap. 206","",0,"","","",1,0,0,[],""],["frenk_t4-ap207-01",8,"Morena del alma mía,\nsal un momento a tu balcón;\nel alma por ti suspira,\npor ti delira mi corazón.",166,2,-1,189,"MORENA DEL ALMA MÍA",3,4,"o",31,0,-1,0,372,372,"Ap. 207","",0,"","","",1,0,0,[],""],["frenk_t4-ap207-02",8,"Yo te amo con amor ardiente;\nsi comprendieras lo que es amor,\nesquiva no te mostraras\nni despreciarías mi corazón.",166,2,-1,189,"MORENA DEL ALMA MÍA",3,4,"o",-1,0,-1,0,372,372,"Ap. 207","",0,"","","",1,0,0,[],""],["frenk_t4-ap209-03",8,"Eres tú la más pulida\ny de la nación coronada,\neres del viento realzada;\ntu imagen da nueva vida\ny te verás revestida\nen el trono de la amada;\nen todo eres muy cabal,\nde mi amor tienes la llave,\ncomo reina de las, aves,\nel águila imperial.",171,2,4,189,"ERES TÚ LA MÁS PULIDA",18,10,"a",1,0,-1,0,373,373,"Ap. 209","",0,"","","",1,0,0,[],""],["frenk_t4-ap209-06",8,"El jilguero y ruiseñor,\nal compás de su instrumento,\nquiso formar en el viento\nla música superior;\ncomo reina en el amor\ndice: “La mayor soy yo”;\nluego que se retrató,\nse metió en una redoma\ny dice: “Soy la paloma\nque en el tunal se sentó.”",171,2,4,189,"ERES TÚ LA MÁS PULIDA",18,10,"o",2,0,-1,0,373,373,"Ap. 209","",0,"","","",1,0,0,[],""],["frenk_t4-ap209-07",8,"Dame tu retrato, guapa,\nen diminuto botón,\npara usarlo en la solapa\nal lado del corazón;\ndámelo, no seas ingrata.",171,2,4,189,"ERES TÚ LA MÁS PULIDA",7,5,"aa",-1,0,-1,0,373,373,"Ap. 209","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap209-08",8,"Quiero a tu efigie sagrada\nllevarla constantemente\nsobre mi alma enamorada,\nsobre el corazón que siente,\nsobre el pecho, prenda amada.",171,2,4,189,"ERES TÚ LA MÁS PULIDA",7,5,"aa",49,0,-1,0,373,373,"Ap. 209","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap209-11",8,"Pues toda la vida canto\ny profano tu decoro.\nDios guarda los campos de oro\nen donde puso su planta;\ncomo reina en el encanto\ntú te has llevado la palma,\ny te vas como la malva\npremiada de la fortuna,\ncomo hermana de la luna,\neres más linda que el alba.",171,2,4,189,"ERES TÚ LA MÁS PULIDA",18,10,"aa",651,0,-1,0,373,373,"Ap. 209","",0,"","","",1,0,0,[],""],["frenk_t4-ap211-01",8,"Mujer, abre tu ventana\npara que escuches mi voz,\nque está cantando el que te ama\ncon el permiso de Dios.",166,2,-1,189,"SERENATA TAPATÍA",0,4,"o",87,0,-1,0,374,374,"Ap. 211","",0,"","","",1,0,0,[],""],["frenk_t4-ap211-02",8,"Aunque la noche está oscura\ny aquí no hay ninguna luz,\ncon tu divina hermosura\nla iluminas toda tú.",166,2,-1,189,"SERENATA TAPATÍA",3,4,"u",-1,0,-1,0,374,374,"Ap. 211","",0,"","","",1,0,0,[],""],["frenk_t4-ap211-03",8,"Yo te juro que ni el sol,\nla luna ni las estrellas,\njuntitas toditas ellas\nla iluminan como tú.",166,2,-1,189,"SERENATA TAPATÍA",5,4,"u",-1,0,-1,0,374,374,"Ap. 211","",0,"","","",1,0,0,[],""],["frenk_t4-ap211-04",8,"Tú iluminaste mi vida;\npor eso, mujer querida\nte canto esta noche azul,\npor eso vengo a robarte\nun rayito de tu luz.",166,2,-1,189,"SERENATA TAPATÍA",7,5,"u",-1,0,-1,0,374,374,"Ap. 211","",0,"","","",1,0,0,[],""],["frenk_t4-ap212-01",8,"Quisiera verte y no verte,\nquisiera hablarte y no hablarte,\nquisiera darte la muerte\ny la vida no quitarte.",171,2,4,189,"QUISIERA VERTE Y NO VERTE",1,4,"ae",8,0,-1,0,374,374,"Ap. 212","",0,"frenk_t2","","",12,0,0,[],""],["frenk_t4-ap212-02",8,"Por el mal comportamiento\nque tú conmigo has tenido,\nquisiera echarte en olvido;\npero ¡ay, no!, que me arrepiento;\nsi fuiste mi pensamiento\ndesde antes de conocerte,\npero hoy, por mi mala suerte,\na mí tu amor me ha ofendido,\ny yo por este motivo\nquisiera verte y no verte.",171,2,4,189,"QUISIERA VERTE Y NO VERTE",18,10,"ee",134,0,-1,0,374,374,"Ap. 212","",0,"","","",1,0,0,[],""],["frenk_t4-ap212-03",8,"Quisiera que un cruel castigo\na ti te enviara el Creador,\no el más punzante dolor\npor lo que has hecho conmigo;\npero ¡ay, no!, ¡qué es lo que digo!,\nmejor será el perdonarte,\nen un trono colocarte\nsiquiera por un momeftto,\npero hoy, por un sentimiento,\nquisiera hablarte y no hablarte.",171,2,4,189,"QUISIERA VERTE Y NO VERTE",18,10,"ae",8,0,-1,0,374,374,"Ap. 212","",0,"","","",1,0,0,[],""],["frenk_t4-ap212-04",8,"Por las muchas amenazas\nque has echado dondequiera,\nme alegraría que una fiera\nde ti hiciera mil pedazos;\npero ¡ay, no!, si yo en tus brazos,\nmuy dichosa fue mi suerte,\ny el día que dejo de verte\nun rato no hallo consuelo;\npero hoy, por un fuerte celo,\nquisiera darte la muerte.",171,2,4,189,"QUISIERA VERTE Y NO VERTE",18,10,"ee",134,0,-1,0,374,374,"Ap. 212","",0,"","","",1,0,0,[],""],["frenk_t4-ap212-05",8,"Quisiera verte tendida,\nque te estuvieran velando,\ny a tu familia llorando\npor ver a tu alma perdida;\npero ¡ay, no!, prenda querida,\npara qué es un mal desearte,\nsi sólo quiero explicarte\nque mi corazón es bueno;\nquisiera darte veneno\ny la vida no quitarte.",171,2,4,189,"QUISIERA VERTE Y NO VERTE",18,10,"ae",8,0,-1,0,374,374,"Ap. 212","",0,"","","",1,0,0,[],""],["frenk_t4-ap214-01",8,"Lloro por mi bien perdido,\nlloro sin saber por qué;\nno lloro porque se fue,\nlloro porque no ha venido.",175,2,6,189,"LLORO POR MÏ BIEN PERDIDO",11,4,"io",101,0,-1,0,375,375,"Ap. 214","",0,"","","",1,0,0,[],""],["frenk_t4-ap214-02",8,"Lloro por la vida mía\nque ausente está de mi lado,\nsi no se fuera ausentado,\nsin duda no lloraría;\nlloro desde el propio día\nen que ha desaparecido;\nel corazón tengo herido\nde tristeza y de pesar;\npor Dios, déjenme llorar,\nlloro por mi bien perdido.",175,2,6,189,"LLORO POR MÏ BIEN PERDIDO",18,10,"io",101,0,-1,0,375,375,"Ap. 214","",0,"","","",1,0,0,[],""],["frenk_t4-ap214-03",8,"Me preguntan por qué lloro,\ncada que escuchan mi llanto;\nyo digo que lloro tanto\npor una joven que adoro;\nlloro por ese tesoro\nque a mí llorar no me ve;\n¿en dónde la encontraré?\nConsuelo no puedo hallar,\ndejen mis ojos llorar,\nlloro sin saber por qué.",175,2,6,189,"LLORO POR MÏ BIEN PERDIDO",18,10,"e",77,0,-1,0,375,375,"Ap. 214","",0,"","","",1,0,0,[],""],["frenk_t4-ap214-04",8,"Mis ojos se han convertido\nen lágrimas y sollozos,\ncada vez ‘stán más llorosos,\nconsuelo no han conseguido,\nconsolarlos no he podido,\nque lloren los dejaré;\npor esa joven que amé\nsollozo, lloro y suspiro;\nlloro porque no la miro,\nno lloro porque se fue.",175,2,6,189,"LLORO POR MÏ BIEN PERDIDO",18,10,"e",77,0,-1,0,376,376,"Ap. 214","",0,"","","",1,0,0,[],""],["frenk_t4-ap214-05",8,"Por un amor verdadero\nque de mi lado está ausente,\nhe llorado amargamente\nno más por ese lucero;\nsi lloro es porque la quiero\ncon un amor muy crecido,\npor ella estoy afligido\nllorando de noche y día;\nlloro por la vida mía,\nlloro porque no ha venido.",175,2,6,189,"LLORO POR MÏ BIEN PERDIDO",18,10,"io",101,0,-1,0,376,376,"Ap. 214","",0,"","","",1,0,0,[],""],["frenk_t4-ap215-01",8,"Elegí para mi esposa\na otra de mejor placer;\nsi quieres, irás de moza\nde otra que voy a tener.",171,2,4,189,"ELEGÍ PARA MI ESPOSA",1,4,"e",20,0,-1,0,376,376,"Ap. 215","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap215-02",8,"Te diré mis intenciones:\ncuando mi amor ya no exista,\nporque ya tengo otra vista\nde mejores proporciones,\na ver qué pero le pones,\nporque no es nada orgullosa,\nes blanca mi mariposa\ny muy bonita también;\npero no te digo a quién\nelegí para mi esposa.",171,2,4,189,"ELEGÍ PARA MI ESPOSA",18,10,"oa",63,0,-1,0,376,376,"Ap. 215","",0,"","","",1,0,0,[],""],["frenk_t4-ap215-03",8,"Ya tengo otra de mi agrado,\nque en todo me satisface,\ny cuando sea nuestro enlace,\nle vas a poner cuidado;\nmi amor en ti habría inclinado\ncreyendo permanecer;\nno lo has de pasar a creer,\ndirás que me estoy chanceando;\npero ya tengo a mi modo\notra de mejor placer.",171,2,4,189,"ELEGÍ PARA MI ESPOSA",18,10,"e",20,0,-1,0,376,376,"Ap. 215","",0,"","","",1,0,0,[],""],["frenk_t4-ap215-04",8,"La que tengo conseguida\nes de buenas cualidades;\nno trata con falsedades\nni se hace la merecida;\nsi no te das por sentida,\ntrataremos de otra cosa.\nPuedes ir con mi esposa,\nque es mujer muy halagüeña,\npero no irás como dueña,\nsi quieres, irás de moza.",171,2,4,189,"ELEGÍ PARA MI ESPOSA",18,10,"oa",195,0,-1,0,376,376,"Ap. 215","",0,"","","",1,0,0,[],""],["frenk_t4-ap215-05",8,"En fin, para no cansarte\nte diré en pocas razones:\nque busques, entre varones,\notro, si quieres casarte.\nYo ya desistí de amarte;\nya no te he de querer,\nsólo te quiero hacer ver\nque la que amo no es ingrata,\npuedes irte, pues, de gata\nde otra que voy a tener.",171,2,4,189,"ELEGÍ PARA MI ESPOSA",18,10,"e",20,0,-1,0,376,376,"Ap. 215","",0,"","","",1,0,0,[],""],["frenk_t4-ap216-01",8,"¡Qué poco del mundo sabe\nquien de una mujer se fía,\nsabiendo que es alcancía\nde que todos cargan llave!",176,2,3,189,"IQUÉ POCO DEL MUNDO SABE!",11,4,"ae",69,0,-1,0,376,376,"Ap. 216","",0,"","","",2,0,0,[],""],["frenk_t4-ap216-02",8,"Si alguna llegase a haber\nde recato y fundamento,\nsuele haber una entre ciento,\npues que no hay buena mujer;\nlealtad no saben tener,\nni en ellas decoro cabe;\nninguno a su dama alabe,\nporque todo aquel que piensa\nque en la mujer no hay ofensa,\n¡qué poco del mundo sabe!",176,2,3,189,"IQUÉ POCO DEL MUNDO SABE!",18,10,"ae",131,0,-1,0,377,377,"Ap. 216","",0,"","","",1,0,0,[],""],["frenk_t4-ap216-03",8,"Bersabé se vio estimada\ny a Urías pagó mal su fe,\notra como Bersabé,\npues que no hay mujer honrada;\nsi en la que fue bien tratada\nse encuentra tal’evosía\n¿cómo en éstas de hoy en día\npodrá estar uno seguro?\nSe pasa de confianzudo\nquien de una mujer se fía.",176,2,3,189,"IQUÉ POCO DEL MUNDO SABE!",18,10,"ia",0,0,-1,0,377,377,"Ap. 216","",0,"","","",1,0,0,[],""],["frenk_t4-ap216-04",8,"Sólo el sabio Salomón,\nen medio de sus placeres,\npodría darme una instrucción\ndel amor de las mujeres;\nhombre, si librarte quieres\nde tan cierta picardía,\npiensa de noche y de día,\npuesto con tal desenfado,\nque cualquiera pierde el grado,\nsabiendo que es alcancía.",176,2,3,189,"IQUÉ POCO DEL MUNDO SABE!",18,10,"ia",0,0,-1,0,377,377,"Ap. 216","",0,"","","",1,0,0,[],""],["frenk_t4-ap216-05",8,"En fin, para no cansar\nni hacer largo el argumento,\ntodo hombre de pensamiento\nno se debería casar;\nque poniéndose a pensar,\ndebe de vivir alerta,\nsi algo desea de la huerta,\nde esa fruta dulce y suave,\nno puede celar la puerta\nde que todos cargan llave.",176,2,3,189,"IQUÉ POCO DEL MUNDO SABE!",18,10,"ae",69,0,-1,0,377,377,"Ap. 216","",0,"","","",1,0,0,[],""],["frenk_t4-ap217-01",8,"Buen tonto es el que se casa,\nsi quiere tener mujer,\nque busca ama a quien servir\ny floja a quien mantener.",166,2,-1,189,"LOS CONSEJOS DE UN SOLTERO",0,4,"e",20,0,-1,0,377,377,"Ap. 217","",0,"","","",2,0,0,[],""],["frenk_t4-ap217-02",8,"Sin ninguna dilación,\nlo necesario ha de dar,\nporque aunque vaya a robar,\nha de dar la mantención.\n¿Habrá mayor sinrazón\ncomo la que un hombre pasa\nel gasto, comida y casa\ny todos los días un diario\nde apetitos y vestuario?\n¡Buen tonto es el que se casa!",166,2,-1,189,"LOS CONSEJOS DE UN SOLTERO",18,10,"aa",-1,0,-1,0,377,377,"Ap. 217","",0,"","","",1,0,0,[],""],["frenk_t4-ap217-03",8,"¡Qué vida pasa el soltero,\nestando de holgorios harto,\nque sin llegársele el parto\nde la mujer ni el casero,\nse pasea muy placentero\nexento de padecer;\nun casado ha de tener\naquí estas disposiciones:\nhacerse de obligaciones\nsi quiere tener mujer.",166,2,-1,189,"LOS CONSEJOS DE UN SOLTERO",18,10,"e",20,0,-1,0,377,377,"Ap. 217","",0,"","","",1,0,0,[],""],["frenk_t4-ap217-04",8,"Con semblante muy extraño\nle dice la mujercita:\n“Compóngase usted, tatita,\nno tengo enaguas, ni paño;\nyo no te busqué este daño,\nal juez le voy a decir\nque usted no sabe cumplir\ncon su obligación muy pronto”;\nEso merece el que es tonto,\nque busca ama a quien servir.",166,2,-1,189,"LOS CONSEJOS DE UN SOLTERO",18,10,"i",157,0,-1,0,377,377,"Ap. 217","",0,"","","",1,0,0,[],""],["frenk_t4-ap217-05",8,"En fin, ¡qué bien hago yo\nque no pretendo mujer!\nQue las vaya a mantener\nSan Isidro que sembró;\nya vuelvo a decir que no,\nnunca casado he de ser;\nporque no quiero tener\nde día y de noche testigo,\nni cruelísimo enemigo\nni floja a quien mantener.",166,2,-1,189,"LOS CONSEJOS DE UN SOLTERO",18,10,"e",20,0,-1,0,377,377,"Ap. 217","",0,"","","",1,0,0,[],""],["frenk_t4-ap220-02",8,"¡Ay! La noche que nos juntamos\nno me dejó dormir:\n¡ay, qué de abrazos nos dimos,\nbesitos de mil a mil!\nCuando yo me quise ir,\n¡ay!, me dice: “Quédate en paz”;\nme dice: “¿Por qué te vas?,\n¡ay!, todavía es de madrugada,\nquiero tenerte abrazado\notro ratito no más.”",176,2,3,190,"OTRO RATITO NO MÁS",18,10,"a",51,0,-1,0,379,379,"Ap. 220","",0,"","","",1,0,0,[],""],["frenk_t4-ap220-03",8,"¡Ay! Estaba tan alto el sol,\ny yo, arrullado en sus brazos;\n¡ay!, me decía con mucho amor:\n“Parece que siento pasos.”\n¡Qué tiroteo y qué balazos!,\n¡ay!, de puros besos no más.\n“Mi alma, si a disgusto estás,\n¡ay!, voltéate pa el otro lado:\nquiero tenerte abrazado\notro ratito no más.”",176,2,3,190,"OTRO RATITO NO MÁS",18,10,"a",51,0,-1,0,379,379,"Ap. 220","",0,"","","",1,0,0,[],""],["frenk_t4-ap220-04",8,"¡Ay! Era de mañanita,\nyo ya andaba levantado,\n¡ay!, yo ya andaba levantado\ny también la pobrecita.\nFue y me dio una mordidita\n¡ay!, le dije: “Muérdeme más;\n¿quién sabe si tú quedrás?”\n¡Ay!, me respondió con voces tiernas:\n“Quiero tenerte en mis piernas\notro ratito no más”.",176,2,3,190,"OTRO RATITO NO MÁS",18,10,"a",51,0,-1,0,379,379,"Ap. 220","",0,"","","",1,0,0,[],""],["frenk_t4-ap220-05",8,"¡Ay! Despedida no les doy\nporque a mí no me conviene,\n¡ay!, porque en este conjunto de arpa\nlo que uno granjea, eso tiene.",176,2,3,190,"OTRO RATITO NO MÁS",3,4,"ee",70,0,-1,0,379,379,"Ap. 220","",0,"","","",3,0,0,[],""],["frenk_t4-ap221-01",8,"Y abajo del puente,\npuente que le llaman,\nmis ojos quisieran\nver correr el agua.",171,2,4,190,"el coco",0,4,"aa",-1,0,-1,0,380,380,"Ap. 221","",0,"","","",1,0,0,[],""],["frenk_t4-ap221-02",8,"Y extendí la vista\npara mejor ver,\ny abajo del puente\nyo vi a una mujer.",171,2,4,190,"el coco",0,4,"e",20,0,-1,0,380,380,"Ap. 221","",0,"","","",1,0,0,[],""],["frenk_t4-ap221-03",8,"Me quedé elevado,\nviéndola bañar,\nparecía sirena\nnadando en el mar.",171,2,4,190,"el coco",0,4,"a",21,0,-1,0,380,380,"Ap. 221","",0,"","","",1,0,0,[],""],["frenk_t4-ap221-04",8,"Sirena, sirena\ndel mar cantador[a],\ny échame los brazos,\ningrata y señora.",171,2,4,190,"el coco",5,4,"oa",-1,0,-1,0,380,380,"Ap. 221","",0,"","","",2,0,0,[],""],["frenk_t4-ap222-01",8,"Me gusta cantarle al viento\nporque vuelan mis cantares,\ny digo lo que yo siento\npor toditos los lugares.",166,2,-1,190,"LA FERIA DE LAS FLORES",1,4,"ae",164,0,-1,0,380,380,"Ap. 222","",0,"","","",1,0,0,[],""],["frenk_t4-ap222-02",8,"Aquí vine porque vine\na la feria de las flores;\nno hay cerro que se me empine,\nni cuaco que se me atore.",166,2,-1,190,"LA FERIA DE LAS FLORES",0,4,"oe",-1,0,-1,0,380,380,"Ap. 222","",0,"","","",1,0,0,[],""],["frenk_t4-ap222-03",8,"En mi caballo retinto\nhe llegado de muy lejos,\ny traigo pistola al cinto\ny con ella doy consejos.",166,2,-1,190,"LA FERIA DE LAS FLORES",1,4,"eo",149,0,-1,0,380,380,"Ap. 222","",0,"","","",1,0,0,[],""],["frenk_t4-ap222-04",8,"Atravesé las montañas\npa venir a ver las flores:\naquí hay una rosa huraña\nque es la flor de mis amores.",166,2,-1,190,"LA FERIA DE LAS FLORES",0,4,"oe",5,0,-1,0,380,380,"Ap. 222","",0,"","","",1,0,0,[],""],["frenk_t4-ap222-05",8,"Y aunque otro quiera cortarla,\nyo la devisé primero,\ny juro que he de robarla\naunque tenga jardinero.",166,2,-1,190,"LA FERIA DE LAS FLORES",1,4,"eo",38,0,-1,0,380,380,"Ap. 222","",0,"","","",1,0,0,[],""],["frenk_t4-ap222-06",8,"Yo la he de ver trasplantada\nen el huerto de mi casa,\ny si sale el jardinero,\n¡pues a ver, a ver qué pasa!",166,2,-1,190,"LA FERIA DE LAS FLORES",0,4,"aa",123,0,-1,0,380,380,"Ap. 222","",0,"","","",1,0,0,[],""],["frenk_t4-ap223-01",8,"Yo soy un hombre casado\ny tengo mil obligaciones;\nno por eso estoy atado,\nsé darme mis resbalones.",166,2,-1,190,"EL CASADO",1,4,"oe",34,0,-1,0,380,380,"Ap. 223","",0,"","","",1,0,0,[],""],["frenk_t4-ap223-02",8,"No por querer tanto y tanto\na mi mujer consentida,\nvoy a olvidarme de cuánto\nse disfruta en esta vida.",166,2,-1,190,"EL CASADO",1,4,"ia",37,0,-1,0,380,380,"Ap. 223","",0,"","","",1,0,0,[],""],["frenk_t4-ap223-03",8,"El hombre siempre es el hombre,\ny el hombre no pierde nada;\nsi la mujer juega doble,\nsiempre queda mal parada.",166,2,-1,190,"EL CASADO",0,4,"aa",49,0,-1,0,380,380,"Ap. 223","",0,"","","",1,0,0,[],""],["frenk_t4-ap223-04",8,"Ser casado es muy bonito,\npero hay que agarrar la rienda,\nsi no, con cualquier brinquito\nte pasan a la trastienda.",166,2,-1,190,"EL CASADO",1,4,"ea",159,0,-1,0,380,380,"Ap. 223","",0,"","","",1,0,0,[],""],["frenk_t4-ap223-05",8,"Pa mí la vida es muy buena,\nel hogar es la gran cosa;\npero la comida ajena\nsiempre sabe más sabrosa.",166,2,-1,190,"EL CASADO",1,4,"oa",63,0,-1,0,380,380,"Ap. 223","",0,"","","",1,0,0,[],""],["frenk_t4-ap223-07",8,"Todo aquel que sea casado\ndebe estar bien prevenido,\nsi con una está enojado,\ncon la otra es bien recibido.",166,2,-1,190,"EL CASADO",1,4,"io",101,0,-1,0,380,380,"Ap. 223","",0,"","","",1,0,0,[],""],["frenk_t4-ap223-08",8,"Espero que las mujeres\nno vayan a darme un susto,\npor decir que en los quereres\ntengo pareado hasta el gusto.",166,2,-1,190,"EL CASADO",1,4,"uo",497,0,-1,0,381,381,"Ap. 223","",0,"","","",2,0,0,[],""],["frenk_t4-ap224-01",8,"Montes lóbregos,\nque de lejos tierras vengo;\nme llevan preso\nporque amo a mujer casada.",166,2,-1,190,"MONTES LÓBREGOS",3,4,"aa",-1,0,-1,0,381,381,"Ap. 224","",0,"","","",1,0,0,[],""],["frenk_t4-ap224-02",8,"Su marido anda diciendo\nque a traición me ha de matar,\nque a la vuelta de una esquina\nun puñal me ha de atascar.",166,2,-1,190,"MONTES LÓBREGOS",0,4,"a",21,0,-1,0,381,381,"Ap. 224","",0,"","","",1,0,0,[],""],["frenk_t4-ap224-03",8,"Y pa que no ande diciendo,\nya me la voy a llevar,\na que dé su vueltecita\ny al otro lado del mar,\ny aluego la vuelvo a traer.",166,2,-1,190,"MONTES LÓBREGOS",7,5,"e",-1,0,-1,0,381,381,"Ap. 224","",0,"","","",1,0,0,[],""],["frenk_t4-ap225-01",8,"Con mi caballo melado\nme paseo por la ribera,\ncon mi sombrero de lado\nque me regaló mi güera.",183,2,19,190,"VIDA RANCHERA",1,4,"ea",44,0,-1,0,381,381,"Ap. 225","",0,"","","",1,0,0,[],""],["frenk_t4-ap225-02",8,"¡Ay, mi güerita!, ¡ay, mi güerita!,\nya no me hagas padecer;\nmira, chatita, mira, chatita,\ntú eres dueña de mi ser.",183,2,19,190,"VIDA RANCHERA",3,4,"e",20,0,-1,0,381,381,"Ap. 225","",0,"","","",1,0,0,[],""],["frenk_t4-ap225-03",8,"Y siempre, al atardecer,\ncuando el sol ya se ocultó,\na mi güera voy a ver,\nque es la que su amor me dio.",183,2,19,190,"VIDA RANCHERA",1,4,"o",2,0,-1,0,381,381,"Ap. 225","",0,"","","",1,0,0,[],""],["frenk_t4-ap225-05",8,"Ayer que vine de Chiapa\nde comprarme unos huaraches,\ncuando pasé por Ixtapa\nme acordé de los remaches.",183,2,19,190,"VIDA RANCHERA",1,4,"ae",526,0,-1,0,381,381,"Ap. 225","",0,"","","",1,0,0,[],""],["frenk_t4-ap225-07",8,"Y hoy que me encuentro a tu lado,\ngüerita de mi querer,\nmira que mi amor te he dado,\nque debes corresponder.",183,2,19,190,"VIDA RANCHERA",1,4,"e",20,0,-1,0,381,381,"Ap. 225","",0,"","","",1,0,0,[],""],["frenk_t4-ap226-02",8,"En tu graciosa mirada\nhe encontrado tal encanto,\nque no resisto ni aguanto\ntu pasión tan acendrada;\na mí no me importa nada\nque aquí sufra un cruel proceso;\nquiero que me des un beso\npara calmar mi pasión,\ny aunque me veas en prisión,\nno tengas pena por eso.",170,2,7,190,"NO TENGAS PENA POR ESO",18,10,"eo",48,0,-1,0,381,381,"Ap. 226","",0,"","","",1,0,0,[],""],["frenk_t4-ap227-02",8,"Y si llego, afortunado,\na encontrarte bien dormida,\ncuando despiertes, lucida,\nde tu sueño reposada,\nhas de tener bien pintada\nen el brazo una mordida.",171,2,4,190,"SI ERES DE BUEN CORAZÓN",9,6,"ia",37,0,-1,0,382,382,"Ap. 227","",0,"","","",1,0,0,[],""],["frenk_t4-ap228-01",8,"Qué bonita mi güerita\ncon esas trencitas de oro,\nsu boquita chiquitita,\ny esa güera es mi tesoro.",186,2,27,190,"LA GÜERA DE ORO",1,4,"oo",85,0,-1,0,382,382,"Ap. 228","",0,"","","",1,0,0,[],""],["frenk_t4-ap228-02",8,"Cuando estamos platicando\njunto a aquella nopalera,\nse me antoja darle un beso,\n¡lástima que nunca quiera!",186,2,27,190,"LA GÜERA DE ORO",0,4,"ea",44,0,-1,0,382,382,"Ap. 228","",0,"","","",1,0,0,[],""],["frenk_t4-ap228-03",8,"Esa güera, güera de oro,\nha de ser mi compañera;\naunque al mundo no le guste\ny aunque su mamá no quiera.",186,2,27,190,"LA GÜERA DE ORO",0,4,"ea",44,0,-1,0,382,382,"Ap. 228","",0,"","","",1,0,0,[],""],["frenk_t4-ap232-01",8,"Yendo de Tula a Jaumave\nme encontré con un ranchero;\niba en su cuaco retinto,\ntodo vestido de cuero.",179,2,26,190,"EL CUERUDO TAMAULIPECO",0,4,"eo",38,0,-1,0,383,383,"Ap. 232","",0,"","","",1,0,0,[],""],["frenk_t4-ap232-02",8,"Le pregunté pa dónde iba,\ny haciéndose el retozón,\n“voy pa Victoria, me dijo,\na darle vueltas a mi amor”.",179,2,26,190,"EL CUERUDO TAMAULIPECO",0,4,"o",-1,0,-1,0,383,383,"Ap. 232","",0,"","","",1,0,0,[],""],["frenk_t4-ap232-03",8,"¡Ay!, qué retinta mi prieta\ncuando la saco a pasear;\nya luego nos casaremos,\naunque sea en Tamatán.",179,2,26,190,"EL CUERUDO TAMAULIPECO",0,4,"a",-1,0,-1,0,383,383,"Ap. 232","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap232-04",8,"Ya alegre se fue cantando\npor el filo de la sierra;\nTamaulipas es mi tierra\npara el que lo ande dudando.",179,2,26,190,"EL CUERUDO TAMAULIPECO",11,4,"ao",33,0,-1,0,383,383,"Ap. 232","",0,"","","",1,0,0,[],""],["frenk_t4-ap232-05",8,"Y si alguno no le cuadra,\nque me lo venga a decir,\nque el cuerudo de mi tierra\nnunca se sabe rajar.",179,2,26,190,"EL CUERUDO TAMAULIPECO",5,4,"a",-1,0,-1,0,383,383,"Ap. 232","",0,"","","",1,0,0,[],""],["frenk_t4-ap233-01",8,"Cuatrocientos kilómetros tiene\nla ciudad donde vive Zenaida;\nvoy a ver si la puedo encontrar,\nvoy a ver si me da su palabra.",195,2,28,190,"ZENAIDA n",3,4,"aa",-1,0,-1,0,383,383,"Ap. 233","",0,"","","",1,0,0,[],""],["frenk_t4-ap233-02",8,"Porque traigo intenciones de hablarle\ny en mis brazos la quiero tener;\nvoy a ver si madrugo mañana\no me voy antes de amanecer.",195,2,28,190,"ZENAIDA n",3,4,"e",20,0,-1,0,384,384,"Ap. 233","",0,"","","",1,0,0,[],""],["frenk_t4-ap233-03",8,"Por áhi dicen que ya viene el tren,\ny sin duda lo estoy esperando;\nya parece que voy en el tren,\nya parece que voy caminando.",195,2,28,190,"ZENAIDA n",3,4,"ao",33,0,-1,0,384,384,"Ap. 233","",0,"","","",1,0,0,[],""],["frenk_t4-ap233-04",8,"Al momento que la vi venir,\nal momento yo la saludé,\ncariñosa me dice la niña:\n“Oiga, joven, ¿de dónde es usted?”",195,2,28,190,"ZENAIDA n",3,4,"e",-1,0,-1,0,384,384,"Ap. 233","",0,"","","",1,0,0,[],""],["frenk_t4-ap233-05",8,"—Yo he venido de tierras lejanas,\nhe llegado en un tren pasajero\na que me haga un favor que le pido:\nque acompañe a este pobre soltero.",195,2,28,190,"ZENAIDA n",3,4,"eo",38,0,-1,0,384,384,"Ap. 233","",0,"","","",1,0,0,[],""],["frenk_t4-ap233-06",8,"—Oiga, joven, si fuera soltero,\ny si usted me quisiera también,\nnos iríamos los dos a pasearnos\nsi me diera el trasporte pa el tren.",195,2,28,190,"ZENAIDA n",3,4,"e",242,0,-1,0,384,384,"Ap. 233","",0,"","","",1,0,0,[],""],["frenk_t4-ap233-07",8,"Porque traigo intenciones de verla\ny en mis brazos ayer la tenía,\nno esperé que se hiciera de noche,\npara mí fue mejor en el día.",195,2,28,190,"ZENAIDA n",3,4,"ia",0,0,-1,0,384,384,"Ap. 233","",0,"","","",1,0,0,[],""],["frenk_t4-ap234-01",8,"En ese tren pasajero\nque va para Nueva York,\nme he de llevar a esa joven\nque es de mi vida, porque es mi amor,\nno más que tenga dinero.",175,2,6,190,"EL TREN PASAJERO",7,5,"eo",38,0,-1,0,384,384,"Ap. 234","",0,"","","",1,0,0,[],""],["frenk_t4-ap235-01",8,"De las tres que vienen áhi,\n¿cuál te gusta, valedor?\nEsa del vestido rojo\nme parece la mejor.",166,2,-1,190,"DE LAS TRES QUE VIENEN ÁHI",0,4,"o",72,0,-1,0,385,385,"Ap. 235","",0,"frenk_t1","","",2,0,0,[],""],["frenk_t4-ap235-02",8,"Vente, deja de moler,\nya no muelas nixtamal;\nvámonos pa Estados Unidos,\nque allá iremos a gozar.",166,2,-1,190,"DE LAS TRES QUE VIENEN ÁHI",0,4,"a",-1,0,-1,0,385,385,"Ap. 235","",0,"","","",1,0,0,[],""],["frenk_t4-ap235-03",8,"Chatita, áhi viene el tren,\nóyelo qué silbos da;\nno más un favor te pido:\nque no llores poi; allá.",166,2,-1,190,"DE LAS TRES QUE VIENEN ÁHI",0,4,"a",9,0,-1,0,385,385,"Ap. 235","",0,"","","",1,0,0,[],""],["frenk_t4-ap235-04",8,"—Querido, yo voy cansada,\ny apenas aquí es Torreón;\npara no sentir cansancio,\ncántame una canción.",166,2,-1,190,"DE LAS TRES QUE VIENEN ÁHI",3,4,"o",31,0,-1,0,385,385,"Ap. 235","",0,"","","",1,0,0,[],""],["frenk_t4-ap235-05",8,"Qué canción tan rebonita,\nque jamás la había oído yo;\ncántame otra más bonita,\ny después, te canto yo.\nme parece la mejor.",166,2,-1,190,"DE LAS TRES QUE VIENEN ÁHI",7,5,"o",-1,0,-1,0,385,385,"Ap. 235","",0,"","","",1,0,0,[],""],["frenk_t4-ap235-06",8,"Yo le dije al renganchista,\nyo le dije que volvía,\npero que no venía solo,\nque hora traiba compañía.",166,2,-1,190,"DE LAS TRES QUE VIENEN ÁHI",0,4,"ia",0,0,-1,0,385,385,"Ap. 235","",0,"","","",1,0,0,[],""],["frenk_t4-ap235-07",8,"No me mandes para Texas,\nni al estado de Oklahoma;\nson puntos desgraciados,\nque aborrecen al que toma.",166,2,-1,190,"DE LAS TRES QUE VIENEN ÁHI",0,4,"oa",86,0,-1,0,385,385,"Ap. 235","",0,"","","",1,0,0,[],""],["frenk_t4-ap235-08",8,"Todos vienen platicando\nque pasaron por San Luis,\ny al llegar a San Antonio\nles robaron el veliz.",166,2,-1,190,"DE LAS TRES QUE VIENEN ÁHI",0,4,"i",335,0,-1,0,385,385,"Ap. 235","",0,"","","",1,0,0,[],""],["frenk_t4-ap235-09",8,"Ya con ésta me despido\ncon apretón de manos;\nestos versos son compuestos\npor los nobles mexicanos.",166,2,-1,190,"DE LAS TRES QUE VIENEN ÁHI",0,4,"ao",318,0,-1,0,385,385,"Ap. 235","",0,"frenk_t3","","",71,0,0,[],""],["frenk_t4-ap236-01",8,"Sabrás, mi bien, que he venido\ntan solamente a avisarte;\ncomo me voy y te dejo,\nharto siento no llevarte.",166,2,-1,190,"DESPEDIDA DE UN AMANTE",0,4,"ae",8,0,-1,0,385,385,"Ap. 236","",0,"frenk_t2","","",5,0,0,[],""],["frenk_t4-ap236-02",8,"A declararte mi intento\nhe llegado, bien del alma,\ny aunque se me parte el alma,\nte diré mi sentimiento;\nYa mi viaje está diolento,\nya el término se ha cumplido;\nahora estoy enternecido,\npues tu fiel amante soy;\na decirte que me voy\nsabrás, mi bien, que he venido.",166,2,-1,190,"DESPEDIDA DE UN AMANTE",18,10,"io",101,0,-1,0,385,385,"Ap. 236","",0,"","","",1,0,0,[],""],["frenk_t4-ap236-03",8,"[Quién te pudiera llevar,\nmi vida, en esta ocasión!\nTe llevo en mi corazón,\nque es el más perfecto amar.\n¡Oh, qué dolor! ¡qué pesar!\nEl corazón se me parte;\npero no puedo llevarte:\nquédate con Dios, belleza,\nque ha llegado mi firmeza\ntan solamente a avisarte.",166,2,-1,190,"DESPEDIDA DE UN AMANTE",18,10,"ae",8,0,-1,0,385,385,"Ap. 236","",0,"","","",1,0,0,[],""],["frenk_t4-ap236-04",8,"Como Dios me preste vida\ny me ampare su favor,\nespero en el Salvador\nel volver de mi partida.\nVolveré, prenda querida,\na mirarme en ese espejo,\npues que contigo me quejo\nllorando en penosa calma,\na avisarte, bien del alma,\ncómo me voy y te dejo.",166,2,-1,190,"DESPEDIDA DE UN AMANTE",18,10,"eo",264,0,-1,0,386,386,"Ap. 236","",0,"","","",1,0,0,[],""],["frenk_t4-ap236-05",8,"Adiós, bien del alma, adiós;\nadiós, mi encanto y lucero,\ndame el abrazo postrero,\ndespidámonos los dos.\nAdiós, que bien sabe Dios\ncómo es preciso dejarte;\nte prometo no olvidarte\ny tenerte en la memoria;\nadiós, encantada gloria:\nharto siento el no llevarte.",166,2,-1,190,"DESPEDIDA DE UN AMANTE",18,10,"ae",8,0,-1,0,386,386,"Ap. 236","",0,"","","",1,0,0,[],""],["frenk_t4-ap237-02",8,"Yo como solo, yo tenía miedo\nque el marinero me fuera a ahogar,\ny las chalupas en su fragancia\ncerca del puerto de Mazatlán.",196,2,16,190,"SOBRE LAS OLAS",3,4,"a",-1,0,-1,0,386,386,"Ap. 237","",0,"","","",1,0,0,[],""],["frenk_t4-ap237-03",8,"Los marineros me preguntaban:\n“¿Abandonastes a tu mujer?”\n“No la abandono nunca en la vida,\nsi no me muero, yo he de volver.”",196,2,16,190,"SOBRE LAS OLAS",3,4,"e",20,0,-1,0,386,386,"Ap. 237","",0,"","","",1,0,0,[],""],["frenk_t4-ap237-04",8,"Del real de Topia se ven toninas\ny las ballenas se ven brollar,\nse ven los buques dentro del agua\ny el armamento de Mazatlán.",196,2,16,190,"SOBRE LAS OLAS",3,4,"a",-1,0,-1,0,386,386,"Ap. 237","",0,"","","",1,0,0,[],""],["frenk_t4-ap237-05",8,"Oyes, morena, trigueña hermosa,\n¿por qué no quieres a un militar?\nCon un vestido muy elegante\nirás al lado de un general.",196,2,16,190,"SOBRE LAS OLAS",3,4,"a",-1,0,-1,0,386,386,"Ap. 237","",0,"","","",1,0,0,[],""],["frenk_t4-ap238-01",8,"En un trapecio elevado\nme vi sin ser maromero;\nno me subí por valiente,\nyo me subí por ligero.",171,2,4,190,"EL TRAPECIO",0,4,"eo",38,0,-1,0,386,386,"Ap. 238","",0,"","","",1,0,0,[],""],["frenk_t4-ap238-02",8,"El amor es un trapecio,\nsegún llego a comprender;\nse suele uno caer\nen cuanto se mece recio;\nno es esta opinión de necio,\ntampoco de hombre ilustrado,\nes de un hombre apasionado\nque escaso de lectura,\nque se ha visto en una altura\nen un trapecio elevado.",171,2,4,190,"EL TRAPECIO",18,10,"ao",14,0,-1,0,386,386,"Ap. 238","",0,"","","",1,0,0,[],""],["frenk_t4-ap238-03",8,"En un trapecio con palo,\nel amor por ser movible,\nque sea fijo no es posible.\n..................",171,2,4,190,"EL TRAPECIO",3,4,"",-1,0,-1,0,386,386,"Ap. 238","",0,"","","",1,0,0,[],""],["frenk_t4-ap238-04",8,"Se mece bien, pero es raro\nque el que sube primero;\npor eso hoy decirles quiero,\nsegún les voy relatando;\nque en la cuerda trabajando\nme vi sin ser maromero-.",171,2,4,190,"EL TRAPECIO",9,6,"eo",38,0,-1,0,386,386,"Ap. 238","",0,"","","",1,0,0,[],""],["frenk_t4-ap239-01",8,"5/ es cierto que gasto un peso\ny que ando muy alhajada,\na nadie le importa nada;\nserá mi gusto y por eso.",166,2,-1,190,"SI ES CIERTO QUE GASTO UN PESO",11,4,"eo",48,0,-1,0,387,387,"Ap. 239","",0,"","","",1,0,0,[],""],["frenk_t4-ap239-02",8,"Voy al baile y al paseo,\nme divierto donde quiero,\npero no con su dinero\nporque ni la seña veo.\nDe usted nadita deseo,\nen verdad se lo confieso,\npues ya me pasó el exceso\nde estar de usted apasionada;\nasí no le importa nada\nsi es cierto que gasto un peso.",166,2,-1,190,"SI ES CIERTO QUE GASTO UN PESO",18,10,"eo",48,0,-1,0,387,387,"Ap. 239","",0,"","","",1,0,0,[],""],["frenk_t4-ap239-03",8,"Calzo como me divierto,\nyo solita me agasajo,\nmas con mi puro trabajo;\nnada más esto le advierto:\nlo que le digo es muy cierto,\npor eso no soy casada\nni estoy nunca enamorada,\nque ser libre es mi deseo,\npues siempre voy al paseo\ny ando muy alhajada.",166,2,-1,190,"SI ES CIERTO QUE GASTO UN PESO",18,10,"aa",49,0,-1,0,387,387,"Ap. 239","",0,"","","",1,0,0,[],""],["frenk_t4-ap239-04",8,"De esa manera no tengo\npersona que me degrade,\nni perrito que me ladre,\ny así, de nada me abstengo;\nmas por ahora le prevengo:\nque no tenga la humorada\nde inclinarme su mirada,\ncomo lo hace su mercó,\npues aunque yo me pasee,\na nadie le importa nada.",166,2,-1,190,"SI ES CIERTO QUE GASTO UN PESO",18,10,"aa",49,0,-1,0,387,387,"Ap. 239","",0,"","","",1,0,0,[],""],["frenk_t4-ap239-05",8,"Por mi parte, aquí cesaron\ntodas nuestras relaciones;\nno hay que recordar acciones\nque en otro tiempo pasaron.\nPara mí ya se olvidaron,\nen verdad se lo confieso,\nsus caricias que en exceso\nme tenían atarantada;\npues hoy, aunque ande alhajada,\nserá mi gusto y por eso.",166,2,-1,190,"SI ES CIERTO QUE GASTO UN PESO",18,10,"eo",48,0,-1,0,387,387,"Ap. 239","",0,"","","",1,0,0,[],""],["frenk_t4-ap241-01",8,"Cuando pensé ser casado\ny no se me concedió,\nla novia se arrepintió,\nmerito el día del peinado.",171,2,4,190,"CUANDO PENSÉ SER CASADO",11,4,"ao",14,0,-1,0,388,388,"Ap. 241","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap241-02",8,"Mucho en el alma lo siento,\npero no me da cuidado,\nhice un grande sentimiento,\ncierto que no me casé\ncon la joven que yo amaba;\npues nunca la maltraté,\nal contrario, la adoraba\ny mi deseo fue burlado,\nno logré mi casamiento\ncuando pensé ser casado.",171,2,4,190,"CUANDO PENSÉ SER CASADO",18,10,"ao",14,0,-1,0,388,388,"Ap. 241","",0,"","","",1,0,0,[],""],["frenk_t4-ap241-03",8,"Estando de pretendiente\npensaba yo en cierto amor,\ntodo era un lindo primor\ny un cariño muy ardiente;\npero ya mi alma no siente\nni yo me acuerdo de nada;\nno me quiso la malvada,\na mí de bien me sirvió,\npues aunque mucho la amaba,\nel fin no me concedió.",171,2,4,190,"CUANDO PENSÉ SER CASADO",18,10,"o",2,0,-1,0,388,388,"Ap. 241","",0,"","","",1,0,0,[],""],["frenk_t4-ap241-04",8,"Con mucho gusto y contento\nles declaro en mi versada,\naunque mi letra es borrada,\nescribo en este momento\nque no logré mi intento\ncuando pensé ser casado,\ny nunca supe el motivo;\ndije: “Esto ya se perdió”,\ny en ese día que describo,\nla novia se arrepintió.",171,2,4,190,"CUANDO PENSÉ SER CASADO",18,10,"o",2,0,-1,0,388,388,"Ap. 241","",0,"","","",1,0,0,[],""],["frenk_t4-ap241-05",8,"En fin, quedé sin pensar\nque ella entrara en razones,\ncuando pensé quebrantar\ntodas sus conversaciones.\nEn las amonestaciones\nun día se lo malicié,\ny aunque yo le pregunté\nque si algo le había pasado,\nme dijo: “Áhi te lo diré,\nmerito el día del peinado.”",171,2,4,190,"CUANDO PENSÉ SER CASADO",18,10,"ao",14,0,-1,0,388,388,"Ap. 241","",0,"","","",1,0,0,[],""],["frenk_t4-ap243-01",8,"Amigo, amigo,\nescucha mis tristes cantos:\n¿qué me pasa en estos días\npor una ingratona mujer?",169,2,8,190,"AMIGO, AMIGO",3,4,"e",-1,0,-1,0,389,389,"Ap. 243","",0,"","","",1,0,0,[],""],["frenk_t4-ap243-02",8,"Se fue sin despedirme;\nmi corazón está muy adolorido,\nque yo padezco mucho,\nalgún día me acordarás.",169,2,8,190,"AMIGO, AMIGO",3,4,"a",-1,0,-1,0,389,389,"Ap. 243","",0,"","","",1,0,0,[],""],["frenk_t4-ap243-03",8,"Si soy un pobre desgraciado,\n¡ay!, ésa es mi suerte, qué le hago yo;\nde dinero no la tengo,\n¡ay!, pero mi amor qué dulce está.",169,2,8,190,"AMIGO, AMIGO",3,4,"a",-1,0,-1,0,389,389,"Ap. 243","",0,"","","",1,0,0,[],""],["frenk_t4-ap243-04",8,"Chaparrita de mi vida,\ndime si ya no me quieres\npara no contar contigo;\nbuscaré otro nuevo amor.",169,2,8,190,"AMIGO, AMIGO",5,4,"o",-1,0,-1,0,389,389,"Ap. 243","",0,"","","",5,0,0,[],""],["frenk_t4-ap243-05",8,"Si me salgo en las calles,\n¡ah!, qué amores encontraré;\nyo no quiero abandonarte,\n¡ay!, porque te quiero más.",169,2,8,190,"AMIGO, AMIGO",5,4,"a",-1,0,-1,0,389,389,"Ap. 243","",0,"","","",1,0,0,[],""],["frenk_t4-ap244-01",8,"Siento en el alma un suspiro\nel día que dejo de verte;\nporque cuando no te miro\ntriste se encuentra mi suerte.",171,2,4,190,"SIENTO EN EL ALMA UN SUSPIRO",1,4,"ee",134,0,-1,0,389,389,"Ap. 244","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap244-02",8,"Perdóname, niña mía,\npor si en algo te he ofendido,\nquisiera verme rendido\nen tus brazos, vida mía;\npara mí el gusto sería\nque platicara contigo;\nes un deseo tan crecido\ny una ilusión tan legal,\nporque cuando te oigo hablar,\nsiento en el alma un suspiro.",171,2,4,190,"SIENTO EN EL ALMA UN SUSPIRO",18,10,"io",-1,0,-1,0,389,389,"Ap. 244","",0,"","","",1,0,0,[],""],["frenk_t4-ap244-03",8,"Sin gusto y sin alegría,\nmi alma, me dejó tu amor,\npor pobre y por mi color\nme desprecias, vida mía;\nya terminó mi alegría,\nmejor me deseo la muerte,\nyo no puedo aborrecerte,\n¡quién sabe por qué será!\nPero pronto llegará\nel día que deje de verte.",171,2,4,190,"SIENTO EN EL ALMA UN SUSPIRO",18,10,"ee",134,0,-1,0,389,389,"Ap. 244","",0,"","","",1,0,0,[],""],["frenk_t4-ap244-04",8,"Más adelante, algún día,\ntú de mí te has de acordar;\ntriste te veré llorar,\ntú en tu casa y yo en la mía;\ncon gusto y con alegría,\nmi alma, de ti me retiro,\npor ser un hombre perdido\nme llegaste a olvidar;\nme conformo con llorar\nsiempre, el día que no te miro.",171,2,4,190,"SIENTO EN EL ALMA UN SUSPIRO",18,10,"io",-1,0,-1,0,389,389,"Ap. 244","",0,"","","",1,0,0,[],""],["frenk_t4-ap244-05",8,"Adiós, sol resplandeciente,\nadiós, luna sin menguante,\nadiós, niña de mis ojos,\nperdió el lucero brillante;\ntu amor fue muy penetrante\ny no pude convencerte,\nhoy me obligo a no quererte\nporque tienes otro amante,\ningrata, cruel, inconstante;\ntriste se encuentra mi suerte.",171,2,4,190,"SIENTO EN EL ALMA UN SUSPIRO",18,10,"ee",134,0,-1,0,389,389,"Ap. 244","",0,"","","",1,0,0,[],""],["frenk_t4-ap245-01",8,"Cuando me distes entrada\nen el jardín de tu amor,\nme ofrecistes una flor\ny estabas ya deshojada.",171,2,4,190,"CUANDO ME DISTES ENTRADA",11,4,"aa",49,0,-1,0,390,390,"Ap. 245","",0,"","","",2,0,0,[],""],["frenk_t4-ap245-02",8,"De tu jardín, vida mía,\nllegué a ser tu jardinero;\naunque otro lo fue primero,\nnada recelar debía\nel que tú me engañarías,\nque tu planta delicada\nestuviera marchitada\npor una mano alevosa;\nal verte tan recelosa\ncuando me distes entrada.",171,2,4,190,"CUANDO ME DISTES ENTRADA",18,10,"aa",49,0,-1,0,390,390,"Ap. 245","",0,"","","",1,0,0,[],""],["frenk_t4-ap245-03",8,"Yo de tu jardín cuidé,\ndía y noche vigilando,\ny tú lo estabas regando;\nalgunas noches soñé,\notra noche desperté\ncon sobresalto y terror\ny soñando que un malhechor\núnica flor se llevaba,\ny sólo el rastro dejaba\nen el jardín de tu amor.",171,2,4,190,"CUANDO ME DISTES ENTRADA",18,10,"o",72,0,-1,0,390,390,"Ap. 245","",0,"","","",1,0,0,[],""],["frenk_t4-ap245-04",8,"Desde aquel terrible sueño\nempezó mi desconfianza,\ny procuré, sin tardanza,\nbuscar la flor con empeño;\nrecordé que al ser tu dueño,\nun día con grande temor,\npor darme pruebas de amor,\nmil juramentos me hiciste,\ny en lo que me dijiste\nme ofrecistes una flor.",171,2,4,190,"CUANDO ME DISTES ENTRADA",18,10,"o",72,0,-1,0,390,390,"Ap. 245","",0,"","","",1,0,0,[],""],["frenk_t4-ap245-05",8,"En fin, llegó el día deseado\nque yo la flor recibiera,\ny no era la vez primera\nque tú la flor habías dado:\nya otro amante había gozado\nde su esencia delicada,\ny tú, en lágrimas bañada,\nqueriéndome consolar,\nme tratastes de engañar\ny estabas ya deshojada.",171,2,4,190,"CUANDO ME DISTES ENTRADA",18,10,"aa",49,0,-1,0,390,390,"Ap. 245","",0,"","","",1,0,0,[],""],["frenk_t4-ap248-01",8,"¡Ay, Dios!, pero qué tristeza\nsufro en el mundo por ti,\nde ver que tú me desprecias\ny no te dueles de mí.",171,2,4,190,"|AY, dios !, pero qué tristeza",0,4,"i",23,0,-1,0,391,391,"Ap. 248","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap248-02",8,"Como no fuiste cumplida,\na mí me causa pesar,\ny por eso en esta vida\nno me puedo consolar;\nporque me llego a acordar\nque yo te amé con firmeza\ny te juré una promesa,\npero esto no se cumplió,\nla culpa la tuve yo,\n¡ay, Dios!, pero qué tristeza.",171,2,4,190,"|AY, dios !, pero qué tristeza",18,10,"ea",108,0,-1,0,392,392,"Ap. 248","",0,"","","",1,0,0,[],""],["frenk_t4-ap248-03",8,"Traigo mi pecho enfermo\ny un dolor que me atormenta,\npero también llevo en cuenta\nque tú a mí me has despreciado;\nsi muero tú lo has culpado,\nporque me has dicho que sí,\nsabrás que me voy de aquí\na otro terreno mejor,\npero ¡ay, mi alma!, ¡qué dolor\nsufro en el mundo por ti!",171,2,4,190,"|AY, dios !, pero qué tristeza",18,10,"i",23,0,-1,0,392,392,"Ap. 248","",0,"","","",1,0,0,[],""],["frenk_t4-ap248-05",8,"Para que pueda volver\nal cielo pido paciencia,\ny si Dios me da licencia\nnos volveremos a ver;\nmucho gusto he de tener\nque otro te lleve a la iglesia,\npero al casarte confiesa\nlo que he sufrido por ti;\nmañana me voy de aquí,\nde ver que tú me desprecias.",171,2,4,190,"|AY, dios !, pero qué tristeza",18,10,"ea",-1,0,-1,0,392,392,"Ap. 248","",0,"","","",1,0,0,[],""],["frenk_t4-ap248-06",8,"Cuando oigas decir mi nombre,\nno suspires, alma mía,\nno llores, si me querías,\nque el sufrir es de los hombres;\nno te espantes ni te asombres\ncuando sepas que morí,\ndespués de muerto vendré\ny te hablaré por derecho,\nmira, mi alma, lo que has hecho\ny no te dueles de mí.",171,2,4,190,"|AY, dios !, pero qué tristeza",18,10,"i",23,0,-1,0,392,392,"Ap. 248","",0,"","","",1,0,0,[],""],["frenk_t4-ap249-01",8,"Ya no me alces a mirar\ncon esos tus ojos tristes,\nporque se me representa\nel mal pago que me diste.",173,2,17,190,"YA NO ME ALCES A MIRAR",0,4,"ie",-1,0,-1,0,392,392,"Ap. 249","",0,"","","",1,0,0,[],""],["frenk_t4-ap249-02",8,"Si amor me hubieras tenido\ny crecida voluntad,\nno hubiera en ti falsedad\nni me hubieras ofendido;\nla fe con que te he querido\nes constante y sin igual;\ndesde hoy te vengo a explicar:\noye, cara descubierta,\ncuando pase por tu puerta\nya no me alces a mitar.",173,2,17,190,"YA NO ME ALCES A MIRAR",18,10,"a",21,0,-1,0,392,392,"Ap. 249","",0,"","","",1,0,0,[],""],["frenk_t4-ap249-03",8,"Cada vez que pienso en ti\nme mueve la compasión,\nque constante te serví\ny pagaste con traición;\ny tuviste corazón\nde ser lícita y quisiste,\nviste y no conociste\nque yo lo había de saber,\ny así no me alces a ver\ncon esos tus ojos tristes.",173,2,17,190,"YA NO ME ALCES A MIRAR",18,10,"ie",-1,0,-1,0,392,392,"Ap. 249","",0,"","","",2,0,0,[],""],["frenk_t4-ap249-04",8,"Arreboles me han pedido\ny arreboles he de dar;\nprimero supe arreboles\nque saberme persinar.",173,2,17,190,"YA NO ME ALCES A MIRAR",0,4,"a",21,0,-1,0,392,392,"Ap. 249","",0,"","","",2,0,0,[],""],["frenk_t4-ap249-05",8,"Ahora, si contigo vuelvo,\ntodos me han de murmurar,\nporque en el juego de amar\nhonra y punto es lo primero;\nyo bien claro considero\nque pública fue mi afrenta,\nque eres muerta haré de cuenta,\ncomo resuelto me obligo\nya no más volver contigo,\nporque se me representa.",173,2,17,190,"YA NO ME ALCES A MIRAR",18,10,"ea",229,0,-1,0,393,393,"Ap. 249","",0,"","","",1,0,0,[],""],["frenk_t4-ap249-06",8,"En fin, y quédate a Dios\ny siempre ruega por ti;\nno te acuerdes más de mí\nni te quejes más veloz;\nesto queda entre los dos,\npues tú la culpa tuviste,\nencubrirme no supiste\ncomo te lo haré patente:\ncada día tengo presente\nel mal pago que me diste.",173,2,17,190,"YA NO ME ALCES A MIRAR",18,10,"ie",153,0,-1,0,393,393,"Ap. 249","",0,"","","",1,0,0,[],""],["frenk_t4-ap250-01",8,"Estoy al vender una ingrata\nque me pagó con desdén;\n¡ay!, la voy a dar muy barata:\npor lo primero que den.",176,2,3,190,"ESTOY AL VENDER UNA INGRATA",1,4,"e",242,0,-1,0,393,393,"Ap. 250","",0,"","","",2,0,0,[],""],["frenk_t4-ap250-02",8,"¡Ay!, voy a poner un pasquín\ndando aviso general,\n¡ay!, para que ella sepa el fin\ny el ser que le voy a dar;\npor la plaza he de pasar,\n¡ay!, diciendo: “Vendo una chata”,\ncosa que si alguno trata,\n¡ay!, la doy por decomiso,\npor el pasquín doy aviso:\nestoy al vender a una ingrata.",176,2,3,190,"ESTOY AL VENDER UNA INGRATA",18,10,"aa",74,0,-1,0,393,393,"Ap. 250","",0,"","","",1,0,0,[],""],["frenk_t4-ap250-03",8,"¡Ay!, mi corazón no se afirma;\nal mayor terrible y calma,\n¡ay!, porque me ofendió esta ingrata\ny hasta las chapas del alma,\npor una Laura...\n¡Ay!, ya se acabó el sumo bien,\nmuerto estoy sin saber quién,\n¡ay!, quién me cortó estando tan verde,\npero yo haré que se acuerde\nque me pagó con desdén.",176,2,3,190,"ESTOY AL VENDER UNA INGRATA",18,10,"e",242,0,-1,0,393,393,"Ap. 250","",0,"","","",1,0,0,[],""],["frenk_t4-ap250-04",8,"¡Ay!, si los dichos compradores\nquieren su cuenta segura,\n¡ay!, les tendré mi escritura\ncon testigos y fiadores\nen un tribunal de amores,\n¡ay!, pa que sepa quién la trata:\nla fereo por cobre y plata.",176,2,3,190,"ESTOY AL VENDER UNA INGRATA",4,7,"aa",74,0,-1,0,393,393,"Ap. 250","",0,"","","",1,0,0,[],""],["frenk_t4-ap250-06",8,"¡Ay!, al fin para acreditar\nque ya corría de otra cuenta,\n¡ay!, mandaré pagar libreta,\nfiada y todo por cabal;\nha de llevar mi señal,\n¡ay!, perros que miran y ven,\npara que ella sepa quién,\n¡ay!, quién le dio salida tan recio,\ny no me separen precio\npor lo primero que den.",176,2,3,190,"ESTOY AL VENDER UNA INGRATA",18,10,"e",242,0,-1,0,393,393,"Ap. 250","",0,"","","",1,0,0,[],""],["frenk_t4-ap250-07",8,"¡Ay!, ¿qué es aquello que relumbra\npor toditito el plan?\n¡Ay!, son las luces del palacio\ndel pueblo de Apatzingán.",176,2,3,190,"ESTOY AL VENDER UNA INGRATA",0,4,"a",147,0,-1,0,393,393,"Ap. 250","",0,"","","",1,0,0,[],""],["frenk_t4-ap250-08",8,"Lo dice Abraham Villaván,\n¡ay!, con tinta y papel sellado,\nmas no dejen de saber\nque el que cantó aquí es su criado.",176,2,3,190,"ESTOY AL VENDER UNA INGRATA",3,4,"ao",14,0,-1,0,393,393,"Ap. 250","",0,"","","",1,0,0,[],""],["frenk_t4-ap253-01",8,"De la edad de catorce años,\ncerquita de mi mamá,\nme gustaba ir a los bailes\ny amar a la libertad.",176,2,3,190,"A LA EDAD DE CATORCE AÑOS",0,4,"a",-1,0,-1,0,395,395,"Ap. 253","",0,"","","",1,0,0,[],""],["frenk_t4-ap253-02",8,"La novia que yo tenía\nmi mamá no la quería,\ntodo el día me regañaba:\nque cuándo la olvidaría.",176,2,3,190,"A LA EDAD DE CATORCE AÑOS",0,4,"ia",0,0,-1,0,395,395,"Ap. 253","",0,"","","",1,0,0,[],""],["frenk_t4-ap253-03",8,"—Mamacita de mi vida,\nmadre de mi corazón,\n¿cómo queres que la olvide\nsi me ha brindado su amor?",176,2,3,190,"A LA EDAD DE CATORCE AÑOS",0,4,"o",-1,0,-1,0,395,395,"Ap. 253","",0,"","","",3,0,0,[],""],["frenk_t4-ap253-04",8,"A los tres días de casado\nquise mi vida empezar;\nolvidé yo a mi mujer\npor unas de la paseada.",176,2,3,190,"A LA EDAD DE CATORCE AÑOS",5,4,"aa",-1,0,-1,0,395,395,"Ap. 253","",0,"","","",3,0,0,[],""],["frenk_t4-ap253-05",8,"A los tres días de casado\nquise mi vida tranquila;\nolvidé yo a mi mujer\npor una ingrata querida.",176,2,3,190,"A LA EDAD DE CATORCE AÑOS",0,4,"ia",-1,0,-1,0,395,395,"Ap. 253","",0,"","","",3,0,0,[],""],["frenk_t4-ap253-06",8,"Olvidé yo a mi mujer\nporque era mujer tirana,\nporque no quiso acostarse\ncon dos en la misma cama.",176,2,3,190,"A LA EDAD DE CATORCE AÑOS",0,4,"aa",-1,0,-1,0,395,395,"Ap. 253","",0,"","","",1,0,0,[],""],["frenk_t4-ap253-07",8,"Cuando yo me fui a casar,\nse me olvidó la dotrina;\nel cura me regañaba\ndelante de mi madrina.",176,2,3,190,"A LA EDAD DE CATORCE AÑOS",0,4,"ia",11,0,-1,0,395,395,"Ap. 253","",0,"","","",1,0,0,[],""],["frenk_t4-ap254-01",8,"Alma mía de mi grandota,\nque antenoche se me huyó;\nme jugó el dedo en la boca\ny se fue y me abandonó.",178,2,10,190,"LA GRANDOTA",0,4,"o",2,0,-1,0,395,395,"Ap. 254","",0,"","","",2,0,0,[],""],["frenk_t4-ap254-03",8,"No más la razón tuvimos;\nque de mañana pasó\npor enfrente del billar\ncon el que se la llevó.",178,2,10,190,"LA GRANDOTA",0,4,"o",2,0,-1,0,395,395,"Ap. 254","",0,"","","",1,0,0,[],""],["frenk_t4-ap254-05",8,"Si la llegan a encontrar,\nlas señas les voy a dar:\n“Trae un saquito masón,\ny sus naguas de percal’’.",178,2,10,190,"LA GRANDOTA",0,4,"a",-1,0,-1,0,395,395,"Ap. 254","",0,"","","",1,0,0,[],""],["frenk_t4-ap254-07",8,"¡Alma mía de mi grandota,\ncuándo la volveré a ver,\ntan grandota y tan frondosa,\nque era todo mi querer!",178,2,10,190,"LA GRANDOTA",0,4,"e",20,0,-1,0,395,395,"Ap. 254","",0,"","","",2,0,0,[],""],["frenk_t4-ap255-01",8,"¡Ah, qué ingrata fue Juanita!,\nsin motivo me largó;\nse pronunció mi güerita\npor tres días que no comió.",166,2,-1,190,"DÉCIMAS DE UN SOLTERITO",1,4,"o",2,0,-1,0,395,395,"Ap. 255","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap255-02",8,"Señores, quién lo ha de creer:\nmi mujer buscó marido;\nrazón no encuentro a mi vez\nque suficiente haya sido.\nCon ella fui muy cumplido;\ngusto el que quería le daba,\nla tenía muy bien tratada;\nparecía una palomita,\nconmigo ñafia deseaba.\n¡Ah, qué ingrata fue Juanita!",166,2,-1,190,"DÉCIMAS DE UN SOLTERITO",18,10,"ia",50,0,-1,0,396,396,"Ap. 255","",0,"","","",1,0,0,[],""],["frenk_t4-ap255-03",8,"Ella bien desayunaba,\nde regalos, no se diga;\ntodos los días bien planchada\ny su media muy lucida.\nFuiste mal agradecida,\nmujer, con quien te adoraba.\n¿Aquel membrillito vara\ntan mal te correspondió?\nNo más porque le pegaba\nsin motivo se largó.",166,2,-1,190,"DÉCIMAS DE UN SOLTERITO",18,10,"o",2,0,-1,0,396,396,"Ap. 255","",0,"","","",1,0,0,[],""],["frenk_t4-ap255-04",8,"Algún día te acordarás\nde todos mis cariñitos;\nentonces recordarás\ncuando éramos amorcitos;\neso sí, que hombres sueltitos\ncomo yo, nunca has de hallar;\ngastaba, al irte a pasear\na veces, mi cuartillita.\n¡Qué suspiros ha de dar!\nSe pronunció mi güerita.",166,2,-1,190,"DÉCIMAS DE UN SOLTERITO",18,10,"ia",50,0,-1,0,396,396,"Ap. 255","",0,"","","",1,0,0,[],""],["frenk_t4-ap255-05",8,"Nadie lo podrá negar,\nmuy hombrote fui con ella;\nla verdad, me hacía gran mella\ncuando se ponía a cenar:\nun grano de nixtamal\nse comía la muy tirana;\nuno y medio en la mañana,\nun dineral me costó;\nse mostró orgullosa Juana\npor tres días que no comió.",166,2,-1,190,"DÉCIMAS DE UN SOLTERITO",18,10,"o",2,0,-1,0,396,396,"Ap. 255","",0,"","","",1,0,0,[],""],["frenk_t4-ap256-01",8,"Estoy trastornado, ya me emborraché,\nyo les diré por qué cosa:\nporque me he encontrado con una mujer\nque de veras es celosa.",169,2,8,190,"POBRE HOMBRE",3,4,"oa",63,0,-1,0,396,396,"Ap. 256","",0,"","","",1,0,0,[],""],["frenk_t4-ap256-02",8,"Cuando la ven seriecita\nes porque ya está enojada,\nes porque ya le contaron\ndiez mil tantas carambadas.",169,2,8,190,"POBRE HOMBRE",0,4,"aa",-1,0,-1,0,396,396,"Ap. 256","",0,"","","",1,0,0,[],""],["frenk_t4-ap256-03",8,"Ella está inquieta y está delirando,\nyo ya les diré el porqué:\nque de pasadita, que de cada en cuando,\ndebajo el paño me ve.",169,2,8,190,"POBRE HOMBRE",3,4,"e",77,0,-1,0,396,396,"Ap. 256","",0,"","","",1,0,0,[],""],["frenk_t4-ap256-04",8,"—Si porque tienes amores,\nsi amas a otras mujeres,\ndime de veras, ¿las quieres?\n¡Ay, dímelo, a ver si puedes!",169,2,8,190,"POBRE HOMBRE",0,4,"ee",-1,0,-1,0,396,396,"Ap. 256","",0,"","","",1,0,0,[],""],["frenk_t4-ap256-05",8,"Ayer en la calle yo me la encontré,\nque no me quiso ni ver:\n—Anda, dijo luego, llegas a la casa,\nque te voy a menester.",169,2,8,190,"POBRE HOMBRE",3,4,"e",20,0,-1,0,396,396,"Ap. 256","",0,"","","",1,0,0,[],""],["frenk_t4-ap256-06",8,"Otro día temprano me fui para su casa,\nme puso tamaño modo;\ny sólo en pensar y considerar\nque bufaba como un toro.",169,2,8,190,"POBRE HOMBRE",3,4,"oo",-1,0,-1,0,396,396,"Ap. 256","",0,"","","",1,0,0,[],""],["frenk_t4-ap256-07",8,"—¡Ay!, mira trigueña, dime la verdad,\nsi quieres doblamos la hoja;\na ti sola quise, te di mi amistad;\nno te he de cambiar por otra.",169,2,8,190,"POBRE HOMBRE",3,4,"oa",-1,0,-1,0,396,396,"Ap. 256","",0,"","","",1,0,0,[],""],["frenk_t4-ap256-08",8,"Mis fieles amigos, yo ya me despido,\nme despido de la broza;\nporque ahí se casan con una mujer,\nla miren, no sea celosa.",169,2,8,190,"POBRE HOMBRE",3,4,"oa",63,0,-1,0,396,396,"Ap. 256","",0,"","","",1,0,0,[],""],["frenk_t4-ap256-09",8,"Una que sea de buena alma\ny sepa considerar;\nque en todo sea buena gente\ny no tenga qué desear.",169,2,8,190,"POBRE HOMBRE",0,4,"a",21,0,-1,0,396,396,"Ap. 256","",0,"","","",2,0,0,[],""],["frenk_t4-ap256-10",8,"Una que sea de buena alma\ny también sepa sufrir;\nque en todo sea buena gente\ny no tenga qué decir.",169,2,8,190,"POBRE HOMBRE",0,4,"i",157,0,-1,0,396,396,"Ap. 256","",0,"","","",2,0,0,[],""],["frenk_t4-ap258-01",8,"¡Ay, qué novia tan tragona\npor desgracia me adquirí!\nA poco, si me descuido,\nme quiere comer a mí.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"i",23,0,-1,0,397,397,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-02",8,"Es una gata bonita\nque se llama María Antoña;\npero come la maldita,\ncome mucho más que roña.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",1,4,"oa",566,0,-1,0,397,397,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-03",8,"Estoy rete arrepentido\nde habérmela enamorado,\nporque me tiene molido\ny muy caro me ha costado.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",1,4,"ao",14,0,-1,0,397,397,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-04",8,"Los domingos en la tarde,\ncuando la suelo encontrar,\ntiemblo como un enyerbado\nsin poderlo remediar.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"a",21,0,-1,0,397,397,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-05",8,"Ya sé que sin discutir\nni poderlo averiguar,\ntodito lo que me pide\nse lo tengo que mercar.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"a",21,0,-1,0,397,397,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-06",8,"Si no es así, se embravece\ny alarga tamaña trompa,\ny es fácil que hasta me muerda\ny las narices me rompa.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"oa",652,0,-1,0,397,397,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-07",8,"Por esto, pues, no hay manera\nque me escape de gastar;\nhasta el chaleco o sombrero\ntengo a veces que empeñar.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"a",21,0,-1,0,397,397,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-08",8,"Parece que puras papas\nes lo que horita les cuento,\npero es la verdad pelona,\ny no es falso ni lo invento.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"eo",94,0,-1,0,398,398,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-09",8,"Pues sépanse que el domingo\ntuvimos un encontrón;\n¡cómo, diablos, no le dio\na la cochina un torzón!",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"o",-1,0,-1,0,398,398,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-10",8,"Y luego, por mi desgracia,\ny mi suerte tan reprieta,\nmuy poco alcancé de raya\ny estaba bruja completa.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"ea",200,0,-1,0,398,398,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-11",8,"“¡Qué gusto que te topé!”,\nen cuanto me vio, me dijo:\n“Vamos al zócalo, chulo,\nte quiero mucho, mi hijito”.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"io",-1,0,-1,0,398,398,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-12",8,"Y a padecer comencé\ny no valieron pretextos,\nque me agarró de la mano\ny caminé haciendo gestos.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"eo",-1,0,-1,0,398,398,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-13",8,"“Yo quiero unos mueganitos\ny charamuscas de queso”;\nle di lo que me pedía,\n¡mejor le diera veneno!",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"eo",-1,0,-1,0,398,398,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-14",8,"En menos que canta un gato,\ndigo, un gallo, se hartó todo:\n¡qué barriga, qué panzota,\ncapaz de beberse a un toro!",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"oo",-1,0,-1,0,398,398,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap258-15",8,"En pago me dio en la boca\nun kiss: ¡qué beso aquél!\nMe llenó todo el bigote\nde migajas y de miel.",166,2,-1,190,"LA GATITA MARÍA ANTOÑA",0,4,"e",32,0,-1,0,398,398,"Ap. 258","",0,"","","",1,0,0,[],""],["frenk_t4-ap259-01",8,"Me metí con un arriero\ny se llevó hasta el petate;\nse me fugó del chiquero:\n¡qué arriero tan zaragate!",168,2,11,190,"ME METÍ CON UN ARRIERO",1,4,"ae",384,0,-1,0,398,398,"Ap. 259","",0,"","","",1,0,0,[],""],["frenk_t4-ap259-02",8,"¡Ah!, qué hombre tan imprudente,\nque no me supo estimar;\npor mi suerte vine a dar\ncon ese diablo indolente,\nborracho e impertinente,\nque con gran tono y salero\nme pedía sopa y puchero,\nsin darme con qué comprar;\ntratando de progresar,\nme metí con un arriero.",168,2,11,190,"ME METÍ CON UN ARRIERO",18,10,"eo",38,0,-1,0,398,398,"Ap. 259","",0,"","","",1,0,0,[],""],["frenk_t4-ap259-03",8,"Con engaños me trataba\neste perro matalote,\ncabeza de zopilote,\ndespués que nada me daba;\na cuartazos me acostaba,\nporque no comía zacate.\n¡Demonio de cacahuate!,\nyo pensaba que era fino;\nme apasioné de este indino,\ny se llevó hasta el petate.",168,2,11,190,"ME METÍ CON UN ARRIERO",18,10,"ae",384,0,-1,0,398,398,"Ap. 259","",0,"","","",1,0,0,[],""],["frenk_t4-ap259-04",8,"En fin, no pude aguantar\nlos hechos de este malvado,\njugador y enamorado;\ntodo se le iba en pasear;\nalgún día ha de suspirar\neste malvado ranchero,\ninfame sinrazonero,\npicaro, indino, cochino;\ninter que tomé mi vino,\nse me fugó del chiquero.",168,2,11,190,"ME METÍ CON UN ARRIERO",18,10,"eo",38,0,-1,0,398,398,"Ap. 259","",0,"","","",1,0,0,[],""],["frenk_t4-ap259-05",8,"Tengo otro mejor que usted,\nmuchachito y muy bonito,\nhombre de bien, planchadito,\ncomo se lo enseñaré;\na éste sí lo estimaré,\npues no crea que me maltrate,\nni esté yo tras un petate,\npues con verdad se lo digo,\nya vio lo que hizo conmigo:\n¡Qué arriero tan zaragate!",168,2,11,190,"ME METÍ CON UN ARRIERO",18,10,"ae",384,0,-1,0,398,398,"Ap. 259","",0,"","","",1,0,0,[],""],["frenk_t4-ap260-01",8,"Ya mi caballo no bebe,\nporque el ánimo perdió;\npero si usted no se atreve,\npara no perderlo yo,\ncantaremos “L’aguanieve”.",171,2,4,190,"DÉCIMAS DE PÁNFILO VALERIO II",7,5,"ee",474,0,-1,0,399,399,"Ap. 260","",0,"","","",2,0,0,[],""],["frenk_t4-ap260-02",8,"Yo perdí por un amor\ntodita una noche entera,\ny me dijo: “No, señor,\nno es fuerza que yo lo quiera.\"",171,2,4,190,"DÉCIMAS DE PÁNFILO VALERIO II",1,4,"ea",44,0,-1,0,399,399,"Ap. 260","",0,"","","",1,0,0,[],""],["frenk_t4-ap260-03",8,"Al momento que llegué\ny le empecé a recordar,\nluego que le empecé a hablar\nme dijo: “¿A qué viene usted?”\nLe dije: “¿Por qué y por qué\nme trata usted con rigor?;\nyo le pido de favor\nque no se muestre enojada”;\nuna fuerte desvelada\nque perdí por un amor.",171,2,4,190,"DÉCIMAS DE PÁNFILO VALERIO II",18,10,"o",72,0,-1,0,399,399,"Ap. 260","",0,"","","",1,0,0,[],""],["frenk_t4-ap260-04",8,"“¿Por qué y por qué\nme trata usted con rigor?;\nyo le pido de favor\nque no se muestre enojada”;\nuna fuerte desvelada\nque perdí por un amor.",171,2,4,190,"DÉCIMAS DE PÁNFILO VALERIO II",9,6,"o",72,0,-1,0,399,399,"Ap. 260","",0,"","","",1,0,0,[],""],["frenk_t4-ap260-05",8,"De lo que le platicaba\nde mí, yo no hacía confianza,\ny lo que me contestaba:\nque perdiera la esperanza,\ny yo sentía la tardanza\nal que no se convenciera;\ny decía yo: “¡Quién pudiera\nablandar a tu persona”;\nperdí por una bribona\ntodita una noche entera.",171,2,4,190,"DÉCIMAS DE PÁNFILO VALERIO II",18,10,"ea",44,0,-1,0,399,399,"Ap. 260","",0,"","","",1,0,0,[],""],["frenk_t4-ap260-06",8,"La besaba y la mordía\ny le daba de besitos,\nle hacía varios cariñitos;\nde lo demás no quería.\nY yo siempre en mi porfía\ncomo al fin padecedor,\ny decía yo: “¡Qué dolor,\nque seré tan desgraciado!”;\npero yo siempre porfiaba,\ny me decía: “No, señor.\"",171,2,4,190,"DÉCIMAS DE PÁNFILO VALERIO II",18,10,"o",72,0,-1,0,399,399,"Ap. 260","",0,"","","",1,0,0,[],""],["frenk_t4-ap260-07",8,"No lo han de pasar a creer,\nque hasta ni yo lo creía,\nque mero rayando el día\nla he venido a convencer;\nyo le pedí a esa mujer\ndesde antes que anocheciera,\ntan dura como madera;\npero al fin se convenció,\ny de refrán le quedó:\n“no es fuerza que yo lo quiera\".",171,2,4,190,"DÉCIMAS DE PÁNFILO VALERIO II",18,10,"ea",44,0,-1,0,399,399,"Ap. 260","",0,"","","",1,0,0,[],""],["frenk_t4-ap261-01",8,"Señor presidente,\nyo le vengo a ver:\nque mi marido\ntiene otra mujer.",187,2,12,190,"SEÑOR PRESIDENTE",6,4,"e",20,0,-1,0,399,399,"Ap. 261","",0,"","","",2,0,0,[],""],["frenk_t4-ap261-02",8,"Si fuera bonita\nyo se la dejaba,\npero es una vieja\nmuy alborotada.",187,2,12,190,"SEÑOR PRESIDENTE",0,4,"aa",-1,0,-1,0,399,399,"Ap. 261","",0,"","","",1,0,0,[],""],["frenk_t4-ap261-03",8,"La tengo que encontrar,\nla tengo que encontrar,\ny de sus melenas\nme he de columpiar.",187,2,12,190,"SEÑOR PRESIDENTE",0,4,"a",21,0,-1,0,399,399,"Ap. 261","",0,"","","",1,0,0,[],""],["frenk_t4-ap262-01",8,"La vieja que tiene Pancho,\na pesar de ser ranchera,\ncuando el pobre va pa el rancho,\nle guiña el ojo a cualquiera\ny se atora en cualquier gancho,\nporque ya no hay quien la quiera.",166,2,-1,190,"LA VIEJA DE PANCHO",9,6,"ea",44,0,-1,0,399,399,"Ap. 262","",0,"","","",1,0,0,[],""],["frenk_t4-ap262-02",8,"Ayer la encontré en la calle\npresumiendo de soltera:\nquien le enseñó aquel detalle\nfue una hija de la portera;\nle dijo: “Usted no desmaye,\nal fin que el viejo anda afuera.”",166,2,-1,190,"LA VIEJA DE PANCHO",9,6,"ea",44,0,-1,0,399,399,"Ap. 262","",0,"","","",2,0,0,[],""],["frenk_t4-ap262-03",8,"Pobre de Panchito, ¿qué le habrá pasado?\nera rete vivo (caramba),\ny ahora se ha agüitado.\nAntes se fajaba (caramba, caramba),\nbien los pantalones;\nahora no se faja (caramba)\nya ni los calzones.",166,2,-1,190,"LA VIEJA DE PANCHO",4,7,"oe",34,0,-1,0,400,400,"Ap. 262","",0,"","","",1,0,0,[],""],["frenk_t4-ap262-04",8,"Y desde aquel día\nla vieja agarró ese mal consejo:\nya se depila las cejas,\nya no le obedece al viejo,\ny cuando quiere lo deja;\nya no sé qué está pasando,\nya le puso el aparejo.",166,2,-1,190,"LA VIEJA DE PANCHO",4,7,"eo",264,0,-1,0,400,400,"Ap. 262","",0,"","","",1,0,0,[],""],["frenk_t4-ap262-05",8,"Pero hay que ver una cosa:\ny la vieja chinguiñosa\nahora se está cobrando,\ny como es tan alevosa,\nlas uñas le está encajando.",166,2,-1,190,"LA VIEJA DE PANCHO",7,5,"ao",33,0,-1,0,400,400,"Ap. 262","",0,"","","",1,0,0,[],""],["frenk_t4-ap263-01",8,"Y zas y zas y zas y zas,\nválgame, mamá, ¿qué haré?\nAhí viene mi esposo Blas,\n¿en dónde me esconderé?",175,2,6,190,"ZAS Y ZAS Y ZAS",1,4,"e",77,0,-1,0,400,400,"Ap. 263","",0,"","","",1,0,0,[],""],["frenk_t4-ap264-02",8,"¡Ay!, mis amigos, sin consuelo\nme hacen burla de de veras;\n¡ay!, al cabo esta renca no la quiero\npara ir a jugar carreras;\namigo, si tú la vieras:\nella se me encela y se me enoja,\nsólo conmigo se aloja;\n¡ay!, con sus muletas me sigue,\nme ha de pegar el “¿quién vive?”;\nme dice, aunque esté coja.",166,2,-1,190,"LA RENCA",18,10,"oa",146,0,-1,0,401,401,"Ap. 264","",0,"","","",1,0,0,[],""],["frenk_t4-ap264-03",8,"¡Ay!, amigo, te advierto,\ny con esto te digo todo,\n¡ay!, que estando uno en un retiro,\nuna renca es un tesoro;\nmayormente la que adoro,\n¡ay!, ella es todo mi querer;\nella me da de comer,\n¡ay!, con su patita arrastrando;\nbuena me la estoy pasando,\namigos, doy a saber.",166,2,-1,190,"LA RENCA",18,10,"e",20,0,-1,0,401,401,"Ap. 264","",0,"","","",1,0,0,[],""],["frenk_t4-ap264-04",8,"Mi renca me anda celando\npor los cuentos de una Anita;\nmuy cierta, la pobrecita,\nque sí le andaba tratando;\nmi renca me andaba espiando,\nun día que me descuidé;\nay, detrás de mí se fue;\nnos jallo entre unas jarras;\nallí nos hartó a patadas\n¡ay!, y ni falta le hizo el pié.",166,2,-1,190,"LA RENCA",18,10,"e",77,0,-1,0,401,401,"Ap. 264","",0,"","","",1,0,0,[],""],["frenk_t4-ap264-05",8,"Todos echan despedida,\npero no como la mía,\nantes que yo naciera\ny naiden me conocía.",166,2,-1,190,"LA RENCA",0,4,"ia",0,0,-1,0,401,401,"Ap. 264","",0,"","","",4,0,0,[],""],["frenk_t4-ap265-02",8,"Todo el que porta decencia,\nhasta le ofrecen dinero;\nno es picaro ni fraudero\nni tampoco sinvergüenza.\nEs verdadera apariencia,\nque averigüe con cualquiera;\ny en bailes y en borracheras,\nal pobre no le hacen caso;\ny sin ningún embarazo,\nes pelón el que se encuera.",177,2,18,190,"ANDANDO EN LA BORRACHERA",18,10,"ea",-1,0,-1,0,401,401,"Ap. 265","",0,"","","",1,0,0,[],""],["frenk_t4-ap265-03",8,"Todo el que se quiera ver\nmuy bien visto y apreciado,\nha de andar muy bien plantado.\nY el que no lo quiera creer,\nverá que hasta la mujer\nse le franquea donde quiera;\npues es cosa verdadera\nque no se puede dudar,\nque para beber o jugar\nes pelón el que se encuera.",177,2,18,190,"ANDANDO EN LA BORRACHERA",18,10,"ea",44,0,-1,0,402,402,"Ap. 265","",0,"","","",1,0,0,[],""],["frenk_t4-ap266-02",8,"Corazón enamorado,\nflorcita de Nochebuena,\n¿por qué te das a la pena\nsi yo soy tu bien amado?\nCon la punta del arado\ntrocé la ráiz de la yuca;\ncuando mi amor se acurruca\ny entre mis brazos se duerme,\nsiento que voy a perderme\ny hasta me duele la nuca.",175,2,6,190,"CORAZÓN ENAMORADO",18,10,"ua",607,0,-1,0,402,402,"Ap. 266","",0,"","","",3,0,0,[],""],["frenk_t4-ap266-03",8,"Para ese dolor, amigo,\nlo mejor es un mezcal;\ntomado en el tinacal,\ncura hasta el dolor de ombligo.\nY de eso yo soy testigo,\nporque una vez me curó;\nesto es lo que digo yo,\npero un muerto me asegura\nque no es tan cierto que cura,\nporque él con eso murió.",175,2,6,190,"CORAZÓN ENAMORADO",18,10,"o",2,0,-1,0,402,402,"Ap. 266","",0,"","","",1,0,0,[],""],["frenk_t4-ap267-02",8,"No te fíes de un casado,\naunque te muestre firmeza,\nporque al cabo vienes siendo\nplato de segunda mesa.",171,2,4,190,"NO TE FÍES DE UN CASADO",0,4,"ea",201,0,-1,0,402,402,"Ap. 267","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap267-03",8,"Una tarde estando triste\nme salí a pasear con él;\nen lo mejor de mi gusto\nsuspiró por su mujer.",171,2,4,190,"NO TE FÍES DE UN CASADO",0,4,"e",-1,0,-1,0,402,402,"Ap. 267","",0,"","","",3,0,0,[],""],["frenk_t4-ap267-04",8,"Me puse con tres amigos a hablar,\ny puse a considerar:\nal fin que es hombre casado\ny me ha de dejar llorando,\ncomo pajarito triste\nde rama en rama llorando,\nllorando mi soledad.",171,2,4,190,"NO TE FÍES DE UN CASADO",4,7,"a",-1,0,-1,0,402,402,"Ap. 267","",0,"","","",1,0,0,[],""],["frenk_t4-ap269-01",8,"Voy a hablar de las casadas,\naunque les parezca mal:\nporque no hacen un costal\naunque estén desocupadas.",175,2,6,190,"LAS CASADAS",11,4,"aa",282,0,-1,0,403,403,"Ap. 269","",0,"","","",2,0,0,[],""],["frenk_t4-ap270-01",8,"Yo soy la mujer casada,\n¡cuántas penas he pasado!;\nmi marido, de bracero,\nno me manda ni un centavo.",166,2,-1,190,"LA CASADA",0,4,"ao",-1,0,-1,0,404,404,"Ap. 270","",0,"","","",1,0,0,[],""],["frenk_t4-ap270-02",8,"Tengo tres años de sola,\náhi no más, sufriendo horrores,\nél gastando puro dólar\ny yo sufriendo los dolores.",166,2,-1,190,"LA CASADA",0,4,"oe",5,0,-1,0,404,404,"Ap. 270","",0,"","","",1,0,0,[],""],["frenk_t4-ap270-03",8,"Las que no se hayan casado\nno deben darse a la pena,\nvale más un taco en casa\nque cien platos en la ajena.",166,2,-1,190,"LA CASADA",0,4,"ea",59,0,-1,0,404,404,"Ap. 270","",0,"","","",1,0,0,[],""],["frenk_t4-ap270-04",8,"Cuando yo andaba de novia,\nme ofrecían leche y frijoles,\nhora son gordas con chile,\npa tomar jarros de atole.",166,2,-1,190,"LA CASADA",3,4,"oe",-1,0,-1,0,404,404,"Ap. 270","",0,"","","",1,0,0,[],""],["frenk_t4-ap270-05",8,"La mujer engaña al hombre\nsi la tiene muerta de hambre;\npero si es el gusto de él,\nhasta la coyunda lambe.",166,2,-1,190,"LA CASADA",0,4,"ae",-1,0,-1,0,404,404,"Ap. 270","",0,"","","",1,0,0,[],""],["frenk_t4-ap270-06",8,"Todos dicen ser muy gallos,\nodos dicen ser muy machos,\ntero son desobligados,\nidemás de ser borrachos.",166,2,-1,190,"LA CASADA",0,4,"ao",-1,0,-1,0,404,404,"Ap. 270","",0,"","","",1,0,0,[],""],["frenk_t4-ap270-07",8,"No quiero morirme de hambre\nsiendo la mujer más buena;\nvale más ser de las malas,\npero con barriga llena.",166,2,-1,190,"LA CASADA",0,4,"ea",59,0,-1,0,404,404,"Ap. 270","",0,"","","",1,0,0,[],""],["frenk_t4-ap272-01",8,"De que el gallo se sacude,\nen medio del árbol canta;\nel que duerme en cama ajena,\nmuy temprano se levanta.",166,2,-1,190,"EL QUE DUERME EN CAMA AJENA",0,4,"aa",148,0,-1,0,405,405,"Ap. 272","",0,"","","",1,0,0,[],""],["frenk_t4-ap272-02",8,"Quien trata mujer ajena\ny de noche la va a ver,\nal tiempo de amanecer\nes más doblada su pena.\nEsa noche se enajena\nen el rocío más que sude,\nsi hay campo en que se desnude;\nde que ya el día le amenaza,\nsale en cueros de la casa,\nde que el gallo se sacude.",166,2,-1,190,"EL QUE DUERME EN CAMA AJENA",18,10,"ue",215,0,-1,0,405,405,"Ap. 272","",0,"","","",1,0,0,[],""],["frenk_t4-ap272-03",8,"Se suelta un madrugador\na cantar duro y tupido,\naunque tenga un pie dormido,\nél corre que es un primor;\nél se va ciego de amor,\ncualesquier bulto le espanta,\nse le seca la garganta,\nno halla bartolos que echar,\nde que el gallo empieza a alear\ny en medio del árbol canta.",166,2,-1,190,"EL QUE DUERME EN CAMA AJENA",18,10,"aa",148,0,-1,0,405,405,"Ap. 272","",0,"","","",1,0,0,[],""],["frenk_t4-ap272-04",8,"Si le guardan qué cenar,\nla cena con grande empeño,\npero ínter que viene el dueño,\nni recio puede mascar;\nno puede destornudar\ny mayor si oye que truena,\ny si alguna puerta suena,\nse le reseca el pescuezo,\nno puede resollar recio\nel que duerme en cama ajena.",166,2,-1,190,"EL QUE DUERME EN CAMA AJENA",18,10,"ea",59,0,-1,0,405,405,"Ap. 272","",0,"","","",1,0,0,[],""],["frenk_t4-ap272-05",8,"Si él es demasiado flojo\ny no sabe madrugar,\nel pobre se ha de excusar\npor no aguantar un sonrojo;\nesté manco o esté cojo,\nsi el gallo canta seguido,\naunque tenga un pie dormido,\nmirando por dónde arranca,\ncon calzones en la mano\nmuy temprano se levanta.",166,2,-1,190,"EL QUE DUERME EN CAMA AJENA",18,10,"aa",-1,0,-1,0,405,405,"Ap. 272","",0,"","","",1,0,0,[],""],["frenk_t4-ap274-02",8,"¿No ha visto nada endiablado?,\n¿no ha visto nada hablador?\n¿No ha visto nada pelado?,\ny si lo vido, ¿qué señas me da?",166,2,-1,190,"JARABE TAPATÍO III",3,4,"a",-1,0,-1,0,406,406,"Ap. 274","",0,"","","",1,0,0,[],""],["frenk_t4-ap274-04",8,"Tiene su pechito prieto,\nsu hociquito colorado\ncon la lengüita de fuera\ncual si estuviera asoleado.",166,2,-1,190,"JARABE TAPATÍO III",0,4,"ao",14,0,-1,0,406,406,"Ap. 274","",0,"","","",1,0,0,[],""],["frenk_t4-ap275-02",8,"Se lo cortó y se lo cortó,\nse lo comió,\ny yo cortando me quedé,\nsaboreando me quedé\ncon mi sebo de panal,\ny hasta un perro me tiró,\npero yo no sé de qué.",170,2,7,190,"CANCIÓN DEL PANAL",4,7,"e",77,0,-1,0,406,406,"Ap. 275","",0,"","","",1,0,0,[],""],["frenk_t4-ap276-02",8,"Ayer, día 22 de marzo,\nse comenzaron mis muinas.\n¡Ay!, cuando comencé a sentir\nla comezón de las juinas.\nEl cuatro y las cuatro esquinas.\n¡Ay!, me agarró una comezón,\ntuve sobrada razón.\n¡Ay!, diablo de tierra caliente,\nporque habla y dice la gente:\n“¡Ay!, uñas, ¿para cuándo son?”",176,2,3,190,"VALONA DE LAS JUINAS",18,10,"o",31,0,-1,0,406,406,"Ap. 276","",0,"","","",1,0,0,[],""],["frenk_t4-ap276-03",8,"¡Ay!, el que en este punto esté\no que viva más acá,\n¡Ay!, nunca dice la verdad,\nporque seguido se ve.\nYo la verdad les diré:",176,2,3,190,"VALONA DE LAS JUINAS",7,5,"e",77,0,-1,0,406,406,"Ap. 276","",0,"","","",1,0,0,[],""],["frenk_t4-ap276-04",8,"¡Ay!, es una ingrata pasión,\nporque hay juinas de a montón.\n¡Ay!; más prisión que Escobedo,\nporque habla y dice el bracero:\n“Uñas, ¿para cuándo son?”.",176,2,3,190,"VALONA DE LAS JUINAS",7,5,"o",31,0,-1,0,406,406,"Ap. 276","",0,"","","",1,0,0,[],""],["frenk_t4-ap276-05",8,"¡Ay!, siempre la ausencia me mata,\nporque el padecer no es justo.\nJAy!, siempre vivo con el susto\nde tanta nación ingrata.\n¡Ay!, también sansaguarituricata,\n¡ay!, también otra nación,\nque si ocupa el pabellón.\n¡Ay!, el jején y el zancudo\nhacen hablar al que es mudo:\n“Uñas, ¿para cuándo son?”",176,2,3,190,"VALONA DE LAS JUINAS",18,10,"o",31,0,-1,0,406,406,"Ap. 276","",0,"","","",1,0,0,[],""],["frenk_t4-ap276-06",8,"¡Ay!, al fin, la juina primero,\nel sansacuate enseguida;\nla turicata escondida\nsabe picar muy ligero;\nel jején, también grosero,\n¡ay!, de noche da su función;\nel zancudo una canción\n¡ay!, canta con mucha alegría,\nsea de noche, sea de día.\nUñas, ¿para cuándo son?",176,2,3,190,"VALONA DE LAS JUINAS",18,10,"o",31,0,-1,0,407,407,"Ap. 276","",0,"","","",1,0,0,[],""],["frenk_t4-ap276-07",8,"¡Ay!, voy a echar mi despedida\npor el ojo de una aguja;\n¡ay!, la que es mujer se sostiene,\ny el que es hombre no más puja.",176,2,3,190,"VALONA DE LAS JUINAS",0,4,"ua",586,0,-1,0,407,407,"Ap. 276","",0,"frenk_t2","","",2,0,0,[],""],["frenk_t4-ap276-08",8,"Se las vuelvo a referir,\n¡ay!, con tinta y papel sellado;\nmas no dejen de saber\nque el que cantó aquí es su criado.",176,2,3,190,"VALONA DE LAS JUINAS",3,4,"ao",14,0,-1,0,407,407,"Ap. 276","",0,"","","",2,0,0,[],""],["frenk_t4-ap277-01",8,"Atención todos para escuchar;\nla triste historia voy a cantar\nde una tortuga que un día fatal\nquiso su suerte pasar muy mal.",169,2,8,190,"LA TORTUGA II",3,4,"a",1,0,-1,0,407,407,"Ap. 277","",0,"","","",1,0,0,[],""],["frenk_t4-ap277-03",8,"En vano, amigo, quise ocultar\na la tortuga del grave mal,\nla pobrecita en un costal\nse muere ahogada, se ha de enredar.",169,2,8,190,"LA TORTUGA II",3,4,"a",-1,0,-1,0,407,407,"Ap. 277","",0,"","","",1,0,0,[],""],["frenk_t4-ap277-04",8,"Los mareñitos al pasar\nvieron a este pobre animal,\ny lo agarran para llevar\na su gran banquete nupcial.",169,2,8,190,"LA TORTUGA II",1,4,"a",-1,0,-1,0,407,407,"Ap. 277","",0,"","","",1,0,0,[],""],["frenk_t4-ap277-05",8,"Uno con su modo de hablai\nle dice al otro: “Tabor, tabor\nTreitu tortugo voy agarrar;\npara mi esposa voy a cazar”.",169,2,8,190,"LA TORTUGA II",3,4,"a",21,0,-1,0,407,407,"Ap. 277","",0,"","","",1,0,0,[],""],["frenk_t4-ap278-01",8,"En unos surcos de milpa\nandaba un tejón\ncon su brazada de elotes\nenvueltos en su cotón.",170,2,7,190,"EL TEJONCITO",0,4,"o",31,0,-1,0,407,407,"Ap. 278","",0,"","","",1,0,0,[],""],["frenk_t4-ap278-02",8,"Sus hijos y su mujer\nlo salieron [a] encontrar;\nse metieron pa su cocina\ny los pusieron [a] asar.",170,2,7,190,"EL TEJONCITO",0,4,"a",21,0,-1,0,407,407,"Ap. 278","",0,"","","",1,0,0,[],""],["frenk_t4-ap278-03",8,"Un tejoncito atrevido,\ncon su grande atrevimiento,\nse sacó uno de la lumbre,\nse lo metió por dentro.",170,2,7,190,"EL TEJONCITO",0,4,"eo",-1,0,-1,0,407,407,"Ap. 278","",0,"","","",1,0,0,[],""],["frenk_t4-ap278-04",8,"Lo vido su mamá agarrar\nuna cuarta muy gruesa:\n“Hora verás, goloso,\nespérate que se cueza.”",170,2,7,190,"EL TEJONCITO",0,4,"ea",108,0,-1,0,407,407,"Ap. 278","",0,"","","",1,0,0,[],""],["frenk_t4-ap279-01",8,"¡Qué bonita está la milpa!,\ntupida de mirasol,\ncuando sazona el jilote\ny está lloviendo con sol.",170,2,7,190,"QUÉ BONITA ESTÁ LA MILPA",0,4,"o",24,0,-1,0,408,408,"Ap. 279","",0,"","","",1,0,0,[],""],["frenk_t4-ap279-02",8,"Pájaros madrugadores\nme enseñaron la canción;\ny entono otra del arado\ncuando llora el corazón.",170,2,7,190,"QUÉ BONITA ESTÁ LA MILPA",0,4,"o",31,0,-1,0,408,408,"Ap. 279","",0,"","","",1,0,0,[],""],["frenk_t4-ap279-03",8,"Granito que has de comer,\ngranito que has de sembrar;\nsi cosecha quieres ver,\nantes tienes que sudar.",170,2,7,190,"QUÉ BONITA ESTÁ LA MILPA",1,4,"a",21,0,-1,0,408,408,"Ap. 279","",0,"","","",1,0,0,[],""],["frenk_t4-ap279-04",8,"Mis bueyes jalan parejo\ny aunque cale fuerte el sol;\nuno se llama El Cangrejo\ny el otro se llama El Frijol.",170,2,7,190,"QUÉ BONITA ESTÁ LA MILPA",3,4,"o",24,0,-1,0,408,408,"Ap. 279","",0,"","","",1,0,0,[],""],["frenk_t4-ap279-05",8,"A lo lejos la humareda\nque sale de mi jacal,\ndonde está mi mamacita\nremoliendo el nixtamal.",170,2,7,190,"QUÉ BONITA ESTÁ LA MILPA",0,4,"a",1,0,-1,0,408,408,"Ap. 279","",0,"","","",1,0,0,[],""],["frenk_t4-ap279-06",8,"Yo siembro para toditos;\nsoy amigo de verdad,\nasí han de ser de parejos\nlos de la comunidad.",170,2,7,190,"QUÉ BONITA ESTÁ LA MILPA",0,4,"a",16,0,-1,0,408,408,"Ap. 279","",0,"","","",1,0,0,[],""],["frenk_t4-ap279-07",8,"Que cuando siembren granito,\nsiembren para los demás;\nque no haiga pobres ni ricos:\ntrabajadores no más.",170,2,7,190,"QUÉ BONITA ESTÁ LA MILPA",0,4,"a",51,0,-1,0,408,408,"Ap. 279","",0,"","","",1,0,0,[],""],["frenk_t4-ap280-01",8,"Tengo una carreta\nmuy rechinadora;\ncuando voy al pueblo\nsiempre se me atora.",166,2,-1,190,"LA CARRETA",0,4,"oa",107,0,-1,0,408,408,"Ap. 280","",0,"","","",1,0,0,[],""],["frenk_t4-ap280-02",8,"Ya mis bueyes flacos\nno quieren jalar;\nno traigo pastura\nni con qué comprar.",166,2,-1,190,"LA CARRETA",0,4,"a",21,0,-1,0,408,408,"Ap. 280","",0,"","","",1,0,0,[],""],["frenk_t4-ap280-03",8,"A veces tardamos\nmucho en regresar,\ny luego Enriqueta\nse empieza a enojar.",166,2,-1,190,"LA CARRETA",0,4,"a",21,0,-1,0,408,408,"Ap. 280","",0,"","","",1,0,0,[],""],["frenk_t4-ap280-04",8,"—No te enojes, vieja,\nno te enojes, Queta:\nmira cómo jalan\nlos bueyes la carreta.",166,2,-1,190,"LA CARRETA",0,4,"ea",200,0,-1,0,408,408,"Ap. 280","",0,"","","",1,0,0,[],""],["frenk_t4-ap280-05",8,"—No me enojo, viejo,\nno me juzgues mal;\nporque al cabo un día\nvamos a llegar.",166,2,-1,190,"LA CARRETA",0,4,"a",-1,0,-1,0,408,408,"Ap. 280","",0,"","","",1,0,0,[],""],["frenk_t4-ap280-06",8,"—Jueta, bueyes flojos,\nhora no hay que ser:\npues allá en el rancho\ntienen qué comer.",166,2,-1,190,"LA CARRETA",0,4,"e",20,0,-1,0,408,408,"Ap. 280","",0,"","","",1,0,0,[],""],["frenk_t4-ap281-01",8,"¡Ay!, qué destino tan cabrón\ntienen los tiradores;\n¡ay!, no alcanzan para cotón,\ncontimás para calzones.",176,2,3,190,"EL TIRADOR II",0,4,"oe",-1,0,-1,0,408,408,"Ap. 281","",0,"","","",1,0,0,[],""],["frenk_t4-ap281-02",8,"¡Ay!, que harían petardos\ny balas de pólvora en un frasco;\n¡ay!, cuando vienen de tirar,\nvienen a dar que es un asco.\nEstudiando para contar,\n¡ay!, diciendo fue jacalón,\nse la medí al corazón;\n¡ay!, dejan sangrita en el pelo,\nluego se van por los perros:\n¡qué destino tan cabrón!",176,2,3,190,"EL TIRADOR II",18,10,"o",31,0,-1,0,409,409,"Ap. 281","",0,"","","",1,0,0,[],""],["frenk_t4-ap281-03",8,"¡Ay!, con sus garras de sombrero,\ncon la falda arriscadita,\n¡ay!, se pasan los días enteros\nmirando las pisaditas.\nDeseando siquiera verlos,\n¡ay!, también echan borrones;\nle tiran a los troncones\n¡ay!, pensando que son venados,\npero como ya están salados\nno alcanzan ni pa calzones.",176,2,3,190,"EL TIRADOR II",18,10,"oe",34,0,-1,0,409,409,"Ap. 281","",0,"","","",1,0,0,[],""],["frenk_t4-ap281-04",8,"¡Ay!, cuando llegan a tirar,\nlos más se los llevan heridos.\n¡Ay!, cuando los hallan perdidos,\nya no les sirve ni el cuero.\nRecibí gran desconsuelo,\n¡ay!, como fue de los mejores,\nse tomó por esos sones,\n¡ay! por no haber sido zahorín.\nAmigo, pues este fin\ntienen los tiradores.",176,2,3,190,"EL TIRADOR II",18,10,"oe",-1,0,-1,0,409,409,"Ap. 281","",0,"","","",1,0,0,[],""],["frenk_t4-ap281-06",8,"¡Ay!, que se haga mitadera,\nno alcanza perdón de Dios;\n¡ay!, sólo de hambre mata amor,\nno contando la primera,\ncamina por la ladera,\n¡ay!, sin pronunciar más razón,\ncazándola como un león.\n¡Ay! matan una por evento,\nno alcanzan pa bastimento,\ncontimás para cotón.",176,2,3,190,"EL TIRADOR II",18,10,"o",31,0,-1,0,409,409,"Ap. 281","",0,"","","",1,0,0,[],""],["frenk_t4-ap281-07",8,"¡Ay!, todos echan despedida,\npero no como la mía;\n¡ay!, antes de que naciera\ny naiden me conociera.",176,2,3,190,"EL TIRADOR II",5,4,"ea",44,0,-1,0,409,409,"Ap. 281","",0,"","","",1,0,0,[],""],["frenk_t4-ap281-08",8,"Se los vuelvo a repetir:\n¡ay!, con tinta y papel sellado,\npa que no se quede sin parte\nel clavel que está a mi lado.",176,2,3,190,"EL TIRADOR II",3,4,"ao",14,0,-1,0,409,409,"Ap. 281","",0,"","","",1,0,0,[],""],["frenk_t4-ap282-01",8,"Sol redondo y colorado\ncomo una rueda de cobre;\nde diario me estás mirando,\ny diario me miras pobre.",166,2,-1,190,"EL SOL",0,4,"oe",410,0,-1,0,409,409,"Ap. 282","",0,"","","",1,0,0,[],""],["frenk_t4-ap282-02",8,"Me miras con el arado,\nluego con la rozadera;\nuna vez en la llanura\ny otra vez en la ladera.",166,2,-1,190,"EL SOL",0,4,"ea",44,0,-1,0,409,409,"Ap. 282","",0,"","","",1,0,0,[],""],["frenk_t4-ap282-03",8,"Me miras lazando un toro,\nme ves amando un atajo;\npero diario me ves pobre,\ncomo todos los de abajo.",166,2,-1,190,"EL SOL",0,4,"ao",168,0,-1,0,409,409,"Ap. 282","",0,"","","",1,0,0,[],""],["frenk_t4-ap282-04",8,"Sol, tú que eres tan parejo\npara repartir la luz,\nhabías de enseñar al amo\na ser lo mismo que tú.",166,2,-1,190,"EL SOL",0,4,"u",-1,0,-1,0,409,409,"Ap. 282","",0,"","","",1,0,0,[],""],["frenk_t4-ap282-05",8,"No que el amo nos hambrea\ny nos pega y nos maltrata,\nmientras en nosotros tiene\nuna minita de plata.",166,2,-1,190,"EL SOL",0,4,"aa",74,0,-1,0,409,409,"Ap. 282","",0,"","","",1,0,0,[],""],["frenk_t4-ap283-01",8,"Ni el sol ni el agua me arredran\npor cumplir con mi deber:\nque es trabajar diariamente\npara tener qué comer.",166,2,-1,190,"LA MATRACA DEL BARRENDERO",0,4,"e",20,0,-1,0,410,410,"Ap. 283","",0,"","","",1,0,0,[],""],["frenk_t4-ap283-02",8,"Para mi diario sustento\nmi sueldo apenas alcanza;\ny en las fiestas de cada año\ncifro toda mi esperanza.",166,2,-1,190,"LA MATRACA DEL BARRENDERO",0,4,"aa",163,0,-1,0,410,410,"Ap. 283","",0,"","","",1,0,0,[],""],["frenk_t4-ap283-03",8,"Con ello tengo un respiro,\npues los nobles corazones\nse duelen de mis congojas\ncon sus gratificaciones.",166,2,-1,190,"LA MATRACA DEL BARRENDERO",0,4,"oe",34,0,-1,0,410,410,"Ap. 283","",0,"","","",1,0,0,[],""],["frenk_t4-ap283-04",8,"Espero que ahora me obsequie\ny pido a Dios agradecido\nque le dé sus bendiciones\npor haberme socorrido.",166,2,-1,190,"LA MATRACA DEL BARRENDERO",0,4,"io",101,0,-1,0,410,410,"Ap. 283","",0,"","","",1,0,0,[],""],["frenk_t4-ap284-01",8,"Bástanle desdicha tiene\nel que a tierra ajena va;\ntodos lo miran y dicen:\n“Éste ¿qué mañas tendrá?’’",171,2,4,190,"BASTANTE DESDICHA TIENE",0,4,"a",9,0,-1,0,410,410,"Ap. 284","",0,"","","",1,0,0,[],""],["frenk_t4-ap284-02",8,"Ha de ser muy obediente\ny de buenos procederes;\nevitar de sus placeres,\ndirigirse por el tiempo;\nha de dar conocimiento\nde la tierra donde viene,\nhacer cuanto se le ordene;\nesto a mí ya me pasó,\ny si es solo como yo,\nbastante desdicha tiene.",171,2,4,190,"BASTANTE DESDICHA TIENE",18,10,"ee",70,0,-1,0,410,410,"Ap. 284","",0,"","","",1,0,0,[],""],["frenk_t4-ap284-03",8,"El que sale a aventurar\ngoza dos mil desventuras;\nlo regañan las criaturas\ny se tiene que callar;\nporque si quiere pelear,\nel juez lo castigará;\ndeclaraciones dará,\nle pondrán en cierta casa;\ntodas estas penas pasa\nel que a tierra ajena vq.",171,2,4,190,"BASTANTE DESDICHA TIENE",18,10,"",-1,0,-1,0,410,410,"Ap. 284","",0,"","","",1,0,0,[],""],["frenk_t4-ap284-04",8,"Si no tiene algún amigo\nque lo conozca al llegar,\nlo ven en aquel lugar\ncomo al fin desconocido;\nha de vivir sumergido\ntodo lo feliz que pise;\nsin que nada le precise,\nsiempre al hablar es muy fino;\nsin saber de dónde vino\ntodos lo miran y dicen.",171,2,4,190,"BASTANTE DESDICHA TIENE",18,10,"ie",-1,0,-1,0,410,410,"Ap. 284","",0,"","","",1,0,0,[],""],["frenk_t4-ap284-05",8,"En fin, si es enamorado\ntiene que disimular;\npero ellas han de indagar\nque si es soltero o casado;\nle ponen mucho cuidado\nal saber de’onde vendrá,\nse juntan ellas por allá\npara hablar de aquello bien\ny dicen cuando lo ven:\n“Éste ¿qué mañas tendrá?\"",171,2,4,190,"BASTANTE DESDICHA TIENE",18,10,"a",9,0,-1,0,410,410,"Ap. 284","",0,"","","",1,0,0,[],""],["frenk_t4-ap285-01",8,"Conmigo estaba durmiendo\ncuando este señor me habló;\n¡ay!, qué caramba es el miedo\nque el sueño se me quitó.",175,2,6,190,"EL MIEDO",0,4,"o",2,0,-1,0,410,410,"Ap. 285","",0,"","","",1,0,0,[],""],["frenk_t4-ap285-02",8,"Con mi guitarra en la mano\nrecordé de toda prisa,\nque hasta me caiba de risa\nde oír a este ciudadano;\nyo le digo muy ufano:\nde mi amigo me estoy riendo;\npero si usted está creyendo\nque despluma a este pollito,\npues espérese tantito\nque ya me estaba durmiendo.",175,2,6,190,"EL MIEDO",18,10,"eo",52,0,-1,0,411,411,"Ap. 285","",0,"","","",1,0,0,[],""],["frenk_t4-ap285-03",8,"Dispénseme, trovador,\nel que no había despertado;\npero aquí, en este tablado,\naquí está su servidor;\naunque me agarra un temblor\nde ese grito que le echó,\nal pronto despierto yo\ny observar su gritería;\npues ya mero me dormía\ncuando usted, señor, me habló.",175,2,6,190,"EL MIEDO",18,10,"o",2,0,-1,0,411,411,"Ap. 285","",0,"","","",1,0,0,[],""],["frenk_t4-ap285-04",8,"De sorpresa me agarró\nque me dijo el violinero:\n“Oiga al otro guitarrero”;\ny pronto despierto yo.",175,2,6,190,"EL MIEDO",11,4,"o",2,0,-1,0,411,411,"Ap. 285","",0,"","","",1,0,0,[],""],["frenk_t4-ap285-05",8,"“Aquí vengo yo”,\ny me agacho mi sombrero,\ny me quedo imaginando;\npero yo estoy temblando\n/qy/, qué caramba es el miedo.",175,2,6,190,"EL MIEDO",7,5,"eo",-1,0,-1,0,411,411,"Ap. 285","",0,"","","",1,0,0,[],""],["frenk_t4-ap285-06",8,"En fin, después del temblor,\notra cosa estoy pensando:\nque usted se está imaginando\nque a mí me falta valor.\nNo se equivoque, señor,\nsegún se lo digo yo:\nsu amigo ya despertó\nsoñando que usted callaba,\na los gritos que me echaba,\nel sueño se me quitó.",175,2,6,190,"EL MIEDO",18,10,"o",2,0,-1,0,411,411,"Ap. 285","",0,"","","",1,0,0,[],""],["frenk_t4-ap286-01",8,"Me dicen que soy coqueta,\nque padezco mal de amor,\npero al mundo no le importa;\ntengo alegre el corazón.",166,2,-1,190,"AL COMPÁS DEL TREINTA-TREINTA",0,4,"o",-1,0,-1,0,411,411,"Ap. 286","",0,"","","",2,0,0,[],""],["frenk_t4-ap286-02",8,"Nací entre carrizales,\na la sombra de un nopal;\nde cuero eran mis pañales,\nmi mamita un pedernal.",166,2,-1,190,"AL COMPÁS DEL TREINTA-TREINTA",1,4,"a",1,0,-1,0,411,411,"Ap. 286","",0,"","","",1,0,0,[],""],["frenk_t4-ap286-03",8,"Mi cuna, ramas de hiedra,\ny mi arrullo, el huracán;\nmis juguetes, las culebras\ny también el alacrán.",166,2,-1,190,"AL COMPÁS DEL TREINTA-TREINTA",0,4,"a",147,0,-1,0,411,411,"Ap. 286","",0,"","","",1,0,0,[],""],["frenk_t4-ap286-05",8,"Con música de guitarra\ny compás de treinta-treinta,\ncon píldoras de cananas\ncelebraron esa fiesta.",166,2,-1,190,"AL COMPÁS DEL TREINTA-TREINTA",0,4,"ea",-1,0,-1,0,411,411,"Ap. 286","",0,"","","",1,0,0,[],""],["frenk_t4-ap286-06",8,"Me pusieron Guadalupe;\nquedé dormida yo.\nLo demás ya no lo supe;\ncon eso les digo adiós.",166,2,-1,190,"AL COMPÁS DEL TREINTA-TREINTA",0,4,"o",-1,0,-1,0,411,411,"Ap. 286","",0,"","","",1,0,0,[],""],["frenk_t4-ap287-01",8,"Si acaso no me conoces,\nyo me daré a conocer:\nFulano de Tal me llamo,\nmarido de mi mujer.",171,2,4,190,"SI ACASO NO ME CONOCES",0,4,"e",20,0,-1,0,411,411,"Ap. 287","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap287-02",8,"Vivo enfrente de un lugar,\nen una casa parada\nque, encontrándola cerrada,\nno tienes por dónde entrar,\ny si me vas a buscar\ny no me hallas, y echas voces,\naunque las eches atroces,\nciertas noticias te doy:\nhijo de mi madre soy,\nsi acaso no me conoces.",171,2,4,190,"SI ACASO NO ME CONOCES",18,10,"oe",205,0,-1,0,412,412,"Ap. 287","",0,"","","",1,0,0,[],""],["frenk_t4-ap287-03",8,"Pregunta por “el Cuadrado”,\nel tocador de vihuela,\nyo soy nieto de mi abuela,\nun hombre grueso y delgado,\nmoreno, muy colorado;\nde estatura, a mi entender,\nalto y bajo vengo a ser,\ncomo bien te habrás fijado;\nsi no me hubieras hallado,\nyo me daré a conocer.",171,2,4,190,"SI ACASO NO ME CONOCES",18,10,"e",20,0,-1,0,412,412,"Ap. 287","",0,"","","",1,0,0,[],""],["frenk_t4-ap287-04",8,"Si el pueblo ya se acabó\ny no me habías encontrado,\nvuelve a andar lo que has andado,\nque adelante vivo yo.\nNo me solicites, no;\nde mí no hagas reclamo\ny di que de veras te amo\ny te quiero como amigo;\nmi nombre que tengo, digo:\nFulano de Tal me llamo.",171,2,4,190,"SI ACASO NO ME CONOCES",18,10,"ao",100,0,-1,0,412,412,"Ap. 287","",0,"","","",1,0,0,[],""],["frenk_t4-ap287-05",8,"Las maderas son de pino,\nno tienes ni qué dudar,\nmi casa viene a quedar\nenfrente de mi vecino,\nven por el mismo camino\ncuando me vengas a ver,\ny si no lo quieres creer,\nharé dos mil regocijos,\nyo soy padre de mis hijos,\nmarido de mi mujer.",171,2,4,190,"SI ACASO NO ME CONOCES",18,10,"e",20,0,-1,0,412,412,"Ap. 287","",0,"","","",1,0,0,[],""],["frenk_t4-ap288-01",8,"¡Ay, chivarras coloradas!,\ncuánto me gusta el mitote;\nmuchachas entusiasmadas,\nde veras soy hombrezote;\naquí traigo mi garrote,\npues peleo hasta con el diablo;\nse lo juro por San Pablo,\nque me atoro con Juan Cuerdas;\nyo con los malditos hablo:\nespántenselas siquiera.",166,2,-1,190,"EL COSTEÑO",18,10,"ea",-1,0,-1,0,412,412,"Ap. 288","",0,"","","",3,0,0,[],""],["frenk_t4-ap288-02",8,"Hoy lo veremos, muchachos,\nno digan que soy su guaje;\nhoy los hago chicharrones\naunque les cause coraje;\nno digan que soy salvaje,\nyo soy la purita espuma,\nmejor que la miel de tuna\nque da gusto al paladar:\n“Óigame, usted, doña Bruna,\nno se las deje pegar.”",166,2,-1,190,"EL COSTEÑO",18,10,"a",21,0,-1,0,412,412,"Ap. 288","",0,"","","",1,0,0,[],""],["frenk_t4-ap288-03",8,"Vamos a empinar la huila,\n¿qué nos ha de suceder?\nAllá viene Petronila\ny creo sale del taller;\npues es lo mismo que antier,\nlo mucho que a mí me importa;\nsi alguno quiere la torta,\nvamos., pues, a trabajar,\nque en esta tierra y en la otra\nno me las dejo pegar.",166,2,-1,190,"EL COSTEÑO",18,10,"a",21,0,-1,0,412,412,"Ap. 288","",0,"","","",1,0,0,[],""],["frenk_t4-ap288-04",8,"Oiga usted, doña Simona:\n¿qué ya no me hace cabal?\nDígale a mi rechulona\nque la espero en el portal.\nNo se me empiece a arrugar,\nni tampoco le haga ceja,\nvamos a tomar cerveza\na casa de don Marcial:\nvaledores de la empresa,\nno se las dejen pegar.",166,2,-1,190,"EL COSTEÑO",18,10,"a",-1,0,-1,0,413,413,"Ap. 288","",0,"","","",1,0,0,[],""],["frenk_t4-ap288-05",8,"Muchachitos de la nueva,\ndel año noventa y nueve,\ny aunque el demonio me lleve\n¿quieren?, les daré la prueba;\nyo me enredo con cualquiera\nporque soy muy hombrecito.\nNo digan que soy indito\nni que vengo de la sierra,\npero aunque no soy maldito,\nme las espanto siquiera.",166,2,-1,190,"EL COSTEÑO",18,10,"ea",-1,0,-1,0,413,413,"Ap. 288","",0,"","","",1,0,0,[],""],["frenk_t4-ap288-06",8,"No le hace que sean la fiebre,\nyo también soy de la ordeña,\ny también me vuelvo liebre\ncuando miro a una trigueña.\nPero botella bien llena\nde aguardiente o de mezcal,\naunque vale medio real,\neso y mucho más le diera:\nmuchachitas del rabiar,\nespántenselas siquiera.",166,2,-1,190,"EL COSTEÑO",18,10,"ea",44,0,-1,0,413,413,"Ap. 288","",0,"","","",1,0,0,[],""],["frenk_t4-ap288-07",8,"A mí no me importa nada\nel que sea de Alicaísco;\nsoy de la pelea pasada,\nde adelante de Jalisco;\nYo para pelear soy listo,\npues ni a la muerte le temo;\nno le hace que sea veneno,\nyo lo creería si lo viera;\ny le digo al que sea bueno:\nespánteselas siquiera.",166,2,-1,190,"EL COSTEÑO",18,10,"ea",44,0,-1,0,413,413,"Ap. 288","",0,"","","",3,0,0,[],""],["frenk_t4-ap288-08",8,"Mírenme, no soy tan viejo,\npero he andado bien la bola;\npor señas que no me dejo\nlos chayotes en la cola;\na mí ninguno me embola\nporque he sido misionero;\nme pongo en el avispero\ny tengo ley verdadera.\n“Oiga, amigo papelero,\nespánteselas siquiera.”",166,2,-1,190,"EL COSTEÑO",18,10,"ea",44,0,-1,0,413,413,"Ap. 288","",0,"","","",1,0,0,[],""],["frenk_t4-ap288-09",8,"Amigo guanajuateño,\nque te tienes por valiente,\nyo soy purito costeño,\nde las costas del Poniente.\nMe acuerdo que soy la gente\ny en cualquier gancho me atoro;\nyo a ningún gallo le lloro,\naunque el mismo diablo fuera;\nyo soy el mentado Rorro:\nespánteselas siquiera.",166,2,-1,190,"EL COSTEÑO",18,10,"ea",44,0,-1,0,413,413,"Ap. 288","",0,"","","",1,0,0,[],""],["frenk_t4-ap288-10",8,"Amigo, para que vea,\nnos está llevando el río;\nya nos anda con el frío,\npero siempre en la pelea.\n¿Y qué le parece Andrea?\nVamos a rifar la suerte,\na jugar un peso fuerte\ncon los que vienen de fuera.\n¿No ve que dirá la muerte:\nespánteselas siquiera?",166,2,-1,190,"EL COSTEÑO",18,10,"ea",44,0,-1,0,413,413,"Ap. 288","",0,"","","",1,0,0,[],""],["frenk_t4-ap288-11",8,"Muchachos carcamaneros,\n¿por qué hacen tantos corajes?\nCuando la rana críe pelos,\nentonces caerán los majes.\nPues dizque no son tan guajes,\nni jueguen la lotería,\nmas creo que ya es mediodía,\ny ahí viene la chimolera\ny me dice: vida mía,\nespánteselas siquiera.",166,2,-1,190,"EL COSTEÑO",18,10,"ea",44,0,-1,0,413,413,"Ap. 288","",0,"","","",1,0,0,[],""],["frenk_t4-ap289-01",8,"Aquí está el guanajuateño\ncon su sombrero de lado,\nque anda buscando al costeño,\nque de a tiro lo han tanteado\ncon mi vale el pachuqueño\nque es, como yo, renombrado.",166,2,-1,190,"EL GUANAJUATEÑO",9,6,"ao",14,0,-1,0,413,413,"Ap. 289","",0,"","","",2,0,0,[],""],["frenk_t4-ap289-02",8,"Soy de mero Guanajuato,\nnacido en el Cantador,\nsoy de los meros valientes,\narrojado, no hablador;\nsi usted quiere, valedor,\njugar un rato conmigo,\ntráteme mejor de amigo:\n¡Por Dios!, que si se me enoja\ny quiere bajar a la agua,\nni los zapatos me moja.",166,2,-1,190,"EL GUANAJUATEÑO",18,10,"oa",146,0,-1,0,414,414,"Ap. 289","",0,"","","",1,0,0,[],""],["frenk_t4-ap289-03",8,"¿Qué dice, vale costeño,\nusted que hora anda triunfando\ny que anda vociferando\ncon mi vale el pachuqueño?\nMe hace menos porque ando\nsin mi camisa y mi chata;\ntambién sé tirar mi plata,\ntambién me gusta brillarla;\npregúntele al vale Prieto\nlo que tiraba en la Cata.",166,2,-1,190,"EL GUANAJUATEÑO",18,10,"aa",-1,0,-1,0,414,414,"Ap. 289","",0,"","","",1,0,0,[],""],["frenk_t4-ap289-04",8,"Acércate, chata Juana,\nya ni me hagas renegar,\nni me quieras despreciar\nporque compraste tu indiana,\nsi ahora se te da la gana,\npéinate del arriscao\npara echártela de lao,\na mí no me importa nada:\nque tengo el alma curada\nde los espantos y el vaho.",166,2,-1,190,"EL GUANAJUATEÑO",18,10,"ao",653,0,-1,0,414,414,"Ap. 289","",0,"","","",1,0,0,[],""],["frenk_t4-ap289-05",8,"Aquí está el de Guanajuato\nque a nadie le pide nada,\nni siquiera una tostada\npara alimentarse un rato;\nno le hagan miau como al gato,\ny a la cañada no bajen,\nni mucho menos se encajen\narmándome una coton a,\nsi es que no quieren la gorda,\nni el ranchero, ni el salvaje.",166,2,-1,190,"EL GUANAJUATEÑO",18,10,"ae",-1,0,-1,0,414,414,"Ap. 289","",0,"","","",1,0,0,[],""],["frenk_t4-ap289-06",8,"¿Qué dice, vale Coyote?,\nvamos a echar la misión;\nno porque lo veo grandote\nle tengo ningún temor;\nsoy del puro Cantador,\nbarrio de la libertad;\nya les digo la verdad,\nsi no la quieren conmigo,\ntrátenme mejor de amigo;\nno es cochina mi amistad.",166,2,-1,190,"EL GUANAJUATEÑO",18,10,"a",16,0,-1,0,414,414,"Ap. 289","",0,"","","",1,0,0,[],""],["frenk_t4-ap289-07",8,"¿Qué dices, vale Tarasca,\nno has ido a ver a Martina,\nla hija de doña Agustina,\nla querida de Charrasca?\nSupongo quieren la frasca\ny desean vociferar,\nno me hagan desesperar,\nporque yo soy delicado,\nningún valedor, mi amigo,\nel cuerpo me ha manoseado.",166,2,-1,190,"EL GUANAJUATEÑO",18,10,"ao",14,0,-1,0,414,414,"Ap. 289","",0,"","","",1,0,0,[],""],["frenk_t4-ap289-08",8,"Oiga, manis, pachuqueño;\ncreo que usted es medio rejego,\nsi quiere la gorda luego,\nsáquese, no tenga miedo.\nUn puro guanajuateño\nse puede batir con treinta,\ny si quieren sus mercedes\nbajar hasta el socavón,\nbajen, que ésta es la ocasión\nde arreglarles bien la cuenta.",166,2,-1,190,"EL GUANAJUATEÑO",18,10,"ea",-1,0,-1,0,414,414,"Ap. 289","",0,"","","",1,0,0,[],""],["frenk_t4-ap289-09",8,"Aquí está el guanajuateño\ncon su sombrero de lado,\nque anda buscando al costeño\nque de a tiro se ha canteado;\naquí está su tío planchado;\nvengan para darles clase,\nlos tanteo muy amonados,\ny que son juiles se me hace;\npos donde yo pongo el pie,\nhasta ni el zacate nace.",166,2,-1,190,"EL GUANAJUATEÑO",18,10,"ae",84,0,-1,0,414,414,"Ap. 289","",0,"","","",2,0,0,[],""],["frenk_t4-ap289-10",8,"¡No se arruguen, valentones,\ntraigan dispuestos sus fierros,\nque aquí está el guanajuateño\npara darles sus lecciones!\nAcérquense los matones,\nque yo no les tengo miedo,\nfirme y parado me quedo\nesperando cuchilladas;\nme parecen enchiladas,\ny me trago las que pueda.",166,2,-1,190,"EL GUANAJUATEÑO",18,10,"ea",-1,0,-1,0,415,415,"Ap. 289","",0,"","","",1,0,0,[],""],["frenk_t4-ap289-12",8,"No crean que soy fantasioso,\nlo que digo es la verdad:\nel que quera retozar\nverá que no soy chismoso.\nSoy un poco cosquilloso\ny me bato con empeño,\nque lo diga el pachuqueño,\nmi querido valedor,\no el barrio del Cantador,\nmi pesadilla, mi sueño.",166,2,-1,190,"EL GUANAJUATEÑO",18,10,"eo",138,0,-1,0,415,415,"Ap. 289","",0,"","","",1,0,0,[],""],["frenk_t4-ap289-13",8,"A toditos les prevengo,\nvalientitos de a centavo,\nque soy en verdad muy bravo,\ny en decirlo me sostengo.\nSólo a mis brazos me atengo,\npues yo no me desbarato;\na cualquiera me echo al plato,\ny el que no lo quera creer,\nno más que me venga a ver:\nsoy de puro Guanajuato.",166,2,-1,190,"EL GUANAJUATEÑO",18,10,"ao",19,0,-1,0,415,415,"Ap. 289","",0,"","","",1,0,0,[],""],["frenk_t4-ap290-01",8,"Soy de puro Guanajuato,\ndonde se pasean los hombres;\ny espera, mi vida, un rato,\npa que de veras te asombres.",181,2,15,190,"SOY DE PURO GUANAJUATO",1,4,"oe",654,0,-1,0,415,415,"Ap. 290","",0,"","","",2,0,0,[],""],["frenk_t4-ap290-02",8,"Tengo mi patio delante\nporque soy puro bajío;\nte prometo ser constante\nsi me quieres, ángel mío.",181,2,15,190,"SOY DE PURO GUANAJUATO",1,4,"io",3,0,-1,0,415,415,"Ap. 290","",0,"","","",1,0,0,[],""],["frenk_t4-ap290-03",8,"Ya sabes que no me rajo,\nsi a gozar, si a padecer;\nquiero mujer y trabajo\npa poderla mantener.",181,2,15,190,"SOY DE PURO GUANAJUATO",1,4,"e",20,0,-1,0,415,415,"Ap. 290","",0,"","","",2,0,0,[],""],["frenk_t4-ap290-04",8,"Soy de Guanajuato puro,\nchorecheño nada más,\ny en las minas, te aseguro,\nno he de pandearme jamás.",181,2,15,190,"SOY DE PURO GUANAJUATO",1,4,"a",51,0,-1,0,415,415,"Ap. 290","",0,"","","",1,0,0,[],""],["frenk_t4-ap290-05",8,"De Guanajuato he venido\npor ingratísimo amor;\ny a Guanajuato me vuelvo\ncon una nueva mujer.",181,2,15,190,"SOY DE PURO GUANAJUATO",5,4,"e",-1,0,-1,0,415,415,"Ap. 290","",0,"","","",1,0,0,[],""],["frenk_t4-ap291-01",8,"Angelina de mi vida:\nvengo a ver si te resuelves,\ny nos vamos a Juquila\npara el ocho de diciembre.",166,2,-1,190,"LA FERIA DE JUQUILA",0,4,"ee",-1,0,-1,0,415,415,"Ap. 291","",0,"","","",1,0,0,[],""],["frenk_t4-ap291-02",8,"Una feria tan mentada,\nque mucho te ha de gustar;\nvienen de distintas partes\na la Virgen adorar.",166,2,-1,190,"LA FERIA DE JUQUILA",0,4,"a",21,0,-1,0,415,415,"Ap. 291","",0,"","","",1,0,0,[],""],["frenk_t4-ap291-03",8,"Que toditos los lugares\nque tenemos que pasar,\nAngelina de mi vida,\nyo te los voy a enseñar.",166,2,-1,190,"LA FERIA DE JUQUILA",0,4,"a",21,0,-1,0,415,415,"Ap. 291","",0,"","","",1,0,0,[],""],["frenk_t4-ap291-04",8,"El distrito de Zaachila\nlo tendremos que pasar;\nsi ...........................\nla sierrita por igual.",166,2,-1,190,"LA FERIA DE JUQUILA",3,4,"a",-1,0,-1,0,415,415,"Ap. 291","",0,"","","",1,0,0,[],""],["frenk_t4-ap292-01",8,"Bonito Pinotepa;\nno soy coplero y te estoy cantando,\nporque nació en tu suelo\nla morenita que estoy amando.",169,2,8,190,"PINOTEPA",3,4,"ao",33,0,-1,0,416,416,"Ap. 292","",0,"","","",1,0,0,[],""],["frenk_t4-ap292-02",8,"Y me gustan tus mujeres;\ny por eso aunque no sepa,\nyo seguiré cantando:\n¡Viva la costa con Pinotepa!",169,2,8,190,"PINOTEPA",3,4,"ea",309,0,-1,0,416,416,"Ap. 292","",0,"","","",1,0,0,[],""],["frenk_t4-ap292-03",8,"Al pasar Tlacamama\nuna paloma dijo a mi oído:\n“Si vas a Pinotepa,\nverás qué flechas tira Cupido.”",169,2,8,190,"PINOTEPA",3,4,"io",101,0,-1,0,416,416,"Ap. 292","",0,"","","",1,0,0,[],""],["frenk_t4-ap292-05",8,"Eres, costeña, linda\ny eres hermosa y eres bonita,\ny bajo tus palmeras\neres la reina de Costa Chica.",169,2,8,190,"PINOTEPA",3,4,"ia",-1,0,-1,0,416,416,"Ap. 292","",0,"","","",1,0,0,[],""],["frenk_t4-ap297-02",8,"Bonita compañerita\nse ha venido usted a encontrar;\ndéjemela usted solita,\nque la voy a hacer bailar,\nque me baile “El ahualulco”,\n¡a ver si sabe bailar!",171,2,4,190,"LOS PANADEROS I",9,6,"a",-1,0,-1,0,418,418,"Ap. 297","",0,"","","",2,0,0,[],""],["frenk_t4-ap297-03",8,"¡Arriba los panaderos,\narriba, arriba y a trabajar!;\nque busque su compañero,\nque lo tiene que encontrar;\nque lo busque, que lo busque,\nque lo tiene que encontrar.",171,2,4,190,"LOS PANADEROS I",9,6,"a",-1,0,-1,0,418,418,"Ap. 297","",0,"","","",4,0,0,[],""],["frenk_t4-ap297-05",8,"¡Arriba los panaderos,\naniba, arriba y a trabajar!;\nque busque a su compañera,\nque la tiene que encontrar;\nque la busque, que la busque,\nque la tiene que encontrar.",171,2,4,190,"LOS PANADEROS I",9,6,"a",-1,0,-1,0,418,418,"Ap. 297","",0,"","","",4,0,0,[],""],["frenk_t4-ap297-06",8,"Bonita compañerita\nse ha venido usted a encontrar;\ny si no quiere salir,\nque le chiflarán, que le chiflarán;\nque le baile un “Ahualulco”,\n¡a ver si sabe bailar!",171,2,4,190,"LOS PANADEROS I",9,6,"a",-1,0,-1,0,418,418,"Ap. 297","",0,"","","",2,0,0,[],""],["frenk_t4-ap297-08",8,"Déjemela usted solita,\nque ahora me la va a pagar;\ny si no quiere salir,\nle chiflarán, que le chiflarán;\nque le toquen “El Colás”,\nque la quiero ver bailar.",171,2,4,190,"LOS PANADEROS I",9,6,"a",-1,0,-1,0,418,418,"Ap. 297","",0,"","","",1,0,0,[],""],["frenk_t4-ap298-07",8,"Daré mi rúbrica o firma\nen convenio de amistad\nque nos hemos ofrecido\nen vuestra salutación;\ny al sentirnos instruidos",170,2,7,190,"CANTEN, CANTEN, PAJARITOS",7,5,"io",-1,0,-1,0,419,419,"Ap. 298","",0,"","","",1,0,0,[],""],["frenk_t4-ap299-01",8,"La música está muy buena\npara festejar tu estado,\ndando gracias a María\ny al Señor Sacramentado.",175,2,6,190,"LA MÚSICA ESTÁ MUY BUENA",0,4,"ao",14,0,-1,0,419,419,"Ap. 299","",0,"","","",1,0,0,[],""],["frenk_t4-ap299-02",8,"Ya quiso el cielo piadoso\nde evitarte la ocasión,\npues él te da por unión\nese clavel generoso;\nél es tu querido esposo\ny tú, su esposa y cadena;\nya se te acabó la pena,\ndale gracias a María;\nme parece que este día\nla música está muy buena.",175,2,6,190,"LA MÚSICA ESTÁ MUY BUENA",18,10,"ea",59,0,-1,0,419,419,"Ap. 299","",0,"","","",1,0,0,[],""],["frenk_t4-ap299-03",8,"Yo quisiera con afán\nel decirte en este día,\njunto con la compañía\nde aquel glorioso José,\nyo quisiera, pero ¿qué?,\nun día tan regocijado,\nque bajara con cuidado\ntoda la gloria divina,\ncon una música fina\npara celebrar tu estado.",175,2,6,190,"LA MÚSICA ESTÁ MUY BUENA",18,10,"ao",14,0,-1,0,419,419,"Ap. 299","",0,"","","",1,0,0,[],""],["frenk_t4-ap299-04",8,"Oye bien lo que te digo,\ntoma este consejo fiel;\ndale gusto a ese clavel,\nya que se casó contigo;\nmira que no es poco abrigo;\ndale gracias a María\nen este dichoso día,\nque he llegado a pensar\nque el infiemo ha de temblar,\ndando gracias a María.",175,2,6,190,"LA MÚSICA ESTÁ MUY BUENA",18,10,"ia",0,0,-1,0,419,419,"Ap. 299","",0,"","","",4,0,0,[],""],["frenk_t4-ap299-05",8,"Tres letras sacro-gloriosas\nquedan en cuenta divina,\nel padrino y la madrina,\nel desposado y su esposa.\n¡Oh, qué cuenta tan hermosa!\nHace un número ajustado,\ncuatro van, pongan cuidado,\ny seis voy a ajustar hora\ncon María, Nuestra Señora,\ny el Señor Sacramentada.",175,2,6,190,"LA MÚSICA ESTÁ MUY BUENA",18,10,"aa",-1,0,-1,0,419,419,"Ap. 299","",0,"","","",1,0,0,[],""],["frenk_t4-ap300-02",8,"Humildes peregrinos,\nJesús, María y José,\nmi alma va con ella,\nmi corazón también.",171,2,4,190,"CANTOS DE POSADAS",0,4,"e",-1,0,-1,0,420,420,"Ap. 300","",0,"","","",2,0,0,[],""],["frenk_t4-ap301-01",8,"Todos los negritos\nvamos a Belén\na ver a la Virgen\ny al niño también.",187,2,12,190,"CANTOS DE POSADAS",0,4,"e",242,0,-1,0,420,420,"Ap. 301","",0,"","","",2,0,0,[],""],["frenk_t4-ap301-02",8,"Pajarito amante,\ndéjanos pasar,\nque somos negritos\nde la catedral.",187,2,12,190,"CANTOS DE POSADAS",0,4,"a",-1,0,-1,0,420,420,"Ap. 301","",0,"","","",1,0,0,[],""],["frenk_t4-ap301-03",8,"Todos los negritos\nvamos a Veracruz\na ver a la Virgen\ny al niño Jesús.",187,2,12,190,"CANTOS DE POSADAS",0,4,"u",270,0,-1,0,420,420,"Ap. 301","",0,"","","",2,0,0,[],""],["frenk_t4-ap301-04",8,"Hijo Francisquito,\nváyase a tocar\nlas tristes campanas,\nque ya voy a agonizar.",187,2,12,190,"CANTOS DE POSADAS",0,4,"a",21,0,-1,0,420,420,"Ap. 301","",0,"","","",1,0,0,[],""],["frenk_t4-ap301-05",8,"Campanita de oro\ncon badajo de cristal;\nse ha de llegar el tiempo\nen que yo me he de alejar.",187,2,12,190,"CANTOS DE POSADAS",0,4,"a",-1,0,-1,0,420,420,"Ap. 301","",0,"","","",5,0,0,[],""],["frenk_t4-ap301-06",8,"Hijos de mi vida,\ndejen de llorar;\nel negro caporal\nya se lo lleva Dios.",187,2,12,190,"CANTOS DE POSADAS",5,4,"o",-1,0,-1,0,420,420,"Ap. 301","",0,"","","",1,0,0,[],""],["frenk_t4-ap301-07",8,"Adiós, gran señora\nde la Soledad;\nsocorre a tus negritos\nque gimiendo van.",187,2,12,190,"CANTOS DE POSADAS",0,4,"a",-1,0,-1,0,420,420,"Ap. 301","",0,"","","",1,0,0,[],""],["frenk_t4-ap301-08",8,"Salgas ya, mariposa,\ncon esa palmilla\nde Dios; seca tu llanto\nhija Maringuilla.",187,2,12,190,"CANTOS DE POSADAS",0,4,"ia",162,0,-1,0,420,420,"Ap. 301","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-01",8,"Qué bonitas mañanitas\ncantaremos con placer\na nuestro padre Jesús\nal tiempo de amanecer.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"e",20,0,-1,0,420,420,"Ap. 302","",0,"","","",4,0,0,[],""],["frenk_t4-ap302-02",8,"Ya viene alboreando el día,\nya comienza a esclarecer;\nPadre, Jesús Nazareno,\nbendito sea tu poder.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"e",20,0,-1,0,420,420,"Ap. 302","",0,"","","",2,0,0,[],""],["frenk_t4-ap302-03",8,"Los pajarillos cantando,\nsacudiendo sus alitas,\nle entonan sus gorjeos,\nsus alegres mañanitas.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"ia",258,0,-1,0,420,420,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-04",8,"Toditos sus visitantes\nvienen con mucho placer\na cantar las mañanitas,\nal tiempo de amanecer.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"e",20,0,-1,0,420,420,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-05",8,"Desde muy lejanas tierras\naquí le vienen a ver\na cantar las mañanitas,\nal tiempo de amanecer.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"e",20,0,-1,0,420,420,"Ap. 302","",0,"","","",2,0,0,[],""],["frenk_t4-ap302-06",8,"Familias, una por una,\nllegan con mucho placer\na cantar las mañanitas\nal tiempo de amanecer.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"e",20,0,-1,0,420,420,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-07",8,"Ya el primer viernes llegó,\nya comienza a esclarecer;\nabre, Señor, tus ojitos\npara que me puedas ver.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"e",20,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-08",8,"Aquí están tus mañanitas,\nPadre de mi corazón;\nrecíbelas, Padre mío,\néchanos tu bendición.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"o",31,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-09",8,"He venido esta ocasión\na cantar tus mañanitas,\nrecíbelas, Padre mío,\ncon tus sagradas manitas.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"ia",258,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-10",8,"Eres un bello clavel\ndel jardín más regalado.\nMuy buenos días, Padre mío,\nloh, Señor Sacramentado!",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"ao",14,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-11",8,"Qué bonitas mañanitas,\nqué gusto y qué regocijo;\ngloria al Padre, gloria al Hijo,\ntambién tú, Espíritu Santo.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",5,4,"ao",-1,0,-1,0,421,421,"Ap. 302","",0,"","","",4,0,0,[],""],["frenk_t4-ap302-12",8,"¡Viva Jesús Nazareno!,\nentonan en alta voz\nal tiempo de amanecer:\n¡Bendito sea tu poder!",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",5,4,"e",20,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-13",8,"Ya viene rayando el sol,\nresplandor sobredorado,\nsaludándole al Señor\nde Nazareno nombrado.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"ao",14,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-14",8,"De gusto y regocijo\nhoy le canta el ruiseñor,\ny dice con regocijo:\nbuenos días, hermosa flor.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",1,4,"o",72,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-15",8,"El jilguero presuroso\nsu canto va resonando,\nal Señor Nazareno,\nsu santo nombre alabando.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"ao",33,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-16",8,"Padre, Jesús Nazareno,\nde los cielos alegría;\nqué bonitas mañanitas,\nya viene alboreando el día.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"ia",-1,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-17",8,"Ya comienza a esclarecer,\nya cantan los pajaritos:\n“saludemos al Señor”,\nte alaban con su piquito.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"io",-1,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-18",8,"Canarios y gorrioncitos\nvienen con mucha alegría\na saludar al Señor,\na su santo romerío.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",5,4,"io",-1,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-19",8,"Ya vine, Padre amoroso,\nporque me diste licencia\nde cantar tus mañanitas\nen tu divina presencia.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"ea",46,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-20",8,"Se me hizo mucha la ausencia,\nun año que no te veía;\npero me diste licencia\nde estar en tu compañía.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",1,4,"ia",0,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-21",8,"Qué felicidad la mía\nde volverte a visitar,\nen tu santuario dichoso\ntus mañanitas cantar.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"a",21,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-22",8,"Los ángeles en el cielo\ncon regocijo y contento\nte rinden adoración\ny rendido nombramiento.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"eo",94,0,-1,0,421,421,"Ap. 302","",0,"","","",10,0,0,[],""],["frenk_t4-ap302-23",8,"Abre, Señor, tus ojitos,\nya el primer viernes llegó,\nque éstas son tus mañanitas,\nmira que ya amaneció.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"o",2,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-24",8,"Los ángeles te saludan\nen columnas, con placer,\ndándote mil parabienes\nal tiempo de amanecer.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"e",20,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-25",8,"Eres frondoso alhelíe\ndel jardín más escogido,\nmuy buenos días, Padre mío,\nsanto cielo aparecido.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",0,4,"io",-1,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap302-26",8,"De flores muy exquisitas\nsólo quisiera adornarte,\ny darte rendidas gracias\nal tiempo de amanecer.",166,2,-1,190,"MAÑANITAS A NUESTRO PADRE JESÚS",5,4,"e",-1,0,-1,0,421,421,"Ap. 302","",0,"","","",1,0,0,[],""],["frenk_t4-ap303-01",8,"Cruz bendita y amable\nen que murió el redentor;\ncuando yo muera, que vea\ntus brazos cerca de mí.",182,2,21,190,"DANZA DE LOS DOCE PARES DE FRANCIA",5,4,"i",-1,0,-1,0,422,422,"Ap. 303","",0,"","","",1,0,0,[],""],["frenk_t4-ap303-02",8,"Señor, que llevas la cruz\ncon tanta resignación,\nhaz que yo tome la mía\ny no me aparte de ti.",182,2,21,190,"DANZA DE LOS DOCE PARES DE FRANCIA",5,4,"i",-1,0,-1,0,422,422,"Ap. 303","",0,"","","",1,0,0,[],""],["frenk_t4-ap303-03",8,"Bendito sea el madero\nen que mi amado Jesús\nsucumbió por redimirnos,\nlibrándonos del infierno.",182,2,21,190,"DANZA DE LOS DOCE PARES DE FRANCIA",5,4,"eo",-1,0,-1,0,422,422,"Ap. 303","",0,"","","",1,0,0,[],""],["frenk_t4-ap303-04",8,"Bendito sea el Señor,\nque tanto padeció\npor redimir las almas\ny darles salvación.",182,2,21,190,"DANZA DE LOS DOCE PARES DE FRANCIA",0,4,"o",-1,0,-1,0,422,422,"Ap. 303","",0,"","","",1,0,0,[],""],["frenk_t4-ap304-01",8,"Vamos, vamos al Santuario\nbendito de Guatemala,\na que nos bendiga Cristo,\ndepositado en su sala.",166,2,-1,190,"ORACIÓN AL SEÑOR DE ESQUIPULAS",0,4,"aa",330,0,-1,0,422,422,"Ap. 304","",0,"","","",1,0,0,[],""],["frenk_t4-ap304-02",8,"Alabemos, chiapanecos,\na este Cristo poderoso,\npara que seamos felices\nfrente al Padre poderoso.",166,2,-1,190,"ORACIÓN AL SEÑOR DE ESQUIPULAS",0,4,"oo",-1,0,-1,0,422,422,"Ap. 304","",0,"","","",1,0,0,[],""],["frenk_t4-ap304-03",8,"De todas nuestras capillas\ne iglesias vamos llegando;\nsi es preciso de rodillas\ny hasta con los pies sangrando.",166,2,-1,190,"ORACIÓN AL SEÑOR DE ESQUIPULAS",1,4,"ao",33,0,-1,0,422,422,"Ap. 304","",0,"","","",1,0,0,[],""],["frenk_t4-ap304-04",8,"De Villa Flores llegaste\nadorado por nosotros;\nen Guatemala quedaste\nhaciendo el bien a unos y otros.",166,2,-1,190,"ORACIÓN AL SEÑOR DE ESQUIPULAS",1,4,"oo",306,0,-1,0,422,422,"Ap. 304","",0,"","","",1,0,0,[],""],["frenk_t4-ap304-05",8,"El día 15 de enero,\nel pueblo con gran fervor\ncelebra tu dulce nombre,\ny se encomienda al Creador.",166,2,-1,190,"ORACIÓN AL SEÑOR DE ESQUIPULAS",0,4,"o",72,0,-1,0,422,422,"Ap. 304","",0,"","","",1,0,0,[],""],["frenk_t4-ap304-06",8,"Enfermos de todo Chiapas,\ndel Istmo y de Veracruz;\ntodos van en el camino\npara estar frente a tu cruz.",166,2,-1,190,"ORACIÓN AL SEÑOR DE ESQUIPULAS",0,4,"u",109,0,-1,0,422,422,"Ap. 304","",0,"","","",1,0,0,[],""],["frenk_t4-ap304-07",8,"Ya llegaré, Padrecito,\ncon otros accidentados;\nme hincaré frente a su imagen\nviendo a los otros curados.",166,2,-1,190,"ORACIÓN AL SEÑOR DE ESQUIPULAS",0,4,"ao",18,0,-1,0,422,422,"Ap. 304","",0,"","","",1,0,0,[],""],["frenk_t4-ap304-08",8,"Para ir a Guatemala\nestoy regando unas flores,\npara que el camino tenga\nun vestido de colores.",166,2,-1,190,"ORACIÓN AL SEÑOR DE ESQUIPULAS",0,4,"oe",5,0,-1,0,422,422,"Ap. 304","",0,"","","",2,0,0,[],""],["frenk_t4-ap304-09",8,"Para ir a Guatemala\nvoy a comprarme un sombrero\nque traeré de regreso\ncon adornos de romero.",166,2,-1,190,"ORACIÓN AL SEÑOR DE ESQUIPULAS",0,4,"eo",-1,0,-1,0,422,422,"Ap. 304","",0,"","","",2,0,0,[],""],["frenk_t4-ap304-10",8,"Dame ye tu bendición\npara que me vaya bien;\nmi familia y compañeros\nte agradecemos. Amén.",166,2,-1,190,"ORACIÓN AL SEÑOR DE ESQUIPULAS",0,4,"e",242,0,-1,0,422,422,"Ap. 304","",0,"","","",1,0,0,[],""],["frenk_t4-ap305-01",8,"Jesucristo me acompañe\ny la flor en que nació;\ntambién la hostia consagrada\ny la cruz en que murió\npor librarnos del pecado.\n¡Bendita sea tu pasión!\n¡Ay!, Virgen de la Candelaria,\nyo te ofrezco esta oración\npara que con más frecuencia\nte celebren tu función.",182,2,21,190,"ALABADO",18,10,"o",31,0,-1,0,422,422,"Ap. 305","",0,"","","",1,0,0,[],""],["frenk_t4-ap305-02",8,"El Señor San Juan Bautista,\nel patrón de nuestro pueblo,\npréstanos vida y salud\npa seguir tu devoción.",182,2,21,190,"ALABADO",5,4,"o",-1,0,-1,0,423,423,"Ap. 305","",0,"","","",1,0,0,[],""],["frenk_t4-ap305-03",8,"Te pido que con tu amparo\nnos dejes anochecer;\nque con el alma en el cuerpo\nnos dejes amanecer.",182,2,21,190,"ALABADO",0,4,"e",20,0,-1,0,423,423,"Ap. 305","",0,"","","",1,0,0,[],""],["frenk_t4-ap305-05",8,"Al ilustre Ayuntamiento\néchale tu bendición,\npara que con más frecuencia\nte celebren tu función.",182,2,21,190,"ALABADO",0,4,"o",31,0,-1,0,423,423,"Ap. 305","",0,"","","",1,0,0,[],""],["frenk_t4-ap305-06",8,"Gracias te doy, gran Señor,\nalabando tu gran poder,\nalabando a tres personas\nque es: Jesús, María y José.",182,2,21,190,"ALABADO",3,4,"e",-1,0,-1,0,423,423,"Ap. 305","",0,"","","",1,0,0,[],""],["frenk_t4-ap305-07",8,"Los ángeles en el cielo\nalaban con gran contento,\ny nosotros en la tierra,\nal divino Sacramento.",182,2,21,190,"ALABADO",0,4,"eo",94,0,-1,0,423,423,"Ap. 305","",0,"","","",10,0,0,[],""],["frenk_t4-ap306-01",8,"En nombre de Dios comienzo\ncon mucho gusto a cantar\nestas nuevas mañanitas\na la Virgen celestial.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"a",-1,0,-1,0,423,423,"Ap. 306","",0,"","","",3,0,0,[],""],["frenk_t4-ap306-02",8,"Virgencita de Acahuato,\nhoy te vengo a saludar;\ntodos con gran voluntad\nte venimos a cantar.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"a",-1,0,-1,0,423,423,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap306-03",8,"En este dichoso día\ntoditos vienen a ver\nlos milagros que tú has hecho\ncon tu divino poder.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"e",20,0,-1,0,423,423,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap306-04",8,"A los que creemos en ti,\nque te amamos de verdad,\nVirgencita de Acahuato,\nde todos tienes piedad.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"a",16,0,-1,0,423,423,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap306-05",8,"Por eso, todos llegamos\ncon cariño sin igual;\nante tus plantas benditas\ngracias venimos a dar.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"a",-1,0,-1,0,423,423,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap306-06",8,"Despierta, ve a tus hijitos\nque vienen con devoción,\nsaludándote gustosos\ncon el alma y corazón.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"o",31,0,-1,0,423,423,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap306-07",8,"Porque eres madre querida,\nnos libras de todo mal;\nen recompensa tus hijos\nte venimos a cantar.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"a",-1,0,-1,0,423,423,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap306-08",8,"Reina de Tierra Caliente\nte nombramos por aquí;\nyo te tengo mucha fe\ndesde que te conocí.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"i",23,0,-1,0,423,423,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap306-09",8,"Desde tu aparecimiento\ntodos te tenemos fe\npor tus milagros patentes\nque nos acabas de hacer.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"e",-1,0,-1,0,423,423,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap306-10",8,"Tú que estás allá en el cielo,\na presencia del Creador;\nVirgencita de Acahuato,\nruégale de corazón.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"o",-1,0,-1,0,423,423,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap306-11",8,"Que nos libre del infierno,\ndel pecado mortal;\nVirgencita de Acahuato,\nlíbranos de todo mal.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"a",1,0,-1,0,423,423,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap306-12",8,"Recibe estas mañanitas\nque venimos a cantar;\néchanos tu bendición,\nnos vamos a caminar.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"a",21,0,-1,0,424,424,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap306-13",8,"Al despedirme de ti,\nganas me dan de llorar,\nadiós, madrecita santa,\náhi te quedas en tu altar.",170,2,7,190,"NUEVAS MAÑANITAS DEDICADAS A LA SANTISIMA VIRGEN DE ACAHUATO",0,4,"a",21,0,-1,0,424,424,"Ap. 306","",0,"","","",1,0,0,[],""],["frenk_t4-ap307-02",8,"Los ángeles en el cielo\nte cantan con alegría,\ny nosotros en la tierra\nsaludárnoste, María.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE LA DEFENSA",0,4,"ia",0,0,-1,0,424,424,"Ap. 307","",0,"","","",10,0,0,[],""],["frenk_t4-ap307-03",8,"Eres todo nuestro encanto,\neres tú la preferida,\npor eso te saludamos,\nVirgencita muy querida.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE LA DEFENSA",0,4,"ia",37,0,-1,0,424,424,"Ap. 307","",0,"","","",1,0,0,[],""],["frenk_t4-ap307-04",8,"Tu hermosura nos fascina,\ntu humildad no tiene igual,\nporque eres la reina madre\nsin pecado original.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE LA DEFENSA",0,4,"a",1,0,-1,0,424,424,"Ap. 307","",0,"","","",1,0,0,[],""],["frenk_t4-ap307-05",8,"Escucha nuestros acentos\nque te aclaman sin cesar,\ny se mueven nuestros labios\nsin dejarte de alabar.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE LA DEFENSA",0,4,"a",21,0,-1,0,424,424,"Ap. 307","",0,"","","",1,0,0,[],""],["frenk_t4-ap307-06",8,"Míranos con esos ojos\nque parecen luminares,\nmientras todos de rodillas\nestamos en tus altares.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE LA DEFENSA",0,4,"ae",164,0,-1,0,424,424,"Ap. 307","",0,"","","",1,0,0,[],""],["frenk_t4-ap307-07",8,"Líbranos de todo mal,\néchanos tu bendición,\nalcanzándonos de Dios\nuna humilde contrición.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE LA DEFENSA",0,4,"o",-1,0,-1,0,424,424,"Ap. 307","",0,"","","",1,0,0,[],""],["frenk_t4-ap308-01",8,"Buenos días, mi San Juanita,\nte venimos a cantar\nahora en esta mañanita\nante tu bendito altar.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE SAN JUAN",1,4,"a",21,0,-1,0,424,424,"Ap. 308","",0,"","","",1,0,0,[],""],["frenk_t4-ap308-02",8,"Lindas flores olorosas\nte venimos a ofrecer,\nblancas y muy olorosas,\ntiernas al amanecer.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE SAN JUAN",1,4,"e",20,0,-1,0,424,424,"Ap. 308","",0,"","","",1,0,0,[],""],["frenk_t4-ap308-03",8,"Ante tus plantas benditas\nse arrodilla el trovador,\ncantando las mañanitas\ncon el más ferviente amor.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE SAN JUAN",1,4,"o",72,0,-1,0,424,424,"Ap. 308","",0,"","","",1,0,0,[],""],["frenk_t4-ap308-04",8,"Fresca esiá la mañanita,\nno tarda en salir el sol,\ny nosotros, San Juanita,\nte cantamos con fervor.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE SAN JUAN",0,4,"o",-1,0,-1,0,424,424,"Ap. 308","",0,"","","",1,0,0,[],""],["frenk_t4-ap308-05",8,"Los cordones de mi lira\nacompañan nuestra voz\npara saludarte, Niña,\ncon el permiso de Dios.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE SAN JUAN",0,4,"o",87,0,-1,0,424,424,"Ap. 308","",0,"","","",1,0,0,[],""],["frenk_t4-ap308-06",8,"Los ángeles con anhelo,\ncreo, también te cantarán\ncon la música del cielo,\nVirgencita de San Juan.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE SAN JUAN",1,4,"a",147,0,-1,0,424,424,"Ap. 308","",0,"","","",1,0,0,[],""],["frenk_t4-ap308-07",8,"Perdóname, Niña hermosa,\nmadre de mi corazón,\ntú que eres tan milagrosa:\néchanos tu bendición.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE SAN JUAN",1,4,"o",31,0,-1,0,424,424,"Ap. 308","",0,"","","",2,0,0,[],""],["frenk_t4-ap308-08",8,"Éstas son las mañanitas\nque venimos a ofrecer,\nante sus plantas benditas,\nporque ya va a amanecer.",166,2,-1,190,"MAÑANITAS A LA VIRGEN DE SAN JUAN",1,4,"e",20,0,-1,0,424,424,"Ap. 308","",0,"","","",2,0,0,[],""],["frenk_t4-ap309-01",8,"Buenos días, paloma blanca,\nhoy te vengo a saludar,\nsaludando tu belleza\nen tu reino celestial.",166,2,-1,190,"MAÑANITAS A LA VIRGEN MARÍA",0,4,"a",-1,0,-1,0,425,425,"Ap. 309","",0,"","","",2,0,0,[],""],["frenk_t4-ap309-02",8,"Eres madre del Creador,\ntu poder es soberano;\nmándanos pronto el consuelo,\npatrona del suelo indiano.",166,2,-1,190,"MAÑANITAS A LA VIRGEN MARÍA",0,4,"ao",81,0,-1,0,425,425,"Ap. 309","",0,"","","",3,0,0,[],""],["frenk_t4-ap309-03",8,"Los ángeles en el cielo\nforman columna este día\ny dicen en sus cantares:\n“Ya viene alboreando el día”.",166,2,-1,190,"MAÑANITAS A LA VIRGEN MARÍA",0,4,"ia",-1,0,-1,0,425,425,"Ap. 309","",0,"","","",10,0,0,[],""],["frenk_t4-ap309-04",8,"Eres madre del Creador\nque a mi corazón encanta;\ngracias te doy con amor,\nbuenos días, paloma blanca.",166,2,-1,190,"MAÑANITAS A LA VIRGEN MARÍA",0,4,"aa",-1,0,-1,0,425,425,"Ap. 309","",0,"","","",3,0,0,[],""],["frenk_t4-ap309-05",8,"Niña linda, niña santa,\ntu santo nombre alabado;\nporque eres tan sacrosanta,\nyo te vengo a saludar.",166,2,-1,190,"MAÑANITAS A LA VIRGEN MARÍA",5,4,"a",-1,0,-1,0,425,425,"Ap. 309","",0,"","","",2,0,0,[],""],["frenk_t4-ap310-01",8,"Adiós, mi México lindo,\nde ti yo me separé;\nno pierdo las esperanzas\nque muy pronto volveré.",166,2,-1,190,"ADIÓS MI MÉXICO LINDO",0,4,"e",77,0,-1,0,425,425,"Ap. 310","",0,"","","",1,0,0,[],""],["frenk_t4-ap310-02",8,"Tus calles son muy preciosas,\nbonita tu catedral,\npero más linda se mira\nla Virgen del Tepeyac.",166,2,-1,190,"ADIÓS MI MÉXICO LINDO",0,4,"a",-1,0,-1,0,425,425,"Ap. 310","",0,"","","",1,0,0,[],""],["frenk_t4-ap310-03",8,"Virgencita milagrosa,\nde ti no me he de olvidar:\nde noche, cuando me acueste,\nun rosario te voy a rezar.",166,2,-1,190,"ADIÓS MI MÉXICO LINDO",3,4,"a",21,0,-1,0,425,425,"Ap. 310","",0,"","","",2,0,0,[],""],["frenk_t4-ap310-04",8,"Cuando de ti estaba cerca\nmuy seguido te iba a ver:\nde rodillas, de la puerta\nhasta llegar a tus pies.",166,2,-1,190,"ADIÓS MI MÉXICO LINDO",0,4,"e",-1,0,-1,0,425,425,"Ap. 310","",0,"","","",1,0,0,[],""],["frenk_t4-ap310-05",8,"Cuando a tus pies yo llegaba\ncon todo aquel gran fervor,\nsentía que te entregaba\ntodito mi corazón.",166,2,-1,190,"ADIÓS MI MÉXICO LINDO",0,4,"o",-1,0,-1,0,425,425,"Ap. 310","",0,"","","",1,0,0,[],""],["frenk_t4-ap310-06",8,"Virgencita mexicana,\nmadre de nuestra nación,\nya se despide el que te ama\ncon todo su corazón.",166,2,-1,190,"ADIÓS MI MÉXICO LINDO",0,4,"o",31,0,-1,0,425,425,"Ap. 310","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-01",8,"Al alba de la mañana,\nalabemos loh, Dios Santo!,\ncon una voz resonante,\nel canto de un gallo blanco.",183,2,19,190,"ALABADO",0,4,"ao",-1,0,-1,0,425,425,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-02",8,"Ya el primer gallo cantó,\nya tronaron sus alitas\ndiciendo: “Cristo nació;\nqué bonitas mañanitas”.",183,2,19,190,"ALABADO",1,4,"ia",258,0,-1,0,425,425,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-03",8,"Los dolores de María,\nméritos son de su esposo;\nlos anunció con gran gozo\nel canto de un gallo blanco.",183,2,19,190,"ALABADO",5,4,"ao",-1,0,-1,0,425,425,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-04",8,"Al nacer el niño Dios\nalumbrando al mundo, tanto\nse oía que resonaba\nel canto de un gallo blanco.",183,2,19,190,"ALABADO",0,4,"ao",-1,0,-1,0,425,425,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-05",8,"Para Egipto caminó\ncon sus padres temerosos,\npara librarlo de Herodes,\ncuando el gallito cantaba.",183,2,19,190,"ALABADO",5,4,"aa",-1,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-06",8,"Hasta el portal de Belén\nlos pastores han llegado,\ndándole gracias a Dios\ncuando el gallito ha cantado.",183,2,19,190,"ALABADO",0,4,"ao",14,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-07",8,"¡Ah, qué portal tan dichoso,\nqué maravilla se vio,\npues nacido en un pesebre,\nhasta el gallito cantó!",183,2,19,190,"ALABADO",0,4,"o",2,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-08",8,"En unos pobres pañales\nya su madre lo envolvió,\npero tenía mañanitas\nque el gallito le cantó.",183,2,19,190,"ALABADO",0,4,"o",2,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-09",8,"Lo llevaban al Calvario,\na mi Jesús sacrosanto,\npara ser crucificado,\ncuando cantó el gallo blanco.",183,2,19,190,"ALABADO",0,4,"ao",-1,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-10",8,"San Pedro ¿qué tienes hoy,\nque al Señor has traicionado?;\nle volteaste las espaldas\ncuando cantó el gallo blanco.",183,2,19,190,"ALABADO",0,4,"ao",-1,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-11",8,"Qué terrible procesión\nla noche del Jueves Santo,\nMaría llena de dolor\ncuando cantó el gallo blanco.",183,2,19,190,"ALABADO",0,4,"ao",-1,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-12",8,"Murió a las tres de la tarde,\nuna hora antes de las cuatro,\ndesde la Cruz escuchaba\nlos cantos del gallo blanco.",183,2,19,190,"ALABADO",0,4,"ao",-1,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-13",8,"Aquel Sábado de Gloria,\ncuando fuera sepultado,\nresucitó al tercer día\ncuando el gallito cantaba.",183,2,19,190,"ALABADO",5,4,"aa",-1,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-14",8,"Qué desconsuelo el domingo,\nen su urna levantaban\na Jesús Crucificado\ncuando el gallito cantaba.",183,2,19,190,"ALABADO",0,4,"aa",-1,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-15",8,"En el día de su Ascensión\na los cielos fue elevado\ny nos dio su bendición\ncuando el gallito cantaba.",183,2,19,190,"ALABADO",5,4,"aa",-1,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap311-16",8,"Madre Santa, Cristo Santo,\npor ti rezo este Alabado,\ndiciéndolo con voz alta\nal igual que el gallo blanco.",183,2,19,190,"ALABADO",0,4,"ao",-1,0,-1,0,426,426,"Ap. 311","",0,"","","",1,0,0,[],""],["frenk_t4-ap313-01",8,"De Chalma sois titulado,\noye, benigno, mi voz:\ntu protección he implorado;\nmuy buenos días, padre Dios.",166,2,-1,190,"MAÑANITAS AL SEÑOR DE CHALMA",1,4,"o",87,0,-1,0,427,427,"Ap. 313","",0,"","","",1,0,0,[],""],["frenk_t4-ap313-02",8,"Pues en cueva apareciste,\nte presentaste ante nos;\nno nos eches en olvido;\nmuy buenos días, padre Dios.",166,2,-1,190,"MAÑANITAS AL SEÑOR DE CHALMA",0,4,"o",87,0,-1,0,427,427,"Ap. 313","",0,"","","",1,0,0,[],""],["frenk_t4-ap313-03",8,"Todo formaste veloz,\neste mundo y las estrellas,\ndo pones fúlgidas huellas;\nmuy buenos días, padre Dios.",166,2,-1,190,"MAÑANITAS AL SEÑOR DE CHALMA",11,4,"o",87,0,-1,0,427,427,"Ap. 313","",0,"","","",1,0,0,[],""],["frenk_t4-ap313-04",8,"Tú amparas al desvalido,\ncastigas al hombre atroz,\ndas consuelo al afligido;\nmuy buenos días, padre Dios.",166,2,-1,190,"MAÑANITAS AL SEÑOR DE CHALMA",1,4,"o",87,0,-1,0,427,427,"Ap. 313","",0,"","","",1,0,0,[],""],["frenk_t4-ap313-05",8,"Moriste por mis pecados\ncuando las tres dio el reloj;\nde ti seamos auxiliados;\nmuy buenos días, padre Dios.",166,2,-1,190,"MAÑANITAS AL SEÑOR DE CHALMA",0,4,"o",-1,0,-1,0,427,427,"Ap. 313","",0,"","","",1,0,0,[],""],["frenk_t4-ap313-06",8,"Pues tú redimiste al mundo\npredicando con tu voz;\neres un ser sin segundo;\nmuy buenos días, padre Dios.",166,2,-1,190,"MAÑANITAS AL SEÑOR DE CHALMA",1,4,"o",87,0,-1,0,427,427,"Ap. 313","",0,"","","",1,0,0,[],""],["frenk_t4-ap313-07",8,"Tú mantienes al cristiano\ny hasta el leopardo feroz,\na la hormiga y al gusano;\nmuy buenos días, padre Dios.",166,2,-1,190,"MAÑANITAS AL SEÑOR DE CHALMA",3,4,"o",87,0,-1,0,427,427,"Ap. 313","",0,"","","",1,0,0,[],""],["frenk_t4-ap313-08",8,"Con tu poder infinito,\nPadre mío, bendícenos\ny recibe estos cuartetos;\nmuy buenos días, padre Dios.",166,2,-1,190,"MAÑANITAS AL SEÑOR DE CHALMA",5,4,"o",-1,0,-1,0,427,427,"Ap. 313","",0,"","","",1,0,0,[],""],["frenk_t4-ap314-01",8,"Reina y soberana,\nfiel amparo nuestro;\nde estos hijos tuyos\nse oyen los lamentos.",170,2,7,190,"CANTOS PARA IR A OFRECER A LA VIRGEN",0,4,"eo",-1,0,-1,0,428,428,"Ap. 314","",0,"","","",1,0,0,[],""],["frenk_t4-ap314-02",8,"Lirio de los valles,\nblanca flor del campo,\n¿quién siguiera alegre\ntus hermosos pasos?",170,2,7,190,"CANTOS PARA IR A OFRECER A LA VIRGEN",0,4,"ao",-1,0,-1,0,428,428,"Ap. 314","",0,"","","",1,0,0,[],""],["frenk_t4-ap314-03",8,"Tus cabellos forman,\npara aprehender almas,\npreciosos anillos\nque adoran y guardan.",170,2,7,190,"CANTOS PARA IR A OFRECER A LA VIRGEN",0,4,"aa",-1,0,-1,0,428,428,"Ap. 314","",0,"","","",1,0,0,[],""],["frenk_t4-ap315-02",8,"Su hora, todas las naciones\nocurren a venerarte\npor las santas bendiciones\nque mandas de baluarte.",175,2,6,190,"A LA SANTISIMA VIRGEN DE GUADALUPE",1,4,"ae",8,0,-1,0,428,428,"Ap. 315","",0,"","","",1,0,0,[],""],["frenk_t4-ap315-03",8,"Pero con más grande amor\nlo hace nuestra gran nación,\nporque ésta tuvo el honor\nde tu real aparición.",175,2,6,190,"A LA SANTISIMA VIRGEN DE GUADALUPE",1,4,"o",-1,0,-1,0,428,428,"Ap. 315","",0,"","","",1,0,0,[],""],["frenk_t4-ap315-04",8,"Hoy pedimos con anhelo\ny con todo corazón\nque nos mandes desde el cielo\ntu sagrada bendición.",175,2,6,190,"A LA SANTISIMA VIRGEN DE GUADALUPE",1,4,"o",31,0,-1,0,428,428,"Ap. 315","",0,"","","",1,0,0,[],""],["frenk_t4-ap315-06",8,"Hora venimos de nuevo\ncon el amor conocido;\ncomo lo hiciera Juan Diego,\nel hijo más preferido.",175,2,6,190,"A LA SANTISIMA VIRGEN DE GUADALUPE",0,4,"io",101,0,-1,0,428,428,"Ap. 315","",0,"","","",1,0,0,[],""],["frenk_t4-ap316-03",8,"Adorote, santa cruz,\npuesta en el monte Calvario,\nen ti murió mi Jesús\npara darme eterna luz\ny librarme del pecado.",166,2,-1,190,"ALABADO",7,5,"ao",-1,0,-1,0,428,428,"Ap. 316","",0,"","","",1,0,0,[],""],["frenk_t4-ap316-04",8,"Oh, dulcísimo Jesús,\nyo te doy mi corazón\npara que estampes en él\ntu santísima pasión.",166,2,-1,190,"ALABADO",0,4,"o",31,0,-1,0,428,428,"Ap. 316","",0,"","","",1,0,0,[],""],["frenk_t4-ap316-05",8,"Madre llena de dolor,\nhaced que, cuando expiremos,\nnuestras almas entreguemos\nen las manos del Señor.",166,2,-1,190,"ALABADO",11,4,"o",72,0,-1,0,429,429,"Ap. 316","",0,"","","",1,0,0,[],""],["frenk_t4-ap316-06",8,"Quien a Dios quiera seguir\ny en la gloria quiera entrar,\nuna cosa ha de asentar\ny de corazón decir:\n“Antes morir que pecar,\nantes que pecar, morir”.",166,2,-1,190,"ALABADO",9,6,"i",157,0,-1,0,429,429,"Ap. 316","",0,"","","",1,0,0,[],""],["frenk_t4-ap316-07",8,"Alabadas sean las horas,\nlas que Cristo padeció,\npor librarme del pecado,\nbendita sea su pasión.",166,2,-1,190,"ALABADO",0,4,"o",-1,0,-1,0,429,429,"Ap. 316","",0,"","","",1,0,0,[],""],["frenk_t4-ap316-08",8,"Jueves santo a media noche\nmadrugó la Virgen santa,\nen busca de Jesucristo,\nporque ya el dolor no aguanta.",166,2,-1,190,"ALABADO",0,4,"aa",148,0,-1,0,429,429,"Ap. 316","",0,"","","",1,0,0,[],""],["frenk_t4-ap316-11",8,"Bendita la que del pecho\npor último resto sale\na fundar los sacramentos,\npara que todos se salven.",166,2,-1,190,"ALABADO",0,4,"ae",-1,0,-1,0,429,429,"Ap. 316","",0,"","","",2,0,0,[],""],["frenk_t4-ap316-12",8,"Alabemos y ensalcemos\nal santo autor de la cruz,\ndonde fue crucificado\nnuestro cordero Jesús.",166,2,-1,190,"ALABADO",0,4,"u",270,0,-1,0,429,429,"Ap. 316","",0,"","","",1,0,0,[],""],["frenk_t4-ap316-14",8,"Venid, pecadores,\nvenid con honor,\n[a] adorar el cuerpo\nde mi redentor.",166,2,-1,190,"ALABADO",0,4,"o",72,0,-1,0,429,429,"Ap. 316","",0,"","","",1,0,0,[],""],["frenk_t4-ap316-15",8,"Muera yo, Jesús,\nmuera yo de amor,\nacabe mi vida\nunida con vos.",166,2,-1,190,"ALABADO",0,4,"o",-1,0,-1,0,429,429,"Ap. 316","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-01",8,"Eres un ángel divino\nque vas a cantar victoria;\ncuando llegues a la gloria,\nruega a Dios por tus padrinos.",170,2,7,190,"MUERTE DE UN NIÑO",5,4,"io",-1,0,-1,0,429,429,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-02",8,"Llegando a la casa santa,\nentras a Jerusalén;\nte volverás a Belén,\ndonde la mente se encanta.",170,2,7,190,"MUERTE DE UN NIÑO",11,4,"aa",148,0,-1,0,429,429,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-03",8,"Ahí San Miguel te planta\nun bello laurel divino;\nanda, sigue tu camino\nporque vas a descansar.",170,2,7,190,"MUERTE DE UN NIÑO",5,4,"a",-1,0,-1,0,430,430,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-04",8,"Y de Dios vas a gozar.\nEres un ángel divino,\npasarás el río Jordán\ny las palmas del Cedrón.",170,2,7,190,"MUERTE DE UN NIÑO",5,4,"o",-1,0,-1,0,430,430,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-05",8,"Te dará la bendición\nel que bautizó a San Juan;\nhoy en los cielos están\nlos recuerdos de tu historia.",170,2,7,190,"MUERTE DE UN NIÑO",5,4,"oa",-1,0,-1,0,430,430,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-06",8,"No apartes de tu memoria\ndel bien que aquí te deseamos,\ny muy contentos estamos,\npues vas a cantar victoria.",170,2,7,190,"MUERTE DE UN NIÑO",3,4,"oa",126,0,-1,0,430,430,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-07",8,"En el coro celestial\nde ángeles y serafines,\nque te tocan los clarines\nuna marcha general.",170,2,7,190,"MUERTE DE UN NIÑO",11,4,"a",1,0,-1,0,430,430,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-08",8,"Esto es lo más principal\nde la vida transitoria;\nla nueva dedicatoria\nescribo con eficacia:\n“La Virgen te dé la gracia\ncuando llegues a la gloria.”",170,2,7,190,"MUERTE DE UN NIÑO",9,6,"oa",126,0,-1,0,430,430,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-09",8,"Ángel bello, en este instante\nacuérdate de tus padres\ny de tu querida madre;\nno la olvides, infante.",170,2,7,190,"MUERTE DE UN NIÑO",0,4,"ae",-1,0,-1,0,430,430,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-10",8,"Súbete al cielo triunfante,\ntiéndete en damasco fino\ndel color más purpurino;\ny al obtener el consuelo\nque debe venir del cielo,\nruega a Dios por tus padrinos.",170,2,7,190,"MUERTE DE UN NIÑO",9,6,"io",-1,0,-1,0,430,430,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-12",8,"Ruégale a Dios por tus padres,\ntú que no eres mal presente,\ny por todos tus parientes\ny, además, por los compadres.",170,2,7,190,"MUERTE DE UN NIÑO",5,4,"ae",656,0,-1,0,430,430,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap317-13",8,"Adiós, angelito, adiós;\ncoronado vas de flores;\nte suplico, ángel divino,\nniegues por los pecadores.",170,2,7,190,"MUERTE DE UN NIÑO",0,4,"oe",5,0,-1,0,430,430,"Ap. 317","",0,"","","",1,0,0,[],""],["frenk_t4-ap318-01",8,"Salgan, salgan, salgan,\nánimas en pena,\nque el Rosario santo\nrompa las cadenas.",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",0,4,"ea",-1,0,-1,0,430,430,"Ap. 318","",0,"","","",3,0,0,[],""],["frenk_t4-ap318-02",8,"Miren, consideren,\nque también vendrán\ny estas tristes penas\nlas padecerán.",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",0,4,"a",147,0,-1,0,430,430,"Ap. 318","",0,"","","",1,0,0,[],""],["frenk_t4-ap318-03",8,"Con un Padre Nuestro\ny una Ave María\ntendremos descanso\nde tanta agonía.",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",0,4,"ia",0,0,-1,0,430,430,"Ap. 318","",0,"","","",1,0,0,[],""],["frenk_t4-ap318-04",8,"Hijo muy amado,\npariente o compadre,\npadrecito o madre,\n¿nos han olvidado?",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",11,4,"ao",14,0,-1,0,430,430,"Ap. 318","",0,"","","",1,0,0,[],""],["frenk_t4-ap318-05",8,"Ténebre mansión\nes la que habitamos,\npecamos, morimos,\nrecuérdalo, hermano.",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",0,4,"ao",-1,0,-1,0,430,430,"Ap. 318","",0,"","","",1,0,0,[],""],["frenk_t4-ap318-06",8,"Tiembla, pecador,\nque en este aposento\nno te dan la mano\n..................",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",3,4,"",-1,0,-1,0,430,430,"Ap. 318","",0,"","","",1,0,0,[],""],["frenk_t4-ap318-07",8,"Salgan, salgan, salgan,\nánimas en pena,\nque la Virgen Santa\nlibre su condena.",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",0,4,"ea",59,0,-1,0,431,431,"Ap. 318","",0,"","","",3,0,0,[],""],["frenk_t4-ap318-08",8,"Las llamas nos queman\npor nuestros pecados,\ndad, pues, el descanso,\nhermanos amados.",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",0,4,"ao",-1,0,-1,0,431,431,"Ap. 318","",0,"","","",1,0,0,[],""],["frenk_t4-ap318-09",8,"Pidan, pues, a Cristo,\ncon semblante tierno,\nconceda se acorte\nel ardiente infierno.",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",0,4,"eo",225,0,-1,0,431,431,"Ap. 318","",0,"","","",1,0,0,[],""],["frenk_t4-ap318-10",8,"Tenemos descanso\nel día de finados,\npero en todo el año\nsomos olvidados.",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",0,4,"ao",-1,0,-1,0,431,431,"Ap. 318","",0,"","","",1,0,0,[],""],["frenk_t4-ap318-11",8,"Virgen, reina amada,\njardín de azucenas,\ndadles un consuelo,\nsacadles las penas.",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",0,4,"ea",62,0,-1,0,431,431,"Ap. 318","",0,"","","",1,0,0,[],""],["frenk_t4-ap318-12",8,"Almas, pues, confiad\nque a Dios pediremos\nles dé buen descanso\npor siglos eternos.",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",0,4,"eo",-1,0,-1,0,431,431,"Ap. 318","",0,"","","",1,0,0,[],""],["frenk_t4-ap318-13",8,"Salgan, salgan, salgan,\nánimas de penas,\nque el Rosario santo\nrompa sus cadenas.",166,2,-1,190,"A LAS BENDITAS ÁNIMAS",0,4,"ea",62,0,-1,0,431,431,"Ap. 318","",0,"","","",3,0,0,[],""],["frenk_t4-ap319-01",8,"Ya se acabó mi tesoro,\nse murió mi madre amada;\nestas páginas que lloro,\nno me sirven para nada.",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",1,4,"aa",49,0,-1,0,431,431,"Ap. 319","",0,"frenk_t3","","",2,0,0,[],""],["frenk_t4-ap319-02",8,"Qué bien me decía mi madre:\n“Hijo de mi corazón,\nde esta amable reprensión\nte has de acordar, aunque tarde”.",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",5,4,"ae",-1,0,-1,0,431,431,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-03",8,"Me acuerdo que me decía\ncuando me salía a pasear:\nno te vayas a tardar,\nno acortes la vida mía;\nporque se llegará el día\nque te acuerdes de tu padre\ny tu pecho se taladre\nde verte en tal situación\ny dirás con atención:\n\"¡Qué bien me decía mi madre!\"",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",166,0,-1,0,431,431,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-04",8,"Cuando yo estaba embriagado\nal juego o a la bebida,\ndecía mi madre afligida:\n“Ah qué hijo tan porfiado,\nsi te agarran de soldado,\nte acordarás, aunque tarde,\ndel consejo de tu padre\nque te daba sana paz,\ny con lágrimas dirás:\n¡Qué bien me decía mi madre!\"",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",166,0,-1,0,431,431,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-05",8,"A buscarme se salía\na la calle, a los billares,\nhechos sus ojos dos mares.\nSi por fortuna me veía\ncon lágrimas me decía:\n“Hijo mío, aunque no te cuadre,\nte ha de sorprender tu madre,\ny algún día te acordarás,\ny suspirando dirás:\n¡Qué bien me decía mi madre!\"",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",-1,0,-1,0,431,431,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-06",8,"Es muy claro y evidente\nque el hijo que es desgraciado\nse mira muy despreciado\ndel mundo y de toda gente.\nTodo esto tenga presente\naquel que no sea cobarde\ny su pecho se taladre\nde sentimiento y dolor\ny dirás con tierno amor:\n\"¡Qué bien me decía mi madre!\"",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",166,0,-1,0,431,431,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-07",8,"Mi madre me reprendía\nla junta de mis amigos,\nlos cielos son mis testigos\nlo que yo le respondía.\nAfligida me decía:\n“Hijo mío, no hagas alarde,\nconocerás, aunque tarde,\nesta amable reprensión,\ndirás en una prisión:\n¡Qué bien me decía mi madre!\"",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",-1,0,-1,0,432,432,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-08",8,"Si yo en cárcel me veía\npor la bebida y el juego,\nllorando con gran anhelo,\n“Es posible, vida mía,\n—mi madre a mí me decía-\nmi consejo no te cuadre;\naunque mi pecho taladre\nel dolor y el sentimiento;\npero ahí dirás con el tiempo:\n¡Qué bien me decía mi madre!\"",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",166,0,-1,0,432,432,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-09",8,"¿Quién de todos los parientes\ncon lágrimas de sus ojos,\naguanta por mis sonrojos?\n¡Qué hermanos ni qué vivientes!\nPueda que ni mis dolientes\nlloraban como mi padre.\n¿Qué amigo, qué tío o compadre\ndará alivio a mi pasión\nen tan triste situación?\n¡Qué bien me decía mi madre!",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",166,0,-1,0,432,432,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-10",8,"El día que bajó a la tumba\nese ser idolatrado,\nsiente el hijo desgraciado\nque la gloria se redumba;\nviene y llora hacia la tumba\ny siente un fuego qm arde\ny la madrina o comadre\nle dice al mirarlo sUo:\n“Ahijado mío, no hay tesoro\ntan rico como!a madre.\"",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",166,0,-1,0,432,432,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-11",8,"Tu nombre quedó grabado\ndentro Je mi corazón,\nrecibe esta petición\nque dirige tu hijo amado.\nMi corazón traspasado\nse quedó en fuego que se arde;\nni un pariente, ni un compadre\nque venga a llorar conmigo.\nJunto a tu sepulcro digo:\n¡Qué bien me decía mi madre!",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",166,0,-1,0,432,432,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-12",8,"Al hijo ya desvalido,\nesta suerte le conviene;\nnadie sabe el bien que tiene\nhasta que lo ve perdido.\n¡Oh, quién hubiera sabido\nque era triste y lamentable\nel quebrarse uno en la calle\ntirado a los cuatro vientos!\nEsto es lo que lloro y siento.\n¡Qué bien me decía mi madre!",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",-1,0,-1,0,432,432,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-13",8,"En fin, has de comenzar,\ncorazón, a sentir penas,\nmirando caras ajenas\nsin poderlo remediar.\nComencemos a llorar\nporque me faltó el tesoro\nmás rico y fino que el oro.\nEsto digo sin alarde,\nestas lágrimas que lloro.\n¡Qué bien me decía mi madre!",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",-1,0,-1,0,432,432,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-14",8,"¡Oh, qué terrible amargura\ncuando mi madre murió!\nAl tiempo que ella expiró\nme miraba con ternura\naquella bella hermosura;\ny un recuerdo memorable\ntengo también de mi padre,\nyo siempre me acordaré;\nllorando siempre diré:\n¡Qué bien me decía mi madre!",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",166,0,-1,0,432,432,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap319-15",8,"En fin, queridos oyentes,\noigan el triste gemido\nque da un huérfano afligido\npor las congojas presentes.\nAmigos, tíos y parientes,\nes dolor incomparable\nquedarse uno sin su padre,\ntirado a los cuatro vientos.\nRecuerdo en estos momentos:\n¡Qué bien me decía mi madre!",166,2,-1,190,"DÉCIMAS DE HUÉRFANOS",18,10,"ae",166,0,-1,0,432,432,"Ap. 319","",0,"","","",1,0,0,[],""],["frenk_t4-ap320-01",8,"Si las Margaritas\nfueran de mamón,\n¡cuántas Margaritas\nme comiera yo!",187,2,12,190,"LAS MARGARITAS",0,4,"o",-1,0,-1,0,433,433,"Ap. 320","",0,"","","",1,0,0,[],""],["frenk_t4-ap320-02",8,"Pero tienen uñas,\nsaben arañar;\nahí vienen los yanquis,\nse las llevarán.",187,2,12,190,"LAS MARGARITAS",0,4,"a",-1,0,-1,0,433,433,"Ap. 320","",0,"","","",1,0,0,[],""],["frenk_t4-ap321-01",8,"El Parián que tu fortuna\naprecia mucho, te advierte:\nque puedes hallar la muerte\nen el lugar de Ju cuna;\ndeja, pues, la caballuna\nempresa de estar gritando;\ndeja la ambición y el mando;\nacuérdate del compadre,\npues por más que Hirán te ladre,\n¿lo oiremos nosotros? ¡Cuándo!",166,2,-1,190,"CONSEJO DE LOS PARIANISTAS",18,10,"ao",33,0,-1,0,433,433,"Ap. 321","",0,"","","",1,0,0,[],""],["frenk_t4-ap321-02",8,"¿Cuándo llegará ese cuándo?,\n¿cuándo llegará mañana?\nQue le den sus pildoritas\nal jovencito Santa Anna.",166,2,-1,190,"CONSEJO DE LOS PARIANISTAS",0,4,"aa",-1,0,-1,0,433,433,"Ap. 321","",0,"","","",5,0,0,[],""],["frenk_t4-ap322-02",8,"Vamos, amiga Cholita,\nme dijo la tamalera,\na tomar pulque curado\nde ley en “La Calavera”;\ntomaremos una copa\nantes de irnos a almorzar;\npóngase la mejor ropa\ny vámonos a pasear;\nporque todo el mundo dice:\n\"¡Ya el mundo se va a acabar!\"",166,2,-1,190,"YA EL MUNDO SE VA A ACABAR",18,10,"a",21,0,-1,0,433,433,"Ap. 322","",0,"","","",1,0,0,[],""],["frenk_t4-ap322-03",8,"No se asusten, muchachitas,\npor esto que les anuncio,\nque recen las viejecitas\na su patrón San Panuncio.\nQue ustedes, entretenidas\ny de amores platicando,\ncual bellas rosas lucidas\ny en los salones bailando,\nse olvida hasta el fin del mundo,\nsegún están anunciando.",166,2,-1,190,"YA EL MUNDO SE VA A ACABAR",18,10,"ao",33,0,-1,0,433,433,"Ap. 322","",0,"","","",1,0,0,[],""],["frenk_t4-ap322-04",8,"No te asustes, valedor,\nporque debes presumir\nque todo aquel que nació,\nal fin debe de morir;\nno me mires enojado,\nni pongas tan serio el busto,\nprocura estar preparado\npor ser esto lo más justo;\no borracho y acostado\npara no sentir el susto.",166,2,-1,190,"YA EL MUNDO SE VA A ACABAR",18,10,"uo",497,0,-1,0,433,433,"Ap. 322","",0,"","","",1,0,0,[],""],["frenk_t4-ap322-05",8,"En fin, si no me hacen caso,\ny por charla esto lo toman,\nque les haga buen provecho\ny con su pan se lo coman;\nque yo, con un cuero lleno\ny botellas destapadas,\nles diré a mis amiguitos\nentre gimiendo y llorando:\n“Para no sentir el fin,\nvámonos emborrachando.\"",166,2,-1,190,"YA EL MUNDO SE VA A ACABAR",18,10,"ao",33,0,-1,0,433,433,"Ap. 322","",0,"","","",1,0,0,[],""],["isaacs_colombia-00001",9,"“Aunque la puerca sea rucia\ny la tengan en la villa\ny la alimenten con leche,\nsiempre es negra la morcillas”.",197,3,-1,-1,"",0,4,"ia",-1,0,-1,0,5,5,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00001-e2",9,"“A la orilla del mar\nnavega un peine\ny en las olitas que hace\nmi amor se duerme”.",197,3,-1,-1,"",6,4,"ee",-1,0,-1,0,5,5,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00001-e3",9,"“Me puse a tonar un toro;\nlo tarjé por la mitá;\nel toro taba en Arauca\ny yo taba en Trinidá”.",197,3,-1,-1,"",0,4,"a",9,0,-1,0,5,5,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00001-e4",9,"“Lina pasión tan sincera\njamás, mi bien, la hallarás;\nhallarás quien bien te quiera\nmenos quien te quiera mas",197,3,-1,-1,"",1,4,"a",51,0,-1,0,5,5,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00001-e5",9,"“La paloma que te traje\nen el nido la cogí;\nla madre quedó llorando\ncomo yo lloré por tí”.",197,3,-1,-1,"",0,4,"i",23,0,-1,0,5,5,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00001-e6",9,"“Esta casa es muy bonita,\nDios se lo pague al que l’hizo\nque por dentro está la gloria\ny por fuera el paraíso”.",197,3,-1,-1,"",0,4,"io",92,0,-1,0,5,5,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00002",9,"“De mi tierra me he venido\ncon el agua hast’el sobaco,\nsólo por venirte a ver\npescuezo e pájaro vaco”.",197,3,-1,-1,"",0,4,"ao",423,0,-1,0,7,7,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00002-e2",9,"“Se le olvidó a la señora\nque me estaba sonsacando\n‘quiuna cosa piensa el burro\ny otra el que lo está enjalmando’”.",197,3,-1,-1,"",0,4,"ao",33,0,-1,0,7,7,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00002-e3",9,"“A las gallinas maíz\ny a los pollos el arroz,\npara los viejos las viejas,\npara las muchachas yo”.",197,3,-1,-1,"",0,4,"o",-1,0,-1,0,7,7,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00002-e4",9,"“Te quiero más que a mi vida,\nmás que a mi padre y mi madre\ny, si no fuera pecado,\nmás que a la Virgen del Carmen”.",197,3,-1,-1,"",0,4,"ae",-1,0,-1,0,7,7,"","",0,"","","",7,0,0,[],""],["isaacs_colombia-00002-e5",9,"“Hasta los palos del monte\ntienen su separación:\nunos sirven pa hacer santos\ny otros para hacer carbón”.",197,3,-1,-1,"",0,4,"o",31,0,-1,0,7,7,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00002-e6",9,"“Al pobre del armadillo\nlo reclaman para juez\ny él dice que no lo jodan,\nque lo dejen pa endespués”.",197,3,-1,-1,"",0,4,"e",218,0,-1,0,7,7,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00003r1",9,"“El gallo en su gallinero\nlibre, se sacude y canta.\nEl que duerme en casa ajena\npasitico se levanta”.",197,3,-1,-1,"",0,4,"aa",148,0,-1,0,8,8,"","",0,"andina_t1","","",5,0,0,[],""],["isaacs_colombia-00003r2",9,"“Déjame dentrar al monte,\ndéjame coger la flor,\ndéjame dormir sueñito\nentre tus brazos, mi amor”.",197,3,-1,-1,"",0,4,"o",72,0,-1,0,8,8,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00003",9,"“Un indio estaba muriendo\ny a su hijo le aconsejaba:\nhas de saber, hijo mío,\nquiun bien con un mal se paga”.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,8,8,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00003-e2",9,"“Si algún blanco te dijera\nque le ensillara el caballo,\ndejale la cincha floja\npa que se lo lleve el diablo”.",197,3,-1,-1,"",0,4,"ao",-1,0,-1,0,8,8,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00003-e3",9,"“Tres aguas habré bebido,\ncuatro con la de verbena\ny no hay agua más amarga\nquel vivir en casa ajena”",197,3,-1,-1,"",0,4,"ea",59,0,-1,0,8,8,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00003-e4",9,"“El que ve la lechuza, de momento,\nla quiere matá,\nque conozco el elemento,\n(qué va, gallo, qué va.)\nbuchipluma no má”.",197,3,-1,-1,"",7,5,"a",9,0,-1,0,8,8,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00004r1",9,"“Ensillando mi caballo\nella se puso a llorar\ny yo, llorando con ella,\nlo volví a desensillar”.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,10,10,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00004",9,"“Yo no soy de por aquí,\nyo soy de Sutapelao\ny me trajo un capuchino\nen las barbas enredao”.",197,3,-1,-1,"",0,4,"ao",98,0,-1,0,9,9,"","",0,"","","",11,0,0,[],""],["isaacs_colombia-00004-e2",9,"“No me casaré con viuda\naunque la vistan de seda\nporque a mula que otro amansa\nalgún resabio le queda”.",197,3,-1,-1,"",0,4,"ea",266,0,-1,0,9,9,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00004-e3",9,"“Una ollita de barro\nme dió mi suegra;\ncada vez que peliamos\nmanda por ella”.",197,3,-1,-1,"",6,4,"ea",-1,0,-1,0,9,9,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00004-e4",9,"“La guabina me dijo\nque me daría\nuna guayaba verde\nque me tenía”.",197,3,-1,-1,"",6,4,"ia",0,0,-1,0,9,9,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00004-e5",9,"“En los asientos del mar\nsuspiraba un buey churriento\ny en los suspiros decía:\nsi no me muero, me aliento”.",197,3,-1,-1,"",0,4,"eo",94,0,-1,0,9,9,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00005",9,"“Me subí en una lomita\npor ver si la divisaba;\ntan solo topé las quimbas\ndel indio que la llevaba”.",197,3,-1,-1,"",0,4,"aa",28,0,-1,0,11,11,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00005-e2",9,"“Lloraba la margarita\nla muerte de su marido\ny en el llanto preguntaba\nsi el otro ya había venido”.",197,3,-1,-1,"",0,4,"io",101,0,-1,0,11,11,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00005-e3",9,"“Los sapos en la laguna,\ncuando viene el aguacero,\nunos se ponen cachucha\ny otros se ponen sombrero”.",197,3,-1,-1,"",0,4,"eo",38,0,-1,0,11,11,"","",0,"","","",6,0,0,[],""],["isaacs_colombia-00005-e4",9,"“Me quisiste, me olvidaste,\nme volvistes a querer;\nasí se estriega la ropa\nmi vida, pa que blanquié”",197,3,-1,-1,"",0,4,"e",-1,0,-1,0,11,11,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00005-e5",9,"“Véndame un cuartillo e chicha\nen totuma timaneja;\nyo no l’huago por la chicha\nsino por la muchareja”.",197,3,-1,-1,"",1,4,"ea",165,0,-1,0,11,11,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00005-e6",9,"“Tienes unos ojos negros\ny unas sedosas pestañas\ny unos labios mentirosos\ncon que me engañas, me engañas”.",197,3,-1,-1,"",0,4,"aa",42,0,-1,0,11,11,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00006",9,"Si el más triste de los tristes\nmis lamentos escuchara,\npor compadecer mis penas\nde las suyas se olvidara.",197,3,-1,-1,"",0,4,"aa",57,0,-1,0,13,13,"","",0,"pacifico_colombia","","",2,0,0,[],""],["isaacs_colombia-00007",9,"A conquistar tu plaza\nme dirigía\ncuando vi que otro.\npuso su batería;\nmudé de intento\ny puse en otra parte\nmi pensamiento.",197,3,-1,-1,"",4,7,"eo",94,0,-1,0,13,13,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00008",9,"Cinco sentidos tenemos;\ntodos los necesitamos;\ntodos cinco los perdemos\ncuando nos enamoramos.",197,3,-1,-1,"",1,4,"ao",116,0,-1,0,13,13,"","",0,"rm_t4, pacifico_colombia","","",7,0,0,[],""],["isaacs_colombia-00009",9,"Malos pensamientos tienes\ny yo mil presentimientos:\npara dejar de pensar,\nmudemos de pensamiento",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,13,13,"","",0,"pacifico_colombia","","",2,0,0,[],""],["isaacs_colombia-00010",9,"Muchos constancia prometen\nmientras logran sus intentos,\ny logrando lo que quieren,\nsi te vide no me acuerdo.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,13,13,"","",0,"pacifico_colombia","","",2,0,0,[],""],["isaacs_colombia-00011",9,"Cuando te contemplo ausente\ncon más fineza te adoro,\nmi cogollo de romero,\nmi bello granito de oro.",197,3,-1,-1,"",0,4,"oo",85,0,-1,0,13,13,"","",0,"pacifico_colombia","","",2,0,0,[],""],["isaacs_colombia-00012",9,"Si mi cuidado es causa\nde disgustarte,\nMira que es imposible\nel olvidarte;\nque si pudiera,\nsólo por complacerte,\nmi amor, lo hiciera.",197,3,-1,-1,"",4,7,"ea",44,0,-1,0,13,13,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00013",9,"Si piensas que en tí piensa\nmi pensamiento,\npiensas en una cosa\nque yo no pienso;\nsi la pensara\ncomo mal pensamiento\nla desechara.",197,3,-1,-1,"",4,7,"aa",57,0,-1,0,13,13,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00014",9,"Si la pasión te ciega,\nmira primero donde\npones los ojos,\nno llores luego:\nlos ojos abre;\nmira que cuando acuerdes\nserá ya tarde.",197,3,-1,-1,"",4,7,"ae",-1,0,-1,0,13,13,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00015",9,"Quisiera con un suspiro\ndescerrejar esta puerta,\npor ver si la vida mía\nestá dormida o despierta.",197,3,-1,-1,"",0,4,"ea",267,0,-1,0,13,13,"","",0,"pacifico_colombia","","",3,0,0,[],""],["isaacs_colombia-00016",9,"El clavel que me diste\nlo tengo en agua,\nporque no se marchite,\n¡prenda del alma!",197,3,-1,-1,"",6,4,"aa",-1,0,-1,0,13,13,"","",0,"pacifico_colombia","","",3,0,0,[],""],["isaacs_colombia-00017",9,"El alma y las tres potencias\ncon mi corazón te di,\nporque estaba convencido\nque para amarte nací.",197,3,-1,-1,"",0,4,"i",23,0,-1,0,13,13,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00018",9,"La vida paso muriendo;\nsi muriera, viviría,\nporque muriendo, saldría\ndel mal que sufro viviendo.",197,3,-1,-1,"",11,4,"eo",52,0,-1,0,13,13,"","",0,"pacifico_colombia","","",2,0,0,[],""],["isaacs_colombia-00019",9,"Qué lejos estás de mí;\nno te alcanzo a divisar;\nlos cerros tienen la culpa,\n¡Quién los pudiera tumbar!",197,3,-1,-1,"",0,4,"a",21,0,-1,0,13,13,"","",0,"pacifico_colombia","","",2,0,0,[],""],["isaacs_colombia-00020",9,"Ausente del bien que adoro\ncualquiera me considere:\n¿Qué gustos podré tener\nsin saber si vive o muere?",197,3,-1,-1,"",0,4,"ee",115,0,-1,0,14,14,"","",0,"pacifico_colombia","","",10,0,0,[],""],["isaacs_colombia-00021",9,"Si yo fuera pajarito,\na verte fuera derecho,\ny con pajitas y plumas\nhiciera nido en tu pecho.",197,3,-1,-1,"",0,4,"eo",60,0,-1,0,14,14,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00022",9,"Suerte, suerte desgraciada,\n¿Para qué dichas mediste?\n¿Por qué con tiempo no viste\nque dichas no duran nada?",197,3,-1,-1,"",11,4,"aa",49,0,-1,0,14,14,"","",0,"pacifico_colombia","","",2,0,0,[],""],["isaacs_colombia-00023",9,"Mi vida, si tú me quieres\nno se lo digas a nadie;\nmete la mano en tu pecho,\ndile al corazón que calle.",197,3,-1,-1,"",0,4,"ae",-1,0,-1,0,14,14,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00024",9,"Di, Cali, en qué te ofendí:\n¿Por qué tanto me maceras?\n¡Ay! ¿por qué como las fieras\nme despedazas así?",197,3,-1,-1,"",11,4,"i",23,0,-1,0,14,14,"","",0,"pacifico_colombia","","",2,0,0,[],""],["isaacs_colombia-00025",9,"En el mar de tu pelo\nnavega un peine,\ny a las olitas que hace\nmi amor se duerme.",197,3,-1,-1,"",6,4,"ee",-1,0,-1,0,14,14,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00026",9,"Adiós, Cali tan famoso,\ntierra donde yo nací,\nque para otros eres madre\ny madrastra para mí.",197,3,-1,-1,"",0,4,"i",23,0,-1,0,14,14,"","",0,"pacifico_colombia","","",2,0,0,[],""],["isaacs_colombia-00027",9,"Propasas tanto a Venus\nen tu hermosura,\ncuanto va de lo vivo\na la pintura.",197,3,-1,-1,"",6,4,"ua",17,0,-1,0,14,14,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00028",9,"Adiós, Popayán hermoso,\ntierra de la picardía,\nadiós, patojas del diablo,\nque yo volveré algún día.",197,3,-1,-1,"",0,4,"ia",0,0,-1,0,14,14,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00029",9,"Aunque nunca me quieras\nhe de quererte,\ny se que estos amores\nme dan la muerte.",197,3,-1,-1,"",6,4,"ee",134,0,-1,0,14,14,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00030",9,"Allá arriba en esa loma\ntengo un pañuelo volando,\ny en las puntas tiene escrito:\n“Ya mi amor se va acabando”.",197,3,-1,-1,"",0,4,"ao",33,0,-1,0,14,14,"","",0,"","","",6,0,0,[],""],["isaacs_colombia-00031",9,"Aunque la puerca sea rusia\ny la maten en la villa,\ny le echen leche a la sangre,\nsiempre es negra la morcilla.",197,3,-1,-1,"",0,4,"ia",162,0,-1,0,14,14,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00032",9,"Aunque tú no me quieras,\nyo he de quererte,\nporque esos tus amores\nme dan la muerte.",197,3,-1,-1,"",6,4,"ee",134,0,-1,0,14,14,"","",0,"","","",6,0,0,[],""],["isaacs_colombia-00033",9,"Si la sirena se embarca\ncon ella te escribiré:\nmi sangre será la tinta,\nmi corazón el papel.",197,3,-1,-1,"",0,4,"e",-1,0,-1,0,14,14,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00034",9,"Yo soy, trigueña, yo soy\nquien todo el alma te fía:\nquiéreme por vida tuya,\nque yo te adoro, alma mía.",197,3,-1,-1,"",0,4,"ia",0,0,-1,0,14,14,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00035",9,"Quien no previene los daños\nni los peligros advierte,\na golpes de desengaños\nserá razón que despierte.",197,3,-1,-1,"",1,4,"ee",134,0,-1,0,15,15,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00036",9,"Un volcán tengo en el pecho,\nque arde de diversos modos,\ny yo, callando, me abraso\nporque no lo sepan todos.",197,3,-1,-1,"",0,4,"oo",418,0,-1,0,15,15,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00037",9,"Es tánto lo que te quiero\ny mi amor tan majadero,\nque cuando te veo me escondo\ny por verte desespero.",197,3,-1,-1,"",0,4,"eo",38,0,-1,0,15,15,"","",0,"","","",26,0,0,[],""],["isaacs_colombia-00038",9,"Abreme la puerta, cielo,\nque yo no vengo a dormir,\nsólo te vengo a decir...\nque si me quieres, te quiero.",197,3,-1,-1,"",5,4,"eo",-1,0,-1,0,15,15,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00039",9,"Es tanto lo que te quiero\ny lo que te quiero es tanto,\nque te quisiera tener\nen mi pecho como santo.",197,3,-1,-1,"",0,4,"ao",30,0,-1,0,15,15,"","",0,"","","",26,0,0,[],""],["isaacs_colombia-00040",9,"Ojos habrá desgraciados,\npero no como los míos,\nporque mis ojos se hicieron\npara aumento de los ríos.",197,3,-1,-1,"",0,4,"io",135,0,-1,0,15,15,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00041",9,"Ojos negros y pardos\nson los comunes,\npero los de mi gusto\nson los azules.",197,3,-1,-1,"",6,4,"ue",-1,0,-1,0,15,15,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00042",9,"Cuando un pobre se enamora\ny un rico se le atraviesa,\nsale el pobre puerta afuera\nrascándose la cabeza.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,15,15,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00043",9,"Ojitos de cambalache,\nque lindo mirar tenéis;\npor donde quiera que vais\nun cambalachito hacéis.",197,3,-1,-1,"",0,4,"e",657,0,-1,0,15,15,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00044",9,"Eres un granito de oro,\nuna perla dibujada;\neres aquel pajarito\nque canta a la madrugada.",197,3,-1,-1,"",0,4,"aa",49,0,-1,0,15,15,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00045",9,"Ojitos de cambalache,\nque lindo mirar tenés;\npor cualquier parte que andás\ntu cambalachito hacés.",197,3,-1,-1,"",0,4,"e",218,0,-1,0,15,15,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00046",9,"Jamás, mi bien, hallarás\nquien, como yo, por tí muera:\nhallarás quien bien te quiera,\nmás no quién te quiera más.",197,3,-1,-1,"",11,4,"a",51,0,-1,0,15,15,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00047",9,"Cuando un negro me saluda,\n¡Ay! que miedo que me da\nde verle los ojos blancos,\n¡Santísima Trinidad!",197,3,-1,-1,"",0,4,"a",-1,0,-1,0,15,15,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00048",9,"Ya la luna no me alumbra,\nlos alares no hacen sombra;\ny con esto me despido:\nhasta mañana, paloma.",197,3,-1,-1,"",0,4,"oa",-1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00049",9,"Te quiero porque me quieres,\nte quiero porque me buscas\nte quiero porque te quiero,\nte quiero porque me gustas.",197,3,-1,-1,"",0,4,"ua",-1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00050",9,"Clavelito colorado\nmatizado con romero,\n¿Cómo no te he de querer\nsi fuiste mi amor primero?",197,3,-1,-1,"",0,4,"eo",38,0,-1,0,16,16,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00051",9,"¡Válgame Dios! qué cosas\nlas que preguntas:\n¿Sabes por qué te quiero?\nporque me gustas.",197,3,-1,-1,"",6,4,"ua",-1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00052",9,"Clavelito colorado,\nde la mata te cogí:\nla mata quedó llorando\ncomo yo lloro por ti.",197,3,-1,-1,"",0,4,"i",23,0,-1,0,16,16,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00053",9,"Me mandan bailar la pisa\nla pisa yo no la sé,\nque para bilar la pisa\nlas indias de Santa Fé.",197,3,-1,-1,"",1,4,"e",77,0,-1,0,16,16,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00054",9,"De repente me han sacado\na bailar el mollejón\nquién sabe como me vaya\npor ser primera ocasión.",197,3,-1,-1,"",0,4,"o",31,0,-1,0,16,16,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00055",9,"Adoremos esta casa\ny al albañil que la hizo,\npues por dentro está la gloria\ny por fuera el paraíso.",197,3,-1,-1,"",0,4,"io",92,0,-1,0,16,16,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00056",9,"Alabemos esta casa,\nno por su merecimiento,\nsino por la gente honrada\nque está de puertas adentro.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,16,16,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00057",9,"Debajo de tu ventana\nme cogieron prisionero,\ny para pena mayor\nme ataron con tu pañuelo.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,16,16,"","",0,"","","",29,0,0,[],""],["isaacs_colombia-00058",9,"Mañana como a estas horas\njunto de ella pienso estar,\ncontándole mis trabajos\nhasta que la haga llorar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,16,16,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00059",9,"¿Para qué son tus caricias,\ntus caricias para qué,\nsi al mismo tiempo te faltan\ncaricias, amor y fe?",197,3,-1,-1,"",0,4,"e",77,0,-1,0,16,16,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00060",9,"Por dos pesos que te di\nha habido dos mil enojos:\nmira cuánto son dos pesos...\ndiez y seis reales, mis ojos.",197,3,-1,-1,"",0,4,"oo",99,0,-1,0,17,17,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00061",9,"Por el filo de una espada\nme atrevo a subir al cielo,\npor coronarte de gloria,\nhermosísimo lucero.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,17,17,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00062",9,"Te están celando por mí\nsin haber pasado nada:\nsi no lo hice, lo haré,\npues ya ha corrido mi fama.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,17,17,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00063",9,"Las estrellas en el cielo\ncaminan de dos en dos:\nasí caminan mis ojos,\nmi vida, detrás de vos.",197,3,-1,-1,"",0,4,"o",87,0,-1,0,17,17,"","",0,"","","",18,0,0,[],""],["isaacs_colombia-00064",9,"Las niñas en la ventana\ncantando la mejorana;\nlas viejas en el rincón\ndesmotando el algodón.",197,3,-1,-1,"",5,4,"o",31,0,-1,0,17,17,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00065",9,"Por esta calle me voy,\npor la otra doy la vuelta;\nla muchacha que me quiera,\nque tenga la puerta abierta.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,17,17,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00066",9,"En el monte de las Pavas\nde continuo está lloviendo...\n¿Cómo me quieres negar\nlo que mis ojos van viendo?",197,3,-1,-1,"",0,4,"eo",52,0,-1,0,17,17,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00067",9,"¿Para qué son gustos\nsi se han de acabar?\nmás valen mis penas,\nque me han de durar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,17,17,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00068",9,"¡Qué preciosos! ¡qué preciosos!\n¡arrayanes florecidos!\n¡Cuánta diera por tus ojos\nsi no estuvieran vendidos",197,3,-1,-1,"",0,4,"io",255,0,-1,0,17,17,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00069",9,"Cruelísima condición\nla que en suerte me ha tocado:\nhe de vivir separado\nde mi propio corazón.",197,3,-1,-1,"",11,4,"o",31,0,-1,0,17,17,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00070",9,"Debajo del limonero,\ndonde el agua no corría,\nentregué mi corazón\na quien no lo merecía.",197,3,-1,-1,"",0,4,"ia",0,0,-1,0,17,17,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00071",9,"A tan triste condición\nla suerte me ha sujetado,\nque he de vivir separado\nde mi mismo corazón.",197,3,-1,-1,"",11,4,"o",31,0,-1,0,17,17,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00072",9,"La naranja nació verde\ny el tiempo la maduró;\nmi corazón nació libre\ny el tuyo lo cautivó.",197,3,-1,-1,"",0,4,"o",2,0,-1,0,18,18,"","",0,"rm_t2, andina_t2","","",5,0,0,[],""],["isaacs_colombia-00073",9,"Vuela, pensamiento, y dile\na la niña que más quiero,\nque aquí en mi pecho hay amor\ny en mi bolsillo dinero.",197,3,-1,-1,"",0,4,"eo",38,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00074",9,"Tú me amas de corazón,\ny que te amo, es cosa cierta;\nen decir tengo razón:\n“Cuando la puerta está abierta\nno tiene culpa el ladrón”.",197,3,-1,-1,"",7,5,"o",31,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00075",9,"Satisfacciones no pido:\ndáselas a quien quisieres,\nque bien satisfecha estoy\ndel poco amor que me tienes.",197,3,-1,-1,"",0,4,"ee",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00076",9,"Con esta mi bandolita\nme atrevo a voltear el mundo\nenamorando muchachas,\nvagamundo, vagamundo.",197,3,-1,-1,"",0,4,"uo",179,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00077",9,"Chiquitica te buscaba,\nchiquitica te encontré;\nhermosura de mis ojos,\n¡cuándo yo te olvidaré!",197,3,-1,-1,"",0,4,"e",77,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00078",9,"Una bonita puede\ncon un suspiro\nresucitar a un muerto,\nmatar a un vivo,",197,3,-1,-1,"",6,4,"io",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00079",9,"Adiós, pajarillo triste,\nque aprisionado en tu jaula,\ntan pronto gimes y lloras\ncomo enamorado cantas.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00080",9,"Donde me dijiste adiós,\ntriste me quedé pensando,\nsin poderte responder:\nadiós, mi vida; ¿hasta cuándo?",197,3,-1,-1,"",0,4,"ao",33,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00081",9,"Quiere volar y no puede,\ny sacudiendo las alas,\nllora en su prisión primera\na su libertad pasada.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00082",9,"Ya se murieron mis perros,\nya quedó mi rancho solo;\nmañana me muero yo\npara que se acabe todo.",197,3,-1,-1,"",0,4,"oo",-1,0,-1,0,18,18,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00083",9,"Desde que te vi venir\nmontadita en una avispa,\nle dije a mi corazón:\neste diablo ya no arrisca.",197,3,-1,-1,"",0,4,"ia",-1,0,-1,0,18,18,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00084",9,"Cuando te vas a bañar\navísame tres días antes,\npara empedrarte el camina\nde rubíes y diamantes.",197,3,-1,-1,"",0,4,"ae",262,0,-1,0,18,18,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00085",9,"Esta noche voy allá;\ndesde ahora te lo aviso;\nsi la puerta es sonadora\núntale cebo en el quicio.",197,3,-1,-1,"",0,4,"io",-1,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00086",9,"Zamba del demonio,\n¿Cuándo te veré\nen la tasajera\ncolgada de un pié?",197,3,-1,-1,"",0,4,"e",77,0,-1,0,19,19,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00087",9,"Cuando una mujer te jura\nque te quiere y que te estima,\nes porque tiene ya puesto\nel matachín en la esquina.",197,3,-1,-1,"",0,4,"ia",-1,0,-1,0,19,19,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00088",9,"Lucerito de mañana,\nno te vas a enajenar,\nque aunque la vida me cueste\ncontigo me he de quedar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,19,19,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00089",9,"Yo me enamoré del aire,\ndel aire de una mujer;\ncomo la mujer es aire\nen el aire me quedé.",197,3,-1,-1,"",0,4,"e",-1,0,-1,0,19,19,"","",0,"rm_t3, palau_cantares, lafuente_madrid, murciano_antiguo, fernan_caballero","","",7,0,0,[],""],["isaacs_colombia-00090",9,"Es mucho lo que te quiero\ny la que te quiero es mucho,\npues te quisiera llevar\nen la oreja como pucho.",197,3,-1,-1,"",0,4,"uo",415,0,-1,0,19,19,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00091",9,"Diera ya por conseguirte\ny porque tú me quisieras,\nlas dos niñas de mis ojos,\naunque quedara sin ellas.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,19,19,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00092",9,"Las mujeres son el diablo\ncuando ven a un hombre pobre:\nlo ponen de candelero,\ncomo si fuera de cobre.",197,3,-1,-1,"",0,4,"oe",410,0,-1,0,19,19,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00093",9,"A cada paso que doy\nme parece que te veo:\nes tu sombra que me sigue\na apariencias del deseo.",197,3,-1,-1,"",0,4,"eo",66,0,-1,0,19,19,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00094",9,"El amar de las mujeres\nes como el del gallinazo,\nque en comiéndose la carne\nal hueso no le hacen caso.",197,3,-1,-1,"",0,4,"ao",145,0,-1,0,19,19,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00095",9,"Antes de conocerte,\nya te quería,\ny soñaba contigo\nhasta de día.",197,3,-1,-1,"",6,4,"ia",0,0,-1,0,19,19,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00096",9,"Cuando una mujer te diga\nque te quiere y te idolatra,\nes porque te tiene vista\nla bolsa llena de plata.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,19,19,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00097",9,"Desde que te ví, te amé,\ny todo fue de improviso;\nno sé qué sería primero,\nsi amarte o haberte visto.",197,3,-1,-1,"",0,4,"io",-1,0,-1,0,19,19,"","",0,"","","",17,0,0,[],""],["isaacs_colombia-00098",9,"Cuando una mujer te dice\nque te quiere y que te adora,\nes porque te tiene puesto\ntu buen marchante a la cola.",197,3,-1,-1,"",0,4,"oa",-1,0,-1,0,19,19,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00099",9,"Qué bonita está la luna,\ny un lucero la acompaña;\n¡qué triste se pone un hombre\ncuando una mujer lo engaña!",197,3,-1,-1,"",0,4,"aa",213,0,-1,0,20,20,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00100",9,"Yo soy hombre entre los hombres\ny entre las gallinas, gallo,\ny en el corral de mis yeguas\nno me relincha caballo.",197,3,-1,-1,"",0,4,"ao",102,0,-1,0,20,20,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00101",9,"Cinta colorada\nde la nueva unión,\nteñida con sangre\nde mi corazón.",197,3,-1,-1,"",0,4,"o",31,0,-1,0,20,20,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00102",9,"Me decís que me querés;\nyo digo que así será:\npara mí será el cariño,\npara otro... la voluntá.",197,3,-1,-1,"",0,4,"a",9,0,-1,0,20,20,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00103",9,"Águila que vas volando\ny en el pico llevas viento,\nllévame este papelito\ndonde está mi pensamiento.",197,3,-1,-1,"",0,4,"eo",94,0,-1,0,20,20,"","",0,"","","",10,0,0,[],""],["isaacs_colombia-00104",9,"Ya me lo quiere decir,\ny yo que se las entiendo...\nplata es lo que necesita\ny esa es la que yo no tengo.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,20,20,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00105",9,"Aguila que vas volando\ny en el pico llevas flores,\nllévale este papelito\nal amor de mis amores.",197,3,-1,-1,"",0,4,"oe",5,0,-1,0,20,20,"","",0,"","","",10,0,0,[],""],["isaacs_colombia-00106",9,"Morenito soy, señora,\nyo no niego mi color,\nque entre rosas y azucenas\nlo moreno es lo mejor.",197,3,-1,-1,"",0,4,"o",72,0,-1,0,20,20,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00107",9,"El naranjo tiene espinas,\nsiendo un árbol tan frondoso\nmi corazón es el firme\ny el tuyo es el engañoso.",197,3,-1,-1,"",0,4,"oo",160,0,-1,0,20,20,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00108",9,"¡Cuántas guayabas maduras!\n¡Cuánto limón por el suelo!\n¡Cuántas muchachas bonitas!\n¡Cuánto galán sin dinero!",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,20,20,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00109",9,"Yo soy como el tominejo,\nque pica de flor en flor,\npues de todas me enamoro\ny en ninguna pongo amor.",197,3,-1,-1,"",0,4,"o",-1,0,-1,0,20,20,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00110",9,"Dicen que los que se mueren\nprimero visiones ven;\nyo he visto unos ojos negros...\nno sé si me moriré.",197,3,-1,-1,"",0,4,"e",-1,0,-1,0,20,20,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00111",9,"Yo soy el zambo sarambo\nque fuma tabaco en bomba,\ny si saco mi garrote\nno hay zambo que se me ponga.",197,3,-1,-1,"",0,4,"oa",-1,0,-1,0,20,20,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00112",9,"Corazones partidos\nyo no los quiero,\nque cuando doy el mío\nlo doy entero.",197,3,-1,-1,"",6,4,"eo",38,0,-1,0,21,21,"","",0,"rm_t3, palau_cantares, leonesas_diez","","",7,0,0,[],""],["isaacs_colombia-00113",9,"fueron los tres parasismos\nque en el corazón me dieron.\nA ti te estarán vistiendo\nde blanco, verde y azul,\ny a mi me estarán diciendo:\n“Hermano, diga Jesús”.",197,3,-1,-1,"",9,6,"u",-1,0,-1,0,21,21,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00114",9,"Dicen que los celos matan;\nlos celos no matan, no,\nque silos celos mataran\nya me hubierta muerto yo.",197,3,-1,-1,"",0,4,"o",2,0,-1,0,21,21,"","",0,"","","",6,0,0,[],""],["isaacs_colombia-00115",9,"A ti te estarán probando\nel lindo traje de gala,\ny a mí me estarán sacando\ndel aposento a la sala.",197,3,-1,-1,"",1,4,"aa",330,0,-1,0,21,21,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00116",9,"Mi madre me las pegó\nporque le pedí marido;\nvuélvame, madre, a pegar\ny deme lo que le pido.",197,3,-1,-1,"",0,4,"io",101,0,-1,0,21,21,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00117",9,"A ti te estarán poniendo\nlas sortijas, los zarcillos,\ny a mí me estarán cargando\nen sus hombros mis amigos.",197,3,-1,-1,"",0,4,"io",-1,0,-1,0,21,21,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00118",9,"Cuando un hombre se enamora\nde mujer que no lo quiere,\nes lo mismo que encontrarse\nun calvo, en la calle, un peine.",197,3,-1,-1,"",0,4,"ee",-1,0,-1,0,21,21,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00119",9,"En la puerta de la iglesia\na él le entregarán tu mano,\ny a mí me estarán poniendo\nun hábito franciscano.",197,3,-1,-1,"",0,4,"ao",81,0,-1,0,21,21,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00120",9,"Allá arriba en aquel alto\nhay un pozo entre limones,\ndonde lloran las mocitas\ntiernamente por los hombres.",197,3,-1,-1,"",0,4,"oe",-1,0,-1,0,21,21,"","",0,"","","",10,0,0,[],""],["isaacs_colombia-00121",9,"En la puerta de la iglesia\nsaldré a recibirte el cura,\ny a mí me estarán llevando\na mi triste sepultura.",197,3,-1,-1,"",0,4,"ua",17,0,-1,0,21,21,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00122",9,"Yo supe que te casabas\ny no fuí a tu casamiento\npor no ver otro sentado\ndonde pusiste mi asiento.",197,3,-1,-1,"",0,4,"eo",94,0,-1,0,21,21,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00123",9,"A ti te estarán poniendo\nen el cuello la cadena,\ny a mí me estará cubriendo\nla primer capa de tierra.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,21,21,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00125",9,"¡Qué recio bailan los novios!\n¡qué recio que están bailando!\nmás recios suenan los golpes\ndel cuerpo que están pisando.",197,3,-1,-1,"",0,4,"ao",33,0,-1,0,22,22,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00126",9,"Quien se enamora de una\ndebe completar las dos,\ny si no ajusta las tres\nno tiene perdón de Dios.",197,3,-1,-1,"",0,4,"o",87,0,-1,0,22,22,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00127",9,"¿De qué te sirve, señora,\ntanta gala y hermosura\nsi todo viene a quedar\nal pie de la sepultura?",197,3,-1,-1,"",0,4,"ua",17,0,-1,0,22,22,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00128",9,"La niña que está bailando\nse parece a Santa Rita,\npor los ojitos humildes\ny esa boca tan bonita.",197,3,-1,-1,"",0,4,"ia",50,0,-1,0,22,22,"","",0,"","","",19,0,0,[],""],["isaacs_colombia-00129",9,"Haré por ti un sacrificio,\nel que tú por mí no harás:\nquererte sin que me quieras;\n¿Qué más quieres? ¿Quieres más?",197,3,-1,-1,"",0,4,"a",51,0,-1,0,22,22,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00130",9,"Si porque te quiero piensas\nque ya me voy a casar,\nescapa la banderilla,\nque yo lo que sé es torear.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,22,22,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00131",9,"Yo no soy de por aquí:\nyo soy de Barquisimeto:\nnadie se meta conmigo\nque yo con nadie me meto.",197,3,-1,-1,"",0,4,"eo",543,0,-1,0,22,22,"","",0,"","","",11,0,0,[],""],["isaacs_colombia-00132",9,"Desde mi tierra he venido\npisando espinas y abrojos\nsólo por venir a verte,\nvida mía de mis ojos.",197,3,-1,-1,"",0,4,"oo",99,0,-1,0,22,22,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00133",9,"Yo no soy de por aqui;\nyo soy de ciertos lugares:\nnadie se meta conmigo,\no le rayo los ijares.",197,3,-1,-1,"",0,4,"ae",164,0,-1,0,22,22,"","",0,"","","",11,0,0,[],""],["isaacs_colombia-00134",9,"Desde mi tierra he venido\npisando espinas y abrojos\nsólo por venir a ver,\nvida de mi alma, esos ojos.",197,3,-1,-1,"",0,4,"oo",99,0,-1,0,22,22,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00135",9,"Querer una, no es ninguna;\nquerer dos, algo será:\ncuando la una esté brava,\nla otra contenta estará.",197,3,-1,-1,"",0,4,"a",9,0,-1,0,22,22,"","",0,"","","",7,0,0,[],""],["isaacs_colombia-00136",9,"Desde mi tierra he venido\nrodando como pelota\nsólo por venirte a ver,\nbarriga de puerca chota.",197,3,-1,-1,"",0,4,"oa",432,0,-1,0,22,22,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00137",9,"Niña de los veinte novios,\nya conmigo son veintiuno;\nsi todos son como yo\nte quedarás sin ninguno.",197,3,-1,-1,"",0,4,"uo",230,0,-1,0,23,23,"","",0,"","","",11,0,0,[],""],["isaacs_colombia-00138",9,"Si porque te estoy queriendo\nte manifiestas infiel,\nsabe que estás en el mundo\ny “que a donde ha de ir el buey”",197,3,-1,-1,"",0,4,"e",-1,0,-1,0,23,23,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00139",9,"Allá te mandé un pañuelo\nllenito de colación;\nla punta estaba manchada\ncon sangre del corazón.",197,3,-1,-1,"",0,4,"o",31,0,-1,0,23,23,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00140",9,"Si porque te estoy queriendo\nme das tantas amarguras,\nsabe que estás en el mundo,\ny “el que ha de morir a oscuras",197,3,-1,-1,"",0,4,"ua",238,0,-1,0,23,23,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00141",9,"Estos mocitos de ahora\nmucho gastan en planchado:\nirles a ver el bolsillo\nlleno de plátano asado.",197,3,-1,-1,"",0,4,"ao",14,0,-1,0,23,23,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00142",9,"Para los bimbos maíz,\npara los gansos pescado,\ncomo la mujer bonita\npara el hombre enamorado.",197,3,-1,-1,"",0,4,"ao",14,0,-1,0,23,23,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00143",9,"Mañana me voy de aquí,\ncomo todos lo verán;\na vuelta de mis espaldas\nsabe Dios lo que dirán.",197,3,-1,-1,"",0,4,"a",147,0,-1,0,23,23,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00144",9,"A las gallinas maíz,\na las garzas el pescado,\ny las muchachas bonitas\npara el hombre enamorado.",197,3,-1,-1,"",0,4,"ao",14,0,-1,0,23,23,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00145",9,"Aunque no me quieras más\ndespués de haberme querido,\nsiempre me queda un consuelo:\nen tus brazos he dormido.",197,3,-1,-1,"",0,4,"io",101,0,-1,0,23,23,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00146",9,"Asómate a la vergüenza\ncara de poca ventana\ny échame un jarro de sed\nque me estoy muriendo de agua.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,23,23,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00147",9,"Si porque te estoy queriendo\nte manifiestas ingrata,\nsabe que estás en el mundo,\ny “quien a cuchillo mata”",197,3,-1,-1,"",0,4,"aa",74,0,-1,0,23,23,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00148",9,"Asómate a la ventana\ny ve lo que van vendiendo;\nlos calzones de tu amante\nhechos un solo remiendo,",197,3,-1,-1,"",0,4,"eo",52,0,-1,0,23,23,"","",0,"","","",13,0,0,[],""],["isaacs_colombia-00149",9,"Las muchachas de esta tierra\nson como pocas, bonitas:\npero son más pedigüeñas\nque las ánimas benditas.",197,3,-1,-1,"",0,4,"ia",258,0,-1,0,24,24,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00150",9,"Al señor garrapatero\nlo llaman para escribano,\ny él dice que no podrá\nporque le tiembla la mano.",197,3,-1,-1,"",0,4,"ao",81,0,-1,0,24,24,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00151",9,"Te quiero más que a mí mismo,\nte quiero más que a mi madre,\ny si no fuera pecado,\nmás que a la Virgen del Carmen.",197,3,-1,-1,"",0,4,"ae",-1,0,-1,0,24,24,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00152",9,"En un hospital de amores\nun loco me aconsejó\nque no quisiera a una sola,\nque de eso se enloqueció.",197,3,-1,-1,"",0,4,"o",2,0,-1,0,24,24,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00153",9,"Las mujeres son el diablo,\nson el mismo lucifer;\nse visten por la cabeza,\nse desvisten por los pies.",197,3,-1,-1,"",0,4,"e",-1,0,-1,0,24,24,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00154",9,"Si un caballero te manda\nque le ensilles el caballo,\ndéjale la cincha floja\naunque se lo lleve el diablo.",197,3,-1,-1,"",0,4,"ao",-1,0,-1,0,24,24,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00155",9,"Hasta los palos del monte\nnacen con separación:\ncon los unos hacen santos\ny con los otros carbón.",197,3,-1,-1,"",0,4,"o",31,0,-1,0,24,24,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00156",9,"Antonio, te tengo dicho\nque echés ese gato afuera,\nporque no quiero en mi casa\n(que a mi madre no le gustan)\ngatos de cabeza negra",197,3,-1,-1,"",7,5,"ea",-1,0,-1,0,24,24,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00156-e2",9,"¡Quíchito, perro!\n¡Quichito, gato!\nsi no lo espanta\nyo ya lo mato.",197,3,-1,-1,"",6,4,"ao",19,0,-1,0,24,24,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00157",9,"De una costilla de Adán\nhizo Dios a la mujer,\npara que el hombre tuviera\nese hueso que roer.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,24,24,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00158a",9,"Antonio, te tengo dicho,\npor el Ángel San Gabriel,\nque me prestes los zurrones\npara que tiren la miel",197,3,-1,-1,"",0,4,"e",32,0,-1,0,24,24,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00158b",9,"¡Quíchito, perro!\n¡Quíchito, gato!\nsi no lo espanta\nya yo lo mato.",197,3,-1,-1,"",6,4,"ao",19,0,-1,0,24,24,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00159",9,"Si el naranjito de amores\nno tuviera sus azares,\nfuera mi quita-dolores,\nfuera mi quita-pesares.",197,3,-1,-1,"",1,4,"ae",164,0,-1,0,24,24,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00160",9,"Toma un puñal,\nrómpeme el pecho,\nve tu retrato,\nque está bien hecho.",197,3,-1,-1,"",6,4,"eo",60,0,-1,0,25,25,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00161",9,"El amor es un bichito\nque por los ojos se mete,\ny en llegando al corazón,\nFrancisco Javier, tenéte.",197,3,-1,-1,"",0,4,"ee",285,0,-1,0,25,25,"","",0,"carrizo_salta","","",10,0,0,[],""],["isaacs_colombia-00162",9,"Con esta muchachita\nme caso yo;\nbendita sea la madre\nque la parlo.",197,3,-1,-1,"",6,4,"ao",-1,0,-1,0,25,25,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00163",9,"Una vez que te dije\nque me quisieras,\nte pusiste más alta\nque las estrellas.",197,3,-1,-1,"",6,4,"ea",-1,0,-1,0,25,25,"","",0,"","","",6,0,0,[],""],["isaacs_colombia-00164",9,"El corazón, site veo,\nparece que se me parte;\ny mi alma quiere salir\npara verte y abrazarte.",197,3,-1,-1,"",0,4,"ae",8,0,-1,0,25,25,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00166",9,"La voluntad que te tengo\n¡Cuándo se me ha de acabar,\nsi cada vez que te veo\nme consuelo con llorar!",197,3,-1,-1,"",0,4,"a",21,0,-1,0,25,25,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00167",9,"Las muchachitas de mi tierra\nson como el terrón de azúcar;\nel que las llega a probar\nhasta los dedos se chupa.",197,3,-1,-1,"",0,4,"ua",-1,0,-1,0,25,25,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00168",9,"Mi pecho, si hablas, suspira;\ny al verte, solloza el alma,\ny si te miro, a mis ojos\nse asoma siempre una lágrima.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,25,25,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00169",9,"Los ojos de mi morena\nse parecen a mis males;\nnegros como mi fortuna,\ngrandes como mis pesares.",197,3,-1,-1,"",0,4,"ae",-1,0,-1,0,25,25,"","",0,"","","",23,0,0,[],""],["isaacs_colombia-00170",9,"Ojos verdes son el mar;\nojos azules, el cielo;\nojos pardos, purgatorios,\ny ojos negros, el infierno.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,25,25,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00171",9,"Hice voto de quererte,\nmil empeños de adorarte:\nfortuna fue conocerte,\ndesgracia fuera olvidarte.",197,3,-1,-1,"",1,4,"ae",8,0,-1,0,25,25,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00172",9,"Una guacharaca mansa\ny un chilacó cimarrón,\ny una muchacha bonita\nque me roba el corazón.",197,3,-1,-1,"",0,4,"o",31,0,-1,0,26,26,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00173",9,"Mis ojos tienen la culpa,\ncon ellos he de pelear,\nporque con ellos he visto\nlo que no puedo olvidar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,26,26,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00174",9,"Por aquella ventana\nme tiran flechas;\ncomo sean de tus manos,\nvengan derechas.",197,3,-1,-1,"",6,4,"ea",658,0,-1,0,26,26,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00175",9,"Mañana me voy de aquí,\nmañana será mi viaje;\nsólo un beso y un abrazo\nserán mi matalotaje.",197,3,-1,-1,"",0,4,"ae",231,0,-1,0,26,26,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00176",9,"No digo que no me gustan\ntus gracias y tu belleza;\npero del amor al gusto\nhay una distancia inmensa.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,26,26,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00177",9,"Mi vida, si así deseas\na mis penas dar alivio,\nbusca pronto la ocasión\nde verte a solas conmigo.",197,3,-1,-1,"",0,4,"io",-1,0,-1,0,26,26,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00178",9,"Hay ojos que dan enojos,\nhay ojos que congracean,\nhay ojos que con mirar\nconsiguen lo que desean.",197,3,-1,-1,"",0,4,"ea",390,0,-1,0,26,26,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00179",9,"¿De qué me sirve llorar\nsi mi dueño no lo sabe?\nlas lágrimas en ausencia\ncuestan mucho y poco valen.",197,3,-1,-1,"",0,4,"ae",-1,0,-1,0,26,26,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00180",9,"Amantes fuimos y somos,\namantes hemos de ser,\nporque no hay poder humano\nque al amor pueda vencer,",197,3,-1,-1,"",0,4,"e",20,0,-1,0,26,26,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00181",9,"Primero que encuentres,\nniña, amor firme como el mío,\nse volverán plata y oro\nlos arenales del río.",197,3,-1,-1,"",0,4,"io",3,0,-1,0,26,26,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00182",9,"La pobreza es un borrón\nque a todo mundo oscurece:\nal pobre, aunque sea muy noble,\nno lo ven como merece.",197,3,-1,-1,"",0,4,"ee",64,0,-1,0,26,26,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00183",9,"Me acuerdo, que, llorando,\ndijiste un día,\nque sólo con la muerte\nme olvidarías.",197,3,-1,-1,"",6,4,"ia",-1,0,-1,0,26,26,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00185",9,"¿Dices que no me quieres?\ntengo el consuelo\nde saber que tú sabes\nque yo te quiero.",197,3,-1,-1,"",6,4,"eo",-1,0,-1,0,27,27,"","",0,"","","",14,0,0,[],""],["isaacs_colombia-00186",9,"Si porque te quiero, quieres\nque yo la muerte reciba,\nhágase tu voluntad;\nmuera yo porque otro viva.",197,3,-1,-1,"",0,4,"ia",53,0,-1,0,27,27,"","",0,"preciso_coleccion","","",10,0,0,[],""],["isaacs_colombia-00187",9,"La camisa tengo rota\ny yo no la he de coser\nen todos los agujeros\ntusitas le he de meter.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,27,27,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00188",9,"Si me vieras padecer\npor tí, niña, tan de veras,\nlástima te había de dar\naunque amor no me tuvieras.",197,3,-1,-1,"",0,4,"ea",103,0,-1,0,27,27,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00189",9,"Amante leal y rendido\ntu amistad solicité,\ny tan infeliz fuí que\nme hallé mal correspondido.",197,3,-1,-1,"",11,4,"io",101,0,-1,0,27,27,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00190",9,"Yo comí de la retama,\ndel cogollo la mitad\npues no hay cosa más amarga\nque un amor pagado mal.",197,3,-1,-1,"",0,4,"a",-1,0,-1,0,27,27,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00191",9,"¿Has vista cuando, al tomar\nun músico el instrumento,\naplica el oído atento\nhasta poderlo templar;\ny si luego, al registrar,\nuna cuerda falsa siente\npone la mano impaciente,\ntuerce la clavija airado\ny da por muy bien empleado\nque esa cuerda se reviente?",197,3,-1,-1,"",18,10,"ee",15,0,-1,0,27,27,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00192",9,"Ahora que está bailando\nla rosa con el clavel\nla rosa que se deshoja\ny el clavel la va a coger.",197,3,-1,-1,"",0,4,"e",-1,0,-1,0,27,27,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00193",9,"Por haber mi amor mudado\nte quejas a grito herido:\nme espanta el haber querido\nmas no el haberme cansado.",197,3,-1,-1,"",11,4,"ao",14,0,-1,0,27,27,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00194",9,"Morir será lo mejor;\nmis penas se acabarán:\nmis padres me llorarán,\nque abandoné por tu amor.",197,3,-1,-1,"",11,4,"o",72,0,-1,0,27,27,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00196",9,"El amor que te tenía\nera poco y se acabó:\nlo puse en una lomita\ny el viento se lo llevó.",197,3,-1,-1,"",0,4,"o",2,0,-1,0,27,28,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00198",9,"Eres un granito de oro\nensartado en un bejuco;\n¿Cómo quieres que te quiera\nsi tu cuerpo es tan maluco?",197,3,-1,-1,"",0,4,"uo",659,0,-1,0,28,28,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00199",9,"De dos amores que tuve,\nal uno le dió la peste\ny el otro que me ha quedado...\nVen, Coco, y llevaste éste.",197,3,-1,-1,"",0,4,"ee",396,0,-1,0,28,28,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00200",9,"Desde mi tierra he venido\npisando chiribitales,\nsólo por venirte a ver,\nboquita de dos corales.",197,3,-1,-1,"",0,4,"ae",26,0,-1,0,28,28,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00201",9,"Si el amor que puse en ti,\ntan firme y tan verdadero,\nyo lo hubiera puesto en Dios\nme hubiera ganado el cielo.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,28,28,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00202",9,"Mi mulita la tenía\namarrada en la quebrada,\ncomo era de contrabando\nse la llevaron los guardas.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,28,28,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00203",9,"Dices que nada te quiero,\n¿Por qué no te he de querer?\nyo me hago el desentendido\npara no darlo a entender.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,28,28,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00204",9,"¡Lástima de mi mulita!\n¿Para qué la vendería?\ncuando yo montaba en ella,\nen el paso se dormía.",197,3,-1,-1,"",0,4,"ia",0,0,-1,0,28,28,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00205",9,"El amor que te tenía\nera de vara y tres cuartas;\nlo puse en la talanquera;\nse lo comieron las vacas.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,28,28,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00206",9,"—Dime, niña bonita,\n¿Quién te mantiene?\n—Las tropas de Colombia\nque van y vienen.",197,3,-1,-1,"",6,4,"ee",-1,0,-1,0,28,28,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00207",9,"Déjame seguirte al monte,\ndéjame coger la flor,\ndéjame dormir un sueño\nen tus bracitos, mi amor.",197,3,-1,-1,"",0,4,"o",72,0,-1,0,28,28,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00208",9,"Adiós, ramita de albahaca,\ncogollo de ajonjolí,\nme tienes inquieta el alma\ndesde la hora en que te vi.",197,3,-1,-1,"",0,4,"i",23,0,-1,0,28,28,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00209",9,"Déjame dentrar al monte,\ndéjame coger las ramas,\ndéjame dormir un sueño\nen tu regalada cama.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,28,28,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00210",9,"Dígame, Señor herrero,\ncuánto fierro ha menester\npara ponerle un candado\nen la boca a mi mujer.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,29,29,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00211",9,"Te dije que te quería\ny siempre te estoy queriendo;\nel amor que te tenía\nsiempre te lo estoy teniendo.",197,3,-1,-1,"",1,4,"eo",52,0,-1,0,29,29,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00212",9,"El alcalde me destierra,\nel cura me descomulga,\nmi madre me muele a palos\ny el amor zumba que zumba.",197,3,-1,-1,"",0,4,"ua",-1,0,-1,0,29,29,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00213",9,"Cuando vas a comprar paño\npide la muestra,\nque en el paño hay mucho engaño,\ncomo en la mujer compuesta.",197,3,-1,-1,"",3,4,"ea",-1,0,-1,0,29,29,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00214",9,"La mujer amorosa\ncorre el peligro\nde las flores que nacen\njunto al camino.",197,3,-1,-1,"",6,4,"io",-1,0,-1,0,29,29,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00215",9,"Al diablo doy la mujer\nque viste enaguas en suma,\nporque ave de mucha pluma\ntiene poco qué comer.",197,3,-1,-1,"",11,4,"e",20,0,-1,0,29,29,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00217",9,"El corazón me has pedido\nsiendo una cosa tan dura;\nsi te doy el corazón\nse me daña la asadura.",197,3,-1,-1,"",0,4,"ua",17,0,-1,0,29,29,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00218",9,"El amor del hombre pobre\nes como el del gallo enano,\nque en correr y no alcanzar\nse le pasa todo el año.",197,3,-1,-1,"",0,4,"ao",-1,0,-1,0,29,29,"","",0,"","","",6,0,0,[],""],["isaacs_colombia-00219",9,"En el patio de mi casa\ncorre el agua a borbollón;\nquien te dió casa de teja\nque te dé la varazon.",197,3,-1,-1,"",5,4,"ao",-1,0,-1,0,29,29,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00220",9,"No te alegres de mi mal,\nque pende de una campana,\npues lo que hoy pasa por mí\npasará por ti mañana.",197,3,-1,-1,"",0,4,"aa",4,0,-1,0,29,29,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00222",9,"A la quebradita fui\nsólo por verte pasar;\nhasta el agua se enternece\nde ver mis ojos llorar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00223",9,"A mi mamita le pido\nque no me case con tuerto,\nporque parece dormido\ncuando se está más despierto.",197,3,-1,-1,"",1,4,"eo",88,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00224",9,"Dicen que una hermosa dama\nel corazón me entregó;\npero el corazón, sin ella,\n¿para qué lo quiero yo?",197,3,-1,-1,"",0,4,"o",2,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00225",9,"Cogí la rosa en la mano\ny le sacudí el rocío\npara ver si se juntaba\ntu corazón con el mío.",197,3,-1,-1,"",0,4,"io",3,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00226",9,"El corazón de mi dama\ndicen que lo tengo yo;\nel corazón sin la dama\n¿para qué lo quiero yo?",197,3,-1,-1,"",1,4,"o",-1,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00227",9,"Aunque el alcalde me coja\ny los grillos me remache,\nyo nunca te olvidaré\nporque así fue el cambalache.",197,3,-1,-1,"",0,4,"ae",531,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00228",9,"Una ocasión que lloré\nme callaron con mamar;\ncebadito me quedé\na cada rato llorar.",197,3,-1,-1,"",1,4,"a",21,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00229",9,"Dicen que el águila negra\nes la reina de las aves,\ny tus ojos han de ser\nde mi corazón las llaves.",197,3,-1,-1,"",0,4,"ae",129,0,-1,0,30,30,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00230",9,"Echame mi manta afuera,\nmi mochila y mi bordón,\ny mis dos pares de albarcas\ny verás como me voy.",197,3,-1,-1,"",0,4,"o",-1,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00231",9,"Dicen que el águila negra\nes la reina de las aves,\ny tus negros ojos son\nde mi corazón las llaves.",197,3,-1,-1,"",0,4,"ae",129,0,-1,0,30,30,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00232",9,"Ese tiempo que gasté\nen quererte, vida mía,\ngastado en torcer cabuya,\nya hubiera hecho una guambía.",197,3,-1,-1,"",0,4,"ia",0,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00233",9,"Tienes unos ojos negros\nque parecen de azabache;\nsi fueras cambalachera,\nyo te hiciera cambalache.",197,3,-1,-1,"",0,4,"ae",531,0,-1,0,30,30,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00234",9,"Mi mujer y mi caballo\nse me murieron a un tiempo:\nqué mujer ni qué demonio,\nmi caballo es lo que siento.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,31,31,"","",0,"carrizo_salta, palau_cantares, lafuente_madrid","","",8,0,0,[],""],["isaacs_colombia-00235",9,"Si piensas que por tu amor\nme he de volver aceituna,\nadvierte que soy muchacha\ny que me sobra fortuna.",197,3,-1,-1,"",0,4,"ua",56,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00236",9,"Decime si me querés,\nno me andés con salvajadas;\nayer te escribí una carta\ncon letricas coloradas.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00237",9,"Esos tus ojos tan negros\ncon que me alzas a mirar,\nabájalos un poquito\nque me puedo condenar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00238",9,"No digo que no me gusten\nlas gracias de su belleza\npero del amor al gusto\nhay una distancia inmensa.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00239",9,"Echate por la ventana\nque yo te recibiré,\ny si acaso te matares\ndirás que yo te maté.",197,3,-1,-1,"",0,4,"e",77,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00240",9,"En el otro lado vive\nla que a mí me está queriendo;\nella está llena de chunche\ny hasta a mi me está cundiendo.",197,3,-1,-1,"",0,4,"eo",52,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00241",9,"Tienes unos ojitos\ny unas pestañas\ny una boca embustera\ncon que me engañas.",197,3,-1,-1,"",6,4,"aa",42,0,-1,0,31,31,"","",0,"","","",16,0,0,[],""],["isaacs_colombia-00242",9,"Si alguna quiere saber\ncómo enamoran los blancos,\nasómese a una ventana...\n— Señora, cómpreme santos.",197,3,-1,-1,"",0,4,"ao",-1,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00243",9,"Si tu fueras formalita\nyo te diera una camisa\npero eso es vestir altar\npara que otro diga misa.",197,3,-1,-1,"",0,4,"ia",68,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00244",9,"Anoche, mi bien, soñé\nque unos negros me mataban,\ny eran tus dos ojos negros\nque enojados me miraban.",197,3,-1,-1,"",0,4,"aa",39,0,-1,0,31,31,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00245",9,"Yo no quiero tus amores\nni tampoco tu camisa:\ntengo quien vista el altar\ny también quién diga misa.",197,3,-1,-1,"",0,4,"ia",68,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00246",9,"Fuerza de amor me obligó\na escribirte, porque en suma,\npara eso dice la pluma\nlo que un vergonzoso no.",197,3,-1,-1,"",11,4,"o",2,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00247",9,"¡Ojos negros, ojos negros!\n¿Por qué me miráis así?\ntan alegres para otros\ny tan tristes para mí!",197,3,-1,-1,"",0,4,"i",23,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00248",9,"El que te escribe soy yo,\ny la que dicta es el alma;\nel que se muere por ti\nya sabes cómo se llama.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00249",9,"En las balanzas de amor\nestán pesando firmezas:\n¿Qué importa que el fiel sea firme\nsi el engaño está en las pesas?",197,3,-1,-1,"",0,4,"ea",660,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00250",9,"Con tinta negra te escribo\nporque muy negra es mi suerte;\nlos renglones apartados\nporque de ti vivo ausente.",197,3,-1,-1,"",0,4,"ee",-1,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00251",9,"Temeroso de un desprecio\nvivo muriendo de amor,\ny estoy pasando una vida\nmás triste que la de Job.",197,3,-1,-1,"",0,4,"o",-1,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00252",9,"Las mocitas de este tiempo\ncon trabajo hallan esposo,\npues se dejan engañar\ncon sortijas de corozo.",197,3,-1,-1,"",0,4,"oo",156,0,-1,0,32,32,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00253",9,"Temo que me des el pago\nque le dió David a Unas,\ny así, con tanta aflicción\nlloro como Jeremias.",197,3,-1,-1,"",5,4,"ea",-1,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00255",9,"La mujer y la gallina\ntienen instintos iguales:\nquieren mucho al sexo opuesto\ny del suyo son rivales.",197,3,-1,-1,"",0,4,"ae",26,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00256",9,"Daré mis quejas al mar,\na lo hondo y más profundo,\nque de tus ingratitudes\nno quiero que sepa el mundo.",197,3,-1,-1,"",0,4,"uo",179,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00257",9,"Pavita del monte\ndéjame pasar,\nque voy de camino\npara Popayán.",197,3,-1,-1,"",0,4,"a",-1,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00258",9,"En Cali me dieron fríos,\nen Caloto calentura,\nen Cartago fue mi muerte\ny en Buga mi sepultura.",197,3,-1,-1,"",0,4,"ua",17,0,-1,0,33,33,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00259",9,"Dicen que no se siente\nla despedida:\ndile al que te lo dice\nque se despida.",197,3,-1,-1,"",6,4,"ia",37,0,-1,0,33,33,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00260",9,"De los chuyacos del día\nmi chuyaco es el mejor,\nporque mi chuyaco tiene\najo, pimienta y color.",197,3,-1,-1,"",0,4,"o",72,0,-1,0,33,33,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00261",9,"Yo no soy de por aquí,\nyo vine del otro lado,\nque me trajo un capuchino\nen las barbas enredado.",197,3,-1,-1,"",0,4,"ao",14,0,-1,0,33,33,"","",0,"","","",11,0,0,[],""],["isaacs_colombia-00262",9,"Las mujeres de este tiempo\nson como las avellanas:\nde ciento sale una buena\ny noventa y nueve vanas.",197,3,-1,-1,"",0,4,"aa",263,0,-1,0,33,33,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00263",9,"Por aquélla loma arriba\nmuchos cazadores van;\nunos cazando perdices\ny otros las hijas de Adán.",197,3,-1,-1,"",0,4,"a",147,0,-1,0,33,33,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00264",9,"Mi mujer y mi caballo\ncomen en un mismo plato;\nmi mujer por lo garosa\ntiene a mi caballo flaco.",197,3,-1,-1,"",0,4,"ao",-1,0,-1,0,33,33,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00265",9,"La perdiz en el monte\ncantando dice:\n¿la mujer que es hermosa,\npor qué se aflije?",197,3,-1,-1,"",6,4,"ie",-1,0,-1,0,33,33,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00266",9,"Los suspiros que yo doy\nsalen de mi pecho franco,\ny se dirigen al tuyo\ncomo las balas al blanco.",197,3,-1,-1,"",0,4,"ao",303,0,-1,0,33,33,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00267",9,"Con viuda no me casara\nni por plata que tuviera,\nporque a mula que otro amansa\nalgún resabio le queda.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,33,33,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00268",9,"Lucero de la mañana,\nrival de la luz del día,\n¿Por qué no me despertaste\ncuando se fue el alma mía?",197,3,-1,-1,"",0,4,"ia",0,0,-1,0,33,33,"","",0,"","","",22,0,0,[],""],["isaacs_colombia-00269",9,"Si yo fuera gato negro\npor tu ventana me entrara;\na ti te diera un besito\ny a tu madre la arañara.",197,3,-1,-1,"",0,4,"aa",57,0,-1,0,33,33,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00270",9,"Los enemigos del alma\nme enseñaron que eran tres,\ny yo digo que son cuatro\nsi se cuenta la mujer.",197,3,-1,-1,"",0,4,"e",-1,0,-1,0,34,34,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00271",9,"Más allá del infierno\nparió mi suegra\nveinticinco alacranes\ny una culebra.",197,3,-1,-1,"",6,4,"ea",-1,0,-1,0,34,34,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00272",9,"Una olleta de cobre\nme dió mi suegra;\ncada vez que se enoja\nmanda por ella.",197,3,-1,-1,"",6,4,"ea",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00273",9,"Todas las bonitas son\ndulces como el caramelo,\ny yo, como soy meloso,\npor todas ellas me muero.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00274",9,"Una niña me dijo\nque me daría\nuna cosa del seno,\nque ella tema.",197,3,-1,-1,"",6,4,"ea",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00275",9,"Suspiros que van de aquí,\ny otros que vienen de allá,\nse encuentran en el camino\n¿qué de cosas se dirán?",197,3,-1,-1,"",0,4,"a",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00276",9,"Cuando dos quieren a una\ny ella quiere a uno no mas\nparece el aborrecido\nmico cuando chupa agraz.",197,3,-1,-1,"",0,4,"a",253,0,-1,0,34,34,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00277",9,"Desde que no te veo\nno miro flores,\nni los pájaros cantan,\nni el agua corre,",197,3,-1,-1,"",6,4,"oe",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00278",9,"Morenita te buscaba,\nmorenita te encontré;\n¡ay! morena de mi vida,\n¡Cuándo yo te olvidaré!",197,3,-1,-1,"",0,4,"e",77,0,-1,0,34,34,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00279",9,"Mañana cuando me vaya\n¿con qué corazón me iré?\nlos ojos en el camino\ny el corazón en usté.",197,3,-1,-1,"",0,4,"e",77,0,-1,0,34,34,"","",0,"","","",7,0,0,[],""],["isaacs_colombia-00280",9,"Vale más una morena\nque la blanca más hermosa,\nporque la morena tiene...\nno sé que cosa graciosa.",197,3,-1,-1,"",0,4,"oa",63,0,-1,0,34,34,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00281",9,"Mujeres hay en el mundo\ncomo en las tiendas hay ropa;\npero una mujer honrada\npor obra de Dios se topa.",197,3,-1,-1,"",0,4,"oa",608,0,-1,0,34,34,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00282",9,"¿Dices que no me quieres?\nya me has querido;\nya no tiene remedio\nlo sucedido.",197,3,-1,-1,"",6,4,"io",101,0,-1,0,34,34,"","",0,"","","",14,0,0,[],""],["isaacs_colombia-00283",9,"La mujer es una torta\ncasi dulce, casi amarga:\nes un contento a la corta,\nes un tormento a la larga.",197,3,-1,-1,"",1,4,"aa",512,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00285",9,"Mi vida, dame un besito\nque me voy a confesar,\ny si el padre me regaña\nte lo volveré yo a dar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00286",9,"La mujer que sea bonita\na ningún hombre desprecie,\nque con ser el hilo de oro\ndándole vuelta destuerce.",197,3,-1,-1,"",0,4,"ee",-1,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00287",9,"Quieres que te quiera más\nporque no sabes querer,\ny me pierdes por saber\nlo bien querido que estás.",197,3,-1,-1,"",11,4,"a",51,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00288",9,"Por esta calle a lo largo\nunos pobrecitos van\ndesdichados hijos de Eva\ntras de las hijas de Adán.",197,3,-1,-1,"",0,4,"a",147,0,-1,0,35,35,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00289",9,"Mal hacen los ojos negros\nen ponerse en las ventanas,\nporque peca el pecador\naun cuando no tenga ganas.",197,3,-1,-1,"",0,4,"aa",263,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00290",9,"Esperanzas tengo en Dios\nque en el año venidero\nme he de mirar en tus brazos,\nmi vida, si no me muero.",197,3,-1,-1,"",0,4,"eo",38,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00291",9,"Decís que no me querés\nporque no te he dado nada;\nacordate de la pela\nque te di a guasca doblada.",197,3,-1,-1,"",0,4,"aa",49,0,-1,0,35,35,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00292",9,"Debajo de tu ventana\ntengo de pintar un tres,\nuna rosa colorada\ny un clavelito francés.",197,3,-1,-1,"",0,4,"e",218,0,-1,0,35,35,"","",0,"","","",29,0,0,[],""],["isaacs_colombia-00293",9,"¿Para qué sales al puesto\nsi la gracia no te ayuda?\npareces petaca vieja\nbotadora de basura.",197,3,-1,-1,"",0,4,"ua",-1,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00294",9,"Hasta ahora no me acuerdo\npor mujer haber llorado\nsólo por una lloré\nsegún el pago me ha dado.",197,3,-1,-1,"",0,4,"ao",14,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00295",9,"Dos corazones heridos\nde la misma enfermedad;\nambos se dan a la muerte\npor no decir la verdad.",197,3,-1,-1,"",0,4,"a",16,0,-1,0,35,35,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00296",9,"¿De qué le sirve al cautivo\nque le quiten las cadenas\nsi le remachan los grillos,\nquedando en las mismas penas?",197,3,-1,-1,"",0,4,"ea",62,0,-1,0,36,36,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00297",9,"De la peña sale el agua,\ndel agua sale el pescado,\nde la boca de esta niña\nsale un clavel encarnado.",197,3,-1,-1,"",0,4,"ao",14,0,-1,0,36,36,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00298",9,"Aunque los grillos sean de oro\ny las cadenas de plata,\n¿de qué le sirve al cautivo\nsi su libertad le falta?",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,36,36,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00299",9,"Una mujer en coche\ncarne vendía:\n¿quién ha visto en un coche\ncarnicería?",197,3,-1,-1,"",6,4,"ia",0,0,-1,0,36,36,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00300",9,"Como la mariposa\ntengo la suerte,\nque aquella que más amo\nme da la muerte.",197,3,-1,-1,"",6,4,"ee",134,0,-1,0,36,36,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00301",9,"A Cupido lo pintan\nchirriquitico,\nporque ya se acostumbra\nquerer poquito.",197,3,-1,-1,"",6,4,"io",-1,0,-1,0,36,36,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00302",9,"Como la mariposa\nque va volando,\ntengo mis amorcitos\nde cuando en cuando.",197,3,-1,-1,"",6,4,"ao",33,0,-1,0,36,36,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00303",9,"En el centro de la mar\nsuspiraba una sirena,\ny en los suspiros decía:\nquien tiene amor tiene pena.",197,3,-1,-1,"",0,4,"ea",59,0,-1,0,36,36,"","",0,"","","",7,0,0,[],""],["isaacs_colombia-00304",9,"Al infierno tengo d’ir\na hablar con el mismo diablo,\npara que ninguno diga\nque es de miedo que no te hablo.",197,3,-1,-1,"",0,4,"ao",567,0,-1,0,36,36,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00305",9,"Yo te vide persinar,\nmis ojos fueron testigos;\n¡Quién te pudiera besar\ndonde dices enemigos!",197,3,-1,-1,"",1,4,"io",648,0,-1,0,36,36,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00306",9,"Por esta calle a lo largo\njuran que me han de matar\npor unos ojitos negros\nque me alzaron a mirar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,36,36,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00307",9,"Ensillando mi caballo\nmi vidita echó a llorar,\ny yo de verla tan triste\nlo volví a desensillar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,36,36,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00308",9,"Aquella tu quebradita\nanoche mucho creció\ny no me dejó pasar\n¡triste de mí! ¿qué haré yo?",197,3,-1,-1,"",0,4,"o",2,0,-1,0,37,37,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00309",9,"El pájaro mochilero\nes un pájaro grandote\nque se lleva las muchachas\na hacer mochilas al monte.",197,3,-1,-1,"",0,4,"oe",-1,0,-1,0,37,37,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00310",9,"A las mujeres quererlas\ny no darles de comer,\ndarles palo como a mulas\ny agua caliente a beber.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,37,37,"","",0,"","","",7,0,0,[],""],["isaacs_colombia-00311",9,"Por la calle del cura\nvienen bajando\nunos ojitos negros\nde contrabando.",197,3,-1,-1,"",6,4,"ao",33,0,-1,0,37,37,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00312",9,"El hombre que se enamora\nde mujer que no lo quiere,\nmerece cincuenta azotes\ncantándole el miserere.",197,3,-1,-1,"",0,4,"ee",115,0,-1,0,37,37,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00313",9,"Por aquella ventana\nme arrojan flores;\ncomo sean de mi amada,\nvengan olores.",197,3,-1,-1,"",6,4,"oe",5,0,-1,0,37,37,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00314",9,"Dos estrellas se han perdido;\nen los cielos no parecen\npor tus puertas se han entrado\ny en tus ojos resplandecen.",197,3,-1,-1,"",0,4,"ee",359,0,-1,0,37,37,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00315",9,"En el patio de mi casa\ntengo una pila tapada\ndonde se batía mi negra\ncon vino y agua rosada.",197,3,-1,-1,"",0,4,"aa",49,0,-1,0,37,37,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00316",9,"La sortija que me diste\nen el mar se me cayó\nque parezca la sortija\ny el galán que me la dió.",197,3,-1,-1,"",0,4,"o",2,0,-1,0,37,37,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00317",9,"Yo tuve mi tengo tengo\ny ahora no tengo nada;\nasí les sucede a muchas:\ntienen y se les acaba.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,37,37,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00318",9,"El pájara mochilero\nle pregunta al Diostedé,\n— ¿Cómo come sumercé\ncon ese pico tan fiero?",197,3,-1,-1,"",11,4,"eo",38,0,-1,0,37,37,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00319",9,"La chaqueta tengo rota,\nel calzón hecho migajas,\nla camisa hecha un yesquero,\n¡y amor que me vuelvo rajas!",197,3,-1,-1,"",0,4,"aa",661,0,-1,0,37,37,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00320",9,"¡Quién fuera como el patico\nchiquitito y nadador,\nque se bota a la corriente\nen alcance de su amor!",197,3,-1,-1,"",0,4,"o",72,0,-1,0,38,38,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00321",9,"La sortija que me diste\naquí la tengo en el dedo;\ncon ella me enterrarán\nsi esperándote me muero.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,38,38,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00322",9,"En la puerta del cielo\ntocan guitarra:\nSan Pedro la registra\nSan Juan la baila.",197,3,-1,-1,"",6,4,"aa",-1,0,-1,0,38,38,"","",0,"","","",7,0,0,[],""],["isaacs_colombia-00323",9,"A tu madre ya le dije\ny a tu padre no me atrevo\ndímele, pues, vida mía,\nque si quiere ser mi suegro.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,38,38,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00324",9,"En la puerta del cielo\njugaron cañas\nporque parió la Virgen\nen las montañas.",197,3,-1,-1,"",6,4,"aa",42,0,-1,0,38,38,"","",0,"","","",7,0,0,[],""],["isaacs_colombia-00325",9,"Yo pretendí una casada\ny pronto me arrepentí:\nel perro que muerde a su amo\nmás presto me muerde a mi.",197,3,-1,-1,"",0,4,"i",23,0,-1,0,38,38,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00326",9,"Anoche dormí en tus brazos\ndespués de tantos desvelos;\npor estas y por aquellas\nte soñé con otro dueño.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,38,38,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00327",9,"Tres cuartillos tengo aquí,\nque son para enamorar,\nhe de gastar como un loco\ny medio me ha de sobrar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,38,38,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00328",9,"La sortija que me diste\nbien pronto se me perdió;\nprenda de mujer casada\n¿para qué la quiero yo?",197,3,-1,-1,"",0,4,"o",2,0,-1,0,38,38,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00329",9,"En la calle del cura\nvenden mujeres;\nveinticinco al cuartillo,\ncomo alfileres.",197,3,-1,-1,"",6,4,"ee",55,0,-1,0,38,38,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00330",9,"La sortija que me diste\naquí la tengo en el dedo,\ncon ella me llevarán\nal Camposanto del pueblo.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,38,38,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00331",9,"En la calle del cura\nvenden muchachas;\nveinticinco al cuartillo\ncomo arracachas.",197,3,-1,-1,"",6,4,"aa",589,0,-1,0,38,38,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00332",9,"En un palo frondoso\nme ví subida;\nal quebrarse una rama\nme vi caída.",197,3,-1,-1,"",6,4,"ia",37,0,-1,0,39,39,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00333",9,"Ayer pasé por tu puerta\ny me tiraste un limón;\nel agrio me dió en los ojos\ny el golpe en el corazón.",197,3,-1,-1,"",0,4,"o",31,0,-1,0,39,39,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00334",9,"Cálla la boca, caballo,\ncostillas de molendero\nque sólo el rabo te falta\npara ser caballo entero.",197,3,-1,-1,"",0,4,"eo",38,0,-1,0,39,39,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00335",9,"Ayer pasé por tu calle\ny estabas en el balcón;\nno fuiste para tirarme\nde tu jardín una flor.",197,3,-1,-1,"",0,4,"o",-1,0,-1,0,39,39,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00336",9,"iQué muchacha tan bonita!\nsi su madre me la diera,\nme la llevara esta noche\ny mañana la trujera.",197,3,-1,-1,"",0,4,"ea",44,0,-1,0,39,39,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00337",9,"Amores y dolores\nquitan el sueño;\ncomo no tengo amores\ndescanso y duermo.",197,3,-1,-1,"",6,4,"eo",-1,0,-1,0,39,39,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00338",9,"Gavilancito pintado,\n¿dónde vas tan halagüeño?\nen vanos tiendes las alas,\nya esa polla tiene dueño.",197,3,-1,-1,"",0,4,"eo",138,0,-1,0,39,39,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00339",9,"A la vidita de mi alma\nse la lleva su marido;\nno importa que se la lleve\nque yo también sé el camino.",197,3,-1,-1,"",0,4,"io",-1,0,-1,0,39,39,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00340",9,"Allá arriba en aquel alto\nestán vendiendo cachacos,\na veinticinco el cuartillo\ncomo si fueran tabacos.",197,3,-1,-1,"",0,4,"ao",389,0,-1,0,39,39,"","",0,"","","",10,0,0,[],""],["isaacs_colombia-00341",9,"A ninguno le aconsejo\nque quiera mujer casada,\nporque en viniendo el marido\nle hacen largar la mascada.",197,3,-1,-1,"",0,4,"aa",49,0,-1,0,39,39,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00342",9,"Allá arriba, allá en la altura\npor siempre le dije adiós,\ny fue tanta mi amargura\nque sólo lo sabe Dios.",197,3,-1,-1,"",1,4,"o",87,0,-1,0,39,39,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00343",9,"A todos les vas diciendo,\n—Allá va calzones-rotos;\npero a ninguno le has dicho:\n—Yo le hice vender los otros.",197,3,-1,-1,"",0,4,"oo",-1,0,-1,0,39,39,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00344",9,"Ardo y lloro sin sosiego,\nardiendo y llorando tanto,\nque ni el llanto apaga el fuego\nni el fuego consume el llanto.",197,3,-1,-1,"",1,4,"ao",30,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00345",9,"Ay boquita de mi vida,\nboca de mi corazón!...\nesos cielos de tus ojos\na ver cuál es más bocón.",197,3,-1,-1,"",0,4,"o",31,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00346",9,"Aquí me encontré un cuartillo\ny adelante, medio real,\narriba, caballo viejo,\nsácame de este barrial.",197,3,-1,-1,"",3,4,"a",1,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00347",9,"Bonita la rebonita,\n¡bonita como un coral!\n¿qué importa que sea bonita\nsi la quiere un colegial?",197,3,-1,-1,"",1,4,"a",1,0,-1,0,40,40,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00348",9,"Aunque tus ojos recuerdan\nlo hermoso y lo azul del cielo,\nesos cielos de tus ojos\nson para mí dos infiernos.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00349",9,"Como hay en el mar arenas\nhay en mí melancolías,\ntodo soy, todo agonías,\ncorazón lleno de penas.",197,3,-1,-1,"",11,4,"ea",62,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00350",9,"Abrime la puerta, cielo,\nque yo soy la mejorana,\ny si no me abrís aprisa\nme dentro por la ventana.",197,3,-1,-1,"",0,4,"aa",4,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00351",9,"Cantan los pajaritos,\ncantan y dicen\nque los enamorados\nsiempre están tristes.",197,3,-1,-1,"",6,4,"ie",-1,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00352",9,"Anda vete noramala,\nen tu cara te lo digo,\nque por no jugar con tierra\nme puese a jugar contigo.",197,3,-1,-1,"",0,4,"io",106,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00353",9,"Cada vez que yo me acuerdo\nque tuve un amor ingrato,\nno sé cómo no me doy\ncontra un colchón y mato.",197,3,-1,-1,"",0,4,"ao",-1,0,-1,0,40,40,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00354",9,"Allá te mandé un suspiro,\npero no te pudo ver,\ny llegó todo mojado\ncerca del amanecer.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00355",9,"Cuando yo era más chiquito\npreguntaba —¿qué es amor?\ny hora que estoy grandecito\n¡chupa por preguntador!",197,3,-1,-1,"",1,4,"o",72,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00356",9,"¿Cuándo llegará ese día\ny esa dichosa mañana\nen que nos lleven a juntos\nel chocolate a la cama?",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,41,41,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00357",9,"Desde aquí te estoy mirando\ncara a cara y frente a frente\nboquita de enjalma rota\ncachetes de cojinete.",197,3,-1,-1,"",0,4,"ee",-1,0,-1,0,41,41,"","",0,"","","",19,0,0,[],""],["isaacs_colombia-00358",9,"Cuando ayer me despedí\ndel bien que adoraba yo,\nlanzando al cielo un suspiro\nmi corazón se partió.",197,3,-1,-1,"",0,4,"o",2,0,-1,0,41,41,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00359",9,"Dígame, mamita mía,\ndígame por vida suya,\nsi para amarrar un hombre\nse necesita cabuya.",197,3,-1,-1,"",0,4,"ua",111,0,-1,0,41,41,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00360",9,"Cuando salí de mi tierra\nde nadie me despedí;\nlas piedras lloraban sangre\nde un tropezón que me di.",197,3,-1,-1,"",0,4,"i",23,0,-1,0,41,41,"","",0,"","","",9,0,0,[],""],["isaacs_colombia-00361",9,"Dicen los que se casan\nque van al cielo:\nsalen del purgatorio,\nvan al infierno.",197,3,-1,-1,"",6,4,"eo",-1,0,-1,0,41,41,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00362",9,"¿Cuándo llegará ese cuando,\ncuándo llegará ese día\nque por mano del vicario\npase tu mano a la mía?",197,3,-1,-1,"",0,4,"ia",0,0,-1,0,41,41,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00363",9,"Decís que no me querés\nporque no te he dado nada:\nacordate que te di\nuna pela en la quebrada.",197,3,-1,-1,"",0,4,"aa",49,0,-1,0,41,41,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00364",9,"Cansados tengo los ojos\nde mirar aquella loma:\ncuando se bullen las matas\nme parece que ya asoma.",197,3,-1,-1,"",0,4,"oa",86,0,-1,0,41,41,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00365",9,"Díle, niña, a tu madre\nque no sea boba:\nque me tranque la puerta\ncon una escoba.",197,3,-1,-1,"",6,4,"oa",298,0,-1,0,41,41,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00366",9,"Dulce encanto de mi vida,\n¿cómo viviré sin verte?\n¿dónde volveré los ojos\nque no te tenga presente?",197,3,-1,-1,"",0,4,"ee",-1,0,-1,0,41,41,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00367",9,"Ventanas a la calle\nson peligrosas\npara madres que tienen\nhijas hermosas.",197,3,-1,-1,"",6,4,"oa",61,0,-1,0,41,41,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00368",9,"¿Para qué quiere un ciego\ncasa pintada\ncon balcón a la calle\nsi no vé nada?",197,3,-1,-1,"",6,4,"aa",49,0,-1,0,42,42,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00369",9,"El primer amor que tuve\nera como borrachera:\nse me nublaban los ojos\ny me temblaban las piernas.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,42,42,"","",0,"","","",6,0,0,[],""],["isaacs_colombia-00370",9,"De tu casa a la mía\nson mis paseos,\ny casarme contigo\nson mis deseos.",197,3,-1,-1,"",6,4,"eo",662,0,-1,0,42,42,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00371",9,"Esta calle está mojada\ncomo si hubiera llovido,\nde lágrimas de un amante\nque anda por aquí perdido.",197,3,-1,-1,"",0,4,"io",101,0,-1,0,42,42,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00372",9,"De azul celeste viste\nmi sueño amado,\ny yo por imitarle,\nsiempre azulado.",197,3,-1,-1,"",6,4,"ao",14,0,-1,0,42,42,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00373",9,"El árbol de mis amores\nera coposo y lozano:\nla indiferencia lo heló\nlos celos lo deshojaron.",197,3,-1,-1,"",0,4,"ao",-1,0,-1,0,42,42,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00374",9,"De domingo en domingo\nte veo la cara;\n¿cuándo será domingo,\nDios mío de mi alma?",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,42,42,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00375",9,"El perder una bonita\nno es perder ninguna joya:\nes lo mismo que perder\nde la jáquima la argolla.",197,3,-1,-1,"",0,4,"oa",453,0,-1,0,42,42,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00376",9,"Debajo de unos naranjos\nescuché tus juramentos:\ncomo el olor de las flores\nse los llevaron los vientos.",197,3,-1,-1,"",0,4,"eo",234,0,-1,0,42,42,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00377",9,"Ensillando mi cocina\ny entejando mi caballo,\nme fui a defender el runcho\nque no lo matara el gallo.",197,3,-1,-1,"",0,4,"ao",102,0,-1,0,42,42,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00378",9,"Esto de querer a muchas\nes una condenación:\nno puedo comer con gusto\nni rezar con devoción.",197,3,-1,-1,"",0,4,"o",31,0,-1,0,42,42,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00379",9,"En la cárcel me tenían\nyo no sé por qué delito:\nsalté a la plaza,\ncogí la ronda,\nmaté al alcalde\ny al juez distrito.",197,3,-1,-1,"",9,6,"io",119,0,-1,0,42,42,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00380",9,"En el pié de tu ventana\nhizo una perdiz su nido,\ny yo como perdiguero\na tu ventana he venido.",197,3,-1,-1,"",0,4,"io",101,0,-1,0,43,43,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00381",9,"El amor y los celos\nme han obligado\na ausentarme del dueño\nque yo idolatro.",197,3,-1,-1,"",6,4,"ao",-1,0,-1,0,43,43,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00382",9,"Desde la hora en que te vi\nte puse tanta afición,\nque nunca, ni con la muerte,\nsaldrás de mi corazón.",197,3,-1,-1,"",0,4,"o",31,0,-1,0,43,43,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00383",9,"El amor y el cuchillo\nson dos extremos:\nmucho acero en la punta\ny al cabo, un cuerno.",197,3,-1,-1,"",6,4,"eo",-1,0,-1,0,43,43,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00384",9,"El que me oyere cantar\ndirá qué alegre está aquel!\npero tengo el corazón\nmás amargo que la hiel.",197,3,-1,-1,"",0,4,"e",32,0,-1,0,43,43,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00385",9,"El verte me dá la muerte,\ny el no verte me aniquila:\nprefiero la muerte y verte\na no verte y tener vida.",197,3,-1,-1,"",0,4,"ia",-1,0,-1,0,43,43,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00386",9,"El cura de mi parroquia\nme mandó que no te amara\nyo le dije: Señor Cura,\naunque me recondenara.",197,3,-1,-1,"",0,4,"aa",57,0,-1,0,43,43,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00387",9,"El amor y el interés\ncomen juntos en un plato,\nel amor come por horas\ny el interés cada rato.",197,3,-1,-1,"",0,4,"ao",19,0,-1,0,43,43,"","",0,"","","",9,0,0,[],""],["isaacs_colombia-00388",9,"Es tanto lo que te quiero\nque si te miro,\na todos aborrezco,\nde mi me olvido.",197,3,-1,-1,"",6,4,"io",-1,0,-1,0,43,43,"","",0,"","","",26,0,0,[],""],["isaacs_colombia-00389",9,"Es, comadrita, el amor\nclavo que no tiene vuelta;\nmientras más se le maltrata\nmás se consume y aprieta.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,43,43,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00390",9,"Es tanto lo que te quiero\ny lo que te quiero es tanto,\nque por ti duermo en el suelo\ny de cabecera un banco.",197,3,-1,-1,"",0,4,"ao",-1,0,-1,0,43,43,"","",0,"frenk_t1","","",26,0,0,[],""],["isaacs_colombia-00391",9,"¿Qué haré yo con este incendio\nque me abrasa el corazón?\nsilo publico, me pierde...\nsilo callo, ¿qué haré yo?",197,3,-1,-1,"",0,4,"o",-1,0,-1,0,43,43,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00392",9,"El amor crece con penas,\ncon penas se hace constante,\nquien no pena no es amante,\ny si es amante es apenas.",197,3,-1,-1,"",11,4,"ea",62,0,-1,0,43,43,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00393",9,"El que ha sido calavera\ny se trata de enmendar,\ndeja pasar unos días\ny vuelve a calaverear.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,44,44,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00394",9,"Lágrimas de las mujeres\nno conmueven ni enamoran,\nque ellas lloran cuando quieren\ny cuando no quieren lloran.",197,3,-1,-1,"",0,4,"oa",663,0,-1,0,44,44,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00395",9,"El tiempo y el desengaño\nson dos amigos que suelen\ndesengañar y engañar\ny despertar al que duerme.",197,3,-1,-1,"",0,4,"ee",-1,0,-1,0,44,44,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00396",9,"Lloraba y lloraba,\nlloraba y decía:\npara una paloma\n¡tanta cacería!",197,3,-1,-1,"",0,4,"ia",0,0,-1,0,44,44,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00397",9,"El amor tiene la culpa\nde que en lo limpio me pierda,\nporque llegan ocasiones\nque aunque uno fuera de piedra.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,44,44,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00398",9,"Lágrimas que no pudieron\ntánta dureza ablandar,\nque se vuelvan a la mar\nporque de la mar salieron.",197,3,-1,-1,"",11,4,"eo",105,0,-1,0,44,44,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00399",9,"¿En qué alto me parare\nque me dé el viento en el pecho?\n¿a quién le daré mis quejas\nque no me diga “bien hecho”?",197,3,-1,-1,"",0,4,"eo",60,0,-1,0,44,44,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00400",9,"Lloraba la triste viuda\nla muerte de su marido,\ny llorando preguntaba\nsi ya el otro había venido.",197,3,-1,-1,"",0,4,"io",101,0,-1,0,44,44,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00401",9,"Fuiste mi primer amor,\ntú me enseñaste a querer;\nno me enseñes a olvidar,\nque eso no quiero aprender",197,3,-1,-1,"",0,4,"e",20,0,-1,0,44,44,"","",0,"andina_t2","","",5,0,0,[],""],["isaacs_colombia-00402",9,"Las mujeres de este tiempo\nson como las alcachofas:\nbuscan y buscan el tronco,\ny todas se vuelven hojas.",197,3,-1,-1,"",0,4,"oa",-1,0,-1,0,44,44,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00403",9,"Hasta el alto fui detrás\npor ver si la divisaba;\nsólo la quimba topé\ndel indio que la llevaba.",197,3,-1,-1,"",0,4,"aa",28,0,-1,0,44,44,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00404",9,"La mujer que piensa mucho\nse levanta con el sol,\nporque nunca tiene sueño,\nni tranquilo el corazón.",197,3,-1,-1,"",0,4,"o",-1,0,-1,0,44,44,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00405",9,"Los dientes a los cuernos\nson parecidos,\nporque con ellos comen\nmuchos maridos.",197,3,-1,-1,"",6,4,"io",255,0,-1,0,45,45,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00406",9,"La vela en el candelero\nse contenta con arder;\nasí se contenta un hombre\ncon querer a una mujer.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,45,45,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00407",9,"Las mujeres de hoy en día\nson como las avellanas:\npartir una, partir dos,\npartir tres, y todas vanas.",197,3,-1,-1,"",0,4,"aa",263,0,-1,0,45,45,"","",0,"","","",7,0,0,[],""],["isaacs_colombia-00408",9,"La vela en el candelero\nse conforma con arder;\nasí mismo se arde un hombre\nen brazos de una mujer.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,45,45,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00409",9,"Las ranas en la laguna\ncuando viene el aguacero,\nunas piden la capuza\ny otras piden su sombrero.",197,3,-1,-1,"",0,4,"eo",38,0,-1,0,45,45,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00410",9,"Las estrellas en el cielo\ncaminan de das en dos;\nasí caminan mis ojos,\nchinita, detrás de vos.",197,3,-1,-1,"",0,4,"o",87,0,-1,0,45,45,"","",0,"","","",18,0,0,[],""],["isaacs_colombia-00411",9,"Lucero de la mañana,\npréstame tu claridad,\npara seguirle las huellas\na mi amante que se va.",197,3,-1,-1,"",0,4,"a",-1,0,-1,0,45,45,"","",0,"","","",22,0,0,[],""],["isaacs_colombia-00412",9,"Los hombres cuando pretenden\nnos prometen ser esclavos;\ny cuando ya son queridos,\nde esclavos se vuelven amos.",197,3,-1,-1,"",0,4,"ao",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00413",9,"Los ojos que desde lejos\nse aman y se quieren bien,\nno son ojos, sino espejos\ndonde dos almas se ven.",197,3,-1,-1,"",1,4,"e",242,0,-1,0,45,45,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00414",9,"Me hacen variar de colores,\ny mil tormentos me dan,\ncon sus rencores los unos\ny con su amor los demás.",197,3,-1,-1,"",0,4,"a",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00415",9,"La cabeza me duele\nde suplicarle\nque me des un remedio\npara olvidarte.",197,3,-1,-1,"",6,4,"ae",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00416",9,"Me quisiste, me olvidaste,\ny me volviste a querer\nzapato que yo desecho\nno me lo vuelvo a poner.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,45,45,"","",0,"palau_cantares, lafuente_madrid","","",8,0,0,[],""],["isaacs_colombia-00417",9,"Me quisiste, me olvidaste,\ny me volviste a querer,\ny me hallaste tan constante\ncomo la primera vez.",197,3,-1,-1,"",0,4,"e",-1,0,-1,0,46,46,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00418",9,"Mi amigo por ser mi amigo\nme enamora mi mujer;\nqué buen amigo que tengo,\npues me la ayuda a querer.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00419",9,"¡Más, ay! el que más congojas\ny más tormentos me dá,\nni rencor me tuvo nunca\nni amor me tuvo jamás.",197,3,-1,-1,"",0,4,"a",-1,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00420",9,"Mi vida, si así me quieres,\nno me subas tan arriba,\nque las hojas en el árbol\nno duran toda la vida.",197,3,-1,-1,"",0,4,"ia",-1,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00421",9,"¡Malditas sean las mujeres!\nel diablo se las llevara,\ncontento quedara yo\ncon veinte que me dejara.",197,3,-1,-1,"",0,4,"aa",57,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00422",9,"Me puse a lavar un negro\na ver qué color cogía;\nmientras más agua le echaba\nmás cenizo se ponía.",197,3,-1,-1,"",0,4,"ia",0,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00423",9,"Malpago se llama el perro,\ny Fortuna la perrita;\nCuando Malpago se muera\nqueda Fortuna solita.",197,3,-1,-1,"",0,4,"ia",50,0,-1,0,46,46,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00424",9,"Más vale querer a un perro\nque querer a una mujer;\nel perro es agradecido\ndonde le dan de comer.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,46,46,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00425",9,"Malhaya quien fuera perro\npara no saber sentir,\nque al perro como no siente\ntodo se le va en dormir.",197,3,-1,-1,"",0,4,"i",157,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00426",9,"Misas de cuerpo presente\nle cantan al cuerpo muerto,\ny a mí me las cantan vivo\nentre bobos anda el cuento.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00427",9,"Mi corazón se quema\nsin echar humo:\neso sí que es quemarse\ncon disimulo.",197,3,-1,-1,"",6,4,"uo",-1,0,-1,0,46,46,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00428",9,"Mujer que llega a prendarse\nde un hombre es cosa resuelta:\no se casa, o se hace monja,\no el demonio se la lleva.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00429",9,"Mi chata me dió un abrazo,\nsu mama la regañó:\nartificios de la vieja,\npues nada se le quitó.",197,3,-1,-1,"",0,4,"o",2,0,-1,0,47,47,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00430",9,"Me subí en un alto pino\npor ver si la divisaba;\ncomo el pino era tan tierno,\nde yerme llorar lloraba.",197,3,-1,-1,"",0,4,"aa",28,0,-1,0,47,47,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00431",9,"Mi mama tiene una perra;\ndice que la matará\npara hacer un tamborcito;\nlo que fuere sonara.",197,3,-1,-1,"",5,4,"aa",-1,0,-1,0,47,47,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00432",9,"Me entristece el corazón\nverte vestida de negro;\nque la sombra de tu pena\na mí me da sentimiento.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,47,47,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00433",9,"Mañana me voy de aquí,\ncomo todos lo verán;\ny a vuelta de mis espaldas\n¡sabe Dios lo que dirán!",197,3,-1,-1,"",0,4,"a",147,0,-1,0,47,47,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00434",9,"Mi señora, déme chicha\nen totuma Timaná;\nyo no lo hago por la chicha\nsino por lo que sabrá.",197,3,-1,-1,"",1,4,"a",9,0,-1,0,47,47,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00435",9,"Mi corazón a tus pies\nlo ves y no lo levantas:\n¡Ay, triste corazón mío,\ncuántos desprecios aguantas!",197,3,-1,-1,"",0,4,"aa",118,0,-1,0,47,47,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00436",9,"Márgara se está peinando\ny el aire se lleva el pelo;\n¡Ay, quién fuera golondrina\npara volar y cogerlo!",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,47,47,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00437",9,"Mi señora no me quiere,\nmi amo no me puede ver,\nmi señora la chiquita\ndice que me ha de vender.",197,3,-1,-1,"",0,4,"e",20,0,-1,0,47,47,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00438",9,"Nunca, mi bien, hallarás\nquien, como yo, por ti muera;\nhallarás quien ien te quiera,\nmás no quien te quiera más.",197,3,-1,-1,"",11,4,"a",51,0,-1,0,47,47,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00439",9,"Mis amores son del campo,\ny yo vivo en la ciudad;\namores que van y vienen\nno tienen seguridad.",197,3,-1,-1,"",0,4,"a",16,0,-1,0,47,47,"","",0,"","","",6,0,0,[],""],["isaacs_colombia-00440",9,"No sé qué estrella importuna\ninfluyó en mi nacimiento:\n¡tan alto mi pensamiento\ny tan baja mi fortuna!",197,3,-1,-1,"",11,4,"ua",56,0,-1,0,47,47,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00441",9,"No sé qué tiene mi chata\nque todos me la codician;\nhasta al cura se le antoja\ncomo si fuera primicia.",197,3,-1,-1,"",0,4,"ia",-1,0,-1,0,48,48,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00442",9,"Nace el hombre y en naciendo\nsólo a llorar se dedica,\ny con su llanto publica\nque ha de vivir padeciendo.",197,3,-1,-1,"",11,4,"eo",52,0,-1,0,48,48,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00443",9,"No quiero que me quieras\nni yo quererte:\nquiero que me aborrezcas\ny aborrecerte.",197,3,-1,-1,"",6,4,"ee",134,0,-1,0,48,48,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00444",9,"No quiero querer a nadie\nni que me quieran a mí,\nno quiero pasar trabajos\nni que los pasen por mi.",197,3,-1,-1,"",0,4,"i",-1,0,-1,0,48,48,"","",0,"","","",5,0,0,[],""],["isaacs_colombia-00445",9,"No me mires mal, paloma,\nporque tan alta te veas,\nque para torres más altas\nse fabrican escaleras.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,48,48,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00446",9,"Niña, cuando vas a misa\nla iglesia se resplandece,\nla yerba seca que pisas\nal momento reverdece.",197,3,-1,-1,"",0,4,"ee",64,0,-1,0,48,48,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00447",9,"No quiero que te vayas,\nni que te quedes,\nni que me dejes sola,\nni que me lleves.",197,3,-1,-1,"",6,4,"ee",-1,0,-1,0,48,48,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00448",9,"No te fies de las mujeres\naunque te lo estén diciendo,\nque con una mano tejen\ny con otra están urdiendo.",197,3,-1,-1,"",0,4,"eo",52,0,-1,0,48,48,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00449",9,"No me mates con cuchillo\nporque el hierro es enconoso,\nmátame con un suspiro\nde tu pecho candoroso.",197,3,-1,-1,"",0,4,"oo",160,0,-1,0,48,48,"","",0,"","","",7,0,0,[],""],["isaacs_colombia-00450",9,"No te fies de los hombres\naunque digan bien te quiero,\nque en volteando las espaldas,\nsi te vide no me acuerdo.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,48,48,"","",0,"","","",16,0,0,[],""],["isaacs_colombia-00451",9,"No hay corazón como el mío\nque sufre y calla su pena:\ncorazón que sufre y calla\nno se encuentra donde quiera.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,48,48,"","",0,"andina_t1","","",9,0,0,[],""],["isaacs_colombia-00452",9,"Ojos míos desdichados,\nllorar por lo que os disgusta,\nque llorar por cosa justa\nes de los ojos honrados.",197,3,-1,-1,"",11,4,"ao",18,0,-1,0,48,48,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00453",9,"Ojos azules me gustan\ny los negros me enamoran;\npero los verdes, comadre,\n¡ay! los verdes me encocoran.",197,3,-1,-1,"",0,4,"oa",663,0,-1,0,49,49,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00454",9,"Por aquí va el caminito\npor donde mi amor pasó;\nse la llevaron de noche\nporque no la viera yo.",197,3,-1,-1,"",0,4,"o",2,0,-1,0,49,49,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00455",9,"Pasaré mis tristes días\nllorando indecibles penas,\nglorias envidiando ajenas\ndesdichas llorando mías.",197,3,-1,-1,"",11,4,"ia",214,0,-1,0,49,49,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00456",9,"Para qué son cerrojos\nen los portones\nsi han de quedar abiertos\nlos corazones.",197,3,-1,-1,"",6,4,"oe",34,0,-1,0,49,49,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00457",9,"Para llevar mis desgracias\nal cielo pido un favor:\nque disminuya tus gracias\no ensanche mi corazón.",197,3,-1,-1,"",0,4,"o",-1,0,-1,0,49,49,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00459",9,"Quise sin saber a quién\ny sin tener experiencia,\nporque la pedrada viene\nde aquí que uno menos piensa.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,49,49,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00460",9,"Pájaro que vas volando\ny en el pico llevas flores,\nen las alas clavellinas\ny en el corazón dolores.",197,3,-1,-1,"",0,4,"oe",5,0,-1,0,49,49,"","",0,"","","",6,0,0,[],""],["isaacs_colombia-00461",9,"¿Qué haremos, vidita mía,\nque nos quieren separar?\n¡como si la ausencia fuera\nremedio para olvidar!",197,3,-1,-1,"",0,4,"a",21,0,-1,0,49,49,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00462",9,"Para carate en Antioquia,\npara niguas en la Villa,\npara muchachas bonitas\nRionegro y la Marinilla.",197,3,-1,-1,"",0,4,"ia",-1,0,-1,0,49,49,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00463",9,"¿Qué haremos, trigueña mía,\ncon tanto que nos queremos?\nel remedio está en la mano,\nen San Juan nos casaremos\n(mi vida, nos casaremos)",197,3,-1,-1,"",7,5,"eo",-1,0,-1,0,49,49,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00464",9,"Parado en una esquina\nlloviendo estaba;\naunque estaba lloviendo\nno me mojaba.",197,3,-1,-1,"",6,4,"aa",28,0,-1,0,49,49,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00465",9,"¿Qué esperanza llevará\naquel que ya va perdida?\nsin saber par dónde va,\nsin saber par dónde vino\n(ni par donde es el camino)",197,3,-1,-1,"",7,5,"io",-1,0,-1,0,50,50,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00466",9,"Si yo fuera pajarito\na tus hombros diera un vuelo\npara decirte al oído:\notorgo, recibo y quiero.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,50,50,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00467",9,"Si porque te quiero quieres\nque yo la muerte reciba\nmuere tú, que yo no quiero\nmorir para que otro viva.",197,3,-1,-1,"",0,4,"ia",53,0,-1,0,50,50,"","",0,"","","",10,0,0,[],""],["isaacs_colombia-00468",9,"Subo la cuesta cargado\ncan mi carga de tinajas,\nla barriga hecha un yesquero\ny amor que me vuelvo rajas!",197,3,-1,-1,"",0,4,"aa",661,0,-1,0,50,50,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00469",9,"Si tu marido es celoso\néchale un hueso en el plato,\nque mientras lo esté royendo\nconversaremos un rato.",197,3,-1,-1,"",0,4,"ao",19,0,-1,0,50,50,"","",0,"","","",7,0,0,[],""],["isaacs_colombia-00470",9,"Si piensas que por tu pique\nme he de poner a florar,\nyo no sé quitar enojos\ny así te puedes quedar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,50,50,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00471",9,"Si yo supiera de cierto\nque no me habías de olvidar\nme retirara unos días\nmientras dejaban de hablar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,50,50,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00472",9,"Si piensas que par tu enojo\nme derrito como cera,\nya soy de tal calidad\nque el mismo fuego me hiela.",197,3,-1,-1,"",0,4,"ea",-1,0,-1,0,50,50,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00473",9,"Sospechas tengo de tí,\nporque amante muy rendido,\nsegún se me pone a mí\nno debe ser buen marido.",197,3,-1,-1,"",1,4,"io",101,0,-1,0,50,50,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00474",9,"Si el cielo se rompiera,\nsegún yo entiendo,\nesa tu linda cara\nsería el remiendo.",197,3,-1,-1,"",6,4,"eo",52,0,-1,0,50,50,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00475",9,"Si tu hermosura indiscreta\na mi inocencia provoca,\nte he de dar con esta jeta\nun porrazo en esa boca.",197,3,-1,-1,"",1,4,"oa",178,0,-1,0,50,50,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00476",9,"Si yo fuera pajarito\nno me ocupara en volar,\nme sentara en los caminos\nsólo por verte pasar.",197,3,-1,-1,"",0,4,"a",21,0,-1,0,50,50,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00477",9,"Tus ojos son dos estrellas\ntus labios son un coral,\ntus dientes son perlas finas\nsacados del hondo mar.",197,3,-1,-1,"",0,4,"a",-1,0,-1,0,51,51,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00478",9,"Tú negalo siempre, Elena,\nporque en percances de amor,\nantes el código ordena\nser mártir que confesor.",197,3,-1,-1,"",1,4,"o",72,0,-1,0,51,51,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00479",9,"Toda la noche me estuve\nparadito en una estaca\ny no fuites pa decirme\nlorito, dáca la pata.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,51,51,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00480",9,"Te quise y tu no quisiste,\nhoy no te quiero y tú quieres,\n¡qué caprichosas que son\npor lo común las mujeres!",197,3,-1,-1,"",0,4,"ee",55,0,-1,0,51,51,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00481",9,"Te quiero como a mis ojos,\ncomo a mis ojos te quiero,\npero más quiero a mis ojos\nporque mis ojos te vieron.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,51,51,"","",0,"","","",4,0,0,[],""],["isaacs_colombia-00482",9,"Tengo y no tengo esperanza,\nespero y me desespero:\ntengo todo cuanto quiero,\npero tengo desconfianza.",197,3,-1,-1,"",11,4,"aa",163,0,-1,0,51,51,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00483",9,"Tienes unos ojitos\ny unas pestañitas...\ny una boca embustera\ncon que me engañas.",197,3,-1,-1,"",3,4,"aa",-1,0,-1,0,51,51,"","",0,"","","",16,0,0,[],""],["isaacs_colombia-00484",9,"Todas las mañanitas\ndel mes de enero\nme amanecen las uñas\nsobre los dedos.",197,3,-1,-1,"",6,4,"eo",-1,0,-1,0,51,51,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00485",9,"Te vas, luz del día,\nte vas y me dejas,\ny no oyes las quejas\nde la pena mía.",197,3,-1,-1,"",11,4,"ia",0,0,-1,0,51,51,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00486",9,"Tengo una cosa en el alma\nque decírtela no puedo,\ntengo celos, tengo amor,\nvalor tengo y tengo miedo.",197,3,-1,-1,"",0,4,"eo",304,0,-1,0,51,51,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00487",9,"Tienes unos ojos\nlindos en extremo\ny los ojos míos\nson sus prisioneros.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,51,51,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00488",9,"Tu mujer es muy bonita\npero no como la mía,\nque parece levadura\ndesatada en agua fría.",197,3,-1,-1,"",0,4,"ia",0,0,-1,0,51,51,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00489",9,"Te dió la tierra caliente\nel garbo y los ojos negros,\nte dió color la sabana\ny hermosura te dió el cielo.",197,3,-1,-1,"",0,4,"eo",-1,0,-1,0,52,52,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00490",9,"Una tengo y dos envido,\ncon un siete espero un as;\nun amor he conocido\ny debe haber muchos más.",197,3,-1,-1,"",1,4,"a",51,0,-1,0,52,52,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00491",9,"Usted dice que me quiso,\nsi así fue yo no lo supe;\nvuélvame a querer de nuevo,\nme hace el bien, y más se suple.",197,3,-1,-1,"",0,4,"ue",-1,0,-1,0,52,52,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00492",9,"Una, dos, tres, cuatro, cinco...\n¡cuántas y yo sin ninguna!\nseñora, déme a su hija\nque Dios da ciento por una.",197,3,-1,-1,"",0,4,"ua",56,0,-1,0,52,52,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00493",9,"Una palomita\na quien yo adoré,\nhizo aquí su nido,\nlo olvidó y se fue.",197,3,-1,-1,"",0,4,"e",77,0,-1,0,52,52,"","",0,"","","",3,0,0,[],""],["isaacs_colombia-00494",9,"Una mora me enamora\nporque es mora de nación\ny es muy mora porque mora\ndentro de mi corazón.",197,3,-1,-1,"",1,4,"o",31,0,-1,0,52,52,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00495",9,"Una señorita blanca\nme dijo que la besara,\nyo le dije —Sí señora,\ncon esa ganita estaba.",197,3,-1,-1,"",0,4,"aa",-1,0,-1,0,52,52,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00496",9,"Un rosal cría una rosa\ny una maceta un clavel,\ny una madre cría su hija\nsin saber para quién es.",197,3,-1,-1,"",0,4,"e",-1,0,-1,0,52,52,"","",0,"","","",8,0,0,[],""],["isaacs_colombia-00497",9,"Un clavel fue la causa\npara quererte,\nque los mismos claveles\nson alcahuetes.",197,3,-1,-1,"",6,4,"ee",-1,0,-1,0,52,52,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00498",9,"Una camisa sin mangas\nsin cuello ni delantera,\nno necesita jabón\nni tampoco lavandera.",197,3,-1,-1,"",0,4,"ea",44,0,-1,0,52,52,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00499",9,"Una negra me dió un beso,\n¡nunca me lo hubiera dado!\npues los besos de las negras\nsaben a cacho quemado.",197,3,-1,-1,"",0,4,"ao",14,0,-1,0,52,52,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00500",9,"Un pájaro me ofreció\nlas plumas de su copete;\nno hay pájaro en ésta vida\nque cumpla lo que promete.",197,3,-1,-1,"",0,4,"ee",285,0,-1,0,52,52,"","",0,"antioquia_animales","","",2,0,0,[],""],["isaacs_colombia-00501",9,"Vida de los amantes,\nvida penosa;\nvida desesperada\npero sabrosa.",197,3,-1,-1,"",6,4,"oa",63,0,-1,0,53,53,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00502",9,"Ya llega la noche triste\npara mí que estoy penando:\nduerma bien quien tiene sueño\nque yo velaré llorando.",197,3,-1,-1,"",0,4,"ao",33,0,-1,0,53,53,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00503",9,"Yo soy como aquellas piedras\nque se encuentran en la calle;\ntodos tropiezan con ellas y ellas\nno tocan con nadie.",197,3,-1,-1,"",3,4,"ae",-1,0,-1,0,53,53,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00504",9,"Me estoy muriendo de amor\ny el remedio es olvidar:\nsi he de vivir del remedio\nprefiero morir del mal.",197,3,-1,-1,"",0,4,"a",-1,0,-1,0,53,53,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00505",9,"Yo te miré persignar,\nmis ojos fueron testigos,\nquién te pudiera besar\ndonde dices enemigos.",197,3,-1,-1,"",1,4,"io",648,0,-1,0,53,53,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00506",9,"Yo te dí mi medio real\nporque me hicieras cariños:\nme diste sólo un besito,\nme estás debiendo un cuartillo.",197,3,-1,-1,"",0,4,"io",-1,0,-1,0,53,53,"","",0,"","","",2,0,0,[],""],["isaacs_colombia-00507",9,"A tu casa no entro\nporque la gente,\npor una vez que vaya,\ndicen que siempre.",197,3,-1,-1,"",6,4,"ee",-1,0,-1,0,53,53,"","",0,"","","",1,0,0,[],""],["isaacs_colombia-00508",9,"Yo tuve cinco chaticas\nojinegras y una zarca,\ny me quedé sin ninguna\ncomo aquel que mucho abarca.",197,3,-1,-1,"",0,4,"aa",395,0,-1,0,53,53,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00003",10,"En la plenitud de la Pampa\nel viento de la noche trajo a\nnuestros oídos el eco de un canto,\ndoliente como el postrer lamento\nde una vida que se extingue.",198,4,-1,-1,"",7,5,"ie",-1,0,-1,0,7,7,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00009",10,"Cuando ensillo mi caballo\ny me fajo mi machete\nno envidio la suerte a tiaide\nni aun al mismo Presidente.",198,4,-1,-1,"",0,4,"ee",-1,0,-1,0,12,12,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00010",10,"Anoche soñaba yo\nun sueñito de alegría,\nque tu boquita besaba\ny en tus brazos me dormía.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,13,13,"","",0,"","","",9,0,0,[],""],["machado_venezuela-00010-e2",10,"En castigo de sus culpas\nanda por esas sabanas,\ncon los cabellos ardiendo\ny doblando una campana.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,13,13,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00011",10,"Una pena y otra pena\nson dos penas para mí;\nayer penaba por verte;\nhoy peno porque te vi.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,14,14,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00012",10,"¡Señores! Tengan presente\nque por dones especiales\nen el campo tengo flores\ny en mi cabeza, cantares.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,15,15,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00012-e2",10,"Yo soy Cantaor de fama\nSin conoce el dicionario;\nentre la gente e mi tierra\nhago de cura y vicario.",198,4,-1,-1,"",0,4,"ao",25,0,-1,0,15,15,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00013",10,"Cuando una mujer resbala\naunque no caiga, se pierde,\nporque nunca falta alguno\nque del resbalón se acuerde.",198,4,-1,-1,"",0,4,"ee",154,0,-1,0,15,15,"","",0,"andina_t1","","",2,0,0,[],""],["machado_venezuela-00014r1",10,"Hasta los palos del monte\ntienen su separación:\nunos sirven para santos,\ny otros para hacer carbón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,17,17,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00014",10,"La mujer que tuvo amores\nno sirve para casada,\npues de la gloria pasada\nle quedan los borradores.",198,4,-1,-1,"",11,4,"oe",5,0,-1,0,16,16,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00014-e2",10,"Las penas que me maltratan\nson tantas que se atrepellan,\nunas con otras se amellan\ny por eso no me matan.",198,4,-1,-1,"",11,4,"aa",399,0,-1,0,16,16,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00014-e3",10,"El que nació para pobre\ny su sino es niguatero,\naunque le saquen la nigua\nsiempre le queda el anjero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,16,16,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00015a",10,"— Por ser la primera vez\nque yo en esta casa canto\ngloria al Padre, gloria al Hijo\ngloria al Espíritu Santo.",198,4,-1,-1,"",0,4,"ao",30,0,-1,0,18,18,"","",0,"frenk_t3, andina_t1","","",8,0,0,[],""],["machado_venezuela-00015b",10,"— Por ser la primera vez\nque yo en esta casa canto\nme hago en la frente la cruz\npara librarme de espanto.",198,4,-1,-1,"",0,4,"ao",30,0,-1,0,18,18,"","",0,"","","",8,0,0,[],""],["machado_venezuela-00017a",10,"— Si quieres cantar conmigo\ncontéstame en un segundo:\n¿Qué poder es el más grande\ndespués de Dios, en el mundo?",198,4,-1,-1,"",0,4,"uo",179,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00017b",10,"— Después de Dios, en el mundo,\nel poder del confesor\ncuando levanta la mano\ny bendice al pecador.",198,4,-1,-1,"",0,4,"o",72,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00017c",10,"— Ques muy grande tu saber\npor lo que me has dicho, infiero;\nmas, deseo que me digas:\n¿Cuántos pelos tiene un cuero?",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,18,18,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00018",10,"— Ay, Jesús, María y José,\nque me has dejado confuso,\nlos pelos que tiene un cuero\nfueron los que Dios le puso.",198,4,-1,-1,"",3,4,"uo",438,0,-1,0,19,19,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00019",10,"Nosotros semos tuyeros\nde Yare y Santa Lucía,\ncantamos a todas horas\nde noche como de día.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,19,19,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00020",10,"No le negamos el vicio\na los músicos llaneros:\nen el Tuy toos semos negros,\npero semos caballeros.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,20,20,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00024",10,"No escupas nunca pa arriba,\nques una verdad muy clara\nque el que para arriba escupe\nluego le cae en la cara.",198,4,-1,-1,"",0,4,"aa",57,0,-1,0,23,23,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00027",10,"Por ser la primera vez\nque yo en esta casa canto\nme hago la cruz en la frente\npara librarme de espanto.",198,4,-1,-1,"",0,4,"ao",30,0,-1,0,29,29,"","",0,"","","",8,0,0,[],""],["machado_venezuela-00028",10,"Ayúdame guitarrita\nayúdame cuatro cuerdas,\nque quiero cantar ahora\npara recordar mi tierra.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,29,29,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00029",10,"Guitarrita, guitarrita,\ntienes boca para hablar\nlos ojos no más te faltan\npara conmigo llorar,",198,4,-1,-1,"",0,4,"a",21,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00030",10,"¿Pides un canto, querida?\npide más un gemido:\nlos pesares son el nido\ndonde mi alma se reclina.",198,4,-1,-1,"",5,4,"ia",-1,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00031",10,"Los pajarillos y yo\nnos levantamos a un tiempo:\nellos a cantar sus dichas,\nyo a llorar mis sentimientos.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,30,30,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00032",10,"Triste canta la paloma,\nmás triste canta el paují;\ntriste está mi corazón\nde tanto pensar en ti.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00033",10,"Las arenitas del río\ncorren debajo del agua;\ndebajo de mis cantares\ncorren las penas de mi alma.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,30,30,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00034",10,"Yo canto porque cantando\ndivierto los males míos;\ncuando estoy a solas lloro,\ny en conversación me río.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,31,31,"","",0,"carrizo_salta","","",2,0,0,[],""],["machado_venezuela-00035",10,"Si supiera que cantando\nmis penas se distraían\ncantando me la pasara\ntoda la noche y el día.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,31,31,"","",0,"","","",10,0,0,[],""],["machado_venezuela-00036",10,"El que me oyere cantando\ndirá: ¡qué alegre está aquél!\npero tengo el corazón\nmás amargo que la hiel.",198,4,-1,-1,"",0,4,"e",32,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00037",10,"Yo no canto porque me oigan,\nni porque mi voz es buena:\nyo canto porque no caiga\nla culpa sobre la pena.",198,4,-1,-1,"",0,4,"ea",59,0,-1,0,31,31,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00038",10,"Cuando más trabajos tengo\ncanto con más alegría,\nporque los mismos trabajos\nme sirven de compañía.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,31,31,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00039",10,"Cuando llego a una parranda\ndonde hay muchachas bonitas,\nyo canto con mucha gana\nporque divierto la vista.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00040",10,"Yo le canto al señorío\npa que me preste atención,\nel hijo e ño Zacarías\nse llama Presentación.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00041",10,"Si me dan licencia canto\ny si no me estoy callao,\nconsiderando que me hallo\nde mi libertad privao.",198,4,-1,-1,"",1,4,"ao",-1,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00042",10,"Ahora sí voy a cantar\ncon muchísima alegría,\nporque ya salió a bailar\nla prenda que yo quería.",198,4,-1,-1,"",1,4,"ia",0,0,-1,0,32,32,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00043",10,"Voy a suspender mi voz\nsi me ayuda la garganta,\nporque digan las mujeres:\n¿Cuál moreno es el que canta?",198,4,-1,-1,"",0,4,"aa",148,0,-1,0,32,32,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00044",10,"A mí mismo me da miedo\ncuando levanto el tañío,\nporque me hallo facultoso\ny dueño de mi albedrío.",198,4,-1,-1,"",0,4,"io",3,0,-1,0,33,33,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00045",10,"Cuando revienta mi voz\ncomo que sale del alma,\nse escucha a cuarenta leguas\nestando la noche en calma.",198,4,-1,-1,"",0,4,"aa",125,0,-1,0,33,33,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00046",10,"Cuando tengo el pecho claro\nhago lo que me da gana:\nde mi garganta una torre;\nde mi lengua una campana.",198,4,-1,-1,"",0,4,"aa",4,0,-1,0,33,33,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00047",10,"Yo no sé si estoy errao\no la música me farta,\nporque estoy hecho a cantar\na són de bandola y arpa.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,33,33,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00048",10,"Arrímese al instrumento\nsi gusta de que le cante:\nno me haga perder el tiempo\nque ahora soy comerciante.",198,4,-1,-1,"",0,4,"ae",47,0,-1,0,33,33,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00049",10,"Desde el llano abajo vengo\nen mi caballo melao,\natropellando cantores\ncomo atropellá ganao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,34,34,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00050",10,"Yo no digo que no habrá\ncantaores en el llano\nque canten más arreglao;\npero más sabroso ¿cuándo?",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00051",10,"Yo me la paso cantando\nde Cuchivero a Caicara.\nPecho ¿Por qué estás tan ronco?\nLengua ¿Por qué no declaras?",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00052a",10,"No puedo cantar de ronco\npues la voz se me acabó\ndesde que me echaron daño\nlas indias de Boconó.",198,4,-1,-1,"",0,4,"o",2,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00052b",10,"Yo no canto en los fandangos\nporque mi zamba no quiere:\nporque dice que cantando\nenamoro las mujeres.",198,4,-1,-1,"",0,4,"ee",-1,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00053",10,"Cante, cante, compañero,\nno le tenga miedo a naide\nque en la copa del sombrero\ncargo la Virgen del Carmen.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00054",10,"Si la gracia me ayudara\ncomo me ayuda el deseo\nmás sabroso le cantara:\npero sin gracia, no puedo.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,35,35,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00055",10,"Esto dicen, esto dicen,\nesto dicen los llaneros:\nel que no sabe cantar\nno sirve pa cabrestero.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,35,35,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00056",10,"Yo me atrevo a estar cantando\ntoda la semana entera,\nsi se me calienta el tarro\ny se me abre la mollera.",198,4,-1,-1,"",0,4,"ea",44,0,-1,0,36,36,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00057",10,"Aquí me estaré cantando,\ncantando hasta amanecer,\npara que las hojas secas\nvuelvan a reverdecer.",198,4,-1,-1,"",0,4,"e",20,0,-1,0,36,36,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00058",10,"Para obsequiar mis amores\ntengo cosas especiales:\nen el campo muchas flores;\nen mi cabeza, cantares.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,36,36,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00059",10,"Algunos para cantar\ntienen su medio salero;\npero yo para cantar\ntengo mi salero entero.",198,4,-1,-1,"",1,4,"eo",38,0,-1,0,36,36,"","",0,"andina_t1","","",2,0,0,[],""],["machado_venezuela-00060",10,"A la una, más o menos,\ncanta el gallo e la pasión;\na estas horas se levanta\nel que tiene ocupación.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,37,37,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00061",10,"Si porque canto me arrestan\nme la pasaré llorando;\n¿cómo no arrestan los gallos\nque se la pasan cantando?",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,37,37,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00062",10,"El que un cantaor se pele\nno debe ser tan notao;\nse pelan todos los hombres\npor más que hayan estudiao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,37,37,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00063",10,"El cantar a quien no entiende\nes majar en hierro frío,\necharle ayudas a un muerto\ny levantar un tullío.",198,4,-1,-1,"",0,4,"io",3,0,-1,0,37,37,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00064",10,"Oiga, compadre Roberto,\nponga su guitarra al sol\npara decirle unas cosas\npropias para un sí bemol.",198,4,-1,-1,"",0,4,"o",24,0,-1,0,37,37,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00065",10,"Cuando la guitarra gime\nal compás de los capachos,\nes claro que en el hogar\nno perecen mis muchachos.",198,4,-1,-1,"",0,4,"ao",463,0,-1,0,38,38,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00066",10,"Yo tengo una guitarrita\nque la llaman quita-quita,\nporque quita los pesares\na las muchachas bonitas.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,38,38,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00067",10,"Tóqueme, compadre, el arpa,\ndémele el quinto registro,\nque soy como un aspirante\ncuando visita a un Menistro.",198,4,-1,-1,"",0,4,"io",664,0,-1,0,38,38,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00068",10,"Dale duro a esa bandola\nque se acabe de quebrar,\nque palos hay en el monte\ny quien los sepa labrar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,38,38,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00069a",10,"El oficio de maraquero\nes oficio condenao;\npara todos hay asiento\ny el maraquero parao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,39,39,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00069b",10,"Con mi maraca (6) en la mano\naquí estoy dando candela;\ny le hago tragar el medio\ncon trapo y todo a cualquiera.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,39,39,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00070a",10,"Con el permiso de ustedes\nseñoras y caballeros,\nde mi guitarra a los sones\nvoy a sacar unos versos.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,40,40,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00070b",10,"Al son de mi guitarrita\nvoy a sacar unos versos,\npara que sepan las niñas\ncómo cantan los llaneros.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00071a",10,"Para que sepan las niñas\ncómo cantan los llaneros,\nque por doquiera que pasan\ndejan los buenos recuerdos.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00071b",10,"Mi zamba no necesita\nque le regalen espejo;\ncuando se mira en mis ojos\nme dice: ya tengo sueño.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00071c",10,"Una vez le regalé\nun camisón, de recuerdo,\nunas argollas de plata,\nuna pava y un pañuelo.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,40,40,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00072",10,"Entonces ella me dió\nun mechoncito de pelo,\ny una pluma de garza\nque uso siempre en el sombrero.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,41,41,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00073",10,"Cuando salgo queda triste,\ntriste, pensando en su negro;\ny alegre como las pascuas\nla jallo, cuando regreso.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,41,41,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00074",10,"Tengo una vaquita mansa\nla vaca más buena moza;\ncon el fondo de canela\ny manchas de mariposa.",198,4,-1,-1,"",0,4,"oa",63,0,-1,0,41,41,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00075",10,"Yo la tengo destinada\npara regalo a mi novia\ncon cuatro bonitos mautes\ny dos o tres novillonas.",198,4,-1,-1,"",0,4,"oa",-1,0,-1,0,41,42,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00078",10,"Cuando las mujeres quieren\nnadie las puede atajar;\ncomo se ataja el caballo\ncon el freno y el bozal.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,42,42,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00079",10,"— ¿Quién es ese cantaor\nque canta en ese rincón,\nque sólo el rejo le falta\npara ser caballo andón?",198,4,-1,-1,"",0,4,"o",31,0,-1,0,43,43,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00080",10,"— El que cantare conmigo\nese sí que es grande empeño,\nporque tengo más colmillo\nque un caimán viejo, apureño.",198,4,-1,-1,"",0,4,"eo",138,0,-1,0,43,43,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00081",10,"— El que cantare conmigo\napriétese los calzones,\nno piense que va a comer\narepa con chicharrones.",198,4,-1,-1,"",0,4,"oe",34,0,-1,0,43,43,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00082",10,"— Yo no soy de por aquí\nque yo soy de Zorrocloco,\nel que cantare conmigo\nsi no muere, queda loco.",198,4,-1,-1,"",0,4,"oo",152,0,-1,0,44,44,"","",0,"","","",11,0,0,[],""],["machado_venezuela-00083",10,"— Yo no soy de por aquí\nyo soy de Barquisimeto,\nnaide se meta conmigo\nque yo con naide me meto.",198,4,-1,-1,"",0,4,"eo",543,0,-1,0,44,44,"","",0,"","","",11,0,0,[],""],["machado_venezuela-00084",10,"— Tú que la echas de cantor\ndí, si puedes contestar:\n¿Con cuántas pipas de miel\nse endulsa el agua del mar?",198,4,-1,-1,"",0,4,"a",21,0,-1,0,44,44,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00085",10,"— El Polo se anda álabando\nde que no hay otro mejor que'l\nresponde la caña dulce\n¿de dónde saca la miel?",198,4,-1,-1,"",0,4,"e",32,0,-1,0,44,44,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00086",10,"— Yo soy cantador de fama\nsin conocé el diccionario;\nentre la gente e mi tierra\nhago de Cura y Vicario.",198,4,-1,-1,"",0,4,"ao",25,0,-1,0,44,44,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00087",10,"El que me enseñó a cantar\nme enseñó lo que sabía,\ny me dijo: vete al mundo\na lucí la ciencia mía.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,45,45,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00088",10,"Yo canto, pero no digo\nel que me enseñó a cantar,\nni a manejar un machete,\nuna lanza y un puñal.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00089",10,"—Yo salí de San Felipe\na las ocho e la mañana,\ny me la pasé cantando\nentre Cocorote y Guama.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00090",10,"En San Pablo no canté\nporque lo encontré quemao:\nhasta el Cura bebe caldo\ncuando estoy emparrandao.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00092",10,"Cantar bien o cantar mal\npuede ser indiferente;\npero estando entre la gente\ncantar bien o no cantar.",198,4,-1,-1,"",5,4,"a",-1,0,-1,0,45,45,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00093",10,"Despiértese, compañero,\ndespierte, si está dormío,\nmire que voy a cantar\nel galerón de corrío.",198,4,-1,-1,"",0,4,"io",3,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00094",10,"Señores, tengan presente,\nlo arvierto sin condición,\nque ha de ser inteligente\nel que me haga oposición.",198,4,-1,-1,"",1,4,"o",31,0,-1,0,46,46,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00095",10,"— Supongo que sea un portento\nel cantaor que ha cantao,\ny por si acaso le arvierto\nque aquí me tiene a su lao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00096",10,"—Te llaman gallo de espuela,\nmas, tu pluma no respeto,\nque he mandado yo a la escuela\na gallos de más talento.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00097",10,"— He mandado yo a la escuela\na verdaderos cantores:\nqué no haré con este intruso:\n¿díganme ustedes, señores?",198,4,-1,-1,"",0,4,"oe",5,0,-1,0,46,46,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00098",10,"— Díganme ustedes, señores,\nsi no merece desprecio\nquien funda sus pretenciones\nsólo en palabras de necio.",198,4,-1,-1,"",0,4,"eo",276,0,-1,0,47,47,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00099",10,"— Sólo en palabras de necio\nno fundes tu fama, digo:\nelija un tema de cencia\nsi quieres cantar conmigo.",198,4,-1,-1,"",0,4,"io",106,0,-1,0,47,47,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00104",10,"Cuando yo voy a Caracas\ncargo mi carpeta lista\npara librarme del cacho\nde tanto blanco sablista.",198,4,-1,-1,"",0,4,"ia",352,0,-1,0,49,49,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00105",10,"Todo el que fuere a Caracas\ndebe tener mucha vista,\nque allá cantan los sablistas\nsin bandola ni maracas.",198,4,-1,-1,"",5,4,"aa",665,0,-1,0,49,49,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00106",10,"El que se quiera salvar\npóngase un escapulario,\nporque le llega un plumario\nqueriéndolo retratar.",198,4,-1,-1,"",11,4,"a",21,0,-1,0,49,49,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00107",10,"Si fueres al Puente e Jierro\ndirásmele a Nicanor\nque me devuelva los riales\nque allá me bebí en licor.",198,4,-1,-1,"",0,4,"o",72,0,-1,0,50,50,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00108",10,"El Paradero, en el llano\nes donde baja el ganao:\na la Ceiba e San Francisco\nva mucho blanco avispao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,50,50,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00108r1",10,"Cuando yo voy a Caracas\nme buscan los zapateros\npa que le enseñe las cantas\ncon que enamoro en mi pueblo.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,50,50,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00109",10,"Todos saben que soy feo\ny bruto como una yegua:\npero tengo más diñero\nque el Banco de Venezuela",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,51,51,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00109-e2",10,"En Caracas está venteando,\ny en Chaguaramas lloviendo;\ndicen que el mundo se acaba\npa los que se van muriendo.",198,4,-1,-1,"",3,4,"eo",52,0,-1,0,51,51,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00110",10,"Yo estuve bebiendo amargo\nuna vez que fuí a Caracas\ncuando regresé a mi casa\nllegué arrastrando las patas.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,51,51,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00111",10,"En Caracas tengo tienda\ny en Valencia pulpería,\nyo no le quito a mi zamba\nque converse ni se ría.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,51,51,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00112",10,"En Caracas tengo tienda\ny en Valencia pulpería;\nJosefita es la que vende,\nIsabel es la que fía. \"",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,52,52,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00112-e2",10,"En el camino e Caracas\nmataron un pavorreal,\ny del buche le sacaron\nla bandera federal.",198,4,-1,-1,"",0,4,"a",1,0,-1,0,52,52,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00113",10,"Aquí te tengo un pañuelo\nque te traje de Valencia\npara secarte las lágrimas\nque derramaste en mi ausencia.",198,4,-1,-1,"",0,4,"ea",46,0,-1,0,52,52,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00114",10,"Me puse a torear un toro\npara demostrar mi brío,\nla fiera se hallaba en Coro\ny yo en Valencia escondió.",198,4,-1,-1,"",5,4,"o",-1,0,-1,0,52,52,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00115",10,"Las muchachas en La Villa\nme llaman lanza en lo oscuro,\nporque cuando estoy cantando\nle aflojo la mano al pulso.",198,4,-1,-1,"",0,4,"uo",-1,0,-1,0,53,53,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00116",10,"En Camaguán me conocen\npor mi fama de arrestao,\ny se dicen las muchachas:\nahí viene el mismo pecao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,53,53,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00117",10,"Me gusta Puerto Cabello\npor pasear la Calle Real,\ny ver a los marineros\ndando tumbos en el mar.",198,4,-1,-1,"",3,4,"a",-1,0,-1,0,53,53,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00118",10,"De Puerto Cabello vengo\nde pagar una novena....\nahora que estamos solitos\néchame el brazo, morena.",198,4,-1,-1,"",0,4,"ea",59,0,-1,0,53,53,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00120a",10,"Del Puerto me fuí a La Guaira,\nde La Guaira vine aquí:\nquién sabe si volveré\na la tierra en que nací.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,54,54,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00120b",10,"San Felipe es buena tierra\npero no para vivir;\nPuerto Cabello y Valencia\npara dentrar y salir.",198,4,-1,-1,"",0,4,"i",157,0,-1,0,54,54,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00120c",10,"Curarigua es un desierto,\nCarora es un campo-santo,\nBarquisimito no tanto,\nporque salgo y me divierto.",198,4,-1,-1,"",11,4,"eo",88,0,-1,0,54,54,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00120d",10,"De aquí al pueblo hay media legua,\nde aquí al Tocuyo hay un día.\nadonde llaman Soy tuya\nmás distancia todavía.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,54,54,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00120e",10,"Yo no soy de por aquí\nque yo vengo de Trujillo;\nzamuro no cae en trampa\nni come maiz amarillo.",198,4,-1,-1,"",0,4,"io",228,0,-1,0,54,54,"","",0,"","","",11,0,0,[],""],["machado_venezuela-00121",10,"A mí me llaman pagüeño,\npero yo no soy del Pao;\ntengo la fe de bautismo,\npero no soy bautizao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,55,55,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00122",10,"Yo no adivino de aquí\nlo que está pasando en Cagua;\ntampoco sabe ninguno\ncuando es que el pez bebe el agua.",198,4,-1,-1,"",0,4,"aa",383,0,-1,0,55,55,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00123",10,"Cuando voy a San Fernando\nme dice Petra Quiñones:\nsi este moreno se muere\nse acaban las diversiones.",198,4,-1,-1,"",0,4,"oe",34,0,-1,0,55,55,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00124",10,"Yo fuera muy bien cuidao\nsi estuviera en Arichuna\nque allí con los forasteros\ntodas las hembras son una.",198,4,-1,-1,"",0,4,"ua",56,0,-1,0,55,55,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00125",10,"Al Juez para una demanda\nllegué a Cabruta buscando\ny el Secretario me dijo\nque estaba cachicameando.",198,4,-1,-1,"",0,4,"ao",33,0,-1,0,56,56,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00126",10,"En Ocumare no estao\nSan Sebastián no lo he visto,\nen Cúa y San Casimiro\nhay mucho hombre reparisto.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,56,56,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00127",10,"Altagracia de Orituco\nes pueblo que yo no quiero,\nporque allá son muy malucos\nlos dotores papeleros.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,56,56,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00128",10,"Cuando voy a Guariquito\nsiempre me vengo ostinao\nde tanta plaga: puyón,\njején, mosquito rayao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,56,56,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00129",10,"Hará como cuatro meses\nvi una muchacha en Sarare,\ntenía en la cara más pintas\nque un tabaco capadare.",198,4,-1,-1,"",0,4,"ae",175,0,-1,0,57,57,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00130",10,"Puerto Rico no es tan rico\ncomo me lo han ponderao\nni Bajo Seco es tan seco\nni Apure tan apurao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,57,57,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00131",10,"Costa Rica no es tan rica\ncomo la ponderan tanto,\nni la Vera Cruz es vera\nni Santo Domingo santo.",198,4,-1,-1,"",0,4,"ao",30,0,-1,0,57,57,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00132",10,"En Camatagua hay un baile,\nen Barbacoas un velorio;\ndicen que se casa Juana,\npero no conoce el novio.",198,4,-1,-1,"",0,4,"oo",-1,0,-1,0,57,57,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00133",10,"Recuerdo de mi hermanito\nel que se comió el caimán,\nen el paso de Arichuna,\ndiendo para Camaguán.",198,4,-1,-1,"",0,4,"a",147,0,-1,0,57,57,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00134a",10,"Perro que come manteca\nmete la lengua en tapara;\ntodos Los Encarbonaos\nson hijos de Parapara.",198,4,-1,-1,"",0,4,"aa",57,0,-1,0,59,59,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00134b",10,"Yo conocí en El Socorro\na mucho hombre encopetao;\na Pedro Vicente Hernández\nque era de toro parao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,59,59,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00135",10,"Jacinto en Valle e La Pascua,\nTalavera en Calabozo;\nen el pueblo de Zaraza\nVolcán, fresco en su negocio.",198,4,-1,-1,"",0,4,"oo",-1,0,-1,0,60,60,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00136",10,"En Espino los Martínez,\nlos Cobeñas en Parmana,\ny un general Cabrera\nque fue Patriarca en Iguana.",198,4,-1,-1,"",0,4,"aa",4,0,-1,0,60,60,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00137",10,"En Cabruta, Jacobito,\nMarcos Cordero en Caicara;\nen el pueblo e Las Bonitas\nno hay una bonita cara.",198,4,-1,-1,"",0,4,"aa",57,0,-1,0,60,60,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00138",10,"Yo encontré a Torres Carujo\nconversando con Padrón\nen el Paso Pachequero\nque iba con Hernández Ron.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,60,60,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00139",10,"Miré a Benjamín Caldera\nel hombre más estudiao,\npescando en una chorrera\njunto a un barranco sentao.",198,4,-1,-1,"",1,4,"ao",98,0,-1,0,60,60,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00140",10,"Estuve en La Cruz Rubiera:\nvi a Pancho Mier y Terán\nen una bestia cerrera\nque le ensilló Sebastián.",198,4,-1,-1,"",1,4,"a",147,0,-1,0,61,61,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00141",10,"Hará cuatro años y pico\nque no visito El Calvario,\nporque les di en el jocico\nal Juez y al Secretario.",198,4,-1,-1,"",1,4,"ao",25,0,-1,0,61,61,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00142",10,"Acordarme no quisiera\nde aquel término apureño,\ndel fulano Salazar\ny el tal Nicolás Briceño.",198,4,-1,-1,"",0,4,"eo",138,0,-1,0,61,61,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00143",10,"Tuvo la suerte tan negra\nel general Echandía\nque en toda guerra que había\nlo derrotaba su suegra.",198,4,-1,-1,"",11,4,"ea",382,0,-1,0,61,61,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00144",10,"Este verano que viene\nte convido pa una fiesta\nque tiene Ramón Amparan\nen el Paso e La Carreta.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,61,61,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00145",10,"Comandante Belisario\nno me lleve a la pelea\nporque se me aflije el cuerpo\ncuando la bala chiflea.",198,4,-1,-1,"",0,4,"ea",54,0,-1,0,62,62,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00146",10,"Se me alegra el corazón\ncon un vaso de cocuy\npor eso tengo intenciones\nde viví en el Yaracuy",198,4,-1,-1,"",0,4,"i",408,0,-1,0,62,62,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00147",10,"La iguana y el mato de agua\nse fueron al Orinoco:\nla iguana no volvió más,\nni el mato de agua tampoco.",198,4,-1,-1,"",0,4,"oo",152,0,-1,0,62,62,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00148",10,"Le dijo el mono a la ardita\nen la Selva de Turén:\ncuando le brinques a un palo\nme avisas, que yo también.",198,4,-1,-1,"",0,4,"e",242,0,-1,0,62,62,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00149",10,"Tengo una lanza en Arauca\ncon un cabo de platina,\ny en la cintura, terciada,\nuna Santa Catalina.",198,4,-1,-1,"",0,4,"ia",11,0,-1,0,63,63,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00150",10,"A que nadie me adivina\nde quien toi enamorao,\nde la muchacha más buena\nde San José de Tiznao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,63,63,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00151",10,"Ah! mundo, cuando era mundo;\nAh! Llanos, cuando eran Llanos!\ntanto mueren los enfermos\ncomo los buenos y sanos.",198,4,-1,-1,"",0,4,"ao",318,0,-1,0,63,63,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00152",10,"Cuando voy al Llano abajo\nlos mismos vientos me llevan,\ny cuando vengo de allá\nno hay viento ni cosa buena.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,64,64,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00153",10,"Si fueres al Llano arrriba\nsalúdame a Juan Sotillo\nel hijo del General\nque escupía por el colmillo.",198,4,-1,-1,"",0,4,"io",228,0,-1,0,64,64,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00154",10,"Aguacates de Acarigua,\nplátanos de San Fernando,\nal que le debo le pago\na ver si sigue cobrando.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,64,64,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00155",10,"En el Palo de Machao\nme cogió una comisión,\nporque me encontró bailando\ncon una zamba e pitón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,65,65,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00157",10,"Allá va la cachicama\npor la orilla e la quebrá,\nsi los perros no son buenos\nla cachicama se va.",198,4,-1,-1,"",0,4,"a",9,0,-1,0,68,68,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00158",10,"Pa chigüire puya e juajua,\npara morrocoy candela,\npara la mula mañosa\narristranco y gurupera.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,68,68,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00159",10,"Para gallina, maiz,\npara la garza el pescao,\ny las mujeres bonitas\npara el hombre enamorao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,68,68,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00160",10,"Como el acure hace daño\nmetido en el arrozal,\ncon esos ojos azules\ntú me estás haciendo mal.",198,4,-1,-1,"",0,4,"a",1,0,-1,0,69,69,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00161",10,"El cochino come maiz,\ncada uno tiene su antojo,\ny hasta a las viejas les gusta\ncuando les pican el ojo.",198,4,-1,-1,"",0,4,"oo",400,0,-1,0,69,69,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00162",10,"El terecay en el caño\nse encontró con la tortuga,\ny caminandito fueron\na nadar en la laguna.",198,4,-1,-1,"",0,4,"ua",-1,0,-1,0,69,69,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00163",10,"El toro pita la vaca,\ny el novillo se retira;\ncomo el novillo fue toro\nla vaca siempre lo mira.",198,4,-1,-1,"",0,4,"ia",372,0,-1,0,69,69,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00164",10,"Yo tengo una yegua mora\nque no es bonita ni fea,\npero se puede sacar\ndonde la gente la vea.",198,4,-1,-1,"",0,4,"ea",54,0,-1,0,70,70,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00165",10,"Yo tengo una vaca negra\nques tuerta y garrapatosa;\nme hace acordar de mi suegra\npor lo brava y lo mañosa.",198,4,-1,-1,"",1,4,"oa",63,0,-1,0,70,70,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00166",10,"A los montes me retiro\na hablar con los animales;\ncomo son irracionales\nacaso tengan razón.",198,4,-1,-1,"",5,4,"o",-1,0,-1,0,70,70,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00167",10,"Viven cual perros y gatos\nlos hombres en sociedad:\nlos animales se unen....\n¿quién más animal será?",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,70,70,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00168",10,"Más vale querer un perro\nque querer a una mujer;\nel perro es agradecío\ndonde le dan de comer.",198,4,-1,-1,"",0,4,"e",20,0,-1,0,71,71,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00169",10,"A mí no me aruña gato,\nratón no ruñe mi queso,\nmujer no juega conmigo,\nhombre....no venga con eso.",198,4,-1,-1,"",0,4,"eo",48,0,-1,0,71,71,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00170",10,"Si yo fuera basilisco\nque con el mirar matara,\nmis ojos te dieran muerte\npa que nadie te gozara.",198,4,-1,-1,"",0,4,"aa",57,0,-1,0,71,71,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00171",10,"Rayados los matos son\ny caminan empinaos,\ny se meten en sus cuevas\ncon el rabito parao.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,71,71,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00172",10,"Del toro la vuelta al cacho,\ndel caballo la carrera,\nde las muchachas bonitas.\nla cincha y la gurupera.",198,4,-1,-1,"",0,4,"ea",44,0,-1,0,71,71,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00173",10,"Pa juerte mi potro rucio,\npa tibio el toro encerao,\ny pa no queré a nadie\ntu corazoncito amao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,72,72,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00174",10,"Cuando ensillo mi caballo\ny me fajo mi machete\nno envidio la suerte a naide\nni aun al mismo Presidente.",198,4,-1,-1,"",0,4,"ee",-1,0,-1,0,73,73,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00175",10,"Arrogante yo me siento\ncuando monto mi caballo:\nen la pampa no transijo\nni con rey ni con vasallo.",198,4,-1,-1,"",0,4,"ao",102,0,-1,0,73,73,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00176",10,"Ensillando mi caballo\nle pongo la mano en l'anca:\n¿Quien es aquel qué no llora\npor el amor de una blanca?",198,4,-1,-1,"",0,4,"aa",75,0,-1,0,73,73,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00177",10,"El caballo que monté\ncuando dentré en la campaña\nera rucio marmoleño,\ncon las ancas alazanas.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,74,74,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00178",10,"Dispénsenme si me atrevo\na murmurar a mi antojo;\nya saben que a potro flojo\nno hay más que chaparro nuevo.",198,4,-1,-1,"",11,4,"eo",240,0,-1,0,74,74,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00179",10,"¿Quiere que le monte el potro\ny se lo haga caminar?\npóngale la gurupera\ndonde tiene el cabezal.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,74,74,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00180",10,"Si quieres ser muy feliz\nprocura que estén contigo\ntu caballo, tu mujer,\ny tu cobija y tu amigo.",198,4,-1,-1,"",0,4,"io",106,0,-1,0,74,74,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00181",10,"Mi caballo y mi mujer\nse me murieron a un tiempo:\nmi mujer... Dios la perdone:\nmi caballo es lo que siento.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,75,75,"","",0,"carrizo_salta","","",3,0,0,[],""],["machado_venezuela-00182",10,"Cuando murió mi mujer\nno fue grande mi disgusto;\ncuando murió mi caballo\nestuve un año de luto.",198,4,-1,-1,"",0,4,"uo",-1,0,-1,0,75,75,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00183",10,"No sonría zamba, asina\ncuando me vea cabalgar,\nque sus ojos me marean\ny me puede hacer matar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,75,75,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00184",10,"Las golondrinas que cantan\nde tu casa en rededor\nme trajeron ayer tarde\ntus suspiritos de amor.",198,4,-1,-1,"",0,4,"o",72,0,-1,0,77,77,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00185",10,"Quisiera ser golondrina\npara levantar el vuelo,\ny buscar en otros climas\npara mis penas consuelo.",198,4,-1,-1,"",0,4,"eo",10,0,-1,0,77,77,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00186",10,"La perdiz canta en el monte,\nel pájaro en la cañada;\nla mujer es la que pierde,\nel hombre no pierde nada.",198,4,-1,-1,"",0,4,"aa",49,0,-1,0,77,77,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00187",10,"Ví un pajarito volando\nque en el pico lleva flores,\nen las alitas suspiros\ny en el corazón amores.",198,4,-1,-1,"",0,4,"oe",5,0,-1,0,78,78,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00188",10,"¿Sabes lo que el Cristofué\ndice cantando en las ramas?\nque aunque ya tú no me aguaites\nno abandone la esperanza.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,78,78,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00189",10,"Del gavilán tuve celos,\ny tuve celos por tí,\ncuando ayer en la mañana\nallá en tu patio lo ví.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,78,78,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00190a",10,"Guacharaca de mi vida\nnacida en el mes de enero.\n¿Cómo quieres que te olvide\nsi fuiste mi amor primero?",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,79,79,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00190b",10,"El gallo en su gallinero\nse sacude y luego canta;\nel que duerme en cama agena\ntempranito se levanta.",198,4,-1,-1,"",0,4,"aa",148,0,-1,0,79,79,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00191a",10,"El gallo en su gallinero\nse sacude y aletea,\nel que duerme en cama agena\ndespacito se voltea.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,79,79,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00191b",10,"Ya se fue la paraulata\ncon su canillita seca;\ngavilán no se la come\nporque no tiene manteca.",198,4,-1,-1,"",0,4,"ea",594,0,-1,0,79,79,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00192",10,"Donde hay cambures maduros\nnunca faltan pajaritos\ndonde hay muchachas bonitas\nnunca falta un babosito.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,79,79,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00193",10,"Al pasar por tu ventana\nme dijeron: yo te adoro\nyo pensé que era una niña\ny era un condenado loro.",198,4,-1,-1,"",0,4,"oo",85,0,-1,0,80,80,"","",0,"","","",8,0,0,[],""],["machado_venezuela-00194",10,"Una palomita blanca\nparada en la torre está:\nah, quién fuera palomita\npara tan alto volar.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,80,80,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00195",10,"Oye, palomita blanca,\npaloma del palomar,\n¿Con quién anoche tuviste\nque no me quieres hablar?",198,4,-1,-1,"",0,4,"a",21,0,-1,0,80,80,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00196",10,"El que tenga su paloma\nténgala con gran cuidado,\nque no será la primera\nque gavilán se ha llevado.",198,4,-1,-1,"",0,4,"ao",14,0,-1,0,80,80,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00197",10,"Paloma, al monte no vayas\nque te come gavilán;\nsi no te come te espanta,\nquien viviere lo verá.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,81,81,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00198a",10,"En la mesa puse el vaso\ny en el vaso una redoma,\nen la redoma una rosa\ny en la rosa una paloma.",198,4,-1,-1,"",0,4,"oa",-1,0,-1,0,81,81,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00198b",10,"Palomita, palomita:\nmira que soy cazador,\nque si te tiro y te mato\npara mí será el dolor.",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,81,81,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00199",10,"No todos son cazadores\nlos que por el monte van:\nunos cazan las palomas,\notros, las hijas de Adán.",198,4,-1,-1,"",0,4,"a",147,0,-1,0,81,81,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00200",10,"Me monté en un alto pino\npor ver si la divisaba,\ny como el pino era verde\nen vez de verla, lloraba.",198,4,-1,-1,"",0,4,"aa",28,0,-1,0,83,83,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00201",10,"A tus puertas planté un pino,\nal cielo alcanzan las ramas,\nsi tienes tu amor en otro\n¿Por qué no me desengañas?",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,83,83,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00202",10,"En tu puerta planté un pino\ny en tu ventana un laurel:\naunque me maten a tiros\nsiempre te habré de querer.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,83,83,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00203",10,"Debajo de un limón verde\ndonde mana el agua fría\nyo entregué mi corazón\na quien no lo merecía.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,84,84,"","",0,"","","",9,0,0,[],""],["machado_venezuela-00204",10,"Al limón córtale el agrio,\nal agrio la fortaleza,\nno creer a las mujeres\nporque no tienen firmeza.",198,4,-1,-1,"",0,4,"ea",108,0,-1,0,84,84,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00205",10,"Mi naranjo tiene espinas,\nel tuyo tiene también,\nmi corazón es el tuyo,\nel tuyo,... no sé de quien.",198,4,-1,-1,"",0,4,"e",242,0,-1,0,84,84,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00206",10,"Una naranja madura\nle dijo a la que era verde:\nel que siembra en tierra agena\nhasta la semilla pierde.",198,4,-1,-1,"",0,4,"ee",154,0,-1,0,84,84,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00207",10,"Se secó mi naranjito\nteniendo el agua en el pie,\nen el tronco la esperanza\ny en el pimpollo la fe.",198,4,-1,-1,"",0,4,"e",77,0,-1,0,84,84,"","",0,"carrizo_salta","","",2,0,0,[],""],["machado_venezuela-00208",10,"Me dijiste que eras firme\ncomo la palma en desierto;\nsi la palma fuera firme\nno la tremolara el viento.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,85,85,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00209",10,"Yo sembré mi yerbabuena\ny se me volvió culantro;\nyo no sé, vidita mía,\npor qué nos queremos tanto.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,85,85,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00210",10,"Yo sembré mi yerbabuena\nse murió, y volvió a crecer:\nsinvergüenza fuera yo\nsi te volviera a querer.",198,4,-1,-1,"",0,4,"e",20,0,-1,0,85,85,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00211a",10,"Arranqué de la berbena\na un pimpollo la mitad,\nno hay cosa que más amargue\nque un amor sin voluntad.",198,4,-1,-1,"",0,4,"a",16,0,-1,0,85,85,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00211b",10,"Aprended flores de mí\nlo que va de ayer a hoy,\nayer maravilla fui\nhoy sombra de mí no soy.",198,4,-1,-1,"",1,4,"o",112,0,-1,0,85,85,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00212",10,"Un rosal cría una rosa,\ny una maceta un clavel,\ny un padre cría a su hija\nsin saber para quien es.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,86,86,"","",0,"carrizo_salta","","",8,0,0,[],""],["machado_venezuela-00213",10,"El clavel que ayer me diste\nentero me lo he comido:\naquí en el pecho lo siento\nclavado y más encendido.",198,4,-1,-1,"",0,4,"io",101,0,-1,0,86,86,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00214",10,"Clavelito colorado\nnacido en aquel peñón,\n¿Por qué le das tan mal pago\na este triste corazón?",198,4,-1,-1,"",0,4,"o",31,0,-1,0,86,86,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00215",10,"Buen encuentro hemos tenido\nbello clavel encarnado,\ndime pronto si me quieres\no me tienes engañado.",198,4,-1,-1,"",0,4,"ao",14,0,-1,0,86,86,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00216",10,"Buen encuentro hemos tenido\nhermosísima azucena,\nquisiera que tu hermosura\nle diera alivio a mi pena.",198,4,-1,-1,"",0,4,"ea",59,0,-1,0,86,86,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00217",10,"A todos les da claveles\nla hermosura de la plaza;\na todos les da claveles\ny a mí me da calabazas.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,87,87,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00218",10,"Las rosas en los rosales\npor tiempos se reverdecen,\na según las voluntades\nasí los amores crecen.",198,4,-1,-1,"",0,4,"ee",359,0,-1,0,87,87,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00219",10,"De las peñas mana el agua,\nde los páramos el viento,\ny del pecho de la ingrata\nel mal agradecimiento.",198,4,-1,-1,"",0,4,"eo",94,0,-1,0,89,89,"","",0,"carrizo_salta","","",2,0,0,[],""],["machado_venezuela-00220",10,"A las orillas de un río,\na la sombra de un laurel,\nme acordé de tí, bien mío,\nviendo las aguas correr.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,89,89,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00221",10,"Agua que corriendo vas,\nbañando el campo florido,\ndame razón de mi bien,\nmira que se me ha perdido.",198,4,-1,-1,"",0,4,"io",101,0,-1,0,89,89,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00222",10,"Este pozo se secó\npero antes tuvo agua;\ny yo, antes de ser pobre,\ntambién tuve mucha plata.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,90,90,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00223",10,"El que ha sido navegante\ncuando ve la mar, suspira,\ny yo tengo por venganza\nolvidar a quien me olvida.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,90,90,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00224",10,"Vamos a la mar, morena,\nque allá nos embarcaremos:\ntu cuerpo será el navío,\nmis brazos serán los remos.",198,4,-1,-1,"",0,4,"eo",127,0,-1,0,90,90,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00225",10,"A la mar mandé por perlas\ny me trajeron corales\ncon qué hacer unas pulseras\npara alivio de mis males.",198,4,-1,-1,"",0,4,"ae",26,0,-1,0,90,90,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00226",10,"Para abajo corre el agua,\npara arriba corre el viento;\npara donde van tus ojos\nse llevan mis pensamientos.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,90,90,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00227",10,"Asómate a la ventana\ny verás correr el río,\ncomo corren mis amores\ncuando están correspondíos.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,91,91,"","",0,"","","",13,0,0,[],""],["machado_venezuela-00228",10,"Quien te puso la Pastora\nno te supo dar el nombre,\nmás vale te hubiera puesto\nla perdición de los hombres.",198,4,-1,-1,"",0,4,"oe",-1,0,-1,0,93,93,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00229",10,"Maricela se ha perdido\nen el camino e Caracas:\nsu madre la anda buscando\ncon el cinco y las maracas.",198,4,-1,-1,"",0,4,"aa",665,0,-1,0,93,93,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00230",10,"Señora Juana Bautista\nyo la quiero mucho a usted;\nusted se muere por otro:\neste mundo está al revés.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,93,93,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00231",10,"A mí me gusta Silveria\nla que raspa el papelón;\nSilveria, dame la mano,\nla mano del corazón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,94,94,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00232",10,"Tiene un espejo Beatriz\nque está que se vuelve loca,\nporque se ha visto la boca\ndebajo de la nariz.",198,4,-1,-1,"",11,4,"i",335,0,-1,0,94,94,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00233",10,"Mañana se va Pastora,\nmañana se va Teresa,\nel que no lleva la carga\nle parece que no pesa.",198,4,-1,-1,"",0,4,"ea",201,0,-1,0,94,94,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00234",10,"Asómate a la ventana\nCarmelita, y dame el sí;\ntengo un dolor en el alma\nCarmelita, y es por ti.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,95,95,"","",0,"","","",13,0,0,[],""],["machado_venezuela-00235",10,"Mariquita, dame un beso\nque tu madre me mandó\n— Mi madre manda en lo suyo;\nen lo mío, mando yo.",198,4,-1,-1,"",0,4,"o",2,0,-1,0,95,95,"","",0,"","","",7,0,0,[],""],["machado_venezuela-00236",10,"Jacinta me dió una cinta,\nJuanita me dió un cordón;\nen mi alma está Jacinta,\nJuanita en mi corazón.",198,4,-1,-1,"",1,4,"o",31,0,-1,0,95,95,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00237",10,"A la catira Ramona\nquien sabe si le dirán\nque élla es la triste paloma\ny yo soy el gavilán.",198,4,-1,-1,"",0,4,"a",147,0,-1,0,95,95,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00238",10,"Cuando me acuerdo de Lola\nque allá me estará esperando\nse me sale de la boca\nla arepa que estoy mascando.",198,4,-1,-1,"",0,4,"ao",33,0,-1,0,95,96,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00240",10,"María me dio una rosa,\nIsabel me dio un clavel;\nMaría, toma tu rosa\nque me voy con Isabel.",198,4,-1,-1,"",1,4,"e",32,0,-1,0,96,96,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00241",10,"Yo soy, y no me conozco,\nhijo del ají chirel;\ncuando el tigre está en la jaula\nlos burros juegan con él.",198,4,-1,-1,"",0,4,"e",32,0,-1,0,97,97,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00242",10,"Yo me zumbé a Matapués\nque estaba de orilla a orilla,\ny monté sobre un caimán,\ny le quité una costilla.",198,4,-1,-1,"",0,4,"ia",162,0,-1,0,98,98,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00243",10,"Soy un pájaro en el aire,\nsoy un pato en el estero\ny entre muchachas bonitas\nsoy un loro conuquero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,98,98,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00244",10,"Yo no soy de por aquí,\nyo vengo del otro lao,\ncon mi camisa de lienzo\ny mis mangas de listao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,98,98,"","",0,"","","",11,0,0,[],""],["machado_venezuela-00245",10,"Solo soy, solo nací,\nsolo me parió mi madre,\ny solo tengo que andar\ncomo paloma en el aire.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,98,98,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00246",10,"Yo puse una pulpería\ncon el indio Antonio Navas,\nél era el que me vendía,\ny era yo el que le compraba.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,99,99,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00247",10,"Yo no me meto con viejo,\nni tampoco con muchacho,\nno le tengo miedo al toro\nsino a la vuelta del cacho.",198,4,-1,-1,"",0,4,"ao",310,0,-1,0,99,99,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00248",10,"Yo no les temo a las balas\nni a cuchillo, ni a puñales,\nni a un hombre de vara y media\nni de dos varas cabales.",198,4,-1,-1,"",0,4,"ae",26,0,-1,0,99,99,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00249",10,"Alumbro como una vela.\ny corro más que un caballo,\nsi me ponen contra el viento\nvuelo más que un papagayo.",198,4,-1,-1,"",0,4,"ao",293,0,-1,0,99,99,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00250",10,"No conozco el escabeche\nni he visto la limoná;\nyo me alimento con leche\ny con buena carne asáa.",198,4,-1,-1,"",5,4,"aa",-1,0,-1,0,99,99,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00251",10,"No blasono de valiente\npero sí me doy tal rango,\nque el que conmigo se mete\npisa una concha de mango.",198,4,-1,-1,"",0,4,"ao",596,0,-1,0,100,100,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00252",10,"Con mi camisa vestío,\nmi blusa y mi garrasí,\npertenezco al señorío\ny a la nobleza de aquí.",198,4,-1,-1,"",3,4,"i",23,0,-1,0,100,100,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00253",10,"Un pozo de agua es mi espejo;\ny mi rancho es una mata,\nmi comida un merecure\ny mi delirio una vaca.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,100,100,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00254",10,"Sobre la yerba la palma,\nsobre la palma los cielos;\nsobre mi caballo, yo,\ny sobre yo, mi sombrero.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,101,101,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00255",10,"Como nací en la sabana,\ny en la sabana me crié,\nno me amaño a las ciudades\nporque no hay donde corré.",198,4,-1,-1,"",0,4,"e",77,0,-1,0,101,101,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00256",10,"Los llaneros no compramos\nbilletes de lotería;\nzamuro no cae en trampa\nni le dentra brujería.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,101,101,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00257",10,"A mi me llaman el tonto,\nel tonto de mi lugar;\ntodos comen trabajando,\nyo cómo sin trabajar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,101,101,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",8,0,0,[],""],["machado_venezuela-00258",10,"Todos me dicen el sucio;\nverdá que nunca me lavo,\nporque hay un refrán que dice:\nLa cáscara guarda el palo.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,101,101,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00259a",10,"A mi me llaman zoquete,\ny por zoquete me tengo;\ny cuando los vivos van\nyo que soy zoquete vengo.",198,4,-1,-1,"",0,4,"eo",124,0,-1,0,102,102,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00259b",10,"Tan solo mi compañero\nsabe lo bueno y lo malo:\nsabe donde late el perro,\nsabe donde canta el gallo.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,102,102,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00260",10,"Cuando me acuerdo e mi tierra\nme dan ganas de llorar:\ntánta bestia sin ginete;\ntánta dama sin galán.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,102,102,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00261",10,"Yo vivo solo en el mundo\ny de mí nadie se acuerda;\ny busco sombra en el arbol\ny los árboles se secan.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,102,102,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00262",10,"Trabajando estuve un año\npara comprar una espada,\ny ahora, que ya la tengo,\nni soy guapo, ni soy nada.",198,4,-1,-1,"",0,4,"aa",49,0,-1,0,102,102,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00263a",10,"Cuando estaba chiquitico\nme cargaban en los brazos;\nahora, que estoy ya grande,\nme cargan a los porrazos.",198,4,-1,-1,"",0,4,"ao",132,0,-1,0,103,103,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00263b",10,"Niña que vistes de luto\ndíme quien se te murió:\nsi se te murió tu amante\nno llores, que aquí estoy yo.",198,4,-1,-1,"",0,4,"o",2,0,-1,0,103,103,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00264",10,"Querer una no es ninguna\nquerer dos algo será,\nporque si la úna es brava\nla ótra contenta estará.",198,4,-1,-1,"",0,4,"a",9,0,-1,0,103,103,"","",0,"","","",7,0,0,[],""],["machado_venezuela-00265",10,"Mujer, por urbanidá,\nvuélveme a decir que sí,\nsiquiera porque volví\na provocar tu amistá.",198,4,-1,-1,"",11,4,"a",9,0,-1,0,103,103,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00266",10,"Para qué me diste el sí\ntraidora, teniendo dueño,\npues sabe que no se goza\ncon gusto, lo que es ajeno.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,103,103,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00267",10,"Hace ocho días que no cómo,\ny otros tántos que no duermo,\nni cómo, ni tengo hambre,\nni duermo, ni tengo sueño.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,104,104,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00268",10,"Cuando me vine de casa\nsalí por el boquerón,\ncon mi chamarrita al hombro\nque quebraba el corazón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,105,105,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00269",10,"Mis amigos me abandonan\nporque me vean abatido,\ntodo el mundo corta leña\ndel árbol que está caído.",198,4,-1,-1,"",0,4,"io",101,0,-1,0,105,105,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00272",10,"No hay amigos en el mundo\nni se halla de quien confiar:\nno hay más amigo que Dios\ny en la faltriquera un real.",198,4,-1,-1,"",3,4,"a",-1,0,-1,0,106,106,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00272-e2",10,"Contra un amigo traidor\nno hay precauciones que basten,\nni mercedes que lo obliguen,\nni dádivas que lo ablanden.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,106,106,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00273",10,"Una vieja se...ca, se...ca,\nse...ca, se...ca, se casó.\ncon un viejo seco, seco,\nsecos, secos, son los dos.",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,107,107,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00274",10,"Las viejas valen a medio,\ny las muchachas a cuarto,\ny yo. como soy muy pobre,\nme voy a lo más barato.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,107,107,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00275",10,"Siempre verán a las viejas\nechándolas de bonitas,\nno saben que cuero viejo\nno sirve ni pa cotizas.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,107,107,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00276",10,"Las viejas para coser\npiden anteojos prestados;\npara celar a sus hijas\ntienen los ojos pelados.",198,4,-1,-1,"",0,4,"ao",18,0,-1,0,108,108,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00277",10,"Una vieja se ca...yó\ndetrás del Altar Mayor,\nla gente salió corriendo\ncreyendo que era temblor.",198,4,-1,-1,"",0,4,"o",72,0,-1,0,108,108,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00278",10,"Una vieja me dió un palo\npara enseñarme a rezar,\ncuando me tenía en el suelo:\nmuchacho, por la señal.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,108,108,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00279",10,"Recójanme toas las viejas\nháganmelas un montón,\npara darles chocolate\ncon una mano e pilón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,108,108,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00280",10,"Una vieja me dió un beso\nque me tiene enmabitao;\nlos besos que dan las viejas\nsaben a cacho quemao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,108,108,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00281",10,"Muchacha, dile a tu madre\nque si quiere ser mi suegra,\ny verás, si se lo dices,\ncomo la vieja se alegra.",198,4,-1,-1,"",0,4,"ea",382,0,-1,0,109,109,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00282",10,"El que quisiere saber\nde que color es la pena\nsiente plaza de soldado\ny auséntese de su tierra.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,111,111,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00283",10,"A la guerra me voy, madre,\nécheme su bendición:\n— La de Dios vaya contigo,\nhijo de mi corazón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,111,111,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00284",10,"Mientras haiga un General\nno he de comprar ni una perra\nporque éllos para robar\nde naa forman una guerra.",198,4,-1,-1,"",0,4,"ea",80,0,-1,0,111,111,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00285",10,"Yo conozco Generales\nhechos a los empujones;\na conforme es la manteca\nasí son los chicharrones.",198,4,-1,-1,"",0,4,"oe",34,0,-1,0,112,112,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00286",10,"Amigo, no he dio a la guerra\nni siquiera soy sordao;\nno me diga General\nporque nada le he robao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,112,112,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00287",10,"Allá arriba en aquel alto\ntengo una mata de ají\ndonde me paso las horas\nsolito, pensando en ti.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,113,113,"","",0,"","","",10,0,0,[],""],["machado_venezuela-00288",10,"Allá arriba en aquel alto\ntengo un pañuelo volando,\nen las puntas tiene escrito:\nya mi amor se va acabando.",198,4,-1,-1,"",0,4,"ao",33,0,-1,0,113,113,"","",0,"","","",10,0,0,[],""],["machado_venezuela-00289",10,"Allá arriba en aquel alto\ntengo un palo colorao,\ndonde pongo mi sombrero\ncuando estoy enamorao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,113,113,"","",0,"","","",10,0,0,[],""],["machado_venezuela-00290",10,"Allá arriba en aquel alto\ntengo una cajita de oro\ndonde guardo mis suspiros\ny las lágrimas que lloro.",198,4,-1,-1,"",0,4,"oo",85,0,-1,0,114,114,"","",0,"","","",10,0,0,[],""],["machado_venezuela-00291",10,"Allá arriba en aquel alto\ntengo un chivato amarrao,\nque en las barbas se parece\nal galán que tengo al lao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,114,114,"","",0,"","","",10,0,0,[],""],["machado_venezuela-00292",10,"El amor es un bichito\nque por los ojos se mete,\ny en llegando al corazón\nda fatiguitas de muerte.",198,4,-1,-1,"",0,4,"ee",-1,0,-1,0,115,115,"","",0,"carrizo_salta","","",10,0,0,[],""],["machado_venezuela-00293",10,"El amor correspondido\nes un destello del cielo,\nno siéndolo es desconsuelo\nque del infierno ha salido.",198,4,-1,-1,"",11,4,"io",101,0,-1,0,115,115,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00294",10,"¡Cuán dulce sabe el amor\ncuando es bien correspondido;\ny qué grande la amargura\ncuando el amor es finjido!",198,4,-1,-1,"",0,4,"io",101,0,-1,0,115,115,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00295a",10,"Ama el ave cuando pía,\nama al mecerse la flor,\ny el alma del alma mía\nno sabe lo que es amor.",198,4,-1,-1,"",1,4,"o",72,0,-1,0,116,116,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00295b",10,"Si yo mismo no adivino\nsecretos del corazón,\n¿cómo quieres que comprenda\nsi tú me tienes amor?",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,116,116,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00296",10,"Acabo de comprender\nque no me tienes amor,\nporque me tienes secando\ncomo ramito en el sol.",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,116,116,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00297a",10,"El amor que te tenía\nen una rama quedó;\nvino un fuerte remolino,\nrama y amor se llevó.",198,4,-1,-1,"",0,4,"o",2,0,-1,0,116,116,"","",0,"frenk_t2","","",5,0,0,[],""],["machado_venezuela-00297b",10,"Ah, refrán bien verdadero:\namor con hambre no dura,\nque en habiendo dividive\nla curtiembre está segura.",198,4,-1,-1,"",0,4,"ua",17,0,-1,0,116,116,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00298",10,"El amor del forastero\nes como espina de tuna,\nque punza, y queda doliendo\nsin esperanza ninguna.",198,4,-1,-1,"",0,4,"ua",56,0,-1,0,117,117,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00299",10,"El amor de los soldados\nes como plato de arena,\nque en poniéndolo en la calle\nviene el viento y se la lleva.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,117,117,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00300",10,"El amor de las mujeres\nes como el de las gallinas,\nque en faltándoles el gallo\na cualquier pollo se arriman.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,117,117,"","",0,"antioquia_animales","","",17,0,0,[],""],["machado_venezuela-00301",10,"El amor me llamó hermano\nen mi niñez, cierto día,\ny yo no le di la mano\nporque no lo conocía.",198,4,-1,-1,"",1,4,"ia",0,0,-1,0,117,117,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00302",10,"Madre, yo compré un cariño\nen la feria del amor:\nqué bonito era el juguete,\ny que caro me costó.",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,118,118,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00303",10,"El amor y el interés\nsalieron al campo un día,\ny más pudo el interés\nque el amor que me tenía.",198,4,-1,-1,"",1,4,"ia",0,0,-1,0,118,118,"","",0,"","","",9,0,0,[],""],["machado_venezuela-00304",10,"A toditas las mujeres\nles tengo grande aficción,\npero más a las muchachas\nque alégranme el corazón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,119,119,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00305",10,"No hay que creer en mujeres,\nesa es la pura verdá;\nla que santita parece\nmás fácil la muerte da.",198,4,-1,-1,"",0,4,"a",9,0,-1,0,119,119,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00306",10,"Una jamuga merece\nel que de mujer se fía;\ny como yo me fié en una\nla primer jamuga es mía.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,119,119,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00307",10,"No te fíes de mujeres.\naunque las veas llorar,\npues sus lágrimas te dicen\nel pago que te han de dar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,120,120,"","",0,"","","",6,0,0,[],""],["machado_venezuela-00308",10,"A las mujeres quererlas\ny no darles de comer;\nporque hartas aborrecen\ny con hambre quieren bien.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,120,120,"","",0,"","","",7,0,0,[],""],["machado_venezuela-00309",10,"Una mujer fue la causa\nde mi perdición primera:\nno hay perdición en el mundo\nque por mujeres no venga.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,120,120,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00311",10,"No hay atajo sin trabajo,\nni camino sin verea,\nni mujer que no se enoje\ncuando le dicen que es fea.",198,4,-1,-1,"",0,4,"ea",54,0,-1,0,120,120,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00312",10,"Las mujeres de este tiempo\nson como las avellanas:\nuna sola es buena en ciento\ny noventa y nueve malas.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,121,121,"","",0,"","","",8,0,0,[],""],["machado_venezuela-00313",10,"No hay mujer que no se enoje\ncuando le dicen que es fea:\nla mujer, como la mula,\nsi no recula, patea.",198,4,-1,-1,"",0,4,"ea",54,0,-1,0,121,121,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00314",10,"Si el tabaco se te apaga\nno lo vuelvas a encender;\na la mujer que te olvide\nno la vuelvas a querer.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,121,121,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00315",10,"El carbón que ha sido brasa\nes muy facil de prender,\nporque a mí me ha acontecido\nque olvido y vuelvo a querer.",198,4,-1,-1,"",0,4,"e",20,0,-1,0,121,121,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00316",10,"A la mujer que es celosa\nse lo conozco temprano,\nporque agacha la cabeza\ncomo burro con gusano.",198,4,-1,-1,"",0,4,"ao",81,0,-1,0,121,121,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00317",10,"La mujer enamorada\nla conozco muy lijero,\nporque agacha la cabeza\ncomo burro malojero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,122,122,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00318",10,"El pájaro y la mujer\nno se deben dejar solos;\nel primero con el gato,\nla segunda con el novio.",198,4,-1,-1,"",0,4,"oo",-1,0,-1,0,122,122,"","",0,"lafuente_madrid","","",2,0,0,[],""],["machado_venezuela-00319",10,"A la mujer enamorada\nque le aconsejan recato\nes como el que tiene hambre\ny le dan bicarbonato.",198,4,-1,-1,"",0,4,"ao",19,0,-1,0,122,122,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00320",10,"La mujer que quiere a dos\nlos quiere como hermanitos:\nel úno le trae la jaula,\nel ótro los pajaritos.",198,4,-1,-1,"",0,4,"io",254,0,-1,0,122,122,"","",0,"","","",12,0,0,[],""],["machado_venezuela-00321",10,"La mujer que quiere a dos\nes discreta y entendida;\nsi una vela se le apaga\nla otra le queda encendida.",198,4,-1,-1,"",0,4,"ia",37,0,-1,0,122,122,"","",0,"frenk_t2","","",12,0,0,[],""],["machado_venezuela-00322",10,"Las mujeres son el diablo\nparientes de lucifer,\nse visten por la cabeza,\nse desnudan por los pies.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,123,123,"","",0,"frenk_t2","","",8,0,0,[],""],["machado_venezuela-00323",10,"Los hombres son el demonio:\nasí dicen las mujeres;\npero siempre andan buscando\nque el demonio se las lleve.",198,4,-1,-1,"",0,4,"ee",-1,0,-1,0,123,123,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00324",10,"Zapato que yo calcé\ny lo boté al basurero\nque importa que otro lo calce\nsi yo lo calcé primero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,123,123,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00325",10,"Cada vez que yo recuerdo\nque tuve un amor ingrato,\nno sé como no me doy\ncontra un colchón y me mato.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,123,123,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00326",10,"Si me preguntan aquello\nconfesaré la verdá;\n¿Cómo quieres que lo niegue\nestando tú como estás?",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,123,123,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00327",10,"Ahí te mando tu sortija,\ntus cartas y tu pañuelo;\nespérame en Los Chaparros\npara llevarte tus besos.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,124,124,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00328",10,"Viva Dios, viva la patria,\nviva la flor de romero;\nviva la mujer que pasa\ntrabajos por un soltero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,125,125,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00329",10,"Viva Dios, viva la patria,\nviva la flor de granao;\nviva la mujer que pasa\ntrabajos por un casao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,125,125,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00330",10,"Carga la mortaja en la anca,\nmás, atrás la mosquitá\ny la sepultura abierta\nel que ama mujer casáa.",198,4,-1,-1,"",5,4,"aa",-1,0,-1,0,125,125,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00331",10,"Una novia que yo tuve\ntodas las efes tenía:\nera flaca, fea y floja,\nfregona, frágil y fría.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,126,126,"","",0,"andina_t2","","",3,0,0,[],""],["machado_venezuela-00332b",10,"La niña que acepta novio\nporque le dicen que es bueno\nquien sabe si va labrando\nsu más terrible tormento.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,126,126,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00333",10,"No te cases sin amor,\nsi quieres paz duradera;\narbolito sin raíces\nviene el viento, y se lo lleva'.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,126,126,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00333-e2",10,"Compañero, no se case,\ngoce de su vio ceda;\ndeje casar a los bobos\npara ver como les va.",198,4,-1,-1,"",5,4,"a",-1,0,-1,0,126,126,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00334a",10,"Si se casa, compañero,\nbusque una mujer morena,\npues de las blancas y rubias\nde ciento sale una buena.",198,4,-1,-1,"",0,4,"ea",59,0,-1,0,127,127,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00334b",10,"Son las mayores desdichas\nque un hombre puede tener,\ncasarse con una fea\ny no tener que comer:",198,4,-1,-1,"",0,4,"e",20,0,-1,0,127,127,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00334c",10,"El hombre que se casare\ncon una mujer bonita\nhasta que no llega a vieja\nel susto no se le quita.",198,4,-1,-1,"",0,4,"ia",50,0,-1,0,127,127,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00334d",10,"La mujer que está creyendo\nque yo con ella me caso\nsepa que soy volatón\ny no caigo en ese lazo.",198,4,-1,-1,"",0,4,"ao",43,0,-1,0,127,127,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00335",10,"El que bebe agua en tapara\ny se casa en tierra ajena,\nni sabe si el agua es clara\nni si la mujer es buena.",198,4,-1,-1,"",1,4,"ea",59,0,-1,0,127,127,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00336",10,"La piedra que mucho rueda\nno sirve para cimiento;\nla mujer que a muchos ama\ntarde espere el casamiento.",198,4,-1,-1,"",0,4,"eo",94,0,-1,0,128,128,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00338",10,"Si tu marido es celoso\néchale un güeso en el plato,\nque mientras lo está ruñendo\nconversaremos un rato.",198,4,-1,-1,"",0,4,"ao",19,0,-1,0,128,128,"","",0,"","","",7,0,0,[],""],["machado_venezuela-00339",10,"El cura que me casó\nme dijo en el altosano:\nahí te entrego ese animal\nen figura de cristiano.",198,4,-1,-1,"",0,4,"ao",81,0,-1,0,128,128,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00342",10,"Todo hombre que se casa\ncon una mujer muy niña\nprevenga una vara verde,\nque el miedo guarda la viña.",198,4,-1,-1,"",0,4,"ia",170,0,-1,0,129,129,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00343",10,"El dinero y los amores\nno pueden estar cubiertos:\nel dinero porque suena,\nlos amores, por inquietos.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,129,129,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",4,0,0,[],""],["machado_venezuela-00344",10,"Que triste que está la luna\ny el lucero en su compaña:\nque triste se pone un hombre\ncuando una mujer lo engaña.",198,4,-1,-1,"",0,4,"aa",213,0,-1,0,129,129,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00345",10,"Las estrellas en el cielo,\nla luna en el cafetal,\nboquita de caña dulce\nquien te pudiera besar.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,129,129,"","",0,"","","",18,0,0,[],""],["machado_venezuela-00346",10,"Estrella de la mañana,\nclaro lucero del día,\n¿por qué no me despertaste\ncuando se fue el alma mía?",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,130,130,"","",0,"carrizo_salta","","",4,0,0,[],""],["machado_venezuela-00347",10,"A las cinco muere el sol\nen los brazos de la tarde,\npor eso la triste noche\nviste de negros pañales.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,130,130,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00348",10,"Luna que alumbras la tierra,\npréstame tu claridá\npara seguirle los pasos\na una ingrata que se va.",198,4,-1,-1,"",0,4,"a",9,0,-1,0,130,130,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00349",10,"Ya salió la blanca luna\nvestida de negros velos;\nmalhaya quien se enamora\nde prenda que tenga dueño.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,130,130,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00350",10,"Lucero de la mañana,\nde la mañana lucero,\n¿cómo te vas y me dejas\ncuando soy tu compañero?",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,130,130,"","",0,"","","",22,0,0,[],""],["machado_venezuela-00351",10,"Qué triste parece el cielo\ncuando las nubes se cierran,\n¡ay, del corazón que cubren\nlas nubes de la tristeza!",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,131,131,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00352",10,"En el último escalón,\nya para llegar al cielo,\nme acordé de ti, bien mío,\ny volví a bajar al suelo.",198,4,-1,-1,"",0,4,"eo",10,0,-1,0,131,131,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00353",10,"Todas las mañanas voy\na las orillas del mar\na preguntarle a las olas\nsi han visto mi amor pasar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,133,133,"","",0,"","","",12,0,0,[],""],["machado_venezuela-00354",10,"Al mar voy por ver las olas,\nal campo por ver las flores,\nal cielo por ver estrellas\ny aquí por ver mis amores.",198,4,-1,-1,"",3,4,"oe",5,0,-1,0,133,133,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00355",10,"Primera vez que yo veo\npájaro de mar por tierra:\n¡quién te pudiera querer\nsin que nadie lo supiera!",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,133,133,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00356",10,"Concha llena de colores,\nolas de la mar en calma,\nsi ella admite mis amores\nle daré toda mi alma.",198,4,-1,-1,"",1,4,"aa",125,0,-1,0,134,134,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00357",10,"Soy pescador, y mi anzuelo\ntiro a los mares de amor,\nporque es seguro que va\nla mano donde el dolor.",198,4,-1,-1,"",0,4,"o",72,0,-1,0,134,134,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00358",10,"Ayer pasé por tu puerta,\nme tiraste un limón,\nel zumo me dió en los ojos\ny el golpe en el corazón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,135,135,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00359",10,"Ayer pasé por tu casa,\nalcé los ojos y ví,\nun letrero que decía:\nyo no nací para tí.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,135,135,"","",0,"","","",10,0,0,[],""],["machado_venezuela-00360",10,"Después de haberlo leído\nlo borré, y puse este otro:\ntú, no naciste pa mí,\nni yo para tí tampoco.",198,4,-1,-1,"",0,4,"oo",-1,0,-1,0,135,135,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00361",10,"Ayer pasé por tu casa\ny hallé que estaba sin gente;\nlas gallinas se riyeron\ny el gallo arrugó la frente.",198,4,-1,-1,"",0,4,"ee",15,0,-1,0,136,136,"","",0,"","","",10,0,0,[],""],["machado_venezuela-00361-e2",10,"Ayer tarde hizo un año\nque de ti me enamoré,\n¡víspera de Noche Buena!\nmira, si me acordaré.",198,4,-1,-1,"",0,4,"e",77,0,-1,0,136,136,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00361-e3",10,"Ayer te mandé el pañuelo\npartido en cuatro pedazos;\nen las puntas van los besos,\nen el medio los abrazos.",198,4,-1,-1,"",0,4,"ao",132,0,-1,0,136,136,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00362a",10,"Ayer tarde me morí\ny vide quien me lloró;\nDios se lo pague en el alma\na quien de mí se acordó.",198,4,-1,-1,"",0,4,"o",2,0,-1,0,136,136,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00362b",10,"Ayer te mandé una carta\ndiciéndote la verdad;\nni te quiero, ni te estimo,\nni te tengo voluntad.",198,4,-1,-1,"",0,4,"a",16,0,-1,0,136,136,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00363",10,"Anoche a la media noche\nlloraba un garrapatero,\nporque tocaban a misa\ny no encontraba el sombrero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,137,137,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00364",10,"Anoche a la media noche\nme vinieron a avisar\nque tenías amores nuevos:\n¡Dios te los deje gozar!",198,4,-1,-1,"",0,4,"a",21,0,-1,0,137,137,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00365",10,"Anoche me mordió un perro\ny esta mañana una ardita:\npor qué no me mordería\nuna muchacha bonita.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,138,138,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00366",10,"Anoche soñaba, niña,\nque dos rayos me mataban:\neran tus hermosos ojos\nque enojados me miraban.",198,4,-1,-1,"",0,4,"aa",39,0,-1,0,138,138,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00367",10,"Noche oscura y tenebrosa,\ny temeroso el camino;\nes tanto lo que te quiero\nque a todo me determino.",198,4,-1,-1,"",0,4,"io",199,0,-1,0,138,138,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00368",10,"Cuán oscura está la noche\ndel uno al otro confín;\nasí se queda mi alma\ncuando te apartas de mí.",198,4,-1,-1,"",0,4,"i",-1,0,-1,0,138,138,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00369",10,"Toda la noche me tienes\ncomo garza en la laguna\ncon el pescuezo estirao\nsin esperanza ninguna.",198,4,-1,-1,"",0,4,"ua",56,0,-1,0,138,138,"","",0,"","","",7,0,0,[],""],["machado_venezuela-00370",10,"Esta noche vendré tarde\nporque el burro se perdió;\nsi sientes pasos de burro\nte asomas, que seré yo.",198,4,-1,-1,"",0,4,"o",2,0,-1,0,139,139,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00371",10,"Mañana me voy de aquí\ncomo todos lo verán:\n¡cuando vuelva las espaldas\ncómo no murmurarán!",198,4,-1,-1,"",0,4,"a",147,0,-1,0,141,141,"","",0,"","","",8,0,0,[],""],["machado_venezuela-00372",10,"Hasta mañana, señores,\nporque el moreno se va;\nsi me da la gana vuelvo,\ny si nó, no vuelvo más.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,141,141,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00373",10,"Mañana me voy volando\ncomo pájaro perdido,\npero quizá vuelva luego\na recuperar mi nido.",198,4,-1,-1,"",0,4,"io",101,0,-1,0,141,141,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00374",10,"¿Dices que te vas mañana?\nvete con Dios, amor mío,\ncuenta no bebas el agua\nde la fuente del olvido.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,142,142,"","",0,"carrizo_salta","","",2,0,0,[],""],["machado_venezuela-00375",10,"Adios, porque ya me voy,\nel destino me reclama;\npor si acaso no volviere\n! adiós para siempre, mi alma!",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,142,142,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00376",10,"Nunca me digas adiós:\nque es una palabra triste:\ncorazones que se quieren\nnunca deben despedirse.",198,4,-1,-1,"",0,4,"ie",-1,0,-1,0,142,142,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00377",10,"Ya se fué la vida mía,\nya se fué, y no me llevó;\ntánto como la quería\ny tan mal que me pagó.",198,4,-1,-1,"",1,4,"o",2,0,-1,0,142,142,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00378",10,"¿Qué no llore, compañero?\ncómo no voy a llorar,\ncomo si la ausencia fuera\nremedio para olvidar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,142,142,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00379",10,"Ausente de un bien que adoro\nningún placer me divierte:\nporque ausente de su vista\ntodo lo que veo es muerte.",198,4,-1,-1,"",0,4,"ee",134,0,-1,0,143,143,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00380",10,"Presente te quiero mucho,\nausente te quiero más:\npresente, porque te veo;\nausente, porque no estás.",198,4,-1,-1,"",0,4,"a",51,0,-1,0,143,143,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00381",10,"Dicen que el aguila real\npasa volando los mares:\nAy! quién pudiera volar\ncomo las águilas reales.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,145,145,"","",0,"rm_t3, palau_cantares, lafuente_madrid","","",5,0,0,[],""],["machado_venezuela-00382",10,"Dicen que el águila real\npasa la mar en un vuelo;\nmi amante también la pasa.\ntodas las noches en sueño.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,145,145,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00383",10,"Dicen que la brasa quema,\npero hay otra cosa peor:\nla brasa quema y se apaga,\nuna mala lengua nó.",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,145,145,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00384",10,"Dicen que los celos matan\nyo digo que no es así,\npues si los celos mataran\nte hubieran matado a ti.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,146,146,"","",0,"","","",6,0,0,[],""],["machado_venezuela-00385",10,"Dicen que mi amor es feo\ny que tiene mala cara:\na mí me parece un cielo;\nvaya el mundo enhoramala.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,146,146,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00386",10,"¿Qué importa que el pajarillo\ntenga la jaula de plata,\ny le quieran y le mimen\nsi la libertad le falta?",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,147,147,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00387",10,"Preso en la cárcel estoy,\nno te dé pena por eso,\nque no soy el primer preso\nni dejo de ser quien soy.",198,4,-1,-1,"",11,4,"o",112,0,-1,0,147,147,"","",0,"","","",9,0,0,[],""],["machado_venezuela-00388",10,"Decídmele al carcelero\nque me quite la cadena:\nque si el querer es delito\nmerece él la misma pena.",198,4,-1,-1,"",0,4,"ea",59,0,-1,0,147,147,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00389",10,"Ah, caramba, compañero,\ncomo no voy a llorar\nsi los grillos que me quitan\nme los vuelven a pegar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,148,148,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00390",10,"Prisiones de mis amores\nno me soltéis que me muero,\ntus brazos son los grilletes,\ntus ojos los carceleros.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,148,148,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00391",10,"El hombre que nació libre\ny buscó su cautiverio\nnada hace con llorar,\nlo que no tiene remedio.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,148,148,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00392",10,"Anda, vete al campo y llora:\nsi tienes por qué llorar,\nque por tu mala cabeza\nperdiste tu bienestar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,148,148,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00393",10,"No llores, vidita mía,\nno llores, que me da pena;\nllorarás cuando me veas\nprisionero en tierra ajena.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,148,148,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00394",10,"Quién pudiera con un llanto\nremediar un bien perdido,\no no haberla conocido\npara no sentirla tanto.",198,4,-1,-1,"",11,4,"ao",30,0,-1,0,149,149,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00395",10,"Ah, malhaya un toro bravo,\nah, malhaya un tigre cruel,\npara salir a un camino\ny tropezarme con él.",198,4,-1,-1,"",0,4,"e",32,0,-1,0,151,151,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00396",10,"Ah, malhaya un trago de agua\nde la quebrá de Aguanegra,\nun biscochuelo cubierto,\ny el beso de una morena.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,151,151,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00397",10,"Ah, malhaya un pajarito\nque volara más que el viento,\ny llevara mis suspiros\ndonde están mis pensamientos.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,152,152,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00398",10,"Ah, malhaya, quien la viera\ntres veces en la semana,\ny después volviera a verla\ndomingo por la mañana.",198,4,-1,-1,"",0,4,"aa",4,0,-1,0,152,152,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00399",10,"Ah, malhaya fuera yo\ncuenta de tu gargantilla,\nde tu cintura la faja,\nde tu zapato la hebilla.",198,4,-1,-1,"",0,4,"ia",162,0,-1,0,152,152,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00400",10,"Ah, malhaya una tortuga:\ny conchas de terecay\npara hacerle una peineta\na una paloma torcaz.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,152,152,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00401",10,"Ah, malhaya si me viera\ncontigo en el aposento,\nque se perdiera la llave,\ny el herrero hubiera muerto.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,153,153,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00402",10,"Ah, malhaya quien me dió\ntanto amor para quererte,\nque ahora para olvidarte\nmis penillas son de muerte.",198,4,-1,-1,"",0,4,"ee",134,0,-1,0,153,153,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00403",10,"Los negros y los zamuros\nson del mismo parecer:\nlos negros son maliciosos,\ny los zamuros también.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,155,155,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00404",10,"A los negros se conoce\nen lo largo del talón,\nen lo grueso de la boca\ny en el pelo chicharrón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,155,155,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00405",10,"Todos los negros son tristes,\ny causa su desconsuelo\nel que dijo San Benito\nque negro no sube al cielo.",198,4,-1,-1,"",0,4,"eo",10,0,-1,0,155,155,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00406",10,"Negros no hubo en la pasión,\nindio no se conocía,\nmulatos no los había:\nde blancos fue la función.",198,4,-1,-1,"",11,4,"o",31,0,-1,0,156,156,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00407",10,"Negra fue Santa Efigenia\nla madre de San Benito;\nnegros fueron los tres clavos\nconque clavaron a Cristo.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,156,156,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00408",10,"El que me dijere negro\nme pone santa corona,\nporque de negro se viste\nel Padre Santo de Roma.",198,4,-1,-1,"",0,4,"oa",-1,0,-1,0,156,156,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00409",10,"El que me dijere negro\nnegro tendrá el corazón,\nnegros su padre y su madre\ny toa su generación.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,156,156,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00410",10,"Me puse a bañar un negro\na ver que color cogía:\ncuanto más agua le echaba\nmás mojoso se ponía.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,156,156,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00411",10,"La negra que se echa polvo\ny viste de muselina\nparece troncón quemado\ncubierto con la ceniza.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,157,157,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00412",10,"La mujer que por locura\ntiene un negro por amante\naunque el sol esté radiante\nsiempre ve la casa oscura.",198,4,-1,-1,"",11,4,"ua",17,0,-1,0,157,157,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00413",10,"Todo blanco es embustero,\ntoda pulpero, ladrón,\ntodo negro pelo liso\ntiene muy mala intención.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,157,157,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00414",10,"Yo soy el negro Fabián\nnegro coquetón y vano,\nque te viene a enamorar\ncon la guitarra en la mano.",198,4,-1,-1,"",0,4,"ao",81,0,-1,0,157,157,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00415",10,"Yo soy el negrito chingo\nnariz de plan de batea,\nque me quieren las bonitas\ny me aborrecen las feas",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,157,157,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00416",10,"Queriendo estuve a una negra\nun verano y un invierno,\ny me parece que estuve\ndiez años en el infierno.",198,4,-1,-1,"",0,4,"eo",225,0,-1,0,158,158,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00417",10,"Entre lo negro y lo blanco\nlo mejor es lo moreno;\nde lo negro y de lo blanco\nse forma un color muy bueno.",198,4,-1,-1,"",1,4,"eo",76,0,-1,0,158,158,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00418",10,"Cuando un blanco está comiendo\nde un negro en la compañía,\no el blanco le debe al negro,\no es del negro la comía.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,158,158,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00419",10,"Aguaite, blanco, mi zamba\nes negra por la color,\npero pocas blancas tienen\ntan hermoso el corazón.",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,158,158,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00420",10,"Mi potro y mi zamba son\nlas dos cosas más queridas;\ny mi lanza y mi bridón\ntambién son mis preferidas.",198,4,-1,-1,"",1,4,"ia",279,0,-1,0,159,159,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00420-e2",10,"La zamba que Dios me ha dao\nes una zamba alesná,\nlo mismo arregla el almuerzo\nque cabalga mi alazán.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,159,159,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00420-e3",10,"Tengo una potranca oscura\nque de su sombra se espanta,\nen que mi zamba va al pueblo\na pasar Semana Santa.",198,4,-1,-1,"",0,4,"aa",148,0,-1,0,159,159,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00421",10,"El que se va de este mundo\nsin querer a una llanera,\nno tiene perdón de Dios\ny el mismo diablo lo espera.",198,4,-1,-1,"",0,4,"ea",44,0,-1,0,160,160,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00422",10,"El hombre que se muriere\nsin querer a una morena\nse va de este mundo al otro\nsin saber que es cosa buena.",198,4,-1,-1,"",0,4,"ea",59,0,-1,0,160,160,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00423",10,"Lo moreno lo hizo Dios,\nlo blanco lo hizo un platero,\nviva la gente morena\nque yo por moreno muero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,160,160,"","",0,"lafuente_madrid","","",6,0,0,[],""],["machado_venezuela-00424",10,"Moreno pintan a Cristo,\nmorena a la Magdalena,\nmoreno es el bien que adoro,\n¡viva la gente morena!",198,4,-1,-1,"",0,4,"ea",59,0,-1,0,160,160,"","",0,"palau_cantares, frenk_t1, andina_t1, lafuente_madrid, fernan_caballero","","",7,0,0,[],""],["machado_venezuela-00425",10,"Muchachas habrá bonitas,\npero no como la mía;\nesa la comparo yo\ncon el lucero del día.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,161,161,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00426",10,"Chiquitica y redondita\ncomo grano de cebada:\nsi así fueras tan bonita\ncomo eres enamorada.",198,4,-1,-1,"",1,4,"aa",49,0,-1,0,161,161,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00427",10,"Niña no pongas tu amor\ndonde no hay correspondencia,\nmira que te quedarás\na la luna de Valencia.",198,4,-1,-1,"",0,4,"ea",46,0,-1,0,161,161,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00428",10,"Prefiero que no me quieras\nsi no me lo has de probar,\nno me gusta la comida\nque no me puedo tragar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,162,162,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00429",10,"Cuenta como el mundo sabe\nque te empiezo a regalar;\nallá te mando un cambur\ncon dos granitos de sal.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,162,162,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00430",10,"Allá te mandé una piña\nen señal de matrimonio:\nsi no te casas conmigo\ndame mi piña, demonio.",198,4,-1,-1,"",0,4,"oo",169,0,-1,0,162,162,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00431",10,"Yo te quisiera querer\ny tu madre no me deja:\nen todo se ha de meter\nel demonio de la vieja.",198,4,-1,-1,"",1,4,"ea",165,0,-1,0,162,162,"","",0,"palau_cantares, lafuente_madrid","","",8,0,0,[],""],["machado_venezuela-00433",10,"Estas muchachas de ahora\nsi que usan buen peinao;\ndebajo de la crineja\ntienen el piojo a puñao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,163,163,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00434",10,"Estas muchachas de ahora\nyo le diré como son:\nAlegres para un fandango\ny tristes para un fogón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,163,163,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00435",10,"Las muchachas de Caracas\ntienen mucha fantasía;\ncamisones muy bonitos\ny la barriga vacía.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,163,163,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00436",10,"Las muchachas lugareñas\nno se pueden pretender,\nporque son muy pedigüeñas\ny falsas en el querer.",198,4,-1,-1,"",1,4,"e",20,0,-1,0,163,163,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00437",10,"Piensas que por tus enojos\nme he de sentar a llorar,\npues, como no sé quitarlos,\ncon ellos te quedarás.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,165,165,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00438",10,"Si piensas que tengo penas\nporque te casas con otro\ncomo ha tiempo no te quiero\neso me importa muy poco.",198,4,-1,-1,"",0,4,"oo",-1,0,-1,0,165,165,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00439",10,"Te quiero mucho, te dije,\ny a otro le diste el alma;\nese otro que tanto quieres\ncon otra mujer se casa.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,165,165,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00441",10,"He pasado en este mundo\nmuchas fatigas por ti,\npero ya ha llegado el día\nque tú las pases por mí.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,166,166,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00442",10,"Si quieres quererme, quiéreme\ny si nó; no me queráis,\nque yo quien me quiera tengo\ny nunca me ha de olvidar.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,166,166,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00443",10,"Cuando quise, no quisiste;\nhoy que quieres, yo no quiero;\npasarás la vida triste,\ncual yo la pasé primero.",198,4,-1,-1,"",1,4,"eo",38,0,-1,0,166,166,"","",0,"","","",8,0,0,[],""],["machado_venezuela-00444",10,"Me quisiste, yo te quise,\nme olvidaste, te olvidé,\nte pagaste de tu gusto\ny yo me pagué también.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,166,166,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00445",10,"Me quisiste, yo te quise,\nen otros brazos estás,\nni lloro, ni me lamento,\nque mujeres hay de más.",198,4,-1,-1,"",0,4,"a",51,0,-1,0,167,167,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00446",10,"No me quedas a deber\nni te tengo que pagar,\nsi yo te enseñé a querer\ntú me enseñaste a olvidar.",198,4,-1,-1,"",1,4,"a",21,0,-1,0,167,167,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00447",10,"Por este puño de cruces\nte he de decir la verdá,\nni te quiero, ni te estimo,\nni te tengo voluntá",198,4,-1,-1,"",0,4,"a",9,0,-1,0,167,167,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00448",10,"Si dices que no me quieres\nno me das pena maldita,\nque la mancha de la mora\ncon otra verde se quita.",198,4,-1,-1,"",0,4,"ia",50,0,-1,0,167,167,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00449",10,"Si dices que no me quieres,\nte digo: Dios te lo pague,\nque si una puerta se cierra\notras doscientas se abren.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,167,167,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00450",10,"Dios me ha dado un natural\nque me tiene muy contento:\nlo que he querido en un año\nen una hora lo aborrezco.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,168,168,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00451",10,"Si me quieren, sé querer,\nsi me olvidan, sé olvidar,\nsi traicionan mi cariño\ncon lo mismo sé pagar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,168,168,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00452",10,"Si la luna fuera tinta\ny el sol fuera escribidor\nte escribiera una cartica\ncon palabritas de amor.",198,4,-1,-1,"",0,4,"o",72,0,-1,0,169,169,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00453",10,"Cogí la pluma en la mano,\npuse el papel en la mesa,\npara escribirte una carta\ndulce, cariñosa y tierna.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,169,169,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00454",10,"En papel blanco te escribo\nporque blanca fue mi suerte;\nlos renglones separados\nporque de tí vivo ausente.",198,4,-1,-1,"",0,4,"ee",-1,0,-1,0,169,169,"","",0,"","","",7,0,0,[],""],["machado_venezuela-00455",10,"Papel, tú puedes llegar\nadonde no puedo ir,\na solas le has de decir\nque no la puedo olvidar.",198,4,-1,-1,"",11,4,"a",21,0,-1,0,170,170,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00455-e2",10,"Si tuviera pluma de oro\ncompraba papel de plata,\ny la sangre me sacaba\npara escribirte esta carta.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,170,170,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00455-e3",10,"Allá te mandé una carta,\nno la leas al revés;\nen cada esquina un abrazo,\ny un beso en cada doblez.",198,4,-1,-1,"",0,4,"e",150,0,-1,0,170,170,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00455-e4",10,"Carita de papel fino,\nnariz de pluma tajada,\nojos de letra menuda,\nboca de carta cerrada.",198,4,-1,-1,"",0,4,"aa",49,0,-1,0,170,170,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00455-e5",10,"No me escribas más tus cartas\nen papel blanco ¡traidora!\nporque el papel al mirarte\npor tu falta se sonroja.",198,4,-1,-1,"",0,4,"oa",-1,0,-1,0,170,170,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00456",10,"Si a tu ventana llegare\nun pajarito a cantar\nno lo mires con desdén\nporque de mi parte va.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,171,171,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00457",10,"Debajo de tu ventana\nayer me pusieron preso,\ny para mayor martirio\nme ataron con tu pañuelo.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,171,171,"","",0,"","","",29,0,0,[],""],["machado_venezuela-00458",10,"Ventanita, ventanita,\ndímele a la que te cierra\nque si se acuerda de mí\ncomo yo me acuerdo de ella.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,171,171,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00459",10,"Quítate de la ventana\ny óyeme un consejo, niña;\nmecate que no da al aire\nlos pájaros no lo pican...",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,172,172,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00460",10,"Muy malas son las coquetas,\npero son mucho más malas\nlas que hasta la media noche\nse quedan en la ventana.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,172,172,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00461",10,"En nombre de Dios comienzo\na retratar a mi dueño,\ndesde la punta del pie\nhasta el último cabello.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,173,173,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00462",10,"En la palma de mi mano\nvoy a poner tu retrato,\npara cuando estés ausente\nabrir la mano y mirarte.",198,4,-1,-1,"",5,4,"ae",-1,0,-1,0,173,173,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00463",10,"Eres chiquita y bonita:\nes así como te quiero;\nuna campanita de oro\nhecha del mismo platero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,173,173,"","",0,"","","",11,0,0,[],""],["machado_venezuela-00464",10,"Eres águila imperial\nque en el pinar se paró,\neres más linda que el alba\ncuando va a rayar el sol.",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,174,174,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00465",10,"Eres granito de oro\nperdido en un arenal;\ntus ojos son dos luceros,\ny tu boquita un coral.",198,4,-1,-1,"",0,4,"a",1,0,-1,0,174,174,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00466a",10,"Ayer te hallé dormidita\ny no quise despertarte:\nque despierta eres mujer,\ny dormida eres un angel.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,174,174,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00466b",10,"Los ojos de mi chávala\nson tan bonitos y bellos\nque no merecen que lloren\nsino que lloren por ellos.",198,4,-1,-1,"",0,4,"eo",137,0,-1,0,174,174,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00466c",10,"Tienes unos ojos bellos\nunos modos de mirar,\nunas cosas, unos dengues,\nque me hacen desesperar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,174,174,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00467",10,"Ojos negos y serenos\n¿por qué me miráis así?\nque a todos miran alegres\ny severos, sólo a mí.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,175,175,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00468",10,"Madre! madre! que me matan\ny no me puedo valer:\nson dos negros asesinos\nlos ojos de esa mujer.",198,4,-1,-1,"",0,4,"e",20,0,-1,0,175,175,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00469",10,"El Obispo de las Pampas\nha perdido una esmeralda,\ndale uno de tus ojitos\npa que repare la falta.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,175,175,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00470a",10,"Es tu boca de corales\nde aquellos más encarnaos:\n¡quién te pudiera besar\ny quedarse adormitao!",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,177,177,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00470b",10,"Pensando en ti me dormí\ny en sueños me parecía\nque tu boquita besaba\ny en mis brazos te oprimía.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,177,177,"","",0,"","","",7,0,0,[],""],["machado_venezuela-00471",10,"La muchacha que me dé\nun besito y un abrazo\nle prometo que me caso\nal mismo tener con qué.",198,4,-1,-1,"",11,4,"e",77,0,-1,0,177,177,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00472",10,"Con tus labios inocentes\nmedio piñón sujetabas,\ny el otro medio tratabas\nde ponerlo entre mis dientes.",198,4,-1,-1,"",11,4,"ee",252,0,-1,0,178,178,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00473",10,"Yo, con ademán travieso;\nel medio piñón corté\npero en cambio te dejé\nentre los labios un beso.",198,4,-1,-1,"",11,4,"eo",48,0,-1,0,178,178,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00474",10,"No te vayas a reir\npor lo que a decirte voy\npero dí: ¿No tienes hoy\notro piñón que partir?",198,4,-1,-1,"",11,4,"i",157,0,-1,0,178,178,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00475",10,"Dos besos tengo en el alma\nque no se apartan de mí:\nel último de mi madre\ny el primero que te dí.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,178,178,"","",0,"palau_cantares","","",2,0,0,[],""],["machado_venezuela-00476",10,"Las rosas tienen espinas\ncomo las tiene la palma;\ncomo las tienen los celos\nque me están hincando el alma.",198,4,-1,-1,"",0,4,"aa",125,0,-1,0,179,179,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00477",10,"Dicen que los celos matan\nyo digo que no es así:\nque si los celos mataran\nme hubieran matado a mí.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,179,179,"","",0,"lafuente_madrid, palau_cantares","","",6,0,0,[],""],["machado_venezuela-00478",10,"No quiero que a misa vayas,\nni a la ventana te asomes,\nni tomes agua bendita\ndonde la toman los hombres.",198,4,-1,-1,"",0,4,"oe",-1,0,-1,0,179,179,"","",0,"palau_cantares, lafuente_madrid","","",5,0,0,[],""],["machado_venezuela-00479",10,"Cansado estoy de decirte\nque no tengas amistad\nni con la luz que te alumbra,\nni con el sol que te da.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,180,180,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00480",10,"Tu madre muere de celos\nporque me diste una flor;\n! que celosas son las madres\npalomita de mi amor!",198,4,-1,-1,"",0,4,"o",72,0,-1,0,180,180,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00481",10,"Muere tu madre de celos\nporque conversas conmigo;\npero con verte y hablarte\nnada, mi vida, te quito.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,180,180,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00482",10,"¿De que le sirve a tu madre\nponer tranca en el corral,\nsi te has de venir conmigo\npor la puerta principal?",198,4,-1,-1,"",0,4,"a",1,0,-1,0,180,180,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00483",10,"Acordarme no quisiera\nde aquellos tiempos pasaos\nde cuando gozé tu gloria,\ntiempos como te han mudao.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,181,181,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00484",10,"Acuérdate de que en un tiempo\nle diste palabra a un triste,\nrecorre tu pensamiento,\ncumple lo que prometiste.",198,4,-1,-1,"",0,4,"ie",153,0,-1,0,181,181,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00485",10,"Acuérdate que dijiste\nque primero habías de ver\nlas estrellas en el suelo\nque dejarme de querer.",198,4,-1,-1,"",0,4,"e",20,0,-1,0,181,181,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00486",10,"Acuérdate que pusiste\ntus manos sobre las mías,\ny llorando me dijiste\nque jamás me olvidarías.",198,4,-1,-1,"",1,4,"ia",214,0,-1,0,182,182,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00487",10,"¿Hasta cuándo padecer?\nmira que no soy de bronce:\nlas peñas con ser las peñas\nunas con otras se rompen.",198,4,-1,-1,"",0,4,"oe",-1,0,-1,0,182,182,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00488",10,"Quien pudiera con un llanto\nrestaurar un bien perdido;\npara tan grande dolor\nmás vale no haber nacido.",198,4,-1,-1,"",0,4,"io",101,0,-1,0,182,182,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00490",10,"Una pena y otra pena,\nun dolor y otro dolor,\nun clavo saca otro clavo\npero no el clavo de amor.",198,4,-1,-1,"",0,4,"o",72,0,-1,0,182,182,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00491",10,"Las penas que me maltratan\nson tántas que se atropellan\nuna con otra se amellan,\ny por eso no me matan.",198,4,-1,-1,"",11,4,"aa",399,0,-1,0,183,183,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00492",10,"Cuántas veces yo me acuerdo\nque la tuve y la perdí...\nno la perdí porque quise\nni porque cobarde fui.",198,4,-1,-1,"",0,4,"i",23,0,-1,0,183,183,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00493",10,"Pensamiento, estate quieto;\nmemoria, déjame estar;\nsi la quise o no la quise.\nno hay para qué recordar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,183,183,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00494",10,"A una piedra de la calle\nle conté un día mi dolor.\ncuántas cosas le diría\nque la piedra se partió.",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,183,183,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00495",10,"Para mí ya se acabaron\nlos placeres y los gustos;\nlas calles por donde andaba\nestán vestidas de luto.",198,4,-1,-1,"",0,4,"uo",-1,0,-1,0,183,183,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00496",10,"Ojos míos, no lloréis;\nlágrimas, tened paciencia:\nel que nace desgraciado\ndesde chiquitico empieza.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,184,184,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00497",10,"Cada existencia es un libro\nque a toda prisa se estampa;\n¡cuánto daríamos todos\npor corregir sus erratas!",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,185,185,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00498",10,"Esta vida es un misterio;\nuna completa mudanza:\nando buscando una vega\nen que nazca la esperanza.",198,4,-1,-1,"",0,4,"aa",163,0,-1,0,185,185,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00499",10,"Nacemos entre sollozos\ny entre lágrimas morimos.\n¿Si no hay placer para el hombre\npor qué a este mundo vinimos?",198,4,-1,-1,"",0,4,"io",329,0,-1,0,185,185,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00500",10,"Lágrimas en el rocío,\nen el mar y en las montañas,\n¿qué es la tierra para el hombre\nsino un vasto mar de lágrimas?",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,186,186,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00501",10,"Cada vez que considero\nque me tengo que morir\nalzo los ojos al cielo:\n¡Dios mío, por qué nací!",198,4,-1,-1,"",0,4,"i",-1,0,-1,0,186,186,"","",0,"","","",14,0,0,[],""],["machado_venezuela-00502",10,"Cada vez que yo me acuerdo\nque el mundo se ha de acabar,\ncada vez que yo me acuerdo...\n¡no me quisiera acordar!",198,4,-1,-1,"",1,4,"a",21,0,-1,0,186,186,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00503",10,"Pensando en la muerte estoy\ny sé que me he de morir:\npero no te sé decir\nsi será mañana u hoy.",198,4,-1,-1,"",11,4,"o",112,0,-1,0,186,186,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00504",10,"La ilusión nace con alas\ny apenas nacida, vuela;\nel desengaño es de plomo\ny donde nace, se queda.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,186,186,"","",0,"palau_cantares","","",2,0,0,[],""],["machado_venezuela-00505",10,"Estoy tan hecho a la pena\nque cuando sin ella estoy\nme parece que me falta\nde la vida lo mejor.",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,187,187,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00506",10,"¿Oyes el triste suspiro\nque lanza mi corazón?\n¡es que la dicha se ahuyenta,\nes que se acerca el dolor!",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,187,187,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00507",10,"Tristezas me ponen triste,\ntristezas salgo a buscar\npara ver si con tristezas\ntristezas puedo,olvidar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,187,187,"","",0,"rm_t3","","",2,0,0,[],""],["machado_venezuela-00508",10,"Quisiera pero no puedo\nhacer mi casa en el aire,\npara el día en que me muera\nno darle que hacer a nadie.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,187,187,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00509",10,"No hay quien levante al caído,\nni quien la mano le dé;\nal que toca la desgracia\ntodos se apartan de él.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,187,187,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00510a",10,"Más vale saber que haber,\ndijo un sabio, y lo probó:\nel sabio puede ser rico,\npero el rico, sabio, nó.",198,4,-1,-1,"",0,4,"o",2,0,-1,0,188,188,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00510b",10,"Sin querer estoy amando,\ny sin amar, padeciendo,\neste es un vivir penando\nque yo mismo no lo entiendo.",198,4,-1,-1,"",1,4,"eo",52,0,-1,0,188,188,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00510c",10,"Quien tuviera una baraja\npara jugar treinta y uno\nah, trabajo que es querer\ny que no quieran a uno.",198,4,-1,-1,"",0,4,"uo",-1,0,-1,0,188,188,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00510d",10,"El guariqueño no sabe\ncuanto puede una creciente;\nni las vueltas que da un tronco\nllevado por la corriente.",198,4,-1,-1,"",0,4,"ee",15,0,-1,0,188,188,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00511",10,"Regálame una mascada,\nno me digas que no tienes;\nlo que no es hoy es mañana,\nlo que no se espera, viene.",198,4,-1,-1,"",0,4,"ee",-1,0,-1,0,188,188,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00512",10,"Dice un pájaro cantando\npor no dejar que decir:\nmás vale morir cantando\nque no cantando morir.",198,4,-1,-1,"",1,4,"i",157,0,-1,0,189,189,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00513",10,"Hay gentes muy convencidas\nde que uno y uno son dos:\nuna mujer y un hombre\no son uno o nada son.",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,189,189,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00514",10,"El indio con sus raíces\ny el viejo con su experiencia\nson, y serán, sin disputa,\nmás cientistas que la ciencia.",198,4,-1,-1,"",0,4,"ea",46,0,-1,0,189,189,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00515",10,"Quesero que vende el queso\nsin que a su amo le aproveche,\ny de pobre pasa a rico\n¿de dónde sacó esa leche?",198,4,-1,-1,"",0,4,"ee",180,0,-1,0,189,189,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00516",10,"En el pueblo de no sé donde\ncelebran no sé que santo,\nle rezan yo no sé qué\nle pagan, yo no sé cuánto.",198,4,-1,-1,"",0,4,"ao",30,0,-1,0,190,190,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00517",10,"De negro viste la viuda,\nde amarillo la casada,\nde azul viste la doncella,\nde verde la enamorada.",198,4,-1,-1,"",0,4,"aa",49,0,-1,0,190,190,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00518",10,"Te vestiste de amarillo.\npara que no te quisiera,\nlo amarillo es lo que luce,\nnace el verde donde quiera.",198,4,-1,-1,"",0,4,"ea",44,0,-1,0,190,190,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00519",10,"Verde fue mi nacimiento,\namarillo mi vivir,\nque de negro me amortajen\ncuando me vaya a morir.",198,4,-1,-1,"",0,4,"i",157,0,-1,0,190,190,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00520",10,"A ningún amante viejo\nle des posada en tu casa,\nporque es facil de prender\nel carbón que ha sido brasa.",198,4,-1,-1,"",0,4,"aa",123,0,-1,0,191,191,"","",0,"andina_t1","","",3,0,0,[],""],["machado_venezuela-00522",10,"Mujeres, jilen y cosan,\nno se atengan a los hombres,\nque el que no tiene camisa\nno puede dar camisones.",198,4,-1,-1,"",0,4,"oe",-1,0,-1,0,191,191,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00523",10,"Ninguna aunque sea bonita,\nse atenga a su bonitura,\naténgase a su dedal,\ny a su canasto e costura.",198,4,-1,-1,"",0,4,"ua",17,0,-1,0,192,192,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00524",10,"Atente a lo que te den\ny no hagas diligencia;\nel que tiene come bien,\ny el que no tiene...paciencia.",198,4,-1,-1,"",1,4,"ea",46,0,-1,0,192,192,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00526",10,"Al que te pidiere, dale,\nque tendrá necesidá;\nal que tiene se le acaba,\ny el que no tiene, tendrá.",198,4,-1,-1,"",0,4,"a",9,0,-1,0,192,192,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00527",10,"No escupas nunca pa arriba:\nes una verdad muy clara,\nel que para arriba escupe\nluego le cae en la cara.",198,4,-1,-1,"",0,4,"aa",57,0,-1,0,192,192,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00528",10,"Nadie descubra su pecho\npor dar alivio a su pena,\nque el que su pecho descubre\npor su boca se condena.",198,4,-1,-1,"",0,4,"ea",59,0,-1,0,193,193,"","",0,"rm_t4, palau_cantares, andina_t2, lafuente_madrid","","",5,0,0,[],""],["machado_venezuela-00529",10,"Si quieres que te maltraten\ndi que te duele, cariño,\nque todo el mundo se goza\ncon el dolor del vecino.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,193,193,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00530",10,"En asuntos de amoríos\nno mezcles a otra persona,\nporque cargan muchas veces\ncon el santo y la limosna.",198,4,-1,-1,"",0,4,"oa",-1,0,-1,0,193,193,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00531",10,"Mi madre me dió un consejo,\ncomo consejo de madre:\nque a las muchachas bonitas\nno las hiciera comadres.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,193,193,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00532",10,"Mi madre me aconsejó\ny me lo dijo mi abuela:\nquien tenga rabo de paja\nno se arrime a la candela.",198,4,-1,-1,"",0,4,"ea",167,0,-1,0,193,193,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00533a",10,"Mi madre me dio un consejo\nque el cielo le premiará:\nque enamorase a las feas\nque es obra de caridad.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,194,194,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00534",10,"El que corteja y no sabe\nla cuerda que ha de tocar,\npor más sacristán que sea\nnunca llega a repicar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,194,194,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00535",10,"Como quieres que una luz\nalumbre dos aposentos.\n¿Cómo quieres que yo quiera\na dos mujeres a un tiempo?",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,194,194,"","",0,"","","",7,0,0,[],""],["machado_venezuela-00536",10,"Dos cosas hay en el mundo\nque nunca tienen buen fin:\nmuchacho que bebe vino\ny mujer que habla latín.",198,4,-1,-1,"",0,4,"i",211,0,-1,0,195,195,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00537",10,"Dos cosas hay en el mundo\nque no he podido creer:\nen la cojera del perro\ny en lágrimas de mujer.",198,4,-1,-1,"",0,4,"e",20,0,-1,0,195,195,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00538",10,"Dos cosas buscaba el Dante\npara escribir su comedia:\nla cara del tuerto Infante\ny al doctor Torrealba Heredia.",198,4,-1,-1,"",3,4,"ea",666,0,-1,0,195,195,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00539",10,"La mujer para bonita\nha de ser alta y delgada;\nel agua para beber\nha de ser de la quebrada.",198,4,-1,-1,"",0,4,"aa",49,0,-1,0,196,196,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00540",10,"La mujer para ser buena\ntres cosas debe tener:\nbuena pierna, buenos ojos\nbuen cachete que morder.",198,4,-1,-1,"",0,4,"e",20,0,-1,0,196,196,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00541",10,"El caballo para bueno\ndebe ser rucio mosqueado;\ny el hombre para ser guapo\ndebe estar enamorado.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,196,196,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00542",10,"El hombre para ser hombre\ntres cosas ha de tener:\nbuen garrote, buen cuchillo\nbuenas piernas pa corré.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,196,196,"","",0,"","","",7,0,0,[],""],["machado_venezuela-00543",10,"Tres cosas hay en el mundo\nque no me atrevo a guardar:\ncasa con puerta en el fondo,\nmujer y cañaveral.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,196,196,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00544",10,"Tres jueves hay en el año\nde eterna veneración:\nJueves Santo, Corpus Cristi\ny Jueves de la Ascención.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,197,197,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00545",10,"En el cielo manda Dios,\nlos diablos en el infierno,\ny en este pícaro mundo\nel que manda es el dinero.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,199,199,"","",0,"rm_t4, palau_cantares, lafuente_madrid","","",8,0,0,[],""],["machado_venezuela-00546",10,"En la puerta principal\ndel Infierno, hay un letrero,\nque dice, con letras grandes:\nPor aquí los majaderos!",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,199,199,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00547",10,"Sarampión, toca a la puerta,\nlechina, mira quien es;\nsi es mi comadre viruela\ndile que vuelva después.",198,4,-1,-1,"",0,4,"e",218,0,-1,0,199,199,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00548",10,"Voy a comprar un puñal\nde punta acerada y fuerte\npara matar a la muerte\ncuando me venga a buscar.",198,4,-1,-1,"",5,4,"a",-1,0,-1,0,200,200,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00549",10,"Pasé por el Campo-Santo\ny vi la muerte en camisa:\ny a las ánimas benditas\nque ya se morían de risa.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,200,200,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00550",10,"Cada vez que paso y miro\nla puerta del Campo-Santo\nle digo a mi cuerpecito:\naquí será tu descanso.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,200,200,"","",0,"","","",24,0,0,[],""],["machado_venezuela-00551",10,"No sé que tienen las flores\nque están en el cementerio;\nparece que están rezando\nal moverse con el viento.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,200,200,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00552",10,"Junto de aquella laguna\nadonde se eleva un sauce\nenterrado dejé un día\nel cadáver de mi madre.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,200,200,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00553",10,"Dios, de los niños que nacen,\ncruzan el mundo, y se van,\nforma los ángeles bellos\nde la corte celestial.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,201,201,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00554",10,"Pasé por el purgatorio\ny vi la mar de las penas;\npero vi que por querer\nningún alma se condena.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,201,201,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00555a",10,"Así como toda planta\nnecesita de rocío,\nyo necesito, bien mío,\ncon qué aclarar la garganta.",198,4,-1,-1,"",11,4,"aa",148,0,-1,0,203,203,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00555b",10,"De las uvas sale el vino,\ndel vino, la fortaleza,\nde la mujer, la palabra,\ny del hombre, la firmeza.",198,4,-1,-1,"",0,4,"ea",108,0,-1,0,203,203,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00556",10,"El catón de San Casiano\nempieza por Baso y Beba;\ny cuando yo me emborracho\nse pone brava mi suegra.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,203,203,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00557",10,"Anoche dormí en el suelo\nteniendo tan buena cama.\n¿quien tiene la culpa de esto?\nel aguardiente de caña.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,204,204,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00558",10,"El aguardiente de caña\nes de tanta fortaleza\nque lo echan pa la barriga\ny se va pa la cabeza.",198,4,-1,-1,"",0,4,"ea",108,0,-1,0,204,204,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00559",10,"Tu cuerpo es un alambique,\nlo que sudas, aguardiente;\nsi por eso te critican\npara tí es indiferente.",198,4,-1,-1,"",0,4,"ee",15,0,-1,0,204,204,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00560",10,"Borracho con rial no estorba;\nel refrán es verdadero;\npor eso cuando me chispo\nlleno de rial el sombrero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,204,204,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00561",10,"Todo el que bebe aguardiente,\nsegún un doctor muy sabio,\nha de morir de repente\ncon el estómago hinchao.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,204,204,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00562",10,"Decía al estar borracha,\nla zamba Juana Quilina:\nno se admite cucaracha\nen los bailes de gallina.",198,4,-1,-1,"",1,4,"ia",11,0,-1,0,205,205,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00563",10,"Seguro no saca piojos,\nni garabato cangrejos;\nveguero no pone tienda,\nni borracho escupe lejos.",198,4,-1,-1,"",0,4,"eo",149,0,-1,0,205,205,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00564",10,"Beber aguardiente puro\nmandan las antiguas leyes,\nque beban agua los bueyes\nque tienen el cuero duro.",198,4,-1,-1,"",11,4,"uo",248,0,-1,0,205,205,"","",0,"carrizo_salta","","",2,0,0,[],""],["machado_venezuela-00565",10,"Si quieres saber, señora,\nla virtud del aguardiente;\na los mudos hace hablar,\ny a los cobardes, valiente.",198,4,-1,-1,"",0,4,"ee",15,0,-1,0,205,205,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00566",10,"Yo no bebo el aguardiente\nporque luego me marea;\ndigo, no bebo en totuma\npara beber lo en batea.",198,4,-1,-1,"",0,4,"ea",54,0,-1,0,205,206,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00568",10,"Me gusta un trago de ron\nmás que muchacha bonita,\nporque el ron siempre me quita\nlas penas del corazón.",198,4,-1,-1,"",11,4,"o",31,0,-1,0,206,206,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00569",10,"Ah trabajo que es ser pobre!\nlo digo por mi pobreza;\nme puse a tejer sombreros...\nninguno tuvo cabeza.",198,4,-1,-1,"",0,4,"ea",108,0,-1,0,207,207,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00570",10,"Esta es la pura verdad,\nesto es lo que se empaqueta,\npor eso dice el refrán:\nEl pobre no salga a fiestas.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,207,207,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00571",10,"A las orillas de un río\nme puse a considerar\nlo poco que vale un hombre\ncuando no tiene que dar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,207,207,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00572",10,"Tengo el sombrero rompío\ndesde la copa hasta el ala,\ny no lo quiero coser\nhasta no ver en qué para.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,208,208,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00573",10,"Pantalones, yo no tengo,\ncamisa, no la conozco,\nenamorado perdido\nestoy que me vuelvo loco.",198,4,-1,-1,"",0,4,"oo",-1,0,-1,0,208,208,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00574",10,"Vivir como vive el pobre\nen eterno samplegorio,\nes pagar, anticipadas\nlas penas del purgatorio.",198,4,-1,-1,"",0,4,"oo",551,0,-1,0,208,208,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00575",10,"A mí mismo me da pena\nde verme tan arrastrao,\nes cuestión de mala suerte\nque aunque pobre, soy honrao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,208,208,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00576",10,"Cuando voy donde mi amada\ndoy una vuelta, y me miro,\ny al pensar en mi pobreza\nme devuelvo del camino.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,208,208,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00577",10,"Hombre pobre no enamora,\ny es muy facil la razón;\nhombre pobre y leña verde\nno calientan el fogón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,209,209,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00578",10,"Hombre pobre no enamora,\nla razón lo anda diciendo:\neí que no tiene que dar\nmal puede llegar pidiendo.",198,4,-1,-1,"",0,4,"eo",52,0,-1,0,209,209,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00579",10,"Hombre pobre enamorao\nes gallo tuerto, sin cola,\nque le dan un aletazo\ny queda ciego de bola.",198,4,-1,-1,"",0,4,"oa",321,0,-1,0,209,209,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00580",10,"El amor del hombre pobre\nes como el del gallo enano\nque en correr y no alcanzar\nse la pasa todo el año.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,209,209,"","",0,"","","",6,0,0,[],""],["machado_venezuela-00581",10,"El amor del hombre pobre\nes como el de las gallinas,\nque en faltándoles el gallo\na cualquier pollo se arriman.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,209,209,"","",0,"","","",6,0,0,[],""],["machado_venezuela-00582",10,"Cuando un pobre se enamora\ny un rico se le atraviesa\nsale el pobre por la puerta\nrascándose la cabeza.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,210,210,"","",0,"","","",3,0,0,[],""],["machado_venezuela-00583",10,"Si por pobre me desprecias\ndigo que tienes razón:\nhombre pobre y leña verde\narden cuando hay ocasión.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,210,210,"","",0,"rm_t3","","",7,0,0,[],""],["machado_venezuela-00584",10,"Siempre mi madre decía\nen el más sentido tono:\nhombre pobre hiede a mono;\nno hay que dejarlo acercar.",198,4,-1,-1,"",5,4,"a",-1,0,-1,0,210,210,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00585",10,"Anda, vé, dile a tu madre,\nsi me desprecia por pobre\nque el mundo da muchas vueltas,\nque ayer se cayó una torre.",198,4,-1,-1,"",0,4,"oe",-1,0,-1,0,210,210,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00586",10,"Todo el que tiene dinero\nbrinca adelante y atrás;\ny yo, como no lo tengo,\nbrinco adelante no más.",198,4,-1,-1,"",0,4,"a",51,0,-1,0,210,210,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00587",10,"Todo el que tiene dinero\ntiene la sangre liviana,\naunque su padre sea un tigre\ny su madre una caimana.",198,4,-1,-1,"",0,4,"aa",4,0,-1,0,211,211,"","",0,"andina_t1","","",4,0,0,[],""],["machado_venezuela-00588",10,"Todo el que tiene dinero\ntiene la sangre dulcita,\naunque su padre sea el diablo\ny su madre una diablita.",198,4,-1,-1,"",0,4,"ia",50,0,-1,0,211,211,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00589",10,"Cuando yo tenga dinero\nloco me voy a volver;\nque ya tengo el elemento\npa yo quererme, y querer.",198,4,-1,-1,"",0,4,"e",20,0,-1,0,211,211,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00590",10,"En un tiempo tuve, tuve...\npero ya se me acabó:\ny he quedado como aquél\nque tuvo vista y cegó.",198,4,-1,-1,"",0,4,"o",2,0,-1,0,211,211,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00591",10,"Grandeza cual la de Dios\nla del Espíritu Santo,\ninfinito, sabio, eterno\nGran Misterio Sacrosanto.",198,4,-1,-1,"",0,4,"ao",30,0,-1,0,213,213,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00592",10,"Por divino adoro a Dios,\ny lo adoro por perfecto:\npor bondadoso le amo,\npor justiciero le temo.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,213,213,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00593",10,"A un Santo Cristo de bronce\nmis penas le conté yo,\ny como serían de amargas\nque el Santo Cristo lloró.",198,4,-1,-1,"",0,4,"o",2,0,-1,0,213,213,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00594",10,"Mañana por la mañana\nriega tu patio de flores\nque te viene a visitar\nla Virgen de los Dolores.",198,4,-1,-1,"",0,4,"oe",5,0,-1,0,214,214,"","",0,"","","",11,0,0,[],""],["machado_venezuela-00595",10,"Mi vida, si vas al templo\npor mí rogarás a Dios,\nque tus penas y mis penas.\nson hermanitas las dos.",198,4,-1,-1,"",0,4,"o",87,0,-1,0,214,214,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00596",10,"Cuando te encuentro rezando\ny miro tu devoción\nlos celos me están matando,\nprenda de mi corazón.",198,4,-1,-1,"",1,4,"o",31,0,-1,0,214,214,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00597",10,"Si el amor que puse en ti\ntan firme y tan verdadero\nlo hubiera puesto en mi Dios,\nhubiera ganado el cielo.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,214,214,"","",0,"carrizo_salta","","",3,0,0,[],""],["machado_venezuela-00598",10,"Si sabes los Mandamientos,\nel primero es el amar:\ncúmplelo, vidita mía,\ncon este pobre galán.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,214,214,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00599",10,"Es tánto lo que te quiero,\ny lo que te quiero, tánto,\nque el día en que no te veo\nno le rezo a ningún santo.",198,4,-1,-1,"",0,4,"ao",30,0,-1,0,215,215,"","",0,"","","",26,0,0,[],""],["machado_venezuela-00600",10,"Ni contigo ni sin ti\ntienen mis penas remedio:\ncontigo porque me matas\ny sin ti porque me muero.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,215,215,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00601",10,"Si me miras, me maltratas;\nsi no me miras, me muero;\ny si no me das el sí\npronto hasta morirme quiero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,215,215,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00602",10,"Un collar llevas al pecho,\npendiente de él una cruz,\nservirá para mi tumba\ncuando me falte la luz.",198,4,-1,-1,"",0,4,"u",109,0,-1,0,215,215,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00603",10,"De cuando te persignaste\nmis ojos fueron testigos:\nquien te pudiera besar\ndonde dices Enemigos.",198,4,-1,-1,"",0,4,"io",648,0,-1,0,215,215,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00604",10,"Quisiera hacerte un regalo\ncon la luna y los luceros,\npero me falta la escala\npara subir a las cielos.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,216,216,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00605",10,"Bendito sea Dios, caramba!\nque mala fortuna tengo;\ntodos conversan contigo\ny yo con mirar te ofendo.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,216,216,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00606",10,"Por ti me olvidé de Dios,\npor ti la gloria perdí,\ny ahora me voy a quedar,\nsin Dios, sin gloria y sin tí.",198,4,-1,-1,"",3,4,"i",23,0,-1,0,216,216,"","",0,"rm_t3","","",3,0,0,[],""],["machado_venezuela-00607",10,"Mi vida, si es que me quieres\nno se lo digas a nadie;\nlos secretos de tú y yo\nvan y vienen por el aire.",198,4,-1,-1,"",0,4,"ae",-1,0,-1,0,216,216,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00608",10,"Desde mi tierra he venido\ncon el agua a la garganta,\nsólo por venir a verte\nhermosa paloma blanca.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,216,216,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00609",10,"Traigo cien pesos en oro\ny un potro que es novedá;\ntan sólo me faltas tú\npara completar mi ajuar.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,217,217,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00609-e2",10,"Si yo me hubiera aprendido\nlos libros del padre cura\nhubiera asombrado al mundo\ncon lo escrito por mi pluma.",198,4,-1,-1,"",0,4,"ua",-1,0,-1,0,217,217,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00609-e3",10,"No se vaya, señor cura,\nque ya el sancocho va a estar;\ntiene yuca, tiene ñame,\ntiene batata moráa.",198,4,-1,-1,"",5,4,"aa",-1,0,-1,0,217,217,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00609-e4",10,"Un cura socaliñero\ndecía para su sayo\nque los velorios en mayo\nson bautizos en enero.",198,4,-1,-1,"",11,4,"eo",38,0,-1,0,217,217,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00610",10,"Señores los bailadores\nles voy a leer un bando:\nEl que no tenga dinero\npuede irse retirando.",198,4,-1,-1,"",0,4,"ao",33,0,-1,0,219,219,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00611",10,"Niña, buena bailadora,\npréstame tu relicario\npa ponérmelo en el pecho\npa que no me lleve el diablo.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,219,219,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00612",10,"Que bonito paso doble\nbailan las sanfelipeñas,\npero más bonito bailan\ncuando van por agua y leña.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,219,219,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00613",10,"En aquella loma arriba\nestá una vieja gritando\nporque la tiene un bejuco.\npor la papera bailando.",198,4,-1,-1,"",0,4,"ao",33,0,-1,0,220,220,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00614",10,"Muchas gracias, caballero,\nel que me obsequió el cuartillo,\nque a caballo regalado\nno se le mira el colmillo.",198,4,-1,-1,"",0,4,"io",228,0,-1,0,220,220,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00615",10,"Nosotros semos tuyeros\nde Yare y Santa Lucía,\ncantamos a todas horas\npues semos de buena cría.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,221,221,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00616a",10,"No le negamos el vicio\na las músicos llaneros,\nen el Tuy toos semos negros\npero semos caballeros.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,221,221,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00616b",10,"Nosotros nunca salimos\na cantar en patio ageno,\nni mendigamos pesetas\npor tenerlo muy a menos.",198,4,-1,-1,"",0,4,"eo",-1,0,-1,0,221,221,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00617",10,"Nosotros ganamos real\nmacaneando un callejón,\nno acostados en chinchorros\ny comiendo requesón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,222,222,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00618",10,"Que se vengan para el Tuy\na jalar una escardilla,\na doblarse sobre un pico\npara plantar la semilla.",198,4,-1,-1,"",0,4,"ia",162,0,-1,0,222,222,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00619",10,"Y no anden haciendo bulla\ncon su cuatro destemplao\nporque pueden tropezarse\ncon un ñaure encabullao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,222,222,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00620",10,"Si mis suspiros volaran\ncomo vuelan las abejas\n¡cuántos enjambres irían\ndonde quiera que tú fueras!",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,223,223,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00621",10,"Si las aves y las brisas\nfueran buenas mensajeras\ncon ellas siempre te enviara\nmis suspiros y mis quejas.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,223,223,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00622",10,"Suspiro que de mí salga\ny los que de ti saldrán,\nsi en el camino se encuentran\n¡qué de cosas se dirán!",198,4,-1,-1,"",0,4,"a",147,0,-1,0,223,223,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00623",10,"Un ciego halló una colmena\ny un manco la fue a sacar,\nun cojo salió corriendo\na buscar en qué aparar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,225,225,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00624",10,"Un ciego estaba mirando\ncomo se quema una casa,\nun mudo llamaba gente,\ny un cojo llevaba el agua.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,225,225,"","",0,"lafuente_madrid, palau_cantares","","",4,0,0,[],""],["machado_venezuela-00625",10,"Un calvo se encontró un peine,\nlo miraba y remiraba,\ny no pudo descubrir\nque aplicación se le daba.",198,4,-1,-1,"",0,4,"aa",28,0,-1,0,225,225,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00626",10,"Yo vi una pelona crespa,\nyo vi un calvo bien peinao,\nyo vi un muerto que lloraba\ncon el resuello parao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,226,226,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00627",10,"Yo vide un barco en La Vela\ny un marinero en la popa\nque navegaba hacia Suiza\nregresando de Polonia",198,4,-1,-1,"",0,4,"oa",-1,0,-1,0,226,226,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00628",10,"Yo vide un caimán barroso,\nun terecay alazano;\nyo vide un zapo parao\ncon un bastón en la mano.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,226,226,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00629",10,"En la sabana de paja\nme cayó un invierno de agua,\ncomiéndome un queso e leche\ncon un papelón de caña.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,226,226,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00630",10,"Negro soy como la leche,\nblanco como el cigarrón,\ncorronchoso como el bagre,\nliso como el cascarrón.",198,4,-1,-1,"",0,4,"o",31,0,-1,0,226,226,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00631",10,"Quítate de esa vergüenza\ncara de poca ventana,\ny dame un vaso de sed\nque me estoy muriendo de agua.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,227,227,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00632",10,"De las alas de un mosquito\nhizo mi moreno un manto\ny le salió tan bonito\nque lo estrenó el Viernes Santo.",198,4,-1,-1,"",1,4,"ao",30,0,-1,0,227,227,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00633",10,"En la sabana de El Morro\nsuspiraba un morrocoy,\ny en el suspiro decia:\natájenme, que me voy.",198,4,-1,-1,"",0,4,"o",112,0,-1,0,227,227,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00634",10,"En esos llanos abajo\nsuspiraba una ballena,\ny en el suspiro decía:\n¡ah, malhaya, quien pudiera!",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,227,227,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00635",10,"Yo me fuí para los Llanos\na aprender a ginetear:\nme monté en un burro muerto\ny no me pudo tumbar.",198,4,-1,-1,"",0,4,"a",21,0,-1,0,227,227,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00636",10,"Yo miré una garza blanca\ndándole combate al río;\nasí está tu corazón\ndándole combate al mío.",198,4,-1,-1,"",0,4,"io",3,0,-1,0,228,228,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00637a",10,"Galerón por la mañana,\ngalerón a mediodía,\ngalerón a todas horas\ncomo si fuera comía.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,229,229,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00637b",10,"Galerón no come carne\nque lo que come es gallina,\ngalerón es caballero\nde la ciudad de Barinas.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,229,229,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00638",10,"Guabina le dijo a bagre:\nvámonos al caramero,\nporque ya suena el clarín\ny nos coje el chinchorrero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,229,230,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00640",10,"Amor que se va no vuelve\ny si vuelve es lisonjero,\nporque nunca puede ser\nlo que antes era el primero.",198,4,-1,-1,"",0,4,"eo",38,0,-1,0,230,230,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00641",10,"Dicen que la miel es dulce\ny también el tamarindo;\nyo no sé por qué a los negros\nles gusta fumar cachimbo.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,231,231,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00642",10,"Me puse a echar unos huevos\nde una polla primeriza;\ntoda mujer bailadora\ntiene las espaldas lisas.",198,4,-1,-1,"",0,4,"ia",-1,0,-1,0,231,231,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00643",10,"La mujer que se enamora\ndel hombre que no la quiere\nmerece cincuenta palos\ncantándole el Miserere.",198,4,-1,-1,"",0,4,"ee",115,0,-1,0,231,231,"","",0,"","","",5,0,0,[],""],["machado_venezuela-00644",10,"Las mujeres de'mi tierra\nson bonitas cual diamante,\npero pobre faltriquera\nla que cojan por delante.",198,4,-1,-1,"",0,4,"ae",47,0,-1,0,232,232,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00645",10,"Si los besitos salieran\ncomo sale el perejil,\nmás de una niña tuviera\nla cara como un jardín.",198,4,-1,-1,"",0,4,"i",-1,0,-1,0,232,232,"","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],""],["machado_venezuela-00646",10,"Que alta que va la nube\ny el viento la revolea;\nque sabroso no asentara\nen tu lomo una correa.",198,4,-1,-1,"",0,4,"ea",54,0,-1,0,232,232,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00647",10,"No es por el que murió\nque dobla aquella campana,\nes para que sepa yo\nque me he de morir mañana.",198,4,-1,-1,"",1,4,"aa",4,0,-1,0,232,232,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00648",10,"Ya para mí se acabó\nla pompa y la vanidad;\nen el mundo todo es falso,\nsólo la muerte es verdad.",198,4,-1,-1,"",0,4,"a",16,0,-1,0,232,232,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00649",10,"Quien fuera como la vela\nque se acaba en el servicio,\ny acabándose la vela\nse acaban los beneficios.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,233,233,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00650",10,"No te acuestes en chinchorro\nsin mirar los colgaderos,\nni duermas en la posada\nen unión de forasteros.",198,4,-1,-1,"",0,4,"eo",22,0,-1,0,235,235,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00651",10,"Acostúmbrate a dormir\ncon un ojo siempre abierto\nque el pillo que así te viere\nte considera despierto.",198,4,-1,-1,"",0,4,"eo",88,0,-1,0,235,235,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00652",10,"Si duermes en despoblado\npega el oído en el suelo;\nsentirás a gran distancia\nel que viene sin recelo.",198,4,-1,-1,"",0,4,"eo",10,0,-1,0,235,235,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00653",10,"Anda siempre en el arnés\ncon la cobija pegada,\npara evitar que la bestia\nte la quiten emprestada.",198,4,-1,-1,"",0,4,"aa",49,0,-1,0,236,236,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00654",10,"En un viaje de ida y vuelta\nno trilles la misma pista,\nni te olvides que en la oreja\nde la mula, hay otra vista.",198,4,-1,-1,"",0,4,"ia",352,0,-1,0,236,236,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00655",10,"Para que nunca se alcance\nel caballo en la carrera\nse le corta con cuidado\nlas dos uñas delanteras.",198,4,-1,-1,"",0,4,"ea",-1,0,-1,0,236,236,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00656",10,"En el Llano los zamuros\nson del cielo telegramas,\nque te anuncian, más o menos,\nsi la victoria te llama.",198,4,-1,-1,"",0,4,"aa",-1,0,-1,0,236,236,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00657",10,"Sabe que el perro llanero\nse burla del cocodrilo,\nle late en un punto dado\ny bebe lejos, tranquilo.",198,4,-1,-1,"",0,4,"io",247,0,-1,0,236,236,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00658",10,"Centinela es nombre propio\nque a perro de campo cuadra,\nen la noche más dormida\nel solo despierta y ladra.",198,4,-1,-1,"",0,4,"aa",667,0,-1,0,237,237,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00659",10,"Si ves que la huella viene\npor llanos, montes y faldas,\nno te vuelvas; es posible,\nque el que huye vaya de espaldas.",198,4,-1,-1,"",0,4,"aa",668,0,-1,0,237,237,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00660",10,"Como guapo soy de alante\ny créalo, camará,\nal que me arrugue la frente\nle endilgo su puñalá,\nque son pandas las navajas\nCaracoles, camará.",198,4,-1,-1,"",9,6,"a",9,0,-1,0,239,239,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00661",10,"Cuentas claras son bambarrias\ny no le digo más na,\nal que con yo se metiere\nle jiendo por la mitá,\nporque a nadie tengo miedo\nCréalo, caviar á.",198,4,-1,-1,"",9,6,"a",9,0,-1,0,240,240,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00662",10,"Soy un indio libertao,\nque viva la libertá\ny me vivo dando gusto\nporque muy bien sé bailá\ny dos maracas y un cinco,\nCarángano, camará.",198,4,-1,-1,"",9,6,"a",9,0,-1,0,240,240,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00663",10,"Ojo al Cristo, y ojo e garza,\nsi doy una zapatiá\nno queda ni el mismo diablo\nsin dar una carcajá\nque rejienda los infiernos\nsigún de juerte será.",198,4,-1,-1,"",9,6,"a",9,0,-1,0,240,240,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00664",10,"Huracán pasa por casa,\ntempestá por mi ventana,\nrío crecío sal al camino,\ntigre, vente a mi sabana,\ntoro bravo a mi corral,\ncandela, al palmarital.\ny verán si soy un hombre\nde mirarme en los peligros\ncara a cara con la muerte\ny el corazón tranquilo.",198,4,-1,-1,"",18,10,"io",-1,0,-1,0,241,241,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00665",10,"En el hato del Setenta\ndonde se colea el ganao,\nme dieron para mi silla\nun caballito melao.\nme lo dieron por maluco\ny me salió retemplao.",198,4,-1,-1,"",9,6,"ao",98,0,-1,0,243,243,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00666",10,"Más acá de sí sé donde,\njuntico de la quebrá,\niba yo una nochecita\ny hallé la tigra cebáa;",198,4,-1,-1,"",5,4,"aa",-1,0,-1,0,243,243,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00667",10,"no sé que estaría pensando\nel dianche de condená\nque así que me vido encima\nme tiró una manotá.",198,4,-1,-1,"",0,4,"a",9,0,-1,0,244,244,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00668",10,"Juyiste! dije a la indina\nno sea busté tan malcriada\nque pa saludá a un hombre\nno se le tira a la cara,\n¿no vé que el morcillo es potro\ny que se asusta de na?",198,4,-1,-1,"",9,6,"a",-1,0,-1,0,244,244,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00670a",10,"Me llaman el tantas muelas,\naunque no las he mostrao,\nque si las llego a mostrá\nse ha de ve el sol eclisao,",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,245,245,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00670b",10,"la luna teñida en sangre\nlos elementos trocaos,\nlas estrellas apagás\ny al mesmo Dios armirao.",198,4,-1,-1,"",0,4,"ao",-1,0,-1,0,245,245,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00671",10,"Para saltos, el conejo,\npara carrera, el venao;\nyo me parezco a los tigres\ny al león en lo colorao.",198,4,-1,-1,"",3,4,"ao",98,0,-1,0,245,245,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00672",10,"ningún zambo me la ha hecho\nque no me la haya pagao.\nAnoche comí culebra\ny esta mañana pescao;\nlos dedos los tengo romos\nde pegale a los malcriaos.",198,4,-1,-1,"",9,6,"ao",-1,0,-1,0,246,246,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00673",10,"El que cantare conmigo\nha de ser muy estudiao,\nporque le tengo e dejar\ncomo faltriquera a un lao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,246,246,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00674",10,"Conmigo y la rana es gana\nque se metan a cantar,\nque no me gana a moler\nni la piedra de amolar,\nporque tengo más quintillas\nque letras tiene un misal.",198,4,-1,-1,"",9,6,"a",-1,0,-1,0,246,246,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00675",10,"Yo fui quien le dió la muerte\nal plátano verde asao;\ncuando me lo dan, lo cómo,\ncuando no, aguanto callao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,246,246,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00676",10,"Echenme afuera ese toro,\nhijo de la vaca mora\npara sacarle unos lances\ndelante de esa señora.",198,4,-1,-1,"",0,4,"oa",107,0,-1,0,247,247,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00678",10,"Mi mujer está muy brava\nporque otra me agasajó,\nsi yo tengo mi modito\ny me quieren ¿qué hago yo?",198,4,-1,-1,"",0,4,"o",2,0,-1,0,247,247,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00680",10,"Yo te di mi medio real\nporque me hicieras cariños;\nsólo me hiciste una vez:\nme estás debiendo un cuartillo.",198,4,-1,-1,"",0,4,"io",-1,0,-1,0,248,248,"","",0,"","","",2,0,0,[],""],["machado_venezuela-00681-e2",10,"Yo no soy de por aquí,\nyo vengo del otro lao,\ny me trajo un capuchino\nen las barbas enredao.",198,4,-1,-1,"",0,4,"ao",98,0,-1,0,248,248,"","",0,"","","",11,0,0,[],""],["machado_venezuela-00681-e3",10,"Si hubiere alguno en la rueda\nque con yo esté incomodao\nsálgaseme para afuera\nle pondré patiarribao\ncon este brazo invencible\nque Jesucristo me ha dao.",198,4,-1,-1,"",9,6,"ao",98,0,-1,0,248,248,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00682",10,"En estos Llanos de Apure\nyo soy el zambo montao;\nyo fuí quien le dió la muerte\nal plátano verde, asao,\ncon un cabito de vela\ny un Padrenuestro gloriao.",198,4,-1,-1,"",9,6,"ao",98,0,-1,0,249,249,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00685",10,"Quien me quiera conocer\nyo soy fulano de tal\nque a la ciudad: No sé Dónde\nme han llevado a bautizar.\nUn hombre fue mi padrino,\nmi madrina una mujer,\npa dormí cierran los ojos,\ny los abren para ver.\nYo vivo sobre la tierra\nsi me quieren conocer.",198,4,-1,-1,"",18,10,"e",20,0,-1,0,253,253,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00686",10,"Tengo los brazos colgando\npendientes de las paletas;\ncuando las estoy meneando\nes por no tenerlas quietas.",198,4,-1,-1,"",1,4,"ea",525,0,-1,0,253,253,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00688",10,"Ronca el tigre en la montaña\ny la ballena en el mar,\nBrizuela allá en la sabana\ny el Jefe en la capital.",198,4,-1,-1,"",0,4,"a",-1,0,-1,0,255,255,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00689",10,"El joven Francisco Agüero\nlleva una rosa en la mano,\ncuidao si se le deshoja\ncon los vientos del verano.",198,4,-1,-1,"",0,4,"ao",81,0,-1,0,255,255,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00690",10,"Pancho Méndez pegó un grito\nen el alto e La Vigía,\nsi yo fuera Pancho Méndez\npues, también lo pegaría.",198,4,-1,-1,"",0,4,"ia",0,0,-1,0,255,255,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00691",10,"Maestro Luciano Romero\nalúmbreme con su vela,\ny me verá la rodilla\njunto de la choquezuela.",198,4,-1,-1,"",0,4,"ea",167,0,-1,0,256,256,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00692",10,"Para rey nació David,\npara sabio, Salomón,\npara llorar, Jeremías,\ny para quererte, yo.",198,4,-1,-1,"",0,4,"o",-1,0,-1,0,256,256,"","",0,"palau_cantares, lafuente_madrid","","",4,0,0,[],""],["machado_venezuela-00693",10,"Mañana por la mañana\nriega tu patio de flores\nque te viene a visitar\nla Virgen de los Dolores.\n¡Carro de oro. Carro de oro!...",198,4,-1,-1,"",7,5,"oo",-1,0,-1,0,257,257,"","",0,"","","",11,0,0,[],""],["machado_venezuela-00694",10,"Allá arriba, en aquel alto\ntengo un pozo de agua clara\ndonde se lava la Virgen\nlos piecitos y la cara.",198,4,-1,-1,"",0,4,"aa",57,0,-1,0,257,257,"","",0,"","","",10,0,0,[],""],["machado_venezuela-00695",10,"Estrella de la mañana,\nclaro lucero del día,\ncómo no me despertaste,\ncuando se iba el alma mía.\n¡Clavelito! ¡Clavelito!",198,4,-1,-1,"",7,5,"io",-1,0,-1,0,257,257,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00697",10,"Noche oscura y tenebrosa\npréstame tu claridad\npara seguirle los pasos\na una ingrata que se va.\n¡Pavo real! ¡Pava real!",198,4,-1,-1,"",7,5,"a",-1,0,-1,0,258,258,"","",0,"","","",4,0,0,[],""],["machado_venezuela-00698",10,"No soy ningún ruiseñor\nni tampoco pico e plata,\npero si en mí se desata\nla vena del cantaor,\nlo confieso sin rubor,\nnadie me gana a cantar\nque mi garganta, señores,\nalgo tendrá singular\ncuando me pueden llamar\nEl terror de los Cantores.",198,4,-1,-1,"",18,10,"oe",5,0,-1,0,259,259,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00699a",10,"Sólo se debe admirar\na los hombres de talento\nque tomen un argumento\ny lo sepan explicar;\nque puedan repiquetear\nsin-recelos ni temores,\nsi lo piden los señores,\no cuando el caso lo exija,\nlos versos que les dirija\nEl terror de los Cantores.",198,4,-1,-1,"",18,10,"oe",5,0,-1,0,260,260,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00700",10,"Ya la noche al sol embiste\ny mis tristezas cantando\nvoy al paso recordando\nlos abrazos que me diste.\nMira tú si estaré triste\nque coje sabana un toro\nle echo encima al rucio moro\ny al tumbarlo diligente\nrepite el eco doliente:\nCUANDO ESTOY A SOLAS LLORO.",198,4,-1,-1,"",18,10,"oo",85,0,-1,0,261,261,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00701",10,"No he visto mujer bonita\nque no le aprete la mano;\nyo soy el tigre serrano\nde la pinta menudita,\nal romper la mañanita\nensayo en el libro mío,\ny tan libre como el río\nlo seré en el cementerio;\nporque en discusión soy serio\ny en conversación me río.",198,4,-1,-1,"",18,10,"io",-1,0,-1,0,262,262,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00702",10,"Cuando siento el corazón\nlleno de amarga tristeza\nme amarro bien la cabeza,\nme fajo mi cinturón;\ny en mi potro redomón\nmonto a mi zamba, y ufano,\nla llevo al baile cercano,\nella rompe un zapateo,\ny yo orgulloso la veo\ncon la maraca en la mano.",198,4,-1,-1,"",18,10,"ao",81,0,-1,0,262,262,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00703",10,"Soy gallo que no me voy\nni en mi tierra ni en la extraña;\na mí no me meten caña\nporque trapiche no soy.",198,4,-1,-1,"",11,4,"o",112,0,-1,0,262,262,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00704",10,"Adonde me buscan voy\nporque en el cantar doy frío;\nmuy pocos tienen mis bríos,\nyo espanto al ánima sola\ny al golpe de mi bandola\ndivierto los males míos.",198,4,-1,-1,"",9,6,"io",135,0,-1,0,263,263,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00705",10,"Quererle cortar los pasos\na dos que se quieren bien\nes echarle leña al fuego\ny sentarse a verla arder.",198,4,-1,-1,"",0,4,"e",-1,0,-1,0,265,265,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00706",10,"¿Quién será aquel que podrá\ncon rigor envanecer\nque se dejen de querer\ndos, con fina voluntá?\nSólo Dios les quitará\nque se amen con tiernos lazos;\naunque los vuelvan pedazos\npor constantes que hayan sío,\nes majar en hierro frío\nquererle cortar los pasos.",198,4,-1,-1,"",18,10,"ao",375,0,-1,0,265,265,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00707",10,"Aunque penitencia grave\nles imponga el confesor\ny les meta algún temor\nconsejo en ellos no cabe\npa que la amistá se acabe\nporque están de quién a quién;\nsi les aconsejan bien\nellos siguen su destino:\nno hay que guiar por buen camino\na dos que se quieren bien.",198,4,-1,-1,"",18,10,"e",-1,0,-1,0,266,266,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00708",10,"Aunque en trabajos se vean\nprisioneros en cadenas,\npues, con estas mismas penas,\nentonces más se desean;\npor el peligro no crean\nque en ellos haya despego,\nporque el amor es tan ciego\nque aunque la vida perdieran\nprivarles de que se quieran\nes echarle leña al fuego.",198,4,-1,-1,"",18,10,"eo",29,0,-1,0,266,266,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00709",10,"Y si dos se estan queriendo\ncon todita su afección,\nse ofrecen el corazón\ny así el amor va creciendo.",198,4,-1,-1,"",11,4,"eo",52,0,-1,0,266,266,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00710",10,"Los que aquí me están oyendo\nbien me sabrán entender,\neso es como ver prender\ncasa de seca madera\ny por gusto abrirse fuera\nY SENTARSE A VERLA ARDER.",198,4,-1,-1,"",9,6,"e",20,0,-1,0,267,267,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00711",10,"No me vengan con bisteque\nni rosbif, ni champiñón;\nyo digo al soirée, guateque,\ny al restaurant, bodegón.",198,4,-1,-1,"",1,4,"o",31,0,-1,0,269,269,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00712",10,"Malhaya sean los guajiros\nque al volver de la ciudad\ndesdeñan la sociedad\nde sus plácidos retiros;\ncongojas sean los suspiros\nque la garganta les seque,\nal que de ilustrado peque\nhablando sólo de hoteles\nesos señores noveles\nno me vengan con bisteque.",198,4,-1,-1,"",18,10,"ee",-1,0,-1,0,269,269,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00713",10,"Las costumbres patriarcales\nde los labriegos sencilos\nrechazan los estribillos\nde las gentes principales;\ny como no son iguales\nse ponen en irrisión\nafectando ilustración\ny no comprenden a fe\nfricandó ni fricasé,\nni rosbif ni champiñón.",198,4,-1,-1,"",18,10,"o",31,0,-1,0,270,270,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00714",10,"Nada, nada, soy muy claro;\nno quiero echarla de fino;\ndigo al pan, pan, vino al vino,\ny torre y farola al faro.\nAl que pretende ser raro\nviviendo en mi bahareque\nle alborotaré un zambeque\nporque se largue lijero:\nvaya al diablo el caballero\nyo llamo al soirée, guateque.",198,4,-1,-1,"",18,10,"ee",615,0,-1,0,270,270,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00715",10,"Montuno y rancio nací\nallá por la tierra adentro,\ny estoy conforme en mi centro\nsin que se burlen de mí,\nvaya el necio baladi\npara llamar la atención\ncorriendo la población\ncon extranjera matraca:\nyo al bistek le digo vaca\ny al restaurant, bodegón.",198,4,-1,-1,"",18,10,"o",31,0,-1,0,271,271,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00717",10,"Tánto tiempo temeroso\ncomo he podido explicarte,\npero me temo al hablarte\nporque soy muy vergonzoso;\nvuélvome a quedar lloroso\nsintiendo un grande dolor\nal ver tanto desamor\nque está mi vida minando,\ny dice mi alma llorando:\nque desgraciado que soy.",198,4,-1,-1,"",18,10,"o",-1,0,-1,0,273,273,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00718",10,"Atado con tus cadenas\npadezco infeliz y callo,\ny cuando presente te hallo\nse acrecientan más mis penas.\nNo sé si eres agena,\npero cuando a verte vengo,\nno sé que me está diciendo\nque ha de ser otro feliz\ny me digo: ¡ay infeliz!\nque mala fortuna tengo!",198,4,-1,-1,"",18,10,"eo",-1,0,-1,0,274,274,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00719",10,"No siento tanto la pena,\nni siento tanta crueldad,\nno siento que seas agena.\nsiento la infelicidad.\nNo siento tanta maldad,\nni el rigor que usas conmigo,\nsólo en secreto te digo,\nhermosa perla del mar:\nque no me puedes negar\nque todos hablan contigo.",198,4,-1,-1,"",18,10,"io",106,0,-1,0,274,274,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00720",10,"En fin, corazón de acero,\ngustas de verme penando\npor más que me estoy mostrando\ncomo amigo verdadero.",198,4,-1,-1,"",11,4,"eo",38,0,-1,0,274,274,"","",0,"","","",1,0,0,[],""],["machado_venezuela-00721",10,"A tu afecto me refiero\ny lo digo con dolor,\nlos tesoros de su amor\na todos vas ofreciendo\nsin alarma del pudor;\nY YO CON MIRAR TE OFENDO.",198,4,-1,-1,"",9,6,"eo",52,0,-1,0,275,275,"","",0,"","","",1,0,0,[],""],["andina_t1-p0022-05",11,"En la boca 'e la bandola\nquiero hacer mi sepultura,\npara enterrar estos güesos\nque nacieron sin ventura.",200,4,-1,-1,"Ocasión Función",0,4,"ua",17,0,-1,0,22,23,"","",72,"","","",1,0,0,[],""],["andina_t1-p0023-01",11,"Señores, yo soy el muerto,\naunque los muertos no hablan:\na mí me enterraron vivo\nal pie de una verde palma.",200,4,-1,-1,"Ocasión Función",0,4,"aa",-1,0,-1,0,23,23,"","",72,"","","",1,0,0,[],""],["andina_t1-p0026-02a",11,"He bajado el conde Olivo\nla mañana de San Juan\na dar agua a su caballo\na las orillas del mar.",200,4,-1,-1,"Corrido del Pajarillo",0,4,"a",-1,0,-1,0,26,26,"","",72,"","","",1,0,0,[],""],["andina_t1-p0026-02b",11,"-Mientras mi caballo bebe,\nsiéntome un poco a cantar.\nAves que iban por el aire\nse han parado a escuchar.",200,4,-1,-1,"Corrido del Pajarillo",0,4,"a",21,0,-1,0,26,26,"","",72,"","","",1,0,0,[],""],["andina_t1-p0026-02c",11,"Una madre y una hija\nque vivían junto al mar,\ndice la madre a la hija\ncon cariño y con piedad:",200,4,-1,-1,"Corrido del Pajarillo",0,4,"a",-1,0,-1,0,26,26,"","",72,"","","",1,0,0,[],""],["andina_t1-p0028-01",11,"San José con la vara florecida,\ny el Niño Jesús nacido.\nEstas son las consecuencias\nde Nuestro Señor el Mesías.",200,4,-1,-1,"Romance",3,4,"ia",-1,0,-1,0,28,28,"","",72,"","","",1,0,0,[],""],["andina_t1-p0028-04",11,"Esto dijo Adolfo Antonio\ncuando salió de Angostura:\nyo sueño que pongo pena\nen San Fernando de Apure.\nA las seis y media 'el día\nel 24 de octubre,",200,4,-1,-1,"Corrido del paso Arauca",9,6,"ue",-1,0,-1,0,28,28,"","",72,"","","",1,0,0,[],""],["andina_t1-p0028-05",11,"asomaron dos vapores\ntodos dos, llenos de azules,\nSalió Lisandrote Díaz\ncon todita su brigada\ny el general Estanislao\ncubriendo la retaguardia.",200,4,-1,-1,"Corrido del paso Arauca",9,6,"aa",-1,0,-1,0,28,28,"","",72,"","","",1,0,0,[],""],["andina_t1-p0032-01",11,"El año noventa y dos\nFue año de padecer.\nLa guerra estuvo muy brava\nY murió gente también.",200,4,-1,-1,"Corrido del año 1892",0,4,"e",-1,0,-1,0,32,32,"","",72,"","","",1,0,0,[],""],["andina_t1-p0032-02",11,"Hasta hoy no se echan de ver\nLos muebles que nos fallecen;\nEl que no perdió dinero.\nSufrió con sus intereses.",200,4,-1,-1,"Corrido del año 1892",0,4,"ee",-1,0,-1,0,32,32,"","",72,"","","",1,0,0,[],""],["andina_t1-p0032-03",11,"Lo que fue reses y bestias.\nIr a traer a la Goajira;\nHasta los burros también\nPagaron las salvajinas.",200,4,-1,-1,"Corrido del año 1892",3,4,"ia",-1,0,-1,0,32,32,"","",72,"","","",1,0,0,[],""],["andina_t1-p0032-04",11,"Hablemos de las gallinas.\nPatos y pavos también;\nPa' volverse e ensemillar.\nLargos ojos han de ver.",200,4,-1,-1,"Corrido del año 1892",0,4,"e",-1,0,-1,0,32,32,"","",72,"","","",1,0,0,[],""],["andina_t1-p0032-05",11,"Hasta los zorros también\nYo no sé que comerán;\nSapos y frutas del monte\nU otra clase de animal.",200,4,-1,-1,"Corrido del año 1892",0,4,"a",-1,0,-1,0,32,32,"","",72,"","","",1,0,0,[],""],["andina_t1-p0032-06",11,"Volvamos a trabajar;\nEsto es que ya nos conviene;\nMe dicen que es profecía.\nY que duda no le queden.",200,4,-1,-1,"Corrido del año 1892",0,4,"ee",-1,0,-1,0,32,32,"","",72,"","","",1,0,0,[],""],["andina_t1-p0032-09",11,"Las viejas salen gritando\nCuando ven la comisión.\nY algunos se atemorizan.\nY no les falta razón.",200,4,-1,-1,"Corrido del año 1892",0,4,"o",31,0,-1,0,32,32,"","",72,"","","",1,0,0,[],""],["andina_t1-p0032-10",11,"Se les pone el corazón\nQue una pipa de albahaca.\nY aquella rabia en las piernas\nY el cuerpo es un jamaca.",200,4,-1,-1,"Corrido del año 1892",0,4,"aa",457,0,-1,0,32,32,"","",72,"","","",1,0,0,[],""],["andina_t1-p0032-11",11,"No caben en una saca\nLas boleras (2) que han paseo;\nSacen los moros del monte\nComo que están amarraos.",200,4,-1,-1,"Corrido del año 1892",5,4,"ao",-1,0,-1,0,32,32,"","",72,"","","",1,0,0,[],""],["andina_t1-p0032-12",11,"Yo mismo fui con cuidao\nA hacer un rancho pa' huir,\nY lo encontraron primero\nAntes de yo ir a dormir.",200,4,-1,-1,"Corrido del año 1892",0,4,"i",157,0,-1,0,32,32,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-01",11,"De suerte que vino igual\nLa valición de panela;\nExperiencia en lo adelante...\nEso me dijo mi abuela.",200,4,-1,-1,"Corrido del año 1892",0,4,"ea",167,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-02",11,"La gente bastimentera.\nEsa sí se sacó el clavo;\nY el pobre que iba a comprar\nSe quedó rascando el rabo:",200,4,-1,-1,"Corrido del año 1892",0,4,"ao",358,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-03",11,"De todos modos chupamos;\nSaqúese por el jabón.\nQué sebo se conseguía\nEn esa revolución.",200,4,-1,-1,"Corrido del año 1892",0,4,"o",31,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-04",11,"Solamente del licor\nSe puso el trago a cuartillo.\nY ocasiones se perdía\nPorque más orina un grillo.",200,4,-1,-1,"Corrido del año 1892",0,4,"io",228,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-05",11,"Nos pegaron al codillo\nCon el tabaco 'e mascar\nSe puso a fuerte la libra\nY acabamos de ajustar.",200,4,-1,-1,"Corrido del año 1892",0,4,"a",21,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-06",11,"A estos mismos de fumar\nQue hacen de tripa cocida.\nYo no les hacía rebaja...\nLa verdá nunca es mentira.",200,4,-1,-1,"Corrido del año 1892",0,4,"ia",-1,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-08",11,"Cuando oí la salvajina.\nQue estaba el fuego en contorno.\nAy sí dije, madre mía.\nNo va a haber escapatorio..",200,4,-1,-1,"Corrido del año 1892",0,4,"oo",-1,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-09",11,"Por suerte tenía un chinchorro\nY me fui ai monte con él.\nY me pegué una cuadrada.\nComo cuasi no hay jején.",200,4,-1,-1,"Corrido del año 1892",0,4,"e",-1,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-10",11,"Cuando se pone a llover\nParece un pollo de a medio;\nAl hombre más apacible\nLe hace despertar el sueño.",200,4,-1,-1,"Corrido del año 1892",0,4,"eo",-1,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-11",11,"Yo siempre duermo y recuerdo.\nMe la paso vigilando;\nYo no se el año que dentra.\nEste ya se va acabando.",200,4,-1,-1,"Corrido del año 1892",0,4,"ao",33,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-12",11,"Y se mé estaba olvidando:\nEl chimu ya es alucema;\nNos va a llevar quien nos trajo\nSi otro tiempo asina llega.",200,4,-1,-1,"Corrido del año 1892",0,4,"ea",-1,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-13",11,"Dígame por la orejas\nTodito lo que ha pasao;\nMuchas veces por el miedo\nSe deja de hacer mercao.",200,4,-1,-1,"Corrido del año 1892",0,4,"ao",98,0,-1,0,33,33,"","",72,"","","",1,0,0,[],""],["andina_t1-p0033-14",11,"Yo tanteo incomodaos\nEn el campo los tienden.\nPorque uno cuando se\nSe vuelve medio grosero",200,4,-1,-1,"Corrido del año 1892",5,4,"eo",-1,0,-1,0,33,34,"","",72,"","","",1,0,0,[],""],["andina_t1-p0035-02a",11,"Te nombraré sin tardar\nlas plantas de nuestro suelo:\ncon delicia y con esmero\ncrece el mango corpulento,",200,4,-1,-1,"Corrido",0,4,"eo",-1,0,-1,0,35,35,"","",72,"","","",1,0,0,[],""],["andina_t1-p0035-02b",11,"que le da vida y sustento;\nel coporo es como un rey,\nacompáñalo el merey\ny la castaña de alimento;",200,4,-1,-1,"Corrido",11,4,"eo",94,0,-1,0,35,35,"","",72,"","","",1,0,0,[],""],["andina_t1-p0035-03",11,"también sobra sustento\nel trigo en el mundo entero,\nel plátano con esmero\ncambur con melodía,\nse crecen cada día.",200,4,-1,-1,"Corrido",7,5,"ia",0,0,-1,0,35,35,"","",72,"","","",1,0,0,[],""],["andina_t1-p0039-03",11,"Tuve queriendo una negra\nun verano y un invierno;\nay, me parece que estuve\ntres años en el infierno.\n(Me) tenía tan consentido\nla maldita y condena,\nlos diablos se la llevaron\nno se la pude quita.\nHe caminao tanto er mundo,\nno quiero caminar más.",200,4,-1,-1,"Corrido de los animales",18,10,"a",-1,0,-1,0,39,39,"","",72,"","","",1,0,0,[],""],["andina_t1-p0039-04",11,"me han pasao tantos chascos\nque ya hasta miedo me da.\nEsta no es conversación\nni tampoco embustería,\nque yo les voy a explicar\nlos defectos que tenía.",200,4,-1,-1,"Corrido de los animales",9,6,"ia",0,0,-1,0,39,39,"","",72,"","","",1,0,0,[],""],["andina_t1-p0046-01",11,"Cesa, trovador, tu canto.\nque te quiero contestar.\naunque acabo de llegar\nde los confines de un campo.\nYa sé que causas espanto\ncon tu canto placentero.\npero probarte yo quiero\nque no he tenido rival:\nDonde canta loro real\nno canta cucarachero.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"eo",38,0,-1,0,46,46,"","",72,"","","",1,0,0,[],""],["andina_t1-p0046-02",11,"Soy nacido en San José\npertenciente a Miranda\ny por todas partes anda\nmi fama, no sé por qué.\nPara cantar no estudié\nporque no tenía dinero.\npero el continente entero\nse alegra con mi cantar:\nDonde canta loro real\nno canta cucarachero.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"eo",38,0,-1,0,46,46,"","",72,"","","",1,0,0,[],""],["andina_t1-p0046-04",11,"Tú cantas con fantasía,\nyo canto triste y sincero.\npero todo caballero\naprecia mi poesía.\nNo hay público que se ría\nni me diga majadero.\nporque saludo primero\na todo el mundo en plural.\nDonde canta loro real\nno canta cucarachero.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"eo",38,0,-1,0,46,46,"","",72,"","","",1,0,0,[],""],["andina_t1-p0046-05",11,"Hay que aprender en la vida\npara tratar con decencia.\npara crear influencia\nen partes desconocidas;\ntener amigos y amigas\nasí no tengan dinero.\nporque tú eres el primero\nque habla sólo por hablar.\nDonde canta loro real\nno canta cucarachero.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"eo",38,0,-1,0,46,46,"","",72,"","","",1,0,0,[],""],["andina_t1-p0047-01",11,"Casa de un pobre llegué,\napenas ni pan tenía;\ntodo lo que conseguía\ncon Jesús participaba,\ny San Pedro le decía\nporque ese hombre no enriquece,\nporque ese hombre no merece\nadelantar en sostener;\ntú te vas a convencer\nque el ser malo es bueno a veces.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"ee",-1,0,-1,0,47,47,"","",72,"","","",1,0,0,[],""],["andina_t1-p0047-04",11,"De negro viste la viuda\nde amarillo la casada,\nde encarnado la doncella\nde verde la enamorada",200,4,-1,-1,"LAS DÉCIMAS ,",0,4,"aa",49,0,-1,0,47,47,"","",72,"","","",2,0,0,[],""],["andina_t1-p0047-05",11,"De negro se vistió el cielo\ncuando expiró el Redentor\ndando sus pruebas de amor\ncon amoroso consuelo;\nel templo rompió su velo",200,4,-1,-1,"LAS DÉCIMAS ,",7,5,"eo",10,0,-1,0,47,47,"","",72,"","","",1,0,0,[],""],["andina_t1-p0047-06",11,"y de negro con ternura,\nse vistió la Virgen pura\nllorando su soledad;\ny por su santa piedad\nde negro viste la viuda.",200,4,-1,-1,"LAS DÉCIMAS ,",7,5,"ua",-1,0,-1,0,47,47,"","",72,"","","",1,0,0,[],""],["andina_t1-p0048-01",11,"y le dio un fuerte desmayo\nque quedó desfigurado,\ncon espadas traspasado\nde su santo corazón,\npues se viste en la ocasión\nde amarillo la casada.",200,4,-1,-1,"LAS DÉCIMAS ,",9,6,"aa",-1,0,-1,0,48,48,"","",72,"","","",1,0,0,[],""],["andina_t1-p0048-02",11,"De encarnado es el vestido\nde la Santa Encarnación\npara dar satisfacción\ndel pecado cometido.\nMi Dios tan compadecido\nque fundó un alma bella,\npara nacer una estrella",200,4,-1,-1,"LAS DÉCIMAS ,",4,7,"ea",6,0,-1,0,48,48,"","",72,"","","",1,0,0,[],""],["andina_t1-p0048-04",11,"Verde es el árbol copioso\ndel madero sacrosanto\ndonde toditos los santos\nsuben al cielo glorioso;\nverde el pimpollo gracioso\nde la más preciosa rama,\nverde es aquella esmeralda\nque tiene el mar en su centro,\npues viste el árbol por eso\nde verde la enamorada.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"aa",-1,0,-1,0,48,48,"","",72,"","","",1,0,0,[],""],["andina_t1-p0048-05",11,"Los clavos que con pasión\ny espinas que le quitaron.\nsegunda vez traspasaron\nde María el corazón.\nen ver a nuestro Señor\ncon la sangre que lo baña.\nde aquella fuerte lanzada\nque Longino a Cristo dio.\nMira bien como murió.\nalma, si te ves tentada.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"aa",49,0,-1,0,48,48,"","",72,"","","",1,0,0,[],""],["andina_t1-p0048-06",11,"Alma si te ves tentada\npiensa con grande dolor,\nla madre del Redentor\nllorosa y acongojada",200,4,-1,-1,"LAS DÉCIMAS ,",11,4,"aa",49,0,-1,0,48,48,"","",72,"","","",1,0,0,[],""],["andina_t1-p0048-07",11,"El que los cielos crió\ny a la tierra le dio el ser.\npor su amor quiso caer\nal primer paso que dio.",200,4,-1,-1,"LAS DÉCIMAS ,",11,4,"o",2,0,-1,0,48,48,"","",72,"","","",1,0,0,[],""],["andina_t1-p0048-08",11,"Considera cuál sería\nen tan recíproco amor.\nlas penas del Redentor\ny el martirio de María.\nElla cruelmente sufría\nen ver a nuestro Señor,\nllena de tanto dolor.\ntriste sin hallar que hacer.\n- como piadosa mujer\nla madre del Redentor",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"o",72,0,-1,0,48,48,"","",72,"","","",1,0,0,[],""],["andina_t1-p0049-02",11,"Tan hermosa como el sol\nera María Magdalena\nque a los hombres en cadena\nlos tenía siempre en su amor.\nY una bonita flor\nparecía la doncella,",200,4,-1,-1,"LAS DÉCIMAS ,",9,6,"ea",-1,0,-1,0,49,49,"","",72,"","","",1,0,0,[],""],["andina_t1-p0049-04",11,"Enloquecía corazones\naquel divino misterio,\ncon las notas del salterio\ny su lira hecha bordones.\nCantaba dulces canciones",200,4,-1,-1,"LAS DÉCIMAS ,",7,5,"oe",34,0,-1,0,49,49,"","",72,"","","",1,0,0,[],""],["andina_t1-p0049-07",11,"A la sombra que formaban\nlos tupidos emparrados\nde aquel jardín congraciado\ndiariamente se lanzaba;\nen la alfombra se sentaba\naquella doncella hermosa,\ncomo la fragante rosa\nrodeada de claveles;\ngozaba de sus placeres\nMagdalena virtuosa",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"oa",63,0,-1,0,49,49,"","",72,"","","",1,0,0,[],""],["andina_t1-p0049-08",11,"Estaban los cuatro colores\nen grande argumento un día,\nblanco, negro y colorado\ny el azul los combatía",200,4,-1,-1,"LAS DÉCIMAS ,",0,4,"ia",0,0,-1,0,49,49,"","",72,"","","",1,0,0,[],""],["andina_t1-p0049-09",11,"Salió el blanco muy ufano\ndiciendo: yo soy primero;\nde mi color viste el cielo\nque rompen en el sagrario;\nblanca palma en el santuario\ny azucena entre las flores,\nde mis colores, señores,\nes la sal de bautizar;\ny en este argumentar\n'tabán los cuatro colores.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"oe",5,0,-1,0,49,49,"","",72,"","","",1,0,0,[],""],["andina_t1-p0049-10",11,"Salió el negro de su corte\ndiciendo que se admiraba,\nque de su color se hallaba\nel vestido del sacerdote.\nLos señores de la corte\nde capa negra vestían,\nnegro el manto de María\ny su divina pasión,\ny en esta revolución\nla grande argumento un día.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"ia",0,0,-1,0,49,50,"","",72,"","","",1,0,0,[],""],["andina_t1-p0050-01",11,"Estando todos presentes\nha salido el colorado:\nSeñores, aparten a un lado\nque soy banda del presidente,\nvestidura de los valientes\ne insignia de los soldados;\nbandera de los armados\nque me llevan siempre al frente,\npara andar entre la gente\nblanco, negro y colorado.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"ao",-1,0,-1,0,50,50,"","",72,"","","",1,0,0,[],""],["andina_t1-p0050-02",11,"Salió el azul, dulce encanto\ndiciendo: yo soy primero,\nde mi color viste el cielo\nvisten los reyes y santos",200,4,-1,-1,"LAS DÉCIMAS ,",5,4,"ao",-1,0,-1,0,50,50,"","",72,"","","",1,0,0,[],""],["andina_t1-p0050-03",11,"viste la grey jerarquía\nviste la virgen María\ny el verdadero sacramento,\ny en este grande argumento\nel azul los combatía.",200,4,-1,-1,"LAS DÉCIMAS ,",7,5,"ia",0,0,-1,0,50,50,"","",72,"","","",1,0,0,[],""],["andina_t1-p0050-06",11,"De tanto amor idolatro\ny de tanta descelencia,\nel alma y las tres potencias\nmi amor te ofrezco a las cuatro;\na las cinco hacen recato\nmis sentidos y en ti está,\npensando si llegará\nlas seis sin ver tu hermosura;\nyo no tengo hora segura\nen el reloj de mi afán.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"a",-1,0,-1,0,50,50,"","",72,"","","",1,0,0,[],""],["andina_t1-p0050-07",11,"No hay hora que me asujete\nsin tener de ti un consuelo\nporque la luz de tu cielo\nen pie me tiene e las siete;\na las ocho me promete\nque mis penas cesarán,\ny si a las nueve serán\nmis caricias bien premiadas,\nqué horas tan dilatadas\nque tan poco a poco dan.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"a",147,0,-1,0,50,50,"","",72,"","","",1,0,0,[],""],["andina_t1-p0050-08",11,"En fin; las horas que vivo\npasando la noche en vela,\npresentando una cautela\npor ver si te hablo a las diez,\na las once pienso que es\nbien pasada mi aflicción\ny cuando las doce son\nprocuro con más anhelo,\nporque la luz de tu cielo\nalivia mi corazón.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"o",31,0,-1,0,50,50,"","",72,"","","",1,0,0,[],""],["andina_t1-p0051-01",11,"Yo le di la vuelta al mundo,\ncon la mayor osadía,\npor ver si podía aprender\ntoda la Mitología.",200,4,-1,-1,"LAS DÉCIMAS ,",0,4,"ia",0,0,-1,0,51,51,"","",72,"","","",1,0,0,[],""],["andina_t1-p0051-02",11,"Me remonté a los titanes,\nconsulté con el gran Polo,\nle di muerte a Visagolo,\ncon todos sus capitanes,\nregresé a Napolitana,\nconsulté con el Segundo,\nde ahí bajé a lo profundo,\ny le di muerte a Clarión,\ncon grande resolución\nyo le di la vuelta al mundo.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"uo",179,0,-1,0,51,51,"","",72,"","","",1,0,0,[],""],["andina_t1-p0051-03",11,"De ahí bajé a los infiernos,\nconsulté con los impíos,\nfui al mar Rojo y sus ríos\njunto con el Padre Eterno.\npasé la noche en un sueño,\nme marché al siguiente día,\nregresé a la Alejandría,\nsometí al Gobernador,\na la Grande Religión,\ncon la mayor osadía-",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"ia",0,0,-1,0,51,51,"","",72,"","","",1,0,0,[],""],["andina_t1-p0051-04",11,"Prontamente yo llegué\na aquellas temibles tierras,\nprontamente les hice guerra,\na todos con grande fe,\nprontamente me marché,\na Salamanca por ver,\na la cumbre por saber,\nlos juramentos de allí,\nestuve treinta años allí,\npor ver si podía aprender.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"e",20,0,-1,0,51,51,"","",72,"","","",1,0,0,[],""],["andina_t1-p0051-05",11,"Cuando cumplí mi misión,\nremonté los elementos,\nle di muerte al Rey del Viento\ncon todo su familión,\nmarché casa de Plutón,\na quien yo no conocía,\ndiez veces que me repetía,\nvete de aquí, majadero,\nque tú no aprenderás luego,\ntoda la Mitología.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"ia",0,0,-1,0,51,51,"","",72,"","","",1,0,0,[],""],["andina_t1-p0051-06",11,"Vide a Chile y El Callao\nEl Perú y el Cantal\nGuasipati y Tumeremo\nvide el pueblo del Palmar.\nYo salí de Barcelona",200,4,-1,-1,"LAS DÉCIMAS ,",7,5,"oa",-1,0,-1,0,51,51,"","",72,"","","",1,0,0,[],""],["andina_t1-p0052-02",11,"Estuve en Ciudad Bolívar\ny por San Félix salí,\nvide Altagracia y Upata,\nSanta Rosa y Tupapuí;\ntodos esos pueblos yo vi,\nvide a Cicafué y Pastora;\nantes de romper la aurora\nme puse a premeditar\ny vide como en dos horas\nel Perú y el Caratal",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"a",-1,0,-1,0,52,52,"","",72,"","","",1,0,0,[],""],["andina_t1-p0052-07",11,"No hay filosofía sin filo,\nsin sangre no hay sangregorio,\nsin velo no hay velorio\ncomo sin ene no hay Nilo.",200,4,-1,-1,"LAS DÉCIMAS ,",11,4,"io",247,0,-1,0,52,52,"","",72,"","","",1,0,0,[],""],["andina_t1-p0052-09",11,"sin pampa no hay Pampatar.\nSin tribu no hay tribunal\nni sin flor de tilo estito;\nno hay camino sin Camilo\nsin bando no hay bandolín.\nsin palo no hay paladín\nni hay filosofía sin filo,",200,4,-1,-1,"LAS DÉCIMAS ,",4,7,"io",247,0,-1,0,52,52,"","",72,"","","",1,0,0,[],""],["andina_t1-p0053-01",11,"Sin cara no hay caracol\nni habrá Cristóbal sin Cristo;\nsin el cáliz no hay Calixto\nni habrá soldado sin sol.\nSin alcorriente alcohol\nni sin Apolo Apolonio,\nni sin esposa esposorio;\nsin barca no hay barcarola,\nsin coro nunca hay corola,\nsin sangre no hay San Gregorio.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"oo",551,0,-1,0,53,53,"","",72,"","","",1,0,0,[],""],["andina_t1-p0053-02",11,"No hay romance sin Román,\nsin ron nunca habrá Rondón,\nsin cama no hay camarón,\nsin re mayor no hay refrán;\nsin asa no hay azafrán\nni sin acceso accesorio,\nni sin onoto notorio,\nsin rosa nunca hay rosario,\nsin frente calva calvario\ny sin velo no hay velorio.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"oo",551,0,-1,0,53,53,"","",72,"","","",1,0,0,[],""],["andina_t1-p0053-05",11,"Salí de casa a pasear,\nllegué casa de Silveria\ny como la hallé tan seria\nme fui casa de Pilar.\nLuisa me mandó a llamar\nno me quise devolver;\nClara me entregó un papel\ny lo leyó Concepción,\npero yo con distinción\nestoy queriendo a Isabel.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"e",32,0,-1,0,53,53,"","",72,"","","",1,0,0,[],""],["andina_t1-p0053-06",11,"Lo que siento es Agustina\nporque es ardiente y celosa;\ncuando estoy casa de Rosa\nme está mirando Martina.\nLo mismo hace Catalina\nsi voy casa de Estefana;",200,4,-1,-1,"LAS DÉCIMAS ,",9,6,"aa",-1,0,-1,0,53,53,"","",72,"","","",1,0,0,[],""],["andina_t1-p0053-07",11,"nada digo de Emiliana\nporque es todo mi conato.\na todas mujeres trato\npero me agrada Juliana.",200,4,-1,-1,"LAS DÉCIMAS ,",11,4,"aa",4,0,-1,0,53,53,"","",72,"","","",1,0,0,[],""],["andina_t1-p0053-08",11,"No voy casa de Tomasa\nporque ella si no me cela\nde Candelaria y Manuela\ny la causa es Nicolasa;\nque cuando estoy en su casa\ny veo pasar a Lucía,\nle lleve el cuento a María\na Pifania y a Mercedes;\nno sé cómo me veré\nal saberlo Rosalía.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"ia",0,0,-1,0,53,53,"","",72,"","","",1,0,0,[],""],["andina_t1-p0053-09",11,"Me separo de Gregoria\nno quiero más sus amores.\nporque Josefa y Dolores\nyo las cargo en la memoria.\nPara terminar la historia\nme disculparé con Juana,\nme arreglare con pifania\ny hablo con Margarita,\ny por ocasión de Rita\nquedo mal con Feliciana.",200,4,-1,-1,"LAS DÉCIMAS ,",18,10,"aa",-1,0,-1,0,53,54,"","",72,"","","",1,0,0,[],""],["andina_t1-p0054-01",11,"Yo digo que dos son tres\ntambién ocho y ocho nueve;\nel que quiera que lo pruebe\nque dos y cuatro son diez.",200,4,-1,-1,"Trovo de Julián Guevara",11,4,"e",150,0,-1,0,54,54,"","",72,"","","",1,0,0,[],""],["andina_t1-p0054-02",11,"Señores, no soy poeta\npero digo en alta voz.\nque para escribirse dos\nasí, se ponen dos letras.\nY todo el que leer sepa\nverá que una es la de,\nla o que sigue y después.\nla última que es la ese;\npor ese motivo a veces\nyo digo que dos son tres.",200,4,-1,-1,"Trovo de Julián Guevara",18,10,"e",218,0,-1,0,54,54,"","",72,"","","",1,0,0,[],""],["andina_t1-p0054-03",11,"Cuatro letras pongo aquí\npara decir ocho escribo;\nsiendo doble el sustantivo\nocho serán porque si;\npero añadiendo la i\nes distinto el punto leve.\nporque entonces muy en breve\nse esclarece la verdad,\ny se dice en realidad\ntambién ocho y ocho nueve.",200,4,-1,-1,"Trovo de Julián Guevara",18,10,"ee",474,0,-1,0,54,54,"","",72,"","","",1,0,0,[],""],["andina_t1-p0054-05",11,"Cuántos no se pensarán\nque es mentira lo que digo.\npero tengo mis testigos\nque son las letras que están\npresentes como verán.\nfijas y nadie las mueve.\ny si acaso alguien se atreve\npara combatirme a mí.\nte puedo decir así:\nque el que quiera que lo pruebe.",200,4,-1,-1,"Trovo de Julián Guevara",18,10,"ee",82,0,-1,0,54,54,"","",72,"","","",1,0,0,[],""],["andina_t1-p0054-06",11,"A números no me atengo.\nestoy hablando de letras.\nque de las cuales impetras\nla relación que sostengo.\nPor lo cual juro y convengo\nque esto es de mucho Interés.\nsaber desenredar pues\nque cuatro y cinco son doce.\ny para terminar goces\nque dos y cuatro son diez.",200,4,-1,-1,"Trovo de Julián Guevara",18,10,"e",150,0,-1,0,54,54,"","",72,"","","",1,0,0,[],""],["andina_t1-p0054-07",11,"Gracias a la providencia\ndamos los venezolanos,\nque nos dio este ser hermano\npara nuestra independencia.",200,4,-1,-1,"Trovo de Julián Guevara",5,4,"ea",46,0,-1,0,54,54,"","",72,"","","",1,0,0,[],""],["andina_t1-p0054-08",11,"Cuando Venezuela estaba\nbajo el dominio de España,\nnadie intentó la campaña\nporque el yugo le estorbaba;",200,4,-1,-1,"Trovo de Julián Guevara",11,4,"aa",-1,0,-1,0,54,54,"","",72,"","","",1,0,0,[],""],["andina_t1-p0055-01",11,"pero en ese tiempo estudiaba\nun hombre de inteligencia,\nde muy buena descendencia\nen Caracas fue su cuna,\ny esta fue una gran fortuna\ngracias a la providencia.",200,4,-1,-1,"Trovo de Julián Guevara",9,6,"ea",46,0,-1,0,55,55,"","",72,"","","",1,0,0,[],""],["andina_t1-p0055-02",11,"Su dicha no se manchó,\nfue de un corazón sencillo,\nporque él quería ver libre\nsu tierra donde nació.\nSu deseo se le cumplió\nquitando el yugo tirano,\ntodo lo hizo con su mano,\nBolívar no quiso gloria;\ngracias a la eterna memoria\ndamos los venezolanos.",200,4,-1,-1,"Trovo de Julián Guevara",18,10,"ao",-1,0,-1,0,55,55,"","",72,"","","",1,0,0,[],""],["andina_t1-p0055-03",11,"Del Libertador los restos\nque hoy están en el panteón,\ndonde rinde la nación\nsus amores con respeto.\nEn él no hubo pretexto\nni ambición en su conciencia,\nfue de tanta inteligencia\nque de la patria fue amado,\npues fue el más interesado\npara nuestra independencia.",200,4,-1,-1,"Trovo de Julián Guevara",18,10,"ea",46,0,-1,0,55,55,"","",72,"","","",1,0,0,[],""],["andina_t1-p0058-01",11,"No hay mal que dure cien años\nni cuerpo que lo resista,\nni botica que lo cure\nni doliente que lo asista.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"ia",352,0,-1,0,58,58,"","",72,"","","",1,0,0,[],""],["andina_t1-p0058-02",11,"Eso de adorar las bellas\nes ayunar el traspaso;\nyo con las feas me paso.\nque tienen lo mismo que ellas.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",11,4,"ea",89,0,-1,0,58,58,"","",72,"","","",1,0,0,[],""],["andina_t1-p0058-03",11,"Debajo de un considero\nme puse a considerar,\nlo poco que vale un hombre\ncuando no tiene que dar.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"a",21,0,-1,0,58,58,"","",72,"","","",1,0,0,[],""],["andina_t1-p0058-04",11,"Dicen que el mundo se acaba,\nyo digo que eso es mentira;\nel mundo sólo se acaba\npa aquel que la pata estira.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",1,4,"ia",372,0,-1,0,58,58,"","",72,"","","",1,0,0,[],""],["andina_t1-p0058-06",11,"Unos'tan por conseguir\ny otros 'tan velando güira;\ny otro por conseguidor\nle agarró la cola a un tigre.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",5,4,"ie",-1,0,-1,0,58,58,"","",72,"","","",1,0,0,[],""],["andina_t1-p0058-07",11,"Mañana cuando me case\nviviré cerca de un caño:\nsi tengo frío me arropo,\nsi tengo calor me baño.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"ao",40,0,-1,0,58,58,"","",72,"","","",1,0,0,[],""],["andina_t1-p0058-08",11,"Hasta los palos del monte\ntienen su separación:\nunos sirven para leña\ny otros para hacer carbón.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"o",31,0,-1,0,58,58,"","",72,"","","",4,0,0,[],""],["andina_t1-p0058-09",11,"Todo el que tiene dinero\ntiene la sangre liviana,\naunque su padre sea un tigre\ny su madre una caimana.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"aa",4,0,-1,0,58,58,"","",72,"machado_venezuela","","",4,0,0,[],""],["andina_t1-p0058-10",11,"Aquí me encontré una locha,\nmás alante medio real;\narriba, caballo rucio,\nsácame de este barrial!",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"a",1,0,-1,0,58,58,"","",72,"","","",1,0,0,[],""],["andina_t1-p0058-11",11,"¡Ah trabajo pasa un flojo\nen la casa de un mezquino,\nun borracho en un barrial\ny un cangrejo en un camino!",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"io",199,0,-1,0,58,58,"","",72,"","","",1,0,0,[],""],["andina_t1-p0059-01",11,"Vale mas un diablo de oro\nque un crucifijo de plata.\npara el avaro que trata\nde adquirir mucho tesoro.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",11,4,"oo",85,0,-1,0,59,59,"","",72,"","","",1,0,0,[],""],["andina_t1-p0059-02",11,"Goza del sol mientras dure.\ntodo no he de ser verano;\nyo aprendí con la experiencia\nque atrás de un cerro está un lleno.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",5,4,"eo",-1,0,-1,0,59,59,"","",72,"","","",2,0,0,[],""],["andina_t1-p0059-03",11,"Pensando en la muerte estoy\ny sé que debo morir;\npero no puedo decir\nsi será mañana u hoy.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",11,4,"o",112,0,-1,0,59,59,"","",72,"","","",2,0,0,[],""],["andina_t1-p0059-04",11,"Hay cosas que al parecer\npueden suceder no siendo.\npero cosas se están viendo\nque no se pueden creer.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",11,4,"e",20,0,-1,0,59,59,"","",72,"","","",2,0,0,[],""],["andina_t1-p0059-05",11,"Al tiempo le pido tiempo\ny el tiempo tiempo me da,\ny el tiempo siempre me dice\nque él me desengañará.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"a",9,0,-1,0,59,59,"","",72,"","","",1,0,0,[],""],["andina_t1-p0059-06",11,"Las viejas tienen la culpa\nsi las hijas se les van.\nporque a cuenta de automóviles\ndan cabida al gavilán.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"a",147,0,-1,0,59,59,"","",72,"","","",1,0,0,[],""],["andina_t1-p0059-07",11,"Maluco es cuando uno pide\ny le dicen que no hay;\nentonces querrá decir\nque este golpe no es por ai.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"a",669,0,-1,0,59,59,"","",72,"","","",1,0,0,[],""],["andina_t1-p0059-08",11,"Vamos comiendo y bebiendo\nque la vida no es estable;\ncomo la que me parió\nno hallo mujer que me cuadre.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"ae",-1,0,-1,0,59,59,"","",72,"","","",1,0,0,[],""],["andina_t1-p0059-09",11,"Si un pobre no vale nada.\nahora sí estoy convencido:\na ninguno le va mal\ncon dinero en su bolsillo.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"io",-1,0,-1,0,59,59,"","",72,"","","",1,0,0,[],""],["andina_t1-p0059-10",11,"Cuando un negro está comiendo\nde un blanco en la compañía.\no el blanco le debe al negro\no es del negro le comía.",200,4,-1,-1,"Coplas Filosóficas y Satíricas",0,4,"ia",0,0,-1,0,59,59,"","",72,"","","",1,0,0,[],""],["andina_t1-p0059-11",11,"De catira a mí no me hable:\nyo tuve cuatro docenas.\ny en esas cuarenta y ocho\nno salió ninguna buena.",200,4,-1,-1,"De Amores",3,4,"ea",-1,0,-1,0,59,59,"","",72,"","","",1,0,0,[],""],["andina_t1-p0059-12",11,"Si quieres quererme, quiéreme.\ny si no, dame veneno:\nque no es el primer amante\nque le da muerte a su dueño.",200,4,-1,-1,"De Amores",0,4,"eo",-1,0,-1,0,59,59,"","",72,"","","",2,0,0,[],""],["andina_t1-p0059-13",11,"Si piensas que con tu amor\nme derrito como plomo,\nanda vete a los infiernos\nque yo con tu amor no como.",200,4,-1,-1,"De Amores",0,4,"oo",349,0,-1,0,59,59,"","",72,"","","",1,0,0,[],""],["andina_t1-p0059-14",11,"Desde que te vi, te amé\ncon afecto y esperanza.\npero como todo cansa.\nme olvidaste y te olvidé.",200,4,-1,-1,"De Amores",11,4,"e",77,0,-1,0,59,59,"","",72,"","","",17,0,0,[],""],["andina_t1-p0059-15",11,"Tú eres la piña madura.\nyo soy el puñal de acero;\npartí por donde tú quieras\nque por tus amores muero.",200,4,-1,-1,"De Amores",0,4,"eo",38,0,-1,0,59,59,"","",72,"","","",1,0,0,[],""],["andina_t1-p0059-16",11,"Levanta el ala 'el sombrero.\ngalán, que te quiero ver;\nque te quiero comparar\ncon un lucido clavel.",200,4,-1,-1,"De Amores",0,4,"e",-1,0,-1,0,59,59,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-01",11,"Tengo que hacer un vestido\ntodo lleno 'e sentimientos,\ncon los botones de olvido\ny el género de escarmiento.",200,4,-1,-1,"De Amores",0,4,"eo",-1,0,-1,0,60,60,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-02",11,"Triste esté mi corazón,\ntriste y no sé lo que tiene,\nmas triste se debe ver\nel que triste e mí me tiene.",200,4,-1,-1,"De Amores",0,4,"ee",-1,0,-1,0,60,60,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-03",11,"Todo el que me oye cantando\ndice, qué alegre está aquél;\ny mi corazón lo tengo\nmas amargo que una hiél.",200,4,-1,-1,"De Amores",0,4,"e",32,0,-1,0,60,60,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-04",11,"La mujer que no me quiera\nno me hace ningunos males;\nmejor como y mejor visto\ny mas me duran mis ríales.",200,4,-1,-1,"De Amores",5,4,"ie",-1,0,-1,0,60,60,"","",72,"","","",2,0,0,[],""],["andina_t1-p0060-05",11,"No vuelvo más a tu casa\ncomo en un tiempo lo hacía,\nporque se secó la mata\ndonde yo flores cogía.",200,4,-1,-1,"De Amores",0,4,"ia",0,0,-1,0,60,60,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-06",11,"Ayer te mandé un platillo\ncon yerbabuena del río;\nentre cogollo y cogollo\nva mi corazón partido.",200,4,-1,-1,"De Amores",0,4,"io",-1,0,-1,0,60,60,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-07",11,"Las rocas en los raudales\nel tiempo las reverdece;\ne sigún las voluntades\nasí los amores crecen.",200,4,-1,-1,"De Amores",0,4,"ee",-1,0,-1,0,60,60,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-08",11,"El primer amor es dulce,\nel segundo es lisonjero,\nel tercero es vengador:\nno hay amor como el primero.",200,4,-1,-1,"De Amores",0,4,"eo",38,0,-1,0,60,60,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-09",11,"Arbolito, te secaste,\nteniendo el agua en el pie,\nen la raíz la esperanza\ny en el cogollo la fe.",200,4,-1,-1,"De Amores",0,4,"e",77,0,-1,0,60,60,"","",72,"","","",5,0,0,[],""],["andina_t1-p0060-10",11,"Ayer tarde estaba yo\nentre las flores metido,\ny entre claveles y rosas\nme hallaba resplandecido.",200,4,-1,-1,"De Amores",0,4,"io",101,0,-1,0,60,60,"","",72,"","","",2,0,0,[],""],["andina_t1-p0060-11",11,"Corazón de palo santo,\nramo de limón florido\n¿por qué dejas en olvido\na quien te ha querido tanto?",200,4,-1,-1,"De Amores",11,4,"ao",30,0,-1,0,60,60,"","",72,"","","",3,0,0,[],""],["andina_t1-p0060-12",11,"Un clavel me tiene loco\nde ver y considerar,\nde verlo tan bajitico\ny no poderlo agarrar.",200,4,-1,-1,"De Amores",0,4,"a",21,0,-1,0,60,60,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-13",11,"Desde aquí te estoy mirando\ncomo un granito de arroz;\na mí se me está poniendo\nque nos queremos los dos.",200,4,-1,-1,"De Amores",0,4,"o",87,0,-1,0,60,60,"","",72,"","","",19,0,0,[],""],["andina_t1-p0060-14",11,"En las orillas de un río\nen la sombra de un laurel,\nestaba la vida mía\nviendo las aguas correr.",200,4,-1,-1,"De Amores",0,4,"e",-1,0,-1,0,60,60,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-15",11,"Mañana cuando te vayas\nte voy a salir al camino,\npara llenarte el pañuelo\nde lágrimas y suspiros.",200,4,-1,-1,"De Amores",0,4,"io",-1,0,-1,0,60,60,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-17",11,"Poco a poco va cayendo\nel páramo a la quebrá;\nque ya viniste, ¿quien te trajo?\n¿y ahora quién te llevará?",200,4,-1,-1,"De Amores",3,4,"a",9,0,-1,0,60,60,"","",72,"","","",1,0,0,[],""],["andina_t1-p0060-18",11,"La pena y la que no es pena\ntodo es pena para mí;\nayer penaba por verte.\ny hoy peno porque te vi.",200,4,-1,-1,"De Amores",0,4,"i",23,0,-1,0,60,60,"","",72,"rm_t3, fernan_caballero","","",8,0,0,[],""],["andina_t1-p0061-01",11,"Las flores de los caminos\nnacen pa' tos caminantes;\ntú naciste para mí\ny yo para ser tu amante.",200,4,-1,-1,"De Amores",0,4,"ae",-1,0,-1,0,61,61,"","",72,"","","",1,0,0,[],""],["andina_t1-p0061-02",11,"La madre es un lindo ser\ndigno de saber amar,\nno se puede comparar\ncon cualesquiera mujer.",200,4,-1,-1,"De Amores",11,4,"e",20,0,-1,0,61,61,"","",72,"","","",1,0,0,[],""],["andina_t1-p0061-03",11,"A mí sí que me da miedo\ncuando me pongo a cantar;\nsaco los monos del monte\ny hago los mudos hablar.",200,4,-1,-1,"Jactanciosas",0,4,"a",21,0,-1,0,61,61,"","",72,"","","",1,0,0,[],""],["andina_t1-p0061-04",11,"Entre los hombres soy hombre\ny entre la mar soy pescao;\ny entre los géneros güenos\nyo soy el ebatanao.",200,4,-1,-1,"Jactanciosas",0,4,"ao",98,0,-1,0,61,61,"","",72,"","","",1,0,0,[],""],["andina_t1-p0061-05",11,"Con mi maraca en la mano\naquí estoy dando candela;\ny le hago tragar el medio\ncon trapo y todo a cualquiera.",200,4,-1,-1,"Jactanciosas",0,4,"ea",-1,0,-1,0,61,61,"","",72,"","","",1,0,0,[],""],["andina_t1-p0061-06",11,"Soy un pájaro de cuenta\ncuando la gana me da;\ncuando no me da la gana,\nno soy pájaro ni ná.",200,4,-1,-1,"Jactanciosas",0,4,"a",9,0,-1,0,61,61,"","",72,"","","",1,0,0,[],""],["andina_t1-p0061-09",11,"Canté con un cantador\ny no me pudo ganar;\nél con un mapire 'e versos\ny yo con uno no más.",200,4,-1,-1,"Jactanciosas",0,4,"a",-1,0,-1,0,61,61,"","",72,"","","",1,0,0,[],""],["andina_t1-p0061-10",11,"Yo tengo los dientes duros\ny muerdo buenos bocaos;\na mí nadie me la ha hecho\nque no me la haiga pagao.",200,4,-1,-1,"Jactanciosas",0,4,"ao",-1,0,-1,0,61,61,"","",72,"","","",1,0,0,[],""],["andina_t1-p0061-11",11,"Como charrasquero estoy\na la vanguardia de todos,\nporque de distintos modos\na la charrasca le doy.",200,4,-1,-1,"Jactanciosas",11,4,"o",112,0,-1,0,61,61,"","",72,"","","",1,0,0,[],""],["andina_t1-p0061-12",11,"Algunos para cantar\ntienen su medio salero;\npero yo para cantar,\ntengo mi salero entero.",200,4,-1,-1,"Jactanciosas",1,4,"eo",38,0,-1,0,61,61,"","",72,"machado_venezuela","","",2,0,0,[],""],["andina_t1-p0061-13",11,"En Caracas tengo tienda\ny en Valencia pulpería,\ny en las barrancas de Apure\ntengo mi guarapería.",200,4,-1,-1,"Jactanciosas",0,4,"ia",0,0,-1,0,61,61,"","",72,"","","",3,0,0,[],""],["andina_t1-p0061-14",11,"Sobre la tierra la palma,\nsobre la palma los cielos;\nsobre mi caballo yo\nsobre yo mi sombrero.",200,4,-1,-1,"Jactanciosas",0,4,"eo",-1,0,-1,0,61,61,"","",72,"","","",2,0,0,[],""],["andina_t1-p0061-15",11,"San Rafael tiró el anzuelo.\na las seis de la mañana,\ny a las siete lo sacó\ncon una enorme cachama.",200,4,-1,-1,"Conocimientos y temas generales",0,4,"aa",-1,0,-1,0,61,61,"","",72,"","","",1,0,0,[],""],["andina_t1-p0061-16",11,"Buen amigo y compañero\ndígamele el otro vete,\nque me empreste rial y medio\npa' completar cinco ríales.",200,4,-1,-1,"Conocimientos y temas generales",5,4,"ie",-1,0,-1,0,61,61,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-01",11,"En la galera del Pao\ncanta el pájaro Pla-póco,\ny la guacharaca de agua\nen la costa 'el Orinoco.",200,4,-1,-1,"Conocimientos y temas generales",0,4,"oo",152,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-02",11,"En el último escalón,\nya pa'llegar a la gloria,\nme acordé que había dejao\nun asientico entre Colla.",200,4,-1,-1,"Conocimientos y temas generales",0,4,"oa",-1,0,-1,0,62,62,"","",72,"","","",2,0,0,[],""],["andina_t1-p0062-03",11,"En balde son los cordiales\ny los caldos de gallina:\ncuando el enfermo está grave\nse le da la medicina.",200,4,-1,-1,"Conocimientos y temas generales",0,4,"ia",11,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-04",11,"Por ser la primera vez\nque yo en esta casa canto,\ngloria al Padre, gloria al Hijo,\ngloria al Espíritu Santo.",200,4,-1,-1,"Conocimientos y temas generales",0,4,"ao",30,0,-1,0,62,62,"","",72,"frenk_t3, machado_venezuela","","",8,0,0,[],""],["andina_t1-p0062-05",11,"Ocho reales tiene un peso,\ncuatro reales la mitad;\ndos reales la cuarta parte\ny un real la cuarta mitad.",200,4,-1,-1,"Conocimientos y temas generales",3,4,"a",-1,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-06",11,"Eso yo se lo aseguro,\ncompañero, amigo mío:\npasaje no es como golpe\nni que lo toquen corrió.",200,4,-1,-1,"Conocimientos y temas generales",5,4,"o",-1,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-07",11,"Cantar bien o no cantar,\nen el campo es diferente;\npero delante 'e la gente,\ncantar bien o no cantar.",200,4,-1,-1,"Conocimientos y temas generales",11,4,"a",-1,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-08",11,"A las cuatro muere el sol\nen los brazos de la tarde;\npor éso la triste noche\nviste de negros pañales.",200,4,-1,-1,"Conocimientos y temas generales",0,4,"ae",-1,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-09",11,"Mono no sube guemacho,\nni guacharaca, cardón;\na palo que no florea,\nno le baja cigarrón.",200,4,-1,-1,"Conocimientos y temas generales",0,4,"o",31,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-10",11,"Cuatro cuerdas tiene el cuatro\ny ocho tiene la bandola;\ncuatro mil pesares tiene\nla mujer que se enamora.",200,4,-1,-1,"Conocimientos y temas generales",0,4,"oa",-1,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-12",11,"Aquí me tenéis presente,\naquí me tenéis parao;\nel que decían que era muerto\npero no estaba enterrao.",200,4,-1,-1,"Temas Sociales",0,4,"ao",98,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-13",11,"Mi mama se llama arepa\ny mi taita maiz tostao:\nmiren las horas que son\ny no me he desayunao.",200,4,-1,-1,"Temas Sociales",0,4,"ao",98,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-14",11,"Si tuviéramos una olla,\nun huevo y tantica sal,\nhiciéramos una pisca:\npero no hay agua ni hay pan.",200,4,-1,-1,"Temas Sociales",0,4,"a",-1,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0062-16",11,"El que nació para pobre\ny su capital es medio,\ncuando se gana tres reales\nse le pierden dos y medio.",200,4,-1,-1,"Temas Sociales",0,4,"eo",-1,0,-1,0,62,62,"","",72,"","","",3,0,0,[],""],["andina_t1-p0062-17",11,"Soy negro porque es preciso,\nporque negro fue papá;\nquiere decir que mamá\nno faltó a su compromiso.",200,4,-1,-1,"Temas Sociales",11,4,"io",92,0,-1,0,62,62,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-01",11,"No soy negro por la ley.\nsoy negro por ley de Cristo;\npero e mí nunca me han visto.\nrobando café en el muey.",200,4,-1,-1,"Temas Sociales",11,4,"e",133,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-02",11,"Soy negro como él zamuro\ny aunque de memoria bruta.\npuedo así en su cuarto oscuro,\nsalvarme de la recluta.",200,4,-1,-1,"Temas Sociales",1,4,"ua",197,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-03",11,"Señores yo ya me voy\nno me vayan a hablar mal.\nporque maña es del que queda\nhablar mal de quien se va.",200,4,-1,-1,"Temas Sociales",0,4,"a",-1,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-04",11,"De mí no pueden decir\nque yo soy faramallero,\nporque a mí nunca me han visto\nhaciendo lo que no puedo.",200,4,-1,-1,"Temas Sociales",0,4,"eo",-1,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-05",11,"Yo tenía mi Severiana\ny se me fue pa' Pueblo Hondo:\ny de allá me la mandaron\ncon un Severiano al hombro.",200,4,-1,-1,"Temas Sociales",0,4,"oo",-1,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-06",11,"Eso fue lo que sacates\nde la cogida de arroz:\nlas naguas a media pierna\ny un chinito puro a vos.",200,4,-1,-1,"Temas Sociales",0,4,"o",87,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-07",11,"En la cogida 'e café\nmucha plata sí, se gana.\npero también echa vaina\nel rocío por la mañana.",200,4,-1,-1,"Temas Sociales",0,4,"aa",-1,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-08",11,"Cuando un pobre se enamora\ny un rico se le atraviesa.\nsale el pobre atribulado\nrascándose la cabeza.",200,4,-1,-1,"Temas Sociales",0,4,"ea",108,0,-1,0,63,63,"","",72,"","","",3,0,0,[],""],["andina_t1-p0063-09",11,"Cuando una mujer resbala\naunque no caiga se pierde:\nporque nunca falta alguno\nque del resbalón se acuerde.",200,4,-1,-1,"Temas Sociales",0,4,"ee",154,0,-1,0,63,63,"","",72,"machado_venezuela","","",2,0,0,[],""],["andina_t1-p0063-10",11,"Arrímese al istrumento\nsi gusta de que le cante;\nno me haga perder el tiempo,\nque ahora soy comerciante.",200,4,-1,-1,"Temas Sociales",0,4,"ae",47,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-11",11,"Mi taita se murió anoche.\nmi mama esta madrugada;\nla mujercita que tengo\nme dicen que esta preñada.",200,4,-1,-1,"Temas Sociales",0,4,"aa",49,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-12",11,"¿Cómo puede un policía\ncon lo poquito que gana\ncomer de noche y mañana\nvestirse y tener querida?",200,4,-1,-1,"Temas Sociales",5,4,"ia",-1,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-13",11,"Cuando oigo sonar el cacho\nel cuerpo se me espeluca,\nsólo de considerar\nel alimento 'e la yuca.",200,4,-1,-1,"Temas Sociales",0,4,"ua",607,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-14",11,"El que nació para pobre\ny su sino es niguatero.\naunque le saquen la nigua\nsiempre le queda el aujero.",200,4,-1,-1,"Temas Sociales",0,4,"eo",38,0,-1,0,63,63,"","",72,"","","",3,0,0,[],""],["andina_t1-p0063-15",11,"Bailando mi media rosca\nel cura me regañó;\nel cura manda en su iglesia\ny en mi media rosca yo.",200,4,-1,-1,"Humorísticas",0,4,"o",2,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0063-16",11,"Mírale el ojo a la mona\ncomo lo relempaguea:\nsi no fuera por la mona\nno hubiera mujeres feas.",200,4,-1,-1,"Humorísticas",0,4,"ea",-1,0,-1,0,63,63,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-01",11,"No te fijes en el chivo,\nfíjate en la cagarruta;\nporque la mujer más bruta\nengaña al hombre más viva",200,4,-1,-1,"Humorísticas",5,4,"ia",-1,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-02",11,"Bonita la rebonita,\npor muy bonita que sea,\nnunca deja de mojarse\ncuando llueve o paramea.",200,4,-1,-1,"Humorísticas",0,4,"ea",54,0,-1,0,64,64,"","",72,"","","",2,0,0,[],""],["andina_t1-p0064-03",11,"La mujer que quiere a dos\nlos quiere como hermanitos:\nuno te lleva la jaula\ny el otro los pajaritos.",200,4,-1,-1,"Humorísticas",0,4,"io",254,0,-1,0,64,64,"","",72,"","","",12,0,0,[],""],["andina_t1-p0064-04",11,"Todas la mujeres tienen\nen el ombligo la luna;\ny una cuarta más abajo\nla rueda de la fortuna.",200,4,-1,-1,"Humorísticas",0,4,"ua",56,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-05",11,"Una noche en una fiesta\nme dijo una cucuteña:\nsi no me queras hablar\nyo también entiendo a señas.",200,4,-1,-1,"Humorísticas",0,4,"ea",-1,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-06",11,"Para cantar y bailar\nninguno me gana a yo;\npara rezar el Rosario,\nmi hermano que se murió.",200,4,-1,-1,"Humorísticas",0,4,"o",2,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-07",11,"Las mujeres merideñas\nno son feas ni bonitas,\npero son más pedigüeñas,\nque las ánimas benditas.",200,4,-1,-1,"Humorísticas",1,4,"ia",258,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-08",11,"Cuando un tuerto se enamora\nde una muchacha bonita,\nel corazón le palpita\ny el ojo tuerto le llora.",200,4,-1,-1,"Humorísticas",11,4,"oa",107,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-09",11,"La mujer que sea tetona\nno sirve pa'cocinera.\nporque con las mismas tetas\nbota la masa pa'fuera.",200,4,-1,-1,"Humorísticas",0,4,"ea",-1,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-10",11,"Una muchacha me dijo\nque le diera un camisón,\nque ella me lo pagaría\ndebajo de un almendrón.",200,4,-1,-1,"Humorísticas",0,4,"o",31,0,-1,0,64,64,"","",72,"","","",4,0,0,[],""],["andina_t1-p0064-11",11,"Una muchacha me dijo\nque le diere un real en plata,\ncon tal que me lo pagara\ncon un conejo sin peros.",200,4,-1,-1,"Humorísticas",5,4,"eo",-1,0,-1,0,64,64,"","",72,"","","",4,0,0,[],""],["andina_t1-p0064-12",11,"Esto me dijo papá\nque buscaré una querida;\nque así viejo como estaba,\nél tampoco se descuide.",200,4,-1,-1,"Humorísticas",5,4,"ie",-1,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-13",11,"Si el pático se comiere\nyo me lo comiere asao,\npor quitarle la querencia\nque tiene en el otro lao.",200,4,-1,-1,"Humorísticas",0,4,"ao",98,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-14",11,"San Rafael se fue a pescar\ny no llevó la tarraya;\n¿qué creería San Rafael,\nque el peje está en la playa?",200,4,-1,-1,"Humorísticas",3,4,"aa",404,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-15",11,"Me gusta la Perra Baya,\nme gusta por lo ligera;\ncuando la mando al mandado\necha la semana entera.",200,4,-1,-1,"Humorísticas",0,4,"ea",44,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-16",11,"Chipolita dame el seno\nque yo me quiero enseñar;\nantes que otro se acomode\nyo me quiero acomodar.",200,4,-1,-1,"Humorísticas",0,4,"a",21,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-17",11,"San Cristóbal es la Gloria\ny La Grita es otro cielo;\nGueraque es el Purgatorio\ny Pregonero el Infierno.",200,4,-1,-1,"Humorísticas",0,4,"eo",-1,0,-1,0,64,64,"","",72,"","","",1,0,0,[],""],["andina_t1-p0064-18",11,"Un calvo se encontró un peine,\nun tullido un par de botas;\nunos anteojos un ciego...\n¡vaya una fortuna local",200,4,-1,-1,"Humorísticas",5,4,"a",-1,0,-1,0,64,64,"","",72,"","","",2,0,0,[],""],["andina_t1-p0065-01",11,"Recójanme toas las viejas,\nme las pone en un montón,\npara darles su aguinaldo\ncon una mano 'e pilón.",200,4,-1,-1,"Humorísticas",0,4,"o",31,0,-1,0,65,65,"","",72,"","","",2,0,0,[],""],["andina_t1-p0065-02",11,"Un viejito y una vieja\nse fueron hacer un guiso;\nla vieja pele las papas\ny el viejito los chorizos.",200,4,-1,-1,"Humorísticas",0,4,"io",-1,0,-1,0,65,65,"","",72,"","","",4,0,0,[],""],["andina_t1-p0065-03",11,"Dicen que los barrigones\nson los dueños de la plata;\nyo también soy barrigón\nestoy pelando una lata.",200,4,-1,-1,"Humorísticas",0,4,"aa",74,0,-1,0,65,65,"","",72,"","","",1,0,0,[],""],["andina_t1-p0065-04",11,"Mas allá de no se donde\nmataron a no sé quien,\ny si no corro tan duro\nme matan a mí también.",200,4,-1,-1,"Humorísticas",0,4,"e",242,0,-1,0,65,65,"","",72,"","","",1,0,0,[],""],["andina_t1-p0065-05",11,"La sapa estaba pariendo;\nel sapo estaba apurao,\nhaciendo una diligencia.\nen su butaca sentao.",200,4,-1,-1,"Humorísticas",0,4,"ao",98,0,-1,0,65,65,"","",72,"","","",2,0,0,[],""],["andina_t1-p0065-06",11,"Por una vez que lloré\nme pusieron a mamá;\nme he quedao con la costumbre\ncada momento llora.",200,4,-1,-1,"Humorísticas",5,4,"oa",-1,0,-1,0,65,65,"","",72,"","","",1,0,0,[],""],["andina_t1-p0065-07",11,"Ajila, ajila ganaíto\npor la huella 'el cabrestero;\nponele amor al camino\ny olvida tu comedero.",200,4,-1,-1,"Funcionales",0,4,"eo",38,0,-1,0,65,65,"","",72,"","","",2,0,0,[],""],["andina_t1-p0065-08",11,"Ajila, ajila ganaíto\npor la huella 'el cabrestero,\npara contarte los pasos\ndel corral al paradero.",200,4,-1,-1,"Funcionales",0,4,"eo",38,0,-1,0,65,65,"","",72,"","","",2,0,0,[],""],["andina_t1-p0065-09",11,"Yo no soy hombre chiquito\nni muchacho de mendao;\ndecímele al cabrestero\nque me cante este ganao.",200,4,-1,-1,"Funcionales",0,4,"ao",98,0,-1,0,65,65,"","",72,"","","",1,0,0,[],""],["andina_t1-p0065-10",11,"Arrímate, Negra Vieja,\npa la puerta del chiquero,\ne dele qué mamá a tu hijo,\na tu amo dale dinero.",200,4,-1,-1,"Funcionales",0,4,"eo",38,0,-1,0,65,65,"","",72,"","","",1,0,0,[],""],["andina_t1-p0065-11",11,"El día que yo me muera\nte voy a dejá un recuerdo,\npa que te ordeñe mañana\nel muchacho becerrero.",200,4,-1,-1,"Funcionales",0,4,"eo",-1,0,-1,0,65,65,"","",72,"","","",6,0,0,[],""],["andina_t1-p0065-12",11,"Mañana cuando me vaya\ny pesao porque yo vuelvo,\nmira que me está alumbrando\nlos corrales una estrella. Turupial,\nTurupial...",200,4,-1,-1,"Funcionales",7,5,"a",-1,0,-1,0,65,65,"","",72,"","","",7,0,0,[],""],["andina_t1-p0065-13",11,"Orinoco... Orinoco...\nEn la galera del Pao\ncanta el pájaro piapoco,\ny la guacharaca de agua\nen la costa 'el Orinoco.",200,4,-1,-1,"Funcionales",7,5,"oo",152,0,-1,0,65,65,"","",72,"","","",1,0,0,[],""],["andina_t1-p0065-14",11,"Nochebuena... Nochebuena...\nEn los esteros del mar\nsuspiraba una ballena,\ny en el suspiro decía\nque el que tiene amores pena.",200,4,-1,-1,"Funcionales",7,5,"ea",59,0,-1,0,65,65,"","",72,"","","",3,0,0,[],""],["andina_t1-p0065-15",11,"El señor Francisco Díaz\n¿dónde está que no lo veo?\nToy botando los begazos\npara ganarle el dinero",200,4,-1,-1,"Funcionales",0,4,"eo",-1,0,-1,0,65,66,"","",72,"","","",1,0,0,[],""],["andina_t1-p0066-01",11,"A este público presente\nle agradezco la atención;\n'tamos moliendo la caña\npa sacar el papelón;",200,4,-1,-1,"Funcionales",0,4,"o",31,0,-1,0,66,66,"","",72,"","","",1,0,0,[],""],["andina_t1-p0066-02",11,"Para comer los cogollos\nmuele la caña primero;\npa que digen las muchachas\n¡ah bueyecito molenderol",200,4,-1,-1,"Funcionales",3,4,"o",-1,0,-1,0,66,66,"","",72,"","","",1,0,0,[],""],["andina_t1-p0066-04",11,"Muele bueycito querido\nque el guarapo ya salió,\nya la caña se molió,\nsu amo queda agradecido.",200,4,-1,-1,"Funcionales",11,4,"io",101,0,-1,0,66,66,"","",72,"","","",1,0,0,[],""],["andina_t1-p0066-05",11,"Ya la caña se molió,\nel guarapo va a la paila;\npuede limpiarse el trapiche\na las ocho 'e la mañana.",200,4,-1,-1,"Funcionales",0,4,"aa",-1,0,-1,0,66,66,"","",72,"","","",1,0,0,[],""],["andina_t1-p0066-06",11,"Ya sacamos la tarea,\na descansar van los bueyes,\ne comer y a seguir\nporque así es que nos conviene.",200,4,-1,-1,"Funcionales",0,4,"ee",-1,0,-1,0,66,66,"","",72,"","","",1,0,0,[],""],["andina_t1-p0066-07a",11,"Tú eres tapiña madura,\nyo soy el puñal de acero;\npartí por donde tú quieras\nque por tus amores muero.",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",0,4,"eo",38,0,-1,0,66,66,"","",72,"","","",1,0,0,[],""],["andina_t1-p0066-07b",11,"Ayer te mandé un pañuelo\ny en cada punta un gafete,\npara cuando nos casemos\nandemos de brazalete.",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",0,4,"ee",285,0,-1,0,66,66,"","",72,"","","",2,0,0,[],""],["andina_t1-p0066-08a",11,"Levante el ala 'el sombrero\ngalán, que te quiero ver;\nque te quiero comparar\ncon un lucido clavel.",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",0,4,"e",-1,0,-1,0,66,66,"","",72,"","","",1,0,0,[],""],["andina_t1-p0066-08b",11,"Eres un granito de oro\nprendido en una balanza;\npor ti vivo y por ti muero\ny en ti son mis esperanzas.",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",0,4,"aa",-1,0,-1,0,66,66,"","",72,"","","",5,0,0,[],""],["andina_t1-p0066-10",11,"Estoy tan escarmentado\ny del mundo tan sentido,\nen verme tan maltratado\ny tan mal correspondido.",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",1,4,"io",101,0,-1,0,66,66,"","",72,"","","",1,0,0,[],""],["andina_t1-p0066-11",11,"Los zapaticos son negros,\nlas medias son colora';\npara subir al altar mayor\nno tengo dificulta.",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",3,4,"ua",-1,0,-1,0,66,66,"","",72,"","","",1,0,0,[],""],["andina_t1-p0066-11-e2",11,"Una muchacha me dijo\nque le diera un camisón;\nyo le dije: condenada,\n¿a mí quién me da calzón?",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",0,4,"o",31,0,-1,0,66,66,"","",72,"","","",4,0,0,[],""],["andina_t1-p0066-12",11,"Carita de papel fino,\nnariz de pluma tajada,\nojo de letra menuda,\nboca de carta cerrada.",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",0,4,"aa",49,0,-1,0,66,66,"","",72,"","","",3,0,0,[],""],["andina_t1-p0066-12-e2",11,"En tu puerta sembré un pino\ny en tu ventana un cerezo;\ncada pino es un abrazo,\ncada cerezo es un beso.",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",0,4,"eo",48,0,-1,0,66,66,"","",72,"","","",3,0,0,[],""],["andina_t1-p0066-13",11,"Eres como la hoja de ñame\nque no consiente rocío;\ndices que tienes vergüenza\ny nunca la has conocido.",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",0,4,"io",-1,0,-1,0,66,67,"","",72,"","","",1,0,0,[],""],["andina_t1-p0067-01",11,"Boca de canasto viejo\nharto de botar basura;\nquién te manda a conversar\nsi la lengua no te ayuda.",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",0,4,"ua",-1,0,-1,0,67,67,"","",72,"","","",1,0,0,[],""],["andina_t1-p0067-02",11,"Ni soy clavo ni soy rosa\nni soy nada de comer;\nni tengo gracia ninguna,\nfavor que me quiere hacer.",200,4,-1,-1,"(En el baile, la mujer dice y el hombre le contesta)",0,4,"e",20,0,-1,0,67,67,"","",72,"","","",1,0,0,[],""],["andina_t1-p0067-03",11,"Dormite niñito\nque tengo que hacer\nlavar los pañales\ny hacer de comer.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"e",20,0,-1,0,67,67,"","",72,"","","",4,0,0,[],""],["andina_t1-p0067-04",11,"Dormite niñito\nsin tanto alboroto\nque tu pepa y tu mama\nestán haciendo el otro.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"oo",-1,0,-1,0,67,67,"","",72,"","","",4,0,0,[],""],["andina_t1-p0067-05",11,"Dormite niñito\nque estás en la cuna\nque no hay mazamorra\nni cosa ninguna.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"ua",56,0,-1,0,67,67,"","",72,"","","",4,0,0,[],""],["andina_t1-p0067-06",11,"Dormite niñito\ndormite ya\nque viene la coca\ny te comerá.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",6,4,"a",9,0,-1,0,67,67,"","",72,"","","",4,0,0,[],""],["andina_t1-p0067-07",11,"Duérmete mi niño\nduérmete ya\nque viene el coco\ny te comerá.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",6,4,"a",9,0,-1,0,67,67,"","",72,"","","",2,0,0,[],""],["andina_t1-p0067-08",11,"Dormite mi niño\nque tengo que hacer\nlavar los pañales\ny hacer de comer.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"e",20,0,-1,0,67,67,"","",72,"","","",2,0,0,[],""],["andina_t1-p0067-09",11,"Y matar la gallina\ny echarla a cocer\nllamar e Juancito\nque venga a comer.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"e",20,0,-1,0,67,67,"","",72,"","","",1,0,0,[],""],["andina_t1-p0067-10",11,"Duérmete mi niño\nyo te dormiré\ncon la maraquita\nde Julián José.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"e",77,0,-1,0,67,67,"","",72,"","","",2,0,0,[],""],["andina_t1-p0067-11",11,"Dormite niño.\nde tanto llorar\nque solo tu mama\nte puede aguantar.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",6,4,"a",-1,0,-1,0,67,67,"","",72,"","","",1,0,0,[],""],["andina_t1-p0067-12",11,"Dormite niñita\nque tengo que hacer\nmatar la gallina\ny echarla a cocer.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"e",20,0,-1,0,67,67,"","",72,"","","",2,0,0,[],""],["andina_t1-p0067-13",11,"Dormite niña\nque estás en la cuna\nsin padre ni madre\nni hermana ninguna.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",6,4,"ua",56,0,-1,0,67,67,"","",72,"","","",1,0,0,[],""],["andina_t1-p0067-14",11,"Este niño quiere\nque lo duerma yo\nduérmalo su madre\nque ella lo encargó.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"o",2,0,-1,0,67,67,"","",72,"","","",1,0,0,[],""],["andina_t1-p0067-15",11,"El niño quera\nque lo cante yo\nque lo cante la mama\nque lo parió.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",6,4,"o",2,0,-1,0,67,67,"","",72,"","","",1,0,0,[],""],["andina_t1-p0068-01",11,"Señor San Joaquín\nSeñora Santa Ana\ndormite niño\ncon toda tu gana",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",6,4,"aa",4,0,-1,0,68,68,"","",72,"","","",4,0,0,[],""],["andina_t1-p0068-02",11,"Señora Santa Ana\nseñor San Joaquín\nacuésteme el niño\nque quiere dormir.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"i",-1,0,-1,0,68,68,"","",72,"","","",8,0,0,[],""],["andina_t1-p0068-03",11,"-Señor San Joaquín\nseñora Santa Ana\nporque llora el niño?—\n—Por una manzana—.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"aa",4,0,-1,0,68,68,"","",72,"","","",4,0,0,[],""],["andina_t1-p0068-04",11,"Yo le daré una\nyo le daré dos\nuna para el Niño\ny otra para vos.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",3,4,"o",87,0,-1,0,68,68,"","",72,"","","",1,0,0,[],""],["andina_t1-p0068-05",11,"Señora Santa Ana\nporqué llora el niño\npor una manzana\nque se le ha perdido.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"io",-1,0,-1,0,68,68,"","",72,"","","",8,0,0,[],""],["andina_t1-p0068-06",11,"Que no llore el niño\nque yo le doy dos\nuna para el Niño\ny otra para vos.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",1,4,"o",87,0,-1,0,68,68,"","",72,"","","",1,0,0,[],""],["andina_t1-p0068-07",11,"Señora Santa Ana\n¿por qué llora el niño?\npor una manzana\nque se le ha perdido.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",0,4,"io",-1,0,-1,0,68,68,"","",72,"","","",8,0,0,[],""],["andina_t1-p0068-08",11,"Yo te traigo una\nyo te traigo dos\nuna para el niño\ny otra para vos.",200,4,-1,-1,"COPLAS HEXASILABAS Arrullos",3,4,"o",87,0,-1,0,68,68,"","",72,"","","",1,0,0,[],""],["andina_t1-p0068-09",11,"De allá abajo vengo\nrecogiendo flores\npara hacer un ramo\nde varios colores.",200,4,-1,-1,"De Adoración al Niño",0,4,"oe",5,0,-1,0,68,68,"","",72,"","","",1,0,0,[],""],["andina_t1-p0068-10",11,"De jazmín y rosas\nmirtos y claveles\nllevan la corona\nal Rey de tos reyes.",200,4,-1,-1,"De Adoración al Niño",0,4,"ee",-1,0,-1,0,68,68,"","",72,"","","",1,0,0,[],""],["andina_t1-p0068-11",11,"La mata de higuera.\nflorió en nochebuena;\ncomo es tan hermosa\nflorea una azucena",200,4,-1,-1,"De Adoración al Niño",0,4,"ea",59,0,-1,0,68,68,"","",72,"","","",1,0,0,[],""],["andina_t1-p0068-12",11,"Hoy con tantas flores\nlos campos se alegran\nSerafines cantan\nMaría gracia plena.",200,4,-1,-1,"De Adoración al Niño",0,4,"ea",-1,0,-1,0,68,68,"","",72,"","","",1,0,0,[],""],["andina_t1-p0068-13",11,"Aguinaldos nuevos\ntengo en mi memoria\nhoy los canto aquí\nmañana en la gloria.",200,4,-1,-1,"De Adoración al Niño",0,4,"oa",126,0,-1,0,68,68,"","",72,"","","",1,0,0,[],""],["andina_t1-p0068-14",11,"A la medianoche\nde estar encerrado\nnació de su vientre\nblanco y encarnado.",200,4,-1,-1,"De Adoración al Niño",0,4,"ao",14,0,-1,0,68,68,"","",72,"","","",3,0,0,[],""],["andina_t1-p0068-15",11,"A los nueve meses,\nde estar encerrado\nnació de su vientre\nblanco y encarnado.",200,4,-1,-1,"De Adoración al Niño",0,4,"ao",14,0,-1,0,68,68,"","",72,"","","",1,0,0,[],""],["andina_t1-p0068-16",11,"El infierno tiembla\nel demonio llora\nde ver que ha nacido\nel Rey de la gloria.",200,4,-1,-1,"De Adoración al Niño",0,4,"oa",-1,0,-1,0,68,68,"","",72,"","","",2,0,0,[],""],["andina_t1-p0069-01",11,"Pasito, pasito\nque ha nacido un sol\nque a todos alumbra\ncon su resplandor",200,4,-1,-1,"De Adoración al Niño",0,4,"o",-1,0,-1,0,69,69,"","",72,"","","",1,0,0,[],""],["andina_t1-p0069-02",11,"De aquella tapia abajo\nbaja una araña\ncocuy de mi vida, ja, ja,\ncon el culo pa lo alto\nvida del alma\nqué mala maña.",200,4,-1,-1,"Seguidillas (Recogidas en el Estado Metida)",9,6,"aa",-1,0,-1,0,69,69,"","",72,"","","",1,0,0,[],""],["andina_t1-p0069-03",11,"En la puerta del cielo\nvenden zapatos\ncocuy de mi vida, ja, ja,\npara los angelitos\nvida del alma\nque van descalzos.",200,4,-1,-1,"Seguidillas (Recogidas en el Estado Metida)",9,6,"ao",-1,0,-1,0,69,69,"","",72,"","","",7,0,0,[],""],["andina_t1-p0069-04",11,"En la puerta del cielo\nvenden hallacas\nveinticinco por medio\ny una de ñapa;",200,4,-1,-1,"Seguidillas (Recogidas en el Estado Metida)",6,4,"aa",-1,0,-1,0,69,69,"","",72,"","","",7,0,0,[],""],["andina_t1-p0069-05",11,"En la puerta del cielo\nvenden cebollas,\nperejil y culantro\npara las ollas.",200,4,-1,-1,"Seguidillas (Recogidas en el Estado Metida)",6,4,"oa",467,0,-1,0,69,69,"","",72,"","","",7,0,0,[],""],["andina_t1-p0069-06",11,"Una monja y un cura\ndurmieron juntos,\nporque les metían miedo\ncon los difuntos.",200,4,-1,-1,"Seguidillas (Recogidas en el Estado Metida)",6,4,"uo",296,0,-1,0,69,69,"","",72,"","","",1,0,0,[],""],["andina_t1-p0069-07",11,"En la torre más alta\ndel consistorio,\nestá mi amante preso:\nlas voces le oigo.",200,4,-1,-1,"Seguidillas (Recogidas en el Estado Metida)",6,4,"oo",-1,0,-1,0,69,69,"","",72,"","","",3,0,0,[],""],["andina_t1-p0069-08",11,"En la orilla del río\nparió una blanca,\nveinticinco alacranes\ny una potranca.",200,4,-1,-1,"(el estribillo sigue igual) (Recogidas en la Isla de Margarita)",6,4,"aa",75,0,-1,0,69,69,"","",72,"","","",3,0,0,[],""],["andina_t1-p0069-09",11,"En la orilla del rio\nparió una negra,\nveinticinco alacranes\ny una culebra.",200,4,-1,-1,"(el estribillo sigue igual) (Recogidas en la Isla de Margarita)",6,4,"ea",-1,0,-1,0,69,69,"","",72,"","","",3,0,0,[],""],["andina_t1-p0069-10",11,"En la puerta del cielo\nvenden cangrejos,\npara los angelitos\nque van sin ellos.",200,4,-1,-1,"(el estribillo sigue igual) (Recogidas en la Isla de Margarita)",6,4,"eo",-1,0,-1,0,69,69,"","",72,"","","",7,0,0,[],""],["andina_t1-p0069-11",11,"En la puerta del cielo\nvenden zapatos,\npara los angelitos\nque van descalzos.",200,4,-1,-1,"(el estribillo sigue igual) (Recogidas en la Isla de Margarita)",6,4,"ao",-1,0,-1,0,69,69,"","",72,"","","",7,0,0,[],""],["andina_t1-p0069-12",11,"Si yo fuera rica\ny tuviera mis modos,\nle compraría a mi niña\nuna cuna de oro.",200,4,-1,-1,"(el estribillo sigue igual) (Recogidas en la Isla de Margarita)",0,4,"oo",-1,0,-1,0,69,69,"","",72,"","","",1,0,0,[],""],["andina_t1-p0069-13",11,"¿Qué quieres que te traiga,\nniña, de Coro?\nPara tu mano blanca\nsortija de oro.",200,4,-1,-1,"(el estribillo sigue igual) (Recogidas en la Isla de Margarita)",6,4,"oo",85,0,-1,0,69,70,"","",72,"","","",5,0,0,[],""],["andina_t1-p0070-10",11,"Taqui ti tá el coroso.\ntaqui ti taino mí\nAmor, amor, amor.\nQue en el amor me duermo.\nAmor, desesperado amor.",200,4,-1,-1,"Estrofas Varias con Estribillo",7,5,"o",-1,0,-1,0,70,70,"","",72,"","","",1,0,0,[],""],["andina_t1-p0071-02",11,"Con los rayos de la luna\ny los clarores del sol,\naunque me cueste la vida\nsigo tocando el tambor.",200,4,-1,-1,"Estrofas Varias con Estribillo",0,4,"o",-1,0,-1,0,71,71,"","",72,"","","",2,0,0,[],""],["andina_t1-p0071-04",11,"El que cantare conmigo\ntiro a tiro, cuero a cuero,\nse comerá los mamones\npero me deja el conchera.",200,4,-1,-1,"Estrofas Varias con Estribillo",5,4,"ea",-1,0,-1,0,71,71,"","",72,"","","",4,0,0,[],""],["andina_t1-p0071-06",11,"Señores los bailadores\nno bailen tan de carrera,\nque con la punta 'e los pies\nlevantan la polvasera.",200,4,-1,-1,"Estrofas Varias con Estribillo",0,4,"ea",44,0,-1,0,71,71,"","",72,"","","",2,0,0,[],""],["andina_t1-p0071-07",11,"Ay, llové llové, aguacero,\nay, llové llové.\nOló lo lo ó\nolóloloé.",200,4,-1,-1,"Estrofas Varias con Estribillo",6,4,"e",77,0,-1,0,71,71,"","",72,"","","",1,0,0,[],""],["andina_t1-p0071-08",11,"Y ahora sí que se juntaron\ntres pollos 'e la misma cría;\noló lo lo é,\nno nací en Santa Teresa,\nyo soy de Santa Lucía\nOló lo lo ó",200,4,-1,-1,"Estrofas Varias con Estribillo",9,6,"o",-1,0,-1,0,71,71,"","",72,"","","",1,0,0,[],""],["andina_t1-p0071-09",11,"Para que cantes conmigo\ncoge la décima mía;\nOlo lo lo ó\nya yo te voy a empezé.\nlos versos en poesía\nOló lo lo ó",200,4,-1,-1,"Estrofas Varias con Estribillo",9,6,"o",-1,0,-1,0,71,71,"","",72,"","","",1,0,0,[],""],["andina_t1-p0071-10",11,"Ayer tarde estaba yo\nque por muerta me velaban;\noló lo lo ó\ny con la luz de tus ojos\nmuerta me resucitaban.\nOló lo lo ó\noló lo lo é.",200,4,-1,-1,"Estrofas Varias con Estribillo",4,7,"e",-1,0,-1,0,71,71,"","",72,"","","",2,0,0,[],""],["andina_t1-p0071-11",11,"Oló lo lo ó,\nTan bonita que era yo\noló lo lo é\ny tan fea que me he pue'to;\noló lo lo ó\ntan flaca y tan amarilla\nque a la muerte me pere'co.",200,4,-1,-1,"Estrofas Varias con Estribillo",4,7,"eo",-1,0,-1,0,71,72,"","",72,"","","",1,0,0,[],""],["andina_t1-p0072-01",11,"Yo comí de la verbena,\ndel corozo lo baboso;\npensando que era caballo\nle tire la silla a un oso;\ny un animal tan chiquito\ny su golpe tan sabroso.",200,4,-1,-1,"SEXTILLAS",9,6,"oo",160,0,-1,0,72,72,"","",72,"","","",1,0,0,[],""],["andina_t1-p0072-02",11,"No me cantes con aluma,\ncanta con filosofía;\nsi en caso te preguntaran\nque si me canta turnia,\nseguí mete así cantando\nse gana su simpatía.",200,4,-1,-1,"SEXTILLAS",9,6,"ia",0,0,-1,0,72,72,"","",72,"","","",1,0,0,[],""],["andina_t1-p0072-03",11,"Lucero de la mañana,\nlucero de todo el día.\nMuchachas del otro lado,\nrueguen por la vida mía;\nporque me voy e embarcar\nen una lancha podría.",200,4,-1,-1,"SEXTILLAS",9,6,"ia",0,0,-1,0,72,72,"","",72,"","","",22,0,0,[],""],["andina_t1-p0072-04",11,"Yo vide una garza blanca\npintando una lotería;\nla pintaba con el pico\nporque manos no tenía;\ny no la pintó tan buena\ncomo yo pinté la mía.",200,4,-1,-1,"SEXTILLAS",9,6,"ia",0,0,-1,0,72,72,"","",72,"","","",1,0,0,[],""],["andina_t1-p0072-05",11,"Una vieja se sentó\narriba de una sepultura,\ny el muerto sacó la mano\ny le agarró la hermosura\n¡Ah placer que a mí me da\ny con mi vaca Cerradural",200,4,-1,-1,"SEXTILLAS",9,6,"a",-1,0,-1,0,72,72,"","",72,"","","",5,0,0,[],""],["andina_t1-p0072-06",11,"No sé que será de mí\nasí tú me eches en olvido;\nyo entre las nueve y las once\nestoy por hablar contigo;\ny canto por el esquilón\ncuando me salgo del hilo.",200,4,-1,-1,"SEXTILLAS",9,6,"io",-1,0,-1,0,72,72,"","",72,"","","",1,0,0,[],""],["andina_t1-p0072-07",11,"Yo soy el que me paseo\nde la noche a la mañana;\ncuando tengo mi voz buena\nhago lo que me de gana:\nde mi pecho hago una torre\ny de mi voz una campana.",200,4,-1,-1,"SEXTILLAS",9,6,"aa",4,0,-1,0,72,72,"","",72,"","","",1,0,0,[],""],["andina_t1-p0072-08",11,"Si el gavilán se comiera\ncomo se come el venado,\nya yo me hubiera comido\nel gavilán colorado,\npa quítale la querencia\nque tiene en el otro lado.",200,4,-1,-1,"SEXTILLAS",9,6,"ao",14,0,-1,0,72,72,"","",72,"","","",2,0,0,[],""],["andina_t1-p0072-09",11,"Cómo quieres que te brinde\nsi tengo limpio el bolsillo;\nyo también 'taba en Caracas\ncuando llegó el baratillo:\ncuatro muchachas por medio\ny ocho viejas por cuartillo.",200,4,-1,-1,"SEXTILLAS",9,6,"io",228,0,-1,0,72,72,"","",72,"","","",1,0,0,[],""],["andina_t1-p0072-10",11,"Te convido pa que vamos\na un paseo a mi guarida,\npa que veas cabellos buenos\ny pollos de buena cría;\ny cómo me niegas un pollo\nsiendo la gallina mía.",200,4,-1,-1,"SEXTILLAS",9,6,"ia",0,0,-1,0,72,72,"","",72,"","","",1,0,0,[],""],["andina_t1-p0072-11",11,"Yo fui quien le di candela\nal cañaveral de Juana,\ny después que cogió fuego\nhice lo que me dio gana;\ny e quien no le ve a dá gusto\nordenando a mi vaca Botana",200,4,-1,-1,"SEXTILLAS",9,6,"aa",4,0,-1,0,72,72,"","",72,"","","",1,0,0,[],""],["andina_t1-p0073-01",11,"Llegándose a la verde\nsoy un cuadro de tristeza;\nel burro carga en el lomo\ny el bechaco en la cabeza;\ny el que no lleva la carga\nle parece que no pesa.",200,4,-1,-1,"SEXTILLAS",9,6,"ea",201,0,-1,0,73,73,"","",72,"","","",1,0,0,[],""],["andina_t1-p0073-02",11,"Muchachita y buenamoza\nparecen dos hermanitos.\nuna come en el estero\ny la otra en los medanitos,\ny una carga la jaula\ny la otra los pajaritos.",200,4,-1,-1,"SEXTILLAS",9,6,"io",254,0,-1,0,73,73,"","",72,"","","",1,0,0,[],""],["andina_t1-p0073-03",11,"Adiós romerito verde,\nespejito delicado;\nentre más lejos estoy\npretendo estar a tu lado.",200,4,-1,-1,"COPLAS ENCADENADAS",0,4,"ao",14,0,-1,0,73,73,"","",72,"","","",1,0,0,[],""],["andina_t1-p0073-04",11,"Pretendo estar a tu lado\ncontándote mis aiciones;\ndos amantes se despiden\npero no los corazones.",200,4,-1,-1,"COPLAS ENCADENADAS",0,4,"oe",34,0,-1,0,73,73,"","",72,"","","",1,0,0,[],""],["andina_t1-p0073-06",11,"Ingrata desconocida,\nrecorre tu pensamiento;\nmire que yo soy aquella\nque adorabas en un tiempo.",200,4,-1,-1,"COPLAS ENCADENADAS",0,4,"eo",-1,0,-1,0,73,73,"","",72,"","","",2,0,0,[],""],["andina_t1-p0073-07",11,"En un tiempo era yo,\nera tu amante querida;\ny hora por nuevos amores\nme tienes aborrecida.",200,4,-1,-1,"COPLAS ENCADENADAS",0,4,"ia",37,0,-1,0,73,73,"","",72,"","","",1,0,0,[],""],["andina_t1-p0073-08",11,"Aborrecida me tienes,\nyo no sé por qué será;\nque si es por lo enamorada\nlo mismo es aquí que allá.",200,4,-1,-1,"COPLAS ENCADENADAS",0,4,"a",9,0,-1,0,73,73,"","",72,"","","",1,0,0,[],""],["andina_t1-p0074-01",11,"Yo tenía un turpial primoroso\ncuyas plumas el sol envidió,\ny tenía un cantar tan precioso\nque hasta el trono de Dios se elevó.",200,4,-1,-1,"CANCIONES",3,4,"o",2,0,-1,0,74,74,"","",72,"","","",1,0,0,[],""],["andina_t1-p0075-01",11,"Hoy sólo cruzan por la mente mía\ntristes recuerdos que a mi alma hieren;\npero las buenas como tú, María,\nse van del mundo pero nunca mueren.",200,4,-1,-1,"María",3,4,"ee",670,0,-1,0,75,75,"","",72,"","","",1,0,0,[],""],["andina_t1-p0075-03",11,"Hoy agobiado de dolor profundo\nen vano busco por doquier consuelo;\nhorrible abismo me parece el mundo\ny sus placeres para mí son duelo.",200,4,-1,-1,"María",3,4,"eo",10,0,-1,0,75,75,"","",72,"","","",1,0,0,[],""],["andina_t1-p0075-04",11,"Y cuando pienso de dolor transido\nen el alma soñada por los dos,\nsale una frase de mi pecho herido:\n¡Adiós María, para siempre adiós!",200,4,-1,-1,"María",3,4,"o",87,0,-1,0,75,75,"","",72,"","","",1,0,0,[],""],["andina_t1-p0075-05",11,"La noche triste, oscura y tenebrosa;\ntú duermes y tu sueño no es turbado,\nporque el amor con su aroma, de rosas,\nel santuario de tu alma no ha tocado.",200,4,-1,-1,"La Noche Triste",3,4,"ao",14,0,-1,0,75,75,"","",72,"","","",1,0,0,[],""],["andina_t1-p0075-08",11,"Ya me parece verte reclinada\nsobre tu lecho blanco y perfumado,\ncomo una diosa del Olimpo enviada\ny buscando un ideal ya realizado.",200,4,-1,-1,"La Noche Triste",3,4,"ao",14,0,-1,0,75,75,"","",72,"","","",1,0,0,[],""],["andina_t1-p0093-02a",11,"La Virgen va caminando\nY extendiendo en el romero\nLos ángeles van cantando\nLas aguas se suspendieron",201,3,-1,-1,"Romance de la Virgen Canamente",0,4,"eo",-1,0,-1,0,93,93,"","",72,"","","",12,0,0,[],""],["andina_t1-p0093-02b",11,"La Virgen va caminando\nDebajo del verde olivo\nLas hojas se desgranaron\nPara no mojar al Niño.",201,3,-1,-1,"Romance de la Virgen Canamente",0,4,"io",-1,0,-1,0,93,93,"","",72,"","","",12,0,0,[],""],["andina_t1-p0094-01",11,"Sacratísima Marta,\nque todos los nombres alaban;\nquiero saber de qué suerte,,\nse aparta el cuerpo del alma.",201,3,-1,-1,"Salve",0,4,"aa",-1,0,-1,0,94,94,"","",72,"","","",1,0,0,[],""],["andina_t1-p0094-05",11,"Con esto no digo más,\ndoblen todas las campanas,\ntraigan una cruz por mí,\nque ya se arranca el alma",201,3,-1,-1,"Salve",0,4,"aa",-1,0,-1,0,94,94,"","",72,"","","",2,0,0,[],""],["andina_t1-p0094-07",11,"—Anda, muerta, y vuelva luego,\nporque ahora estoy ocupado;\nque no puedo recibirte\nun agasajo de tu mano.",201,3,-1,-1,"Salve",0,4,"ao",-1,0,-1,0,94,94,"","",72,"","","",1,0,0,[],""],["andina_t1-p0094-09",11,"Ahí no te vale pariente,\n\\-.. -ni hermanito, ni papá.\nTe valen las buenas obras,\nsi por acaso las habéis hecho.",201,3,-1,-1,"Salve",3,4,"eo",-1,0,-1,0,94,94,"","",72,"","","",1,0,0,[],""],["andina_t1-p0094-11",11,"Allá en ese río,\nque llaman Iró,\nlo tienen en duda\nla muerte de Dios.",201,3,-1,-1,"\"Romance\"",0,4,"o",-1,0,-1,0,94,94,"","",72,"","","",1,0,0,[],""],["andina_t1-p0094-12",11,"¿Cuál es ese niño\nque no sabe hablar?\n¿Por qué no le enseñan,\nque diga papá?",201,3,-1,-1,"\"Romance\"",0,4,"a",-1,0,-1,0,94,94,"","",72,"","","",1,0,0,[],""],["andina_t1-p0094-13",11,"Adiós, papacito,\npapacito, adiós.\nDéme Usted su mano\npa' decirle adiós.",201,3,-1,-1,"\"Romance\"",0,4,"o",-1,0,-1,0,94,94,"","",72,"","","",1,0,0,[],""],["andina_t1-p0094-14",11,"¿Cuál es esa niña\nque no sabe hablar?\n¿Por qué no le enseñan,\nque diga mamá?",201,3,-1,-1,"\"Romance\"",0,4,"a",-1,0,-1,0,94,94,"","",72,"","","",1,0,0,[],""],["andina_t1-p0095-04",11,"Al pasar Condoto\ny el río de Iró,\nabrí tus ojitos\npe' decirte adiós.",201,3,-1,-1,"Romance paragualí",0,4,"o",-1,0,-1,0,95,95,"","",72,"","","",1,0,0,[],""],["andina_t1-p0095-05",11,"Matica de tomate,\nte quiero sembrar,\npero no te siembro\npor falta de lugar.",201,3,-1,-1,"Romance paragualí",0,4,"a",21,0,-1,0,95,95,"","",72,"","","",1,0,0,[],""],["andina_t1-p0095-06",11,"Matica de cilantro,\nte quiero sembrar;\npero no te siembro\npor falta de lugar.",201,3,-1,-1,"Romance paragualí",0,4,"a",21,0,-1,0,95,95,"","",72,"","","",1,0,0,[],""],["andina_t1-p0095-07",11,"Matica de polea,\nte quiero sembrar;\npero no te siembro,\npor falta de lugar",201,3,-1,-1,"Romance paragualí",0,4,"a",21,0,-1,0,95,95,"","",72,"","","",1,0,0,[],""],["andina_t1-p0095-11",11,"De todo eso Blancaflor\nLe cuenta el Emperador\nY cogieron al pastor\nY lo ahorcaron por traidor\nEn el sitio en que violara\nA la hermana de Blancaflor.",201,3,-1,-1,"Romance de Blancaflor y Filomena",9,6,"o",72,0,-1,0,95,95,"","",72,"","","",1,0,0,[],""],["andina_t1-p0097-01",11,"En Francia nace un niño,\n¡qué horror, que horror, que pena!\nEn Francia nace un niño,\nde padre militar,\ndorremí, dorrefá,\nde padre militar.",201,3,-1,-1,"Mambrú",9,6,"a",-1,0,-1,0,97,97,"","",72,"","","",1,0,0,[],""],["andina_t1-p0097-11",11,"Encima de la tapa\nuna corona va.\nEncima de la corona\nuna tarjeta va.",201,3,-1,-1,"Mambrú",0,4,"a",-1,0,-1,0,97,97,"","",72,"","","",1,0,0,[],""],["andina_t1-p0098-06",11,"Contaste la hormiga\nen su bodega,\nque siga la boda,\nque yo doy manteca.",201,3,-1,-1,"Elpiojoy la pulga",6,4,"ea",-1,0,-1,0,98,98,"","",72,"","","",1,0,0,[],""],["andina_t1-p0098-07",11,"Ahora manteca,\nque ya la tenemos,\nahora por tomate,\n¿adonde hallaremos?",201,3,-1,-1,"Elpiojoy la pulga",0,4,"eo",127,0,-1,0,98,98,"","",72,"","","",1,0,0,[],""],["andina_t1-p0098-08",11,"Contesta el conejo\nen su tomatal:\nque siga la boda,\nyo lo voy a dar.",201,3,-1,-1,"Elpiojoy la pulga",0,4,"a",-1,0,-1,0,98,98,"","",72,"","","",1,0,0,[],""],["andina_t1-p0098-09",11,"Ahora tomate,\nque ya lo tenemos.\nahora por vino,\n¿adonde hallaremos?",201,3,-1,-1,"Elpiojoy la pulga",0,4,"eo",127,0,-1,0,98,98,"","",72,"","","",1,0,0,[],""],["andina_t1-p0098-10",11,"Contesta el gorgojo\nen el camino:\nque siga la boda,\nque yo doy el vino.",201,3,-1,-1,"Elpiojoy la pulga",6,4,"io",199,0,-1,0,98,98,"","",72,"","","",1,0,0,[],""],["andina_t1-p0098-11",11,"Ahora el vino,\nque ya lo tenemos,\nahora por padrino,\n¿adonde hallaremos?",201,3,-1,-1,"Elpiojoy la pulga",6,4,"eo",127,0,-1,0,98,98,"","",72,"","","",1,0,0,[],""],["andina_t1-p0098-12",11,"Contesta el ratón\nen el madrigal:\nsi amarran el gato,\nyo voy a apadrinar.",201,3,-1,-1,"Elpiojoy la pulga",0,4,"a",-1,0,-1,0,98,98,"","",72,"","","",1,0,0,[],""],["andina_t1-p0098-13",11,"Estando en la boda\ny tomándose el vino,\nsoltaron el gato,\ny se comió al padrino.",201,3,-1,-1,"Elpiojoy la pulga",0,4,"io",199,0,-1,0,98,98,"","",72,"","","",1,0,0,[],""],["andina_t1-p0099-03",11,"- Arrurrú mi niño,\nmi niño adorado\nmi chirriquitico\nmi clavel rosado.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"ao",14,0,-1,0,99,99,"","",72,"","","",1,0,0,[],""],["andina_t1-p0099-05",11,"Si este niño se durmiera\nle pagaba medía riel,\ny cuando se dispertara\nse lo compraría de pan.",201,3,-1,-1,"Arrullo * y canciones infantiles",5,4,"a",-1,0,-1,0,99,99,"","",72,"","","",1,0,0,[],""],["andina_t1-p0100-05",11,"Este niño llora\nno hay quién lo consuela\nel último arrullo\nde su madre quiere.",201,3,-1,-1,"Arrullo * y canciones infantiles",5,4,"ee",-1,0,-1,0,100,100,"","",72,"","","",1,0,0,[],""],["andina_t1-p0100-06",11,"Ayúdame, prima,\ncon esta canción,\nporque se me arranca\nhasta el corazón.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"o",31,0,-1,0,100,100,"","",72,"","","",1,0,0,[],""],["andina_t1-p0100-08",11,"vamos a la playa.\nQue hay mucho que ver\nLa gallina enana\nCon el gallo inglés.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"e",-1,0,-1,0,100,100,"","",72,"","","",3,0,0,[],""],["andina_t1-p0100-09",11,"Vamos a la playa.\nDe la playa vengo;\nDe bailar el fandango\nMe vengo muriendo.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"eo",-1,0,-1,0,100,100,"","",72,"","","",3,0,0,[],""],["andina_t1-p0101-02",11,"Dormita, mi niño\nQue vengo a traerte\nUna blanca rosa\nCon hojitas verdes.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"ee",-1,0,-1,0,101,101,"","",72,"","","",1,0,0,[],""],["andina_t1-p0101-03",11,"Al otro lado del río\nCanta y silva un canagüí\nEn el silbidito dice:\nQue viva Manuel Ortiz.",201,3,-1,-1,"Arrullo * y canciones infantiles",3,4,"i",-1,0,-1,0,101,101,"","",72,"","","",13,0,0,[],""],["andina_t1-p0101-04",11,"Dame un besito, mi vida.\nQue estoy con dolor de muela;\nEse que me diste anoche\nMe supo a clavo y canela.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"ea",167,0,-1,0,101,101,"","",72,"","","",3,0,0,[],""],["andina_t1-p0101-06",11,"Matica de yerbabuena,\nFrasquito de agua de olor,\nNo te vas a derramar\nEn otro pecho traidor.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"o",72,0,-1,0,101,101,"","",72,"","","",1,0,0,[],""],["andina_t1-p0101-08",11,"A la una nací yo.\nA las dos me bautizaron.\nA las tres supe de amores.\nA las cuatro me casaron.\nA las cinco tuve un hijo.\nA las seis lo bautizaron.\nA las siete fue ladrón.\nA las ocho lo mataron.\nPara ensañarte a ser hombre\nY estimar a una mujer.",201,3,-1,-1,"Arrullo * y canciones infantiles",18,10,"e",-1,0,-1,0,101,101,"","",72,"","","",7,0,0,[],""],["andina_t1-p0101-09",11,"Ya viene la vaca.\nYa vierte al ternero.\nLa niña bonita\nSe muere de miedo.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"eo",-1,0,-1,0,101,101,"","",72,"","","",1,0,0,[],""],["andina_t1-p0101-10",11,"Ya viene la luna.\nYa viene el lucero,\nA hacerte una almohadita\nDe albahaca y romero.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"eo",38,0,-1,0,101,101,"","",72,"","","",1,0,0,[],""],["andina_t1-p0101-12",11,"La señora luna\nSe quiere casar.\nCon el Jovencito\nDe la casa real.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"a",-1,0,-1,0,101,101,"","",72,"","","",1,0,0,[],""],["andina_t1-p0101-13",11,"Ayer pasé por tu calle,\nY por la otra di la vuelta,\nSólo por verte la cara,\nGrandísima sin vergüenza.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"ea",-1,0,-1,0,101,101,"","",72,"","","",3,0,0,[],""],["andina_t1-p0101-14",11,"De la naranja comí\nDel cogollo la mitad.\nNo hay cosita más amarga\nQue el amor sin voluntad.",201,3,-1,-1,"Arrullo * y canciones infantiles",0,4,"a",16,0,-1,0,101,101,"","",72,"","","",1,0,0,[],""],["andina_t1-p0102-02",11,"A las siete fue a la escuela.\nA las ocho le enseñaron.\nA las nueve cayó quinto.\nA las diez se fue soldado.\nA las once ya fue muerto.\nA las doce lo enterraron.",201,3,-1,-1,"Arrullo * y canciones infantiles",9,6,"ao",-1,0,-1,0,102,102,"","",72,"","","",1,0,0,[],""],["andina_t1-p0107-02",11,"\" Cuando vino el hombre al mundo\nen muy triste situación\nera entonces el león\nel rey de los animales... \"",201,3,-1,-1,"Ensaladillas",5,4,"ae",-1,0,-1,0,107,107,"","",72,"","","",1,0,0,[],""],["andina_t1-p0108-02",11,"Hoy pregunto a la Memoria\ndiga de sabiduría\n¿qué cosas mi Dios haría\nantes de formar la gloria?",201,3,-1,-1,"Ensaladillas",11,4,"oa",126,0,-1,0,108,108,"","",72,"","","",1,0,0,[],""],["andina_t1-p0108-03",11,"Ya se murieron mis perros\nya quedó mi rancho sólo;\nahora me muero yo\npara que se acabe todo.",201,3,-1,-1,"Ensaladillas",0,4,"oo",-1,0,-1,0,108,108,"","",72,"","","",2,0,0,[],""],["andina_t1-p0108-04",11,"Yo no como en reunión\nporque yo no soy soidao\ny yo no salgo a rodeo\nporque yo no soy ganao.",201,3,-1,-1,"Ensaladillas",0,4,"ao",98,0,-1,0,108,108,"","",72,"","","",2,0,0,[],""],["andina_t1-p0108-05",11,"Yo no le temo a las balas\nni a cuchillo ni a puñales\nni a hombres de vara y media\no de dos varas cabales.",201,3,-1,-1,"Ensaladillas",0,4,"ae",26,0,-1,0,108,108,"","",72,"","","",1,0,0,[],""],["andina_t1-p0108-06",11,"Los ricos son pobres ricos\nque no tienen sino plata\nen cambio en pobre de yo\ngozo con mi alpargata.",201,3,-1,-1,"Ensaladillas",0,4,"aa",74,0,-1,0,108,108,"","",72,"","","",1,0,0,[],""],["andina_t1-p0108-07",11,"No es lo mismo sol que luna\naunque viva alumbrando\nni iguales son los caballos\naunque habiten relinchando.",201,3,-1,-1,"Ensaladillas",0,4,"ao",-1,0,-1,0,108,108,"","",72,"","","",1,0,0,[],""],["andina_t1-p0108-08",11,"Aunque habiten relinchando\nno son igual los caballos\ncomo la luna y el sol\nno lanzan los mismos rayos.",201,3,-1,-1,"Ensaladillas",0,4,"ao",671,0,-1,0,108,108,"","",72,"","","",1,0,0,[],""],["andina_t1-p0108-09",11,"Pongan cuidado mis hijos\nen las cosas de la vida\nlo bueno se ha de aprender\ny lo aprendido se olvida.",201,3,-1,-1,"Ensaladillas",0,4,"ia",37,0,-1,0,108,108,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-02",11,"Y llora mas que un nigua.\nse queja mas que el carrao\nse lamenta mas que el pobre\nque quiere vivir echao.",201,3,-1,-1,"Ensaladillas",0,4,"ao",98,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-03",11,"El negrito se conoce\nen la punta del talón;\nlas patas son cenizosas\ny el pelito chicharrón.",201,3,-1,-1,"Ensaladillas",0,4,"o",31,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-04",11,"La camisa de los pobres\nparece un Jardín de flores.\ntoda llena de remiendos\nde diferentes colores.",201,3,-1,-1,"Ensaladillas",0,4,"oe",5,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-05",11,"Cuando yo tenía mi plata\nme llamaban Don Tomas,\nahora que no tengo nada\nme llaman Tomas no más.",201,3,-1,-1,"Ensaladillas",0,4,"a",51,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-06",11,"Los pobres salimos buenos\ny de buena dentadura;\npor eso a poner semana\nque amor con hambre no dura",201,3,-1,-1,"Ensaladillas",0,4,"ua",17,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-07",11,"Nadie es cumplido en la vida\nporque el justo también peca;\npues el árbol mas florido\nno le falta rama seca.",201,3,-1,-1,"Ensaladillas",0,4,"ea",594,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-08",11,"No quiero sombrero blanco.\nporque no soy caballero.\ncon mi sombrerito negro\nme paso por donde quiero",201,3,-1,-1,"Ensaladillas",0,4,"eo",-1,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-09",11,"Yo soy el poncho borugo\nnacido en la liberta\npor eso es que estoy aquí\nsirviendo de novedé.",201,3,-1,-1,"Ensaladillas",5,4,"e",-1,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-10",11,"La pobreza es una mancha\ny es una mancha morada,\nque en bebiendo cuatro ríales.\nesté la mancha quitada.",201,3,-1,-1,"Ensaladillas",0,4,"aa",49,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-11",11,"Yo no soy tan colorado\ny menos visto de azul;\nyo soy del que esté arriba\ny algo me haya dado.",201,3,-1,-1,"Ensaladillas",5,4,"ao",14,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-12",11,"El hombre que roba al pobre,\nun pavo ó una gallina\nó una moneda de cobre.\nmerece la guillotina.",201,3,-1,-1,"Ensaladillas",1,4,"ia",11,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-13",11,"Por grande que un hombre sea.\nnunca miedo me inspira.\nni que hable, ni que grita\nni que me apriete la barriga.",201,3,-1,-1,"Ensaladillas",0,4,"ia",-1,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-14",11,"Para los males de amor\nlos cataplasmas de olvido\nlos fomentos de otro amor\npero seguido, seguido.",201,3,-1,-1,"Ensaladillas",1,4,"io",101,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-15",11,"Donde hay carbón hay herrero\ndonde hay humo hay llamarada.\ndonde hay amores hay celos\ndonde no hay celos no hay nada.",201,3,-1,-1,"Ensaladillas",0,4,"aa",49,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-16",11,"Si alguna mujer te engaña\nbúscate otra más bonita,\nque la mancha de la mora\ncon mora verde se quita.",201,3,-1,-1,"Ensaladillas",0,4,"ia",50,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-17",11,"No te crees de las mujeres\nni aunque las tengas por tuyas.\nyo tuve cinco amarradas\ny totiaron las cabuyas.",201,3,-1,-1,"Ensaladillas",0,4,"ua",672,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0109-18",11,"Todos no son cazadores\nlos que por el monte van;\nunos cazan las perdices\ny otros las hijas de Adán.",201,3,-1,-1,"Ensaladillas",0,4,"a",147,0,-1,0,109,109,"","",72,"","","",1,0,0,[],""],["andina_t1-p0110-01",11,"El amor de las mujeres\nes como el cordero flaco\nque quitándoles la lana\nsolo queda el guacharaco.",201,3,-1,-1,"Ensaladillas",0,4,"ao",423,0,-1,0,110,110,"","",72,"","","",17,0,0,[],""],["andina_t1-p0110-05",11,"Cuando yo estaba chiquito\ntodas me querían besar;\nhora que estoy grandecito\ntodas se hacen del rogar.",201,3,-1,-1,"Ensaladillas",1,4,"a",21,0,-1,0,110,110,"","",72,"","","",2,0,0,[],""],["andina_t1-p0110-08",11,"Don Galtán tiene un cañón\nqué lo llaman \"bocariegra\"; \"\ncuando ese cañón dispara\nmanda a todos pa' la mierda",201,3,-1,-1,"Ensaladillas",0,4,"ea",-1,0,-1,0,110,110,"","",72,"","","",1,0,0,[],""],["andina_t1-p0110-10",11,"Si el pecho fuer'e cristal,\nse vieran los corazones\nno hubiera falsos amigos,\nse acabaran las traiciones.",201,3,-1,-1,"Ensaladillas",0,4,"oe",34,0,-1,0,110,110,"","",72,"","","",1,0,0,[],""],["andina_t1-p0110-11",11,"Vivo, diciendo y no digo,\nvivo, sin decir, diciendo:\nvivo queriendo y no quiero,\nvivo, sin querer, queriendo.",201,3,-1,-1,"Ensaladillas",0,4,"eo",-1,0,-1,0,110,110,"","",72,"","","",1,0,0,[],""],["andina_t1-p0110-12",11,"Mas vale tenerla lejos\ny tener que caminar\nque no tenerle cerquita\ny no poderla gozar.",201,3,-1,-1,"Ensaladillas",0,4,"a",21,0,-1,0,110,110,"","",72,"","","",1,0,0,[],""],["andina_t1-p0110-13",11,"Yo soy como el tominejo\nque pico de flor en flor,\na todas las enamoro\ny en ninguna pongo amor.",201,3,-1,-1,"Ensaladillas",0,4,"o",-1,0,-1,0,110,110,"","",72,"","","",3,0,0,[],""],["andina_t1-p0110-15",11,"Dicen que el hambre mata,\nyo digo que eso es mentira;\n¿cómo hay gente en Hatoviejo\nsin comer toda la vida?.",201,3,-1,-1,"Ensaladillas",0,4,"ia",-1,0,-1,0,110,110,"","",72,"","","",1,0,0,[],""],["andina_t1-p0110-16",11,"A todo el que te pide date,\nque necesidad tendrá;\nal que tiene se le acaba\ny el que no tiene tendrá;",201,3,-1,-1,"Ensaladillas",0,4,"a",-1,0,-1,0,110,110,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-01",11,"Árbol por qué no floreces\nteniendo l'egua en el pie\nen las ramas la esperanza\ny en el corazón la fé.",201,3,-1,-1,"Ensaladillas",0,4,"e",77,0,-1,0,111,111,"","",72,"","","",2,0,0,[],""],["andina_t1-p0111-03",11,"Me quejo porque me duele,\ny sino, no me quejara;\nquien será aquel que se queja\nsin que le duele na'a",201,3,-1,-1,"Ensaladillas",0,4,"aa",-1,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-04",11,"Aquel doble de campana\nno fué por el que murió\nsino porque sepa yo\nque m'he de morir mañana.",201,3,-1,-1,"Ensaladillas",11,4,"aa",4,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-05",11,"El gallo en su gallinero\nlibre se sacude y canta;\nel que duerme en casa ajena\npasitico se levanta.",201,3,-1,-1,"Ensaladillas",0,4,"aa",148,0,-1,0,111,111,"","",72,"isaacs_colombia","","",5,0,0,[],""],["andina_t1-p0111-06",11,"Tres aguas habré bebido\ncuatro con la barbaria,\ny no hay agua más amarga\nque vivir en casa ajena.",201,3,-1,-1,"Ensaladillas",5,4,"ea",-1,0,-1,0,111,111,"","",72,"","","",2,0,0,[],""],["andina_t1-p0111-07",11,"Recibe lo que te den\ny agradécelo constante;\nque el que no tiene que dar\nuna flor es un diamante.",201,3,-1,-1,"Ensaladillas",0,4,"ae",47,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-08",11,"Tras el tiempo viene el tiempo,\nsobre el tiempo, témpora;\nasí como cambia el tiempo\nse cambia la voluntad.",201,3,-1,-1,"Ensaladillas",5,4,"a",-1,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-09",11,"A yo me tiene ofendido\ncon esta maldita mafia\namigo a comer panela\nsin haber sembrado caña.",201,3,-1,-1,"Ensaladillas",0,4,"aa",-1,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-10",11,"El que fuera enamorado\naprenda a tocar vihuela\nque aunque no tange trapiche\nno le faltará panela.",201,3,-1,-1,"Ensaladillas",0,4,"ea",167,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-11",11,"Venimos de Santander\ny somos santandereanos;\nsi nos vienen a pegar\nnosotros también pegamos.",201,3,-1,-1,"Ensaladillas",0,4,"ao",-1,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-12",11,"Adiós, te dije mi vida,\npor si acaso no volviere\nque el hombre sabe'onde nace\npero no sabe 'onde muere.",201,3,-1,-1,"Ensaladillas",0,4,"ee",115,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-13",11,"Es malo buscar padrinos\nantes de nacer el niño,\nporque después viene a ser\ncompadre, padre y padrina",201,3,-1,-1,"Ensaladillas",5,4,"ia",-1,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-14",11,"De negro viste el amor,\nde celeste viste el cielo,\nno hay cielo sin el azul\nni amor que no traiga celo.",201,3,-1,-1,"Ensaladillas",0,4,"eo",10,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-16",11,"Dicen que el ají chivato\npica mas que la pimienta;\nmás pica una mala lengua\nque sin preguntarle cuenta.",201,3,-1,-1,"Ensaladillas",0,4,"ea",-1,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-17",11,"No importa la cuna humilde\nque dejemos el nacer\nno es caballero el que nace\nsino el que lo sabe ser",201,3,-1,-1,"Ensaladillas",0,4,"e",20,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0111-18",11,"Ay! qué triste situación\nla que estamos atravesando,\nse ha perdido la moneda\nsin saber cómo ni cuándo.",201,3,-1,-1,"Ensaladillas",0,4,"ao",33,0,-1,0,111,111,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-01",11,"Soy pobre porque no tengo\nplata como el poderoso\npero como soy dichoso\ncon la dicha me mantengo",201,3,-1,-1,"Ensaladillas",11,4,"eo",124,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-02",11,"Si por pobre me desprecies.\nbusca un rico que te dé;\nel pobre da lo que tiene.\nel rico da con tos pies.",201,3,-1,-1,"Ensaladillas",0,4,"e",-1,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-03",11,"Si la justicia me encuentra\njugando con los ladrones.\nle digo el señor alcalde\nque quien no roba no come.",201,3,-1,-1,"Ensaladillas",0,4,"oe",-1,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-04",11,"Mientras mas trabajo tengo.\nvivo con mas alegría.\nporque los mismos trabajos\nme sirven de compañía.",201,3,-1,-1,"Ensaladillas",0,4,"ia",0,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-05",11,"Búscale la cama al monte\nhombre: el monte no tiene cama;\nla cama que tiene el monte\nes darle soco con gana.",201,3,-1,-1,"Ensaladillas",0,4,"aa",-1,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-06",11,"Un gallo con tantas plumas\nsí se puede sostener,\nescarbando con sus uñas\nmantiene hijos y mujer",201,3,-1,-1,"Ensaladillas",0,4,"e",20,0,-1,0,112,112,"","",72,"","","",2,0,0,[],""],["andina_t1-p0112-07",11,"Un gallo con tantas plumas\nno se puede sostener,\ny un escribano con una\nmantiene hijos y mujer.",201,3,-1,-1,"Ensaladillas",0,4,"e",20,0,-1,0,112,112,"","",72,"","","",2,0,0,[],""],["andina_t1-p0112-08",11,"Levántense mis hijos.\nvamos a trabajar;\ntrabajo no busca a nadie\nsi no lo van a buscar.",201,3,-1,-1,"Ensaladillas",0,4,"a",21,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-09",11,"Con mi caballo y mi rejo\nme siento mas lisonjero\nque el cura y el sacristán,\nel dotor y el estanquero.",201,3,-1,-1,"Ensaladillas",0,4,"eo",38,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-12",11,"Buenos consejos me dieron\ncuando yo estaba chiquito\nse picaro y mujeriego\nque para eso eres bonito.",201,3,-1,-1,"Ensaladillas",0,4,"io",119,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-13",11,"Que si no me quiere naide\npos me quiero y ti torito\nno saben lo que se pierden\nlas hijas de don Benito.",201,3,-1,-1,"Ensaladillas",0,4,"io",119,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-14",11,"Por costumbre no soy pobre\npor herencia no soy rico,\neso me deja bailar\nal golpe de mucurito.",201,3,-1,-1,"Ensaladillas",0,4,"io",-1,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-15",11,"Yo no le temo a las leyes\npero si a los requisitos\nno le temo a las muchachas\npero sí a los muchachitos.",201,3,-1,-1,"Ensaladillas",0,4,"io",254,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-16",11,"El que nace barrigón\nmas que lo fagan chiquito\ny el que va para él infierno\nmas que nazca muy bendito.",201,3,-1,-1,"Ensaladillas",0,4,"io",119,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-17",11,"Donde el bobo muere de hambre\nel vivo siempre está ajito\nal uno bebe mera agua\ncuando el otro come frito.",201,3,-1,-1,"Ensaladillas",0,4,"io",119,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0112-18",11,"Yo a Dios no le pido mal\npara ningún enemigo\nmás bien que le dé mas plata\npa que viva perseguido.",201,3,-1,-1,"Ensaladillas",0,4,"io",-1,0,-1,0,112,112,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-01",11,"El que come como un grande\ny trabaja como un chiquito\nhace como al paje grande\nque se come el pequeñito.",201,3,-1,-1,"Ensaladillas",1,4,"io",119,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-02",11,"Dicen que vale por dos\nel hombre que es prevenío\npues siempre se ríe del hambre\nen después de haber comió.",201,3,-1,-1,"Ensaladillas",5,4,"o",-1,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-03",11,"¿quién desprecia oro por cobre,\nni agua dulce por salobre?\n¿Quién desprecia uno de su tierra\npor un forastero pobre?",201,3,-1,-1,"Ensaladillas",0,4,"oe",410,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-04",11,"La política se ha puesto\nque es una calamidá,\nque el que quiere un puestecito\nse tiene que arrodillá.",201,3,-1,-1,"Ensaladillas",0,4,"a",9,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-05",11,"Gallinazo no seas bobo\nrecibe lo que te dan;\nque mas vale ser obispo\nque cura o sacristán.",201,3,-1,-1,"Ensaladillas",0,4,"a",147,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-06",11,"Siempre andan aconsejando\nque me aguante la pobreza\n-el que no carga la carga\nle parece que no pesa.",201,3,-1,-1,"Ensaladillas",0,4,"ea",201,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-07",11,"Estoy tan hacho al dolor\ny el dolor tan hecho e mí,\nque ni yo siento él dolor\nni el dolor se hace sentir.",201,3,-1,-1,"Ensaladillas",0,4,"i",-1,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-09",11,"El mundo es un campamento\nla vida es una batalla\nen que la lleva perdida\nal hombre que sufre y calla",201,3,-1,-1,"Ensaladillas",0,4,"aa",249,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-11",11,"Mazamorra por la mañana\nmazamorras medio día,\nmazamorra por la tardecita\ncomo si fuera comida.",201,3,-1,-1,"Ensaladillas",3,4,"ia",-1,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-12",11,"Gracias a Dios que yo tengo\ndos camisas de mudar:\nuna que se me acabó\ny otra que voy a comprar.",201,3,-1,-1,"Ensaladillas",0,4,"a",21,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-13",11,"Yo soy el toro sinuano\nde cachos sin afilé;\nque al que se meta en el medio\nlo parto por la mita.",201,3,-1,-1,"Ensaladillas",5,4,"ia",-1,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-14",11,"La mujer para bonita\ntres cosas ha de tener:\nbuena cara, buena pierna\nbuena cadera también.",201,3,-1,-1,"Ensaladillas",0,4,"e",-1,0,-1,0,113,113,"","",72,"","","",2,0,0,[],""],["andina_t1-p0113-16",11,"Comunícame tus malas\nsi dolencias te lastimen\nque males comunicados\nsi no se curan se alivian.",201,3,-1,-1,"Ensaladillas",5,4,"ia",-1,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-17",11,"Triste de verte triste,\nyo consolarte no puedo,\nporque uno que esté mas triste\n¿cómo puede dar consuelo?",201,3,-1,-1,"Ensaladillas",0,4,"eo",-1,0,-1,0,113,113,"","",72,"","","",1,0,0,[],""],["andina_t1-p0113-18",11,"Con el que se va, me voy,\ncon el que se queda, me quedo;\nla gatuna pica el maíz\npero se lo traga entero.",201,3,-1,-1,"Ensaladillas",0,4,"eo",-1,0,-1,0,113,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-01",11,"Servir para merecer\nnadie lo consiguió,\nsiempre viene mereciendo\naquel que menos sirvió.",201,3,-1,-1,"Ensaladillas",0,4,"o",2,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-02",11,"Me tiro la manta al hombro,\nme riego como el bujío;\nque no hay frió sin calentura\nni calentura sin frío.",201,3,-1,-1,"Ensaladillas",0,4,"io",3,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-03",11,"Este cantar y bailar\ntiene al diablo en la babaza;\nal que no lleva la carga\nle parece que no pesa.",201,3,-1,-1,"Ensaladillas",5,4,"ea",-1,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-04",11,"Que importa que buena cama\ncortinas y pabellones,\nsino me dejan dormir\nvarias imaginaciones.",201,3,-1,-1,"Ensaladillas",0,4,"oe",34,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-05",11,"Bien hace al hombre en llorar\ndesde que vino a la tierra,\nque si viera donde nace\nnunca los ojos abriera.",201,3,-1,-1,"Ensaladillas",0,4,"ea",-1,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-06",11,"Mi madre es una cometa\nmi padre un rayó feroz,\nhijo de cometa y rayo\ndigan quien puedo ser yo.",201,3,-1,-1,"Ensaladillas",0,4,"o",-1,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-07",11,"Si se quema la sabana\ndéjela que'eche humo,\nninguno es mejor que yo\nni yo mejor que ninguno.",201,3,-1,-1,"Ensaladillas",0,4,"uo",-1,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-08",11,"Adonde dices que bailo\njamas he pinta o mi planta,\nyo bailo con todas juntas;\ncon la negra y con la blanca.",201,3,-1,-1,"Ensaladillas",0,4,"aa",-1,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-10",11,"Moreno pintan a Cristo\nmorena a la Magdalena\nmoreno es el bien que adoro\nviva la gente morena.",201,3,-1,-1,"Ensaladillas",0,4,"ea",59,0,-1,0,114,114,"","",72,"palau_cantares, frenk_t1, machado_venezuela, lafuente_madrid, fernan_caballero","","",7,0,0,[],""],["andina_t1-p0114-11",11,"Si vez a un blanco comiendo\ncon un negro en compañía\nel blanco le debe al negro\no es del negro la comida.",201,3,-1,-1,"Ensaladillas",0,4,"ia",-1,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-12",11,"El negro junto al blanco\nningún papel representa,\nque'l negro no se de cuenta\nque parece un mico manco",201,3,-1,-1,"Ensaladillas",11,4,"ao",303,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-13",11,"Qué me ves y qué me miras,\n¿no sabes que soy letrero?\nnarices de olleta vieja\ncara de tiesto arepero.",201,3,-1,-1,"Ensaladillas",0,4,"eo",38,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-14",11,"Que me miras, que me vés,\nqué me quedas reparando;\nen tus manos me tuviste,\nnadie me anduvo quitando.",201,3,-1,-1,"Ensaladillas",0,4,"ao",33,0,-1,0,114,114,"","",72,"","","",2,0,0,[],""],["andina_t1-p0114-15",11,"Me aconsejan que te deje,\nyo no la quiero dejar,\ncomo no saben de amor\nse ponen a aconsejar.",201,3,-1,-1,"Ensaladillas",0,4,"a",21,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-16",11,"A San Antonio Bendito\nlo tentó en balde el demonio\nsi lo tienta mi morena\nse condena San Antonio.",201,3,-1,-1,"Ensaladillas",0,4,"oo",169,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-17",11,"Yo vengo de Chinavita\nde cumplir una promesa;\ny agora que vengo santo\ndami un besito, teresa.",201,3,-1,-1,"Ensaladillas",0,4,"ea",201,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0114-18",11,"En el otro \"loo\" del rio\nsuspiraba una hormiguita\ny en el suspiro decía\nSanta Barbara bendita.",201,3,-1,-1,"Ensaladillas",0,4,"ia",-1,0,-1,0,114,114,"","",72,"","","",1,0,0,[],""],["andina_t1-p0115-01",11,"Bendita la Virgen del Carmen\nde todos tan adorada;\nlíbrame de estos trabajos\ny déme una buena jugada.",201,3,-1,-1,"Ensaladillas",0,4,"aa",49,0,-1,0,115,115,"","",72,"","","",1,0,0,[],""],["andina_t1-p0115-02",11,"Por ser la primera vez,\nque en esta montaña canto\nGloria al Padre, Gloria al Hijo,\nGloria al Espíritu Santo.",201,3,-1,-1,"Ensaladillas",0,4,"ao",30,0,-1,0,115,115,"","",72,"","","",8,0,0,[],""],["andina_t1-p0115-03",11,"El pajaro diostedé\ntiene el nombre de Jesús,\ncuando va a tomar el agua,\ncon el pico hace la cruz.",201,3,-1,-1,"Ensaladillas",0,4,"u",109,0,-1,0,115,115,"","",72,"","","",2,0,0,[],""],["andina_t1-p0115-04",11,"Dos cuartillos de limosna\na San Antonio Divino\nque nos alargue las zancas\no nos acorta el camino.",201,3,-1,-1,"Ensaladillas",0,4,"io",199,0,-1,0,115,115,"","",72,"","","",1,0,0,[],""],["andina_t1-p0115-05",11,"Borrachos y amanecidos\npor ahí van unos muchachos\npero nada les suceda\npues Dios cuida sus borrachos",201,3,-1,-1,"Ensaladillas",0,4,"ao",463,0,-1,0,115,115,"","",72,"","","",1,0,0,[],""],["andina_t1-p0115-06",11,"A nosotros los del campo\nno nos cantan el entierro:\ny nos ponen cruz de palo\nque nu alcanza pa de hierro. -",201,3,-1,-1,"Ensaladillas",0,4,"eo",379,0,-1,0,115,115,"","",72,"","","",1,0,0,[],""],["andina_t1-p0115-09",11,"Mi marido está en la cama\nyo estoy en la cabecera,\ncon un rosario en la mano\nrogando a Dios que se muera",201,3,-1,-1,"Ensaladillas",0,4,"ea",44,0,-1,0,115,115,"","",72,"","","",2,0,0,[],""],["andina_t1-p0115-10",11,"Muerto yo te quiero ver\nen el fondo de la iglesia;\nvaya el hombre a los infiernos\nla mujer no se desprecia.",201,3,-1,-1,"Ensaladillas",0,4,"ea",673,0,-1,0,115,115,"","",72,"","","",1,0,0,[],""],["andina_t1-p0115-12",11,"Cuando Cristo dijo misa,\nrepicaron las campanas,\nlas repicó San José\na las cinco de la mañana",201,3,-1,-1,"Ensaladillas",0,4,"aa",-1,0,-1,0,115,115,"","",72,"","","",1,0,0,[],""],["andina_t1-p0115-14",11,"Es una vaina la vida\npero así lo quiere Dios;\npior vaina sería morir\nsin sufir tan güen dolor.",201,3,-1,-1,"Ensaladillas",0,4,"o",-1,0,-1,0,115,115,"","",72,"","","",1,0,0,[],""],["andina_t1-p0115-15",11,"Si vas a la romería\ny encuentra e mi señor\ndecíto que su María\nse esté muriendo de amor",201,3,-1,-1,"Ensaladillas",1,4,"o",72,0,-1,0,115,115,"","",72,"","","",1,0,0,[],""],["andina_t1-p0115-16",11,"El que diga que las flores\nno tienen alma ni voz,\nes un bruto que no sabe\nque en el jardín habla Dios.",201,3,-1,-1,"Ensaladillas",0,4,"o",87,0,-1,0,115,115,"","",72,"","","",1,0,0,[],""],["andina_t1-p0115-17",11,"Estando los santos juntos,\nse presentó San Silvestre;\nSan Agustín que lo ve...\ncarajo!... ¿qué santo es éste?",201,3,-1,-1,"Ensaladillas",0,4,"ee",-1,0,-1,0,115,115,"","",72,"","","",1,0,0,[],""],["andina_t1-p0115-18",11,"Cuando el diablo está algo triste\nse va para Turmequé;\nlas niñas le sirven chicha\ny le dicen sumercé.",201,3,-1,-1,"Ensaladillas",0,4,"e",77,0,-1,0,115,115,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-01",11,"Con ella dormí en la arena\ncomo en un colchón de lana;\nquien tuvo la culpa deso?\nEl aguardiente de caña.",201,3,-1,-1,"Ensaladillas",0,4,"aa",-1,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-02",11,"Yo vine porque yegué\nnenguno me convido;\nles pido un poquito e chicha.\nme dicen que si acabó.",201,3,-1,-1,"Ensaladillas",5,4,"o",2,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-03",11,"Aborrezco el aguardiente\nludibrio de los muchachos\npesadilla de mujeres\nescuela normal de cacos.",201,3,-1,-1,"Ensaladillas",0,4,"ao",-1,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-04",11,"Mandan las antigües leyes\nbeber aguardiente puro;\nque beban agua los bueyes\nque tienen el cuero duro.",201,3,-1,-1,"Ensaladillas",1,4,"uo",248,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-05",11,"Ya se murió el aguardiente\ny lo llevan a enterrar.\ny en el testamento deja\nel guarapo en su lugar",201,3,-1,-1,"Ensaladillas",0,4,"a",21,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-07",11,"Si la caña 'taba biche\nquén te la mandó moler;\nel amor que 'tan impedio\nquén te lo mandó querer",201,3,-1,-1,"Ensaladillas",0,4,"e",20,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-08",11,"Dicen que van a coger\nlos que beben aguardiente;\nbebe el Papa, bebe el cura\ny también el Presidente.",201,3,-1,-1,"Ensaladillas",0,4,"ee",15,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-09",11,"Adiós Conchita,\nque ya nos vamos\nla chicha la bebemos\ny el guarapo lo botamos.",201,3,-1,-1,"Ensaladillas",3,4,"ao",116,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-10",11,"Mi vida: si nos casamos\nte voy hacer estos ruegos:\nno me lleves a vivir\ncon cuñada ni con suegros.",201,3,-1,-1,"Ensaladillas",0,4,"eo",-1,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-11",11,"Cuando se muera mi suegra.\nque l'entierren boc'abajo\ncon eso, si resucita\nque se baje mas'abajo",201,3,-1,-1,"Ensaladillas",0,4,"ao",168,0,-1,0,116,116,"","",72,"","","",7,0,0,[],""],["andina_t1-p0116-12",11,"Salga, niño, no desprecié\nq'es su suegra que lo llama;\nno tendrá tan güen esposa\nsi no juere por su mama.",201,3,-1,-1,"Ensaladillas",0,4,"aa",90,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-13",11,"La primera - la hizo Dios\ny esa engañó al padre Adán\n¿si así fue la que Dios hizo\ncómo serán las demás?",201,3,-1,-1,"Ensaladillas",0,4,"a",-1,0,-1,0,116,116,"","",72,"","","",4,0,0,[],""],["andina_t1-p0116-14",11,"Sutatausa es una loma\nGuateque es una planada\nsi los hombres no pedimos\nlas mujeres no dan nada.",201,3,-1,-1,"Ensaladillas",0,4,"aa",49,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-15",11,"A mi chatica la quero\nporque ella también me quere\ny porque e solas me dice:\ncuando se puede se puede",201,3,-1,-1,"Ensaladillas",0,4,"ee",-1,0,-1,0,116,116,"","",72,"","","",2,0,0,[],""],["andina_t1-p0116-16",11,"Yo le dije: vamos, vamos.\ny ella dijo: vamos pues;\nyo no la llevé cargada.\nella se jué por sus pies.",201,3,-1,-1,"Ensaladillas",0,4,"e",218,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-17",11,"Yo tenía mi guariconga\ny el cura se la llevó\nel cura manda en su misa\ny en mi guariconga yo.",201,3,-1,-1,"Ensaladillas",0,4,"o",2,0,-1,0,116,116,"","",72,"","","",1,0,0,[],""],["andina_t1-p0116-18",11,"Delgadita de cintura\ncomo junco de laguna\nque por verte caminar\nse para él sol y la luna.",201,3,-1,-1,"Ensaladillas",0,4,"ua",56,0,-1,0,116,116,"","",72,"","","",6,0,0,[],""],["andina_t1-p0117-02",11,"Cuando dos quieren a una\nla quieren como hermanitos:\nal uno carga la jaula\ny el otro los pajaritos.",201,3,-1,-1,"Ensaladillas",0,4,"io",254,0,-1,0,117,117,"","",72,"","","",8,0,0,[],""],["andina_t1-p0117-03",11,"La mujer que quiere a dos\nse nota que es advertida:\nsi una vela se le apaga\nOtra le queda encendida.",201,3,-1,-1,"Ensaladillas",0,4,"ia",37,0,-1,0,117,117,"","",72,"","","",12,0,0,[],""],["andina_t1-p0117-04",11,"A las mujeres quererlas\nquererlas y siempre amarlas,\ncomerlas si tienen qué\ny al poco tiempo dejarlas.",201,3,-1,-1,"Ensaladillas",0,4,"aa",451,0,-1,0,117,117,"","",72,"","","",7,0,0,[],""],["andina_t1-p0117-05",11,"Arriba caimán goloso\nque una mujer va nadando:\ncogerle.. .la cogerás\npero comértela... cuando I...",201,3,-1,-1,"Ensaladillas",5,4,"i",-1,0,-1,0,117,117,"","",72,"","","",1,0,0,[],""],["andina_t1-p0117-06",11,"Mi chata es la más hermosa,\ntodo el mundo la codicia,\nhasta el cura quiere parte\ncomo si fuera primicia",201,3,-1,-1,"Ensaladillas",0,4,"ia",391,0,-1,0,117,117,"","",72,"","","",1,0,0,[],""],["andina_t1-p0117-07",11,"Cuando dos se quieren bien\ny se encuentran en la plaza,\nel hombre se disimula,\nla mujer se agacha y pasa.",201,3,-1,-1,"Ensaladillas",0,4,"aa",123,0,-1,0,117,117,"","",72,"","","",8,0,0,[],""],["andina_t1-p0117-08",11,"Tantas veces t'he pedido\nlo que no me quieres dar\nque si lo aflojas por fin\nno lo sabrá aprovechar...",201,3,-1,-1,"Ensaladillas",0,4,"a",21,0,-1,0,117,117,"","",72,"","","",1,0,0,[],""],["andina_t1-p0117-09",11,"Si en el sexto no hay perdón\nni en el séptimo rebaje,\nbien pueda nuestro Señor\nllenar su cielo de paja.",201,3,-1,-1,"Ensaladillas",5,4,"aa",-1,0,-1,0,117,117,"","",72,"","","",1,0,0,[],""],["andina_t1-p0117-10",11,"Dame un besito mi vida\ndéme uno, dame dos;\nque los besitos a pares\nno los castiga mi Dios.",201,3,-1,-1,"Ensaladillas",0,4,"o",87,0,-1,0,117,117,"","",72,"","","",3,0,0,[],""],["andina_t1-p0117-11",11,"Cantando el gallo blanco\nya canta el quiquiriquí\nya va llegando la hora\nde aquello que te pedí.",201,3,-1,-1,"Ensaladillas",0,4,"i",23,0,-1,0,117,117,"","",72,"","","",1,0,0,[],""],["andina_t1-p0117-12",11,"El jardinero di amor\nsiembra su planta y se va\notro vien' y le cultiva\n¿de cuál de los dos será?",201,3,-1,-1,"Ensaladillas",0,4,"a",9,0,-1,0,117,117,"","",72,"","","",1,0,0,[],""],["andina_t1-p0117-13",11,"No hay comu el marido di uno\npa' cuando llegan las penas:\nrepartidas entre dos\nhasta las penas son güenas",201,3,-1,-1,"Ensaladillas",0,4,"ea",62,0,-1,0,117,117,"","",72,"","","",1,0,0,[],""],["andina_t1-p0117-14",11,"Tus ojos son dos luceros;\ntu nariz, pluma cortada\ntus dientes, letra menuda;\ntu boca, carta cerrada:",201,3,-1,-1,"Ensaladillas",0,4,"aa",49,0,-1,0,117,117,"","",72,"","","",5,0,0,[],""],["andina_t1-p0117-16",11,"Yo tengo di hacer un puente\nde calicanto y arena\npara que pase la Rosa.\nsi deja de ser ajena.",201,3,-1,-1,"Ensaladillas",0,4,"ea",59,0,-1,0,117,117,"","",72,"","","",2,0,0,[],""],["andina_t1-p0117-17",11,"Piensan los enamorados\ny piensan como vusté \": '\npiensan que naide los mira\ny todu el mundo los ve.",201,3,-1,-1,"Ensaladillas",5,4,"e",-1,0,-1,0,117,117,"","",72,"","","",6,0,0,[],""],["andina_t1-p0118-02",11,"Bonito ques ir a jiestas\nal pueblo dondi hay bonitas,\ny más si son casaderas,\nmanilargas y chiquitas.",201,3,-1,-1,"Ensaladillas",0,4,"ia",258,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-03",11,"Lucero del alto cielo\npréstame tu claridá\npara seguirle los pasos\na mi amada que se va.",201,3,-1,-1,"Ensaladillas",0,4,"a",9,0,-1,0,118,118,"","",72,"","","",2,0,0,[],""],["andina_t1-p0118-04",11,"A mi chatica la quero,\nporque me da chocolata;\ncon las rodillas lo muele\ncon las caderas lo bate.",201,3,-1,-1,"Ensaladillas",5,4,"ae",-1,0,-1,0,118,118,"","",72,"","","",2,0,0,[],""],["andina_t1-p0118-05",11,"Ayer te mandé un pañuelo\nbordeo con hilo di oro\nque en la punta va diciando\nque te quero, que ti adoro.",201,3,-1,-1,"Ensaladillas",0,4,"oo",85,0,-1,0,118,118,"","",72,"","","",2,0,0,[],""],["andina_t1-p0118-06",11,"Chinita cari bonita\nchinita de mis antojos,\n¿ni siquiera te conmueven\nlas lagrimas de mis ojos?",201,3,-1,-1,"Ensaladillas",0,4,"oo",99,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-07",11,"Indiecita retrechera\nque siempre me desprecias;\nah malaya que algún día\nme has de venir a rogar.",201,3,-1,-1,"Ensaladillas",5,4,"a",-1,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-08",11,"Juyero, muñeco e trapo\npo lo bonito que sos;\nque por ahí andas diciendo\nque yo me muero por vos.",201,3,-1,-1,"Ensaladillas",0,4,"o",87,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-09",11,"Mi mamita dice ahora\nque de casarme es mañana,\npero es pa que no se maten\nlos diez que me tienen gana.",201,3,-1,-1,"Ensaladillas",0,4,"aa",4,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-10",11,"Quén juera alpargate jino\npara calzar en tú pié\nY pa mirar de p'arriba\nlo que el alpargate ve...",201,3,-1,-1,"Ensaladillas",0,4,"e",77,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-11",11,"Cógeme este trompo en fuña\na ver si tataratee,\nque la mujer qu'es bonita\ncualquier hombre la desea.",201,3,-1,-1,"Ensaladillas",5,4,"ea",-1,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-12",11,"Quisiera que jueras rosa\npara yo ser colibrí\ny besarte esa jetica\nque loco me tiene a mí.",201,3,-1,-1,"Ensaladillas",0,4,"i",23,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-13",11,"Pajarillo pico di oro\nque picas en la manzana;\n¿cómo queros que yo pique\nsi no me agachas la rama.",201,3,-1,-1,"Ensaladillas",0,4,"aa",-1,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-14",11,"Me enamoré de una chica\nde esas que visten de rasó;\ny ella me respondió\nno gastes pólvora en gallinazo",201,3,-1,-1,"Ensaladillas",3,4,"ao",-1,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-15",11,"Yo me enamoré de un aire;\ndel aire de una mujer;\ncomo la mujer es de aire\nen el aire me quedé.",201,3,-1,-1,"Ensaladillas",0,4,"e",-1,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-16",11,"Ayer me dijiste que hoy,\nhoy me dices que mañana;\nasí me pasas engañando\nhasta que te dé la gana.",201,3,-1,-1,"Ensaladillas",0,4,"aa",4,0,-1,0,118,118,"","",72,"","","",10,0,0,[],""],["andina_t1-p0118-17",11,"Y te fuiste y me dejaste\npara ver si me moría;\nembustera, te engañaste,\nno me he muerto todavía.",201,3,-1,-1,"Ensaladillas",1,4,"ia",0,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0118-18",11,"No me digas lirio rojo,\nni clavelito encantado;\nque los hombres de este tiempo\nson flojos y enamorados.",201,3,-1,-1,"Ensaladillas",0,4,"ao",-1,0,-1,0,118,118,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-01",11,"Nada soy nada valgo\ny de nada me mantengo;\nmi suerte vive en el aire\ny en el aire me sostengo.",201,3,-1,-1,"Ensaladillas",0,4,"eo",124,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-02",11,"No te quero por bonita\nni'an siquiera por antojo,\nsino por la vaca gorda\nque tenes en el rastrojo.",201,3,-1,-1,"Ensaladillas",0,4,"oo",400,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-03",11,"Una estrella se ha perdido\ny en el cielo no 'parece\nen tu pecho se ha metido\ny en tu casa resplandece.",201,3,-1,-1,"Ensaladillas",1,4,"ee",64,0,-1,0,119,119,"","",72,"","","",6,0,0,[],""],["andina_t1-p0119-04",11,"Por esta calle me voy\npor la otra doy la vuelta;\nla mujer que me quisiere\nténgame la puerta abierta.",201,3,-1,-1,"Ensaladillas",0,4,"ea",-1,0,-1,0,119,119,"","",72,"","","",8,0,0,[],""],["andina_t1-p0119-05",11,"El amor vidita mia,\nes afán de no morir;\nafán de hacerse una vida\ny en esa vida vivir.",201,3,-1,-1,"Ensaladillas",0,4,"i",157,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-06",11,"Cuando bailas torbellino,\nme hace señas tu cadera\ny mientras más señas me hace\nmás me da la tembladera.",201,3,-1,-1,"Ensaladillas",0,4,"ea",44,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-07",11,"La tembladera que tengo\nvos me la podías quitar,\nsi me dieras una cosa\nque también te quero dar.",201,3,-1,-1,"Ensaladillas",0,4,"a",21,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-08",11,"Toda la noche moliendo\ny amanecimos sin miel;\nel trapiche sinvergüenza\ny la molinera también.",201,3,-1,-1,"Ensaladillas",0,4,"e",-1,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-09",11,"De amores m'estoy muriendo\ny el remedio es olvidar:\nM'he de morir del remedio\nmás vale morir del mal.",201,3,-1,-1,"Ensaladillas",0,4,"a",-1,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-10",11,"Cuando yo arriaba mis mulas\neran mis negociaciones\nalzar naguas de pa'rriba\ny de pa'bajo calzones...",201,3,-1,-1,"Ensaladillas",0,4,"oe",34,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-11",11,"Para Pasto, la ñapanga,\npara esposa, la mejor\npor cristiana y muy valiente\nnos arranca el corazón.",201,3,-1,-1,"Ensaladillas",0,4,"o",-1,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-12",11,"Este dicho es mi evangelio:\n\"El fraile, mula y mujer\nsi hasta ahora no te la han hecho\nmañana te la han de hacer\".",201,3,-1,-1,"Ensaladillas",0,4,"e",20,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-13",11,"Yo no me caso con viuda\nmas que se vista de seda\nque a las mulas y a las viudas\nalgún resabio les queda.",201,3,-1,-1,"Ensaladillas",0,4,"ea",266,0,-1,0,119,119,"","",72,"","","",2,0,0,[],""],["andina_t1-p0119-14",11,"Amigo, por ser amigo\nun buen consejo le doy:\nno busque mujer chiquita\nporque huele a morrocoy",201,3,-1,-1,"Ensaladillas",0,4,"o",112,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-15",11,"Adiós casita cuadrada,\ncuadrada de cuatro esquinas\nadiós chinita del alma,\nmanojo de clavellinas",201,3,-1,-1,"Ensaladillas",0,4,"ia",243,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-16",11,"A ningún amante viejo\nle des posada en tu casa\nporque es fácil de prender\nel carbón que ha sido brasa",201,3,-1,-1,"Ensaladillas",0,4,"aa",123,0,-1,0,119,119,"","",72,"machado_venezuela","","",3,0,0,[],""],["andina_t1-p0119-17",11,"La muchacha que a los treinta\nse quedó comprometía\nseguro que San Antonio\nle jugó su picardía.",201,3,-1,-1,"Ensaladillas",0,4,"ia",0,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0119-18",11,"Por mujer no se pelea,\nsi quiere coja la mía\nque yo me salgo a la calle.\ny tengo otra parecía.",201,3,-1,-1,"Ensaladillas",0,4,"ia",0,0,-1,0,119,119,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-01",11,"No hay soga que no reviente\nni hombre que no sea incumplido.\nni mujer que no le juegue\ntraiciones a su marido.",201,3,-1,-1,"Ensaladillas",0,4,"io",101,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-02",11,"Muchacha quiéreme a mi\ny abandone a su marido\nque no es la primera paloma\nque deja sólo su nido",201,3,-1,-1,"Ensaladillas",0,4,"io",101,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-03",11,"Las mujeres no me quieren\nyo les hallo la razón -\nporque no tengo caballo\nni rejo ni bayetón.",201,3,-1,-1,"Ensaladillas",0,4,"o",31,0,-1,0,120,120,"","",72,"","","",7,0,0,[],""],["andina_t1-p0120-04",11,"Cuando yo llego a mi rancho\nme voy corriendo al fogón\ndonde me tiene mi negra\nplátano con chicharrón.",201,3,-1,-1,"Ensaladillas",0,4,"o",31,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-05",11,"Al enamorado bobo\nlo ponen de centinela,\ncon la boca llena de baba\nsin tener dolor de muela,",201,3,-1,-1,"Ensaladillas",0,4,"ea",167,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-06",11,"El cura de Babilonia\nno me quiere confesar,\nporque me encontró poniendo\ncada cosa en su lugar.",201,3,-1,-1,"Ensaladillas",0,4,"a",21,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-08",11,"La mujer que vive sola\nvive llena de congoja\nno tiene potito e leña\nni tiene quien se lo coja",201,3,-1,-1,"Ensaladillas",0,4,"oa",146,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-09",11,"La mujer cuando resbala\naunque no caiga se pierde;\npues no ha de faltar alguno\nque del resbalón se acuerde.",201,3,-1,-1,"Ensaladillas",0,4,"ee",154,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-10",11,"Échale llave a la puerta\ny aldabas al corazón\nque estando la puerta abierta\nno tiene culpa el ladrón.",201,3,-1,-1,"Ensaladillas",1,4,"o",31,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-11",11,"La mujer es como el niño\nque se enoja y bota el pan;\nsi la tratan con cariño\nvuelve y coge, si le dan",201,3,-1,-1,"Ensaladillas",1,4,"a",147,0,-1,0,120,120,"","",72,"","","",2,0,0,[],""],["andina_t1-p0120-12",11,"Señores yo estoy de luto\nni a la ventana me asomó.\ngócela quien la merece.\nyo con verla me conformo",201,3,-1,-1,"Ensaladillas",5,4,"oo",-1,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-13",11,"El tabaco que se apaga\nno lo vuelvas a encender;\nla mujer que ya no quieras\nno la vuelvas a querer.",201,3,-1,-1,"Ensaladillas",0,4,"e",20,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-14",11,"El diablo a mi me libre\ndel demonio de la suegra\nprefiero llorar a solas\nun amor que se me fuera.",201,3,-1,-1,"Ensaladillas",0,4,"ea",-1,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-15",11,"Si la familia no quiere\nsiempre me caso con ella;\nsi ella me mienta mi madre\nyo te contesto: la de ella.",201,3,-1,-1,"Ensaladillas",0,4,"ea",-1,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-16",11,"República de Colombia\nNuevo Reino de Granada;\npara todos hay mujeres\nsólo para mí no hay nada:",201,3,-1,-1,"Ensaladillas",0,4,"aa",49,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-17",11,"Allá viene la luna triste\ncon su corazón herido.\na ninguna mujer le gusta\nque le quiten su marido.",201,3,-1,-1,"Ensaladillas",0,4,"io",101,0,-1,0,120,120,"","",72,"","","",1,0,0,[],""],["andina_t1-p0120-18",11,"Las campanas dicen dan,\nlas mujeres dicen den.\nyo prefiero las campanas\nporque dan sin que les den.",201,3,-1,-1,"Ensaladillas",0,4,"e",-1,0,-1,0,120,120,"","",72,"","","",2,0,0,[],""],["andina_t1-p0121-01",11,"Querer atajar el paso\nde dos que se quieren bien.\nes como echar leña al fuego\ny sentarse a verla arder.",201,3,-1,-1,"Ensaladillas",0,4,"e",-1,0,-1,0,121,121,"","",72,"","","",1,0,0,[],""],["andina_t1-p0121-02",11,"Lucero de la mañana\nde la mañanita triste,\nyo te quería preguntar\n—¿anoche con quien dormiste?",201,3,-1,-1,"Ensaladillas",0,4,"ie",153,0,-1,0,121,121,"","",72,"","","",22,0,0,[],""],["andina_t1-p0121-03",11,"El primer amor que tuve\nfué con una giganteña.\nque creyendo que era burro\nme quiso cargar de leña.",201,3,-1,-1,"Ensaladillas",0,4,"ea",291,0,-1,0,121,121,"","",72,"","","",6,0,0,[],""],["andina_t1-p0121-04",11,"La niña que a los quince años\nse deje morder el labio\nsi su mama no le pega\nse queda con el resabio.",201,3,-1,-1,"Ensaladillas",0,4,"ao",217,0,-1,0,121,121,"","",72,"","","",2,0,0,[],""],["andina_t1-p0121-06",11,"Por aquí me voy metiendo\ncomo raiz de cañabrava:\nla mujer es la que pierde\nel hombre no pierde nada.",201,3,-1,-1,"Ensaladillas",0,4,"aa",-1,0,-1,0,121,121,"","",72,"","","",1,0,0,[],""],["andina_t1-p0121-07",11,"Pretender mujer casada\nes predicar en desierto\nes mojar en fierro frío\no echarle ayudas a un muerto.",201,3,-1,-1,"Ensaladillas",0,4,"eo",88,0,-1,0,121,121,"","",72,"","","",1,0,0,[],""],["andina_t1-p0121-08",11,"Tres cosas hay en el mundo\nque no se pueden cuidar\nuna cocina sin puerta\nla mujer y un platanal.",201,3,-1,-1,"Ensaladillas",0,4,"a",-1,0,-1,0,121,121,"","",72,"","","",2,0,0,[],""],["andina_t1-p0121-10",11,"Solamente que dormida\nme picara el alacrán.\npues despierta no han podido.\nno han podido ni podrán.",201,3,-1,-1,"Ensaladillas",0,4,"a",147,0,-1,0,121,121,"","",72,"","","",1,0,0,[],""],["andina_t1-p0121-12",11,"Si cantas coplas de guerra.\nde noche o por la mañana,\nseguramente te pone\nel tiplecito de ruana.",201,3,-1,-1,"Ensaladillas",0,4,"aa",4,0,-1,0,121,121,"","",72,"","","",1,0,0,[],""],["andina_t1-p0121-13",11,"Los cantos contra el gobierno\ncántalos pa vos no mas;\nolvídalos cuando vayas\npuel lao de Chiquinquirá.",201,3,-1,-1,"Ensaladillas",0,4,"a",-1,0,-1,0,121,121,"","",72,"","","",1,0,0,[],""],["andina_t1-p0121-14",11,"Cuando venga don Ramón,\ndéle estrenina en la sopa\npa'que no siga comprando\nnuestras mujeres con ropa.",201,3,-1,-1,"Ensaladillas",0,4,"oa",608,0,-1,0,121,121,"","",72,"","","",1,0,0,[],""],["andina_t1-p0121-15",11,"Si a tu casa llega el amo\nmascando hojas de arrayan\npiensa que al gallo sin cresta\nse la puede el gavilán.",201,3,-1,-1,"Ensaladillas",0,4,"a",-1,0,-1,0,121,121,"","",72,"","","",1,0,0,[],""],["andina_t1-p0121-16",11,"Vos sos el gallo sin cresta;\nel amo es el gavilán;\nsalíte del gallinero\nmentras pase el huracán.",201,3,-1,-1,"Ensaladillas",0,4,"a",147,0,-1,0,121,121,"","",72,"","","",1,0,0,[],""],["andina_t1-p0121-17",11,"Cuando el pobre se enamora\ny el rico se le atraviesa.\nel rico también le cabe\nun buen palo en la cabeza.",201,3,-1,-1,"Ensaladillas",0,4,"ea",108,0,-1,0,121,121,"","",72,"","","",2,0,0,[],""],["andina_t1-p0121-18",11,"Cuando la Rosa se jué\na vivir onde el patrón\nse jué a cuidar una niña\ny con un niño golvió...",201,3,-1,-1,"Ensaladillas",0,4,"o",-1,0,-1,0,121,121,"","",72,"","","",1,0,0,[],""],["andina_t1-p0122-01",11,"Cascabel, cascabel!\nque andas puel cañaveral\npicóle al patrón las patas\nya que el pisó mi rosal.",201,3,-1,-1,"Ensaladillas",0,4,"a",1,0,-1,0,122,122,"","",72,"","","",1,0,0,[],""],["andina_t1-p0122-02",11,"Hay que darle otro veneno\nal pobre que se envenena\nel amor, con mas amor\nlo curó la Magdalena",201,3,-1,-1,"Ensaladillas",0,4,"ea",59,0,-1,0,122,122,"","",72,"","","",1,0,0,[],""],["andina_t1-p0122-05",11,"Si he de morir en Cucaita\nen Toca o Chiquinquirá\nno importa que viva en Suesca\nen Suta o en Saboyá",201,3,-1,-1,"Ensaladillas",0,4,"a",9,0,-1,0,122,122,"","",72,"","","",1,0,0,[],""],["andina_t1-p0122-07",11,"En Arauca estaba yo\ncuando reventó el cañón;\nmurió Páez, murió Bolívar\nmurió Cristóbal Colón.",201,3,-1,-1,"Ensaladillas",0,4,"o",31,0,-1,0,122,122,"","",72,"","","",1,0,0,[],""],["andina_t1-p0122-08",11,"El armadillo es un santo\ncomo el cura a Motavita\nque para hacer penitencia\nduerme con su armadillita.",201,3,-1,-1,"Ensaladillas",0,4,"ia",50,0,-1,0,122,122,"","",72,"","","",1,0,0,[],""]]);
